#!/usr/bin/env bash
# Libraries are linted on their own; following ~40 sourcing sites cost shellcheck 17+ GB here.
# shellcheck source=/dev/null
set -euo pipefail

if [ "${OMS_SMOKE_RUNNER_ACTIVE:-0}" != "1" ]; then
  exec "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/run-smoke-shard.sh" "$@"
fi

ROOT="${OMS_TEST_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
TMP="$(mktemp -d "${TMPDIR:-/tmp}/oms-tests.XXXXXX")"
# shellcheck source=tests/lib/smoke-env.sh
. "$ROOT/tests/lib/smoke-env.sh"
# Stop fixtures must never reach a live Codex app on the developer machine.
export OMS_CODEX_NOTIFY=0
# Worker-guard cases pin strictness per call. A caller that exports
# OMS_WORKER_GUARD_STRICT=1 for its own workers (autopilot acceptance does)
# must not turn the soft-surface cases strict.
unset OMS_WORKER_GUARD_STRICT OMS_WORKER_GUARD_OFF

source_oms_fingerprint() {
  if [ ! -d "$ROOT/.oms" ]; then
    printf 'absent\n'
    return
  fi
  python3 - "$ROOT/.oms" <<'PY'
import hashlib
import os
import sys

root = os.path.realpath(sys.argv[1])
entries = []
# `hooks/` and `work-journal/` are the subtrees the *live* agent session
# writes on its own schedule: the prompt/turn hooks append to
# hooks/events.jsonl and stamp hooks/sessions/*.json, and the Work Journal's
# turn boundaries roll over daily files and rewrite index.json/index.sqlite3
# whenever the agent running this suite takes a step. Including them makes the
# leak check fire on ambient session activity — a concurrent tool call or a
# prompt submitted three seconds into a shard is enough — which is a false
# alarm in exactly the environment the check exists to protect. Tests write
# through temporary repos and never through this path, so excluding them costs
# no coverage.
ambient = {"hooks", "work-journal"}
for base, dirs, files in os.walk(root, followlinks=False):
    if base == root:
        dirs[:] = [name for name in dirs if name not in ambient]
    symlink_dirs = [name for name in dirs if os.path.islink(os.path.join(base, name))]
    dirs[:] = sorted(name for name in dirs if name not in symlink_dirs)
    for name in sorted(files + symlink_dirs):
        path = os.path.join(base, name)
        rel = os.path.relpath(path, root).replace(os.sep, "/")
        if os.path.islink(path):
            entries.append((rel, "L:" + os.readlink(path)))
            continue
        digest = hashlib.sha256()
        try:
            with open(path, "rb") as handle:
                for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                    digest.update(chunk)
        except OSError as exc:
            entries.append((rel, "E:%s" % exc.__class__.__name__))
            continue
        entries.append((rel, "F:" + digest.hexdigest()[:16]))
for rel, mark in sorted(entries):
    print("%s  %s" % (mark, rel))
PY
}

SOURCE_OMS_FINGERPRINT="$(source_oms_fingerprint)"
TEST_HOME="$TMP/home"
TEST_CWD="$TMP/cwd"
mkdir -p "$TEST_HOME" "$TEST_CWD"

# Hermetic, environment-deterministic test runs: ignore the host's git config
# (CI has none, dev machines vary — this is exactly what hid the
# default-branch / no-identity bugs), pin a committer identity and a stable
# locale/timezone. Tests must not depend on ambient host state.
export LC_ALL=C LANG=C TZ=UTC
export HOME="$TEST_HOME" XDG_CONFIG_HOME="$TMP/config" XDG_CACHE_HOME="$TEST_HOME/.cache" NVM_DIR="$TEST_HOME/.nvm"
oms_smoke_use_fixture_root
# Harness residue (worktrees, lock dirs, delegate temp dirs) lives under
# TMPDIR, and doctor/cleanup count what they find there. With the host's
# shared /tmp, a stray oh-my-setting-* dir from a real run makes those tests
# fail for reasons that have nothing to do with the change under test.
export TMPDIR="$TMP/tmp"
mkdir -p "$TMPDIR"
export CODEX_HOME="$TEST_HOME/.codex"
export OH_MY_SETTING_CODEX_PLUGIN=0
cd "$TEST_CWD"

cleanup() {
  rm -rf "$TMP"
}
trap cleanup EXIT

assert_one_artifact_contains() {
  local dir="$1"
  local pattern="$2"
  local text="$3"
  local file

  file="$(find "$dir" -type f -name "$pattern" | sed -n '1p')"
  [ -n "$file" ] || fail "missing artifact matching: $pattern"
  assert_file_contains "$file" "$text"
}

# Provider prompt caches match a byte-exact prefix, so text OMS injects ahead of
# the task must not change with the clock, TZ, TMPDIR, cwd or directory order.
# Names the first differing line of the part before "## Brief" (the task).
assert_delegate_prefix_stable() {
  local first="$1" second="$2" label="$3" diff_out
  diff_out="$(diff <(awk '/^## Prompt$/{p=1;next} /^## Brief$/{exit} p' "$first") \
    <(awk '/^## Prompt$/{p=1;next} /^## Brief$/{exit} p' "$second") | sed -n '1,4p')"
  [ -z "$diff_out" ] || fail "$label: injected prefix differs between renders: $diff_out"
}

assert_symlink_to() {
  local path="$1"
  local target="$2"

  [ -L "$path" ] || fail "$path should be a symlink"
  [ "$(readlink "$path")" = "$target" ] ||
    fail "$path should link to $target, got $(readlink "$path")"
}

agent_plan_land_reviewed() {
  local repo="$1"
  local id="$2"
  local child_mode="${3:-}"
  local plan="$ROOT/scripts/agent-plan.sh"
  local patch lease verify executor soul patch_sha
  local -a land_args

  {
    IFS= read -r -d '' patch
    IFS= read -r -d '' lease
    IFS= read -r -d '' verify
    IFS= read -r -d '' executor
    IFS= read -r -d '' soul
    IFS= read -r -d '' patch_sha
  } < <(python3 - "$repo" "$id" <<'PY'
import hashlib, json, os, sys
repo, task_id = sys.argv[1:]
with open(os.path.join(repo, ".oms/plan/tasks.json"), encoding="utf-8") as handle:
    task = json.load(handle)["tasks"][task_id]
patch = task.get("patch", "")
if not isinstance(patch, str):
    raise SystemExit("non-string plan receipt")
path = patch if os.path.isabs(patch) else os.path.join(repo, patch)
with open(path, "rb") as handle:
    digest = hashlib.sha256(handle.read()).hexdigest()
values = [patch] + [task.get(key, "") for key in (
    "review_lease_id", "verify", "executor_id", "executor_soul_sha256")] + [digest]
for value in values:
    sys.stdout.write(str(value) + "\0")
PY
  )

  land_args=(--repo "$repo" land --id "$id" --lease-id "$lease" \
    --expected-review-patch "$patch" \
    --expected-review-patch-sha256 "$patch_sha" \
    --expected-review-verify "$verify" \
    --expected-review-executor-id "$executor" \
    --expected-review-executor-soul-sha256 "$soul" \
    --expected-review-lease-id "$lease")
  if [ "$child_mode" = child ]; then
    OMS_HARNESS_CHILD=1 "$plan" "${land_args[@]}"
  else
    "$plan" "${land_args[@]}"
  fi
}

agent_plan_finish_landed() {
  local repo="$1"
  local id="$2"
  local plan="$ROOT/scripts/agent-plan.sh"
  local receipt

  receipt="$("$plan" --repo "$repo" show --id "$id" | python3 -c '
import json,runpy,sys
print(runpy.run_path(sys.argv[1])["digest"](json.load(sys.stdin)))
' "$ROOT/scripts/lib/plan-receipt.py" | tr -d '\r')"
  "$plan" --repo "$repo" finish --id "$id" \
    --expected-landing-receipt-sha256 "$receipt"
}

test_poll_interval_adapts_to_elapsed_and_remaining() {
  . "$ROOT/scripts/lib/poll.sh"

  [ "$(oms_poll_interval_seconds 0 300)" = "1" ] ||
    fail "new waits should poll quickly"
  [ "$(oms_poll_interval_seconds 10 300)" = "2" ] ||
    fail "short waits should back off to 2s"
  [ "$(oms_poll_interval_seconds 60 300)" = "5" ] ||
    fail "medium waits should back off to 5s"
  [ "$(oms_poll_interval_seconds 180 300)" = "10" ] ||
    fail "long waits should cap at 10s by default"
  [ "$(oms_poll_interval_seconds 180 3)" = "3" ] ||
    fail "remaining time should cap the poll interval"
  [ "$(OMS_POLL_MAX_SECONDS=4 oms_poll_interval_seconds 180 300)" = "4" ] ||
    fail "OMS_POLL_MAX_SECONDS should cap long waits"
  out="$(OMS_POLL_VERBOSE=1 oms_poll_log_next unit 7 2 5 2>&1)"
  contains "$out" 'oh-my-setting poll: unit elapsed=7s next=2s remaining=5s' ||
    fail "verbose poll log should include label, elapsed, next, and remaining"
}

test_file_lock_nested_mkdir_preserves_nonzero_status_and_releases() {
  local dir="$TMP/file-lock-nested-mkdir"
  local outer="$dir/outer" inner="$dir/inner"
  local rc=0

  mkdir -p "$dir"
  OMS_LOCK_FORCE_MKDIR=1 OMS_LOCK_DIR="$dir/locks" \
    bash -c '
      set -euo pipefail
      . "$1"
      outer_path="$2"
      inner_path="$3"
      nested_failure() {
        oms_with_file_lock "$inner_path" bash -c "exit 3"
      }
      oms_with_file_lock "$outer_path" nested_failure
    ' _ "$ROOT/scripts/lib/file-lock.sh" "$outer" "$inner" \
      > "$dir/out" 2> "$dir/err" || rc=$?
  [ "$rc" = 3 ] ||
    fail "nested mkdir locks changed command status $rc: $(cat "$dir/err")"
  if grep -Fq 'unbound variable' "$dir/err"; then
    fail "nested mkdir lock cleanup lost its captured identity"
  fi
  . "$ROOT/scripts/lib/file-lock.sh"
  OMS_LOCK_FORCE_MKDIR=1 OMS_LOCK_DIR="$dir/locks" \
    oms_try_file_lock "$outer" true || fail "outer mkdir lock leaked"
  OMS_LOCK_FORCE_MKDIR=1 OMS_LOCK_DIR="$dir/locks" \
    oms_try_file_lock "$inner" true || fail "inner mkdir lock leaked"
}

test_file_lock_missing_poll_helper_falls_back() {
  local dir="$TMP/file-lock-no-poll"
  local lib="$dir/lib"
  local state="$dir/state.txt"

  mkdir -p "$lib"
  cp "$ROOT/scripts/lib/file-lock.sh" "$lib/file-lock.sh"
  (
    . "$lib/file-lock.sh"
    OMS_LOCK_FORCE_MKDIR=1 oms_with_file_lock "$state" bash -c 'printf fallback > "$1"' _ "$state"
  )
  assert_file_contains "$state" "fallback"
}

# smoke-weight: 5
test_file_lock_contention_preserves_records_across_backends() {
  local dir="$TMP/file-lock-contention"
  local append_file="$dir/append.txt"
  local rewrite_file="$dir/rewrite.txt"
  local n=30
  local expected=$((n * 2))
  local p1
  local p2

  mkdir -p "$dir"
  : > "$append_file"
  : > "$rewrite_file"
  . "$ROOT/scripts/lib/file-lock.sh"

  (
    for i in $(seq 1 "$n"); do
      oms_with_file_lock "$append_file" bash -c \
        'printf "%s-%03d\n" "$2" "$3" >> "$1"' _ "$append_file" A "$i"
    done
  ) &
  p1=$!
  (
    for i in $(seq 1 "$n"); do
      oms_with_file_lock "$append_file" bash -c \
        'printf "%s-%03d\n" "$2" "$3" >> "$1"' _ "$append_file" B "$i"
    done
  ) &
  p2=$!
  wait "$p1" || fail "append writer A failed"
  wait "$p2" || fail "append writer B failed"

  [ "$(wc -l < "$append_file" | tr -d ' ')" = "$expected" ] ||
    fail "locked appends lost records"
  [ "$(grep -Ec '^[AB]-[0-9][0-9][0-9]$' "$append_file")" = "$expected" ] ||
    fail "locked appends produced malformed records"
  [ "$(sort -u "$append_file" | wc -l | tr -d ' ')" = "$expected" ] ||
    fail "locked appends produced duplicate records"

  (
    for i in $(seq 1 "$n"); do
      oms_with_file_lock "$rewrite_file" bash -c '
        file="$1"
        prefix="$2"
        i="$3"
        tmp="$file.$$.$i"
        cat "$file" > "$tmp"
        printf "%s-%03d\n" "$prefix" "$i" >> "$tmp"
        mv "$tmp" "$file"
      ' _ "$rewrite_file" A "$i"
    done
  ) &
  p1=$!
  (
    for i in $(seq 1 "$n"); do
      oms_with_file_lock "$rewrite_file" bash -c '
        file="$1"
        prefix="$2"
        i="$3"
        tmp="$file.$$.$i"
        cat "$file" > "$tmp"
        printf "%s-%03d\n" "$prefix" "$i" >> "$tmp"
        mv "$tmp" "$file"
      ' _ "$rewrite_file" B "$i"
    done
  ) &
  p2=$!
  wait "$p1" || fail "rewrite writer A failed"
  wait "$p2" || fail "rewrite writer B failed"

  [ "$(wc -l < "$rewrite_file" | tr -d ' ')" = "$expected" ] ||
    fail "locked rewrites lost records"
  [ "$(grep -Ec '^[AB]-[0-9][0-9][0-9]$' "$rewrite_file")" = "$expected" ] ||
    fail "locked rewrites produced malformed records"
  [ "$(sort -u "$rewrite_file" | wc -l | tr -d ' ')" = "$expected" ] ||
    fail "locked rewrites produced duplicate records"
  # Repeat the append race through the mkdir fallback. The focused boundary
  # suite owns basic acquisition and stale-recovery cases; this case owns data
  # integrity for both lock backends.
  dir="$TMP/file-lock-mkdir-contention"
  append_file="$dir/append.txt"
  n=20
  expected=$((n * 2))

  # Same two-writer race as above but forced onto the mkdir fallback — the
  # branch every flock-less host (stock macOS) actually runs. Without this the
  # fallback's acquire loop is only ever tested single-process.
  mkdir -p "$dir"
  : > "$append_file"
  . "$ROOT/scripts/lib/file-lock.sh"

  (
    for i in $(seq 1 "$n"); do
      OMS_LOCK_FORCE_MKDIR=1 oms_with_file_lock "$append_file" bash -c \
        'printf "%s-%03d\n" "$2" "$3" >> "$1"' _ "$append_file" A "$i"
    done
  ) &
  p1=$!
  (
    for i in $(seq 1 "$n"); do
      OMS_LOCK_FORCE_MKDIR=1 oms_with_file_lock "$append_file" bash -c \
        'printf "%s-%03d\n" "$2" "$3" >> "$1"' _ "$append_file" B "$i"
    done
  ) &
  p2=$!
  wait "$p1" || fail "mkdir-lock writer A failed"
  wait "$p2" || fail "mkdir-lock writer B failed"

  [ "$(wc -l < "$append_file" | tr -d ' ')" = "$expected" ] ||
    fail "mkdir-locked appends lost records"
  [ "$(grep -Ec '^[AB]-[0-9][0-9][0-9]$' "$append_file")" = "$expected" ] ||
    fail "mkdir-locked appends produced malformed records"
  [ "$(sort -u "$append_file" | wc -l | tr -d ' ')" = "$expected" ] ||
    fail "mkdir-locked appends produced duplicate records"
}

# smoke-weight: 23
test_delegate_kill9_recovery_via_gc() {
  local project="$TMP/delegate-kill9"
  local bin="$project/bin"
  local home_dir="$project/home"
  local owner="owner_33333333333333333333333333333333"
  local dpid
  local i

  # A SIGKILLed delegate cannot run its EXIT trap: the liveness marker and the
  # plan claim both survive the crash. gc is the recovery path — it must sweep
  # the orphan marker AND release the coupled plan task in one pass.
  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  oms_smoke_make_fake_provider_stub "$bin/codex" <<EOF
#!/usr/bin/env bash
case "\${1:-}:\${2:-}" in --version:|--help:|exec:--help) echo fixture; exit 0 ;; esac
cat > /dev/null
echo \$\$ > "$project/worker.pid"
sleep 60
EOF
  "$ROOT/scripts/agent-plan.sh" --repo "$project" init --goal kill9 >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t1 --title T --verify true >/dev/null
  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$ROOT/scripts/agent-plan.sh" --repo "$project" claim --id t1 --provider codex >/dev/null

  HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" PATH="$bin:/usr/bin:/bin" \
    OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --plan-task t1 --no-verify \
    >"$project/out" 2>"$project/err" &
  dpid=$!
  # Wait for the liveness marker and worker entry, then SIGKILL mid-worker.
  for i in $(seq 1 100); do
    [ -n "$(find "$project/.oms/delegations" -name '*.json' 2>/dev/null)" ] &&
      [ -s "$project/worker.pid" ] && break
    kill -0 "$dpid" 2>/dev/null || fail "delegate died before starting its worker: $(cat "$project/err")"
    sleep 0.2
  done
  [ -n "$(find "$project/.oms/delegations" -name '*.json' 2>/dev/null)" ] ||
    fail "delegate never wrote a liveness marker"
  [ -s "$project/worker.pid" ] ||
    fail "delegate never started its worker: $(cat "$project/err")"
  if ! python3 - "$(find "$project/.oms/delegations" -name '*.json' | sed -n '1p')" <<'PY'
import json, sys
d = json.load(open(sys.argv[1]))
assert d["schema"] == 4
assert isinstance(d.get("pid"), int) and d["pid"] > 0
assert isinstance(d.get("native_pid"), int) and d["native_pid"] > 0
assert d["task_id"] == "t1"
assert d["lease_id"].startswith("lease_")
assert d["autopilot_owner_id"] == "owner_33333333333333333333333333333333"
PY
  then
    fail "delegation marker should carry the captured plan lease"
  fi
  kill -9 "$dpid" 2>/dev/null || true
  wait "$dpid" 2>/dev/null || true
  if [ -f "$project/worker.pid" ]; then
    kill -9 "$(cat "$project/worker.pid")" 2>/dev/null || true
  fi
  # Give the worker's pid a moment to die so gc's kill -0 sees an orphan.
  sleep 1

  [ -n "$(find "$project/.oms/delegations" -name '*.json' 2>/dev/null)" ] ||
    fail "SIGKILL should leave the orphan marker behind (that is the point)"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" show --id t1 |
    grep -E '"state": "(claimed|running)"' > /dev/null ||
    fail "plan task should still hold the crashed worker lease"

  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null 2>&1 )
  [ -z "$(find "$project/.oms/delegations" -name '*.json' 2>/dev/null)" ] ||
    fail "gc should sweep the orphan marker"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" show --id t1 | grep -F '"state": "ready"' > /dev/null ||
    fail "gc should release the crashed worker's plan task"
  # The SIGKILLed delegate cannot clean its managed worktree directory. The
  # shared residue cleaner must scan the private delegate root as well as
  # TMPDIR, remove the exact marked directory, and prune its Git registration.
  local leaked
  HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/cleanup.sh" --apply >"$project/cleanup.out"
  for leaked in "$home_dir/.cache/oh-my-setting/worktrees"/oh-my-setting-delegate.*; do
    [ -d "$leaked" ] || continue
    grep -Fq "repo=$project" "$leaked/.oh-my-setting-tmp" 2>/dev/null || continue
    fail "cleanup left a crashed delegate worktree: $leaked ($(tr '\n' ' ' < "$project/cleanup.out"))"
  done
  grep -Fq 'dead harness temp dir' "$project/cleanup.out" ||
    fail "cleanup did not report the crashed delegate worktree: $(tr '\n' ' ' < "$project/cleanup.out")"
  git -C "$project" worktree prune >/dev/null 2>&1 || true
}

# smoke-weight: 27
test_delegate_marker_set_lock_does_not_grow_per_run() {
  local project="$TMP/delegate-marker-set-lock"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local lock_dir="$project/locks"
  local first_count second_count after_gc_count

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) echo 'fixture --effort low medium high'; exit 0 ;; esac
if [ "${1:-}" = exec ] && [ -n "${LEASE_NEGATIVE_STARTED:-}" ]; then
  printf 'started\n' > "$LEASE_NEGATIVE_STARTED"
fi
cat >/dev/null
printf 'worker edit\n' >> file.txt
echo done
EOF

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" OMS_LOCK_DIR="$lock_dir" \
    PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-delegate.sh" \
    --repo "$project" --to codex --prompt one --no-verify >/dev/null
  first_count="$(find "$lock_dir" -maxdepth 1 -type f \
    -name '.marker-set-lock-target.*.lock' 2>/dev/null | wc -l | tr -d ' ')"
  [ "$first_count" -le 1 ] || fail "one delegation created multiple marker-set locks"

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" OMS_LOCK_DIR="$lock_dir" \
    PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-delegate.sh" \
    --repo "$project" --to codex --prompt two --no-verify >/dev/null
  second_count="$(find "$lock_dir" -maxdepth 1 -type f \
    -name '.marker-set-lock-target.*.lock' 2>/dev/null | wc -l | tr -d ' ')"
  [ "$second_count" = "$first_count" ] ||
    fail "delegation marker-set lock count grew across runs"
  [ -z "$(find "$lock_dir" -maxdepth 1 -type f \
    -name '*.json.*.lock' -print -quit 2>/dev/null)" ] ||
    fail "normal delegation left a permanent per-marker flock inode"

  mkdir -p "$project/.oms/delegations"
  printf '%s\n' \
    '{"schema":4,"id":"dead","pid":999999,"native_pid":999999}' \
    > "$project/.oms/delegations/dead.json"
  OMS_LOCK_DIR="$lock_dir" "$ROOT/scripts/gc.sh" --repo "$project" \
    --days 30 --apply >/dev/null 2>&1 || fail "gc failed under the marker-set lock"
  after_gc_count="$(find "$lock_dir" -maxdepth 1 -type f \
    -name '.marker-set-lock-target.*.lock' 2>/dev/null | wc -l | tr -d ' ')"
  [ "$after_gc_count" = "$second_count" ] ||
    fail "gc created another marker-set lock identity"
  [ -z "$(find "$lock_dir" -maxdepth 1 -type f \
    -name '*.json.*.lock' -print -quit 2>/dev/null)" ] ||
    fail "gc left a permanent per-marker flock inode"
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" OMS_LOCK_DIR="$lock_dir" XDG_STATE_HOME="$TMP/delegate-marker-set-lock-state" \
    PATH="$bin_dir:/usr/bin:/bin" python3 - "$ROOT" "$project" <<'OBSERVATION'
import os, sys, json, subprocess
from pathlib import Path
from unittest.mock import patch
root, repo = map(Path, sys.argv[1:])
sys.path.insert(0, str(root / "scripts/lib"))
import terminal_panel as panel
import room
env = {k: v for k, v in os.environ.items() if not k.startswith(("OMS_PANEL_", "OMS_ROOM_", "OMS_DL_", "OMS_OBSERVER_", "OMS_OBSERVE_PLAN_"))
       and k not in {"OMS_STATE_REPO", "OMS_PLAN_LEASE_ID", "OMS_ATTEMPT_ID", "OMS_HARNESS_CHILD", "OMS_HARNESS_DELEGATE_DEPTH"}}
env.update(OMS_AGENT="claude", OMS_CAPABILITY_SKIP_MODELS="1", OMS_ROLE_ROUTING="0")
entry = ["bash", str(root / "scripts/oms")]
plan = entry + ["agent-plan", "--repo", str(repo)]
def run(argv, use_env=None, ok=True):
    result = subprocess.run(argv, cwd=repo, env=use_env or env, capture_output=True, text=True, timeout=30)
    if ok:
        assert result.returncode == 0, (argv, result.returncode, result.stdout, result.stderr)
    return result
with patch.dict(os.environ, env, clear=True):
    ident = room.create(repo, "lease-observation-negative", "Observation boundary")
    main = "lease-main"
    attempt = run(entry + ["agent-events", "--repo", str(repo), "start", "--provider", "claude", "--tool", "panel-main",
                          "--ref", "panel_role=main", "--ref", "panel_room_id=" + ident,
                          "--ref", "panel_room_participant=" + main, "--then", "starting", "--then", "working"]).stdout.strip()
    room.join(repo, ident, main, "claude", "main")
    room.join(repo, ident, "lease-child", "codex", "worker", "gpt-6-luna", parent=main)
env.update(OMS_ROOM_ID=ident, OMS_ROOM_REPO=str(repo), OMS_ROOM_PARTICIPANT=main, OMS_PANEL_MAIN_ATTEMPT=attempt)
run(plan + ["init", "--goal", "Validated observation"])
run(plan + ["add", "--id", "lease-bound", "--title", "Bound task", "--assignment",
            json.dumps(dict(provider="codex", model="gpt-6-luna", reasoning_effort="low"))])
run(plan + ["claim", "--id", "lease-bound", "--provider", "claude"])
def current():
    task = json.loads(run(plan + ["evidence-snapshot", "--id", "lease-bound"]).stdout)
    return dict(plan_id=task["plan_id"], task_id=task["id"], lease_id=task["lease_id"], claim_provider=task["provider"],
                owner_provider="claude", owner_participant=main, owner_attempt=attempt, room_id=ident)
started = repo / "observer-provider-started"
child_env = dict(env, OMS_PANEL_DISPATCH="1", OMS_PANEL_ROLE="worker", OMS_ROOM_PARTICIPANT="lease-child",
                 OMS_ROOM_ADMITTED_PARTICIPANT="lease-child", LEASE_NEGATIVE_STARTED=str(started))
peer = ["bash", str(root / "scripts/peer-delegate.sh"), "--repo", str(repo), "--to", "codex", "--model", "gpt-6-luna",
        "--reasoning-effort", "low", "--prompt", "Inspect file.txt.", "--task-id", "lease-bound", "--no-verify"]
def refuse(binding, extra=(), use_env=None, contains=None):
    result = run(peer + ["--observe-plan-binding", binding] + list(extra), use_env or child_env, ok=False)
    assert result.returncode != 0 and not started.exists(), (binding, result.stdout, result.stderr)
    assert not list((repo / ".oms/delegations").glob("*.json"))
    if contains:
        assert contains in result.stderr, result.stderr
binding = current()
for raw in ("{}", "[]", "null", "{", "z" * 4097, json.dumps(binding)[:-1] + ',"task_id":"lease-bound"}',
            *(json.dumps(dict(binding, plan_id=value)) for value in ("", "0", "plan_" + "0" * 31, "plan_" + "g" * 32)),
            *(json.dumps(dict(binding, lease_id=value)) for value in ("", "0", "lease_" + "0" * 31, "lease_" + "g" * 32)),
            json.dumps(dict(binding, lease_id="lease_" + "0" * 32)), json.dumps(dict(binding, plan_id="plan_" + "0" * 32)),
            json.dumps(dict(binding, task_id="lease-bound; printf injected")), json.dumps(dict(binding, room_id="foreign")),
            json.dumps(dict(binding, claim_provider="claude")), json.dumps(dict(binding, owner_provider="codex")),
            json.dumps(dict(binding, owner_attempt="att_" + "0" * 32)), json.dumps(dict(binding, injected=True))):
    refuse(raw)
refuse(json.dumps(binding), ["--observe-plan-binding", json.dumps(binding)], contains="duplicate --observe-plan-binding")
refuse(json.dumps(binding), ["--plan-task", "lease-bound"], contains="excludes plan-task")
refuse(json.dumps(binding), use_env=dict(child_env, OMS_ROOM_ADMITTED_PARTICIPANT="foreign-child"))
refuse(json.dumps(binding), use_env=dict(child_env, OMS_ROOM_REPO=str(repo.parent)))
# Private hostile plan bytes, never shared control state.
path = repo / ".oms/plan/tasks.json"
original = path.read_bytes()
for invalid in ("ownerless", "duplicate", "symlink", "hardlink", "oversize", "provider", "model", "reasoning_effort"):
    backup = path.with_name("lease-fixture-backup")
    backup.write_bytes(original)
    try:
        data = json.loads(original)
        if invalid == "ownerless":
            data["tasks"]["lease-bound"].pop("claimed_by_participant")
            path.write_text(json.dumps(data))
        elif invalid == "duplicate":
            path.write_text(original.decode().rstrip()[:-1] + ',"plan_id":"' + binding["plan_id"] + '"}')
        elif invalid in ("symlink", "hardlink"):
            path.unlink()
            if invalid == "symlink": path.symlink_to(backup.name)
            else: os.link(backup, path)
        elif invalid == "oversize": path.write_bytes(b" " * (4 * 1024 * 1024 + 1))
        else:
            data["tasks"]["lease-bound"]["assignment"][invalid] = {"provider":"claude", "model":"gpt-6-astra", "reasoning_effort":"high"}[invalid]
            path.write_text(json.dumps(data))
        refuse(json.dumps(binding), contains="assignment mismatch" if invalid in ("provider", "model", "reasoning_effort") else None)
    finally:
        path.unlink(); backup.unlink(); path.write_bytes(original)
# Exercise the real producer after the observation is validated.
run(peer + ["--observe-plan-binding", json.dumps(binding)], child_env)
attempts = json.loads(run(entry + ["agent-events", "--repo", str(repo), "list", "--json"]).stdout)
workers = [row for row in attempts if row.get("refs", {}).get("panel_room_participant") == "lease-child"]
assert workers and workers[-1]["refs"].get("panel_lease_id") == binding["lease_id"], workers
rows = [json.loads(line) for line in (repo / ".oms/artifacts/index.jsonl").read_text().splitlines()]
delegates = [row for row in rows if row.get("kind") == "delegate" and row.get("task_id") == "lease-bound"]
assert delegates and delegates[-1].get("plan_id") == binding["plan_id"], delegates
started.unlink()
# Freeze a production panel snapshot, replace its lease via the API, then run the actual peer command.
real_launch = subprocess.Popen
def replace_before_launch(argv, *args, **kwargs):
    # The panel launches its call with Popen; every other process (including run()) passes through.
    if not isinstance(argv, list) or "--observe-plan-binding" not in argv:
        return real_launch(argv, *args, **kwargs)
    frozen = json.loads(argv[argv.index("--observe-plan-binding") + 1])
    run(plan + ["release", "--id", "lease-bound", "--lease-id", frozen["lease_id"]])
    run(plan + ["claim", "--id", "lease-bound", "--provider", "claude"])
    assert current()["lease_id"] != frozen["lease_id"]
    kwargs["env"] = dict(kwargs["env"], LEASE_NEGATIVE_STARTED=str(started))
    return real_launch(argv, *args, **kwargs)
brief = repo / "lease-brief.md"
brief.write_text("Inspect file.txt without edits; return evidence.\n")
with patch.dict(os.environ, env, clear=True), patch.object(panel.subprocess, "Popen", side_effect=replace_before_launch):
    assert panel.dispatch(repo, "claude", "worker", None, "write", "implement", brief=brief, verify=":",
                          task_id="lease-bound", target="codex", model="gpt-6-luna", effort="low") != 0
assert not started.exists()
run(entry + ["agent-events", "--repo", str(repo), "transition", "--attempt", attempt,
             "--state", "cancelled", "--reason-code", "fixture-terminal"])
refuse(json.dumps(current()), contains="panel main and room caller identities disagree or are not live")
print("observation negatives: malformed/duplicate/stale/foreign/injected/unsafe plan/assignment and real panel replacement barrier passed")
OBSERVATION

}

setup_doctor_home() {
  local home_dir="$1"

  mkdir -p "$home_dir"
  HOME="$home_dir" "$ROOT/scripts/link.sh" >/dev/null
  # A healthy install has the Claude hooks registered; the doctor verifies the
  # registration whenever the receipt is valid, so a clean fixture registers
  # them the same way install.sh does.
  HOME="$home_dir" "$ROOT/scripts/install-claude-hooks.sh" >/dev/null
  # A healthy install lets antigravity read a repository in headless mode; the
  # doctor only checks this when agy is on PATH, so a clean fixture has to look
  # healthy on a developer machine that has it installed.
  mkdir -p "$home_dir/.gemini/antigravity-cli"
  cat > "$home_dir/.gemini/antigravity-cli/settings.json" <<'JSON'
{
  "permissions": {
    "allow": ["command(*)", "read_file(*)"]
  }
}
JSON
  # Same reason as the block above: gh is credentialed per HOME, so a fixture
  # HOME always looks logged out on a machine that is in fact logged in, and a
  # clean install would report a warning it has no way to fix.
  # Presence is all the doctor reads, so no credential-shaped line is needed —
  # and must not be written: the harness's own sources have to pass the
  # outbound scrubber.
  mkdir -p "$home_dir/.config/gh"
  printf 'github.com:\n    user: oms-test\n' > "$home_dir/.config/gh/hosts.yml"
  # Same again for the provider CLIs: their credentials live under HOME, so a
  # fixture HOME looks logged out for every one that is installed on the
  # developer machine, and a clean install would warn about something it cannot
  # fix from here.
  mkdir -p "$home_dir/.claude" "$home_dir/.codex" "$home_dir/.gemini"
  printf '{"fixture": true}\n' > "$home_dir/.claude/.credentials.json"
  printf '{"fixture": true}\n' > "$home_dir/.codex/auth.json"
  printf '{"fixture": true}\n' > "$home_dir/.gemini/oauth_creds.json"
}

run_doctor_for_project() {
  local project="$1"
  local home_dir="$2"

  (cd "$project" && HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" \
    XDG_RUNTIME_DIR="$home_dir/runtime" \
    OH_MY_SETTING_REQUIRE_TOOLS=0 OH_MY_SETTING_CODEX_PLUGIN=0 "$ROOT/scripts/doctor.sh")
}

test_project_template_dry_runs_have_no_writes() {
  local general_project="$TMP/dry-run-general"
  local ml_project="$TMP/dry-run-ml"

  OH_MY_SETTING_DRY_RUN=1 \
    "$ROOT/scripts/apply-project-template.sh" general "$general_project" >/dev/null
  assert_not_exists "$general_project"

  OH_MY_SETTING_DRY_RUN=1 \
    "$ROOT/scripts/apply-project-template.sh" ml "$ml_project" >/dev/null
  assert_not_exists "$ml_project"
}

test_apply_loader_allows_clear_bounded_changes() {
  local project="$TMP/loader-bounded"
  local words

  "$ROOT/scripts/apply-project-template.sh" general "$project" >/dev/null
  assert_file_contains "$project/AGENTS.md" "Clear bounded changes may proceed from local evidence."
  words="$(wc -w < "$project/AGENTS.md" | tr -d ' ')"
  [ "$words" -le 60 ] || fail "generated loader should stay under 60 words (got $words)"
  if grep -Fq 'Project work starts only after it is filled and confirmed.' "$project/AGENTS.md"; then
    fail "generated loader should not gate clear bounded work on PROJECT.md confirmation"
  fi
}

test_apply_loader_abbreviates_home() {
  local project="$TMP/loader-home"
  local fake_home

  # The loader pointer abbreviates $HOME to ~: an absolute home path is a
  # machine detail and resolves nowhere else. HOME is the checkout's parent
  # here so the abbreviation has a prefix to strike.
  fake_home="$(cd "$ROOT/.." && pwd)"
  HOME="$fake_home" "$ROOT/scripts/apply-project-template.sh" general "$project" >/dev/null
  # shellcheck disable=SC2088  # the literal ~ is the assertion: abbreviate, not expand
  assert_file_contains "$project/AGENTS.md" "~/$(basename "$ROOT")/templates/project-general-AGENTS.md"
  # HOME=/tmp also occurs inside a valid ~/tmp.*/... abbreviation.
  if grep -Fq "$ROOT/templates/" "$project/AGENTS.md"; then
    fail "generated loader leaks the absolute home path"
  fi
}

test_ml_template_keeps_cluster_guidance_in_slurm_overlay() {
  # The ML template applies on workstations too; cluster-only commands ride
  # the conditional Slurm overlay so they never follow into machines that
  # cannot run them.
  if grep -Eq 'snapshot --cluster|run-reconcile' "$ROOT/templates/project-ml-AGENTS.md"; then
    fail "ML template carries cluster-only guidance; it belongs in the slurm overlay"
  fi
  grep -Eq 'snapshot --cluster' "$ROOT/templates/project-slurm-AGENTS.md" ||
    fail "slurm overlay lost its cluster snapshot guidance"
}

test_generated_project_contracts_stay_compact() {
  local general="$TMP/project-budget-general"
  local ml="$TMP/project-budget-ml"
  local general_words ml_words

  "$ROOT/scripts/apply-project-template.sh" general "$general" >/dev/null
  "$ROOT/scripts/apply-project-template.sh" ml "$ml" >/dev/null
  general_words="$(wc -w < "$general/PROJECT.md" | tr -d ' ')"
  ml_words="$(wc -w < "$ml/PROJECT.md" | tr -d ' ')"
  [ "$general_words" -le 100 ] || fail "generated general PROJECT.md is too large ($general_words words)"
  [ "$ml_words" -le 200 ] || fail "generated ML PROJECT.md is too large ($ml_words words)"
  assert_file_contains "$ml/PROJECT.md" '- Prediction unit:'
  assert_file_contains "$ml/PROJECT.md" '- Inference-time information boundary:'
  assert_file_contains "$ml/PROJECT.md" '- Split/group keys:'
  assert_file_contains "$ml/PROJECT.md" '- Validation interval'
  assert_file_contains "$ml/PROJECT.md" '- Success criteria:'
  assert_file_contains "$general/PROJECT.md" '- Affected checks:'
  assert_file_contains "$general/PROJECT.md" '- Always-run checks:'
  assert_file_contains "$general/PROJECT.md" '- CI scope/runtime:'
  assert_file_contains "$general/PROJECT.md" '- Required checks:'
}

test_project_template_mutators_reject_unclosed_managed_blocks() {
  local apply_project="$TMP/apply-malformed"
  local remove_project="$TMP/remove-malformed"

  mkdir -p "$apply_project"
  cat > "$apply_project/AGENTS.md" <<'EOF'
before
<!-- oh-my-setting:general:begin -->
managed
after
EOF

  if "$ROOT/scripts/apply-project-template.sh" general "$apply_project" AGENTS.md \
      >/dev/null 2>"$apply_project/error"; then
    fail "apply should reject unclosed managed block"
  fi
  assert_file_contains "$apply_project/AGENTS.md" "after"
  assert_file_contains "$apply_project/error" "missing managed block end"

  mkdir -p "$remove_project"
  cat > "$remove_project/AGENTS.md" <<'EOF'
before
<!-- oh-my-setting:general:begin -->
managed
after
EOF

  if "$ROOT/scripts/remove-project-template.sh" general "$remove_project" AGENTS.md \
      >/dev/null 2>"$remove_project/error"; then
    fail "remove should reject unclosed managed block"
  fi
  assert_file_contains "$remove_project/AGENTS.md" "after"
  assert_file_contains "$remove_project/error" "missing managed block end"
}

test_apply_ml_scaffolds_docs() {
  local project="$TMP/ml-docs"
  local full="$TMP/ml-docs-full"
  local doctor_out
  mkdir -p "$project/docs"
  printf 'user content\n' > "$project/docs/DATA.md"

  "$ROOT/scripts/apply-project-template.sh" ml "$project" >/dev/null

  for doc in MODEL EVALUATION EXPERIMENTS REPRODUCIBILITY TRAINING; do
    [ ! -e "$project/docs/$doc.md" ] || fail "default ml scaffold should not generate optional docs: $doc"
  done
  doctor_out="$("$ROOT/scripts/project-doctor.sh" "$project")" ||
    fail "minimal ML onboarding should pass project doctor: $doctor_out"
  if contains "$doctor_out" 'core ml doc(s) missing'; then
    fail "doctor must not warn about intentionally optional documentation: $doctor_out"
  fi
  [ -f "$project/PROJECT.md" ] || fail "ml scaffold must retain the project contract"
  assert_file_contains "$project/docs/DATA.md" "user content"
  if grep -Fq '## Schema' "$project/docs/DATA.md"; then
    fail "existing docs/DATA.md should not be overwritten"
  fi

  "$ROOT/scripts/apply-project-template.sh" ml "$full" --full-docs >/dev/null
  for doc in SETUP DATA MODEL TRAINING EVALUATION EXPERIMENTS CHECKPOINTS LOGGING BENCHMARKS REPRODUCIBILITY CONFIGS CHANGELOG DEBUGGING; do
    [ -f "$full/docs/$doc.md" ] || fail "full ml doc not scaffolded: $doc.md"
  done
  assert_file_contains "$full/docs/CHECKPOINTS.md" "Default checkpoint policy"
  assert_file_contains "$full/docs/CHECKPOINTS.md" '`latest`'
  assert_file_contains "$full/docs/CHECKPOINTS.md" '`best`'
  assert_file_contains "$full/docs/CHECKPOINTS.md" "then rename"
  assert_file_contains "$full/docs/CHECKPOINTS.md" "never the test split"
  assert_file_contains "$full/docs/CHECKPOINTS.md" 'checkpoints/<run-id>/latest.pt'
  assert_file_contains "$full/docs/CHECKPOINTS.md" 'checkpoints/<run-id>/best.pt'
  assert_file_contains "$full/docs/CHECKPOINTS.md" "Keep exactly these two files per run"
  assert_file_contains "$full/docs/CHECKPOINTS.md" "Never put epoch, step or metric in a"
  assert_file_contains "$full/docs/CHECKPOINTS.md" "at most about 10%"
  assert_file_contains "$full/docs/CHECKPOINTS.md" "not every epoch"
  assert_file_contains "$full/docs/CHECKPOINTS.md" "state it in validations"
  assert_file_contains "$full/docs/CHECKPOINTS.md" "A tie keeps the earlier"
  assert_file_contains "$ROOT/templates/project-skills/oms-ml-experiment/SKILL.md" 'checkpoints/<run-id>/latest.pt'
  assert_file_contains "$ROOT/templates/project-skills/oms-ml-experiment/SKILL.md" "validation interval"

  local cwd_full="$TMP/ml-docs-full-cwd"
  mkdir -p "$cwd_full"
  (cd "$cwd_full" && "$ROOT/scripts/apply-project-template.sh" ml --full-docs >/dev/null)
  [ -f "$cwd_full/docs/TRAINING.md" ] ||
    fail "--full-docs should use cwd when project_dir is omitted"

  local lead_full="$TMP/ml-docs-full-lead"
  mkdir -p "$lead_full"
  "$ROOT/scripts/apply-project-template.sh" ml --full-docs "$lead_full" >/dev/null ||
    fail "a --full-docs before project_dir must not be taken as the path"
  [ -f "$lead_full/AGENTS.md" ] && [ -f "$lead_full/docs/TRAINING.md" ] ||
    fail "a --full-docs before project_dir must scaffold into project_dir"
  if compgen -G "$lead_full/tmp.*" >/dev/null || compgen -G "$lead_full/*/tmp.*" >/dev/null; then
    fail "a misordered --full-docs must leave no tempfile"
  fi
  "$ROOT/scripts/apply-project-template.sh" general --help | grep -F "Usage:" > /dev/null ||
    fail "--help after the style must print usage and exit 0"
}

test_apply_ml_scaffolds_gitignore() {
