}

test_apply_ml_scaffolds_check_contract() {
  local project="$TMP/ml-check"
  mkdir -p "$project/scripts"
  printf '#!/bin/sh\necho custom\n' > "$project/scripts/check.sh"
  mkdir -p "$project/.github/workflows"
  printf 'name: existing-ci\n' > "$project/.github/workflows/custom.yml"

  "$ROOT/scripts/apply-project-template.sh" ml "$project" >/dev/null
  assert_file_contains "$project/scripts/check.sh" "custom"
  [ "$(cat "$project/.github/workflows/custom.yml")" = 'name: existing-ci' ] ||
    fail 'onboarding must preserve existing CI'

  local project2="$TMP/ml-check-new"
  mkdir -p "$project2"
  "$ROOT/scripts/apply-project-template.sh" ml "$project2" >/dev/null
  [ ! -d "$project2/.github/workflows" ] || fail 'onboarding must not add CI by default'
  [ -x "$project2/scripts/check.sh" ] || fail "check.sh not scaffolded executable"
  assert_file_contains "$project2/scripts/check.sh" "Project verification contract"
  [ -f "$project2/scripts/ml_smoke.py" ] || fail "ml_smoke.py not scaffolded"
  assert_file_contains "$project2/scripts/ml_smoke.py" "One-batch ML interface smoke"
  [ -f "$project2/scripts/ml_resume_smoke.py" ] || fail "ml_resume_smoke.py not scaffolded"
  python3 "$project2/scripts/ml_resume_smoke.py" >/dev/null ||
    fail "scaffolded resume smoke does not pass on its demo plug-in"
  python3 "$project2/scripts/ml_resume_smoke.py" --self-test >/dev/null ||
    fail "resume smoke did not detect a checkpoint that omits RNG/optimizer/scheduler state"

  printf 'custom smoke\n' > "$project/scripts/ml_smoke.py"
  "$ROOT/scripts/apply-project-template.sh" ml "$project" >/dev/null
  assert_file_contains "$project/scripts/ml_smoke.py" "custom smoke"

  # --python-ci is opt-in and refuses before any write: not a uv project, no
  # tests/ suite, a foreign checker, or existing CI.
  local py="$TMP/python-ci" before
  mkdir -p "$py/tests"
  printf '[project]\nname = "x"\n' > "$py/pyproject.toml"
  before="$(find "$py" | sort)"
  if "$ROOT/scripts/apply-project-template.sh" general "$py" --python-ci >/dev/null 2>&1; then
    fail '--python-ci must require uv.lock'
  fi
  [ "$(find "$py" | sort)" = "$before" ] || fail 'refused --python-ci wrote files'
  : > "$py/uv.lock"
  rmdir "$py/tests"
  if "$ROOT/scripts/apply-project-template.sh" general "$py" --python-ci >/dev/null 2>&1; then
    fail '--python-ci must require a tests/ suite'
  fi
  mkdir "$py/tests"
  : > "$project/pyproject.toml"; : > "$project/uv.lock"; mkdir -p "$project/tests"
  if "$ROOT/scripts/apply-project-template.sh" ml "$project" --python-ci >/dev/null 2>&1; then
    fail '--python-ci must refuse a custom checker'
  fi
  cp "$ROOT/templates/check.sh" "$project/scripts/check.sh"
  before="$(cat "$project/AGENTS.md")"
  if "$ROOT/scripts/apply-project-template.sh" ml "$project" --python-ci >/dev/null 2>&1; then
    fail '--python-ci must not add a second workflow'
  fi
  [ "$(cat "$project/AGENTS.md")" = "$before" ] && [ ! -e "$project/.github/workflows/python-ci.yml" ] ||
    fail 'refused --python-ci mutated the project'

  # Dangling links are destinations too; do not write outside the project.
  ln -s "$TMP/ci-outside" "$py/scripts"
  if "$ROOT/scripts/apply-project-template.sh" general "$py" --python-ci >/dev/null 2>&1; then
    fail '--python-ci must refuse symlink destinations'
  fi
  [ ! -e "$TMP/ci-outside" ] && [ ! -e "$py/AGENTS.md" ] || fail 'symlink refusal wrote files'
  rm "$py/scripts"

  # Every destination and parent is refused, python-ci or not, before any write.
  mkdir -p "$TMP/sl-a" "$TMP/sl-b" "$TMP/sl-outside"
  ln -s ../sl-outside/x "$TMP/sl-a/PROJECT.md"
  if "$ROOT/scripts/apply-project-template.sh" general "$TMP/sl-a" >/dev/null 2>&1; then
    fail 'a dangling PROJECT.md symlink must be refused'
  else
    [ "$?" = 2 ] || fail 'symlink refusal must exit 2'
  fi
  [ ! -e "$TMP/sl-outside/x" ] && [ ! -e "$TMP/sl-a/AGENTS.md" ] ||
    fail 'PROJECT.md symlink refusal wrote files'
  printf 'secret\n' > "$TMP/sl-outside/secret"
  ln -s ../sl-outside/secret "$TMP/sl-b/AGENTS.md"
  if "$ROOT/scripts/apply-project-template.sh" general "$TMP/sl-b" >/dev/null 2>&1; then
    fail 'an AGENTS.md symlink must be refused'
  else
    [ "$?" = 2 ] || fail 'symlink refusal must exit 2'
  fi
  [ "$(cat "$TMP/sl-outside/secret")" = secret ] && [ -L "$TMP/sl-b/AGENTS.md" ] ||
    fail 'AGENTS.md symlink refusal touched the link or its target'
  # ml skill installs land under .oms/.agents/.claude; a linked root is refused too.
  mkdir -p "$TMP/sl-c"
  ln -s ../sl-outside "$TMP/sl-c/.oms"
  if "$ROOT/scripts/apply-project-template.sh" ml "$TMP/sl-c" >/dev/null 2>&1; then
    fail 'a symlinked .oms skill root must be refused'
  else
    [ "$?" = 2 ] || fail 'skill root refusal must exit 2'
  fi
  [ -z "$(ls -A "$TMP/sl-outside")" ] || [ "$(ls "$TMP/sl-outside")" = secret ] ||
    fail 'skill root refusal wrote outside the project'
  [ ! -e "$TMP/sl-c/AGENTS.md" ] || fail 'skill root refusal wrote AGENTS.md'
  rm -r "$TMP/sl-a" "$TMP/sl-b" "$TMP/sl-c" "$TMP/sl-outside"

  before="$(find "$py" | sort)"
  OH_MY_SETTING_DRY_RUN=1 "$ROOT/scripts/apply-project-template.sh" general "$py" --python-ci >/dev/null
  [ "$(find "$py" | sort)" = "$before" ] || fail '--python-ci dry run wrote files'
  "$ROOT/scripts/apply-project-template.sh" general "$py" --python-ci >/dev/null
  "$ROOT/scripts/apply-project-template.sh" general "$py" --python-ci >/dev/null ||
    fail '--python-ci reapply must be idempotent'
  cmp -s "$ROOT/templates/check.sh" "$py/scripts/check.sh" && [ -x "$py/scripts/check.sh" ] ||
    fail '--python-ci did not scaffold the shared checker'
  cmp -s "$ROOT/templates/python-ci.yml" "$py/.github/workflows/python-ci.yml" ||
    fail '--python-ci did not scaffold the workflow'
  [ "$(ls "$py/.github/workflows")" = python-ci.yml ] && [ ! -e "$py/scripts/ml_smoke.py" ] ||
    fail '--python-ci added more than the checker and one workflow'
  assert_file_contains "$py/.github/workflows/python-ci.yml" 'bash scripts/check.sh fast --jobs 2 tests'
}

test_project_doctor_warns_missing_check() {
  local project="$TMP/doctor-no-check"
  local out drift
  mkdir -p "$project"

  "$ROOT/scripts/apply-project-template.sh" ml "$project" >/dev/null
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "doctor should pass fresh ml apply"
  contains "$out" 'ml block identical' ||
    fail "project-doctor should confirm identical ml blocks"
  contains "$out" 'matches current template' ||
    fail "project-doctor should confirm template freshness"
  contains "$out" 'verification contract present' ||
    fail "doctor should confirm the generated check.sh contract"

  # Fill the scientific contract so strict failures isolate checker drift.
  awk '
    /^- State:/ { print "- State: confirmed"; next }
    /^- .*:$/ { print $0 " fixture"; next }
    { print }
  ' "$project/PROJECT.md" > "$project/PROJECT.filled"
  mv "$project/PROJECT.filled" "$project/PROJECT.md"
  "$ROOT/scripts/project-doctor.sh" --strict "$project" >/dev/null ||
    fail "confirmed minimal ML onboarding must pass strict doctor without optional docs"

  for drift in missing nonexecutable; do
    if [ "$drift" = missing ]; then
      rm "$project/scripts/check.sh"
    else
      chmod -x "$project/scripts/check.sh"
    fi
    out="$("$ROOT/scripts/project-doctor.sh" "$project")" ||
      fail "checker drift should warn outside strict mode: $out"
    contains "$out" 'warn: scripts/check.sh missing or not executable' ||
      fail "doctor must warn about $drift checker: $out"
    if out="$("$ROOT/scripts/project-doctor.sh" --strict "$project")"; then
      fail "strict doctor accepted $drift checker: $out"
    fi
    if contains "$out" --python-ci; then
      fail "checker repair must not opt into CI: $out"
    fi
    if [ "$drift" = missing ]; then
      "$ROOT/scripts/apply-project-template.sh" ml "$project" >/dev/null
    else
      chmod +x "$project/scripts/check.sh"
    fi
    "$ROOT/scripts/project-doctor.sh" --strict "$project" >/dev/null ||
      fail "restoring the $drift checker must clear strict failure"
    [ ! -d "$project/.github/workflows" ] || fail "checker repair must not create CI"
  done
}

test_project_doctor_warns_structure_drift() {
  local project="$TMP/doctor-drift"

  mkdir -p "$project"
  "$ROOT/scripts/apply-project-template.sh" ml "$project" >/dev/null
  git -C "$project" init >/dev/null

  # Exempt files and an empty index with big UNTRACKED data must stay quiet.
  printf 'import pytest\n' > "$project/conftest.py"
  printf '# changelog\n' > "$project/CHANGELOG.md"
  mkdir -p "$project/data"
  printf '' > "$project/data/.gitkeep"
  git -C "$project" add -f data/.gitkeep >/dev/null
  dd if=/dev/zero of="$project/data/huge-untracked.bin" bs=1 count=0 seek=20971520 2>/dev/null

  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "clean scaffold should pass doctor"
  if printf '%s' "$out" | grep >/dev/null -E "move into src/|move there|over 10MB|gitignored dirs"; then
    fail "exempt files / untracked data must not raise drift warnings: $out"
  fi

  printf 'x = 1\n' > "$project/train_root.py"
  printf '# notes\n' > "$project/NOTES.md"
  printf '{}\n' > "$project/exp.ipynb"
  printf '[project]\nname = "x"\n' > "$project/pyproject.toml"
  printf 'a,b\n' > "$project/data/x.csv"
  git -C "$project" add -f data/x.csv >/dev/null
  dd if=/dev/zero of="$project/big model.ckpt" bs=1 count=0 seek=11534336 2>/dev/null
  git -C "$project" add -f "big model.ckpt" >/dev/null

  out="$("$ROOT/scripts/project-doctor.sh" "$project")" ||
    fail "structure drift must warn, not fail"
  contains "$out" 'train_root.py' || fail "missing stray-python warning"
  contains "$out" 'NOTES.md' || fail "missing markdown-outside-docs warning"
  case "$out" in *'exp.ipynb'*) ;; *) fail "missing notebook warning" ;; esac
  if contains "$out" 'src/ layout'; then
    fail "doctor must not require an ML src/ layout absent from the template"
  fi

  # --contract: one read-only look at what PROJECT.md points at. A target that
  # is not there warns (and fails only under --strict); an unproven criterion
  # is a note, because unfinished work is not drift.
  local contract_out contract="$TMP/doctor-contract" contract_before contract_rc=0
  make_committed_repo "$contract"
  mkdir -p "$contract/tests" "$contract/docs" "$contract/.oms/plan"
  printf 'exit 0\n' > "$contract/tests/run.sh"
  printf '# design\n' > "$contract/docs/design.md"
  cat > "$contract/PROJECT.md" <<'EOF'
# PROJECT.md

## Status

- State: confirmed

## Project

- Goal: ship a tiny greeting CLI
- Scope: src/, tests/

## Verification

- Required checks: bash tests/run.sh
- Required check files: tests/run.sh

## Decisions

- References: docs/design.md

## Acceptance criteria

- [id:REQ-1] WHEN run THE SYSTEM SHALL print hello
- [id:REQ-2] WHEN given a name THE SYSTEM SHALL print it
EOF
  printf '{"tasks":{"c1":{"id":"c1","covers":["REQ-1"]}}}\n' > "$contract/.oms/plan/tasks.json"
  contract_before="$(cd "$contract" && find . -path ./.git -prune -o -type f -print | sort | xargs cksum)"
  contract_out="$("$ROOT/scripts/project-doctor.sh" --contract --strict "$contract")" ||
    fail "a contract whose targets all exist must pass --contract --strict: $contract_out"
  contains "$contract_out" 'ok: contract: Required check files: 1 path(s) exist' || fail "check files not confirmed: $contract_out"
  contains "$contract_out" 'ok: contract: References: 1 path(s) exist' || fail "references not confirmed: $contract_out"
  contains "$contract_out" 'note: criterion REQ-1: ' || fail "criteria not summarised: $contract_out"
  contains "$contract_out" 'plan task c1' || fail "the covering plan task is not named: $contract_out"
  contains "$contract_out" 'note: criterion REQ-2: ' || fail "an uncovered criterion is still listed: $contract_out"
  contains "$contract_out" 'project-doctor: contract ok' || fail "missing contract verdict: $contract_out"
  if contains "$contract_out" 'managed blocks'; then fail "--contract must not run the block checks: $contract_out"; fi
  [ "$contract_before" = "$(cd "$contract" && find . -path ./.git -prune -o -type f -print | sort | xargs cksum)" ] ||
    fail "--contract must not write into the project"
  # Break three pointers: a check file, a reference, and a covered criterion.
  sed -e 's|^- Required check files: tests/run.sh|- Required check files: tests/run.sh, tests/gone.sh|' \
    -e 's|^- References: docs/design.md|- References: docs/design.md, docs/lost.md|' \
    "$contract/PROJECT.md" > "$contract/PROJECT.md.new" && mv "$contract/PROJECT.md.new" "$contract/PROJECT.md"
  printf '{"tasks":{"c1":{"id":"c1","covers":["REQ-1","REQ-9"]}}}\n' > "$contract/.oms/plan/tasks.json"
  contract_out="$("$ROOT/scripts/project-doctor.sh" --contract "$contract")" ||
    fail "broken pointers warn without --strict: $contract_out"
  contains "$contract_out" 'warn: contract: Required check files names tests/gone.sh, which does not exist' ||
    fail "missing check file not reported: $contract_out"
  contains "$contract_out" 'warn: contract: References names docs/lost.md, which does not exist' ||
    fail "missing reference not reported: $contract_out"
  contains "$contract_out" 'warn: contract: plan task c1 covers REQ-9, which the spec does not carry' ||
    fail "stale covers target not reported: $contract_out"
  contains "$contract_out" 'project-doctor: contract ok (with warnings)' || fail "missing warning verdict: $contract_out"
  contract_out="$("$ROOT/scripts/project-doctor.sh" --contract --strict "$contract")" || contract_rc=$?
  [ "$contract_rc" = 1 ] || fail "--contract --strict must fail on a broken pointer, got $contract_rc: $contract_out"
  case "$out" in *'gitignored dirs'*) ;; *) fail "missing tracked-in-ignored warning" ;; esac
  case "$out" in *'big model.ckpt'*) ;; *) fail "missing over-10MB warning (filename with space must survive)" ;; esac

  # High cardinality: head's early exit under pipefail must not silence the
  # warning (the exact bug: SIGPIPE wiped the captured output).
  for i in $(seq 1 100); do printf 'x\n' > "$project/data/f$i.bin"; done
  git -C "$project" add -f data >/dev/null
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "doctor should still warn-pass"
  contains "$out" 'gitignored dirs' ||
    fail "many tracked ignored files must still warn (pipefail/head)"

  # A small tracked symlink to a big target must not be flagged.
  dd if=/dev/zero of="$project/.big-target" bs=1 count=0 seek=20971520 2>/dev/null
  ln -s .big-target "$project/link.ckpt"
  git -C "$project" add -f link.ckpt >/dev/null
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "doctor should still warn-pass"
  if contains "$out" 'link.ckpt'; then
    fail "tracked symlink must not be measured by its target size"
  fi

  # Notebook hygiene: a tracked notebook with stored outputs and a reversed
  # execution_count is reported; a clean one and an untracked one are not.
  local pad
  pad="$(printf 'x%.0s' $(seq 1 1500))"
  mkdir -p "$project/notebooks"
  printf '{"cells":[{"cell_type":"code","execution_count":3,"source":["a=1"],"outputs":[{"output_type":"stream","text":["%s"]}]},{"cell_type":"code","execution_count":2,"source":["b=1"],"outputs":[]}],"nbformat":4}\n' \
    "$pad" > "$project/notebooks/dirty.ipynb"
  printf '{"cells":[{"cell_type":"code","execution_count":null,"source":["a=1"],"outputs":[]}],"nbformat":4}\n' \
    > "$project/notebooks/clean.ipynb"
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "doctor should still warn-pass"
  if contains "$out" 'dirty.ipynb stores outputs'; then
    fail "untracked notebook must not be inspected by the hygiene check"
  fi
  git -C "$project" add -f notebooks/dirty.ipynb notebooks/clean.ipynb >/dev/null
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "notebook hygiene must warn, not fail"
  contains "$out" 'notebooks/dirty.ipynb stores outputs in 1 code cell(s)' ||
    fail "missing stored-output notebook warning: $out"
  contains "$out" 'notebooks/dirty.ipynb ran out of order' ||
    fail "missing execution_count reversal warning: $out"
  if contains "$out" 'clean.ipynb stores' || contains "$out" 'clean.ipynb ran'; then
    fail "clean notebook must not be flagged: $out"
  fi
  grep -Fq "$pad" "$project/notebooks/dirty.ipynb" ||
    fail "hygiene check must never rewrite a notebook"
}

test_project_doctor_warns_unregistered_experiments() {
  local project="$TMP/doctor-prereg"

  mkdir -p "$project"
  "$ROOT/scripts/apply-project-template.sh" ml "$project" >/dev/null
  git -C "$project" init >/dev/null

  # Fresh ml scaffold has the section and no ledger: quiet.
  assert_file_contains "$project/PROJECT.md" '## Experiment Pre-Registration'
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "fresh scaffold should pass"
  if printf '%s' "$out" | grep >/dev/null 'no .## Experiment Pre-Registration'; then
    fail "scaffolded section present: must not warn"
  fi

  # Ledger rows + PROJECT.md without the section (legacy project): warn.
  sed -i '/^## Experiment Pre-Registration/,/^## Slurm\|^## Notes/{/^## Slurm\|^## Notes/!d}' "$project/PROJECT.md"
  mkdir -p "$project/docs"
  printf '{"ts":"2026-06-11T00:00:00Z","exit":0}\n' > "$project/docs/EXPERIMENTS.jsonl"
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "missing pre-reg should warn, not fail"
  printf '%s' "$out" | grep >/dev/null 'Experiment Pre-Registration' ||
    fail "ledger without pre-registration section must warn"
}

test_project_doctor_warns_empty_contract_past_draft() {
  local project="$TMP/doctor-contract"

  mkdir -p "$project"
  "$ROOT/scripts/apply-project-template.sh" general "$project" >/dev/null

  # Fresh apply is draft: the contract warnings must stay silent.
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "fresh general apply should pass"
  if printf '%s' "$out" | grep >/dev/null 'past draft but'; then
    fail "draft PROJECT.md must not raise contract warnings"
  fi

  # Promote past draft while leaving commands/verification empty: warn.
  sed -i 's/^- State: draft/- State: active/' "$project/PROJECT.md"
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "empty contract should warn, not fail"
  contains "$out" 'Commands (Setup/Test/Run) are empty' ||
    fail "doctor should warn about empty commands"
  contains "$out" "'Success criteria' is empty" ||
    fail "doctor should warn about empty success criteria"

  # Fill the contract: warnings clear.
  sed -i 's/^- Test:$/- Test: pytest/; s/^- Success criteria:$/- Success criteria: tests pass/' \
    "$project/PROJECT.md"
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" || fail "filled contract should pass"
  if printf '%s' "$out" | grep >/dev/null 'past draft but'; then
    fail "filled contract must not warn: $out"
  fi
}

