test_review_verdicts_subcommand() {
  local dir="$TMP/verdicts"
  local run="20260611T000000Z-42"

  mkdir -p "$dir/mixed" "$dir/allpass"
  # Complete pass, complete fail, and a died-mid-run artifact. The prompt echo
  # inside Output ("...exactly one line: GATE: pass or GATE: fail.") must not
  # be read as a verdict.
  printf '# codex review\n\n## Output\n\nexactly one line: GATE: pass or GATE: fail.\nFindings: none\nCONFIDENCE: 0.9\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/mixed/codex-x-$run.md"
  printf '# claude review\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' \
    > "$dir/mixed/claude-x-$run.md"
  printf '# antigravity review\n\n## Output\n\npartial output then death\n' \
    > "$dir/mixed/antigravity-x-$run.md"

  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/mixed")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "incomplete artifact should yield exit 2, got $rc"
  contains "$out" 'codex: pass (confidence 0.9)' ||
    fail "stated confidence should ride the verdict line: $out"
  contains "$out" 'claude: fail' || fail "missing claude fail"
  contains "$out" 'antigravity: incomplete' || fail "missing incomplete detection"

  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/allpass/codex-x-$run.md"
  printf '# synthesis\n' > "$dir/allpass/_synthesis-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/allpass")" && rc=0 || rc=$?
  [ "$rc" = "0" ] || fail "all-pass run should exit 0, got $rc"
  if printf '%s' "$out" | grep >/dev/null '_synthesis'; then
    fail "synthesis artifact must not be treated as a provider"
  fi

  mkdir -p "$dir/empty"
  if "$ROOT/scripts/peer-review.sh" verdicts "$dir/empty" >/dev/null 2>&1; then
    fail "empty dir should exit nonzero"
  fi

  # A seat that died after printing a GATE line: the recorded nonzero exit
  # voids the verdict — a partial transcript's pass must not open the gate.
  mkdir -p "$dir/died"
  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n124\n' \
    > "$dir/died/codex-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/died")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "a dead seat's GATE line must not gate (want exit 2, got $rc)"
  contains "$out" 'codex: no-verdict (provider exited 124' ||
    fail "dead seat must be named with its exit: $out"

  # A max_tokens stop exits 0 with finished-looking sentences; the recorded
  # stop reason voids the GATE line the same way a dead exit does.
  mkdir -p "$dir/maxtok"
  printf '# claude review\n\n## Output\n\nstop-reason: provider=claude reason=max_tokens subtype=success is_error=0\nFindings: fine\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/maxtok/claude-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/maxtok")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "a max_tokens seat's GATE line must not gate (want exit 2, got $rc)"
  contains "$out" 'claude: no-verdict (incomplete answer: provider=claude reason=max_tokens' ||
    fail "truncated seat must be named with its stop reason: $out"

  mkdir -p "$dir/agy-timeout"
  printf '# antigravity review\n\n## Output\n\nGATE: pass\n[agy] print timeout after 10m0s with turn in progress; returning partial output\n\n## Exit\n\n0\n' \
    > "$dir/agy-timeout/antigravity-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/agy-timeout")" && rc=0 || rc=$?
  [ "$rc" = 2 ] || fail "a legacy print-timeout artifact must not pass review: $out"

  # A marker quoted in the prompt (a replayed thread turn, a diff's context
  # lines) is not the transport's verdict: only the Output region counts.
  mkdir -p "$dir/quoted"
  printf '# claude review\n\n## Prompt\n\nstop-reason: provider=claude reason=max_tokens subtype=success is_error=0\n\n## Output\n\nstop-reason: provider=claude reason=end_turn subtype=success is_error=0\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/quoted/claude-x-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/quoted")" && rc=0 || rc=$?
  [ "$rc" = "0" ] || fail "a prompt-quoted stop-reason must not void a healthy seat (got $rc): $out"
  q="$(printf '# a\n\n## Prompt\n\n stop-reason: provider=claude reason=max_tokens subtype=success is_error=0\n\n## Output\n\nstop-reason: provider=claude reason=end_turn subtype=success is_error=0\nA complete answer with plenty of body to clear the length floor easily.\n\n## Exit\n\n0\n' > "$dir/quoted/aq.md"; python3 "$ROOT/scripts/lib/answer-quality.py" "$dir/quoted/aq.md")"
  [ "$q" = "ok" ] || fail "answer-quality must read the stop reason from the Output region only (got $q)"
  q="$(printf '# a\n\n## Output\n\nstop-reason: provider=claude reason=refusal subtype=success is_error=0 category=cyber\nI cannot help with that request, but here is a long enough sentence.\n\n## Exit\n\n0\n' > "$dir/quoted/refusal.md"; python3 "$ROOT/scripts/lib/answer-quality.py" "$dir/quoted/refusal.md")"
  [ "$q" = "blocked" ] || fail "a refusal stop reason with is_error=0 is not an answer (got $q)"

  # Debate runs: judge each provider's FINAL round, not round 1; a slug that
  # contains "-r9" must not be parsed as a round suffix.
  mkdir -p "$dir/debate"
  printf '# c\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' > "$dir/debate/codex-x-$run.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/codex-x-$run-r2.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/claude-x-$run.md"
  printf '# c\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' > "$dir/debate/claude-x-$run-r1.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/antigravity-fix-r9-thing-$run.md"

  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/debate")" && rc=0 || rc=$?
  [ "$rc" = "1" ] || fail "debate run with a final-round fail should exit 1, got $rc"
  contains "$out" 'codex: pass' || fail "codex must be judged on final round (r2 pass)"
  contains "$out" 'claude: fail' || fail "claude must be judged on final round (r1 fail)"
  contains "$out" 'antigravity: pass' || fail "slug containing -r9 must be treated as base artifact"

  # A structured provider failure followed by a complete fallback attempt: the
  # controller's attempt sidecar names the final attempt's own output file and
  # the provider/model that produced it; the artifact keeps both for humans.
  mkdir -p "$dir/fallback" "$dir/fallback-dead" "$dir/forged" "$dir/forged-legacy"
  printf '# codex review\n\n## Output\n\nmodel-route: class=explicit (explicit) primary=gpt-6-astra fallback=- effort=high\nstop-reason: provider=codex reason=turn_failed subtype=error is_error=1\nERROR: 429 rate limit\nGATE: fail\n\npanel-provider-fallback: provider=claude model=claude-opus-5-5 reason=capacity exit=1\nstop-reason: provider=claude reason=end_turn subtype=success is_error=0\nCONFIDENCE: 0.8\nGATE: pass\n\nmodel-result: selected=claude-opus-5-5 effort=high fallback_used=1 reason=provider-capacity\n\n## Exit\n\n0\n' \
    > "$dir/fallback/codex-x-$run.md"
  printf 'stop-reason: provider=codex reason=turn_failed subtype=error is_error=1\nERROR: 429 rate limit\nGATE: fail\n' > "$dir/fallback/codex-x-$run.attempt-1.out"
  printf 'stop-reason: provider=claude reason=end_turn subtype=success is_error=0\nCONFIDENCE: 0.8\nGATE: pass\n' > "$dir/fallback/codex-x-$run.attempt-2.out"
  printf '{"attempts": [{"provider": "codex", "model": "gpt-6-astra", "effort": "high", "exit": 1, "stop_reason": "provider=codex reason=turn_failed subtype=error is_error=1", "classification": "capacity", "output": "codex-x-%s.attempt-1.out"}, {"provider": "claude", "model": "claude-opus-5-5", "effort": "high", "exit": 0, "stop_reason": "provider=claude reason=end_turn subtype=success is_error=0", "classification": "", "output": "codex-x-%s.attempt-2.out"}]}\n' \
    "$run" "$run" > "$dir/fallback/codex-x-$run.attempts.json"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/fallback")" && rc=0 || rc=$?
  [ "$rc" = "0" ] || fail "a complete fallback pass must gate as pass (got $rc): $out"
  contains "$out" 'claude: pass (confidence 0.8)' ||
    fail "fallback verdict must be attributed to the provider that answered: $out"
  if printf '%s' "$out" | grep >/dev/null 'codex:'; then
    fail "the failed primary must not own the fallback verdict: $out"
  fi
  out="$("$ROOT/scripts/peer-review.sh" verdicts --json "$dir/fallback")" || true
  OMS_TEST_JSON="$out" python3 - <<'PY' || fail "json fallback attribution wrong: $out"
import json, os
data = json.loads(os.environ["OMS_TEST_JSON"])
seat = data["seats"][0]
assert len(data["seats"]) == 1 and data["overall"] == 0, data
assert seat["provider"] == "claude" and seat["verdict"] == "pass", seat
assert seat["selected_model"] == "claude-opus-5-5", seat
assert seat["requested_model"] == "gpt-6-astra", seat
assert seat["model_family"] == "anthropic", seat
assert seat["artifact"].startswith("codex-x-"), seat
PY

  # A fallback that itself stops incomplete is still no verdict.
  cp "$dir/fallback/codex-x-$run.md" "$dir/fallback/codex-x-$run.attempt-1.out" "$dir/fallback/codex-x-$run.attempts.json" "$dir/fallback-dead/"
  printf 'stop-reason: provider=claude reason=max_tokens subtype=success is_error=0\nGATE: pass\n' > "$dir/fallback-dead/codex-x-$run.attempt-2.out"
  out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/fallback-dead")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "a truncated fallback attempt must not gate (got $rc): $out"

  # The answer cannot open an attempt: a fallback marker printed after a
  # transport max_tokens stop neither erases the stop nor relabels the seat,
  # with or without a controller sidecar.
  printf '# codex review\n\n## Output\n\nmodel-route: class=explicit (explicit) primary=gpt-6-astra fallback=- effort=high\nstop-reason: provider=codex reason=max_tokens subtype=success is_error=0\n\npanel-provider-fallback: provider=claude model=claude-opus-5-5 reason=capacity exit=1\nstop-reason: provider=claude reason=end_turn subtype=success is_error=0\nGATE: pass\n\nmodel-result: selected=gpt-6-astra effort=high fallback_used=0 reason=-\n\n## Exit\n\n0\n' \
    > "$dir/forged/codex-x-$run.md"
  cp "$dir/forged/codex-x-$run.md" "$dir/forged-legacy/"
  printf 'stop-reason: provider=codex reason=max_tokens subtype=success is_error=0\n\npanel-provider-fallback: provider=claude model=claude-opus-5-5 reason=capacity exit=1\nstop-reason: provider=claude reason=end_turn subtype=success is_error=0\nGATE: pass\n' \
    > "$dir/forged/codex-x-$run.attempt-1.out"
  printf '{"attempts": [{"provider": "codex", "model": "gpt-6-astra", "effort": "high", "exit": 0, "stop_reason": "provider=codex reason=max_tokens subtype=success is_error=0", "classification": "", "output": "codex-x-%s.attempt-1.out"}]}\n' \
    "$run" > "$dir/forged/codex-x-$run.attempts.json"
  for case_dir in forged forged-legacy; do
    out="$("$ROOT/scripts/peer-review.sh" verdicts "$dir/$case_dir")" && rc=0 || rc=$?
    [ "$rc" = "2" ] || fail "$case_dir: an answer-authored fallback marker must not erase a max_tokens stop (got $rc): $out"
    contains "$out" 'codex: no-verdict (incomplete answer: provider=codex reason=max_tokens' ||
      fail "$case_dir: the truncated seat keeps its own attribution: $out"
    if printf '%s' "$out" | grep >/dev/null 'claude:'; then
      fail "$case_dir: answer text must not relabel the seat: $out"
    fi
  done
  out="$("$ROOT/scripts/peer-review.sh" verdicts --json "$dir/forged")" || true
  OMS_TEST_JSON="$out" python3 - <<'PY' || fail "forged marker changed the seat attribution: $out"
import json, os
seat = json.loads(os.environ["OMS_TEST_JSON"])["seats"][0]
assert seat["provider"] == "codex" and seat["verdict"] == "no-verdict", seat
assert seat["selected_model"] == "gpt-6-astra" and seat["model_family"] != "anthropic", seat
PY
}

test_review_verdicts_json_mode() {
  local dir="$TMP/verdicts-json"
  local run="20260611T000000Z-43"
  local out
  local rc=0

  mkdir -p "$dir/mixed" "$dir/debate"
  printf '# codex review\n\n## Output\n\nexactly one line: GATE: pass or GATE: fail.\nCONFIDENCE: 0.9\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$dir/mixed/codex-x-$run.md"
  printf '# claude review\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' \
    > "$dir/mixed/claude-x-$run.md"
  printf '# antigravity review\n\n## Output\n\npartial output then death\n' \
    > "$dir/mixed/antigravity-x-$run.md"

  out="$("$ROOT/scripts/peer-review.sh" verdicts --json "$dir/mixed")" && rc=0 || rc=$?
  [ "$rc" = "2" ] || fail "json mode must keep the exit contract, got $rc"
  OMS_TEST_JSON="$out" python3 - <<'PY' || fail "json verdicts wrong: $out"
import json, os
data = json.loads(os.environ["OMS_TEST_JSON"])
seats = {s["provider"]: s for s in data["seats"]}
assert data["overall"] == 2, data
assert seats["codex"]["verdict"] == "pass", seats
assert seats["codex"]["confidence"] == 0.9, seats
assert seats["claude"]["verdict"] == "fail", seats
assert seats["claude"]["confidence"] is None, seats
assert seats["antigravity"]["verdict"] == "incomplete", seats
PY

  # Final-round selection and the -r9 slug guard hold in json mode too.
  printf '# c\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' > "$dir/debate/codex-x-$run.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/codex-x-$run-r2.md"
  printf '# c\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' > "$dir/debate/antigravity-fix-r9-thing-$run.md"
  out="$("$ROOT/scripts/peer-review.sh" verdicts --json "$dir/debate")" || true
  OMS_TEST_JSON="$out" python3 - <<'PY' || fail "json debate selection wrong: $out"
import json, os
data = json.loads(os.environ["OMS_TEST_JSON"])
seats = {s["provider"]: s for s in data["seats"]}
assert seats["codex"]["verdict"] == "pass" and seats["codex"]["round"] == 2, seats
assert seats["antigravity"]["round"] == 0, seats
PY
}

test_job_digest_wait_polls_until_empty() {
  local dir="$TMP/job-digest-wait"
  local bin="$dir/bin"
  mkdir -p "$bin"
  printf 'step 1 ok\n' > "$dir/run.log"

  # Valid log extraction is exercised on the real BSD userland by
  # bsd-portability-smoke. This case owns the argument failures and wait loop.
  if "$ROOT/scripts/job-digest.sh" "$dir/nonexistent" >/dev/null 2>"$dir/error"; then
    fail "digest should reject non-file non-jobid argument"
  fi
  assert_file_contains "$dir/error" 'not a log file or job id'
  if "$ROOT/scripts/job-digest.sh" --wait "$dir/run.log" >/dev/null 2>"$dir/werr"; then
    fail "--wait without a job id should fail"
  fi
  assert_file_contains "$dir/werr" 'requires a slurm job id'

  # Fake squeue: a state file drives queued -> error (retry) -> empty (done).
  printf '0\n' > "$dir/poll"
  # Mirrors real squeue: queued (rc0+row) -> transient controller error
  # (rc1, contact message -> retry) -> completed (rc1, "Invalid job id" -> done).
  cat > "$bin/squeue" <<EOF
#!/usr/bin/env bash
n="\$(cat "$dir/poll")"
printf '%s\n' "\$((n + 1))" > "$dir/poll"
case "\$n" in
  0) echo "  12345 part job R 0:01 1 node"; exit 0 ;;
  1) echo "slurm_load_jobs error: Unable to contact slurm controller" >&2; exit 1 ;;
  2) echo "Invalid user: nobody" >&2; exit 1 ;;
  3) echo "config file not found" >&2; exit 1 ;;
  *) echo "slurm_load_jobs error: Invalid job id specified" >&2; exit 1 ;;
esac
EOF
  chmod +x "$bin/squeue"
  cat > "$bin/sleep" <<EOF
#!/usr/bin/env bash
printf '%s\n' "\$*" >> "$dir/sleep.log"
EOF
  chmod +x "$bin/sleep"

  out="$(OMS_JOB_DIGEST_POLL=0 PATH="$bin:$PATH" "$ROOT/scripts/job-digest.sh" --wait 12345 "$dir/run.log" 2>"$dir/werr")" ||
    fail "--wait digest should succeed once the job leaves the queue"
  contains "$out" '# Job digest' || fail "wait mode should still emit a digest"
  assert_file_contains "$dir/werr" "no longer queued"
  assert_file_contains "$dir/werr" "transiently"
  # Polled 5 times: queued, contact-error, invalid-user, not-found (all retry),
  # then invalid-job-id (done). Non-job errors must not fake completion.
  [ "$(cat "$dir/poll")" -ge 5 ] || fail "wait loop must retry non-job errors and stop only on invalid-job-id"
  assert_file_contains "$dir/werr" "poll 1s"
  assert_file_contains "$dir/sleep.log" "1"

  # --metrics: JSONL and DVCLive tsv, stdlib only, no log required.
  local now old
  now="$(date +%s)"
  old=$((now - 7200))
  {
    printf '{"step": 1, "name": "train/loss", "value": 2.0, "ts": %s}\n' "$old"
    printf '{"step": 2, "name": "train/loss", "value": 1.5, "ts": %s}\n' "$old"
    printf '{"step": 3, "name": "train/loss", "value": 1.0, "ts": %s}\n' "$old"
    printf '{"step": 4, "name": "train/loss", "value": "nan", "ts": %s}\n' "$old"
    printf '{"step": 4, "name": "val/acc", "value": 0.7, "ts": %s}\n' "$old"
    printf 'not json\n'
  } > "$dir/metrics.jsonl"
  out="$("$ROOT/scripts/job-digest.sh" --metrics "$dir/metrics.jsonl")" ||
    fail "metrics-only digest should succeed"
  contains "$out" '## Metrics' || fail "metrics section missing"
  contains "$out" '| train/loss | 4 | 4 | nan | 1 @3 (min) | -0.5 | 1, first @4 |' ||
    fail "loss row wrong: $out"
  contains "$out" '| val/acc | 1 | 4 | 0.7 | 0.7 @4 (max) |' || fail "acc row wrong: $out"
  contains "$out" '1 record(s) skipped' || fail "malformed line not counted"
  contains "$out" '2.0h ago' || fail "last record age missing: $out"
  mkdir -p "$dir/dvc/plots/metrics"
  printf 'timestamp\tstep\tloss\n%s\t0\t3.0\n%s\t1\t2.5\n' "$now" "$now" > "$dir/dvc/plots/metrics/loss.tsv"
  out="$("$ROOT/scripts/job-digest.sh" --metrics "$dir/dvc" "$dir/run.log")" ||
    fail "dvclive digest should succeed"
  contains "$out" '| loss | 2 | 1 | 2.5 | 2.5 @1 (min) |' || fail "tsv row wrong: $out"
  contains "$out" '## Tail' || fail "log sections should remain with --metrics"
  if "$ROOT/scripts/job-digest.sh" --metrics "$dir/none" >/dev/null 2>"$dir/merr"; then
    fail "missing metrics file should fail"
  fi
  assert_file_contains "$dir/merr" 'metrics file not found'
}

test_job_digest_wait_budget_and_byte_cap() {
  local dir="$TMP/job-digest-budget"
  local bin="$dir/bin"
  local out rc size
  mkdir -p "$bin"
  printf 'step 1 ok\n' > "$dir/run.log"

  if "$ROOT/scripts/job-digest.sh" --wait-timeout 5 12345 >/dev/null 2>"$dir/err"; then
    fail "--wait-timeout without --wait should fail"
  fi
  assert_file_contains "$dir/err" 'requires --wait'
  if "$ROOT/scripts/job-digest.sh" --max-bytes 100 "$dir/run.log" >/dev/null 2>"$dir/err"; then
    fail "--max-bytes below the marker reserve should fail"
  fi
  assert_file_contains "$dir/err" 'at least 512'

  # Mock clock: every `date +%s` advances 40s, so a 100s budget is spent after
  # a few polls with no real waiting. Other date calls reach the real binary.
  printf '0\n' > "$dir/clock"
  cat > "$bin/date" <<EOF
#!/usr/bin/env bash
if [ "\${1:-}" = "+%s" ]; then
  n="\$(cat "$dir/clock")"
  printf '%s\n' "\$((n + 40))" > "$dir/clock"
  printf '%s\n' "\$n"
  exit 0
fi
PATH="$PATH" exec date "\$@"
EOF
  # The controller stays down: queue state is unknown, not proof of a queued job.
  cat > "$bin/squeue" <<EOF
#!/usr/bin/env bash
printf 'q\n' >> "$dir/queries"
echo "slurm_load_jobs error: Unable to contact slurm controller" >&2
exit 1
EOF
  cat > "$bin/sleep" <<EOF
#!/usr/bin/env bash
printf '%s\n' "\$*" >> "$dir/sleep.log"
EOF
  # Accounting storage down: a failing sacct must not abort the digest.
  cat > "$bin/sacct" <<'EOF'
#!/usr/bin/env bash
echo "sacct: error: Problem talking to the database" >&2
exit 1
EOF
  printf '#!/usr/bin/env bash\nprintf "%%s\\n" "$*" >> "%s"\n' "$dir/scancel.log" > "$bin/scancel"
  cp "$bin/scancel" "$bin/sbatch"
  chmod +x "$bin/date" "$bin/squeue" "$bin/sleep" "$bin/sacct" "$bin/scancel" "$bin/sbatch"

  set +e
  out="$(OMS_JOB_DIGEST_POLL=60 PATH="$bin:$PATH" "$ROOT/scripts/job-digest.sh" \
    --wait --wait-timeout 100 12345 "$dir/run.log" 2>"$dir/werr")"
  rc=$?
  set -e
  [ "$rc" -eq 124 ] || fail "spent wait budget should exit 124, got $rc"
  contains "$out" 'wait: pending' || fail "pending digest should report an incomplete observation"
  contains "$out" 'outcome unknown, not verified' ||
    fail "failed accounting must read as unknown, not success"
  contains "$out" '## Tail' || fail "failed sacct must not abort the log sections"
  assert_file_contains "$dir/werr" 'queue state may be unknown'
  if contains "$out" 'still queued'; then
    fail "failed queue queries cannot prove that the job is still queued"
  fi
  [ ! -e "$dir/scancel.log" ] || fail "observer timeout must never cancel or resubmit the job"
  # Same failure kind every poll: reported once, then only the total.
  [ "$(grep -c 'transiently' "$dir/werr")" -eq 1 ] || fail "repeated identical query failure should be reported once"
  # 2 where GNU timeout also bounds the query (it reads the clock), else 3.
  grep -Eq 'failed [23] times while waiting' "$dir/werr" || fail "repeated query failures should be totalled once"
  [ "$(wc -l < "$dir/queries" | tr -d ' ')" -ge 2 ] || fail "budgeted wait should re-query after sleeping"
  # The sleep is clipped to the remaining budget instead of overshooting it.
  while read -r slept; do
    [ "$slept" -le 60 ] || fail "sleep $slept exceeded the poll interval"
  done < "$dir/sleep.log"
  [ "$(tail -n 1 "$dir/sleep.log")" -lt 60 ] || fail "last sleep should be clipped to the remaining budget"

  # A scheduler query that never returns must not outlive the budget. Only
  # GNU timeout can preempt it; BSD/macOS bound the sleeps alone (documented).
  if command -v timeout >/dev/null 2>&1 && timeout --version >/dev/null 2>&1; then
    rm -f "$bin/date"
    printf '#!/usr/bin/env bash\nexec "%s" 30\n' "$(command -pv sleep)" > "$bin/squeue"
    SECONDS=0
    set +e
    PATH="$bin:$PATH" "$ROOT/scripts/job-digest.sh" --wait --wait-timeout 1 12345 >/dev/null 2>"$dir/herr"
    rc=$?
    set -e
    [ "$rc" -eq 124 ] || fail "hung scheduler query should end as pending, got $rc"
    [ "$SECONDS" -lt 15 ] || fail "hung scheduler query outlived the wait budget (${SECONDS}s)"
    assert_file_contains "$dir/herr" 'rc=124'

    # The queue can finish promptly while accounting hangs; the same budget
    # must cover both reads, including a scheduler that ignores TERM.
    printf '#!/usr/bin/env bash\nexit 0\n' > "$bin/squeue"
    printf '#!/usr/bin/env bash\ntrap "" TERM\nexec "%s" 30\n' "$(command -pv sleep)" > "$bin/sacct"
    SECONDS=0
    PATH="$bin:$PATH" "$ROOT/scripts/job-digest.sh" --wait --wait-timeout 1 12345 "$dir/run.log" > "$dir/acct-out" 2>"$dir/acct-err" ||
      fail "unknown accounting should still produce a digest"
    [ "$SECONDS" -lt 10 ] || fail "accounting outlived the bounded observation (${SECONDS}s)"
    assert_file_contains "$dir/acct-out" 'outcome unknown, not verified'
    assert_file_contains "$dir/acct-out" '## Tail'
  fi

  # One multi-megabyte UTF-8 line must neither spend the budget nor be cut
  # mid-character; the cap is on whole lines and says what it dropped.
  {
    printf 'ERROR: short cause line\n'
    awk 'BEGIN { for (i = 0; i < 400000; i++) printf "가나다"; printf "\n" }'
    printf '마지막 줄 ok\n'
  } > "$dir/big.log"
  out="$("$ROOT/scripts/job-digest.sh" --max-bytes 2048 "$dir/big.log")" ||
    fail "byte-capped digest should succeed"
  size="$(printf '%s\n' "$out" | wc -c | tr -d ' ')"
  [ "$size" -le 2048 ] || fail "digest exceeded --max-bytes (got $size)"
  contains "$out" 'omitted by --max-bytes 2048' || fail "byte cap should mark the omission"
  contains "$out" 'ERROR: short cause line' || fail "byte cap should keep the short cause line"
  contains "$out" '마지막 줄 ok' || fail "byte cap should keep short lines after the long one"
  if command -v iconv >/dev/null 2>&1; then
    printf '%s\n' "$out" | iconv -f UTF-8 -t UTF-8 >/dev/null 2>&1 ||
      fail "byte-capped digest must stay valid UTF-8"
  fi
  # Without the cap the same digest is unchanged and far over budget.
  size="$("$ROOT/scripts/job-digest.sh" "$dir/big.log" | wc -c | tr -d ' ')"
  [ "$size" -gt 1000000 ] || fail "uncapped digest should keep the long line"
}

# smoke-weight: 3
test_output_digest_keeps_failures_and_exit_code() {
  local dir="$TMP/output-digest" original_dir="$PWD" out rc name raw
  mkdir -p "$dir/repo"
  git -C "$dir/repo" init -q
  cd "$dir/repo"

  # Short output is shown whole, the exit code is the command's, the raw file is kept untouched.
  out="$("$ROOT/scripts/output-digest.sh" -- sh -c 'echo hello; echo "한글 줄" >&2')" ||
    fail "a passing command must pass through the digest"
  contains "$out" 'output-digest: exit=0  lines=2' || fail "digest should report the exit code and line count: $out"
  contains "$out" 'shown: all 2 line(s); nothing omitted' || fail "short output should be shown whole"
  contains "$out" '한글 줄' || fail "stderr and non-ASCII text belong in the capture"
  contains "$out" 'not verification evidence' || fail "the digest must say it is a derived view"
  raw="$(printf '%s\n' "$out" | sed -n 's/^raw: \([^ ]*\)  sha256=.*/\1/p')"
  [ -f "$raw" ] || fail "the raw capture should be kept at the path the digest names: $raw"
  [ "$(cat "$raw")" = "$(printf 'hello\n한글 줄')" ] || fail "the raw capture must be the command's output, unchanged"
  contains "$out" "sha256=$(python3 -c 'import hashlib,sys;print(hashlib.sha256(open(sys.argv[1],"rb").read()).hexdigest())' "$raw")" ||
    fail "the digest should name the raw capture's sha256"

  # A long failing log: the failure line, the line under it, the tail and the exit code
  # survive a small budget; ANSI is stripped from the view; one huge line cannot eat the budget;
  # a capture that ends mid-line says so; what was left out is counted.
  rc=0
  out="$("$ROOT/scripts/output-digest.sh" --max-bytes 900 -- sh -c '
    i=0; while [ "$i" -lt 400 ]; do echo "line $i ok"; i=$((i + 1)); done
    printf "\033[31mFAILED tests/test_a.py::test_x - AssertionError: 값이 다름\033[0m\n"
    echo "  expected 3, got 4"
    i=0; while [ "$i" -lt 60 ]; do echo "after $i"; i=$((i + 1)); done
    awk "BEGIN { for (i = 0; i < 5000; i++) printf \"x\"; printf \"\\n\" }"
    printf "partial tail"; exit 3')" || rc=$?
  [ "$rc" -eq 3 ] || fail "the digest must exit with the command's exit code (got $rc)"
  contains "$out" 'output-digest: exit=3  lines=464' || fail "failing digest should carry exit=3 and the line count: $out"
  contains "$out" '401| FAILED tests/test_a.py::test_x - AssertionError: 값이 다름' ||
    fail "the failure line must survive the budget, without escape codes: $out"
  contains "$out" '402|   expected 3, got 4' || fail "the line under a failure should be kept"
  contains "$out" 'failures: 1 matching line(s) (pytest=1); 1 shown' || fail "failures should be counted by recogniser"
  contains "$out" '464| partial tail' || fail "the tail should be kept"
  contains "$out" 'the capture ends mid-line' || fail "a partial last line should be marked"
  contains "$out" '…[+4700 chars]' || fail "a very long line should be cut and the cut counted"
  contains "$out" 'line(s) omitted' || fail "omitted lines should be marked in place"
  contains "$out" '(failures+tail+head); omitted ' || fail "the digest should say what it left out"
  case "$out" in *$'\033'*) fail "escape codes must not reach the digest" ;; esac
  raw="$(printf '%s\n' "$out" | sed -n 's/^raw: \([^ ]*\)  sha256=.*/\1/p')"
  grep -q "$(printf '\033')" "$raw" || fail "the raw capture keeps the escape codes"
  [ "$(wc -l < "$raw" | tr -d ' ')" -eq 463 ] || fail "the raw capture must hold every line"

  # A failing log no recogniser understands is a raw head and tail, and says so.
  rc=0
  out="$("$ROOT/scripts/output-digest.sh" --max-bytes 400 -- sh -c 'i=1; while [ "$i" -le 300 ]; do echo "$i"; i=$((i + 1)); done; exit 7')" || rc=$?
  [ "$rc" -eq 7 ] || fail "an unrecognised failing log must still exit with the command's code (got $rc)"
  contains "$out" 'no recogniser matched; the lines below are a raw head and tail, not a diagnosis' ||
    fail "an unrecognised failure should fall back to a labelled raw view: $out"
  contains "$out" '300| 300' || fail "the raw fallback should keep the tail"

  # Lines that look like a credential are withheld; the exit code and the raw path are not.
  name="AWS_SEC""RET_ACC""ESS_KEY"
  rc=0
  out="$(VALUE="abcdEFGH1234abcdEFGH1234abcdEFGH1234abcd" NAME="$name" "$ROOT/scripts/output-digest.sh" -- \
    sh -c 'echo "export $NAME=$VALUE"; exit 1' 2>"$dir/secret.err")" || rc=$?
  [ "$rc" -eq 1 ] || fail "a withheld digest must keep the exit code (got $rc)"
  contains "$out" 'shown: nothing; the lines look like they carry a secret' || fail "secret-looking lines should be withheld: $out"
  contains "$out" 'abcdEFGH1234' && fail "the secret-looking value must not be printed"
  contains "$out" 'raw: .oms/artifacts/output-digest/' || fail "a withheld digest still names the raw file"
  assert_file_contains "$dir/secret.err" "the raw capture may carry a secret"

  # --no-store keeps nothing; --file digests an existing capture and runs nothing; a harness child keeps none.
  rm -rf .oms
  out="$("$ROOT/scripts/output-digest.sh" --no-store -- echo once)" || fail "--no-store digest should succeed"
  contains "$out" 'raw: not kept' || fail "--no-store should name no file"
  [ ! -e .oms ] || fail "--no-store must write nothing under .oms"
  out="$(OMS_HARNESS_CHILD=1 "$ROOT/scripts/output-digest.sh" -- echo child)" || fail "a child digest should succeed"
  contains "$out" 'raw: not kept' || fail "a harness child keeps no capture"
  [ ! -e .oms ] || fail "a harness child must write nothing under .oms"
  printf 'ok 1\nFAIL: the thing broke\n' > "$dir/existing.log"
  out="$("$ROOT/scripts/output-digest.sh" --file "$dir/existing.log" --exit-code 2 --json)" ||
    fail "--file should digest an existing capture"
  contains "$out" '"kind": "oms-output-digest"' || fail "--json should carry the kind"
  contains "$out" '"exit_code": 2' || fail "--file --exit-code should be reported"
  contains "$out" '"smoke": 1' || fail "--file should recognise the failure line"
  contains "$out" 'not a tokenizer' || fail "the size estimate must name its method"
  [ ! -e .oms ] || fail "--file must store nothing"

  # Bad requests are refused before anything runs, and retention keeps the newest captures only.
  if "$ROOT/scripts/output-digest.sh" --file "$dir/existing.log" -- echo no >/dev/null 2>&1; then
    fail "--file with a command should be refused"
  fi
  if "$ROOT/scripts/output-digest.sh" --max-bytes 10 -- echo no >/dev/null 2>&1; then
    fail "an out-of-range budget should be refused"
  fi
  mkdir -p .oms/artifacts/output-digest
  local n=0
  while [ "$n" -lt 55 ]; do
    : > ".oms/artifacts/output-digest/20200101T0000$(printf '%02d' "$n")Z-1.log"
    n=$((n + 1))
  done
  : > .oms/artifacts/output-digest/keep-me.txt
  "$ROOT/scripts/output-digest.sh" -- echo newest >/dev/null || fail "digest with a full store should succeed"
  [ "$(find .oms/artifacts/output-digest -name '20*Z-*.log' | wc -l | tr -d ' ')" -eq 50 ] ||
    fail "retention should keep the newest 50 captures"
  [ ! -e .oms/artifacts/output-digest/20200101T000000Z-1.log ] || fail "retention should drop the oldest capture"
  [ -e .oms/artifacts/output-digest/keep-me.txt ] || fail "retention must not touch files it does not own"
  cd "$original_dir"
}


write_fake_tsp() {
  local bin="$1"
  mkdir -p "$bin"
  cat > "$bin/tsp" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
printf '%s\n' "$*" >> "${TSP_STUB_LOG:?}"
case "${1:-}" in
  -S)
    exit 0
    ;;
  -w)
    exit 0
    ;;
  -s)
    printf 'Exit status: %s\n' "${TSP_STUB_EXIT:-0}"
    ;;
  -k)
    exit 0
    ;;
  -r)
    printf 'removed %s\n' "$2"
    ;;
  -c)
    printf 'log for %s\n' "$2"
    ;;
  -C)
    printf 'cleared\n'
    ;;
  -L)
    printf '%s\n' "${TSP_STUB_ID:-41}"
    ;;
  --)
    printf '%s\n' "${TSP_STUB_ID:-41}"
    ;;
  "")
    printf 'ID State Output\n%s finished job\n' "${TSP_STUB_ID:-41}"
    ;;
  *)
    echo "unexpected tsp args: $*" >&2
    exit 2
    ;;
esac
EOF
  chmod +x "$bin/tsp"
}

test_tsp_queue_forwards_basic_subcommands() {
  local dir="$TMP/tsp-forward"
  local bin="$dir/bin"
  local out

  make_committed_repo "$dir"
  write_fake_tsp "$bin"
  out="$(TSP_STUB_LOG="$dir/tsp.log" TSP_STUB_ID=42 \
    OMS_TSP_STATE_DIR="$dir/state" PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/tsp-queue.sh" enqueue --label train-a --slots 1 -- bash -c 'exit 0')"
  [ "$out" = "42" ] || fail "enqueue should print tsp id"
  assert_file_contains "$dir/tsp.log" "-S 1"
  assert_file_contains "$dir/tsp.log" "-L train-a -- bash -c exit 0"

  out="$(TSP_STUB_LOG="$dir/tsp.log" TSP_STUB_ID=77 \
    OMS_TSP_STATE_DIR="$dir/state" PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/tsp-queue.sh" list)"
  contains "$out" '77 finished job' || fail "list should forward to tsp"

  TSP_STUB_LOG="$dir/tsp.log" PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/tsp-queue.sh" cancel 77 >/dev/null
  TSP_STUB_LOG="$dir/tsp.log" PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/tsp-queue.sh" logs 77 >"$dir/logs"
  # cancel must stop a running job (-k), not only drop a queued one (-r).
  assert_file_contains "$dir/tsp.log" "-k 77"
  assert_file_contains "$dir/tsp.log" "-r 77"
  assert_file_contains "$dir/tsp.log" "-c 77"
  assert_file_contains "$dir/logs" "log for 77"

  (cd "$dir" && TSP_STUB_LOG="$dir/tsp.log" TSP_STUB_ID=44 \
    OMS_TSP_STATE_DIR="$dir/state" PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/tsp-queue.sh" enqueue --ledger-note queued-note -- bash -c 'exit 0' >/dev/null)
  (cd "$dir" && TSP_STUB_LOG="$dir/tsp.log" TSP_STUB_ID=44 TSP_STUB_EXIT=0 \
    OMS_TSP_STATE_DIR="$dir/state" PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/tsp-queue.sh" wait 44 >/dev/null)
  assert_file_contains "$dir/docs/EXPERIMENTS.jsonl" '"note": "queued-note"'
  assert_file_contains "$dir/docs/EXPERIMENTS.jsonl" '"cmd": ["bash", "-c", "exit 0"]'
  assert_file_contains "$dir/tsp.log" "-w 44"
  assert_file_contains "$dir/tsp.log" "-s 44"
}

test_harness_child_authority_guards_memory_roles_and_queue() {
  local dir="$TMP/harness-child-authority"
  local project="$dir/project"
  local home_dir="$dir/home"
  local expected="a harness child cannot mutate parent-owned host or global state; return the request to the parent agent"
  local action action_dir explicit_file out rc
  local bin="$dir/bin"

  make_committed_repo "$project"
  mkdir -p "$home_dir"

  # Project-default memory is delegated work state, so children may update it.
  OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" append --agent codex --text "child project memory" >/dev/null ||
    fail "a harness child should be allowed to update project-default memory"
  assert_file_contains "$project/.oms/memory/shared.md" "child project memory"

  # Every global memory mutator is parent-owned and must fail before creating
  # even the isolated global store. Global observation remains available.
  for action in init append pin compact rebuild search recall context; do
    out="$dir/global-$action.out"
    rc=0
    case "$action" in
      append|pin)
        if OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
          --global "$action" --text blocked >"$out" 2>&1; then
          fail "a harness child unexpectedly ran global memory $action"
        else
          rc=$?
        fi
        ;;
      search|recall)
        if OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
          --global "$action" --text blocked >"$out" 2>&1; then
          fail "a harness child unexpectedly ran global memory $action"
        else
          rc=$?
        fi
        ;;
      *)
        if OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
          --global "$action" >"$out" 2>&1; then
          fail "a harness child unexpectedly ran global memory $action"
        else
          rc=$?
        fi
        ;;
    esac
    [ "$rc" = 2 ] || fail "global memory $action should exit 2, got $rc"
    assert_file_contains "$out" "$expected"
  done
  [ ! -e "$home_dir/.oh-my-setting" ] ||
    fail "blocked global memory actions must not create the global store"
  OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --global show >"$dir/global-show.out" ||
    fail "a harness child should retain global memory read access"
  assert_file_contains "$dir/global-show.out" "memory: empty"

  # An explicit file is caller-selected authority even when it sits under the
  # project fixture. Exercise every mutator against a fresh sentinel directory.
  for action in init append pin compact rebuild search recall context; do
    action_dir="$dir/explicit-$action"
    explicit_file="$action_dir/shared.md"
    out="$dir/explicit-$action.out"
    mkdir -p "$action_dir"
    printf 'sentinel\n' > "$explicit_file"
    rc=0
    case "$action" in
      append|pin)
        if OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
          --file "$explicit_file" "$action" --text blocked >"$out" 2>&1; then
          fail "a harness child unexpectedly ran explicit-file memory $action"
        else
          rc=$?
        fi
        ;;
      search|recall)
        if OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
          --file "$explicit_file" "$action" --text blocked >"$out" 2>&1; then
          fail "a harness child unexpectedly ran explicit-file memory $action"
        else
          rc=$?
        fi
        ;;
      *)
        if OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
          --file "$explicit_file" "$action" >"$out" 2>&1; then
          fail "a harness child unexpectedly ran explicit-file memory $action"
        else
          rc=$?
        fi
        ;;
    esac
    [ "$rc" = 2 ] || fail "explicit-file memory $action should exit 2, got $rc"
    assert_file_contains "$out" "$expected"
    [ "$(find "$action_dir" -mindepth 1 -maxdepth 1 | wc -l | tr -d ' ')" = 1 ] ||
      fail "blocked explicit-file memory $action created adjacent state"
    [ "$(cat "$explicit_file")" = sentinel ] ||
      fail "blocked explicit-file memory $action changed the sentinel"
  done
  action_dir="$dir/explicit-full-context"
  explicit_file="$action_dir/shared.md"
  mkdir -p "$action_dir"
  printf 'sentinel\n' > "$explicit_file"
  OMS_HARNESS_CHILD=1 HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --file "$explicit_file" --full context >/dev/null ||
    fail "a child should retain non-compacting explicit-memory context access"
  [ "$(find "$action_dir" -mindepth 1 -maxdepth 1 | wc -l | tr -d ' ')" = 1 ] ||
    fail "full explicit-memory context created adjacent derived state"

  # Role reads and project initialization stay delegated; only global init is
  # parent-owned. The custom role directory keeps the red path off real HOME.
  out="$dir/global-role-init.out"
  rc=0
  if OMS_HARNESS_CHILD=1 OH_MY_SETTING_ROLES_DIR="$dir/global-roles" \
    "$ROOT/scripts/agent-role.sh" --repo "$project" --global \
      --name child-global init >"$out" 2>&1; then
    fail "a harness child unexpectedly initialized a global role"
  else
    rc=$?
  fi
  [ "$rc" = 2 ] || fail "global role init should exit 2, got $rc"
  assert_file_contains "$out" "$expected"
  [ ! -e "$dir/global-roles" ] || fail "blocked global role init created its store"
  [ "$(OMS_HARNESS_CHILD=1 OH_MY_SETTING_ROLES_DIR="$dir/global-roles" \
    "$ROOT/scripts/agent-role.sh" --repo "$project" --global \
      --name readable path)" = "$dir/global-roles/readable.md" ] ||
    fail "a harness child should retain global role read access"
  OMS_HARNESS_CHILD=1 "$ROOT/scripts/agent-role.sh" --repo "$project" \
    --name child-project init >/dev/null ||
    fail "a harness child should be allowed to initialize a project role"
  [ -f "$project/.oms/roles/child-project.md" ] ||
    fail "child project role was not created"

  # Queue mutation is host authority. The fake tsp proves blocked operations
  # never reach a process manager, while list/logs/wait remain observable.
  write_fake_tsp "$bin"
  for action in enqueue cancel; do
    out="$dir/queue-$action.out"
    rc=0
    if [ "$action" = enqueue ]; then
      if OMS_HARNESS_CHILD=1 TSP_STUB_LOG="$dir/blocked-tsp.log" \
        OMS_TSP_STATE_DIR="$dir/blocked-state" PATH="$bin:/usr/bin:/bin" \
        "$ROOT/scripts/tsp-queue.sh" enqueue -- bash -c true >"$out" 2>&1; then
        fail "a harness child unexpectedly enqueued a host job"
      else
        rc=$?
      fi
    else
      if OMS_HARNESS_CHILD=1 TSP_STUB_LOG="$dir/blocked-tsp.log" \
        OMS_TSP_STATE_DIR="$dir/blocked-state" PATH="$bin:/usr/bin:/bin" \
        "$ROOT/scripts/tsp-queue.sh" cancel 88 >"$out" 2>&1; then
        fail "a harness child unexpectedly canceled a host job"
      else
        rc=$?
      fi
    fi
    [ "$rc" = 2 ] || fail "child queue $action should exit 2, got $rc"
    assert_file_contains "$out" "$expected"
  done
  [ ! -e "$dir/blocked-tsp.log" ] || fail "blocked queue actions reached tsp"
  [ ! -e "$dir/blocked-state" ] || fail "blocked queue actions created queue state"

  OMS_HARNESS_CHILD=1 TSP_STUB_LOG="$dir/read-tsp.log" TSP_STUB_ID=88 \
    OMS_TSP_STATE_DIR="$dir/state" PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/tsp-queue.sh" list >"$dir/list.out" ||
    fail "a harness child should be allowed to list host jobs"
  OMS_HARNESS_CHILD=1 TSP_STUB_LOG="$dir/read-tsp.log" \
    OMS_TSP_STATE_DIR="$dir/state" PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/tsp-queue.sh" logs 88 >"$dir/logs.out" ||
    fail "a harness child should be allowed to read host job logs"
  assert_file_contains "$dir/list.out" "88 finished job"
  assert_file_contains "$dir/logs.out" "log for 88"
  (cd "$project" && TSP_STUB_LOG="$dir/read-tsp.log" TSP_STUB_ID=88 \
    OMS_TSP_STATE_DIR="$dir/state" PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/tsp-queue.sh" enqueue --ledger-note child-wait -- bash -c true >/dev/null)
  (cd "$project" && OMS_HARNESS_CHILD=1 TSP_STUB_LOG="$dir/read-tsp.log" \
    TSP_STUB_ID=88 TSP_STUB_EXIT=0 OMS_TSP_STATE_DIR="$dir/state" \
    PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/tsp-queue.sh" wait 88 >/dev/null) ||
    fail "a harness child should be allowed to wait for an existing host job"
  assert_file_contains "$project/docs/EXPERIMENTS.jsonl" '"note": "child-wait"'
}

test_tsp_queue_missing_tsp_fallback_records_ledger() {
