test_experiment_launch_records_registered_run() {
  local project="$TMP/experiment-launch-record"

  make_committed_repo "$project"
  printf '{"val_auc": 0.82, "split": "scaffold"}\n' > "$project/metrics.json"
  (cd "$project" && "$ROOT/scripts/runtime.sh" experiment launch \
    --question "Does warmup improve scaffold validation?" \
    --hypothesis "Warmup 10pct improves val_auc by at least 0.01" \
    --prediction "val_auc increases from 0.80 to 0.81 or higher" \
    --baseline "ledger row baseline-warmup-5pct" \
    --metric "val_auc/scaffold" \
    --success "+0.01 val_auc over baseline" \
    --change "warmup_ratio 0.05 -> 0.10" \
    --metrics metrics.json \
    -- bash -c '"$1" list 1 > during' _ "$ROOT/scripts/run-ledger.sh" >/dev/null 2>"$project/error") ||
    fail "registered research run should launch"

  assert_file_contains "$project/error" "experiment launch: launching registered experiment"
  # The registration was durable while the command ran, and list renders it.
  assert_file_contains "$project/during" "started"
  assert_file_contains "$project/during" "Warmup 10pct improves"
  [ "$(grep -c '"status": "started"' "$project/docs/EXPERIMENTS.jsonl")" = 1 ] ||
    fail "launch must leave exactly one started row before its finished row"
  assert_file_contains "$project/docs/EXPERIMENTS.jsonl" "Warmup 10pct improves"
  assert_file_contains "$project/docs/EXPERIMENTS.jsonl" '"val_auc": 0.82'

  # Readers show a started row as unfinished and fold it into its finished row.
  # (The launched ledger's cmd holds absolute paths, which the digest omits
  # as sensitive, so the digest cases use a hand-built started+finished pair.)
  local seeded="$project/seeded-repo" sha
  make_committed_repo "$seeded"
  mkdir -p "$seeded/docs"
  sha="$(git -C "$seeded" rev-parse --short HEAD)"
  printf '{"ts": "2026-10-19T00:00:00Z", "id": "r1", "cmd": ["true"], "git_sha": "%s", "dirty_hash": "", "exit": null, "duration_s": null, "status": "started"}\n' \
    "$sha" > "$seeded/docs/EXPERIMENTS.jsonl"
  "$ROOT/scripts/agent-ml-context.sh" --repo "$seeded" --force >"$project/digest-started" 2>&1 ||
    fail "agent-ml-context should render a started-only ledger"
  assert_file_contains "$project/digest-started" "started sha="
  if grep -q "exit=None" "$project/digest-started"; then
    fail "digest must show an unfinished started row as started"
  fi
  (cd "$seeded" && "$ROOT/scripts/run-ledger.sh" --no-gate --reason probe -- true >/dev/null 2>"$project/dup-started") || true
  assert_file_contains "$project/dup-started" "identical run already in ledger"
  assert_file_contains "$project/dup-started" "started (unfinished)"
  printf '{"ts": "2026-10-19T00:00:00Z", "id": "r1", "cmd": ["true"], "git_sha": "%s", "dirty_hash": "", "exit": null, "duration_s": null, "status": "started"}\n{"ts": "2026-10-19T00:00:01Z", "id": "r1", "cmd": ["true"], "git_sha": "%s", "dirty_hash": "", "exit": 0, "duration_s": 1, "status": "finished"}\n' \
    "$sha" "$sha" > "$seeded/docs/EXPERIMENTS.jsonl"
  "$ROOT/scripts/agent-ml-context.sh" --repo "$seeded" --force >"$project/digest-done" 2>&1 ||
    fail "agent-ml-context should render a finished ledger"
  [ "$(grep -c 'cmd=true' "$project/digest-done")" = 1 ] ||
    fail "digest must list a finished run once, not as started plus finished"
  assert_file_contains "$project/digest-done" "exit=0 1s"

  # A submission launched inside a job must not record, or hand to
  # run-reconcile, the parent job id (its own id is cluster-qualified: none).
  local bin="$project/bin"
  mkdir -p "$bin"
  printf '#!/bin/sh\necho "Submitted batch job 5 on cluster c1"\n' > "$bin/sbatch"
  printf '#!/bin/sh\nfor a in "$@"; do [ "$p" = -j ] && echo "$a" >> "%s/queried"; p=$a; done\n' "$project" > "$bin/sacct"
  cp "$bin/sacct" "$bin/squeue"
  chmod +x "$bin/sbatch" "$bin/sacct" "$bin/squeue"
  (cd "$project" && SLURM_JOB_ID=9000 PATH="$bin:$PATH" "$ROOT/scripts/runtime.sh" experiment launch \
    --question "Q2" --hypothesis "H2 inside a job" --prediction "P2" --baseline "B2" \
    --metric "m2" --success "S2" --change "C2" \
    -- sbatch job.sh >/dev/null 2>&1) || fail "launched sbatch should succeed"
  assert_file_contains "$project/docs/EXPERIMENTS.jsonl" "H2 inside a job"
  if grep -Fq '9000' "$project/docs/EXPERIMENTS.jsonl"; then
    fail "started and finished rows must not carry the parent SLURM_JOB_ID"
  fi
  (cd "$project" && OMS_SACCT_CMD="$bin/sacct" OMS_SQUEUE_CMD="$bin/squeue" \
    "$ROOT/scripts/run-reconcile.sh" scan --ledger "$project/docs/EXPERIMENTS.jsonl" >/dev/null 2>&1) || true
  if [ -e "$project/queried" ] && grep -Fq 9000 "$project/queried"; then
    fail "run-reconcile must not track the parent job id"
  fi
}

test_experiment_launch_dry_run_no_ledger() {
  local project="$TMP/experiment-launch-dry"

  make_committed_repo "$project"
  (cd "$project" && "$ROOT/scripts/runtime.sh" experiment launch \
    --question "Does batch size help?" \
    --hypothesis "Batch size 64 improves val_loss" \
    --prediction "val_loss decreases by at least 0.02" \
    --baseline "current best config" \
    --metric "val_loss/random" \
    --success "-0.02 val_loss" \
    --change "batch_size 32 -> 64" \
    --dry-run \
    -- bash -c 'exit 0' >"$project/out") ||
