  assert_file_contains "$project/out" "experiment launch: dry-run"
  assert_file_contains "$project/out" "Batch size 64 improves val_loss"
  assert_not_exists "$project/docs/EXPERIMENTS.jsonl"
}

test_run_ledger_metrics_sanitizes() {
  local project="$TMP/run-ledger-metrics-clean"
  make_committed_repo "$project"
  local ledger="$project/docs/EXPERIMENTS.jsonl"

  # NaN/Infinity must be dropped so the row stays RFC-valid JSON.
  printf '{"good": 0.5, "bad": NaN, "worse": Infinity}\n' > "$project/m1.json"
  (cd "$project" && "$ROOT/scripts/run-ledger.sh" --metrics m1.json -- bash -c 'exit 0' >/dev/null 2>&1) ||
    fail "nan/inf metrics run should still succeed"
  tail -n1 "$ledger" | python3 -c 'import json,sys; json.loads(sys.stdin.read())' ||
    fail "ledger row with nan/inf source must remain valid JSON"
  tail -n1 "$ledger" | grep -F '"good": 0.5' > /dev/null || fail "finite metric should survive"
  if tail -n1 "$ledger" | grep -E 'NaN|Infinity' > /dev/null; then
    fail "non-finite floats must be dropped"
  fi

  # Control chars in string values must be stripped (no row-splitting).
  printf '{"label": "a\\nb\\tc"}\n' > "$project/m2.json"
  (cd "$project" && "$ROOT/scripts/run-ledger.sh" --metrics m2.json -- bash -c 'exit 0' >/dev/null 2>&1) ||
    fail "control-char metrics run should succeed"
  [ "$(wc -l < "$ledger")" = "2" ] || fail "control chars must not split the ledger row"

  # Sensitive-looking metric values must keep the row but drop metrics.
  printf '{"path": "%s/u/secret.pt"}\n' "/hom""e" > "$project/m3.json"
  (cd "$project" && "$ROOT/scripts/run-ledger.sh" --metrics m3.json -- bash -c 'exit 0' >/dev/null 2>"$project/serr") ||
    fail "sensitive metrics run should still record the row"
  assert_file_contains "$project/serr" "sensitive-looking"
  [ "$(wc -l < "$ledger")" = "3" ] || fail "row should still be recorded without metrics"
  if tail -n1 "$ledger" | grep -F 'secret.pt' > /dev/null; then
    fail "sensitive metric value must not reach the git-tracked ledger"
  fi

  # Oversized metrics file is skipped, row still recorded.
  OMS_METRICS_MAX_BYTES=64 sh -c "printf '{\"k\": \"%s\"}\n' \"\$(head -c 200 < /dev/zero | tr '\\0' x)\"" > "$project/m4.json"
  (cd "$project" && OMS_METRICS_MAX_BYTES=64 "$ROOT/scripts/run-ledger.sh" --metrics m4.json -- bash -c 'exit 0' >/dev/null 2>"$project/oerr") ||
    fail "oversized metrics run should still record the row"
  assert_file_contains "$project/oerr" "exceeds"

  # Top-level JSON array (non-object) ignored, row recorded.
  printf '[1, 2, 3]\n' > "$project/m5.json"
  (cd "$project" && "$ROOT/scripts/run-ledger.sh" --metrics m5.json -- bash -c 'exit 0' >/dev/null 2>"$project/aerr") ||
    fail "array metrics run should still record the row"
  assert_file_contains "$project/aerr" "not a JSON object"
}

# smoke-weight: 17
test_delegate_auto_verify_uses_check_contract() {
  local project="$TMP/delegate-auto-verify"
  local artifact_dir="$project/artifacts"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local out

  make_committed_repo "$project"
  mkdir -p "$project/scripts" "$bin_dir" "$home_dir"
  printf '#!/usr/bin/env bash\ncase "$1" in fast) echo check-contract-ran ;; *) exit 2 ;; esac\n' > "$project/scripts/check.sh"
  chmod +x "$project/scripts/check.sh"
  git -C "$project" add scripts/check.sh
  git -C "$project" -c user.email=t@e.c -c user.name=T commit -qm check

  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
echo "worker done"
EOF

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --allow-no-change \
    --prompt "Auto verify run" >/dev/null

  assert_one_artifact_contains "$artifact_dir" 'codex-auto-verify-run-*.md' 'check-contract-ran'

  git -C "$project" rm -q scripts/check.sh
  printf '## Commands\n- Test: false\n## Verification\n- Required checks: `bash tests/run.sh`\r\n' > "$project/PROJECT.md"
  git -C "$project" add PROJECT.md
  git -C "$project" -c user.email=t@e.c -c user.name=T commit -qm declared-check
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$artifact_dir" --allow-no-change --prompt 'Declared hint' 2>&1)"
  contains "$out" 'no automatic verifier selected; suggested: --verify bash\ tests/run.sh' || fail "missing declared hint: $out"
  artifact="$(printf '%s\n' "$out" | sed -n 's/^artifact: //p')"
  if grep -Fq '## Verify' "$artifact"; then fail 'suggested command ran'; fi
  printf '## Verification\n- Required checks: TODO\n' > "$project/PROJECT.md"
  git -C "$project" add PROJECT.md
  git -C "$project" -c user.email=t@e.c -c user.name=T commit -qm no-declared-check
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$artifact_dir" --allow-no-change --prompt 'Generic hint' 2>&1)"
  contains "$out" 'no automatic verifier selected; pass --verify CMD or --no-verify' || fail "missing generic hint: $out"
  mkdir -p "$project/scripts"
  printf '#!/usr/bin/env bash\ncase "$1" in fast) echo check-contract-ran ;; *) exit 2 ;; esac\n' > "$project/scripts/check.sh"
  chmod +x "$project/scripts/check.sh"
  git -C "$project" add scripts/check.sh
  git -C "$project" -c user.email=t@e.c -c user.name=T commit -qm restore-check

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --no-verify \
    --allow-no-change \
    --prompt "No verify run" >/dev/null

  artifact="$(find "$artifact_dir" -type f -name 'codex-no-verify-run-*.md' | sed -n '1p')"
  [ -n "$artifact" ] || fail "missing no-verify artifact"
  if grep -Fq '## Verify' "$artifact"; then
    fail "--no-verify should skip verification section"
  fi

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$artifact_dir" --read-only --prompt 'Read only report' 2>"$project/read-only-clean.err")"
  contains "$out" 'worker: codex exit 0' || fail "unchanged read-only worker did not succeed: $out"
  if grep -Fq 'read-only worker changed files:' "$project/read-only-clean.err"; then
    fail "unchanged read-only worker emitted a write violation"
  fi
  artifact="$(find "$artifact_dir" -type f -name 'codex-read-only-report-*.md' | sed -n '1p')"
  [ -n "$artifact" ] || fail "missing read-only report"
  if grep -Fq '## Verify' "$artifact"; then
    fail "read-only report must not automatically run project tests"
  fi

  "$ROOT/scripts/agent-task.sh" --repo "$project" init \
    --goal 'Detect read-only worker writes' --next 'Inspect worker report' >/dev/null
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) echo 'codex 1.0'; exit 0 ;; esac
cat >/dev/null
if [ "${READ_ONLY_REPAIR_PROBE:-0}" = 1 ] && [ ! -f "$HOME/read-only-first-round" ]; then
  touch "$HOME/read-only-first-round"
  echo 'temporary fixture failure'
  exit 1
fi
printf 'unauthorized change\n' > unauthorized.txt
if [ "${READ_ONLY_MANY_PATHS:-0}" = 1 ]; then
  for n in {1..21}; do
    printf -v name 'changed-%02d.txt' "$n"
    printf 'unauthorized change\n' > "$name"
  done
fi
echo 'worker done'
EOF
  local probe rc patch warning
  for probe in initial repair bounded; do
    rc=0
    out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      READ_ONLY_REPAIR_PROBE="$([ "$probe" != repair ] || printf 1)" \
      READ_ONLY_MANY_PATHS="$([ "$probe" != bounded ] || printf 1)" \
      "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
      --artifact-dir "$artifact_dir" --read-only --repair 1 \
      --prompt "Read only violation $probe" 2>"$project/read-only.err")" || rc=$?
    [ "$rc" = 1 ] || fail "read-only writes must fail ($probe): $out"
    contains "$out" 'worker: codex exit 125' || fail "read-only writes lost authority failure status: $out"
    if contains "$out" 'patch-land'; then fail "read-only violation suggested landing: $out"; fi
    artifact="$(printf '%s\n' "$out" | sed -n 's/^artifact: //p')"
    patch="$(printf '%s\n' "$out" | sed -n 's/^patch: //p')"
    [ "$patch" = 'none (read-only)' ] || fail "read-only violation exposed a patch: $patch"
    if find "$artifact_dir" -type f -name '*.patch' | grep -F "read-only-violation-$probe-" > /dev/null; then
      fail "read-only violation created a patch artifact"
    fi
    [ "$(grep -c '^read-only worker changed files: ' "$project/read-only.err")" = 1 ] ||
      fail "read-only violation must emit exactly one warning"
    warning="$(sed -n '/^read-only worker changed files: /p' "$project/read-only.err")"
    if [ "$probe" = bounded ]; then
      contains "$warning" 'changed-20.txt ... (+2 more)' || fail "changed path list is not bounded: $warning"
      if contains "$warning" 'changed-21.txt'; then fail "changed path list exceeded its cap: $warning"; fi
    else
      [ "$warning" = 'read-only worker changed files: unauthorized.txt' ] ||
        fail "read-only warning did not name the changed path: $warning"
    fi
    assert_file_contains "$artifact" "$warning"
    if [ "$probe" = repair ]; then
      contains "$out" 'repair: 1/1 round(s) used' || fail "repair write was not inspected: $out"
    else
      contains "$out" 'repair: 0/1 round(s) used' || fail "authority violation was retried: $out"
    fi
    assert_file_contains "$project/.oms/task/current.md" 'peer-delegate codex exit=1'
    assert_file_contains "$project/.oms/task/current.md" 'worker=codex exit 125'
    python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "read-only failure receipt missing"
import json, pathlib, sys
row = json.loads(pathlib.Path(sys.argv[1]).read_text().splitlines()[-1])
assert row['kind'] == 'delegate' and row['exit'] == 1, row
assert not row.get('patch'), row
PY
  done

  printf '#!/usr/bin/env bash\necho unbounded-check\n' > "$project/scripts/check.sh"
  git -C "$project" add scripts/check.sh
  git -C "$project" -c user.email=t@e.c -c user.name=T commit -qm unbounded-check
  printf '#!/usr/bin/env bash\necho worker-started >&2\nexit 91\n' > "$bin_dir/codex"
  if out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$artifact_dir" --prompt 'Unknown check mode' 2>&1)"; then
    fail "unbounded default verification must not launch"
  fi
  contains "$out" 'no bounded fast mode' || fail "missing actionable verification error: $out"
  if contains "$out" worker-started; then
    fail "worker launched before resolving the verification command"
  fi
}

test_project_doctor_checks_subdirectory_loaders() {
  local project="$TMP/doctor-sub-tier"
  local out
  mkdir -p "$project"

  "$ROOT/scripts/apply-project-template.sh" general "$project" >/dev/null
  # A tier-3 loader for one CLI only: Claude follows rules in sub/ that
  # Codex and Antigravity never see — the divergence the doctor exists to
  # catch, previously invisible below the root.
  "$ROOT/scripts/apply-project-template.sh" general "$project" sub/CLAUDE.md >/dev/null
  if out="$("$ROOT/scripts/project-doctor.sh" "$project")"; then
    fail "a one-CLI subdirectory loader must fail the doctor: $out"
  fi
  contains "$out" 'sub: general block missing in AGENTS.md' ||
    fail "the doctor must name the missing sibling: $out"

  "$ROOT/scripts/apply-project-template.sh" general "$project" sub/AGENTS.md sub/CLAUDE.md >/dev/null
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" ||
    fail "a paired subdirectory loader should pass: $out"
  contains "$out" 'sub: general block matches current template' ||
    fail "the doctor should confirm sub-tier freshness: $out"

  printf 'Unmanaged agy notes.\n' > "$project/sub/GEMINI.md"
  if out="$("$ROOT/scripts/project-doctor.sh" "$project")"; then
    fail "an existing nested GEMINI without the style must fail: $out"
  fi
  contains "$out" 'sub: general block missing in GEMINI.md' ||
    fail "doctor must report a style missing from nested GEMINI: $out"

  sed 's/Project rules override global defaults./Conflicting but marked rule./' \
    "$project/sub/AGENTS.md" > "$project/sub/GEMINI.md"
  if out="$("$ROOT/scripts/project-doctor.sh" "$project")"; then
    fail "matching markers must not hide a conflicting nested GEMINI body: $out"
  fi
  contains "$out" 'sub: general block differs between AGENTS.md and GEMINI.md' ||
    fail "doctor must report nested GEMINI body conflicts: $out"

  # --budget: what each CLI always loads for this project, read as text. The
  # home is a fixture so the report sees only what the test planted.
  local budget="$TMP/doctor-budget" budget_home="$TMP/doctor-budget-home" hop
  local shared='Always run the focused check before you say a change is done and name the command you ran in the report'
  mkdir -p "$budget/notes" "$budget_home/.claude" "$budget_home/.codex" "$budget_home/.gemini"
  printf '# Global\n\n%s.\n' "$shared" > "$budget_home/.claude/CLAUDE.md"
  cp "$budget_home/.claude/CLAUDE.md" "$budget_home/.codex/AGENTS.md"
  printf '# Project\n\n- %s.\n\nShort line.\n' "$shared" > "$budget/AGENTS.md"
  out="$(HOME="$budget_home" CODEX_HOME="$budget_home/.codex" "$ROOT/scripts/project-doctor.sh" --budget --strict "$budget")" && fail "a paragraph loaded twice must fail --budget --strict: $out"
  contains "$out" 'codex: 2 file(s)' || fail "budget must list the global and project files Codex loads: $out"
  contains "$out" 'warn: the same 21-word paragraph is loaded from ~/.codex/AGENTS.md and AGENTS.md' ||
    fail "budget must name a paragraph one provider loads twice, list marker or not: $out"
  contains "$out" 'antigravity: 1 file(s)' || fail "budget must not invent a global file that is absent: $out"
  HOME="$budget_home" CODEX_HOME="$budget_home/.codex" "$ROOT/scripts/project-doctor.sh" --budget "$budget" >/dev/null ||
    fail "budget findings are warnings: without --strict the report exits 0"

  # A CLAUDE.md shadows AGENTS.md for Claude unless it imports it; imports are followed four hops and no further,
  # and an @path inside a code span or fence is not an import.
  {
    printf '# Claude\n\n@notes/h1.md\n\n`@notes/span.md`\n\n'
    printf '%s\n' '```' '@notes/fence.md' '```'
  } > "$budget/CLAUDE.md"
  for hop in 1 2 3 4 5; do printf 'hop %s\n\n@h%s.md\n' "$hop" "$((hop + 1))" > "$budget/notes/h$hop.md"; done
  printf 'never loaded\n' > "$budget/notes/h6.md"
  printf 'span\n' > "$budget/notes/span.md"
  printf 'fence\n' > "$budget/notes/fence.md"
  out="$(HOME="$budget_home" CODEX_HOME="$budget_home/.codex" OMS_RULES_MAX_LINES=4 "$ROOT/scripts/project-doctor.sh" --budget "$budget")" ||
    fail "budget should report, not fail: $out"
  contains "$out" 'warn: AGENTS.md is not read: Claude Code reads AGENTS.md only when no CLAUDE.md is present, and CLAUDE.md is' ||
    fail "budget must say Claude skips a shadowed AGENTS.md: $out"
  contains "$out" 'notes/h4.md  (imported by notes/h3.md)' || fail "budget must follow imports four hops: $out"
  contains "$out" 'warn: notes/h4.md imports notes/h5.md past 4 hops; Claude does not follow it' ||
    fail "budget must stop at the fourth hop and say so: $out"
  case "$out" in *'notes/span.md'*|*'notes/fence.md'*|*'l  notes/h5.md'*) fail "code spans, fences and a fifth hop are not loaded: $out" ;; esac
  contains "$out" 'warn: CLAUDE.md has 9 lines, over the 4-line budget' || fail "budget must apply the line limit: $out"
  ! "$ROOT/scripts/project-doctor.sh" --budget --contract "$budget" >/dev/null 2>&1 || fail "--budget must refuse --contract"
  ! "$ROOT/scripts/project-doctor.sh" --team --budget "$budget" >/dev/null 2>&1 || fail "--team must refuse --budget"
  printf '@AGENTS.md\n' > "$budget/CLAUDE.md"
  out="$(HOME="$budget_home" CODEX_HOME="$budget_home/.codex" "$ROOT/scripts/project-doctor.sh" --budget --json "$budget")" || fail "budget --json should exit 0"
  printf '%s' "$out" | python3 -c '
import json, sys
report = json.load(sys.stdin)
claude = next(row for row in report["providers"] if row["provider"] == "claude")
assert report["kind"] == "oms-instruction-budget" and report["schema"] == 1, report
assert not claude["shadowed"], claude
assert [f["path"] for f in claude["files"]] == ["~/.claude/CLAUDE.md", "CLAUDE.md", "AGENTS.md"], claude["files"]
assert all("text" not in f for f in claude["files"]), "file contents must not be in the report"
' || fail "budget --json must list an imported AGENTS.md as loaded and carry no file text"
  if "$ROOT/scripts/project-doctor.sh" --json "$budget" >/dev/null 2>&1; then
    fail "--json without --budget must be refused"
  fi

  # --prompts audits shipped prompt text: injection class comes from the delivering script's marker,
  # a sentence carried by two always-injected files and an over-emphasis phrase are findings.
  local src="$TMP/prompt-audit-src" dup='Run the focused check before you say a change is done and name it in the report'
  mkdir -p "$src/rules" "$src/roles" "$src/templates" "$src/config" "$src/scripts" "$src/custom-skills/oms-x"
  printf '%s\n' 'rules/global-AGENTS.md $HOME/.claude/CLAUDE.md $HOME/.codex/AGENTS.md' > "$src/scripts/link.sh"
  printf '%s\n' 'templates/project-' > "$src/scripts/apply-project-template.sh"
  printf '%s\n' 'injected into a delegated worker brief' > "$src/scripts/agent-role.sh"
  printf '# Rules\n\n- %s.\n- Please double-check everything twice.\n' "$dup" > "$src/rules/global-AGENTS.md"
  printf '# Project\n\n%s.\n' "$dup" > "$src/templates/project-general-AGENTS.md"
  printf '# Role\n\n%s.\n' "$dup" > "$src/roles/r.md"
  printf '# Skill\n' > "$src/custom-skills/oms-x/SKILL.md"
  printf '%s\n' '# comment' '\bdouble[- ]check\b' > "$src/config/prompt-audit-patterns.txt"
  out="$("$ROOT/scripts/project-doctor.sh" --prompts "$src")" || fail "prompt audit is advisory and must exit 0: $out"
  contains "$out" 'always ' || fail "prompt audit must list injected files: $out"
  contains "$out" 'on-demand' && contains "$out" 'roles/r.md' || fail "a role is on demand: $out"
  contains "$out" 'unknown' && contains "$out" 'custom-skills/oms-x/SKILL.md' || fail "a skill with no delivery marker is unknown: $out"
  contains "$out" 'rules/global-AGENTS.md: 1 line(s) match emphasis pattern' || fail "prompt audit must flag the listed phrase: $out"
  contains "$out" 'in 2 always-injected files (rules/global-AGENTS.md, templates/project-general-AGENTS.md)' ||
    fail "prompt audit must name a sentence two always-injected files carry, not the on-demand role: $out"
  contains "$out" 'claude: 25 always-injected words' || fail "prompt audit must total global words per provider: $out"
  contains "$out" 'antigravity: always-injected words unknown' || fail "a provider with no delivery marker is unknown: $out"
  "$ROOT/scripts/project-doctor.sh" --prompts --strict "$src" >/dev/null 2>&1 && fail "--prompts --strict must fail on findings"
  "$ROOT/scripts/project-doctor.sh" --prompts --json "$src" | python3 -c '
import json, sys
report = json.load(sys.stdin)
assert report["kind"] == "oms-prompt-audit" and report["findings"] == 2, report
assert [f["injection"] for f in report["files"]][:2] == ["always", "on-demand"], report["files"]
' || fail "prompt audit --json must carry classes and the finding count"
  ! "$ROOT/scripts/project-doctor.sh" --prompts --budget "$src" >/dev/null 2>&1 || fail "--prompts must refuse --budget"
}

test_project_doctor_detects_gemini_body_drift() {
  local project="$TMP/doctor-gemini-drift"
  local out name
  mkdir -p "$project"
  "$ROOT/scripts/apply-project-template.sh" general "$project" >/dev/null
  cp "$project/AGENTS.md" "$project/GEMINI.md"
  sed -i 's/Project rules override global defaults./Conflicting but marked rule./' \
    "$project/GEMINI.md"
  if out="$("$ROOT/scripts/project-doctor.sh" "$project")"; then
    fail "matching markers must not hide a conflicting root GEMINI body: $out"
  fi
  contains "$out" 'general block differs between AGENTS.md and GEMINI.md' ||
    fail "doctor must report root GEMINI body conflicts: $out"

  "$ROOT/scripts/apply-project-template.sh" ml "$project" GEMINI.md >/dev/null
  if out="$("$ROOT/scripts/project-doctor.sh" "$project")"; then
    fail "root GEMINI carrying a different style must fail parity: $out"
  fi
  for name in AGENTS.md CLAUDE.md; do
    contains "$out" "ml block missing in $name" ||
      fail "doctor must report the missing $name counterpart: $out"
  done
  contains "$out" 'general block missing in GEMINI.md' ||
    fail "doctor must report the missing GEMINI style counterpart: $out"

  rm "$project/AGENTS.md" "$project/CLAUDE.md"
  if out="$("$ROOT/scripts/project-doctor.sh" "$project")"; then
    fail "a root GEMINI-only loader must fail parity: $out"
  fi
  contains "$out" 'ml block missing in AGENTS.md' ||
    fail "GEMINI-only style must be discovered: $out"
}

test_project_doctor_detects_drift() {
  local project="$TMP/doctor-drift"
  mkdir -p "$project"

  "$ROOT/scripts/apply-project-template.sh" general "$project" >/dev/null
  sed -i 's/Project rules override global defaults./TAMPERED/' "$project/CLAUDE.md"

  if out="$("$ROOT/scripts/project-doctor.sh" "$project")"; then
    fail "project-doctor should fail on drifted CLAUDE.md block"
