# smoke-weight: 6
test_doctor_warns_when_antigravity_cannot_read_in_headless_mode() {
  local project="$TMP/doctor-agy-perms"
  local home_dir="$TMP/doctor-home-agy-perms"
  local bin_dir="$TMP/doctor-agy-perms-bin"
  local out

  setup_doctor_home "$home_dir"
  mkdir -p "$project" "$bin_dir"
  printf '#!/bin/sh\nexit 0\n' > "$bin_dir/agy"
  chmod +x "$bin_dir/agy"
  # Headless antigravity cannot prompt, so a command outside permissions.allow
  # is auto-denied and the call returns nothing. A curated list is not enough:
  # the rule is matched against the whole command line, so the first chained
  # command a peer runs is denied. Discovering that from an empty council costs
  # a full provider call; the config says it for free.
  cat > "$home_dir/.gemini/antigravity-cli/settings.json" <<'JSON'
{
  "permissions": {
    "allow": ["command(ls)", "command(git status)", "read_file(*)"]
  }
}
JSON

  out="$(cd "$project" && HOME="$home_dir" PATH="$bin_dir:$PATH" \
    XDG_RUNTIME_DIR="$home_dir/runtime" OH_MY_SETTING_REQUIRE_TOOLS=0 \
    OH_MY_SETTING_CODEX_PLUGIN=0 "$ROOT/scripts/doctor.sh")" ||
    fail "a narrow antigravity allow-list is a warning, not a failure: $out"
  contains "$out" 'warn: antigravity will be denied these headlessly' ||
    fail "the doctor should name the missing permissions: $out"
  contains "$out" 'command(*)' ||
    fail "a curated command list does not survive a chained command: $out"
  contains "$out" 'permissions.allow' ||
    fail "the warning should say where to fix it: $out"
  # Shell access is not enough: reading a file is a separate permission, and a
  # config that grants every command but no read_file still answers nothing.
  cat > "$home_dir/.gemini/antigravity-cli/settings.json" <<'JSON'
{
  "permissions": {
    "allow": ["command(*)"]
  }
}
JSON
  out="$(cd "$project" && HOME="$home_dir" PATH="$bin_dir:$PATH" \
    XDG_RUNTIME_DIR="$home_dir/runtime" OH_MY_SETTING_REQUIRE_TOOLS=0 \
    OH_MY_SETTING_CODEX_PLUGIN=0 "$ROOT/scripts/doctor.sh")" ||
    fail "a missing read_file rule is a warning, not a failure: $out"
  contains "$out" 'read_file' ||
    fail "the doctor should name the missing file-read permission: $out"

  # --extensions: the same homes read as an inventory. Files are parsed, never
  # run: a server command that would leave a marker must leave none, and no
  # argument, environment value, header or URL path may reach the report.
  local ext_marker="$TMP/doctor-extensions-ran" ext_word="fixture-private-value"
  # Built in pieces: a URL with userinfo in one literal reads as a credential to the outbound scrubber.
  local ext_url="https://user"
  ext_url+=":$ext_word"
  ext_url+="@mcp.example.test/path/$ext_word?k=$ext_word"
  cat > "$home_dir/.claude.json" <<JSON
{"mcpServers": {
  "oh-my-setting": {"command": "bash", "args": ["$ROOT/scripts/mcp-server.sh"]},
  "notes": {"command": "/opt/tools/notes-server --flag $ext_word", "args": ["--run", "touch $ext_marker"],
            "env": {"NOTES_AUTH": "$ext_word"}},
  "remote": {"type": "http", "url": "$ext_url",
             "headers": {"Authorization": "$ext_word"}}},
 "projects": {"$(cd "$project" && pwd -P)": {"mcpServers": {"local-only": {"command": "node"}}}}}
JSON
  printf '{"mcpServers": {"team": {"command": "uvx"}}}\n' > "$project/.mcp.json"
  mkdir -p "$home_dir/.claude" "$home_dir/.codex" "$home_dir/.gemini/config/plugins/oh-my-setting" \
    "$home_dir/.gemini/extensions/helper"
  printf '{"enabledPlugins": {"oh-my-setting@local": true, "formatter@market": false}}\n' > "$home_dir/.claude/settings.json"
  printf '[mcp_servers.oh-my-setting]\ncommand = "bash"\n\n[mcp_servers.notes]\ncommand = "python3"\nargs = ["%s"]\n' \
    "$ext_word" > "$home_dir/.codex/config.toml"
  printf '{"mcpServers": {"oh-my-setting": {"command": "bash"}}}\n' \
    > "$home_dir/.gemini/config/plugins/oh-my-setting/mcp_config.json"
  out="$(cd "$project" && HOME="$home_dir" CODEX_HOME="$home_dir/.codex" "$ROOT/scripts/doctor.sh" --extensions)" ||
    fail "the extension inventory is findings only and exits 0: $out"
  [ ! -e "$ext_marker" ] || fail "the inventory must not run anything a configuration names"
  case "$out" in *"$ext_word"*|*"touch"*|*"/path/"*|*"Authorization"*|*"NOTES_AUTH"*)
    fail "arguments, environment, headers and URL paths must stay out of the inventory: $out" ;; esac
  contains "$out" 'claude: 5 server(s), 2 plugin(s)' || fail "inventory must count user, local and project servers: $out"
  contains "$out" 'https://mcp.example.test' || fail "a URL server is shown by scheme and host only: $out"
  printf '%s\n' "$out" | grep -Eq 'server notes +stdio +user +notes-server  \[1 env name\(s\)\]' ||
    fail "a stdio server is shown by its command base name and env count: $out"
  printf '%s\n' "$out" | grep -Eq 'server oh-my-setting .*\[oms\]' || fail "the OMS server must be marked as owned: $out"
  printf '%s\n' "$out" | grep -Eq 'plugin formatter@market +user  \[disabled\]' || fail "a disabled plugin is listed as disabled: $out"
  contains "$out" 'plugin helper' || fail "an Antigravity extension directory is listed by name: $out"
  contains "$out" 'note: server notes is configured for claude, codex but not for antigravity' ||
    fail "a server one CLI lacks must be noted: $out"
  contains "$out" 'note: server notes points at different targets: notes-server, python3' ||
    fail "one name with two targets must be noted: $out"
  printf '[mcp_servers.broken\n' > "$home_dir/.codex/config.toml"
  out="$(cd "$project" && HOME="$home_dir" CODEX_HOME="$home_dir/.codex" "$ROOT/scripts/doctor.sh" --extensions --json)" ||
    fail "an unparsable file is unread, not a failure"
  printf '%s' "$out" | python3 -c '
import json, sys
report = json.load(sys.stdin)
codex = next(row for row in report["providers"] if row["provider"] == "codex")
assert report["kind"] == "oms-extension-inventory" and report["unread"] == 1, report
assert codex["sources"][0]["status"] == "unread" and codex["servers"] == [], codex
assert not any("codex" in item.get("missing", []) for item in report["mismatches"]), report["mismatches"]
' || fail "an unread Codex config must be unknown: not empty, and not compared: $out"
  if (cd "$project" && HOME="$home_dir" "$ROOT/scripts/doctor.sh" --extensions --repair) >/dev/null 2>&1; then
    fail "--extensions must refuse to run with --repair"
  fi
  if (cd "$project" && HOME="$home_dir" "$ROOT/scripts/doctor.sh" --extensions --security) >/dev/null 2>&1; then
    fail "--extensions must refuse to run with --security"
  fi

  # --mcp: launch shapes are pinned in a private file; nothing is written without --pin.
  local pins="$TMP/doctor-mcp-pins.json"
  cat > "$home_dir/.claude.json" <<JSON
{"mcpServers": {
  "fetcher": {"command": "npx", "args": ["-y", "some-mcp"], "env": {"FETCH_VAR": "$ext_word"}},
  "plain": {"url": "http://mcp.example.test/x"},
  "fixed": {"command": "npx", "args": ["-y", "@scope/pkg@1.2.3"]}}}
JSON
  : > "$home_dir/.codex/config.toml"
  out="$(cd "$project" && HOME="$home_dir" CODEX_HOME="$home_dir/.codex" OMS_MCP_PIN_FILE="$pins" "$ROOT/scripts/doctor.sh" --mcp)" ||
    fail "the pin report exits 0: $out"
  [ ! -e "$pins" ] || fail "--mcp without --pin must not write a pin file"
  contains "$out" 'no baseline recorded' || fail "a missing baseline must be said: $out"
  contains "$out" 'warn: claude:user:fetcher: npx runs a package with no pinned version' || fail "unpinned npx must warn: $out"
  contains "$out" 'warn: claude:user:plain: plain http to a non-loopback host' || fail "plain http must warn: $out"
  case "$out" in *"claude:user:fixed: npx"*|*"$ext_word"*) fail "a versioned package must not warn and values must not print: $out" ;; esac
  (cd "$project" && HOME="$home_dir" CODEX_HOME="$home_dir/.codex" OMS_MCP_PIN_FILE="$pins" "$ROOT/scripts/doctor.sh" --mcp --pin) >/dev/null ||
    fail "--pin should record"
  [ "$(stat -c '%a' "$pins" 2>/dev/null || stat -f '%Lp' "$pins")" = 600 ] || fail "the pin file must be private"
  grep -F "$ext_word" "$pins" >/dev/null && fail "no environment value may reach the pin file"
  cat > "$home_dir/.claude.json" <<JSON
{"mcpServers": {
  "fetcher": {"command": "npx", "args": ["-y", "other-mcp"]},
  "fixed": {"command": "npx", "args": ["-y", "@scope/pkg@1.2.3"]},
  "added": {"command": "node"}}}
JSON
  out="$(cd "$project" && HOME="$home_dir" CODEX_HOME="$home_dir/.codex" OMS_MCP_PIN_FILE="$pins" "$ROOT/scripts/doctor.sh" --mcp)" ||
    fail "the pin report exits 0 on drift: $out"
  contains "$out" 'new: claude:user:added' || fail "an added server must be reported: $out"
  contains "$out" 'changed: claude:user:fetcher' || fail "a changed server must be reported: $out"
  contains "$out" 'removed: claude:user:plain' || fail "a removed server must be reported: $out"
  if (cd "$project" && HOME="$home_dir" OMS_MCP_PIN_FILE="$pins" "$ROOT/scripts/doctor.sh" --mcp --security) >/dev/null 2>&1; then
    fail "--mcp must refuse to run with --security"
  fi
  if (cd "$project" && HOME="$home_dir" OMS_MCP_PIN_FILE="$pins" "$ROOT/scripts/doctor.sh" --extensions --mcp) >/dev/null 2>&1; then
    fail "--extensions must refuse to run with --mcp"
  fi
}

# smoke-weight: 24
test_doctor_clean_harness_state_has_no_warnings() {
  local project="$TMP/doctor-harness-clean"
  local home_dir="$TMP/doctor-home-clean"
  local out harness_out

  setup_doctor_home "$home_dir"
  mkdir -p "$project/.oms/artifacts" "$project/.oms/task" "$project/.oms/memory"
  printf '*\n' > "$project/.oms/.gitignore"
  printf 'artifact\n' > "$project/.oms/artifacts/ok.md"
  printf 'patch\n' > "$project/.oms/artifacts/ok.patch"
  printf 'Current clean task\n' > "$project/.oms/task/current.md"
  printf 'Clean memory note\n' > "$project/.oms/memory/shared.md"
  printf '{"kind":"call","artifact":".oms/artifacts/ok.md","patch":".oms/artifacts/ok.patch"}\n' \
    > "$project/.oms/artifacts/index.jsonl"

  out="$(run_doctor_for_project "$project" "$home_dir")" ||
    fail "clean harness state should pass: $out"
  contains "$out" '# harness state' || fail "missing harness section"
  contains "$out" 'ok: artifact index JSONL' || fail "missing JSONL ok"
  contains "$out" 'ok: artifact index references' || fail "missing reference ok"
  contains "$out" 'ok: harness task/memory sensitive scan' ||
    fail "missing sensitive scan ok"
  # This case owns the harness-state section, not the developer machine's
  # optional external tool versions. Keep host drift from masking its scope.
  harness_out="$(printf '%s\n' "$out" | sed -n '/^# harness state/,$p')"
  if contains "$harness_out" 'warn:'; then
    fail "clean harness state should not warn: $out"
  fi
}

