# The residue scan only ever looked at mkdir-path lock directories, so on a
# machine with twelve thousand flock lock files it reported zero — which reads
# as "nothing here" rather than "this kind cannot be removed". They are
# permanent by design: unlinking a released flock file lets a waiter on the old
# inode and a new arrival on a fresh one both hold the lock. So: report, never
# remove, and say why.
# smoke-weight: 45
test_doctor_notes_flock_lock_files_without_removing_them() {
  local project="$TMP/doctor-flock-note"
  local home_dir="$TMP/doctor-flock-home"
  local lock_root="$home_dir/.cache/oh-my-setting/locks"
  local out

  setup_doctor_home "$home_dir"
  mkdir -p "$project/.oms" "$lock_root"
  : > "$lock_root/state.jsonl.123456789-42.lock"

  out="$(cd "$project" && HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" \
    OMS_LOCK_DIR="$lock_root" OMS_LOCK_FILE_NOTE_AT=1 \
    OH_MY_SETTING_REQUIRE_TOOLS=0 "$ROOT/scripts/doctor.sh")" ||
    fail "a flock lock file must not fail the doctor: $out"
  contains "$out" 'flock lock file(s)' ||
    fail "doctor should report flock lock files: $out"
  contains "$out" 'not removable by design' ||
    fail "doctor should say why they stay: $out"

  # Reported, and still there afterwards. cleanup must not take them either.
  HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" OMS_LOCK_DIR="$lock_root" \
    "$ROOT/scripts/cleanup.sh" --apply >/dev/null 2>&1 || true
  [ -f "$lock_root/state.jsonl.123456789-42.lock" ] ||
    fail "cleanup must not unlink a flock lock file"
}

# smoke-weight: 24
test_doctor_reports_crash_residue_warnings() {
  local project="$TMP/doctor-harness-residue"
  local home_dir="$TMP/doctor-home-residue"
  local runtime="$home_dir/runtime"
  # Locks live in a fixed per-user dir that no XDG variable moves; OMS_LOCK_DIR
  # is the one override, and it is named here so a check.sh run that exports it
  # for hermeticity does not point doctor at a different directory than this
  # fixture writes to. See file-lock.sh.
  local lock_root="$home_dir/.cache/oh-my-setting/locks"
  local lock_dir="$lock_root/dead.lock"
  local out

  setup_doctor_home "$home_dir"
  mkdir -p "$project/.oms/artifacts/call" "$lock_dir"
  printf '*\n' > "$project/.oms/.gitignore"
  # Only an orphan older than the prune grace window may be counted: doctor
  # and prune --files must agree, or the warning prescribes a no-op remedy.
  printf 'orphan\n' > "$project/.oms/artifacts/call/orphan.md"
  touch -t 202601010000 "$project/.oms/artifacts/call/orphan.md"
  printf 'in-flight\n' > "$project/.oms/artifacts/call/fresh.md"
  printf '999999999\n' > "$lock_dir/pid"

  out="$(cd "$project" && HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" \
    OMS_LOCK_DIR="$lock_root" \
    XDG_RUNTIME_DIR="$runtime" OH_MY_SETTING_REQUIRE_TOOLS=0 "$ROOT/scripts/doctor.sh")" ||
    fail "doctor residue warnings must not fail: $out"
  contains "$out" 'warn: 1 dead harness lock dir(s)' ||
    fail "missing dead lock warning: $out"
  contains "$out" 'warn: 1 unindexed artifact file(s)' ||
    fail "missing unindexed artifact warning: $out"
  contains "$out" 'hint: run cleanup.sh --apply to remove safe harness residue' ||
    fail "missing cleanup hint: $out"
  contains "$out" 'doctor: ok' || fail "doctor should still pass"
}

