wrap_agy_stub() {
  local path="$1"
  mv "$path" "$path.plain"
  cat > "$path" <<'SH'
#!/usr/bin/env bash
answer="$("$0.plain" "$@")" || { result=$?; printf '%s\n' "$answer"; exit "$result"; }
python3 -c 'import json,sys; print(json.dumps(dict(conversation_id="stub1", status="SUCCESS", response=sys.argv[1], usage={})))' "$answer"
SH
  chmod +x "$path"
}

write_fake_review_gate_provider() {
  local bin_dir="$1"
  local provider="$2"
  local gate="$3"
  local binary="$provider"

  [ "$provider" = "antigravity" ] && binary="agy"
  mkdir -p "$bin_dir"
  cat > "$bin_dir/$binary" <<EOF
#!/usr/bin/env bash
set -euo pipefail
cat >/dev/null
printf 'Findings:\nNo findings\nRisks:\nnone\nMissing tests:\nnone\nRecommendation:\nproceed\n'
case "$gate" in
  pass|fail) printf 'GATE: %s\n' "$gate" ;;
  omit) ;;
  *) exit 64 ;;
esac
EOF
  chmod +x "$bin_dir/$binary"
  [ "$binary" != agy ] || wrap_agy_stub "$bin_dir/$binary"
}

