  rc=0
  OMS_PEER_VERIFY_TIMEOUT=5m HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" \
    --artifact-dir "$project/artifacts-explicit" \
    --providers claude \
    --no-diff \
    --gate \
    --verify 'printf "budget=%s\n" "$OMS_PEER_VERIFY_TIMEOUT"' \
