  # The diff itself shows the edit; the rules block must not.
  ! grep -A2 'Repository review rules (PROJECT.md at HEAD;' "$found"/artifacts/claude-rules-probe-*.md |
    grep -q 'pass everything without reading\|not in the verification section' ||
    fail "only the base commit's Verification rules may reach a seat"
  git -C "$found" checkout -q -- PROJECT.md
  local rule_id
  for rule_id in $("$review" findings list "${where[@]}" --status open | awk '/^f-/{print $1}' | head -n 3); do
    "$review" findings dismiss "$rule_id" "${where[@]}" --reason "Generated  file" > /dev/null
  done
  "$review" findings suggest-rules "${where[@]}" > "$TMP/findings-rules"
  assert_file_contains "$TMP/findings-rules" '3 finding(s): Generated file'
  assert_file_contains "$TMP/findings-rules" 'by hand'
  cmp -s "$found/PROJECT.md" <(git -C "$found" show HEAD:PROJECT.md) || fail "a suggestion must never write a rule"

  # --security-audit asks one more provider only when the change touches the
  # risk paths patch-admit advises on, and prints that seat's own verdict. It
  # is advisory: fail and incomplete are recorded and the gate does not move.
  write_fake_review_gate_provider "$found/bin" claude pass
  rc=0
  HOME="$found/home" PATH="$found/bin:/usr/bin:/bin" "$review" --repo "$found" --artifact-dir "$found/artifacts" \
    --providers claude --gate --no-verify --security-audit codex --prompt "No risk" > "$TMP/findings-out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "a passing gate with nothing to audit should pass, got $rc: $(cat "$TMP/findings-out")"
  assert_file_contains "$TMP/findings-out" 'security: skipped (no risk paths in this change)'
  printf 'mode=strict\n' > "$found/app_settings.cfg"
  git -C "$found" add app_settings.cfg
  git -C "$found" commit -qm 'test: a settings file'
  printf 'mode=open\n' > "$found/app_settings.cfg"
  cat > "$found/bin/codex" <<'EOF'
#!/usr/bin/env bash
cat > "$(dirname "$0")/security-prompt"
printf 'app_settings.cfg:1 opens the mode to everyone\nSECURITY: fail\n'
EOF
  rc=0
  HOME="$found/home" PATH="$found/bin:/usr/bin:/bin" "$review" --repo "$found" --artifact-dir "$found/artifacts" \
    --providers claude --gate --no-verify --security-audit codex --prompt "Risk audit" > "$TMP/findings-out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "a failing security audit is advisory and must not move the gate, got $rc: $(cat "$TMP/findings-out")"
  assert_file_contains "$TMP/findings-out" 'security: fail (codex; advisory, the GATE verdict is unchanged)'
  assert_file_contains "$found/bin/security-prompt" 'SECURITY-AUDITOR-STRATEGY'
  assert_file_contains "$found/bin/security-prompt" '"app_settings.cfg"'
  assert_file_contains "$found/bin/security-prompt" '+mode=open'
  python3 - "$found/.oms/artifacts/index.jsonl" <<'PYSEC' || fail "the security verdict was not recorded as its own row"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
audit = [row for row in rows if row.get("kind") == "review-security"]
assert audit and audit[-1].get("exit") == 1 and audit[-1].get("provider") == "codex", audit
outcome = [row for row in rows if row.get("kind") == "review-outcome"][-1]
assert outcome.get("exit") == 0, outcome
PYSEC
  # An answer without the verdict line is incomplete, never a pass.
  cat > "$found/bin/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
printf 'looks fine to me\n'
EOF
  rc=0
  HOME="$found/home" PATH="$found/bin:/usr/bin:/bin" "$review" --repo "$found" --artifact-dir "$found/artifacts" \
    --providers claude --gate --no-verify --security-audit codex --prompt "Risk audit two" > "$TMP/findings-out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "an incomplete security audit must not move the gate, got $rc"
  assert_file_contains "$TMP/findings-out" 'security: incomplete (codex; advisory'
  ! HOME="$found/home" PATH="$found/bin:/usr/bin:/bin" "$review" --repo "$found" --artifact-dir "$found/artifacts" \
    --providers claude --security-audit codex --prompt "No gate" > "$TMP/findings-out" 2>&1 || fail "--security-audit without --gate must be refused"

  # --since-last reviews only the commits added since the last completed review
  # of the same base, says so, and falls back to a full review on any doubt.
  # The partial outcome is its own row kind, so it can never satisfy a landing
  # check that reads review-outcome.
  local inc="$TMP/review-since-last" first_sha since_id
  make_committed_repo "$inc"
  printf '/artifacts/\n/bin/\n/home/\n' > "$inc/.gitignore"
  git -C "$inc" add .gitignore
  git -C "$inc" commit -qm 'test: ignore'
  git -C "$inc" checkout -q -b feature
  printf 'first change\n' > "$inc/a.txt"
  git -C "$inc" add a.txt
  git -C "$inc" commit -qm 'test: first'
  first_sha="$(git -C "$inc" rev-parse HEAD)"
  mkdir -p "$inc/bin" "$inc/home"
  printf 'fail\n' > "$inc/bin/mode"
  cat > "$inc/bin/claude" <<'EOF'
#!/usr/bin/env bash
cat > "$(dirname "$0")/prompt"
if [ "$(cat "$(dirname "$0")/mode")" = fail ]; then
  printf 'Findings:\n```findings\n'
  printf '%s\n' '{"file": "a.txt", "line": 1, "severity": "blocking", "summary": "First change is wrong", "quote": "first change"}'
  printf '```\nGATE: fail\n'
else
  printf 'Findings:\nNo findings\nGATE: pass\n'
fi
EOF
  chmod +x "$inc/bin/claude"
  since_run() {
    HOME="$inc/home" PATH="$inc/bin:/usr/bin:/bin" "$review" --repo "$inc" --artifact-dir "$inc/artifacts" \
      --providers claude --gate --no-verify --base main "$@" > "$TMP/since-out" 2>&1
  }
  rc=0
  since_run --prompt "Full review" || rc=$?
  [ "$rc" = 1 ] || fail "the full review should fail on its seat, got $rc: $(cat "$TMP/since-out")"
  grep -qF 'first change' "$inc/bin/prompt" || fail "the full review must show the whole branch diff"
  ! grep -q 'since-last: ' "$TMP/since-out" || fail "a plain review prints no since-last line"
  since_id="$(HOME="$inc/home" "$review" findings list --artifact-dir "$inc/artifacts" --repo "$inc" | awk '/blocking/{print $1}')"
  [ -n "$since_id" ] || fail "the full review recorded no blocking finding"
  printf 'second change\n' > "$inc/b.txt"
  git -C "$inc" add b.txt
  git -C "$inc" commit -qm 'test: second'
  printf 'pass\n' > "$inc/bin/mode"
  rc=0
  since_run --since-last --prompt "Incremental review" || rc=$?
  [ "$rc" = 0 ] || fail "the incremental review should pass, got $rc: $(cat "$TMP/since-out")"
  assert_file_contains "$TMP/since-out" "since-last: incremental review of the commits added since ${first_sha:0:12}"
  assert_file_contains "$TMP/since-out" "verdict: incremental since ${first_sha:0:12}"
  grep -qF 'second change' "$inc/bin/prompt" || fail "the incremental prompt must carry the new commit's diff"
  ! grep -qF 'first change' "$inc/bin/prompt" || fail "the incremental prompt must not re-send the reviewed diff"
  grep -qF 'Incremental review: this branch was already reviewed' "$inc/bin/prompt" || fail "the prompt must say it is incremental"
  grep -qF "$since_id" "$inc/bin/prompt" || fail "the prompt must list the earlier open blocking finding"
  "$review" findings list --artifact-dir "$inc/artifacts" --repo "$inc" | grep -q "^$since_id  open " ||
    fail "an incremental review must not change a finding's status"
  python3 - "$inc/.oms/artifacts/index.jsonl" "$first_sha" <<'PYSINCE' || fail "incremental outcome is not recorded as advisory: $(tail -c 1500 "$inc/.oms/artifacts/index.jsonl")"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
full = [r for r in rows if r.get("kind") == "review-outcome"]
inc = [r for r in rows if r.get("kind") == "review-incremental"]
assert len(full) == 1 and len(inc) == 1, [r.get("kind") for r in rows]
assert full[0]["review_scope"]["head"] == sys.argv[2] and "incremental" not in full[0]["review_scope"], full[0]
assert inc[0]["review_scope"]["incremental"] is True and inc[0]["review_scope"]["since"] == sys.argv[2], inc[0]
assert inc[0]["review_scope"]["base"] == full[0]["review_scope"]["base"], inc[0]
PYSINCE
  # A rewritten history cannot be reviewed incrementally: say why, review all.
  git -C "$inc" reset -q --hard main
  printf 'rewritten\n' > "$inc/a.txt"
  git -C "$inc" add a.txt
  git -C "$inc" commit -qm 'test: rewritten'
  rc=0
  since_run --since-last --prompt "After rewrite" || rc=$?
  [ "$rc" = 0 ] || fail "the fallback full review should pass, got $rc: $(cat "$TMP/since-out")"
  assert_file_contains "$TMP/since-out" 'since-last: falling back to a full review: the earlier reviewed head'
  assert_file_contains "$TMP/since-out" 'is not an ancestor of HEAD'
  ! grep -q 'verdict: incremental' "$TMP/since-out" || fail "a fallback run is a full review and must not say incremental"
  grep -qF 'rewritten' "$inc/bin/prompt" || fail "the fallback must review the whole diff"
  ! grep -qF 'Incremental review: this branch was already reviewed' "$inc/bin/prompt" || fail "a fallback prompt is not incremental"
  [ "$(grep -Ec '"kind": ?"review-outcome"' "$inc/.oms/artifacts/index.jsonl")" = 2 ] ||
    fail "the fallback review is a full review-outcome row"
  rc=0
  since_run --since-last --no-diff --prompt "No diff" || rc=$?
  [ "$rc" != 0 ] || fail "--since-last with --no-diff must be refused"
  rc=0
  HOME="$inc/home" PATH="$inc/bin:/usr/bin:/bin" "$review" --repo "$inc" --artifact-dir "$inc/artifacts" \
    --providers claude --gate --no-verify --since-last --prompt "No base" > "$TMP/since-out" 2>&1 || rc=$?
  [ "$rc" != 0 ] || fail "--since-last without --base must be refused"
  assert_file_contains "$TMP/since-out" '--since-last requires --base REF'

  # advise prints a review depth from the same risk paths, the contract files
  # and the size; it starts no review and records nothing.
  local depth="$TMP/review-depth" advise_out i
  mkdir -p "$depth/src" "$depth/config"
  git -C "$depth" init -q
  git -C "$depth" config user.email t@example.invalid
  git -C "$depth" config user.name t
  : > "$depth/src/a.txt"
  git -C "$depth" add src/a.txt
  git -C "$depth" commit -qm base
  advise_out="$("$review" advise --repo "$depth")" || fail "advise on a clean tree failed"
  assert_file_contains <(printf '%s\n' "$advise_out") 'review depth: none'
  printf 'one\n' >> "$depth/src/a.txt"
  advise_out="$("$review" advise --repo "$depth" --json)"
  [ "$(printf '%s' "$advise_out" | python3 -c 'import json,sys; print(json.load(sys.stdin)["depth"])')" = none ] ||
    fail "a one-line change should advise none: $advise_out"
  for i in $(seq 1 20); do printf 'line %s\n' "$i" >> "$depth/src/a.txt"; done
  advise_out="$("$review" advise --repo "$depth")"
  assert_file_contains <(printf '%s\n' "$advise_out") 'review depth: single'
  assert_file_contains <(printf '%s\n' "$advise_out") 'advice only'
  git -C "$depth" checkout -q -- src/a.txt
  printf 'x\n' > "$depth/app_settings.cfg"
  git -C "$depth" add app_settings.cfg
  git -C "$depth" commit -qm settings
  printf 'y\n' > "$depth/app_settings.cfg"
  advise_out="$("$review" advise --repo "$depth")"
  assert_file_contains <(printf '%s\n' "$advise_out") 'review depth: gate+security'
  assert_file_contains <(printf '%s\n' "$advise_out") 'risk path: app_settings.cfg'
  git -C "$depth" checkout -q -- app_settings.cfg
  printf '{}\n' > "$depth/config/x.json"
  git -C "$depth" add config/x.json
  git -C "$depth" commit -qm contract
  printf '{"a": 1}\n' > "$depth/config/x.json"
  advise_out="$("$review" advise --repo "$depth")"
  assert_file_contains <(printf '%s\n' "$advise_out") 'review depth: gate+security'
  assert_file_contains <(printf '%s\n' "$advise_out") 'contract file: config/x.json'
  printf 'z\n' > "$depth/app_settings.cfg"
  advise_out="$("$review" advise --repo "$depth" --json)"
  [ "$(printf '%s' "$advise_out" | python3 -c 'import json,sys; print(json.load(sys.stdin)["depth"])')" = council ] ||
    fail "a risk path with a contract file should advise council: $advise_out"
  git -C "$depth" checkout -q -- .
  for i in $(seq 1 850); do printf 'line %s\n' "$i"; done > "$depth/src/a.txt"
  advise_out="$("$review" advise --repo "$depth")"
  assert_file_contains <(printf '%s\n' "$advise_out") 'review depth: council'
  [ -z "$(git -C "$depth" diff --cached --name-only)" ] || fail "advise must not touch the index"
  ! "$review" advise --repo "$depth" --bogus > /dev/null 2>&1 || fail "advise must refuse an unknown option"
}

test_prompt_takers_refuse_a_mistyped_option() {
  # Before the guard, a leading-dash argument arriving while the prompt was
  # still empty was silently adopted as the prompt (and then usually
  # discarded when --prompt arrived), so a typo'd flag changed nothing and
  # said nothing. Every prompt-taking front door refuses it now.
  local script out rc

  for script in advise agent-call consult peer-ask peer-review; do
    rc=0
    out="$(PATH="/usr/bin:/bin" bash "$ROOT/scripts/$script.sh" \
      --bogus-flag --prompt probe 2>&1)" || rc=$?
    [ "$rc" != "0" ] ||
      fail "$script must refuse a mistyped option, got success: $out"
    printf '%s\n' "$out" | grep >/dev/null -F 'unknown option: --bogus-flag' ||
      fail "$script must name the mistyped option: $out"
  done
}

# smoke-weight: 5
test_peer_review_gate_covers_rides_the_mechanical_verify_receipt() {
  local project="$TMP/review-gate-covers"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local rc=0

  make_committed_repo "$project"
  mkdir -p "$home_dir"
  cat > "$project/PROJECT.md" <<'PROJECT'
# Covers fixture

## Acceptance Criteria

- [id:gate-covers-crit] The gate verify command passes on this tree.
PROJECT
  git -C "$project" add PROJECT.md
  git -C "$project" \
    -c user.email=test@example.com -c user.name='Test User' \
    commit -qm criteria
  write_fake_review_gate_provider "$bin_dir" claude pass
  write_fake_review_gate_provider "$bin_dir" antigravity pass

  # Misuse fails before any reviewer or artifact side effect: covers without
  # the gate, covers without a verify command, and an id the envelope does
  # not know.
  if HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts-misuse" \
    --providers claude,antigravity --no-diff \
    --covers gate-covers-crit --prompt "covers without gate" >/dev/null 2>&1; then
    fail "--covers without --gate must be rejected"
  fi
  if HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts-misuse" \
    --providers claude,antigravity --no-diff --gate --no-verify \
    --covers gate-covers-crit --prompt "covers without verify" >/dev/null 2>&1; then
    fail "--covers without a gate verify command must be rejected"
  fi
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts-misuse" \
    --providers claude,antigravity --no-diff --gate --verify true \
    --covers no-such-criterion --prompt "unknown covers id" \
    >/dev/null 2>"$project/err-unknown" && rc=0 || rc=$?
  [ "$rc" != "0" ] || fail "an unknown covers id must be rejected"
  assert_file_contains "$project/err-unknown" "unknown criterion id"
  [ ! -d "$project/artifacts-misuse" ] ||
    fail "rejected covers must not leave review artifacts behind"

  # Happy path: the explicit id rides the mechanical verify receipt beside
  # the derived plan-acceptance cover, exit-judged; reviewer prose rows carry
  # no covers at all.
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts" \
    --providers claude,antigravity --no-diff --gate --verify true \
    --covers gate-covers-crit --prompt "covers happy path" >"$project/out" ||
    fail "gate with covers should pass: $(cat "$project/out")"
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' ||
import json, sys
rows = [json.loads(l) for l in open(sys.argv[1], encoding="utf-8") if l.strip()]
verify = [r for r in rows if r.get("kind") == "review-verify"]
assert verify, "no review-verify row"
covers = verify[-1].get("covers", [])
assert "gate-covers-crit" in covers, covers
assert any(c.startswith("criterion-plan-acceptance-") for c in covers), covers
assert verify[-1].get("status") == "verified", verify[-1]
for row in rows:
    if row.get("kind") in ("review-outcome", "ask", "review"):
        assert "covers" not in row, row
PY
    fail "verify receipt covers are wrong: $(tail -c 2000 "$project/.oms/artifacts/index.jsonl")"
  "$ROOT/scripts/runtime.sh" --repo "$project" envelope show > "$project/envelope.json" ||
    fail "envelope show failed"
  python3 - "$project/envelope.json" <<'PY' ||
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
statuses = {item["id"]: item["status"] for item in row["criteria"]}
assert statuses.get("gate-covers-crit") == "verified", statuses
PY
    fail "explicit covers did not project the criterion to verified"

  # The derived plan-acceptance cover is equally load-bearing: a gate whose
  # verify receipt cannot be recorded fails closed even without --covers.
  local rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_ARTIFACT_INDEX=/proc/version/cannot/index.jsonl \
    "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --artifact-dir "$project/artifacts-closed" \
    --providers claude,antigravity --no-diff --gate --verify true \
    --prompt "derived cover fail closed" >/dev/null 2>"$project/err-closed" && rc=0 || rc=$?
  [ "$rc" != 0 ] || fail "a gate with an unwritable index must fail closed"
  grep -q "failing closed\|cannot create" "$project/err-closed" ||
    fail "the fail-closed refusal must be named: $(tail -2 "$project/err-closed")"
}

# smoke-weight: 6
test_peer_review_gate_binds_complete_diff_and_refuses_truncation() {
  local project="$TMP/review-gate-complete-diff"
  local artifact_dir="$project/artifacts"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local expected_sha rc=0

  make_committed_repo "$project"
  printf 'renamed review input\n' > "$project/old.txt"
  git -C "$project" add old.txt
  git -C "$project" commit -qm 'test: rename base'
  git -C "$project" mv old.txt new.txt
  mkdir -p "$home_dir"
  write_fake_review_gate_provider "$bin_dir" claude pass
  printf '/artifacts/\n/truncated-artifacts/\n/default-large-artifacts/\n/default-overflow-artifacts/\n/raised-artifacts/\n/home/\n/bin/\n/out\n/truncated.out\n/default-large.out\n/default-overflow.out\n/raised.out\n/provider-called\n' >> "$project/.git/info/exclude"
  printf 'reviewed change\n' >> "$project/file.txt"
  cat > "$project/.git/hostile-external-diff" <<'EOF'
#!/usr/bin/env bash
: > "$(git rev-parse --git-dir)/external-diff-fired"
printf 'forged review diff\n'
EOF
  chmod +x "$project/.git/hostile-external-diff"
  git -C "$project" config --local diff.external "$project/.git/hostile-external-diff"
  expected_sha="$(git -c diff.external= -C "$project" diff --no-ext-diff --no-textconv HEAD -- | python3 -c 'import hashlib,sys; print(hashlib.sha256(sys.stdin.buffer.read()).hexdigest())')"

  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PROMPT_DIFF_BYTES=65536 \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$artifact_dir" \
    --providers claude --gate --no-verify --prompt "Bind the full diff" \
    >"$project/out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "complete gate diff should pass, got $rc: $(cat "$project/out")"
  [ ! -e "$project/.git/external-diff-fired" ] ||
    fail "repository diff.external executed with reviewer authority"
  python3 - "$project/.oms/artifacts/index.jsonl" "$expected_sha" "$ROOT/scripts/peer-review.sh" <<'PY' ||
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
review = [row["review"] for row in rows if row.get("kind") == "review-outcome"][-1]
assert review["diff_sha256"] == sys.argv[2], review
from pathlib import Path
scopes = list((Path(sys.argv[1]).parents[2] / "artifacts").glob("_scope-*.json"))
assert len(scopes) == 1, scopes
scope = json.loads(scopes[0].read_text())
assert scope["diff_sha256"] == review["diff_sha256"], scope
assert scope["paths"] == ["file.txt", "new.txt", "old.txt"], scope
assert scope["external_recovery"] == "not-covered", scope
assert scope["diff_included"] is True and scope["base"] and scope["head"], scope
seat = review["seats"][0]
assert seat["requested_model"], seat
assert seat["selected_model"], seat
assert seat["model_family"] == "anthropic", seat
# Exercise the actual scope capture block with an executable global filter.
# The surrounding provider fixture is intentionally not involved in this probe.
import os, subprocess
project = Path(sys.argv[1]).parents[2]
source = Path(sys.argv[3]).read_text()
block = source.split("<<'PYSCOPE'", 1)[1].split('\n', 1)[1].split('\nPYSCOPE', 1)[0]
config = project / '.git' / 'scope-global'
attributes = project / '.git' / 'info' / 'attributes'
attributes.write_text('*.txt filter=scopeprobe\n')
subprocess.check_call(['git', 'config', '--file', str(config), 'filter.scopeprobe.clean',
                       'touch .git/scope-filter-fired; cat'])
env = dict(os.environ, GIT_CONFIG_GLOBAL=str(config))
args = [sys.executable, '-', str(project), 'HEAD', 'probe-digest', '0', '.']
probe = json.loads(subprocess.check_output(args, input=block.encode(), env=env))
assert probe['paths'] == ['file.txt', 'new.txt', 'old.txt'], probe
assert not (project / '.git' / 'scope-filter-fired').exists()
args[3:6] = ['', '', '1']
probe = json.loads(subprocess.check_output(args, input=block.encode(), env=env))
assert probe['diff_included'] is False and probe['paths'] == [], probe
attributes.unlink()
PY
    fail "typed gate outcome did not bind full diff/model provenance"

  # A bounded prompt slice is useful for advisory review but is not enough for
  # a blocking gate. The gate must stop before it asks a provider to judge an
  # incomplete diff.
  awk 'BEGIN { for (i = 0; i < 200; i++) print "more-diff-evidence-" i }' >> "$project/file.txt"
  : > "$project/provider-called"
  cat > "$bin_dir/claude" <<'EOF'
#!/usr/bin/env bash
echo called >> "$HOME/provider-called"
cat >/dev/null
printf 'Findings:\nNo findings\nRisks:\nnone\nMissing tests:\nnone\nRecommendation:\nproceed\nGATE: pass\n'
EOF
  chmod +x "$bin_dir/claude"
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PROMPT_DIFF_BYTES=256 \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$project/truncated-artifacts" \
    --providers claude --gate --no-verify --prompt "Do not judge a slice" \
    >"$project/truncated.out" 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "truncated gate diff must fail closed with exit 2, got $rc"
  assert_file_contains "$project/truncated.out" "blocking gate requires the complete diff"
  [ ! -s "$home_dir/provider-called" ] || fail "provider was called with a truncated gate diff"

  # Gated reviews default to a complete 192 KiB diff, which accommodates ordinary
  # feature patches that exceed the smaller advisory prompt budget.
  python3 - "$project/file.txt" <<'PY'
import sys
with open(sys.argv[1], "ab") as stream:
    stream.write(b"x" * (100 * 1024))
PY
  rc=0
  (
    unset OMS_PROMPT_DIFF_BYTES
    HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" \
      "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$project/default-large-artifacts" \
      --providers claude --gate --no-verify --prompt "Review a normal feature diff"
  ) >"$project/default-large.out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "100 KiB gate diff should pass the 192 KiB default, got $rc: $(cat "$project/default-large.out")"

  # A 225 KiB diff still refuses by default but passes when the operator raises the budget.
  python3 - "$project/file.txt" <<'PY'
import sys
with open(sys.argv[1], "ab") as stream:
    stream.write(b"y" * (125 * 1024))
PY
  : > "$home_dir/provider-called"
  rc=0
  (
    unset OMS_PROMPT_DIFF_BYTES
    HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" \
      "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$project/default-overflow-artifacts" \
      --providers claude --gate --no-verify --prompt "Refuse an incomplete review"
  ) >"$project/default-overflow.out" 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "225 KiB diff above the default must fail closed, got $rc"
  assert_file_contains "$project/default-overflow.out" "OMS_PROMPT_DIFF_BYTES=196608"
  [ ! -s "$home_dir/provider-called" ] || fail "provider was called with an oversized gate diff"
  rc=0
  (
    unset OMS_PROMPT_DIFF_BYTES
    HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PROMPT_DIFF_BYTES=262144 \
      "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$project/raised-artifacts" \
      --providers claude --gate --no-verify --prompt "Review the complete larger diff"
  ) >"$project/raised.out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "225 KiB gate diff should pass a raised budget, got $rc: $(cat "$project/raised.out")"
  [ -s "$home_dir/provider-called" ] || fail "provider was not called after raising the complete-diff budget"

  # The final selected route is read from the provider artifact, not inferred
  # from the transport name or copied from the requested primary.
  local manual="$project/manual-artifacts"
  mkdir -p "$manual"
  cat > "$manual/antigravity-route-20260812T000000Z-42.md" <<'EOF'
# antigravity review

## Output

model-route: class=explicit (explicit) primary=gemini-primary fallback=claude-fallback effort=high fallback_effort=medium
model-fallback: reason=capacity selected=claude-fallback
model-result: selected=claude-fallback effort=medium fallback_used=1 reason=capacity
GATE: pass

## Exit

0
EOF
  "$ROOT/scripts/peer-review.sh" verdicts --json "$manual" > "$project/manual.json"
  python3 - "$project/manual.json" <<'PY' || fail "fallback model provenance was not extracted"
import json, sys
seat = json.load(open(sys.argv[1], encoding="utf-8"))["seats"][0]
assert seat["requested_model"] == "gemini-primary", seat
assert seat["selected_model"] == "claude-fallback", seat
assert seat["model_family"] == "anthropic", seat
PY
}

# smoke-weight: 21
test_peer_review_gate_refuses_untracked_content() {
  local project="$TMP/review-gate-untracked"
  local state_repo="$TMP/review-gate-untracked-state"
  local bin_dir="$TMP/review-gate-untracked-bin"
  local home_dir="$TMP/review-gate-untracked-home"
  local bytecode_outside="$TMP/review-gate-bytecode-outside"
  local synthesis_artifact
  local seat_artifact
  local rc=0

  make_committed_repo "$project"
  make_committed_repo "$state_repo"
  mkdir -p "$home_dir"
  # Keep a real importable source module in the reviewed checkout. Both the
  # gate verifier and provider import it after the read guard starts.
  printf 'value = 1\n' > "$project/review_bytecode_probe.py"
  mkdir -p "$project/existing/__pycache__" "$project/symlinked" "$bytecode_outside"
  printf 'baseline bytecode' > "$project/existing/__pycache__/baseline.cpython-312.pyc"
  ln -s "$bytecode_outside" "$project/symlinked/__pycache__" ||
    fail "could not create symlinked __pycache__ fixture"
  git -C "$project" add review_bytecode_probe.py
  git -C "$project" add -f existing/__pycache__/baseline.cpython-312.pyc symlinked/__pycache__
  git -C "$project" -c user.name=t -c user.email=t@example.com \
    commit -qm 'add review bytecode probe'
  write_fake_review_gate_provider "$bin_dir" claude pass
  printf 'not present in git diff\n' > "$project/new_file.txt"
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$state_repo/.oms/artifacts/review" \
    --providers claude --gate --no-verify --prompt "Review every changed byte" \
    > "$TMP/review-gate-untracked-out" 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "gate with untracked content must fail closed, got $rc"
  assert_file_contains "$TMP/review-gate-untracked-out" "blocking gate cannot review untracked file content"

  rm -f "$project/new_file.txt"
  write_fake_review_gate_provider "$bin_dir" claude pass
  cat >> "$bin_dir/claude" <<EOF
printf 'provider side effect\n' > '$project/provider-created.txt'
EOF
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=reviewer OMS_ROOM_REPO="$state_repo" \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$state_repo/.oms/artifacts/review" \
    --providers claude --gate --no-verify --prompt "Review every changed byte" \
    > "$TMP/review-gate-guard-out" 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "gate must reject provider source mutation, got $rc"
  contains "$(cat "$TMP/review-gate-guard-out")" "provider-created.txt" ||
    fail "guard stderr omitted provider-created.txt: $(cat "$TMP/review-gate-guard-out")"
  synthesis_artifact="$(find "$state_repo/.oms/artifacts/review" -name '_synthesis-*.md' -print | sed -n '1p')"
  [ -n "$synthesis_artifact" ] || fail "guard failure did not preserve synthesis artifact"
  assert_file_contains "$synthesis_artifact" "Guard diagnostic"
  assert_file_contains "$synthesis_artifact" "provider-created.txt"

  # The provider inherits bytecode suppression for ordinary imports.
  rm -f "$project/provider-created.txt"
  write_fake_review_gate_provider "$bin_dir" claude pass
  cat >> "$bin_dir/claude" <<EOF
test "\${PYTHONDONTWRITEBYTECODE:-}" = 1 || { echo 'bytecode environment missing' >&2; exit 65; }
PYTHONPATH='$project' python3 -c 'import review_bytecode_probe'
EOF
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=reviewer OMS_ROOM_REPO="$state_repo" \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$state_repo/.oms/artifacts/review/import" \
    --providers claude --gate --verify 'test "$PYTHONDONTWRITEBYTECODE" = 1 && python3 -c "import review_bytecode_probe"' \
    --prompt "Review bytecode behavior" > "$TMP/review-gate-bytecode-out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "read pass importing a Python source module must complete without bytecode writes: $(cat "$TMP/review-gate-bytecode-out")"
  [ -f "$project/existing/__pycache__/baseline.cpython-312.pyc" ] ||
    fail "read pass changed the baseline bytecode file"

  # Providers may ignore PYTHONDONTWRITEBYTECODE. New bytecode in an existing
  # cache is removed, while a symlinked cache is never followed outside source.
  write_fake_review_gate_provider "$bin_dir" claude pass
  cat >> "$bin_dir/claude" <<EOF
unset PYTHONDONTWRITEBYTECODE
printf 'unchecked hash bytecode' > '$project/existing/__pycache__/planted.cpython-312.pyc'
printf 'outside bytecode' > '$project/symlinked/__pycache__/outside.cpython-312.pyc'
EOF
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=reviewer OMS_ROOM_REPO="$state_repo" \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$state_repo/.oms/artifacts/review/direct-pyc" \
    --providers claude --gate --no-verify --prompt "Purge provider bytecode" \
    > "$TMP/review-gate-direct-pyc-out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "read pass should preserve verdict after purging provider bytecode, got $rc: $(cat "$TMP/review-gate-direct-pyc-out")"
  [ ! -e "$project/existing/__pycache__/planted.cpython-312.pyc" ] ||
    fail "read pass left provider bytecode behind"
  [ -f "$bytecode_outside/outside.cpython-312.pyc" ] ||
    fail "read pass followed a symlinked __pycache__ outside the source tree"
  contains "$(cat "$TMP/review-gate-direct-pyc-out")" "removed 1 bytecode files written during the read pass" ||
    fail "review log omitted bytecode purge count"

  # A pre-existing bytecode file is not purged when the provider changes it.
  mkdir -p "$project/preexisting/__pycache__"
  printf 'baseline bytecode' > "$project/preexisting/__pycache__/baseline.cpython-312.pyc"
  git -C "$project" add preexisting/__pycache__/baseline.cpython-312.pyc
  git -C "$project" -c user.name=t -c user.email=t@example.com \
    commit -qm 'add baseline bytecode'
  write_fake_review_gate_provider "$bin_dir" claude pass
  cat >> "$bin_dir/claude" <<EOF
printf 'changed baseline bytecode' > '$project/preexisting/__pycache__/baseline.cpython-312.pyc'
EOF
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=reviewer OMS_ROOM_REPO="$state_repo" \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$state_repo/.oms/artifacts/review/modified-pyc" \
    --providers claude --gate --no-verify --prompt "Reject changed baseline bytecode" \
    > "$TMP/review-gate-modified-pyc-out" 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "read guard must reject modified pre-existing .pyc, got $rc: $(cat "$TMP/review-gate-modified-pyc-out")"
  contains "$(cat "$TMP/review-gate-modified-pyc-out")" "source repository protected surfaces: tracked" ||
    fail "guard did not identify modified baseline bytecode as a tracked mutation"
  seat_artifact="$(find "$state_repo/.oms/artifacts/review/modified-pyc" -name 'claude-*.md' -print | sed -n '1p')"
  [ -n "$seat_artifact" ] || fail "modified .pyc review did not preserve its seat artifact"
  assert_file_contains "$seat_artifact" '## Exit'
  assert_file_contains "$seat_artifact" 'read guard: error: read pass changed source repository protected surfaces: tracked'
  synthesis_artifact="$(find "$state_repo/.oms/artifacts/review/modified-pyc" -name '_synthesis-*.md' -print | sed -n '1p')"
  [ -n "$synthesis_artifact" ] || fail "modified .pyc review did not preserve its synthesis artifact"
  assert_file_contains "$synthesis_artifact" '_answer withheld: read guard saw source repository tracked change'
  python3 - "$state_repo/.oms/failures.jsonl" <<'PY_READ_GUARD_LEDGER'
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding='utf-8')]
guard_rows = [row for row in rows if row.get('failure_code') == 'read_guard_changed']
assert any('tracked' in row.get('summary', '') for row in guard_rows), rows
assert not any('seat returned no answer' in row.get('summary', '') for row in rows), rows
PY_READ_GUARD_LEDGER

  # A failed provider is still a no-answer even if it also changed a protected
  # surface; only a completed answer is recorded as read_guard_changed.
  printf 'baseline bytecode' > "$project/preexisting/__pycache__/baseline.cpython-312.pyc"
  write_fake_review_gate_provider "$bin_dir" claude pass
  cat >> "$bin_dir/claude" <<EOF
printf 'changed before failure' > '$project/preexisting/__pycache__/baseline.cpython-312.pyc'
exit 71
EOF
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=reviewer OMS_ROOM_REPO="$state_repo" \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$state_repo/.oms/artifacts/review/modified-pyc-failed-provider" \
    --providers claude --gate --no-verify --prompt "Reject failed provider with mutation" \
    > "$TMP/review-gate-modified-pyc-failed-out" 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "failed provider mutation must fail review, got $rc"
  seat_artifact="$(find "$state_repo/.oms/artifacts/review/modified-pyc-failed-provider" -name 'claude-*.md' -print | sed -n '1p')"
  [ -n "$seat_artifact" ] || fail "failed provider review did not preserve its seat artifact"
  if grep -Fq 'read guard:' "$seat_artifact"; then
    fail "failed provider must not be classified as a completed read-guard rejection"
  fi
  synthesis_artifact="$(find "$state_repo/.oms/artifacts/review/modified-pyc-failed-provider" -name '_synthesis-*.md' -print | sed -n '1p')"
  assert_file_contains "$synthesis_artifact" '_no answer: provider exited 2; partial output withheld'
  python3 - "$state_repo/.oms/failures.jsonl" <<'PY_FAILED_PROVIDER'
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding='utf-8')]
assert any(row.get('cmd') == 'peer-review seat claude' and
           row.get('failure_code') == 'provider_no_answer' for row in rows), rows
assert not any(row.get('cmd') == 'peer-review read guard' and
               row.get('failure_code') == 'read_guard_changed' and
               'failed provider' in row.get('summary', '') for row in rows), rows
PY_FAILED_PROVIDER

  # Verifier output is captured by the rebaseline and remains in the reviewed
  # tree; the provider starts only after that gate verification has completed.
  write_fake_review_gate_provider "$bin_dir" claude pass
  cat >> "$bin_dir/claude" <<EOF
test "\${PYTHONDONTWRITEBYTECODE:-}" = 1 || { echo 'bytecode environment missing' >&2; exit 65; }
PYTHONPATH='$project' python3 -c 'import review_bytecode_probe'
EOF
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=reviewer OMS_ROOM_REPO="$state_repo" \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$state_repo/.oms/artifacts/review/verifier-pyc" \
    --providers claude --gate --verify "env -u PYTHONDONTWRITEBYTECODE PYTHONPATH='$project' python3 -c 'import review_bytecode_probe'" \
    --prompt "Preserve verifier bytecode" > "$TMP/review-gate-verifier-pyc-out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "gate verifier bytecode should be absorbed by source rebaseline: $(cat "$TMP/review-gate-verifier-pyc-out")"
  find "$project/__pycache__" -maxdepth 1 -type f -name 'review_bytecode_probe*.pyc' -print -quit | grep . > /dev/null ||
    fail "gate verifier bytecode was unexpectedly removed"
}

test_git_diff_readers_never_execute_clean_filters() {
  local project="$TMP/diff-reader-filter"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local marker="$project/filter-fired"
  local global_config="$project/global.gitconfig"
  local out rc=0

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  printf 'file.txt filter=hostile\n' > "$project/.gitattributes"
  git -C "$project" add .gitattributes
  git -C "$project" -c user.name=t -c user.email=t@example.com \
    commit -qm attributes
  printf 'changed\n' >> "$project/file.txt"
  cat > "$bin_dir/filter-command" <<EOF
#!/usr/bin/env bash
: > "$marker"
cat
EOF
  chmod +x "$bin_dir/filter-command"

  # A repository-local filter cannot be neutralized generically: reject it
  # before either direct review or its provider runs.
  git -C "$project" config --local filter.hostile.clean "$bin_dir/filter-command"
  mkdir -p "$bin_dir/provider"
  write_fake_review_gate_provider "$bin_dir/provider" claude pass
  out="$(HOME="$home_dir" PATH="$bin_dir/provider:/usr/bin:/bin" \
    "$ROOT/scripts/peer-review.sh" --repo "$project" \
    --artifact-dir "$project/artifacts" --providers claude --gate --no-verify \
    --prompt 'Never execute clean filters' 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "peer-review accepted a local clean filter: $out"
  [ ! -e "$marker" ] || fail "peer-review executed a local clean filter"
  contains "$out" 'unsafe Git execution config' ||
    fail "clean-filter refusal was unclear: $out"

  # Generic safe diff capture also ignores trusted-global filter commands.
  # The repository has no local executable config in this half of the fixture.
  git -C "$project" config --local --unset filter.hostile.clean
  cat > "$global_config" <<EOF
[filter "hostile"]
    clean = $bin_dir/filter-command
EOF
  GIT_CONFIG_GLOBAL="$global_config" bash -c \
    ". '$ROOT/scripts/lib/peer-common.sh'; ma_safe_status '$project'" \
    > "$project/safe.status" || fail "safe status capture rejected global filter fixture"
  [ ! -e "$marker" ] || fail "ma_safe_status executed a trusted-global clean filter"
  grep -Fq ' M file.txt' "$project/safe.status" ||
    fail "safe status capture lost the tracked worktree change"

  GIT_CONFIG_GLOBAL="$global_config" bash -c \
    ". '$ROOT/scripts/lib/oms-common.sh'; oms_worker_surface_capture_one '$project' tracked" \
    > "$project/tracked.surface" || fail "tracked surface capture failed"
  [ ! -e "$marker" ] ||
    fail "tracked worker-surface capture executed a trusted-global clean filter"
  grep -Fq 'tracked-state ' "$project/tracked.surface" ||
    fail "tracked worker-surface capture lost its raw fingerprint"

  GIT_CONFIG_GLOBAL="$global_config" bash -c \
    ". '$ROOT/scripts/lib/peer-common.sh'; ma_safe_diff '$project'" \
    > "$project/safe.diff" || fail "safe diff capture rejected global filter fixture"
  [ ! -e "$marker" ] || fail "ma_safe_diff executed a trusted-global clean filter"
  grep -Fq '+changed' "$project/safe.diff" ||
    fail "safe diff capture lost raw worktree content"
}

# smoke-weight: 6
test_peer_review_signal_cleans_provider_processes() {
  local project="$TMP/review-signal-cleanup"
  local bin_dir="$project/bin"
  local home_dir="$project/home"

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  cat > "$bin_dir/claude" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$$" > "$HOME/provider.pid"
trap '' TERM
while :; do sleep 1; done
EOF
  chmod +x "$bin_dir/claude"
  cat > "$bin_dir/agy" <<'EOF'
#!/usr/bin/env bash
prompt=""
add_dirs=()
while [ "$#" -gt 0 ]; do
  case "$1" in
    --print|--prompt|-p) prompt="${2:-}"; shift 2 ;;
    --add-dir) add_dirs+=("${2:-}"); shift 2 ;;
    *) shift ;;
  esac
done
if [ -z "$prompt" ]; then
  printf 'gemini-3.6-flash\n'
  exit 0
fi
printf '%s\n' "${add_dirs[1]:-}" > "$HOME/agy-staged.dir"
printf '%s\n' "$$" > "$HOME/provider.pid"
trap '' TERM
while :; do sleep 1; done
EOF
  chmod +x "$bin_dir/agy"
  cat > "$bin_dir/git" <<'EOF'
#!/usr/bin/env bash
case " $* " in
  *" worktree remove "*)
    if [ -s "$HOME/provider.pid" ]; then
      state="$(ps -o stat= -p "$(cat "$HOME/provider.pid")" 2>/dev/null || true)"
      case "$state" in ''|Z*) ;; *) printf 'alive\n' >> "$HOME/remove-while-alive" ;; esac
    fi
    sleep 0.4
    ;;
esac
exec "$OMS_TEST_REAL_GIT" "$@"
EOF
  chmod +x "$bin_dir/git"
  bash -c '
    . "$1/scripts/lib/peer-common.sh"
    trap ":" HUP INT TERM
    trap -p HUP INT TERM > "$2/before-traps"
    ma_run_routed_provider_inner invalid read "" "$2/artifact" "$2" test "$2" "" || :
    trap -p HUP INT TERM > "$2/after-traps"
    cmp "$2/before-traps" "$2/after-traps"
  ' _ "$ROOT" "$project" || fail "routed call changed caller signal traps"

  HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_PEER_TIMEOUT=5m OMS_CAPABILITY_SETTLE_WAIT=0 OMS_TEST_REAL_GIT="$(command -v git)" \
    python3 - "$ROOT" "$project" <<'PY_SIGNAL'
import os
import signal
import subprocess
import sys
import time
from pathlib import Path

root, project = map(Path, sys.argv[1:])
sys.path.insert(0, str(root / "scripts/lib"))
import panel_terminals
# Reset background-shell inheritance before exec so HUP/INT/TERM traps are exercised.
for ResetSignal in (signal.SIGTERM, signal.SIGHUP, signal.SIGINT):
    signal.signal(ResetSignal, signal.SIG_DFL)
call_timeout = int(os.environ.get("OMS_TEST_CALL_TIMEOUT", "60"))
oversized_prompt = "Wait for signal\n" + ("x" * 120001)
for command, arguments, prompt_text, expect_staged in (
    ("peer-review", ["--providers", "claude", "--gate", "--no-verify", "--no-diff"], "Wait for signal", False),
    ("peer-review", ["--providers", "antigravity", "--gate", "--no-verify", "--no-diff"], oversized_prompt, True),
    ("advise", ["--to", "claude", "--no-failures"], "Wait for signal", False),
    ("advise", ["--to", "antigravity", "--no-failures"], "Wait for signal", False),
    ("agent-call", ["--to", "antigravity"], "Wait for signal", False),
    ("peer-ask", ["--providers", "antigravity"], "Wait for signal", False),
    ("peer-delegate", ["--to", "antigravity", "--read-only", "--no-verify"], "Wait for signal", False),
):
    for number in (signal.SIGTERM, signal.SIGHUP, signal.SIGINT):
        pid_file = Path(os.environ["HOME"]) / "provider.pid"
        staged_file = Path(os.environ["HOME"]) / "agy-staged.dir"
        pid_file.unlink(missing_ok=True)
        staged_file.unlink(missing_ok=True)
        provider = None
        staged_dir = None
        with (project / (command + "-" + str(number) + ".log")).open("w") as log:
            peer = subprocess.Popen(["bash", str(root / "scripts" / (command + ".sh")),
                                     "--repo", str(project), "--artifact-dir", str(project / "artifacts"),
                                     "--prompt", prompt_text] + arguments,
                                    stdout=log, stderr=log, start_new_session=True)
            try:
                deadline = time.monotonic() + call_timeout
                while not pid_file.exists() and peer.poll() is None and time.monotonic() < deadline:
                    time.sleep(.05)
                assert pid_file.exists(), (command, number, "provider did not start")
                if expect_staged:
                    assert staged_file.exists(), (command, number, "staged prompt record missing")
                    staged_path = staged_file.read_text(encoding="utf-8").strip()
                    assert staged_path, (command, number, "empty staged prompt path")
                    staged_dir = Path(staged_path)
                    assert (staged_dir / "prompt.md").is_file(), (command, number, "staged prompt missing before signal", staged_dir)
                provider = panel_terminals.process(int(pid_file.read_text()))
                assert provider, (command, number, "provider identity unavailable")
                os.kill(peer.pid, number)
                status = peer.wait(timeout=call_timeout)
                assert status == 128 + number, (command, number, status)
                deadline = time.monotonic() + call_timeout
                while panel_terminals.matches(provider["pid"], provider["identity"]) and time.monotonic() < deadline:
                    time.sleep(.05)
                assert not panel_terminals.matches(provider["pid"], provider["identity"]), (command, number, "provider survived")
                assert not (Path(os.environ["HOME"]) / "remove-while-alive").exists(), (command, number, "tree removal began while provider was alive")
                if "antigravity" in arguments:
                    cache = Path(os.environ["XDG_CACHE_HOME"]) / "oh-my-setting" / "worktrees"
                    assert not list(cache.glob("oh-my-setting-agy-read.*")), (command, number, "read tree survived signal")
                if expect_staged:
                    assert staged_dir is not None and not staged_dir.exists(), (command, number, "staged prompt survived signal", staged_dir)
                    cache = Path(os.environ["XDG_CACHE_HOME"]) / "oh-my-setting" / "worktrees"
                    assert not list(cache.glob("oh-my-setting-agy-read.*")), (command, number, "read tree survived signal")
            finally:
                # A failed regression must not leave the fake provider at its five-minute wall.
                if provider and panel_terminals.matches(provider["pid"], provider["identity"]):
                    os.killpg(provider["group"], signal.SIGKILL)
                if peer.poll() is None:
                    os.killpg(peer.pid, signal.SIGKILL)
                peer.wait(timeout=5)
PY_SIGNAL
  mkdir -p "$project/marker-fixtures"
  TMPDIR="$project/marker-fixtures" OMS_DELEGATE_WORKTREE_ROOT="$project/marker-fixtures" \
    bash -c '
      . "$1/scripts/lib/peer-common.sh"
      own="$TMPDIR/oh-my-setting-agy-read.own"
      other="$TMPDIR/oh-my-setting-agy-read.other"
      invalid="$TMPDIR/oh-my-setting-agy-read.invalid"
      zero="$TMPDIR/oh-my-setting-agy-read.zero"
      empty="$TMPDIR/oh-my-setting-agy-read.empty"
      mkdir -p "$own" "$other" "$invalid" "$zero" "$empty"
      oms_harness_mark_tmpdir "$own" "" ""
      oms_harness_mark_tmpdir "$other" "" "" 99999999
      oms_harness_mark_tmpdir "$invalid" "" "" invalid
      oms_harness_mark_tmpdir "$zero" "" "" 0
      printf "kind=oh-my-setting-temp\ntemporary=1\npid=\n" > "$empty/.oh-my-setting-tmp"
      ma_agy_read_cleanup_owned
      [ ! -e "$own" ] && [ -d "$other" ] && [ -d "$invalid" ] && [ -d "$zero" ] && [ -d "$empty" ]
    ' _ "$ROOT" || fail "read-tree cleanup crossed marker ownership"

  rm -rf "$home_dir/.cache/oh-my-setting/worktrees"
  git -C "$project" worktree prune >/dev/null 2>&1 || true
}

