test_blocked_outbound_context_is_not_a_seat_failure() {
  local project="$TMP/outbound-scrub-ledger"
  local review_prompt="$TMP/outbound-review-prompt"
  local review_diff="$TMP/outbound-review-diff"
  local rc=0
