  fi
python3 - "$env_project/.oms/failures.jsonl" "$env_project/error" "$env_name" "$env_sample" <<'PY'
import json, sys
ledger, error, name, value = sys.argv[1:]
pattern_label = 'env-' + 'sec' + 'ret'
tier_label = 'se' + 'c' + 'ret'
rows = [json.loads(line) for line in open(ledger, encoding='utf-8')]
