write_fake_debate_provider() {
  local bin_dir="$1"
  local provider="$2"
  local fail_round2="$3"
  local fail_round1="${4:-0}"
  local binary="$provider"
  local label

  [ "$provider" = "antigravity" ] && binary="agy"
  label="$(printf '%s' "$provider" | tr '[:lower:]' '[:upper:]')"
  mkdir -p "$bin_dir"
  cat > "$bin_dir/$binary" <<EOF
#!/usr/bin/env bash
set -euo pipefail
case "\${1:-}" in --version|--help) echo 'fake debate provider'; exit 0 ;; esac
prompt="\$(cat)"
round=1
case "\$prompt" in
  *"This is debate round 2."*) round=2 ;;
  *"This is debate round 3."*) round=3 ;;
esac
if [ "\${OMS_TEST_READ_CONTEXT:-0}" = 1 ]; then
  # Read exactly what the prompt references, from this seat's own cwd.
  context="\$(printf '%s\n' "\$prompt" | grep -o '\.oms/delegations/council-context\.[A-Za-z0-9]*' | head -1)"
  [ -n "\$context" ] && [ -r "\$context/request.md" ] && [ -r "\$context/source.txt" ] || exit 51
  case "\$prompt" in *"\${OMS_TEST_FORBID:-/nonexistent-forbid}"*) exit 55 ;; esac
  if [ "\$round" = 2 ]; then
    grep -q 'CODEX ROUND1 ANSWER' "\$context/answer-0.md" || exit 53
    grep -q 'ANTIGRAVITY ROUND1 ANSWER' "\$context/answer-2.md" || exit 53
  fi
  printf '%s READ CONTEXT ROUND%s\n' "$label" "\$round"
fi
if [ "$provider" = antigravity ] && [ "\${OMS_TEST_READ_CONTEXT:-0}" = 1 ]; then
  [ ! -e .oms/threads/private.txt ] || exit 52
  printf 'SHARED EVIDENCE READABLE\n'
fi
if [ "$fail_round1" = "1" ] && [ "\$round" = "1" ]; then
  echo "$label ROUND1 FAILURE"
  exit 42
fi
if [ "$fail_round2" = "1" ] && [ "\$round" = "2" ]; then
  echo "$label ROUND2 FAILURE"
  exit 42
fi
printf 'Answer:\n%s ROUND%s ANSWER\nRecommendation:\nuse %s round %s\n' "$label" "\$round" "$label" "\$round"
EOF
  chmod +x "$bin_dir/$binary"
  [ "$binary" != agy ] || wrap_agy_stub "$bin_dir/$binary"
}

write_fake_auth_noise_debate_provider() {
  local bin_dir="$1"
  local provider="$2"
  local binary="$provider"
  local label
  local auth_scheme="Bea""rer"
  local home_path="/ho""me/noise/private"

  [ "$provider" = "antigravity" ] && binary="agy"
  label="$(printf '%s' "$provider" | tr '[:lower:]' '[:upper:]')"
  mkdir -p "$bin_dir"
  cat > "$bin_dir/$binary" <<EOF
#!/usr/bin/env bash
set -euo pipefail
prompt="\$(cat)"
round=1
case "\$prompt" in
  *"This is debate round 2."*) round=2 ;;
  *"This is debate round 3."*) round=3 ;;
esac
if [ "\$round" = "1" ]; then
  printf 'Answer:\n%s ROUND1 ANSWER\n' "$label"
  printf 'provider auth challenge: %s resource_metadata="https://mcp.example.invalid/resource"\n' "$auth_scheme"
  printf 'provider path: %s/session.log\n' "$home_path"
  printf 'Recommendation:\ncontinue\n'
else
  case "\$prompt" in
    *"$auth_scheme resource_metadata"*|*"$home_path"*) echo "UNSANITIZED ROUND2 PROMPT"; exit 44 ;;
  esac
  case "\$prompt" in
    *"[REDACTED: sensitive-looking provider output line omitted]"*) ;;
    *) echo "MISSING REDACTION"; exit 45 ;;
  esac
  printf 'Answer:\n%s ROUND2 ANSWER\nRecommendation:\naccepted sanitized debate\n' "$label"
fi
EOF
  chmod +x "$bin_dir/$binary"
  [ "$binary" != agy ] || wrap_agy_stub "$bin_dir/$binary"
}

# smoke-weight: 5
test_peer_ask_debate_tracks_dropout() {
  local project="$TMP/ask-debate-dropout"
  local artifact_dir="$project/artifacts"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local synth
  local rc=0

  mkdir -p "$project/.oms/threads" "$home_dir"
  printf 'private unrelated state\n' > "$project/.oms/threads/private.txt"
  write_fake_debate_provider "$bin_dir" codex 0
  write_fake_debate_provider "$bin_dir" claude 1
  write_fake_debate_provider "$bin_dir" antigravity 0

  # A HOME-based, spaced TMPDIR hosts the isolated seat's tree; the prompt
  # must never carry it.
  mkdir -p "$home_dir/tmp dir"
  OMS_TEST_READ_CONTEXT=1 OMS_TEST_FORBID="$home_dir/tmp dir" TMPDIR="$home_dir/tmp dir" \
    HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-ask.sh" \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --providers codex,claude,antigravity \
    --no-memory --no-task --no-ml-context \
    --debate 1 \
    --prompt "Debate dropout coverage" >"$project/out" 2>"$project/err" || rc=$?

  [ "$rc" = "0" ] || fail "dropout debate should exit 0, got $rc"
  if ! find "$artifact_dir" -name 'antigravity-*-r2.md' | grep . > /dev/null; then
    cat "$project/err" >&2
    find "$artifact_dir" -name 'antigravity-*.md' -exec cat {} \; >&2
    fail 'isolated participant did not reach round two'
  fi
  assert_one_artifact_contains "$artifact_dir" 'antigravity-debate-dropout-coverage-*-r2.md' 'SHARED EVIDENCE READABLE'
  if find "$project/.oms" "$home_dir/tmp dir" -name 'council-context.*' | grep . > /dev/null; then
    fail 'temporary council evidence was not removed'
  fi
  # Every seat, not only the isolated one, read the request and source in
  # round one and the shared answers in round two.
  find "$artifact_dir" -name 'codex-debate-dropout-coverage-*.md' ! -name '*-r2.md' -exec cat {} + |
    grep -F 'CODEX READ CONTEXT ROUND1' > /dev/null || fail 'codex did not read the shared context in round one'
  find "$artifact_dir" -name 'claude-debate-dropout-coverage-*.md' ! -name '*-r2.md' -exec cat {} + |
    grep -F 'CLAUDE READ CONTEXT ROUND1' > /dev/null || fail 'claude did not read the shared context in round one'
  find "$artifact_dir" -name 'antigravity-debate-dropout-coverage-*.md' ! -name '*-r2.md' -exec cat {} + |
    grep -F 'ANTIGRAVITY READ CONTEXT ROUND1' > /dev/null || fail 'antigravity did not read the shared context in round one'
  assert_one_artifact_contains "$artifact_dir" 'codex-debate-dropout-coverage-*-r2.md' 'CODEX READ CONTEXT ROUND2'
  assert_one_artifact_contains "$artifact_dir" 'claude-debate-dropout-coverage-*-r2.md' 'CLAUDE READ CONTEXT ROUND2'
  assert_one_artifact_contains "$artifact_dir" 'antigravity-debate-dropout-coverage-*-r2.md' 'ANTIGRAVITY READ CONTEXT ROUND2'
  assert_one_artifact_contains "$artifact_dir" 'codex-debate-dropout-coverage-*-r2.md' 'CODEX ROUND2 ANSWER'
  assert_one_artifact_contains "$artifact_dir" 'antigravity-debate-dropout-coverage-*-r2.md' 'ANTIGRAVITY ROUND2 ANSWER'
  assert_one_artifact_contains "$artifact_dir" 'claude-debate-dropout-coverage-*-r2.md' 'CLAUDE ROUND2 FAILURE'
  synth="$(find "$artifact_dir" -type f -name '_synthesis-debate-dropout-coverage-*.md' | sed -n '1p')"
  [ -n "$synth" ] || fail "missing dropout synthesis"
  assert_file_contains "$synth" 'CLAUDE ROUND1 ANSWER'
  if grep -Fq 'CLAUDE ROUND2 FAILURE' "$synth"; then
    fail "synthesis must use dropped provider's last successful answer"
  fi
  assert_file_contains "$project/out" 'summary: 3/3 providers succeeded (1 dropped during debate)'
  assert_file_contains "$project/err" "note: debate dropped providers: claude; their last successful round's answer was used for synthesis"
}

