test_peer_review_print_timeout() {
  local project="$TMP/review-timeout"
  local artifact_dir="$project/artifacts"

  mkdir -p "$project"
  git -C "$project" init >/dev/null

  OH_MY_SETTING_REVIEW_DRY_RUN=1 "$ROOT/scripts/peer-review.sh" \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --print-timeout 10m \
    --prompt "Review with custom print timeout" >/dev/null

  local bin="$project/bin" mode access
  mkdir -p "$bin"
  cat > "$bin/agy" <<'SH'
#!/usr/bin/env bash
case "${1:-}" in --version|--help) echo 'agy stub'; exit 0 ;; esac
printf '%s\n' "$@" > "$AGY_ARGS"
printf 'x\n' >> "$AGY_ARGS.runs"
# agy's duration grammar: a bare number is a usage error before any model call.
prev=''
for a in "$@"; do
  if [ "$prev" = --print-timeout ]; then
    case "$a" in
      [0-9]*s|[0-9]*m|[0-9]*h) ;;
      *) echo "agy: invalid --print-timeout $a" >&2; exit 2 ;;
    esac
  fi
  prev="$a"
done
case "$AGY_MODE" in
  plain) printf 'plain provider failure\n' ;;
  empty) : ;;
  malformed) printf '{invalid json\n' ;;
  invalid_utf8) printf '\377\n' ;;
  oversized) python3 -c 'import sys; sys.stdout.write("x" * 1048577)' ;;
  timeout) printf '%s\n' '{"conversation_id":"id1","status":"SUCCESS","response":"","usage":{},"finished_reason":"print_timeout"}' ;;
  banner) printf '%s\n' '{"conversation_id":"id1","status":"SUCCESS","response":"partial answer","usage":{},"finished_reason":"print_timeout"}' '[agy] print timeout after 5m with turn in progress; returning partial output' ;;
  banner_error) printf '%s\n' '[agy] print timeout after 5m with turn in progress; returning partial output'; exit 1 ;;
  last) printf '%s\n' '{"conversation_id":"id1","status":"SUCCESS","response":"earlier answer","usage":{}}' '{"conversation_id":"id1","status":"SUCCESS","response":"last answer","usage":{}}' ;;
  noisy) printf '%s\n' '{bad diagnostic' >&2; printf '%s\n' '{"conversation_id":"id1","status":"SUCCESS","response":"noisy answer","usage":{}}' ;;
  failed) printf '%s\n' '{"conversation_id":"id1","status":"FAILED","response":"bad answer","usage":{}}' ;;
  err_interrupted) printf '%s\n' '{"conversation_id":"id1","status":"ERROR","finished_reason":"error","response":"partial text","error":"The stream was interrupted. Please continue the task you were working on.","usage":{}}' ;;
  err_idle) printf '%s\n' '{"conversation_id":"id1","status":"ERROR","finished_reason":"error","response":"","error":"API error (attempt 1): request failed: stream idle timeout (5m0s): context deadline exceeded","usage":{}}' ;;
  err_tokens) printf '%s\n' '{"conversation_id":"id1","status":"ERROR","finished_reason":"error","response":"cut","error":"Your previous response was cut off because it exceeded the output token limit","usage":{}}' ;;
  err_unknown) printf '%s\n' '{"conversation_id":"id1","status":"ERROR","finished_reason":"error","response":"","error":"something else broke","usage":{}}' ;;
  err_auth) printf '%s\n' '{"conversation_id":"id1","status":"ERROR","finished_reason":"error","response":"","error":"authentication failed","usage":{}}' ;;
  err_denied) printf '%s\n' '{"conversation_id":"id1","status":"ERROR","finished_reason":"error","response":"","error":"permission denied: tool run_command requires approval","usage":{}}' ;;
  err_long) printf '{"conversation_id":"id1","status":"ERROR","finished_reason":"error","response":"cut","error":"%s output token limit","usage":{}}\n' "$(python3 -c 'print("x" * 241)')" ;;
  quote) printf '%s\n' '{"conversation_id":"id1","status":"SUCCESS","response":"The stream was interrupted and output token limit are phrases I quote.","usage":{}}' ;;
  zero) printf '%s\n' '{"conversation_id":"id1","status":"SUCCESS","response":"zero usage","usage":{"input_tokens":0,"output_tokens":0,"cache_read_tokens":0}}' ;;
  *) printf '%s\n' '{"conversation_id":"id1","status":"SUCCESS","response":"Answer: hello\n","usage":{"input_tokens":7,"output_tokens":3,"thinking_tokens":2,"cache_read_tokens":4,"total_tokens":12}}' ;;
esac
SH
  chmod +x "$bin/agy"
  printf 'review prompt\n' > "$project/prompt"
  (
    . "$ROOT/scripts/lib/peer-common.sh"
    oms_provider_cli_discovered() { return 0; }
    oms_provider_cli_available() { return 0; }
    run_with_timeout() { "$@"; }
    export PATH="$bin:$PATH" AGY_ARGS="$project/args"
    for access in read write; do
      export AGY_MODE=success
      ma_provider_attempt antigravity "$access" "$project/prompt" "$project/output" "$project" \
        provider-default '' test '' '' || exit 1
      grep -Fxq -- '--output-format' "$project/args" && grep -Fxq -- json "$project/args" || exit 2
      grep -Fxq -- '--print-timeout' "$project/args" || exit 3
      grep -Fxq 'Answer: hello' "$project/output" || exit 4
      grep -Fq '"input_tokens": 7' "$project/output" || exit 5
      grep -Fq '"output_tokens": 3' "$project/output" || exit 6
      grep -Fq '"cache_read_tokens": 4' "$project/output" || exit 7
    done
    OMS_PEER_TIMEOUT=77m ma_provider_attempt antigravity write "$project/prompt" "$project/output" "$project" \
      provider-default '' test '' '' || exit 9
    grep -Fxq 77m "$project/args" || exit 10
    # Documented bare seconds gain a unit at the agy boundary; text and
    # precedence (print override > wall > default) are otherwise preserved.
    OMS_PEER_TIMEOUT=2400 ma_provider_attempt antigravity write "$project/prompt" "$project/output" "$project" \
      provider-default '' test '' '' || exit 30
    grep -Fxq 2400s "$project/args" || exit 31
    OMS_PEER_TIMEOUT=90.5 ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
      provider-default '' test '' '' || exit 32
    grep -Fxq 90.5s "$project/args" || exit 33
    OMS_PEER_TIMEOUT=2400 OMS_PEER_PRINT_TIMEOUT=300 ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
      provider-default '' test '' '' || exit 34
    grep -Fxq 300s "$project/args" || exit 35
    OMS_PEER_TIMEOUT=2400 OMS_PEER_PRINT_TIMEOUT=0.5s ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
      provider-default '' test '' '' || exit 36
    grep -Fxq 0.5s "$project/args" || exit 37
    OMS_PEER_TIMEOUT='' OMS_PEER_PRINT_TIMEOUT='' ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
      provider-default '' test '' '' || exit 38
    grep -Eqx '[0-9.]+[smh]' "$project/args" || exit 39
    rm -f "$project/args" "$project/args.runs"
    for zero in 0 00 0.0; do
      if OMS_PEER_TIMEOUT=$zero ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
          provider-default '' test '' ''; then exit 40; fi
      grep -Fq 'must be positive' "$project/output" || exit 41
      [ ! -e "$project/args.runs" ] || exit 42
    done
    export AGY_MODE=zero
    ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
      provider-default '' test '' '' || exit 11
    grep -Fq '"input_tokens": 0' "$project/output" || exit 12
    for mode in timeout noisy banner last; do
      export AGY_MODE="$mode"
      ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
        provider-default '' test '' '' || exit 15
      case "$mode" in
        timeout) grep -Fq 'reason=stream_truncated subtype=print_timeout' "$project/output" || exit 16 ;;
        noisy) grep -Fq 'noisy answer' "$project/output" || exit 17 ;;
        banner)
          grep -Fq '[agy] print timeout after 5m' "$project/output" || exit 19
          [ "$(grep -c '^stop-reason: ' "$project/output")" = 1 ] || exit 20 ;;
        last)
          grep -Fxq 'last answer' "$project/output" || exit 21
          ! grep -Fq 'earlier answer' "$project/output" || exit 22 ;;
      esac
    done
    for mode in err_interrupted err_idle err_tokens err_unknown err_auth err_denied err_long; do
      export AGY_MODE="$mode"
      if ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
          provider-default '' test '' ''; then exit 50; fi
      grep -Fq 'finished_reason=error error=' "$project/output" || exit 51
      grep -Fq '"conversation_id":"id1"' "$project/output" || exit 52
      ! grep -Fq 'provider turn did not finish' "$project/output" || exit 53
      [ "$(grep -c '^stop-reason: ' "$project/output")" = 1 ] || exit 54
      case "$mode" in
        err_interrupted|err_idle)
          grep -Fxq 'stop-reason: provider=antigravity reason=stream_truncated subtype=error is_error=1' "$project/output" || exit 55
          [ "$OMS_PROVIDER_ERROR_CLASSIFICATION" = provider_down ] || exit 56 ;;
        err_tokens|err_long)
          grep -Fxq 'stop-reason: provider=antigravity reason=max_tokens subtype=error is_error=1' "$project/output" || exit 57
          [ -z "$OMS_PROVIDER_ERROR_CLASSIFICATION" ] || exit 58 ;;
        err_unknown|err_auth|err_denied)
          grep -Fxq 'stop-reason: provider=antigravity reason=turn_failed subtype=error is_error=1' "$project/output" || exit 59
          [ -z "$OMS_PROVIDER_ERROR_CLASSIFICATION" ] || exit 62 ;;
      esac
    done
    export AGY_MODE=quote
    ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
      provider-default '' test '' '' || exit 60
    ! grep -q '^stop-reason: ' "$project/output" || exit 61
    for mode in plain empty malformed failed invalid_utf8 oversized banner_error; do
      export AGY_MODE="$mode"
      if ma_provider_attempt antigravity read "$project/prompt" "$project/output" "$project" \
          provider-default '' test '' ''; then exit 8; fi
      case "$mode" in
        plain) grep -Fq 'plain provider failure' "$project/output" || exit 9 ;;
        empty) grep -Fq "error: conversation protocol:" "$project/output" || exit 13 ;;
        malformed) grep -Fq '{invalid json' "$project/output" || exit 14 ;;
        failed) grep -Fq '"status":"FAILED"' "$project/output" || exit 10 ;;
        invalid_utf8|oversized) grep -Fq 'error: conversation protocol:' "$project/output" || exit 18 ;;
        banner_error)
          grep -Fq '[agy] print timeout after 5m' "$project/output" || exit 23
          [ "$(grep -c '^stop-reason: ' "$project/output")" = 1 ] || exit 24 ;;
      esac
    done
  ) || fail 'agy JSON output, usage, or failure handling failed'
  PATH="$bin:$PATH" AGY_ARGS="$project/args" AGY_MODE=success \
    "$ROOT/scripts/peer-review.sh" --repo "$project" --artifact-dir "$project/live" \
    --providers antigravity --no-diff --print-timeout 10m --prompt 'Review JSON response' > "$project/review.out" ||
    fail 'agy review failed'
  assert_one_artifact_contains "$project/live" 'antigravity-review-json-response-*.md' 'Answer: hello'
  assert_one_artifact_contains "$project/live" 'antigravity-review-json-response-*.md' '"cache_read_tokens": 4'
  PATH="$bin:$PATH" HOME="$project/home" AGY_ARGS="$project/args" AGY_MODE=success OMS_PEER_TIMEOUT=2400 \
    "$ROOT/scripts/oms" peer-review --repo "$project" --artifact-dir "$project/live-numeric" \
    --providers antigravity --no-diff --prompt 'Review numeric wall' > "$project/review-numeric.out" 2>&1 ||
    fail "agy review with numeric OMS_PEER_TIMEOUT failed: $(cat "$project/review-numeric.out")"
  grep -Fxq 2400s "$project/args" || fail 'numeric wall did not reach agy as seconds'
}

# smoke-weight: 20
test_peer_ask_debate_dry_run() {
  local project="$TMP/ask-debate"
  local artifact_dir="$project/artifacts"
  local count

  mkdir -p "$project"
  OH_MY_SETTING_ASK_DRY_RUN=1 "$ROOT/scripts/peer-ask.sh" \
    --artifact-dir "$artifact_dir" \
    --debate 1 \
    --prompt "Debate two options" >/dev/null

  count="$(find "$artifact_dir" -type f -name '*.md' ! -name '_synthesis-*' | wc -l)"
  [ "$count" = "6" ] || fail "expected six debate artifacts (3 round1 + 3 round2), got $count"
  assert_one_artifact_contains "$artifact_dir" 'codex-debate-two-options-*-r2.md' 'Your previous answer:'
  assert_one_artifact_contains "$artifact_dir" 'codex-debate-two-options-*-r2.md' 'Other advisors:'
  assert_one_artifact_contains "$artifact_dir" 'claude-debate-two-options-*-r2.md' 'debate round 2'
  assert_one_artifact_contains "$artifact_dir" '_synthesis-debate-two-options-*.md' 'debate rounds: 1'
  assert_one_artifact_contains "$artifact_dir" '_synthesis-debate-two-options-*.md' '_final answer after debate_'

  OH_MY_SETTING_ASK_DRY_RUN=1 "$ROOT/scripts/peer-ask.sh" --repo "$project" \
    --providers 'codex:model=alpha,codex:model=beta,claude:model=alpha,claude:model=beta,antigravity' \
    --debate 1 --thread bounded-council --prompt 'Compare two options' > "$project/council.out"
  assert_file_contains "$project/council.out" 'thread: bounded-council'
  python3 - "$project/.oms/threads/bounded-council.jsonl" <<'PY' || fail 'council transcript replayed or lost turns'
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1])]
assert len([r for r in rows if r['role'] == 'question']) == 1, rows
answers = [r for r in rows if r['role'] == 'answer']
assert len(answers) == 10, answers
assert len({r['provider'] for r in answers}) == 5, answers
assert any(r.get('live') for r in rows), rows
PY
  "$ROOT/scripts/thread.sh" --repo "$project" --id bounded-council close >/dev/null
  "$ROOT/scripts/thread.sh" --repo "$project" --id bounded-council context >/dev/null ||
    fail 'closing a council must not prevent reading its history'
  if OH_MY_SETTING_ASK_DRY_RUN=1 "$ROOT/scripts/peer-ask.sh" --repo "$project" \
      --thread bounded-council --prompt 'Closed council' > "$project/closed.out" 2>&1; then
    fail 'closed council must not launch more provider calls'
  fi
  # A tracked source snapshot can have no commits. Missing HEAD remains
  # missing across rounds; it must not be mistaken for a changed revision.
  local fresh="$TMP/ask-commitless-snapshot"
  mkdir -p "$fresh"
  git -C "$fresh" init -q
  printf 'fixed source\n' > "$fresh/source.txt"
  git -C "$fresh" add --intent-to-add source.txt
  OH_MY_SETTING_ASK_DRY_RUN=1 "$ROOT/scripts/peer-ask.sh" --repo "$fresh" \
    --repo-context --providers codex,claude --debate 1 --artifact-dir "$fresh/artifacts" \
    --prompt 'Review a fixed commitless source snapshot' > "$fresh/council.out" 2>&1 ||
    fail "commitless source was falsely classified as changed: $(cat "$fresh/council.out")"
  assert_one_artifact_contains "$fresh/artifacts" '*-r2.md' 'Your previous answer:'
  bash -c '
    . "$1/scripts/lib/peer-common.sh"
    REPO="$2"; INCLUDE_STATUS=1; MA_KIND=ask
    ma_prepare_council_context
    provider_names=(); last_arts=(); alive=()
    ma_refresh_council_answers || exit 31
    printf "changed source\n" > "$REPO/source.txt"
    if ma_refresh_council_answers; then exit 32; fi
  ' council-source-guard "$ROOT" "$fresh" > "$fresh/source-guard.out" 2>&1 ||
    fail "commitless council source guard lost mutation protection: $(cat "$fresh/source-guard.out")"
  assert_file_contains "$fresh/source-guard.out" 'tracked source changed during council'
}

