make_committed_repo() {
  local project="$1"
  mkdir -p "$project"
  # -b main so tests are branch-deterministic: CI has no init.defaultBranch,
  # where plain `git init` yields 'master' and make_patch_repo's `git diff main`
  # would fatal.
  git -C "$project" init -b main >/dev/null
  printf 'base\n' > "$project/file.txt"
  git -C "$project" add file.txt
  git -C "$project" commit -m init >/dev/null
}

write_auto_update_fixture_scripts() {
  local repo="$1"
  local link_mode="${2:-ok}"
  local doctor_mode="${3:-ok}"

  mkdir -p "$repo/scripts/lib"
  cp "$ROOT/scripts/auto-update.sh" "$repo/scripts/auto-update.sh"
  cp "$ROOT/scripts/lib/install-contract.sh" "$repo/scripts/lib/install-contract.sh"
  cp "$ROOT/scripts/lib/file-lock.sh" "$repo/scripts/lib/file-lock.sh"
  cp "$ROOT/scripts/lib/poll.sh" "$repo/scripts/lib/poll.sh"
  printf 'import os; print("1 " + os.environ.get("OMS_TEST_CI_RESULT", "success"))\n' > "$repo/scripts/lib/ci-query.py"
  chmod +x "$repo/scripts/auto-update.sh"

  case "$link_mode" in
    ok)
      cat > "$repo/scripts/link.sh" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
mkdir -p "$HOME/.oms-test"
ln -sfn "$root/README.md" "$HOME/.oms-test/readme"
printf 'linked\n' > "$HOME/.oms-test/linked"
EOF
      ;;
    fail)
      cat > "$repo/scripts/link.sh" <<'EOF'
#!/usr/bin/env bash
echo "link failed intentionally" >&2
exit 7
EOF
      ;;
    *) fail "unknown fixture link mode: $link_mode" ;;
  esac
  chmod +x "$repo/scripts/link.sh"

  case "$doctor_mode" in
    ok)
      cat > "$repo/scripts/doctor.sh" <<'EOF'
#!/usr/bin/env bash
echo "doctor ok"
EOF
      ;;
    fail)
      cat > "$repo/scripts/doctor.sh" <<'EOF'
#!/usr/bin/env bash
echo "doctor warning" >&2
exit 8
EOF
      ;;
    *) fail "unknown fixture doctor mode: $doctor_mode" ;;
  esac
  chmod +x "$repo/scripts/doctor.sh"

  cat > "$repo/scripts/install-claude-hooks.sh" <<'EOF'
#!/usr/bin/env bash
mkdir -p "$HOME/.oms-test"
printf 'claude-hooks\n' >> "$HOME/.oms-test/refresh.log"
EOF
  cat > "$repo/scripts/install-codex-plugin.sh" <<'EOF'
#!/usr/bin/env bash
mkdir -p "$HOME/.oms-test"
printf 'codex-plugin\n' >> "$HOME/.oms-test/refresh.log"
EOF
  chmod +x "$repo/scripts/install-claude-hooks.sh" "$repo/scripts/install-codex-plugin.sh"
  cat > "$repo/scripts/install-tools.sh" <<'EOF'
#!/usr/bin/env bash
[ "$1" = --providers ] || exit 2
mkdir -p "$HOME/.oms-test"
printf 'providers\n' >> "$HOME/.oms-test/refresh.log"
EOF
  chmod +x "$repo/scripts/install-tools.sh"
}

setup_auto_update_fixture() {
  local origin="$1"
  local seed="$2"
  local work="$3"

  git init --bare "$origin" >/dev/null
  git init -b main "$seed" >/dev/null
  write_auto_update_fixture_scripts "$seed" ok ok
  printf 'local/\n' > "$seed/.gitignore"
  printf 'one\n' > "$seed/README.md"
  git -C "$seed" add .gitignore README.md scripts >/dev/null
  git -C "$seed" commit -m 'initial' >/dev/null
  git -C "$seed" remote add origin "$origin"
  git -C "$seed" push -u origin main >/dev/null
  git clone --branch main "$origin" "$work" >/dev/null 2>&1
}

# smoke-weight: 7
test_delegate_dry_run() {
  local project="$TMP/delegate-dry"
  local artifact_dir="$project/artifacts"

  make_committed_repo "$project"
  mkdir -p "$project/scripts"
  printf '#!/usr/bin/env bash\ncase "${1:-}" in fast) exit 0 ;; esac\n' > "$project/scripts/check.sh"
  chmod +x "$project/scripts/check.sh"
  git -C "$project" add scripts/check.sh
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' commit -qm 'add bounded check'

  if "$ROOT/scripts/peer-delegate.sh" --workload typo >"$TMP/workload.err" 2>&1; then
    fail "unknown workloads must be rejected"
  fi
  assert_file_contains "$TMP/workload.err" '--workload requires standard or routine'
  if "$ROOT/scripts/peer-delegate.sh" --workload routine --executor frozen >"$TMP/workload.err" 2>&1; then
    fail "removed Soul route must be rejected"
  fi
  assert_file_contains "$TMP/workload.err" 'unknown argument: --executor'

  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --workload routine --model exact-routine-model \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --prompt "Add a helper" >/dev/null

  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' '## Done when'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'Create project files only inside this worktree; put temporary files only under TMPDIR'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'run the tests that use them'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'docs/, README files, and the changed command usage or --help text'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'update prose describing the change'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'Save a git diff of non-test changes to a temporary patch, apply it in reverse'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'do not use git stash'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' '--section S --case NAME'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'For a Python operator section run only its marked case'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'For a shell operator section run bash tests/operator-tools-smoke.sh --section S without --case'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'For each new branch or limit, exercise its failure exit and its edge'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'For each file, ref or record your change writes'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'verify: `bash scripts/check.sh fast`'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'After you return, the harness runs `bash scripts/check.sh fast`.'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'do not run this full command just to confirm completion'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'checks restored from HEAD'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'cluster-storage paths out of added lines'
  # Panel dispatch hands the plan task's paths and declared scopes to the prompt.
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 OMS_PANEL_ALLOWED_PATHS="scripts/a.sh, tests/b.sh" \
    OMS_PANEL_FORBIDDEN_PATHS="secrets/" "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$TMP/delegate-dry-panel" --prompt "Scoped helper" >/dev/null
  assert_one_artifact_contains "$TMP/delegate-dry-panel" 'codex-scoped-helper-*.md' '- allowed paths: scripts/a.sh, tests/b.sh'
  assert_one_artifact_contains "$TMP/delegate-dry-panel" 'codex-scoped-helper-*.md' '- forbidden paths: secrets/'
  # Brief lint is advisory: a long unshaped brief warns, a short one stays quiet,
  # a shaped one is silent, and only --strict-brief refuses.
  local lint_brief="$TMP/delegate-lint-brief.md" lint_i
  : > "$lint_brief"
  for lint_i in 1 2 3 4 5 6 7 8 9; do
    printf '%s. Open the thing and change the other thing a little further down.\n' "$lint_i" >> "$lint_brief"
  done
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$TMP/delegate-lint" --brief-file "$lint_brief" >"$TMP/delegate-lint.out" 2>"$TMP/delegate-lint.err" ||
    fail "brief lint must stay advisory without --strict-brief: $(cat "$TMP/delegate-lint.err")"
  assert_file_contains "$TMP/delegate-lint.err" 'warning: brief: no stated goal'
  assert_file_contains "$TMP/delegate-lint.err" 'warning: brief: step-by-step script with no stated goal'
  assert_file_contains "$TMP/delegate-lint.err" 'warning: brief: no file path pointers'
  if OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$TMP/delegate-lint-strict" --brief-file "$lint_brief" --strict-brief >/dev/null 2>"$TMP/delegate-lint-strict.err"; then
    fail "--strict-brief must refuse a brief with lint warnings"
  fi
  assert_file_contains "$TMP/delegate-lint-strict.err" '--strict-brief: brief lint reported warnings'
  [ ! -d "$TMP/delegate-lint-strict" ] || [ -z "$(ls -A "$TMP/delegate-lint-strict")" ] ||
    fail "--strict-brief must refuse before any artifact is written"
  printf 'Goal: fix the parser.\nScope: scripts/lib/parse.py only; out of scope: tests.\nOutput: a summary of the change.\nDone when: scripts/check.sh passes.\nStart at scripts/lib/parse.py:10 and keep the change minimal for the reviewer to read.\n' > "$lint_brief"
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$TMP/delegate-lint-ok" --brief-file "$lint_brief" --strict-brief >/dev/null 2>"$TMP/delegate-lint-ok.err" ||
    fail "a shaped brief must pass --strict-brief: $(cat "$TMP/delegate-lint-ok.err")"
  ! grep -q 'warning: brief:' "$TMP/delegate-lint-ok.err" || fail "a shaped brief must lint silently"
  # Result lint: warnings on stderr, codes on stdout.
  local lint_codes
  lint_codes="$(printf 'Done.\n\n## Findings\n- bug in scripts/a.sh\n' | python3 "$ROOT/scripts/lib/delegation_lint.py" result - --writer 2>/dev/null)"
  [ "$lint_codes" = "finding-without-pointer,no-unresolved-line,no-changed-files" ] || fail "result lint codes: $lint_codes"
  lint_codes="$(printf 'Fixed the parser.\n\nChanged files: scripts/a.sh\n\n## Findings\n- scripts/a.sh:3 off by one\n\nUnresolved: none\n' | python3 "$ROOT/scripts/lib/delegation_lint.py" result - --writer 2>/dev/null)"
  [ -z "$lint_codes" ] || fail "a complete result must lint clean: $lint_codes"
  # The dry run also prints an advisory inline/researcher/worker verdict from facts.
  local advice_brief="$TMP/advice-brief.md" advice_out="$TMP/advice.out"
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$TMP/delegate-advice" --prompt "Rename one flag" >"$advice_out" 2>&1
  assert_file_contains "$advice_out" 'advice: inline'
  assert_file_contains "$advice_out" 'small sequential edit'
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" --read-only \
    --artifact-dir "$TMP/delegate-advice" --prompt "Map the callers" >"$advice_out" 2>&1
  assert_file_contains "$advice_out" 'advice: researcher'
  printf 'Update scripts/a.sh, scripts/b.sh and tests/c.sh together.\n' > "$advice_brief"
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 OMS_DELEGATE_ADVICE_SMALL_PATHS=2 "$ROOT/scripts/peer-delegate.sh" --to codex \
    --repo "$project" --artifact-dir "$TMP/delegate-advice" --brief-file "$advice_brief" --json >"$advice_out" 2>&1
  assert_file_contains "$advice_out" 'advice-json: {'
  assert_file_contains "$advice_out" '"verdict": "worker"'
  # Another claimed plan task that declares an overlapping path makes the delegate not parallel-safe.
  mkdir -p "$project/.oms/plan"
  printf '{"tasks":{"t1":{"state":"running","allowed_paths":["scripts/"]}}}\n' > "$project/.oms/plan/tasks.json"
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 OMS_DELEGATE_ADVICE_SMALL_PATHS=2 "$ROOT/scripts/peer-delegate.sh" --to codex \
    --repo "$project" --artifact-dir "$TMP/delegate-advice" --brief-file "$advice_brief" >"$advice_out" 2>&1
  assert_file_contains "$advice_out" 'advice: inline'
  assert_file_contains "$advice_out" 'overlaps active task t1'
  rm -rf "$project/.oms/plan"
  # A continuation resolves its default verifier on its recorded base, which
  # here still has the check script that HEAD has since removed.
  local with_check
  with_check="$(git -C "$project" rev-parse HEAD)"
  git -C "$project" rm -q scripts/check.sh
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' commit -qm 'drop check'
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 OMS_PANEL_CONTINUATION="{\"patch\":\".oms/missing.patch\",\"sha256\":\"$(printf '0%.0s' $(seq 64))\",\"base\":\"$with_check\"}" \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" --artifact-dir "$TMP/delegate-dry-cont" \
    --prompt "Continue the helper" >"$TMP/delegate-dry-cont.out" 2>&1 || true
  assert_file_contains "$TMP/delegate-dry-cont.out" 'auto-verify: bash scripts/check.sh fast'
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$TMP/delegate-dry-head" --prompt "Add another helper" >"$TMP/delegate-dry-head.out" 2>&1 || true
  if grep -q 'auto-verify:' "$TMP/delegate-dry-head.out"; then
    fail "HEAD without a check script must not resolve a default verifier"
  fi
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' revert --no-edit HEAD >/dev/null

  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'Do not run git commit'
  assert_file_contains "$project/.oms/artifacts/index.jsonl" 'exact-routine-model'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'Follow the repository instructions; do not re-read a file already in your context, but read any applicable instruction file that is not. Read PROJECT.md once, only if the task touches its contract.'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'Batch independent reads and searches into one tool call or parallel calls in one turn; keep dependent reads sequential.'
  # A Claude target whose repository has only AGENTS.md loads nothing itself.
  local agents_only="$TMP/delegate-agents-only"
  mkdir -p "$agents_only"
  git clone -q "$project" "$agents_only/repo"
  printf 'Project rules.\n' > "$agents_only/repo/AGENTS.md"
  rm -f "$agents_only/repo/CLAUDE.md"
  git -C "$agents_only/repo" add -A
  git -C "$agents_only/repo" -c user.email=test@example.com -c user.name='Test User' commit -qm 'agents only'
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to claude --repo "$agents_only/repo" \
    --artifact-dir "$agents_only/art" --prompt "Add a claude helper" >/dev/null
  assert_one_artifact_contains "$agents_only/art" 'claude-add-a-claude-helper-*.md' \
    'read any applicable instruction file that is not.'
  # A provider whose auto-load is unconfirmed keeps the read instruction.
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to antigravity --repo "$project" \
    --artifact-dir "$TMP/delegate-dry-agy" --prompt "Add an agy helper" >/dev/null
  assert_one_artifact_contains "$TMP/delegate-dry-agy" 'antigravity-add-an-agy-helper-*.md' \
    'Read applicable repository instructions and PROJECT.md.'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'preserve contracts and safety, reuse existing tests, and run affected checks'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' \
    'Report changes, evidence, verification and uncertainty'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'DRY RUN: worker command skipped.'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' '(path omitted)'
  assert_one_artifact_contains "$artifact_dir" 'codex-add-a-helper-*.md' 'worktree: temporary (removed after run)'
  if grep -rFq "$project" "$artifact_dir"/codex-add-a-helper-*.md; then
    fail "delegate artifact must not record the absolute repo path"
  fi
  local patch
  patch="$(find "$artifact_dir" -type f -name 'codex-add-a-helper-*.patch' | sed -n '1p')"
  [ -n "$patch" ] || fail "missing delegate patch artifact"
  [ ! -s "$patch" ] || fail "dry-run patch should be empty"
  [ -z "$(git -C "$project" status --porcelain file.txt)" ] || fail "delegate dry-run touched main tree"

  "$ROOT/scripts/agent-task.sh" --repo "$project" init \
    --goal 'Dry run verification' --next 'Inspect dry run report' >/dev/null
  local out
  out="$("$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --artifact-dir "$artifact_dir" --dry-run --verify 'exit 91' --repair 2 \
    --prompt 'Dry run verify')"
  contains "$out" 'verify: NOT RUN (dry run)' || fail "dry-run verification status missing: $out"
  if contains "$out" 'verify: exit 0'; then
    fail "dry-run verification reported a pass: $out"
  fi
  assert_one_artifact_contains "$artifact_dir" 'codex-dry-run-verify-*.md' 'DRY RUN: verify skipped.'
  assert_one_artifact_contains "$artifact_dir" 'codex-dry-run-verify-*.md' 'verify: `exit 91`'
  assert_file_contains "$project/.oms/task/current.md" 'verify=NOT RUN (dry run)'

  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY_DRY' || fail "dry-run verify receipt reported a pass"
import json, pathlib, sys
row = json.loads(pathlib.Path(sys.argv[1]).read_text().splitlines()[-1])
assert 'verify_exit' not in row, row
assert 'repair_replay' not in row, row
PY_DRY

  "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" --artifact-dir "$artifact_dir" \
    --dry-run --no-verify --prompt 'No verify prompt' >/dev/null
  artifact="$(find "$artifact_dir" -maxdepth 1 -name 'codex-no-verify-prompt-*.md' | sed -n '1p')"
  [ -n "$artifact" ] || fail "no-verify prompt artifact missing"
  if grep -Fq -- '- verify:' "$artifact"; then fail "--no-verify prompt printed a verify line"; fi

  mkdir -p "$project/cap"
  printf 'gpt-5.6-sol\ngpt-5.6-terra\ngpt-5.6-luna\n' > "$project/cap/codex.models"
  OMS_CAPABILITY_DIR="$project/cap" OH_MY_SETTING_DELEGATE_DRY_RUN=1 \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --workload routine --prompt "Routine route probe" >/dev/null
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "routine flag did not reach the resolved route"
import json, sys
with open(sys.argv[1], encoding="utf-8") as handle:
    row = json.loads(handle.readlines()[-1])
assert row["requested_model"] == "gpt-5.6-luna", row
assert row["model_class"] == "role-default", row
PY
}

# smoke-weight: 5
test_delegate_read_only_rejects_apply() {
  local project="$TMP/delegate-read-only"
  local out artifact

  make_committed_repo "$project"
  # Authority comes from the caller, and the two flags contradict: a
  # read-only worker produces a report, never a patch to apply.
  if OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --to codex --repo "$project" --prompt "Audit the tree" \
      --read-only --apply >/dev/null 2>"$project/err"; then
    fail "--read-only with --apply must be rejected"
  fi
  assert_file_contains "$project/err" "--read-only produces no patch"

  out="$(OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --prompt "Audit the tree" --read-only)"
  contains "$out" 'patch: none (read-only)' || fail "read-only patch status missing: $out"
  contains "$out" 'effort=medium / read' || fail "resolved default read effort missing: $out"
  if contains "$out" 'patch-land' || contains "$out" 'applied:'; then
    fail "read-only run must not suggest patch landing: $out"
  fi
  [ -z "$(find "$project/.oms/artifacts/delegate" -name '*.patch')" ] ||
    fail "read-only run created a patch"
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY_READ' || fail "read-only index lost report lineage"
import json, pathlib, sys
row = json.loads(pathlib.Path(sys.argv[1]).read_text().splitlines()[-1])
assert row['kind'] == 'delegate' and row['artifact_sha256'], row
assert not any(k.startswith('patch') for k in row), row
assert row['reasoning_effort'] == 'medium', row
PY_READ

  out="$(OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --prompt "Explicit effort audit" --read-only \
    --reasoning-effort high)"
  contains "$out" 'effort=high / read' || fail "explicit read effort missing: $out"

  local bin_dir="$project/bin" home_dir="$project/home"
  mkdir -p "$bin_dir" "$home_dir"
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
prompt="$(cat)"
[ -n "$prompt" ] || exit 0
python3 - "$OMS_TEST_DELEGATIONS" "$HOME/access-observed" <<'PYACCESS'
import json, pathlib, sys
rows = [json.loads(p.read_text()) for p in pathlib.Path(sys.argv[1]).glob('*.json')]
assert len(rows) == 1, rows
pathlib.Path(sys.argv[2]).write_text(rows[0].get('access', 'missing'))
PYACCESS
if [ ! -f "$HOME/first-attempt" ]; then
  touch "$HOME/first-attempt"
  echo 'temporary fixture failure'
  exit 1
fi
echo 'repaired read-only report'
EOF
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_TEST_DELEGATIONS="$project/.oms/delegations" "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt 'Read-only repair' --read-only --repair 1)"
  [ "$(cat "$home_dir/access-observed")" = read ] || fail "read delegation marker access missing"
  contains "$out" 'repair: 1/1 round(s) used' || fail "read-only repair failed: $out"
  contains "$out" 'effort=medium / read' || fail "actual read effort missing: $out"
  artifact="$(printf '%s\n' "$out" | sed -n 's/^artifact: //p')"
  assert_file_contains "$artifact" 'model-route:'
  assert_file_contains "$artifact" 'effort=medium'
  assert_file_contains "$artifact" 'None (read-only report).'
  assert_file_contains "$artifact" 'repaired read-only report'
  [ -z "$(find "$project/.oms/artifacts/delegate" -name '*.patch')" ] ||
    fail "read-only repair created a patch"

  if OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --read-only --prompt 'api_t'"oken=fixture-secret" \
    >"$project/blocked.out" 2>&1; then
    fail "sensitive read-only prompt must be blocked"
  fi
  assert_file_contains "$project/blocked.out" 'patch: none (read-only)'
  [ -z "$(find "$project/.oms/artifacts/delegate" -name '*.patch')" ] ||
    fail "blocked read-only run created a patch"

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_TEST_DELEGATIONS="$project/.oms/delegations" "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --prompt 'Write marker audit' --allow-no-change --no-verify \
    >/dev/null || fail "write marker delegation failed"
  [ "$(cat "$home_dir/access-observed")" = write ] || fail "write delegation marker access missing"

}

test_delegate_embeds_review_findings() {
  local project="$TMP/delegate-review-uptake"
  local artifact_dir="$project/artifacts"
  local review="$project/review-synthesis.md"

  make_committed_repo "$project"
  printf '# Review synthesis\n\nMust-fix: the loop off-by-one in foo().\n' > "$review"
  printf 'Diagnostic: /ho''me/fixture/project/report.md\napi_t''oken=fixture-only\n' >> "$review"
  printf '%s' 'Final finding without newline.' >> "$review"

  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --review-artifact "$review" \
    --prompt "Fix per review" >/dev/null

  # Findings live inside the worker brief, not in a side artifact the worker
  # may ignore; the index row keeps review->patch lineage joinable.
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' 'Review findings to address'
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' 'the loop off-by-one in foo()'
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' 'Untrusted reviewer claims'
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' '<PATH>'
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' 'Final finding without newline.'
  # The quote ends at an id-carrying close on its own line even when the
  # source lacks a final newline; one-shot workers get the unattended stop rule.
  grep -Eq '^\[end untrusted reviewer findings from peer review id=[0-9a-f]{8}\]$' \
    "$artifact_dir"/codex-fix-per-review-*.md || fail "review findings lack their id-carrying close line"
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' 'Ending your turn ends the task'
  assert_one_artifact_contains "$artifact_dir" 'codex-fix-per-review-*.md' '[REDACTED:'
  if grep -F 'fixture-only' "$artifact_dir"/*.md >/dev/null; then
    fail "review quote leaked sensitive reference data"
  fi
  grep -F 'fixture-only' "$review" >/dev/null || fail "quoting modified the source evidence"
  if OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --artifact-dir "$artifact_dir" \
    --review-artifact "$review" --prompt 'api_t'"oken=operator-private" >/dev/null 2>&1; then
    fail "quote sanitization must not bypass operator prompt validation"
  fi
  grep -Fq '"source": "review-synthesis.md"' "$project/.oms/artifacts/index.jsonl" ||
    fail "delegation index row must record the review artifact as its source"

  # Long reviews keep their first actionable finding with one honest bound.
  python3 - "$review" <<'PY_REVIEW'
from pathlib import Path
import sys
Path(sys.argv[1]).write_text('Must-fix: FIRST-FINDING\n' + 'safe reference detail\n' * 1000)
PY_REVIEW
  OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --artifact-dir "$artifact_dir" \
    --review-artifact "$review" --prompt "Long review" >/dev/null
  assert_one_artifact_contains "$artifact_dir" 'codex-long-review-*.md' 'FIRST-FINDING'
  assert_one_artifact_contains "$artifact_dir" 'codex-long-review-*.md' '[TRUNCATED:'

  # Redaction may shrink enough text to expose a cut token's short prefix.
  python3 - "$review" <<'PY_REVIEW'
from pathlib import Path
import sys
Path(sys.argv[1]).write_text('api_' + 'to' + 'ken=' + 'x' * 12072 + '\n' + 'gh' + 'p_' + '1' * 30)
PY_REVIEW
  (
    . "$ROOT/scripts/lib/peer-common.sh"
    OMS_PROMPT_QUOTE_BYTES=8000 ma_sanitize_quoted_output head < "$review"
  ) > "$project/head-quote.txt"
  if grep -F 'ghp_' "$project/head-quote.txt" >/dev/null; then
    fail "head clipping exposed a partial sensitive line"
  fi
  assert_file_contains "$project/head-quote.txt" '[REDACTED:'

  # A missing review artifact is misuse, caught before any worker runs.
  if OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --artifact-dir "$artifact_dir" \
    --review-artifact "$project/absent.md" --prompt x >/dev/null 2>&1; then
    fail "--review-artifact with a missing file must be rejected"
  fi
}

# smoke-weight: 22
test_delegate_fake_worker_apply() {
  local project="$TMP/delegate-apply"
  # Landing requires the main tree to stay clean, including untracked files;
  # keep caller-selected artifacts outside the repository for this success case.
  local artifact_dir="$TMP/delegate-apply-artifacts"
  local bin_dir="$TMP/delegate-apply-bin"
  local home_dir="$TMP/delegate-apply-home"

  make_committed_repo "$project"
  mkdir -p "$project/tests"
  printf 'assert() { test -f file.txt; }\nassert\nassert\n' > "$project/tests/verify.sh"
  git -C "$project" add tests/verify.sh
  git -C "$project" commit -qm 'verification fixture'
  git -C "$project" config diff.noprefix true
  mkdir -p "$bin_dir" "$home_dir"
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
printf 'hello from worker\n' > delegated.txt
printf 'assert() { test -f file.txt; }\nassert\n' > tests/verify.sh
echo "worker done"
EOF

  local consent out
  for consent in none --allow-verifier-change --allow-test-reduction; do
    local -a consent_args
    consent_args=()
    [ "$consent" = none ] || consent_args=("$consent")
    out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
      --artifact-dir "$artifact_dir" --apply --allow-restructure \
      --verify "bash tests/verify.sh" ${consent_args[@]+"${consent_args[@]}"} --prompt "Create delegated file" 2>&1)" || true
    [ ! -f "$project/delegated.txt" ] || fail "apply bypassed missing consent ($consent): $out"
    contains "$out" 'patch-land rejected' || fail "missing consent did not reach admission: $out"
  done

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --apply \
    --allow-restructure --allow-verifier-change --allow-test-reduction \
    --verify "bash tests/verify.sh" \
    --prompt "Create delegated file" >/dev/null

  [ -f "$project/delegated.txt" ] || fail "applied patch should create delegated.txt in main tree"
  assert_file_contains "$project/delegated.txt" "hello from worker"
  assert_one_artifact_contains "$artifact_dir" 'codex-create-delegated-file-*.md' 'worker done'
  # The terse worker answer is linted and the warning codes ride on the index row.
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "delegate row must record result_lint"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1]) if line.strip()]
row = [r for r in rows if r.get("kind") == "delegate" and r.get("exit") == 0][-1]
assert row.get("result_lint") == ["no-unresolved-line", "no-changed-files"], row
PY
}

test_delegate_nested_apply_preserves_parent_only_capture_guard() {
  local project="$TMP/delegate-nested-apply"
  local artifact_dir="$TMP/delegate-nested-apply-artifacts"
  local bin_dir="$TMP/delegate-nested-apply-bin"
  local home_dir="$TMP/delegate-nested-apply-home"
