cat >/dev/null
printf 'must stay in worker worktree\n' > nested.txt
echo "nested worker done"
EOF

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
