test_agent_memory_append_show_and_rejects_sensitive() {
  local project="$TMP/agent-memory"
  local home_dir="$project/home"
  mkdir -p "$project" "$home_dir"

  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" append --agent codex --text "Prefer scripts/check.sh fast before done." >/dev/null

  [ -f "$project/.oms/memory/shared.md" ] || fail "project memory file missing"
  [ -f "$project/.oms/memory/summary.md" ] || fail "compact memory summary missing"
  assert_file_contains "$project/.oms/memory/shared.md" "Prefer scripts/check.sh fast before done."
  assert_file_contains "$project/.oms/memory/summary.md" "Prefer scripts/check.sh fast before done."

  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" pin --agent codex --text "Current task context should stay compact." >/dev/null
  [ -f "$project/.oms/memory/pins.md" ] || fail "pinned memory file missing"
  assert_file_contains "$project/.oms/memory/pins.md" "Current task context should stay compact."

  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" show >"$project/out"
  assert_file_contains "$project/out" "Shared Agent Memory"

  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" context >"$project/context"
  assert_file_contains "$project/context" "Compact recent:"
  assert_file_contains "$project/context" "Pinned:"
  if grep -Fq "Shared Agent Memory" "$project/context"; then
    fail "compact context should not include full shared.md header"
  fi

  if HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" append --agent codex --text "private path /hom""e/researcher/secret" \
    >"$project/sensitive-out" 2>"$project/sensitive-err"; then
    fail "sensitive-looking memory note should be rejected"
  fi
  assert_file_contains "$project/sensitive-err" "sensitive-looking content"

  if HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" append --agent codex --text "<!-- oms-memory" \
    >"$project/reserved-out" 2>"$project/reserved-err"; then
    fail "the reserved provenance marker must not be accepted as note text"
  fi
  assert_file_contains "$project/reserved-err" "reserved memory metadata marker"

  # A failing scanner must refuse the write, not read as clean.
  local shim="$project/scan-shim" before
  mkdir -p "$shim"
  printf '#!/bin/sh\nexit 1\n' > "$shim/python3"
  chmod +x "$shim/python3"
  before="$(cksum < "$project/.oms/memory/shared.md")"
  if PATH="$shim:$PATH" HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" append --agent codex --text "ordinary note after scanner failure" \
    >"$project/scanfail-out" 2>"$project/scanfail-err"; then
    fail "append must refuse when the sensitive-content scan fails"
  fi
  assert_file_contains "$project/scanfail-err" "scan failed"
  [ "$(cksum < "$project/.oms/memory/shared.md")" = "$before" ] ||
    fail "memory must stay unchanged when the scan fails"

  # Plain `if` callers are fail-closed; the _status form keeps the raw 2.
  printf 'ordinary note\n' > "$project/plain-note"
  PATH="$shim:$PATH" bash -c '
    . "$1/scripts/lib/agent-memory-common.sh"
    if agent_memory_file_has_sensitive_content "$2" 2>"$3"; then exit 0; fi
    exit 9' _ "$ROOT" "$project/plain-note" "$project/plain-err" ||
    fail "plain sensitive-content predicate must treat a failed scan as sensitive"
  assert_file_contains "$project/plain-err" "treating the content as sensitive"
  local status_rc=0
  PATH="$shim:$PATH" bash -c '
    . "$1/scripts/lib/agent-memory-common.sh"
    agent_memory_file_sensitive_status "$2"' _ "$ROOT" "$project/plain-note" || status_rc=$?
  [ "$status_rc" -eq 2 ] || fail "status form must keep returning 2, got $status_rc"
}

test_agent_memory_indexes_existing_logs_in_sqlite() {
  local project="$TMP/agent-memory-db"
  local home_dir="$project/home"
  local db
  local out

  mkdir -p "$project/.oms/memory" "$home_dir"
  cat > "$project/.oms/memory/shared.md" <<'EOF'
# Shared Agent Memory

- scope: project

## 2026-07-01T00:00:00Z claude

Keep the legacy split policy stable.

## 2026-07-02T00:00:00Z codex

Use SQLite for durable project recall.

EOF
  cat > "$project/.oms/memory/pins.md" <<'EOF'
# Pinned Agent Memory

- scope: project

- 2026-07-03T00:00:00Z [antigravity] Keep the migration reversible.
EOF

  db="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" db-path)"
  [ "$db" = "$project/.oms/memory/memory.sqlite3" ] ||
    fail "project memory database path is wrong: $db"
  [ ! -e "$db" ] || fail "db-path must stay read-only"

  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" \
    search --agent claude --text "legacy split")" ||
    fail "database-backed search should migrate existing logs: $out"
  contains "$out" 'Keep the legacy split policy stable.' ||
    fail "migrated search missed the legacy shared entry: $out"
  [ -f "$db" ] || fail "search should create the project memory database"

  python3 - "$db" <<'PY' || fail "memory database schema/content is invalid"
import sqlite3
import sys

db = sqlite3.connect(sys.argv[1])
assert db.execute("pragma user_version").fetchone()[0] == 3
rows = db.execute(
    "select source, agent, body from memory_entries order by source, ordinal"
).fetchall()
assert len(rows) == 3, rows
assert {row[0] for row in rows} == {"shared", "pins"}, rows
assert any(row[1] == "antigravity" and "reversible" in row[2] for row in rows), rows
PY

  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent codex --text "Index new notes immediately." >/dev/null
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" pin \
    --agent claude --text "Pinned rows belong in the same database." >/dev/null
  python3 - "$db" <<'PY' || fail "append/pin did not refresh the memory database"
import sqlite3
import sys

db = sqlite3.connect(sys.argv[1])
text = "\n".join(row[0] for row in db.execute("select body from memory_entries"))
assert "Index new notes immediately." in text, text
assert "Pinned rows belong in the same database." in text, text
PY
}

test_agent_memory_health_is_read_only_and_detects_staleness() {
  local empty_project="$TMP/agent-memory-health-empty"
  local project="$TMP/agent-memory-health"
  local home_dir="$project/home"
  local index="$project/.oms/memory/memory.sqlite3"
  local out
  local before
  local after
  local rc=0

  mkdir -p "$empty_project"
  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$empty_project" --json health)" ||
    fail "empty memory health should be a clean read: $out"
  if ! OMS_MEMORY_HEALTH_JSON="$out" python3 - <<'PY'
import json
import os

report = json.loads(os.environ["OMS_MEMORY_HEALTH_JSON"])
assert report["schema"] == 1 and report["action"] == "health", report
assert report["status"] == "empty", report
assert report["index"]["present"] is False, report
assert report["assessment"] == "index-health-not-memory-quality", report
PY
  then
    fail "empty memory health JSON is incomplete"
  fi
  [ ! -e "$empty_project/.oms" ] ||
    fail "health must not create project state for an empty memory"

  mkdir -p "$project/.oms/memory" "$home_dir"
  cat > "$project/.oms/memory/shared.md" <<'EOF'
# Shared Agent Memory

- scope: project

## 2026-07-01T00:00:00Z codex

Keep memory health read-only.
EOF
  cat > "$project/.oms/memory/pins.md" <<'EOF'
# Pinned Agent Memory

- scope: project

- 2026-07-01T00:00:01Z [claude] Preserve the source logs.
EOF
  cat > "$project/.oms/failures.jsonl" <<'EOF'
{"event":"fail","fingerprint":"fp-1","ts":"2026-07-01T00:00:02Z","agent":"codex","cmd":"false","exit":1,"summary":"fixture failed"}
{"event":"resolved","fingerprint":"fp-1","ts":"2026-07-01T00:00:03Z"}
EOF
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" rebuild >/dev/null

  before="$(find "$project/.oms" -type f -print | LC_ALL=C sort |
    while IFS= read -r file; do cksum "$file"; done)"
  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" --json health)" ||
    fail "current memory health should pass: $out"
  after="$(find "$project/.oms" -type f -print | LC_ALL=C sort |
    while IFS= read -r file; do cksum "$file"; done)"
  [ "$before" = "$after" ] ||
    fail "health must not mutate source or derived memory state"
  if ! OMS_MEMORY_HEALTH_JSON="$out" python3 - <<'PY'
import json
import os

report = json.loads(os.environ["OMS_MEMORY_HEALTH_JSON"])
assert report["status"] == "healthy", report
assert report["index"]["present"] is True, report
assert report["index"]["readable"] is True, report
assert report["index"]["current"] is True, report
assert report["index"]["schema_version"] == 3, report
assert report["index"]["expected_schema"] == 3, report
assert report["index"]["integrity"] == "ok", report
assert report["index"]["entries"] == 3, report
assert report["index"]["by_source"] == {
    "shared": 1, "pins": 1, "failures": 1
}, report
assert report["sources"]["shared"]["entries"] == 1, report
assert report["sources"]["pins"]["entries"] == 1, report
assert report["sources"]["failures"]["entries"] == 1, report
assert report["failures"] == {
    "valid_rows": 2,
    "invalid_rows": 0,
    "open_fingerprints": 0,
    "resolved_fingerprints": 1,
}, report
assert report["index"]["provenance"]["total"] == 3, report
PY
  then
    fail "healthy memory report lost source/index evidence"
  fi

  cat >> "$project/.oms/memory/shared.md" <<'EOF'

## 2026-07-01T00:00:04Z codex

This source now differs from the derived index.
EOF
  before="$(find "$project/.oms" -type f -print | LC_ALL=C sort |
    while IFS= read -r file; do cksum "$file"; done)"
  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" --json health)" || rc=$?
  [ "$rc" -eq 1 ] || fail "stale memory health should exit 1, got $rc: $out"
  after="$(find "$project/.oms" -type f -print | LC_ALL=C sort |
    while IFS= read -r file; do cksum "$file"; done)"
  [ "$before" = "$after" ] ||
    fail "stale health detection must not repair or mutate the index"
  if ! OMS_MEMORY_HEALTH_JSON="$out" python3 - <<'PY'
import json
import os

report = json.loads(os.environ["OMS_MEMORY_HEALTH_JSON"])
assert report["status"] == "stale", report
assert report["index"]["current"] is False, report
assert report["sources"]["shared"]["entries"] == 2, report
assert report["index"]["by_source"]["shared"] == 1, report
PY
  then
    fail "stale memory health JSON is incomplete"
  fi

  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" health 2>/dev/null)" || true
  contains "$out" 'memory health: stale' ||
    fail "human health output should name the stale state: $out"
  [ -f "$index" ] || fail "health must never remove the derived index"

  printf 'not-json\n' >> "$project/.oms/failures.jsonl"
  rc=0
  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" --json health)" || rc=$?
  [ "$rc" -eq 1 ] || fail "malformed ledger health should exit 1, got $rc: $out"
  if ! OMS_MEMORY_HEALTH_JSON="$out" python3 - <<'PY'
import json
import os

report = json.loads(os.environ["OMS_MEMORY_HEALTH_JSON"])
assert report["status"] == "degraded", report
assert report["failures"]["invalid_rows"] == 1, report
assert "failure-ledger-invalid" in report["problems"], report
PY
  then
    fail "malformed failure-ledger evidence should degrade memory health"
  fi
}

test_agent_memory_upgrades_schema_one_database() {
  local project="$TMP/agent-memory-db-v1"
  local home_dir="$project/home"
  local db="$project/.oms/memory/memory.sqlite3"
  local shared="$project/.oms/memory/shared.md"
  local out

  mkdir -p "$project/.oms/memory" "$home_dir"
  cat > "$shared" <<'EOF'
# Shared Agent Memory

- scope: project

## 2026-07-01T00:00:00Z codex

Keep the schema-one memory available.

EOF
  python3 - "$db" "$shared" <<'PY'
import hashlib
import os
import sqlite3
import sys

db_path, source = sys.argv[1:]
raw = open(source, "rb").read()
info = os.stat(source)
mtime_ns = getattr(info, "st_mtime_ns", int(info.st_mtime * 1_000_000_000))
db = sqlite3.connect(db_path)
db.executescript(
    """
    create table memory_sources (
      source text primary key,
      path text not null,
      size integer not null,
      mtime_ns integer not null,
      digest text not null
    );
    create table memory_entries (
      id integer primary key,
      source text not null,
      ordinal integer not null,
      occurred_at text not null,
      agent text not null,
      body text not null,
      rendered text not null,
      unique (source, ordinal)
    );
    pragma user_version = 1;
    """
)
db.execute(
    "insert into memory_sources values (?, ?, ?, ?, ?)",
    ("shared", os.path.realpath(source), len(raw), mtime_ns, hashlib.sha256(raw).hexdigest()),
)
db.execute(
    "insert into memory_entries "
    "(source, ordinal, occurred_at, agent, body, rendered) values (?, ?, ?, ?, ?, ?)",
    (
        "shared",
        0,
        "2026-07-01T00:00:00Z",
        "codex",
        "Keep the schema-one memory available.",
        "## 2026-07-01T00:00:00Z codex\n\nKeep the schema-one memory available.",
    ),
)
db.commit()
db.close()
PY

  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" \
    search --text "schema-one")" ||
    fail "schema-one memory should migrate automatically: $out"
  contains "$out" 'Keep the schema-one memory available.' ||
    fail "automatic migration lost the existing memory: $out"

  python3 - "$db" <<'PY' || fail "schema-one database did not migrate cleanly"
import sqlite3
import sys

db = sqlite3.connect(sys.argv[1])
assert db.execute("pragma user_version").fetchone()[0] == 3
columns = {
    row[1] for row in db.execute("pragma table_info(memory_entries)")
}
assert {
    "event_id", "kind", "task_id", "session_hash",
    "git_sha", "git_dirty", "git_state",
}.issubset(columns), columns
row = db.execute(
    "select event_id, kind, task_id, session_hash, git_sha, git_dirty, git_state "
    "from memory_entries"
).fetchone()
assert row[0].startswith("legacy:shared:0:"), row
assert row[1:] == ("note", "", "", "", None, ""), row
PY
}

test_agent_memory_records_git_and_task_provenance() {
  local project="$TMP/agent-memory-provenance"
  local home_dir="$project/home"
  local db="$project/.oms/memory/memory.sqlite3"
  local source_session="0123456789abcdef"
  local task_id
  local sha
  local json_out
  local before_ids
  local after_ids
  local context

  make_committed_repo "$project"
  mkdir -p "$home_dir"
  HOME="$home_dir" "$ROOT/scripts/agent-task.sh" --repo "$project" init \
    --goal "Record memory provenance" --source-session "$source_session" >/dev/null
  task_id="$(awk -F': ' '/^- task_id:/{print $2; exit}' "$project/.oms/task/current.md")"
  sha="$(git -C "$project" rev-parse HEAD)"
  printf 'dirty work\n' >> "$project/file.txt"

  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent codex --text "Remember the dirty implementation state." >/dev/null
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" pin \
    --agent claude --text "Keep provenance compact." >/dev/null
  HOME="$home_dir" "$ROOT/scripts/agent-task.sh" --repo "$project" close >/dev/null

  assert_file_contains "$project/.oms/memory/shared.md" "<!-- oms-memory"
  assert_file_contains "$project/.oms/memory/shared.md" "git_sha: $sha"
  assert_file_contains "$project/.oms/memory/shared.md" "task_id: $task_id"

  context="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" context)"
  if contains "$context" 'oms-memory'; then
    fail "structured provenance must not consume compact provider context"
  fi
  if contains "$context" 'git_sha:'; then
    fail "git provenance must stay out of compact provider context"
  fi

  json_out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" \
    --json search --text "dirty implementation")" ||
    fail "structured search should return the appended note: $json_out"
  if ! OMS_MEMORY_JSON="$json_out" \
    python3 - "$sha" "$task_id" "$source_session" <<'PY'
import json
import os
import sys

expected_sha, expected_task, expected_session = sys.argv[1:]
row = json.loads(os.environ["OMS_MEMORY_JSON"])
assert row["schema"] == 3, row
assert row["event_id"].startswith("mem-"), row
assert row["kind"] == "note", row
assert row["task_id"] == expected_task, row
assert row["session_hash"] == expected_session, row
assert row["git_sha"] == expected_sha, row
assert row["git_dirty"] is True, row
assert row["git_state"].startswith(expected_sha + ":"), row
PY
  then
    fail "JSON search did not expose stable provenance"
  fi

  if ! python3 - "$db" "$sha" "$task_id" "$source_session" <<'PY'
import sqlite3
import sys

db_path, expected_sha, expected_task, expected_session = sys.argv[1:]
db = sqlite3.connect(db_path)
assert db.execute("pragma user_version").fetchone()[0] == 3
rows = db.execute(
    "select event_id, source, ordinal, kind, task_id, session_hash, "
    "git_sha, git_dirty, git_state, body "
    "from memory_entries order by occurred_at, source, ordinal"
).fetchall()
assert len(rows) == 3, rows
assert len({row[0] for row in rows}) == 3, rows
assert {row[3] for row in rows} == {"note", "pin", "task_close"}, rows
for row in rows:
    assert row[4] == expected_task, row
    assert row[5] == expected_session, row
    assert row[6] == expected_sha, row
    assert row[7] == 1, row
    assert row[8].startswith(expected_sha + ":"), row
PY
  then
    fail "append, pin, and task close provenance is incomplete"
  fi

  before_ids="$(python3 - "$db" <<'PY'
import sqlite3, sys
db = sqlite3.connect(sys.argv[1])
print("\n".join(row[0] for row in db.execute(
    "select event_id from memory_entries order by source, ordinal"
)))
PY
)"
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" rebuild >/dev/null
  after_ids="$(python3 - "$db" <<'PY'
import sqlite3, sys
db = sqlite3.connect(sys.argv[1])
print("\n".join(row[0] for row in db.execute(
    "select event_id from memory_entries order by source, ordinal"
)))
PY
)"
  [ "$before_ids" = "$after_ids" ] ||
    fail "rebuild must preserve stable memory event ids"
}

test_agent_memory_db_preserves_search_and_adds_ranked_recall() {
  local project="$TMP/agent-memory-recall"
  local home_dir="$project/home"
  local db="$project/.oms/memory/memory.sqlite3"
  local out

  mkdir -p "$project" "$home_dir"
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent codex --text "Use pgvector only after lexical recall has evidence." >/dev/null
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent claude --text "SQLite full text recall keeps the local baseline cheap." >/dev/null

  # Existing search is a case-insensitive substring contract, including a
  # substring that begins inside a token; moving to FTS must not narrow it.
  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" \
    search --text "GVector only")" ||
    fail "database search should preserve substring matching: $out"
  contains "$out" 'Use pgvector only after lexical recall has evidence.' ||
    fail "substring search changed during database migration: $out"

  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" \
    recall --limit 1 --text "sqlite full text")" ||
    fail "ranked recall should return a database result: $out"
  contains "$out" 'SQLite full text recall keeps the local baseline cheap.' ||
    fail "ranked recall returned the wrong entry: $out"

  # The database is derived. Rebuilding it must recover from a damaged index
  # without touching either append-only Markdown source.
  printf 'not a sqlite database\n' > "$db"
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" rebuild >/dev/null ||
    fail "rebuild should recover a damaged derived database"
  out="$(HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" \
    search --text "local baseline")" ||
    fail "rebuilt database should be searchable: $out"
  contains "$out" 'SQLite full text recall keeps the local baseline cheap.' ||
    fail "rebuild lost source memory: $out"
}

# smoke-weight: 6
test_agent_memory_database_concurrent_appends_converge() {
  local project="$TMP/agent-memory-db-race"
  local home_dir="$project/home"
  local append_pids=""
  local pid
  local status=0
  local i=0

  mkdir -p "$project" "$home_dir"
  while [ "$i" -lt 12 ]; do
    HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
      --agent codex --text "parallel memory note $i" >/dev/null 2>&1 &
    append_pids="$append_pids $!"
    i=$((i + 1))
  done
  for pid in $append_pids; do
    wait "$pid" || status=1
  done
  [ "$status" -eq 0 ] || fail "a concurrent memory append failed"

  # A final read synchronizes any source append whose process exited after
  # writing Markdown but before winning the SQLite transaction.
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" \
    search --text "parallel memory note" >/dev/null ||
    fail "concurrent notes should remain searchable"
  python3 - "$project/.oms/memory/memory.sqlite3" <<'PY' || fail "concurrent database index is incomplete or corrupt"
import sqlite3
import sys

db = sqlite3.connect(sys.argv[1])
assert db.execute("pragma integrity_check").fetchone()[0] == "ok"
rows = db.execute(
    "select event_id, ordinal, body from memory_entries "
    "where body like 'parallel memory note %' order by ordinal"
).fetchall()
assert len(rows) == 12, rows
assert len({row[0] for row in rows}) == 12, rows
assert [row[1] for row in rows] == list(range(12)), rows
assert len({row[2] for row in rows}) == 12, rows
PY
}


test_agent_task_init_context_and_rejects_sensitive() {
  local project="$TMP/agent-task"
  mkdir -p "$project"

  "$ROOT/scripts/agent-task.sh" \
    --repo "$project" \
    init \
    --agent codex \
    --goal "Implement an ML-focused agent harness" \
    --constraint "Keep provider context compact" \
    --done "agent-task context is available" \
    --verify "bash scripts/check.sh ml-smoke" \
    --decision "Use active task packet before larger task registry" \
    --state "Memory and delegation already exist" \
    --next "Wire task context into provider calls" >/dev/null

  [ -f "$project/.oms/task/current.md" ] || fail "task file missing"
  assert_file_contains "$project/.oms/task/current.md" "Implement an ML-focused agent harness"
  assert_file_contains "$project/.oms/task/current.md" "Use active task packet before larger task registry"
  assert_file_contains "$project/.oms/task/current.md" "## Loop State"
  assert_file_contains "$project/.oms/task/current.md" "## Last Failure"
  assert_file_contains "$project/.oms/task/current.md" "## Verification"

  "$ROOT/scripts/agent-task.sh" --repo "$project" context >"$project/context"
  assert_file_contains "$project/context" "Active task packet follows"
  assert_file_contains "$project/context" "Wire task context into provider calls"
  # A Verify contract that never passed is a claim, not a checkpoint: every
  # resume surface reaching this context sees the reminder.
  assert_file_contains "$project/context" \
    'verification: none — run `oms agent-task verify` before building on this packet'

  if "$ROOT/scripts/agent-task.sh" \
    --repo "$project" append --text "private path /hom""e/researcher/secret" \
    >"$project/sensitive-out" 2>"$project/sensitive-err"; then
    fail "sensitive-looking task note should be rejected"
  fi
  assert_file_contains "$project/sensitive-err" "sensitive-looking content"
}

test_agent_task_loop_state_and_warnings() {
  local project="$TMP/agent-task-loop"
  local home_dir="$project/home"
  local artifact_dir="$project/artifacts"

  make_committed_repo "$project"
  mkdir -p "$home_dir"

  "$ROOT/scripts/agent-task.sh" \
    --repo "$project" \
    init \
    --loop-attempts 3 \
    --loop-max 3 \
    --diff-budget 1 \
    --verify-level "focused-test" \
    --last-failure "bash scripts/check.sh fast exit=1" \
    --verification "bash -n scripts/*.sh passed" \
    --hypothesis "failure is from missing guard" \
    --result "guard still missing" >/dev/null

  "$ROOT/scripts/agent-task.sh" --repo "$project" update \
    --last-failure "bash scripts/check.sh fast exit=1" >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$project" update \
    --last-failure "bash scripts/check.sh fast exit=1" >/dev/null

  assert_file_contains "$project/.oms/task/current.md" "- attempts: 3"
  assert_file_contains "$project/.oms/task/current.md" "- max_attempts: 3"
  assert_file_contains "$project/.oms/task/current.md" "- diff_budget_lines: 1"
  assert_file_contains "$project/.oms/task/current.md" "- verification_level: focused-test"
  assert_file_contains "$project/.oms/task/current.md" "Hypothesis: failure is from missing guard"
  assert_file_contains "$project/.oms/task/current.md" "Result: guard still missing"

  printf 'line one\nline two\n' >> "$project/file.txt"
  HOME="$home_dir" "$ROOT/scripts/peer-delegate.sh" --dry-run \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --to codex \
    --prompt "Implement helper" >/dev/null 2>"$project/err"

  assert_one_artifact_contains "$artifact_dir" 'codex-*.md' "warning: loop attempts exhausted: 3/3"
  assert_one_artifact_contains "$artifact_dir" 'codex-*.md' "warning: repeated last failure detected (3x): bash scripts/check.sh fast exit=1"
  assert_one_artifact_contains "$artifact_dir" 'codex-*.md' "warning: loop diff budget exceeded:"
}

test_agent_plan_dag_and_ready() {
  local d="$TMP/agent-plan"
  local SH="$ROOT/scripts/agent-plan.sh"
  local out
  mkdir -p "$d"; git -C "$d" init -q .

  "$SH" --repo "$d" init --goal demo >/dev/null || fail "plan init failed"
  "$SH" --repo "$d" add --id P1 --title registry >/dev/null || fail "add P1 failed"
  "$SH" --repo "$d" add --id P2 --title schema --depends P1 >/dev/null || fail "add P2 failed"

  if "$SH" --repo "$d" add --id P3 --title x --depends NOPE >/dev/null 2>&1; then
    fail "unknown dependency must be rejected"
  fi
  if "$SH" --repo "$d" add --id '../x' --title bad >/dev/null 2>&1; then
    fail "unsafe task id must be rejected"
  fi
  if "$SH" --repo "$d" add --id P1 --title dup >/dev/null 2>&1; then
    fail "duplicate task id must be rejected"
  fi

  # A repeated list option must fail, not silently keep only the last value.
  out="$("$SH" --repo "$d" add --id P5 --title y --depends P1 --allowed a --allowed b 2>&1)" \
    && fail "repeated --allowed must be rejected"
  case "$out" in
    *"--allowed given twice; pass one comma-separated list"*) ;;
    *) fail "repeated --allowed message missing, got: $out" ;;
  esac
  "$SH" --repo "$d" add --id P5 --title y --depends P1 --depends P2 >/dev/null 2>&1 \
    && fail "repeated --depends must be rejected"
  "$SH" --repo "$d" add --id P5 --title y --depends P1 --forbidden a --forbidden b >/dev/null 2>&1 \
    && fail "repeated --forbidden must be rejected"
  # The rejected adds left no P5 behind, so the comma form can still add it.
  "$SH" --repo "$d" add --id P5 --title y --depends P1,P2 --allowed a,b --forbidden c,d >/dev/null \
    || fail "comma-separated list form must still add a task"

  out="$("$SH" --repo "$d" ready)"
  [ "$out" = "P1" ] || fail "only P1 should be ready, got: $out"

  # A dependent task cannot be claimed until its dependency is done.
  if "$SH" --repo "$d" claim --id P2 --provider codex >/dev/null 2>&1; then
    fail "claiming P2 with unfinished dep P1 must fail"
  fi
  "$SH" --repo "$d" claim --id P1 --provider codex >/dev/null || fail "claim P1 failed"
  printf 'fixture\n' > "$d/change.patch"
  "$SH" --repo "$d" review --id P1 --artifact artifact.md --patch change.patch >/dev/null || fail "review P1 failed"
  agent_plan_land_reviewed "$d" P1 >/dev/null || fail "land P1 failed"
  agent_plan_finish_landed "$d" P1 >/dev/null || fail "finish P1 failed"

  out="$("$SH" --repo "$d" ready)"
  [ "$out" = "P2" ] || fail "P2 should be ready after P1 done, got: $out"
  "$SH" --repo "$d" status | grep -F 'done=1' > /dev/null || fail "status should report done=1"

  # ready --json: schema 1, only startable tasks, same order as plain ready.
  out="$("$SH" --repo "$d" ready --json)" || fail "ready --json failed"
  printf '%s' "$out" | python3 -c '
import json, sys
r = json.load(sys.stdin)
assert r["schema"] == 1 and r["total"] == 1, r
t = r["tasks"][0]
assert t["id"] == "P2" and t["depends"] == ["P1"], t
assert t["allowed"] == [] and t["verify"] == "" and "P1" in t["why_ready"], t
assert "discovered_from" not in t, t
' || fail "ready --json shape wrong: $out"
  "$SH" --repo "$d" claim --id P2 --provider codex >/dev/null || fail "claim P2 failed"
  out="$("$SH" --repo "$d" ready)"
  [ -z "$out" ] || fail "a claimed task must not be ready, got: $out"
  out="$("$SH" --repo "$d" ready --json)"
  printf '%s' "$out" | grep -F '"tasks": []' >/dev/null || fail "claimed task leaked into ready --json: $out"
  "$SH" --repo "$d" ready --limit 0 >/dev/null 2>&1 && fail "--limit 0 must be rejected"
  "$SH" --repo "$d" status --limit 1 >/dev/null 2>&1 && fail "--limit outside ready must be rejected"

  # add --discovered-from: a link only. Unknown parent refused, parent untouched.
  "$SH" --repo "$d" add --id F1 --title found --discovered-from NOPE >/dev/null 2>&1 \
    && fail "unknown --discovered-from must be rejected"
  "$SH" --repo "$d" show --id F1 >/dev/null 2>&1 && fail "rejected discovered add left a task"
  local before after
  before="$("$SH" --repo "$d" show --id P2 | python3 -c 'import json,sys; d=json.load(sys.stdin); d.pop("task_sha256",None); d.pop("claim_age_s",None); print(json.dumps(d,sort_keys=True))')"
  "$SH" --repo "$d" add --id F1 --title found --discovered-from P2 --verify true >/dev/null \
    || fail "discovered add failed"
  out="$("$SH" --repo "$d" add --title generated --discovered-from P2)" || fail "generated-id add failed"
  case "$out" in "plan: added d-"*) ;; *) fail "generated id missing, got: $out" ;; esac
  "$SH" --repo "$d" add --title nolink >/dev/null 2>&1 && fail "add without id and link must still need --id"
  after="$("$SH" --repo "$d" show --id P2 | python3 -c 'import json,sys; d=json.load(sys.stdin); d.pop("task_sha256",None); d.pop("claim_age_s",None); print(json.dumps(d,sort_keys=True))')"
  [ "$before" = "$after" ] || fail "discovered add changed the parent task"
  "$SH" --repo "$d" show --id F1 | grep -F '"discovered_from": "P2"' >/dev/null || fail "show lacks discovered_from"
  "$SH" --repo "$d" brief --id F1 | grep -F 'discovered_from: P2' >/dev/null || fail "brief lacks discovered_from"
  out="$("$SH" --repo "$d" ready --json --limit 1)"
  printf '%s' "$out" | python3 -c '
import json, sys
r = json.load(sys.stdin)
assert r["total"] == 2 and len(r["tasks"]) == 1 and r["tasks"][0]["id"] == "F1", r
assert r["tasks"][0]["discovered_from"] == "P2", r
' || fail "ready --json --limit/discovered link wrong: $out"
  "$SH" --repo "$d" discovered --json | python3 -c '
import json, sys
r = json.load(sys.stdin)
assert r["schema"] == 1 and r["count"] == 2 and [p["id"] for p in r["parents"]] == ["P2"], r
assert r["parents"][0]["state"] == "claimed", r
' || fail "discovered --json wrong"
  "$SH" --repo "$d" discovered | grep -F 'F1' >/dev/null || fail "discovered text lacks F1"
  "$SH" --repo "$d" status --json | python3 -c '
import json, sys
r = json.load(sys.stdin)
assert list(r["discovered"]) == ["P2"] and "F1" in r["discovered"]["P2"], r
' || fail "status --json lacks discovered"
  # Old plans (no link anywhere) keep status --json byte-shape: no discovered key.
  local old="$TMP/agent-plan-old"
  mkdir -p "$old"; git -C "$old" init -q .
  "$SH" --repo "$old" init --goal demo >/dev/null && "$SH" --repo "$old" add --id A --title a >/dev/null
  "$SH" --repo "$old" status --json | grep -F '"discovered"' >/dev/null && fail "plan without links must not grow a discovered key"
  "$SH" --repo "$old" discovered | grep -F '(none)' >/dev/null || fail "empty discovered must say none"
}

test_agent_plan_lock_single_winner() {
  local d="$TMP/agent-plan-race"
  local SH="$ROOT/scripts/agent-plan.sh"
  mkdir -p "$d"; git -C "$d" init -q .
  "$SH" --repo "$d" init --goal race >/dev/null
  "$SH" --repo "$d" add --id P1 --title one >/dev/null

  # Two concurrent claims must not both win the same task (file lock guards the
  # read-decide-write section; the loser gets exit 3 = nothing actionable).
  "$SH" --repo "$d" next --claim --provider codex >"$d/a.out" 2>/dev/null &
  "$SH" --repo "$d" next --claim --provider claude >"$d/b.out" 2>/dev/null &
  wait
  local winners
  winners="$(cat "$d/a.out" "$d/b.out" | grep -c '^# Task P1:' || true)"
  [ "$winners" = 1 ] || fail "exactly one worker should claim P1, got $winners"
}

agent_plan_lifecycle_completion_prelude() {
  cat <<'PY'
import copy
import datetime
import hashlib
import json
import os
from pathlib import Path
import runpy
import stat
import subprocess
import sys
import time
import shutil
root, repo = map(Path, sys.argv[1:])
sys.path.insert(0, str(root / 'scripts/lib'))
engine = runpy.run_path(str(root / 'scripts/lib/plan-receipt.py'))
plan_path = repo / '.oms/plan/tasks.json'
env = dict(os.environ)
for name in list(env):
    if name.startswith('OMS_'):
        env.pop(name)
env['OMS_LOCK_DIR'] = str(repo / '.oms/private-fixture-locks')

def call(script, *args, extra=None, ok=True):
    result = subprocess.run(['bash', str(root / 'scripts' / script), '--repo', str(repo), *args],
                            env=dict(env, **(extra or {})), stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE, timeout=40)
    if ok and result.returncode:
        raise AssertionError((args, result.returncode, result.stderr.decode()))
    if not ok and not result.returncode:
        raise AssertionError(('accepted invalid completion', args))
    return (result.stdout + (result.stderr if not ok else b'')).decode().strip()

def ap(*args, **kwargs):
    return call('agent-plan.sh', *args, **kwargs)

def h(raw):
    return hashlib.sha256(raw).hexdigest()

def ref(path):
    return {'path': path, 'sha256': h((repo / path).read_bytes())}

def entry(path):
    target = repo / path
    if not target.exists():
        return {'path': path, 'state': 'absent', 'mode': None, 'sha256': None}
    return dict(ref(path), state='file', mode='100755' if target.stat().st_mode & stat.S_IXUSR else '100644')

def plan():
    return json.loads(plan_path.read_bytes())

def index():
    return [json.loads(line) for line in (repo / '.oms/artifacts/index.jsonl').read_bytes().splitlines()]

def register(kind, task, artifact, attempt='', patch='', base='', exitcode=0):
    extra = dict(env, OMS_TASK_ID=task, OMS_INDEX_PLAN_ID=plan()['plan_id'],
                 OMS_ATTEMPT_ID=attempt, OMS_INDEX_BASE_SHA=base, OMS_FIXTURE_INDEX_EXIT=str(exitcode))
    result = subprocess.run(['bash', '-c', '. "$1"; ma_append_artifact_index "$2" "$3" codex "$OMS_FIXTURE_INDEX_EXIT" "$4" "$5"',
                             'fixture', str(root / 'scripts/lib/peer-common.sh'), str(repo), kind,
                             str(repo / artifact), str(repo / patch) if patch else ''],
                            env=extra, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30)
    assert result.returncode == 0, result.stderr
    return index()[-1]

ap('init', '--goal', 'typed local completions', '--accept', 'printf accepted > .oms/acceptance-ran')
(repo / 'verify.sh').write_text("test -s file.txt\nprintf '%s\\n' 'bounded verifier output'\n")
(repo / 'obsolete.txt').write_text('Old product to delete\n')
subprocess.run(['git', '-C', str(repo), 'add', 'verify.sh', 'obsolete.txt'], check=True)
subprocess.run(['git', '-C', str(repo), 'commit', '-qm', 'fixture verifier'], env=env, check=True)
base = subprocess.check_output(['git', '-C', str(repo), 'rev-parse', 'HEAD']).decode().strip()
room = json.loads(call('room.sh', 'new', '--topic', 'Private completion fixture', '--json'))['id']
# Native initial enrollment uses the new attempt ID and omits the ref.
main = call('agent-events.sh', 'start', '--provider', 'codex', '--tool', 'panel-main',
            '--ref', 'panel_room_id=' + room, '--ref', 'panel_role=main',
            '--then', 'starting', '--then', 'working')
participant = main
call('room.sh', 'join', '--id', room, '--participant', participant, '--provider', 'codex', '--role', 'main')

env.update(OMS_ROOM_ID=room, OMS_ROOM_PARTICIPANT=participant, OMS_PANEL_MAIN_ATTEMPT=main)
counter = 0
def setup(command='bash verify.sh', empty_verify=False, claim_provider='codex', main_report=False, producer_exit=0, role=None):
    global counter
    read_base = subprocess.check_output(['git', '-C', str(repo), 'rev-parse', 'HEAD']).decode().strip()
    counter += 1
    tid = 'research%d' % counter
    ap('add', '--id', tid, '--title', 'Inspect all original obligations', '--allowed', 'file.txt,verify.sh',
       '--verify', '' if empty_verify else command,
       '--role', role if role is not None else 'analysis-worker' if main_report else '',
       '--assignment', json.dumps({'provider': claim_provider, 'workload': 'routine'}))
    ap('claim', '--id', tid, '--provider', 'codex',
       extra={'OMS_PANEL_MAIN_ATTEMPT': main, 'OMS_ROOM_PARTICIPANT': participant})
    artifact = '.oms/artifacts/research/%s.md' % tid
    (repo / artifact).parent.mkdir(parents=True, exist_ok=True)
    read_result = subprocess.run(['bash', '-c', 'cat file.txt verify.sh; exit %d' % producer_exit], cwd=str(repo),
                                 stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
    assert read_result.returncode == producer_exit, read_result.stderr
    (repo / artifact).write_bytes(read_result.stdout)
    attempt, ancillary = '', ''
    if not main_report:
        attempt = call('agent-events.sh', 'start', '--provider', 'codex', '--tool', 'peer-ask',
                   '--task-id', tid, '--parent-attempt-id', main, '--ref', 'panel_access=read',
                   '--then', 'starting', '--then', 'working')
        call('agent-events.sh', 'transition', '--attempt', attempt, '--state', 'verifying',
         '--then', 'review', '--then', 'done')
        ancillary = '.oms/artifacts/research/%s.patch' % tid
        (repo / ancillary).write_bytes(b'')
    row = register('call-import' if main_report else 'ask', tid, artifact, attempt,
                   patch=ancillary, base=read_base[:7], exitcode=producer_exit)
    ap('review', '--id', tid, '--artifact', artifact)
    current = plan()
    task = current['tasks'][tid]
    bundle = {'schema': 1, 'kind': 'research-accepted', 'plan_id': current['plan_id'], 'task_id': tid,
              'task_sha256': engine['digest'](task), 'plan_sha256': h(plan_path.read_bytes()),
              'state': task['state'], 'lease_id': task['lease_id'],
              'owner': {'provider': task['provider'], 'participant': participant, 'parent_provider': 'codex'},
              'original_contract': engine['projection'](task), 'review_summary': 'Reviewed full original task contract',
              'reviewed_obligations': ['inspect'], 'requirements': [
                  {'id': 'inspect', 'obligation': task['title'], 'deliverable': 'Complete source findings',
                   'source_paths': ['file.txt', 'verify.sh'], 'evidence': [ref(artifact)]}],
              'base_commit': read_base, 'source_envelope': ['file.txt', 'verify.sh'],
              'source_manifest': [entry('file.txt'), entry('verify.sh')],
              'verifier': {'command': command, 'files': [entry('verify.sh')],
                           'adopted': empty_verify, 'review_summary': 'Reviewed verifier and actual frozen inputs'},
              'research': {'classification': 'research-only', 'artifact': ref(artifact),
                           'index_event_id': row['event_id'], 'attempt_id': attempt, 'parent_attempt_id': main}}
    for script in ('drift.py', 'source-drift.sh', 'append-proof.py'):
        if script in command:
            bundle['source_envelope'].append(script)
            bundle['source_manifest'].append(entry(script))
            bundle['verifier']['files'].append(entry(script))
    if main_report:
        bundle.pop('research')
        bundle['kind'] = 'main-research-accepted'
        bundle['reviewer'] = {'kind': 'native-panel-main'}
        bundle['main_research'] = {'classification': 'research-only', 'provenance': 'main-reviewed-external',
            'artifact': ref(artifact), 'index_event_id': row['event_id'], 'original_deliverable': task['title'],
            'read_only_contract': 'original-report-only', 'original_producer_status':
                {key: row.get(key) for key in ('kind', 'exit', 'attempt_id', 'task_id', 'plan_id', 'base_sha')}}
        if producer_exit:
            bundle['main_research'].update(provenance='main-reviewed-external',
                failed_producer_review='The external command failed; current main independently reviewed its report and source')
        return bundle
    bundle['legacy_adoption'] = {'artifact': ref(artifact), 'original_contract': bundle['original_contract'],
                                 'review_summary': 'Current explicit adoption of missing legacy producer binding'}
    return bundle

def invoke(bundle, action='accept-research', extra=None, ok=True, flags=(), payload=None):
    path = '.oms/artifacts/completion-bundle.json'
    raw = json.dumps(bundle).encode() if payload is None else payload
    (repo / path).write_bytes(raw)
    return ap(action, '--id', bundle['task_id'], '--lease-id', bundle['lease_id'],
              '--expected-state', bundle['state'], '--expected-plan-sha256', bundle['plan_sha256'],
              '--expected-task-sha256', bundle['task_sha256'], '--completion-bundle', path,
              '--expected-completion-bundle-sha256', h(raw), *flags, extra=extra, ok=ok)
PY
}

# Remote retries must preserve Git output and stop before a failed push.
test_land_remote_fetch_retry() {
  local d="$TMP/land-retry" repo="$TMP/land-retry/repo" bin="$TMP/land-retry/bin" rc=0
  mkdir -p "$d" "$bin"
  git init -q --bare -b main "$d/remote.git"
  git clone -q "$d/remote.git" "$repo" 2>/dev/null
  printf 'base\n' > "$repo/base"
  git -C "$repo" add base
  git -C "$repo" commit -qm base
  git -C "$repo" push -q origin HEAD:main
  printf 'change\n' >> "$repo/base"
  git -C "$repo" commit -qam change
  local real_git
  real_git="$(command -v git)"
  cat > "$bin/git" <<'GIT'
#!/usr/bin/env bash
case " $* " in
  *' fetch -q --no-write-fetch-head '*) kind=fetch ;;
  *' ls-remote --exit-code '*) kind=lookup ;;
  *' push --no-verify '*) kind=push ;;
  *) exec "$REAL_GIT" "$@" ;;
esac
count=0
[ ! -f "$RETRY_DIR/$kind" ] || read -r count < "$RETRY_DIR/$kind"
count=$((count + 1))
printf '%s\n' "$count" > "$RETRY_DIR/$kind"
case "$kind:$count" in fetch:1|lookup:1|lookup:2) exit 1 ;; esac
[ "${FAIL_FETCH:-0}:$kind" != 1:fetch ] || exit 1
[ "${FAIL_LOOKUP:-0}:$kind" != 1:lookup ] || exit 1
[ "${FAIL_PUSH:-0}:$kind" != 1:push ] || exit 1
exec "$REAL_GIT" "$@"
GIT
  cat > "$bin/sleep" <<'SLEEP'
#!/usr/bin/env bash
printf '%s\n' "$1" >> "$RETRY_DIR/sleeps"
SLEEP
  chmod +x "$bin/git" "$bin/sleep"
  export REAL_GIT="$real_git" RETRY_DIR="$d"
  PATH="$bin:$PATH" "$ROOT/scripts/land.sh" --repo "$repo" --wait --no-update --gate true --ci-wait 0 >"$d/out" 2>&1 ||
    fail "transient remote errors should recover: $(cat "$d/out")"
  [ "$(cat "$d/fetch")" = 2 ] && [ "$(cat "$d/lookup")" = 3 ] || fail "incorrect retry count"
  [ "$(cat "$d/sleeps")" = "$(printf '2\n2\n5')" ] || fail "incorrect retry delays"
  assert_file_contains "$d/out" 'land: remote fetch failed (attempt 1/3); retrying'
  assert_file_contains "$d/out" 'land: remote fetch failed (attempt 2/3); retrying'
  rm -f "$d/fetch" "$d/lookup" "$d/sleeps"
  PATH="$bin:$PATH" "$ROOT/scripts/land.sh" --repo "$repo" --wait --no-update --gate true --ci-wait 0 >"$d/resume" 2>&1 ||
    fail "transient resume lookup should recover: $(cat "$d/resume")"
  [ "$(cat "$d/lookup")" = 3 ] || fail "resume lookup did not retry"
  rm -f "$d/fetch" "$d/sleeps"
  FAIL_FETCH=1 PATH="$bin:$PATH" "$ROOT/scripts/land.sh" --repo "$repo" --wait --no-update --gate true --ci-wait 0 >"$d/fail" 2>&1 || rc=$?
  [ "$rc" = 2 ] && [ "$(cat "$d/fetch")" = 3 ] || fail "exhausted fetch must exit 2 after three attempts"
  [ "$(cat "$d/sleeps")" = "$(printf '2\n5')" ] || fail "exhausted fetch delay mismatch"
  rm -f "$d/fetch" "$d/lookup" "$d/sleeps"
  rc=0
  FAIL_LOOKUP=1 PATH="$bin:$PATH" "$ROOT/scripts/land.sh" --repo "$repo" --wait --no-update --gate true --ci-wait 0 >"$d/lookup-fail" 2>&1 || rc=$?
  [ "$rc" != 0 ] && [ "$(cat "$d/lookup")" = 3 ] || fail "exhausted lookup must fail after three attempts"
  printf 'another\n' >> "$repo/base"
  git -C "$repo" commit -qam another
  rm -f "$d/fetch" "$d/lookup" "$d/push" "$d/sleeps"
  rc=0
  FAIL_PUSH=1 PATH="$bin:$PATH" "$ROOT/scripts/land.sh" --repo "$repo" --wait --no-update --gate true --ci-wait 0 >"$d/push-fail" 2>&1 || rc=$?
  [ "$rc" != 0 ] && [ "$(cat "$d/push")" = 1 ] || fail "failed push must not be retried"
}

# smoke-weight: 50
test_agent_plan_lifecycle_landing_and_main_research() {
  local d="$TMP/agent-plan-life"
  local child_repo="$TMP/agent-plan-child-completion"
  local SH="$ROOT/scripts/agent-plan.sh"
  mkdir -p "$d"; git -C "$d" init -q .
  "$SH" --repo "$d" init --goal life >/dev/null
  "$SH" --repo "$d" add --id P1 --title one >/dev/null

  # A child may review work, but only the controller can fence its landing or
  # mark its exact landing receipt complete.
  make_committed_repo "$child_repo"
  "$SH" --repo "$child_repo" init --goal child-completion >/dev/null
  "$SH" --repo "$child_repo" add --id P2 --title two >/dev/null
  "$SH" --repo "$child_repo" claim --id P2 --provider codex >/dev/null
  printf 'patch bytes\n' > "$child_repo/review.patch"
  printf 'reviewed\n' > "$child_repo/review.md"
  "$SH" --repo "$child_repo" review --id P2 --artifact "$child_repo/review.md" \
    --patch "$child_repo/review.patch" >/dev/null
  local before receipt
  before="$(cat "$child_repo/.oms/plan/tasks.json")"
  if agent_plan_land_reviewed "$child_repo" P2 child >"$child_repo/err" 2>&1; then
    fail "a harness child landed a reviewed plan task"
  fi
  assert_file_contains "$child_repo/err" 'land is parent-only; a harness child cannot complete plan tasks'
  [ "$before" = "$(cat "$child_repo/.oms/plan/tasks.json")" ] ||
    fail "child land refusal changed the plan"
  agent_plan_land_reviewed "$child_repo" P2 >/dev/null || fail "parent land should still work"
  before="$(cat "$child_repo/.oms/plan/tasks.json")"
  receipt="$("$SH" --repo "$child_repo" show --id P2 | python3 -c '
import json,runpy,sys
print(runpy.run_path(sys.argv[1])["digest"](json.load(sys.stdin)))
' "$ROOT/scripts/lib/plan-receipt.py" | tr -d '\r')"
  if OMS_HARNESS_CHILD=1 "$SH" --repo "$child_repo" finish --id P2 \
      --expected-landing-receipt-sha256 "$receipt" >"$child_repo/err" 2>&1; then
    fail "a harness child finished a landed plan task"
  fi
  assert_file_contains "$child_repo/err" 'finish is parent-only; a harness child cannot complete plan tasks'
  [ "$before" = "$(cat "$child_repo/.oms/plan/tasks.json")" ] ||
    fail "child finish refusal changed the plan"
  "$SH" --repo "$child_repo" finish --id P2 --expected-landing-receipt-sha256 "$receipt" >/dev/null ||
    fail "parent finish should still work"
  [ "$("$SH" --repo "$child_repo" show --id P2 | python3 -c 'import json,sys;print(json.load(sys.stdin)["state"])')" = "done" ] ||
    fail "parent finish did not complete its landed task"

  # finish is not allowed straight from ready.
  if "$SH" --repo "$d" finish --id P1 >/dev/null 2>&1; then
    fail "finish from ready must be rejected"
  fi
  # release requeues a claimed task back to ready.
  "$SH" --repo "$d" claim --id P1 --provider codex >/dev/null
  "$SH" --repo "$d" show --id P1 | grep -F '"claimed_at"' > /dev/null || fail "claim should record claimed_at"
  "$SH" --repo "$d" release --id P1 >/dev/null
  [ "$("$SH" --repo "$d" ready)" = "P1" ] || fail "release should return P1 to ready"
  # a blocked task cannot be claimed directly; it must be reopened.
  "$SH" --repo "$d" block --id P1 --reason wait >/dev/null
  if "$SH" --repo "$d" claim --id P1 --provider codex >/dev/null 2>&1; then
    fail "claiming a blocked task must be rejected"
  fi

  # Integration by commit consumes land's shared-worktree receipts, with no
  # fetch or remote process. A later local tip may contain the exact landed SHA.
  local XDG_STATE_HOME="$TMP/agent-plan-land-state"
  export XDG_STATE_HOME
  local sha receipt_dir receipt mode linked before
  git -C "$d" commit --allow-empty -qm base
  git -C "$d" commit --allow-empty -qm integrated
  sha="$(git -C "$d" rev-parse HEAD)"
  git -C "$d" commit --allow-empty -qm later
  "$SH" --repo "$d" add --id integrated --title integrated >/dev/null
  "$SH" --repo "$d" claim --id integrated --provider codex >/dev/null
  if "$SH" --repo "$d" finish --id integrated --landed-commit "$sha" >"$d/err" 2>&1; then
    fail "commit finish from claimed must be rejected"
  fi
  assert_file_contains "$d/err" 'requires review'
  # The land receipt supplies evidence for a review without an artifact.
  "$SH" --repo "$d" review --id integrated >/dev/null
  before="$(cat "$d/.oms/plan/tasks.json")"
  if "$SH" --repo "$d" finish --id integrated --landed-commit "$sha" --artifact artifact.md >"$d/err" 2>&1; then
    fail "commit finish without receipt must be rejected"
  fi
  assert_file_contains "$d/err" 'no passed oms land receipt'
  assert_file_contains "$d/err" 'head SHA that oms land pushed'
  [ "$before" = "$(cat "$d/.oms/plan/tasks.json")" ] || fail "evidence on a rejected finish changed plan"
  # Obtain the directory from land status itself, rather than duplicate its
  # identity calculation in a fixture that could hide a lookup mismatch.
  out="$("$ROOT/scripts/land.sh" status --repo "$d" 2>/dev/null || true)"
  case "$out" in 'no landing recorded under '*) receipt_dir="${out#no landing recorded under }" ;;
    *) fail "cannot resolve fixture receipt directory: $out" ;;
  esac
  mkdir -p "$receipt_dir"
  receipt="$receipt_dir/$sha-fixture.json"
  for mode in failed gate push ci skipped foreign passed; do
    python3 - "$receipt" "$sha" "$mode" <<'PY'
import json, sys
path, sha, mode = sys.argv[1:]
r = {"schema": 1, "state": "passed", "sha": sha, "remote": "origin", "target": "main",
     "gate": {"rc": 0}, "push": {"rc": 0}, "ci": {"conclusion": "success"}}
if mode == "failed": r["state"] = "failed"
if mode in ("gate", "push"): r[mode]["rc"] = 1
if mode == "ci": r["ci"]["conclusion"] = "failure"
if mode == "skipped": r["ci"]["conclusion"] = "skipped"
if mode == "foreign": r["sha"] = "0" * len(sha)
with open(path, "w", encoding="utf-8") as handle:
    json.dump(r, handle)
PY
    if "$SH" --repo "$d" finish --id integrated --landed-commit "$sha" >"$d/err" 2>&1; then
      fail "commit finish accepted $mode proof without a reachable target"
    fi
    if [ "$mode" = passed ]; then
      assert_file_contains "$d/err" 'not reachable'
    else
      assert_file_contains "$d/err" 'no passed oms land receipt'
    fi
    [ "$before" = "$(cat "$d/.oms/plan/tasks.json")" ] || fail "invalid proof changed plan"
  done
  git -C "$d" update-ref refs/remotes/origin/main "$sha^"
  if "$SH" --repo "$d" finish --id integrated --landed-commit "$sha" >"$d/err" 2>&1; then
    fail "commit finish accepted a target that predates the landed SHA"
  fi
  assert_file_contains "$d/err" 'not reachable'
  [ "$before" = "$(cat "$d/.oms/plan/tasks.json")" ] || fail "unreachable proof changed plan"
  git -C "$d" update-ref refs/remotes/origin/main HEAD
  if "$SH" --repo "$d" finish --id integrated --landed-commit "$sha" \
    --expected-landing-receipt-sha256 invalid >"$d/err" 2>&1; then
    fail "commit finish accepted mixed patch-land options"
  fi
  assert_file_contains "$d/err" 'cannot be combined'
  if "$SH" --repo "$d" finish --id integrated --landed-commit "${sha:0:7}" >"$d/err" 2>&1; then
    fail "commit finish accepted abbreviated SHA"
  fi
  assert_file_contains "$d/err" 'full lowercase commit SHA'
  if "$SH" --repo "$d" finish --id integrated --landed-commit "$sha" --lease-id stale >"$d/err" 2>&1; then
    fail "commit finish accepted a stale lease"
  fi
  assert_file_contains "$d/err" 'lease mismatch'
  [ "$before" = "$(cat "$d/.oms/plan/tasks.json")" ] || fail "stale lease changed plan"
  # A newer unrelated receipt must not shadow the exact-SHA proof.
  printf '{"schema":1,"state":"failed"}\n' > "$receipt_dir/unrelated.json"
  linked="$TMP/agent-plan-linked"
  git -C "$d" worktree add -q --detach "$linked" HEAD
  "$SH" --repo "$linked" --file "$d/.oms/plan/tasks.json" finish \
    --id integrated --landed-commit "$sha" >/dev/null || fail "passed commit proof must finish from linked worktree"
  "$SH" --repo "$d" show --id integrated > "$d/done.json"
  python3 - "$d/done.json" "$sha" "$receipt" <<'PY' || fail "commit landing evidence was not retained"
import hashlib, json, sys
t = json.load(open(sys.argv[1], encoding="utf-8"))
landing = {"kind": "commit", "sha": sys.argv[2],
           "receipt_sha256": hashlib.sha256(open(sys.argv[3], "rb").read()).hexdigest()}
assert t["state"] == "done" and t["landing"] == landing, t
assert t["artifact"] == "" and t["patch"] == "", t
assert t["history"][-1]["kind"] == "finish" and t["history"][-1]["landing"] == landing, t
PY
  "$SH" --repo "$d" status --json | python3 -c '
import json, sys
s = json.load(sys.stdin)
assert s["by_state"] == {"blocked": 1, "done": 1}, s
assert s["stale_review"] == [], s
' || fail "status did not count commit finish as done"
  if "$SH" --repo "$d" finish --id integrated --landed-commit "$sha" >"$d/err" 2>&1; then
    fail "commit finish accepted done instead of review"
  fi
  assert_file_contains "$d/err" 'requires review'
  # The land rewrites its receipt as installation proceeds; a finalize retry of
  # the done task proves the same commit, not the same receipt bytes.
  lease="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["lease_id"])' "$d/done.json")"
  python3 -c 'import json,sys; r=json.load(open(sys.argv[1])); r["update"]={"rc":0,"reason":"installed"}; json.dump(r,open(sys.argv[1],"w"))' "$receipt"
  before="$(cat "$d/.oms/plan/tasks.json")"
  "$SH" --repo "$d" finish --id integrated --landed-commit "$sha" --lease-id "$lease" >/dev/null ||
    fail "a finalize retry failed after the land rewrote its receipt"
  [ "$before" = "$(cat "$d/.oms/plan/tasks.json")" ] || fail "finish retry changed the done task"

  # Explicit artifacts survive both review-time and finish-time evidence entry.
  local artifact_route
  for artifact_route in review finish; do
    "$SH" --repo "$d" add --id "artifact-$artifact_route" --title "Explicit artifact $artifact_route" >/dev/null
    "$SH" --repo "$d" claim --id "artifact-$artifact_route" --provider codex >/dev/null
    if [ "$artifact_route" = review ]; then
      "$SH" --repo "$d" review --id "artifact-$artifact_route" --artifact artifact.md >/dev/null
      "$SH" --repo "$d" finish --id "artifact-$artifact_route" --landed-commit "$sha" >/dev/null
    else
      "$SH" --repo "$d" review --id "artifact-$artifact_route" >/dev/null
      "$SH" --repo "$d" finish --id "artifact-$artifact_route" --landed-commit "$sha" --artifact artifact.md >/dev/null
    fi
    "$SH" --repo "$d" show --id "artifact-$artifact_route" | python3 -c '
import json, sys
task = json.load(sys.stdin)
assert task["state"] == "done" and task["artifact"] == "artifact.md", task
' || fail "explicit artifact was lost on $artifact_route"
  done

  # A receipt proves a landing, not which task it landed: a scoped task needs
  # the landed range, back to the previous pushed receipt, to touch its paths.
  local inside outside
  "$SH" --repo "$d" add --id scoped --title scoped --allowed "src/" >/dev/null
  "$SH" --repo "$d" claim --id scoped --provider codex >/dev/null
  "$SH" --repo "$d" review --id scoped --artifact artifact.md --patch change.patch >/dev/null
  mkdir -p "$d/src"; printf 'x\n' > "$d/src/a.txt"
  git -C "$d" add src/a.txt; git -C "$d" commit -qm inside
  inside="$(git -C "$d" rev-parse HEAD)"
  printf 'x\n' > "$d/other.txt"
  git -C "$d" add other.txt; git -C "$d" commit -qm outside
  outside="$(git -C "$d" rev-parse HEAD)"
  git -C "$d" update-ref refs/remotes/origin/main HEAD
  sed "s/$sha/$inside/" "$receipt" > "$receipt_dir/$inside-fixture.json"
  sed "s/$sha/$outside/" "$receipt" > "$receipt_dir/$outside-fixture.json"
  before="$(cat "$d/.oms/plan/tasks.json")"
  if "$SH" --repo "$d" finish --id scoped --landed-commit "$outside" >"$d/err" 2>&1; then
    fail "commit finish accepted a landing outside the task's allowed_paths"
  fi
  assert_file_contains "$d/err" "landed commit $outside does not land task scoped: $inside..$outside"
  assert_file_contains "$d/err" 'allowed_paths (src/); changed: other.txt'
  [ "$before" = "$(cat "$d/.oms/plan/tasks.json")" ] || fail "out-of-scope proof changed plan"
  "$SH" --repo "$d" finish --id scoped --landed-commit "$inside" >/dev/null ||
    fail "commit finish must accept a landing that touches allowed_paths"
  # A pushed land whose CI failed still put its work on the target, and the
  # fix-forward land after it proves the whole tree: its range extends back over
  # that push. A land that never pushed, or one that passed, bounds the range.
  local fwd_head fwd_a fwd_b fwd_c fwd_d fwd_e
  fwd_receipt() {  # sha state push-rc base ci [update-rc update-reason]
    python3 - "$receipt_dir/$1-fwd.json" "$@" <<'PY'
import json, sys
path, sha, state, rc, base, ci = sys.argv[1:7]
push = {"rc": int(rc)}
if base: push["base"] = base
receipt = {"schema": 1, "state": state, "sha": sha, "remote": "origin", "target": "main",
           "gate": {"rc": 0}, "push": push, "ci": {"conclusion": ci}}
if len(sys.argv) > 7: receipt["update"] = {"rc": int(sys.argv[7]), "reason": sys.argv[8]}
with open(path, "w", encoding="utf-8") as handle:
    json.dump(receipt, handle)
PY
  }
  fwd_commit() { printf 'x\n' > "$d/$1"; git -C "$d" add "$1"; git -C "$d" commit -qm "$1"; git -C "$d" rev-parse HEAD; }
  mkdir -p "$d/src"
  fwd_head="$(git -C "$d" rev-parse HEAD)"
  fwd_a="$(fwd_commit src/pushed-failed.txt)"
  fwd_b="$(fwd_commit unrelated-b.txt)"
  fwd_c="$(fwd_commit src/unpushed-failed.txt)"
  fwd_d="$(fwd_commit unrelated-d.txt)"
  fwd_e="$(fwd_commit src/deferred.txt)"
  git -C "$d" update-ref refs/remotes/origin/main HEAD
  fwd_receipt "$fwd_a" failed 0 "$fwd_head" failure
  fwd_receipt "$fwd_b" passed 0 "$fwd_a" success
  fwd_receipt "$fwd_c" failed 1 "$fwd_b" failure
  fwd_receipt "$fwd_d" passed 0 "$fwd_c" success
  fwd_receipt "$fwd_e" failed 0 "$fwd_d" success 1 update-failed
  for mode in pushed-failed unpushed-failed deferred; do
    "$SH" --repo "$d" add --id "fwd-$mode" --title "$mode" --allowed "src/$mode.txt" >/dev/null
    "$SH" --repo "$d" claim --id "fwd-$mode" --provider codex >/dev/null
    "$SH" --repo "$d" review --id "fwd-$mode" --artifact artifact.md --patch change.patch >/dev/null
  done
  "$SH" --repo "$d" finish --id fwd-pushed-failed --landed-commit "$fwd_b" >/dev/null ||
    fail "a passed fix-forward land did not finish the task of the pushed CI-failed land before it"
  before="$(cat "$d/.oms/plan/tasks.json")"
  if "$SH" --repo "$d" finish --id fwd-unpushed-failed --landed-commit "$fwd_d" >"$d/err" 2>&1; then
    fail "a land that never pushed was bridged by the next passed land"
  fi
  assert_file_contains "$d/err" "landed commit $fwd_d does not land task fwd-unpushed-failed: $fwd_c..$fwd_d"
  # A passed land is never bridged: the task of the land before it stays refused.
  "$SH" --repo "$d" add --id fwd-passed --title passed --allowed src/pushed-failed.txt >/dev/null
  "$SH" --repo "$d" claim --id fwd-passed --provider codex >/dev/null
  "$SH" --repo "$d" review --id fwd-passed --artifact artifact.md --patch change.patch >/dev/null
  fwd_receipt "$fwd_d" passed 0 "$fwd_b" success
  if "$SH" --repo "$d" finish --id fwd-passed --landed-commit "$fwd_d" >"$d/err" 2>&1; then
    fail "a land range was extended over a passed land"
  fi
  assert_file_contains "$d/err" "$fwd_b..$fwd_d"
  fwd_receipt "$fwd_d" passed 0 "$fwd_c" success
  before="$(cat "$d/.oms/plan/tasks.json")"
  if "$SH" --repo "$d" finish --id fwd-deferred --landed-commit "$fwd_e" >"$d/err" 2>&1; then
    fail "commit finish accepted a receipt whose update failed"
  fi
  assert_file_contains "$d/err" 're-run oms land to finish installation'
  [ "$before" = "$(cat "$d/.oms/plan/tasks.json")" ] || fail "refused fix-forward finishes changed plan"
  # Install waits for live workers machine-wide; the pushed, CI-proven commit
  # still finishes its task.
  fwd_receipt "$fwd_e" running 0 "$fwd_d" success 76 deferred-live-workers
  "$SH" --repo "$d" finish --id fwd-deferred --landed-commit "$fwd_e" >/dev/null ||
    fail "an install deferred for live workers blocked plan finish of a pushed CI-proven land"
  # A separate producer clone explicitly hands real land receipts back to the
  # shared plan checkout. Two commits need the predecessor to cover src/.
  local handoff_remote="$TMP/plan-handoff.git" producer="$TMP/plan-producer"
  local handoff_bin="$TMP/plan-handoff-bin" baseline landed
  git init -q --bare -b main "$handoff_remote"
  git -C "$d" remote add origin "$handoff_remote"
  git -C "$d" push -q origin HEAD:main
  git clone -q "$handoff_remote" "$producer"
  mkdir -p "$handoff_bin" "$producer/.github/workflows"
  cat > "$handoff_bin/gh" <<'GH'
#!/usr/bin/env bash
while [ "$#" -gt 0 ]; do
  if [ "$1" = --commit ]; then
    printf '[{"databaseId":1,"headSha":"%s","status":"completed","conclusion":"success"}]\n' "$2"
    exit 0
  fi
  shift
done
exit 1
GH
  chmod +x "$handoff_bin/gh"
  local PATH="$handoff_bin:$PATH"
  export PATH
  printf 'on: push\n' > "$producer/.github/workflows/test.yml"
  git -C "$producer" add .github/workflows/test.yml
  git -C "$producer" commit -qm workflow
  "$ROOT/scripts/land.sh" --repo "$producer" --wait --no-update --gate true --ci-wait 1 >"$d/land.out" 2>&1 ||
    fail "producer baseline land failed: $(cat "$d/land.out")"
  baseline="$(git -C "$producer" rev-parse HEAD)"
  "$SH" --repo "$d" add --id handoff --title handoff --allowed src/handoff.txt >/dev/null
  "$SH" --repo "$d" claim --id handoff --provider codex >/dev/null
  "$SH" --repo "$d" review --id handoff --artifact artifact.md --patch change.patch >/dev/null
  printf 'handed off\n' > "$producer/src/handoff.txt"
  git -C "$producer" add src/handoff.txt
  git -C "$producer" commit -qm handoff
