# smoke-weight: 15
test_delegate_resumes_native_session() {
  local project="$TMP/delegate-resume"
  local bin_dir="$TMP/delegate-resume-bin"
  local home_dir="$TMP/delegate-resume-home"
  local log="$TMP/delegate-resume.log"
  local verify_baseline="$TMP/delegate-resume-verify-baseline"
  local session=11111111-2222-3333-4444-555555555555

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir/.claude/projects/-old-worktree"
  printf '{}\n' > "$home_dir/.claude/projects/-old-worktree/$session.jsonl"
  cat > "$bin_dir/claude" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in
  --version|--help) printf 'fixture 1.0 --effort low medium high --resume --output-format\n'; exit 0 ;;
esac
encoded="$(pwd -P | sed 's/[^A-Za-z0-9]/-/g')"
{
  printf 'argv: %s\n' "$*"
  printf 'resume-baseline: %s\n' "${OMS_RESUME_USAGE_BASELINE-unset}"
  printf 'env-names: %s \n' "$(env | cut -d= -f1 | tr '\n' ' ')"
  [ -f "$HOME/.claude/projects/$encoded/$FIXTURE_SESSION.jsonl" ] && printf 'session-in-new-cwd\n'
  printf 'session-body: %s\n' "$(cat "$HOME/.claude/projects/$encoded/$FIXTURE_SESSION.jsonl" 2>/dev/null)"
  cat
} > "$FIXTURE_LOG"
printf '{"type":"result","subtype":"success","is_error":false,"result":"resumed","session_id":"%s","stop_reason":"end_turn"}\n' "$FIXTURE_SESSION"
EOF
  chmod +x "$bin_dir/claude"
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    FIXTURE_LOG="$log" FIXTURE_SESSION="$session" OMS_RESUME_USAGE_BASELINE='{"input_tokens":7}' \
    OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker \
    "$ROOT/scripts/peer-delegate.sh" --to claude --repo "$project" \
    --artifact-dir "$project/artifacts" --allow-no-change --resume-session "$session" \
    --verify "printf '%s' \"\${OMS_RESUME_USAGE_BASELINE-unset}\" > '$verify_baseline'" \
    --prompt "Your earlier work was on abc; New instructions follow." >/dev/null ||
    fail "resumed delegate failed"
  assert_file_contains "$log" "--resume $session"
  assert_file_contains "$log" 'resume-baseline: {"input_tokens":7}'
  [ "$(cat "$verify_baseline")" = unset ] ||
    fail "verify environment inherited the resume usage baseline"
  assert_file_contains "$log" "session-in-new-cwd"
  assert_file_contains "$log" "Your earlier work was on abc"
  grep -rqE "native_session\"?: ?\"$session\"" "$project/.oms/lifecycle" ||
    fail "resumed delegate did not record the native session"

  verify_baseline="$project/verify-baseline"
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    FIXTURE_LOG="$log" FIXTURE_SESSION="$session" OMS_RESUME_USAGE_BASELINE='{"input_tokens":7}' \
    OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker \
    "$ROOT/scripts/peer-delegate.sh" --to claude --repo "$project" \
    --artifact-dir "$project/artifacts" --allow-no-change \
    --verify "printf '%s' \"\${OMS_RESUME_USAGE_BASELINE-unset}\" > '$verify_baseline'" \
    --prompt "No session continuation" >/dev/null ||
    fail "delegate with inherited baseline and no resume failed"
  assert_file_contains "$log" 'resume-baseline: unset'
  [ "$(cat "$verify_baseline")" = unset ] ||
    fail "verify environment inherited the resume usage baseline"

  if "$ROOT/scripts/peer-delegate.sh" --to claude --repo "$project" --no-verify \
      --resume-session '../x' --prompt p >/dev/null 2>&1; then
    fail "an unsafe session id must be rejected"
  fi

  # Secret guard (opt-in). Off: the worker gets no inline settings and the
  # owner's environment as before. On: the Read tool is denied the secret
  # paths the prompt bundle already excludes, and credential-shaped variables
  # stay with the owner except the provider's login and the names allowed.
  local forge="GH_TO""KEN" hub="HF_TO""KEN" cloud="AWS_PROFILE" login="ANTHROPIC_API_KEY" deny
  guard_run() {  # extra environment assignments as arguments
    env HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      FIXTURE_LOG="$log" FIXTURE_SESSION="$session" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker \
      "$forge=f" "$hub=h" "$cloud=c" "$login=l" PLAIN_SETTING=1 "$@" \
      "$ROOT/scripts/peer-delegate.sh" --to claude --repo "$project" \
      --artifact-dir "$project/artifacts" --no-verify --allow-no-change \
      --prompt "Secret guard probe" >/dev/null || fail "delegate under the secret guard probe failed ($*)"
  }
  guard_run
  ! grep -q 'permissions' "$log" || fail "an unguarded worker must not receive inline deny settings"
  for deny in "$forge" "$hub" "$cloud" "$login" PLAIN_SETTING; do
    grep -q "^env-names: .* $deny " "$log" || fail "an unguarded worker lost $deny"
  done
  guard_run OMS_WORKER_SECRET_GUARD=1 OMS_WORKER_ENV_ALLOW="$hub,UNSET_NAME"
  assert_file_contains "$log" '--settings {"permissions":{"deny":["Read(**/.env*)",'
  assert_file_contains "$log" '"Read(~/.ss''h/**)","Read(~/.aw''s/**)","Read(~/.config/gh/hosts.yml)"]}}'
  for deny in "$forge" "$cloud"; do
    ! grep -q "^env-names: .* $deny " "$log" || fail "a guarded worker still carries $deny"
  done
  for deny in "$hub" "$login" PLAIN_SETTING OMS_HARNESS_CHILD; do
    grep -q "^env-names: .* $deny " "$log" || fail "a guarded worker lost $deny"
  done
  # Claude on Bedrock logs in with the cloud's variables; the guard keeps them.
  guard_run OMS_WORKER_SECRET_GUARD=1 CLAUDE_CODE_USE_BEDROCK=1
  grep -q "^env-names: .* $cloud " "$log" || fail "a Bedrock worker lost its cloud login variable"
  ! grep -q "^env-names: .* $forge " "$log" || fail "a guarded Bedrock worker still carries $forge"
  # Every denied repository pattern is one the prompt bundle already excludes.
  while IFS= read -r deny; do
    grep -Fq "':(top,exclude,glob)$deny'" "$ROOT/scripts/lib/peer-common.sh" ||
      fail "Read deny $deny is not excluded from the prompt bundle"
  done < <(sed -n "/^MA_SECRET_READ_DENY=(/,/^)/s/^  '\(\*\*\/.*\)'$/\1/p" "$ROOT/scripts/lib/peer-common.sh")
  [ "$(sed -n "/^MA_SECRET_READ_DENY=(/,/^)/p" "$ROOT/scripts/lib/peer-common.sh" | grep -c "^  '\*\*/")" -ge 10 ] ||
    fail "the Read deny list was not found"

  local projects="$home_dir/.claude/projects" outside="$TMP/delegate-resume-outside"
  mkdir -p "$projects/-newer-worktree"
  resume_for_test() {
    : > "$log"
    HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      FIXTURE_LOG="$log" FIXTURE_SESSION="$session" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker \
      "$ROOT/scripts/peer-delegate.sh" --to claude --repo "$project" \
      --artifact-dir "$project/artifacts" --no-verify --allow-no-change --resume-session "$session" \
      --prompt p >"$log.out" 2>"$log.err"
  }
  next_tied_mtime_ns() {
    python3 - "$projects" "$session" <<'PY' | tr -d '\r'
import os, stat, sys
projects, session = sys.argv[1:3]
times = []
for name in os.listdir(projects):
    path = os.path.join(projects, name, session + ".jsonl")
    try:
        st = os.lstat(path)
    except OSError:
        continue
    if stat.S_ISREG(st.st_mode):
        times.append(st.st_mtime_ns)
print(max(times) + 1000000000)
PY
  }
  set_resume_copy_mtime() {
    local name="$1" body="$2" mtime_ns="$3"
    mkdir -p "$projects/$name"
    python3 - "$projects/$name/$session.jsonl" "$body" "$mtime_ns" <<'PY'
import os, sys
path, body, mtime_ns = sys.argv[1:4]
with open(path, "wb") as f:
    f.write(body.encode())
timestamp = int(mtime_ns)
os.utime(path, ns=(timestamp, timestamp))
PY
  }

  local tie_ns
  tie_ns="$(next_tied_mtime_ns)"
  set_resume_copy_mtime -tie-a A "$tie_ns"
  set_resume_copy_mtime -tie-b B "$tie_ns"
  set_resume_copy_mtime -tie-c B "$tie_ns"
  if resume_for_test; then fail "differing newest tied copies must be rejected"; fi
  grep -q 'error: ambiguous claude session .*newest copies share a timestamp' "$log.err" ||
    fail "tied-copy rejection did not report the expected ambiguity"
  [ ! -s "$log" ] || fail "ambiguous tied copies must be rejected before invoking Claude"

  tie_ns="$(next_tied_mtime_ns)"
  set_resume_copy_mtime -tie-a A "$tie_ns"
  set_resume_copy_mtime -tie-b A "$tie_ns"
  set_resume_copy_mtime -tie-c A "$tie_ns"
  resume_for_test || fail "three identical newest tied copies should resume"
  assert_file_contains "$log" "session-body: A"

  tie_ns="$(next_tied_mtime_ns)"
  set_resume_copy_mtime -tie-a C "$tie_ns"
  set_resume_copy_mtime -tie-b C "$tie_ns"
  set_resume_copy_mtime -tie-c C "$tie_ns"
  set_resume_copy_mtime -tie-older distinct "$((tie_ns - 1))"
  resume_for_test || fail "a differing older copy must not make identical newest copies ambiguous"
  assert_file_contains "$log" "session-body: C"

  rm -rf "$projects/-tie-a" "$projects/-tie-b" "$projects/-tie-c" "$projects/-tie-older"

  # A newer copy of the session wins over the original; links never copy.
  printf 'round2\n' > "$projects/-newer-worktree/$session.jsonl"
  touch -t 202001010000 "$projects/-old-worktree/$session.jsonl"
  resume_for_test || fail "resume with two copies failed"
  assert_file_contains "$log" "session-body: round2"
  rm -f "$projects/-newer-worktree/$session.jsonl"
  printf 'keep\n' > "$outside"
  ln -s "$outside" "$projects/-newer-worktree/$session.jsonl"
  resume_for_test || true
  [ "$(cat "$outside")" = keep ] || fail "resume must not write through a symlink"
  if grep -q 'session-body: keep' "$log"; then fail "a symlinked source must not be copied"; fi
}

test_delegate_missing_cli_writes_exit_and_index() {
  local project="$TMP/delegate-missing-cli"
  local artifact_dir="$project/artifacts"
  local home_dir="$project/home"
  local artifact
  local rc=0

  make_committed_repo "$project"
  mkdir -p "$home_dir"
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --verify 'echo unnecessary-verifier-ran' \
    --prompt "Fix missing provider" >"$project/out" 2>"$project/error" || rc=$?

  [ "$rc" = "1" ] || fail "delegate missing provider should exit 1, got $rc"
  assert_file_contains "$project/out" "worker: codex exit 127"
  artifact="$(find "$artifact_dir" -type f -name 'codex-fix-missing-provider-*.md' | sed -n '1p')"
  [ -n "$artifact" ] || fail "delegate missing provider should still write artifact"
  assert_file_contains "$artifact" "SKIPPED: command not found: codex"
  assert_file_contains "$artifact" "## Exit"
  assert_file_contains "$artifact" "127"
  if grep -Fxq unnecessary-verifier-ran "$artifact"; then
    fail "missing provider must not spend time running the verifier"
  fi
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"kind": "delegate"'
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"exit": 1'

  # A structured provider failure followed by a successful panel fallback is
  # judged on the fallback's own output: not blocked (126), indexed to it.
  local swap="$TMP/delegate-provider-fallback"
  mkdir -p "$swap/bin" "$swap/user-home"
  make_committed_repo "$swap/repo"
  cat > "$swap/bin/codex" <<'EOF'
#!/usr/bin/env bash
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac
printf '%s\n' '{"type":"turn.failed","error":{"message":"exceeded retry limit, last status: 429 Too Many Requests"}}'
exit 1
EOF
  cat > "$swap/bin/claude" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in --version|--help) exit 0 ;; esac
printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"done"}'
EOF
  chmod +x "$swap/bin/codex" "$swap/bin/claude"
  rc=0
  HOME="$swap/user-home" NVM_DIR="$swap/user-home/.nvm" PATH="$swap/bin:/usr/bin:/bin" \
    OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker OMS_PANEL_FALLBACK_PROVIDER=claude \
    OMS_PANEL_FALLBACK_MODEL=claude-sonnet-5-5 OMS_PANEL_FALLBACK_EFFORT=medium \
    "$ROOT/scripts/peer-delegate.sh" --to codex --model gpt-6.1-sol \
    --repo "$swap/repo" --artifact-dir "$swap/artifacts" \
    --allow-no-change --prompt "Fix after provider fallback" >"$swap/out" 2>"$swap/error" || rc=$?
  [ "$rc" = 0 ] || fail "delegate after a successful fallback should exit 0, got $rc: $(cat "$swap/out" "$swap/error")"
  if grep -Fq 'could not run' "$swap/out" "$swap/error"; then
    fail "a successful fallback was reported as blocked: $(cat "$swap/error")"
  fi
  python3 - "$swap/repo" <<'PY' || fail "fallback delegate row is not the fallback's: $(cat "$swap/repo/.oms/artifacts/index.jsonl")"
import json, pathlib, sys
row = json.loads((pathlib.Path(sys.argv[1]) / '.oms/artifacts/index.jsonl').read_text().splitlines()[-1])
assert row['kind'] == 'delegate' and row['exit'] == 0 and row['provider'] == 'claude', row
assert row['selected_model'] == 'claude-sonnet-5-5' and row['fallback_used'] is True, row
assert row['fallback_reason'] == 'provider-capacity', row
PY
}



