test_artifact_index_records_call() {
  local project="$TMP/artifact-index-call"
  local artifact_dir="$project/artifacts"
  local out

  mkdir -p "$project"
  OH_MY_SETTING_CALL_DRY_RUN=1 "$ROOT/scripts/agent-call.sh" \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --to codex \
    --prompt "Assess artifact indexing" >/dev/null

  [ -s "$project/.oms/artifacts/index.jsonl" ] || fail "artifact index missing"
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"kind": "call"'
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"provider": "codex"'
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"artifact": "artifacts/codex-assess-artifact-indexing-'

  out="$($ROOT/scripts/artifact-index.sh --repo "$project" latest)"
  contains "$out" 'call  codex  exit=0' || fail "artifact-index latest missing call row"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" telemetry --json > "$project/telemetry.json"
  python3 - "$project" <<'PY' || fail "primary prompt byte measurement missing or inconsistent"
import json, pathlib, sys
repo = pathlib.Path(sys.argv[1])
row = json.loads((repo / '.oms/artifacts/index.jsonl').read_text().splitlines()[-1])
assert type(row['prompt_bytes']) is int and row['prompt_bytes'] > len('Assess artifact indexing'), row
metric = json.loads((repo / 'telemetry.json').read_text())['usage']['prompt_bytes']
assert metric['reports'] == 1 and metric['total'] == row['prompt_bytes'], metric
assert 'not tokens' in metric['basis'] and 'repair' in metric['basis'], metric
PY

  # A failed panel route records its selection and why no retry ran.
  local absent="$TMP/artifact-index-no-alternate"
  mkdir -p "$absent/bin" "$absent/repo"
  cat > "$absent/bin/codex" <<'EOF'
#!/usr/bin/env bash
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac
printf '%s\n' '{"type":"turn.failed","error":{"message":"Selected model is at capacity. Please try a different model."}}'
exit 1
EOF
  chmod +x "$absent/bin/codex"
  git -C "$absent/repo" init -q -b main
  PATH="$absent/bin:$PATH" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=advisor OMS_PANEL_PURPOSE=advise \
    OMS_PANEL_FALLBACK_DECISION=no-eligible-alternate OMS_AGENT=codex "$ROOT/scripts/agent-call.sh" \
    --repo "$absent/repo" --artifact-dir "$absent/artifacts" --to codex --model gpt-6.1-sol \
    --prompt "Assess failed route" >"$absent/out" 2>&1 || true
  python3 - "$absent/repo/.oms/lifecycle/events.jsonl" <<'PYREF' || fail "missing fallback decision refs"
import json, sys
refs = {}
for line in open(sys.argv[1]):
    refs.update(json.loads(line).get('refs') or {})
assert refs['panel_fallback_decision'] == 'no-eligible-alternate', refs
assert refs['panel_fallback_skip'] == 'no-fallback-route', refs
PYREF

  # A panel read call that failed over to the other provider is indexed, printed
  # and attributed to the provider that answered, never the one that failed.
  local swap="$TMP/artifact-index-call-swap"
  mkdir -p "$swap/bin" "$swap/repo"
  cat > "$swap/bin/codex" <<'EOF'
#!/usr/bin/env bash
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac
printf '%s\n' 'ERROR: model not found' >&2
exit 7
EOF
  cat > "$swap/bin/claude" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in --version|--help) exit 0 ;; esac
printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"ok"}'
EOF
  chmod +x "$swap/bin/codex" "$swap/bin/claude"
  git -C "$swap/repo" init -q -b main
  out="$(PATH="$swap/bin:$PATH" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=advisor OMS_PANEL_PURPOSE=advise \
    OMS_PANEL_FALLBACK_PROVIDER=claude OMS_PANEL_FALLBACK_MODEL=claude-sonnet-5-5 \
    OMS_PANEL_FALLBACK_DECISION=selected OMS_PANEL_FALLBACK_EFFORT=medium OMS_AGENT=codex "$ROOT/scripts/agent-call.sh" \
    --repo "$swap/repo" --artifact-dir "$swap/artifacts" --to codex --model gpt-6.1-sol \
    --prompt "Assess provider fallback attribution" 2>&1)" || fail "fallback advisor call failed: $out"
  contains "$out" 'ok: claude ->' || fail "fallback call did not name the provider that answered: $out"
  python3 - "$swap/repo" "$swap/artifacts" <<'PY' || fail "fallback call was attributed to the provider that failed"
import json, pathlib, sys
repo = pathlib.Path(sys.argv[1])
row = json.loads((repo / '.oms/artifacts/index.jsonl').read_text().splitlines()[-1])
assert row['kind'] == 'call' and row['exit'] == 0 and row['provider'] == 'claude', row
assert row['selected_model'] == 'claude-sonnet-5-5' and row['fallback_used'] is True, row
assert row['fallback_reason'] == 'provider-model-unavailable', row
events = [json.loads(line) for line in (repo / '.oms/lifecycle/events.jsonl').read_text().splitlines()]
refs = {}
for event in events:
    if event['attempt_id'] == row['attempt_id']:
        refs.update(event.get('refs') or {})
assert refs['panel_provider'] == 'claude' and refs['panel_model'] == 'claude-sonnet-5-5', refs
assert refs['panel_fallback'] == 'provider-model-unavailable', refs
assert refs['panel_fallback_decision'] == 'selected', refs
assert refs['panel_fallback_provider'] == 'claude' and refs['panel_fallback_model'] == 'claude-sonnet-5-5', refs
assert 'panel_fallback_skip' not in refs, refs
sidecars = list(pathlib.Path(sys.argv[2]).glob('*.attempts.json'))
assert len(sidecars) == 1, sidecars
attempts = json.loads(sidecars[0].read_text())['attempts']
assert [(a['provider'], a['model'], a['exit']) for a in attempts] == [
    ('codex', 'gpt-6.1-sol', 7), ('claude', 'claude-sonnet-5-5', 0)], attempts
assert attempts[0]['classification'] == 'model_unavailable' and attempts[1]['effort'] == 'medium', attempts
assert attempts[1]['stop_reason'].startswith('provider=claude reason=end_turn '), attempts
outputs = [(sidecars[0].parent / a['output']).read_text() for a in attempts]
assert 'ERROR: model not found' in outputs[0] and 'ok' in outputs[1].splitlines(), outputs
assert 'ERROR: model not found' not in outputs[1], outputs
PY
}

test_artifact_index_telemetry_is_scoped_and_read_only() {
  local project="$TMP/artifact-index-telemetry"
  local artifact_dir="$project/.oms/artifacts"
  local index="$artifact_dir/index.jsonl"
  local out
  local human
  local before
  local after

  mkdir -p "$artifact_dir"
  cat > "$artifact_dir/call.md" <<'EOF'
# Agent Call

- started: 2026-07-01T00:00:00Z

## Output

tokens used
1,200
EOF
  cat > "$artifact_dir/delegate.md" <<'EOF'
# Agent Delegate

- started: 2026-07-01T00:00:10Z

## Role

Example output format:

## Output

usage detail: {"provider":"claude","input_tokens":1200,"output_tokens":900}
tokens used
2,100

## Brief

Quoted example from the task:

usage detail: {"provider":"claude","input_tokens":8000,"output_tokens":7000}
tokens used
15,000

## Output

tokens used
3,000
EOF
  cat > "$index" <<'EOF'
{"schema":1,"event_id":"evt-call","operation_id":"op-call","artifact_id":"artifact-call","ts":"2026-07-01T00:00:03Z","kind":"call","provider":"codex","exit":0,"model_class":"fast","selected_model":"gpt-fast","fallback_used":false,"artifact":".oms/artifacts/call.md"}
{"schema":1,"event_id":"evt-delegate","operation_id":"op-delegate","artifact_id":"artifact-delegate","ts":"2026-07-01T00:00:16Z","kind":"delegate","provider":"claude","exit":1,"verify_exit":2,"model_class":"deep","selected_model":"claude-deep","fallback_used":true,"fallback_reason":"capacity","artifact":".oms/artifacts/delegate.md"}
{"schema":1,"event_id":"evt-export","operation_id":"op-export","artifact_id":"artifact-export","ts":"2026-07-01T00:00:17Z","kind":"call-export","provider":"codex","exit":0}
{"schema":1,"event_id":"evt-admit","operation_id":"op-admit","artifact_id":"artifact-admit","ts":"2026-07-01T00:00:18Z","kind":"patch-admit","provider":"local","exit":0}
{"schema":1,"event_id":"evt-resolution","operation_id":"op-delegate","artifact_id":"artifact-delegate","parent_event_id":"evt-delegate","resolves_event_id":"evt-delegate","resolution":"resolved","ts":"2026-07-01T00:00:19Z","kind":"artifact-resolution","provider":"local","exit":0}
{"schema":1,"event_id":["bad-shape"],"ts":"2026-07-01T00:00:20Z","kind":[],"provider":"local","exit":"unknown"}
not-json
EOF

  before="$(find "$artifact_dir" -type f -print | LC_ALL=C sort |
    while IFS= read -r file; do cksum "$file"; done)"
  if out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" \
      --json telemetry 2>&1)"; then
    fail "artifact telemetry must refuse a structurally corrupt index: $out"
  fi
  after="$(find "$artifact_dir" -type f -print | LC_ALL=C sort |
    while IFS= read -r file; do cksum "$file"; done)"
  [ "$before" = "$after" ] ||
    fail "refused artifact telemetry mutated the retained index or artifacts"

  # A schema-invalid JSON object remains visible as excluded mechanical data;
  # a non-JSON row cannot be skipped into a partial-looking telemetry report.
  sed '$d' "$index" > "$index.clean"
  mv "$index.clean" "$index"
  before="$(find "$artifact_dir" -type f -print | LC_ALL=C sort |
    while IFS= read -r file; do cksum "$file"; done)"
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" --json telemetry)" ||
    fail "artifact telemetry should be available for a structural index: $out"
  after="$(find "$artifact_dir" -type f -print | LC_ALL=C sort |
    while IFS= read -r file; do cksum "$file"; done)"
  [ "$before" = "$after" ] ||
    fail "artifact telemetry must not mutate the retained index or artifacts"

  if ! OMS_ARTIFACT_TELEMETRY_JSON="$out" python3 - <<'PY'
import json
import os

report = json.loads(os.environ["OMS_ARTIFACT_TELEMETRY_JSON"])
assert report["schema"] == 1 and report["action"] == "telemetry", report
assert report["semantic_outcome"] == "mechanical-only", report
assert report["window"]["scope"] == "retained-index-window", report
assert report["window"]["available_rows"] == 6, report
assert report["window"]["selected_rows"] == 6, report
assert report["window"]["limit"] == 1000, report
assert report["window"]["invalid_lines"] == 0, report
assert report["operations"] == {"eligible": 2, "excluded": 4}, report
assert report["recorded_exit"] == {
    "zero": 1, "nonzero": 1, "unavailable": 0
}, report
assert report["verification"] == {
    "recorded": 1, "zero": 0, "nonzero": 1, "unavailable": 1
}, report
assert report["outcomes"] == {
    "verified_success": 0, "verified_failure": 1, "unknown": 1
}, report
assert report["fallback"]["used"] == 1, report
assert report["fallback"]["not_used"] == 1, report
assert report["fallback"]["unrecorded"] == 0, report
assert report["fallback"]["reasons"] == [{"reason": "capacity", "count": 1}], report
assert report["resolution"] == {
    "events": 1, "resolved_nonzero": 1, "unresolved_nonzero": 0
}, report
assert report["coverage"] == {
    "routing_metadata": 2,
    "artifact_files": 2,
    "duration_reports": 2,
    "token_reports": 2,
    "verification_reports": 1,
}, report
assert report["usage"]["provider_reported_tokens"] == {
    "reports": 2, "total": 4200
}, report
assert report["usage"]["wall_seconds"] == {
    "reports": 2, "total": 9.0, "median": 4.5
}, report
routes = {
    (row["provider"], row["model_class"], row["selected_model"]): row
    for row in report["routes"]
}
assert routes[("codex", "fast", "gpt-fast")]["operations"] == 1, routes
assert routes[("codex", "fast", "gpt-fast")]["recorded_exit_zero"] == 1, routes
assert routes[("claude", "deep", "claude-deep")]["recorded_exit_nonzero"] == 1, routes
assert routes[("claude", "deep", "claude-deep")]["fallback_used"] == 1, routes
PY
  then
    fail "artifact telemetry JSON conflated or omitted recorded evidence"
  fi

  python3 - "$project" "$index" "$ROOT/scripts/lib/artifact-telemetry.py" <<'PY' || fail "prompt examples were counted as delegate usage"
import json, runpy, sys
repo, index, helper = sys.argv[1:]
row = next(row for row in map(json.loads, open(index)) if row.get("event_id") == "evt-delegate")
telemetry = runpy.run_path(helper)
assert telemetry["artifact_metrics"](repo, row)[2] == 3000, row
assert telemetry["artifact_usage_metrics"](repo, row) is None, row
PY

  human="$("$ROOT/scripts/artifact-index.sh" --repo "$project" telemetry)"
  contains "$human" 'retained window: 6/6 row(s)' ||
    fail "human telemetry should disclose its retained window: $human"
  contains "$human" 'semantic outcome: mechanical-only' ||
    fail "human telemetry must distinguish mechanical verification from task success: $human"
  contains "$human" 'provider-reported tokens: total=4200 reports=2' ||
    fail "human telemetry should expose the measured token subtotal: $human"
  printf '%s\n' '{"kind":"delegate","provider":"codex","exit":0,"verify_exit":0,"context_verification":"none"}' >> "$index"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" --json telemetry |
    python3 -c 'import json,sys; row=json.load(sys.stdin); assert row["outcomes"]["verified_success"] == 0; assert row["verification"]["unavailable"] == 2' ||
    fail "no-verify placeholder counted as a real verification"
  cat > "$artifact_dir/usage.md" <<'EOF'
## Output
usage detail: {"provider":"antigravity","input_tokens":100,"cache_read_tokens":40,"output_tokens":10}
usage detail: {"provider":"antigravity","input_tokens":30,"cache_read_tokens":5,"output_tokens":2}
EOF
  printf '%s\n' '{"kind":"delegate","provider":"antigravity","model_class":"explicit","selected_model":"agy-model","artifact":".oms/artifacts/usage.md"}' >> "$index"
  printf '%s\n' '{"kind":"call","provider":"codex","model_class":"fast","selected_model":"gpt-fast","provider_usage":{"provider":"codex","input_tokens":20,"cache_read_tokens":10,"output_tokens":3}}' >> "$index"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" --json telemetry | python3 -c '
import json, sys
r = json.load(sys.stdin)
rows = {(x["provider"], x["selected_model"]): x for x in r["routes"]}
assert rows[("antigravity", "agy-model")]["usage_detail"] == {"input_tokens": 130, "cache_read_tokens": 45, "output_tokens": 12, "reports": 1}
assert rows[("codex", "gpt-fast")]["usage_detail"] == {"input_tokens": 20, "cache_read_tokens": 10, "output_tokens": 3, "reports": 1}
' || fail "per-route usage detail missing"
  human="$("$ROOT/scripts/artifact-index.sh" --repo "$project" telemetry)"
  contains "$human" 'tokens: provider=antigravity model=agy-model input=130 cached=45 output=12 reports=1' ||
    fail "human telemetry omitted provider detail: $human"

  # Two resumed-session reports carry a running total. The per-route sums must
  # leave them out, as the grouped view does, and say how many were left out.
  printf '%s\n' '{"kind":"call","provider":"codex","model_class":"fast","selected_model":"gpt-fast","provider_usage":{"provider":"codex","input_tokens":5000,"cache_read_tokens":100,"output_tokens":50,"session_cumulative":true}}' >> "$index"
  printf '%s\n' '{"kind":"call","provider":"codex","model_class":"fast","selected_model":"gpt-fast","provider_usage":{"provider":"codex","input_tokens":9000,"cache_read_tokens":200,"output_tokens":90,"session_cumulative":true}}' >> "$index"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" --json telemetry | python3 -c '
import json, sys
r = json.load(sys.stdin)
rows = {(x["provider"], x["selected_model"]): x for x in r["routes"]}
codex = rows[("codex", "gpt-fast")]
assert codex["usage_detail"] == {"input_tokens": 20, "cache_read_tokens": 10, "output_tokens": 3, "reports": 1}, codex
assert codex["operations"] == 4 and codex["cumulative_reports_excluded"] == 2, codex
assert rows[("antigravity", "agy-model")]["cumulative_reports_excluded"] == 0
assert r["usage"]["cumulative_reports_excluded"] == 2, r["usage"]
' || fail "cumulative reports must stay out of the per-route sums and be counted"
  human="$("$ROOT/scripts/artifact-index.sh" --repo "$project" telemetry)"
  contains "$human" 'tokens: provider=codex model=gpt-fast input=20 cached=10 output=3 reports=1' ||
    fail "human telemetry added a resumed session's running total: $human"
  contains "$human" 'cumulative: 2 resumed-session report(s) carry a running total and are left out of the tokens lines' ||
    fail "human telemetry must disclose the excluded cumulative reports: $human"

  # --by groups the same rows by a recorded field, and --since/--until bound
  # them by their own time. Only reported values are shown: `-` when no call
  # in the group reported one, `N+?` when only some did; a resumed session's
  # running total is left out rather than added twice; cost is never priced.
  local usage="$project/usage" by
  mkdir -p "$usage/.oms/artifacts"
  git -C "$usage" init -q
  cat > "$usage/.oms/artifacts/index.jsonl" <<'EOF'
{"schema":1,"event_id":"u1","operation_id":"o1","artifact_id":"a1","ts":"2026-07-01T23:59:59Z","kind":"call","provider":"codex","exit":0,"model_class":"fast","selected_model":"gpt-fast","tokens":1200,"task_id":"task-a","provider_usage":{"provider":"codex","input_tokens":1000,"cache_read_tokens":400,"output_tokens":200}}
{"schema":1,"event_id":"u2","operation_id":"o2","artifact_id":"a2","ts":"2026-07-02T00:00:00Z","kind":"delegate","provider":"claude","exit":0,"model_class":"explicit","selected_model":"opus","served_model":"opus-served","tokens":3000,"cost_usd":0.25,"task_id":"task-a"}
{"schema":1,"event_id":"u3","operation_id":"o3","artifact_id":"a3","ts":"2026-07-02T10:00:00Z","kind":"call","provider":"codex","exit":0,"model_class":"fast","selected_model":"gpt-fast","provider_usage":{"provider":"codex","input_tokens":9000,"cache_read_tokens":10,"output_tokens":3,"session_cumulative":true}}
{"schema":1,"event_id":"u4","operation_id":"o4","artifact_id":"a4","ts":"2026-07-03T10:00:00Z","kind":"review","provider":"claude","exit":0,"model_class":"explicit","selected_model":"opus","served_model":"opus-served","tokens":500,"cost_usd":0.05}
{"schema":1,"event_id":"u5","operation_id":"o5","artifact_id":"a5","kind":"call","provider":"codex","exit":0}
{"schema":1,"event_id":"u6","operation_id":"o6","artifact_id":"a6","ts":"2026-07-03T11:00:00Z","kind":"patch-admit","provider":"local","exit":0}
EOF
  by="$("$ROOT/scripts/artifact-index.sh" --repo "$usage" telemetry --by day)" ||
    fail "telemetry --by day should run: $by"
  contains "$by" 'usage by day (UTC): 5 routed operation(s) in 6/6 retained row(s) (limit 1000)' ||
    fail "grouped telemetry must state its window and that days are UTC: $by"
  contains "$by" 'window complete: every matching retained row is counted' ||
    fail "grouped telemetry must say the window was not capped: $by"
  printf '%s\n' "$by" | grep -Eq '^2026-07-01 +1 +1200 +1000 +400 +200 +-$' ||
    fail "a fully reported day should show its totals and no cost: $by"
  printf '%s\n' "$by" | grep -Eq '^2026-07-02 +2 +3000\+\? +- +- +- +0\.2500\+\?$' ||
    fail "a partly reported day must be marked +? and must not add a cumulative report: $by"
  printf '%s\n' "$by" | grep -Eq '^undated +1 +- +- +- +- +-$' ||
    fail "a row without a time is its own group, and unreported is not zero: $by"
  contains "$by" 'cumulative: 1 resumed-session report(s)' ||
    fail "an excluded cumulative report must be disclosed: $by"
  by="$("$ROOT/scripts/artifact-index.sh" --repo "$usage" telemetry --by model)"
  printf '%s\n' "$by" | grep -Eq '^opus-served +2 +3500 +- +- +- +0\.3000$' ||
    fail "model grouping should use the served model and sum reported cost: $by"
  by="$("$ROOT/scripts/artifact-index.sh" --repo "$usage" telemetry --by task)"
  printf '%s\n' "$by" | grep -Eq '^task-a +2 +4200 ' ||
    fail "task grouping should use the recorded task id: $by"
  printf '%s\n' "$by" | grep -Eq '^unrecorded +3 ' ||
    fail "task grouping should keep rows without a task id unrecorded: $by"
  by="$("$ROOT/scripts/artifact-index.sh" --repo "$usage" telemetry --by provider --since 2026-07-02 --until 2026-07-02)"
  contains "$by" 'in 2/6 retained row(s) (2 in range; limit 1000)' ||
    fail "a date range should keep exactly that UTC day: $by"
  contains "$by" 'undated: 1 row(s) carry no time and are outside any range' ||
    fail "a range must say which rows it could not place: $by"
  by="$("$ROOT/scripts/artifact-index.sh" --repo "$usage" telemetry 2 --by provider --since 2026-07-01)"
  contains "$by" 'window capped: the 3 oldest matching row(s) are not counted' ||
    fail "a capped window must not read as complete: $by"
  "$ROOT/scripts/artifact-index.sh" --repo "$usage" --json telemetry --by day --until 2026-07-02T00:00:00Z | python3 -c '
import json, sys
r = json.load(sys.stdin)
block = r["usage_by"]
assert r["window"]["matched_rows"] == 2 and r["window"]["timezone"] == "UTC", r["window"]
assert block["by"] == "day" and block["capped"] is False, block
days = {g["group"]: g for g in block["groups"]}
assert sorted(days) == ["2026-07-01", "2026-07-02"], days
assert days["2026-07-01"]["cost_usd"] is None and days["2026-07-01"]["input_tokens"] == 1000, days
assert days["2026-07-02"]["cost_usd"] == 0.25 and days["2026-07-02"]["usage_reports"] == 0, days
' || fail "grouped telemetry JSON should carry usage_by and the bounded window"
  "$ROOT/scripts/artifact-index.sh" --repo "$usage" --json telemetry | python3 -c '
import json, sys
r = json.load(sys.stdin)
assert "usage_by" not in r and "matched_rows" not in r["window"], r["window"]
' || fail "ungrouped, unbounded telemetry JSON must keep its shape"
  human="$("$ROOT/scripts/artifact-index.sh" --repo "$usage" telemetry --since 2026-07-03)"
  contains "$human" 'retained window: 2/6 row(s)' ||
    fail "the summary should honor --since too: $human"
  # --by role: a delegate row records its role; any other row is `unknown`.
  # Admission is a later successful patch-admit/patch-land carrying the same
  # patch digest. Cache share = cache_read / (input + cache_read) as reported,
  # and a group under the threshold with enough reports is warned about.
  local roles="$project/roles" dig_a dig_b
  dig_a="$(printf a | sha256sum | cut -d' ' -f1)"
  dig_b="$(printf b | sha256sum | cut -d' ' -f1)"
  mkdir -p "$roles/.oms/artifacts"
  git -C "$roles" init -q
  cat > "$roles/.oms/artifacts/index.jsonl" <<EOF
{"schema":1,"event_id":"r1","ts":"2026-07-01T00:00:01Z","kind":"delegate","provider":"codex","exit":0,"role":"reviewer","tokens":1000,"patch_sha256":"$dig_a","provider_usage":{"input_tokens":100,"cache_read_tokens":300,"output_tokens":10}}
{"schema":1,"event_id":"r2","ts":"2026-07-01T00:00:02Z","kind":"delegate","provider":"codex","exit":0,"role":"reviewer","tokens":400,"patch_sha256":"$dig_b","provider_usage":{"input_tokens":100,"cache_read_tokens":100,"output_tokens":10}}
{"schema":1,"event_id":"r3","ts":"2026-07-01T00:00:03Z","kind":"delegate","provider":"claude","exit":1,"role":"builder","tokens":50}
{"schema":1,"event_id":"r4","ts":"2026-07-01T00:00:04Z","kind":"call","provider":"claude","exit":0,"tokens":20,"provider_usage":{"input_tokens":50,"cache_read_tokens":50,"output_tokens":1,"cache_in_input":true}}
{"schema":1,"event_id":"r5","ts":"2026-07-01T00:00:05Z","kind":"patch-admit","provider":"local","exit":0,"patch_sha256":"$dig_a"}
{"schema":1,"event_id":"r6","ts":"2026-07-01T00:00:06Z","kind":"patch-admit","provider":"local","exit":1,"patch_sha256":"$dig_b"}
EOF
  by="$(OMS_TELEMETRY_CACHE_MIN_REQUESTS=2 "$ROOT/scripts/artifact-index.sh" --repo "$roles" telemetry --by role)" ||
    fail "telemetry --by role should run: $by"
  printf '%s\n' "$by" | grep -Eq '^reviewer +2 +1400 +200 +400 +20 +- +66\.7% +1 +1400 +400$' ||
    fail "role row: cache 400/600, one admitted, rejected patch's tokens counted: $by"
  printf '%s\n' "$by" | grep -Eq '^builder +1 +50 +- +- +- +- +- +0 +- +50$' ||
    fail "a failed delegate with no usage is unadmitted and not priced: $by"
  printf '%s\n' "$by" | grep -Eq '^unknown +1 +20 +50 +50 +1 +- +100\.0% +0 +- +0$' ||
    fail "a row without a role is unknown, and cache_in_input is not double counted: $by"
  contains "$by" 'warning: cache-read share 66.7% is under 80% for role reviewer (2 usage reports)' ||
    fail "a low-share group with enough reports must be warned about: $by"
  contains "$by" 'never approval evidence' || fail "role view must say it is not approval evidence: $by"
  by="$("$ROOT/scripts/artifact-index.sh" --repo "$roles" telemetry --by role)"
  ! contains "$by" 'warning:' || fail "under the minimum report count there is no warning: $by"
  OMS_TELEMETRY_CACHE_MIN_REQUESTS=2 "$ROOT/scripts/artifact-index.sh" --repo "$roles" --json telemetry --by role | python3 -c '
import json, sys
block = json.load(sys.stdin)["usage_by"]
g = {x["group"]: x for x in block["groups"]}
assert block["by"] == "role" and len(block["warnings"]) == 1 and block["cache_warn"] == {"min_pct": 80, "min_requests": 2}, block
assert g["reviewer"]["cache_read_share"] == 0.6667 and g["reviewer"]["admitted"] == 1, g
assert g["reviewer"]["tokens_per_admitted"] == 1400 and g["reviewer"]["not_admitted_tokens"] == 400, g
assert g["builder"]["not_admitted_results"] == 1 and g["unknown"]["cache_read_share"] == 1.0, g
' || fail "role JSON should carry share, admission and warnings"
  # The writer records the role on delegate rows only.
  local wrote="$project/roles-write"
  mkdir -p "$wrote"
  git -C "$wrote" init -q
  (
    # shellcheck source=scripts/lib/peer-common.sh
    . "$ROOT/scripts/lib/peer-common.sh"
    export OMS_MODEL_ROLE=reviewer
    ma_append_artifact_index "$wrote" delegate codex 0 "" "" "" "" ""
    ma_append_artifact_index "$wrote" call codex 0 "" "" "" "" ""
  ) >/dev/null 2>&1 || fail "role-recording appends should succeed"
  python3 - "$wrote/.oms/artifacts/index.jsonl" <<'PY' || fail "only delegate rows record the role"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8")]
assert [r.get("role") for r in rows] == ["reviewer", None], rows
PY
  ! "$ROOT/scripts/artifact-index.sh" --repo "$usage" telemetry --by team >/dev/null 2>&1 ||
    fail "an unknown grouping must be refused"
  ! "$ROOT/scripts/artifact-index.sh" --repo "$usage" telemetry --since yesterday >/dev/null 2>&1 ||
    fail "an unparseable --since must be refused"
  ! "$ROOT/scripts/artifact-index.sh" --repo "$usage" list --by day >/dev/null 2>&1 ||
    fail "--by is only valid with telemetry"
}

test_artifact_index_latest_run_groups_rows() {
  local project="$TMP/artifact-index-latest-run"
  local index="$project/.oms/artifacts/index.jsonl"
  local out

  mkdir -p "$project/.oms/artifacts/review" "$project/.oms/artifacts/delegate"
  cat > "$index" <<'EOF'
{"ts":"2026-06-11T00:00:01Z","kind":"review","provider":"codex","exit":0,"artifact":".oms/artifacts/review/codex-old-20260611T000001Z-10.md"}
{"ts":"2026-06-11T00:00:02Z","kind":"review","provider":"codex","exit":1,"artifact":".oms/artifacts/review/codex-new-20260611T000002Z-20.md"}
{"ts":"2026-06-11T00:00:03Z","kind":"review","provider":"codex","exit":0,"artifact":".oms/artifacts/review/codex-new-20260611T000002Z-20-r2.md"}
{"ts":"2026-06-11T00:00:04Z","kind":"review","provider":"claude","exit":0,"artifact":".oms/artifacts/review/claude-new-20260611T000002Z-20.md"}
{"ts":"2026-06-11T00:00:05Z","kind":"review","provider":"antigravity","exit":2,"artifact":".oms/artifacts/review/antigravity-slug-r9-20260611T000002Z-20.md"}
{"ts":"2026-06-11T00:00:06Z","kind":"delegate","provider":"codex","exit":0,"verify_exit":0,"artifact":".oms/artifacts/delegate/codex-new-20260611T000002Z-20.md","patch":".oms/artifacts/delegate/codex-new-20260611T000002Z-20.patch"}
EOF

  out="$($ROOT/scripts/artifact-index.sh --repo "$project" latest-run)"
  contains "$out" 'run: 20260611T000002Z-20  kind=delegate,review  debate_round=2' ||
    fail "latest-run missing grouped header: $out"
  contains "$out" 'review  codex  exit=0  artifact=.oms/artifacts/review/codex-new-20260611T000002Z-20-r2.md' ||
    fail "latest-run should keep final codex debate row"
  contains "$out" 'review  claude  exit=0' || fail "latest-run missing claude row"
  contains "$out" 'review  antigravity  exit=2' || fail "latest-run missing antigravity row"
  contains "$out" 'delegate  codex  exit=0  verify=0' ||
    fail "latest-run missing delegate verify exit"
  contains "$out" 'patch=.oms/artifacts/delegate/codex-new-20260611T000002Z-20.patch' ||
    fail "latest-run missing delegate patch"
  if printf '%s\n' "$out" | grep -F 'review  codex' |
    grep -F 'codex-new-20260611T000002Z-20.md' > /dev/null; then
    fail "base codex review row should not override round-2 row"
  fi

  printf '{"ts":"2026-06-11T00:00:07Z","kind":"call","provider":"codex","exit":0,"artifact":".oms/artifacts/call/unparseable.md"}\n' >> "$index"
  out="$($ROOT/scripts/artifact-index.sh --repo "$project" latest-run)"
  contains "$out" 'call  codex  exit=0  artifact=.oms/artifacts/call/unparseable.md' ||
    fail "latest-run should list unparseable artifact row individually"
}

# validate reports rows whose artifact is gone and nothing could repair them:
# the retention prune is a cap on row count, so any keep value either spares
# stale rows or discards good ones, and editing .oms by hand is forbidden. Found
# by deleting 360 test-fixture artifacts and watching doctor warn with no fix
# available.
# Duration and provider-reported tokens are parsed out of the artifact body, so
# reading them used to require the artifact to still exist: retention decided
# whether past calls could be accounted for, and pruning stale artifacts silently
# erased what they had cost. The row caches them at write time now.
test_artifact_index_accounting_survives_artifact_deletion() {
  local project="$TMP/index-accounting"
  local bin="$project/bin"
  local index="$project/.oms/artifacts/index.jsonl"
  local out

  make_committed_repo "$project"
  mkdir -p "$bin"
  {
    printf '%s\n' '#!/usr/bin/env bash'
    printf '%s\n' 'cat >/dev/null'
    printf '%s\n' 'printf "a real answer body for the classifier\n\ntokens used\n1234\n"'
  } > "$bin/codex"
  chmod +x "$bin/codex"

  ( cd "$project" && PATH="$bin:$PATH" "$ROOT/scripts/agent-call.sh" \
      --to codex --repo "$project" --prompt 'accounting probe' >/dev/null 2>&1 ) ||
    fail "the stubbed call should succeed"

  python3 - "$index" <<'PY' || fail "the row should cache duration and tokens"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
row = rows[-1]
assert isinstance(row.get("duration_s"), (int, float)), row
assert isinstance(row.get("tokens"), int) and row["tokens"] > 0, row
PY

  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" telemetry)"
  printf '%s' "$out" | grep >/dev/null -E 'token-reports=[1-9]' ||
    fail "telemetry should report the token count: $out"

  # The artifact goes; the accounting stays. Coverage of artifacts drops, which
  # is the honest part — the numbers do not.
  rm -rf "$project/.oms/artifacts/call"
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" telemetry)"
  contains "$out" 'artifacts=0' ||
    fail "artifact coverage should drop once the file is gone: $out"
  printf '%s' "$out" | grep >/dev/null -E 'token-reports=[1-9]' ||
    fail "token accounting must survive artifact deletion: $out"
  printf '%s' "$out" | grep >/dev/null -E 'durations=[1-9]' ||
    fail "duration accounting must survive artifact deletion: $out"
}

test_artifact_index_prunes_stale_references() {
  local project="$TMP/artifact-index-stale"
  local index="$project/.oms/artifacts/index.jsonl"
  local out

  mkdir -p "$project/.oms/artifacts/ask"
  printf 'kept\n' > "$project/.oms/artifacts/ask/present.md"
  printf '{"ts":"2026-06-11T00:00:01Z","kind":"call","artifact":".oms/artifacts/ask/present.md"}\n' >> "$index"
  printf '{"ts":"2026-06-11T00:00:02Z","kind":"call","artifact":".oms/artifacts/ask/gone.md"}\n' >> "$index"
  printf '{"ts":"2026-06-11T00:00:03Z","kind":"call","exit":0}\n' >> "$index"

  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune --stale --dry-run)"
  contains "$out" 'would drop 1 stale row' ||
    fail "dry-run should report the stale row: $out"
  [ "$(wc -l < "$index")" = "3" ] || fail "dry-run must not change the index"

  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune --stale)"
  contains "$out" 'dropped 1 stale row' || fail "stale sweep should report: $out"
  [ "$(wc -l < "$index")" = "2" ] || fail "stale sweep should drop exactly the stale row"
  grep -Fq 'present.md' "$index" || fail "a row whose artifact exists must survive"
  grep -Fq 'gone.md' "$index" && fail "the stale row must be gone"
  # A row that references no file at all is not stale.
  grep -Fq '00:00:03Z' "$index" || fail "a row with no artifact reference must survive"

  # Age is not the question, so --keep must not enter into it.
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune --stale)"
  contains "$out" 'no stale references' || fail "second sweep should be a no-op: $out"
  [ "$(wc -l < "$index")" = "2" ] || fail "a clean index must be left alone"

  # A resolution explains why an earlier failure is closed, so it cannot outlive
  # the row it resolves: leaving it behind trades one dangling reference for
  # another, and validate is the only thing that would ever notice.
  printf 'temp\n' > "$project/.oms/artifacts/ask/resolved.md"
  printf '{"ts":"2026-06-11T00:00:04Z","kind":"call","event_id":"evt_target","artifact":".oms/artifacts/ask/resolved.md"}\n' >> "$index"
  printf '{"ts":"2026-06-11T00:00:05Z","kind":"artifact-resolution","event_id":"evt_res","resolves_event_id":"evt_target"}\n' >> "$index"
  rm -f "$project/.oms/artifacts/ask/resolved.md"
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune --stale)"
  contains "$out" 'dropped 2 stale row' ||
    fail "the stale row and its orphaned resolution should go together: $out"
  ! grep -Fq 'evt_res' "$index" || fail "a resolution outlived the row it resolves"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" validate \
    > "$project/validate-out" 2>&1 || true
  # The fixture's minimal rows carry other schema gaps on purpose, so assert the
  # one error this sweep is capable of creating rather than a clean bill.
  ! grep -Fq 'resolution target' "$project/validate-out" ||
    fail "the stale sweep left a dangling resolution behind"
}

test_artifact_index_prune() {
  local project="$TMP/artifact-index-prune"
  local index="$project/.oms/artifacts/index.jsonl"
  local out
  local perms

  mkdir -p "$project/.oms/artifacts"
  for i in $(seq 1 10); do
    printf '{"ts":"2026-06-11T00:00:%02dZ","kind":"call","provider":"codex","exit":0}\n' "$i" >> "$index"
  done

  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune 3)"
  contains "$out" 'pruned 10 -> 3' || fail "prune should report 10 -> 3"
  [ "$(wc -l < "$index")" = "3" ] || fail "prune should keep exactly 3 rows"
  # Newest rows are kept (tail).
  tail -n1 "$index" | grep -F '00:10Z' > /dev/null || fail "prune must keep the newest rows"
  grep -Fq '00:01Z' "$index" && fail "prune must drop the oldest rows"

  # Under the keep count: no-op, exit 0.
  out="$("$ROOT/scripts/artifact-index.sh" --repo "$project" prune 100)" || fail "prune within keep should exit 0"
  contains "$out" 'nothing pruned' || fail "prune within keep should be a no-op"
  TMPDIR=/nonexistent-oms-tmp "$ROOT/scripts/artifact-index.sh" --repo "$project" prune 100 >/dev/null ||
    fail "prune no-op without --files must not require TMPDIR"

  # Prune is an in-place overwrite: file permissions survive.
  chmod 640 "$index"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" prune 2 >/dev/null
  perms="$(stat -c '%a' "$index" 2>/dev/null || stat -f '%Lp' "$index" 2>/dev/null)"
  [ "$perms" = "640" ] || fail "prune must preserve file permissions (got $perms)"

  python3 - "$ROOT" "$project" <<'PY' || fail "completion-pinned retention failed"
import datetime, hashlib, json, os, runpy, subprocess, sys
from pathlib import Path
root, repo = map(Path, sys.argv[1:])
index = repo / '.oms/artifacts/index.jsonl'
receipts = repo / '.oms/plan/completions'
receipts.mkdir(parents=True)
store = runpy.run_path(str(root / 'scripts/lib/artifact-index-store.py'))
retain = store['RETENTION']['retained_lines']
failure = dict(schema=1, event_id='evt_failure', kind='call', exit=1, operation_id='op', artifact_id='art',
               ts='2026-10-16T00:00:00Z', provider='codex')
successes = [dict(event_id='evt_ok%d' % i, kind='call', exit=0) for i in range(3)]
def lines(rows):
    return [json.dumps(row).encode() + b'\n' for row in rows]
failed_history = lines([failure] + successes)
assert failure in [json.loads(line) for line in retain(failed_history, 2)]
index.write_bytes(b''.join(failed_history))
store['append_rows'](str(repo), str(index), [dict(event_id='evt_new', exit=0)], keep=2, high=2)
assert 'evt_failure' in {json.loads(line)['event_id'] for line in index.read_bytes().splitlines()}
resolution = dict(schema=1, event_id='evt_resolution', kind='artifact-resolution', exit=0,
                  parent_event_id='evt_failure', resolves_event_id='evt_failure', resolution='resolved',
                  operation_id='op', artifact_id='art', ts='2026-10-16T00:00:01Z', provider='codex')
resolved_history = lines([failure, resolution] + successes)
assert 'evt_failure' not in {json.loads(line)['event_id'] for line in retain(resolved_history, 2)}
resolution['operation_id'] = 'foreign'
assert 'evt_failure' in {json.loads(line)['event_id'] for line in retain(lines([failure, resolution] + successes), 2)}
resolution['operation_id'] = 'op'
resolution.pop('provider')
assert 'evt_failure' in {json.loads(line)['event_id'] for line in retain(lines([failure, resolution] + successes), 2)}
try:
    retain(failed_history, 2, max_bytes=len(failed_history[-1]))
except ValueError:
    pass
else:
    raise AssertionError('protected failures exceeded the durable byte ceiling')
rows = []
for number, kind in enumerate(('research', 'main_research')):
    artifact = '.oms/artifacts/pinned-%d.md' % number
    (repo / artifact).write_text('accepted report\n')
    row = {'event_id': 'evt_pin%d' % number, 'kind': 'ask', 'artifact': artifact}
    rows.append(row)
    receipt = {'bundle': {kind: {'classification': 'research-only', 'index_event_id': row['event_id'],
                                'artifact': {'path': artifact, 'sha256': hashlib.sha256((repo / artifact).read_bytes()).hexdigest()}}},
               'snapshot': {'evidence': {'index': row}}}
    raw = json.dumps(receipt).encode()
    (receipts / (hashlib.sha256(raw).hexdigest() + '.json')).write_bytes(raw)
rows.extend({'event_id': 'evt_recent%d' % number} for number in range(4))
index.write_bytes(b''.join(json.dumps(row).encode() + b'\n' for row in rows))
def prune(*args):
    result = subprocess.run(['bash', str(root / 'scripts/artifact-index.sh'), '--repo', str(repo),
                             'prune', '1', *args], env=dict(os.environ, OMS_ARTIFACT_ORPHAN_GRACE='0'),
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30)
    assert result.returncode == 0, result.stderr.decode()
    return result.stdout.decode()
before = index.read_bytes()
assert 'would prune 6 -> 3' in prune('--dry-run')
assert index.read_bytes() == before
prune('--files')
assert {json.loads(line)['event_id'] for line in index.read_bytes().splitlines()} == {
    'evt_pin0', 'evt_pin1', 'evt_recent3'}
assert all((repo / row['artifact']).exists() for row in rows[:2])
# Automatic high-water compaction uses the same pins and allows a larger count.
store['append_rows'](str(repo), str(index), [{'event_id': 'evt_appended'}], keep=1, high=1)
assert {json.loads(line)['event_id'] for line in index.read_bytes().splitlines()} == {
    'evt_pin0', 'evt_pin1', 'evt_appended'}
# A stale sweep cannot remove a completion's referenced row.
(repo / rows[0]['artifact']).unlink()
prune('--stale')
assert 'evt_pin0' in {json.loads(line)['event_id'] for line in index.read_bytes().splitlines()}
(repo / rows[0]['artifact']).write_text('accepted report\n')
# A previously evicted row cannot turn a frozen artifact into an orphan.
index.write_text(json.dumps({'event_id': 'evt_newest'}) + '\n')
prune('--files')
assert all((repo / row['artifact']).exists() for row in rows[:2])
# Unreadable or oversized receipt scans keep more evidence, never less.
bad = receipts / ('0' * 64 + '.json')
bad.write_bytes(b'{')
index.write_bytes(before)
prune('--files')
assert index.read_bytes() == before
bad.unlink()
bad.symlink_to(next(receipts.iterdir()).name)
prune()
assert index.read_bytes() == before
bad.unlink()
bad.write_bytes(b' ' * (4 * 1024 * 1024 + 1))
prune()
assert index.read_bytes() == before
bad.unlink()
# Recent owner decisions survive ordinary pruning and stale sweeps, even when
# their indexed artifact is missing. Older decisions follow normal retention.
decision_repo = repo / 'decision-retention'
decision_index = decision_repo / '.oms/artifacts/index.jsonl'
decision_index.parent.mkdir(parents=True)
now = datetime.datetime.now(datetime.timezone.utc)
recent = now.isoformat().replace('+00:00', 'Z')
old = (now - datetime.timedelta(days=40)).isoformat().replace('+00:00', 'Z')
pin_decisions = store['RETENTION']['decision_pin_indices']
def decision_at(event_id, stamp):
    return json.dumps({'kind': 'panel-result', 'event_id': event_id, 'ts': stamp}).encode() + b'\n'
pin_probe = [
    decision_at('future-tolerance', (now + datetime.timedelta(seconds=3)).isoformat()),
    decision_at('future-expired', (now + datetime.timedelta(days=1)).isoformat()),
    decision_at('age-expired', old),
    decision_at('older-recent', (now - datetime.timedelta(days=2)).isoformat()),
    decision_at('newer-recent', (now - datetime.timedelta(days=1)).isoformat()),
]
assert store['RETENTION']['MAX_DECISION_PIN_ROWS'] == 3000
assert pin_decisions(pin_probe, now=now) == {0, 3, 4}
assert pin_decisions(pin_probe, now=now, max_rows=2) == {3, 4}
decision_rows = [
    {'kind': 'panel-result', 'task_id': 'task-a', 'event_id': 'a-old', 'ts': old,
     'artifact': '.oms/artifacts/panel-results/a-old.json'},
    {'kind': 'panel-result', 'task_id': 'task-a', 'event_id': 'a-latest', 'ts': recent,
     'artifact': '.oms/artifacts/panel-results/missing.json'},
    {'kind': 'panel-result', 'task_id': 'task-b', 'event_id': 'b-latest', 'ts': recent},
    {'kind': 'panel-result', 'task_id': 'task-old', 'event_id': 'old-decision', 'ts': old},
    {'event_id': 'ordinary-1'}, {'event_id': 'ordinary-2'},
]
decision_index.write_bytes(b''.join(json.dumps(row).encode() + b'\n' for row in decision_rows))
def prune_decisions(*args):
    result = subprocess.run(['bash', str(root / 'scripts/artifact-index.sh'), '--repo', str(decision_repo),
                             'prune', '1', *args], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30)
    assert result.returncode == 0, result.stderr.decode()
    return result.stdout.decode()
decision_before = decision_index.read_bytes()
assert 'would prune 6 -> 3' in prune_decisions('--dry-run')
assert decision_index.read_bytes() == decision_before
prune_decisions()
decision_ids = {json.loads(line)['event_id'] for line in decision_index.read_bytes().splitlines()}
assert decision_ids == {'a-latest', 'b-latest', 'ordinary-2'}, decision_ids
assert 'a-old' not in decision_ids and 'old-decision' not in decision_ids
# The stale sweep keeps the latest decision row despite its missing artifact.
prune_decisions('--stale', '--dry-run')
assert 'a-latest' in {json.loads(line)['event_id'] for line in decision_index.read_bytes().splitlines()}
prune_decisions('--stale')
decision_ids = {json.loads(line)['event_id'] for line in decision_index.read_bytes().splitlines()}
assert 'a-latest' in decision_ids, decision_ids
# Automatic append overflow uses the same decision pins.
store['append_rows'](str(decision_repo), str(decision_index), [{'event_id': 'decision-appended'}], keep=1, high=1)
decision_ids = {json.loads(line)['event_id'] for line in decision_index.read_bytes().splitlines()}
assert {'a-latest', 'b-latest', 'decision-appended'} <= decision_ids, decision_ids
# Soft decision pins cannot consume the byte budget needed for a normal append.
row_limit = store['MAX_ROW_BYTES']
budget_decisions = []
for number in range(16):
    row = {'event_id': 'budget-decision-%02d' % number, 'kind': 'panel-result',
           'ts': recent, 'padding': ''}
    encoded = json.dumps(row, separators=(',', ':')).encode()
    row['padding'] = 'x' * (row_limit - len(encoded) - 1)
    line = json.dumps(row, separators=(',', ':')).encode() + b'\n'
    assert len(line) == row_limit
    budget_decisions.append(line)
decision_index.write_bytes(b''.join(budget_decisions))
store['append_rows'](str(decision_repo), str(decision_index),
                     [{'event_id': 'budget-ordinary-append'}], keep=1, high=1)
budget_lines = decision_index.read_bytes().splitlines()
budget_ids = {json.loads(line)['event_id'] for line in budget_lines}
assert len(decision_index.read_bytes()) <= store['MAX_INDEX_BYTES']
assert 'budget-ordinary-append' in budget_ids
assert 'budget-decision-00' not in budget_ids, budget_ids
assert {'budget-decision-%02d' % number for number in range(1, 16)} <= budget_ids, budget_ids
# Pins may exceed the count floor, but never the durable byte bound.
try:
    store['_bounded'](before.splitlines(keepends=True), 1, 1, repo=str(repo))
except SystemExit as exc:
    assert exc.code == 2
else:
    raise AssertionError('completion pins bypassed the byte bound')
assert index.read_bytes() == before
PY
}


test_artifact_index_prune_files_deletes_only_orphans() {
  local project="$TMP/artifact-index-prune-files"
  local index="$project/.oms/artifacts/index.jsonl"
  local outside="$project/outside.md"
  local out

  mkdir -p "$project/.oms/artifacts/call" "$project/.oms/artifacts/delegate"
  printf 'old artifact\n' > "$project/.oms/artifacts/call/old.md"
  printf 'old patch\n' > "$project/.oms/artifacts/delegate/old.patch"
  printf 'kept artifact\n' > "$project/.oms/artifacts/call/kept.md"
  printf 'keep me\n' > "$project/.oms/artifacts/.gitignore"
  printf 'outside\n' > "$outside"
  ln -s "$outside" "$project/.oms/artifacts/call/outside-link.md"
  cat > "$index" <<'EOF'
{"ts":"2026-06-11T00:00:01Z","kind":"delegate","provider":"codex","exit":0,"artifact":".oms/artifacts/call/old.md","patch":".oms/artifacts/delegate/old.patch"}
{"ts":"2026-06-11T00:00:01Z","kind":"call","provider":"codex","exit":0,"artifact":".oms/artifacts/../outside.md"}
{"ts":"2026-06-11T00:00:02Z","kind":"call","provider":"codex","exit":0,"artifact":".oms/artifacts/call/kept.md"}
EOF

  out="$(OMS_ARTIFACT_ORPHAN_GRACE=0 \
    "$ROOT/scripts/artifact-index.sh" --repo "$project" prune 1 --files --dry-run)"
  contains "$out" 'would delete: .oms/artifacts/call/old.md' ||
    fail "dry-run should print would-delete artifact"
  contains "$out" 'would delete 2 orphan file(s)' ||
    fail "dry-run should print final would-delete count"
  assert_file_contains "$project/.oms/artifacts/call/old.md" "old artifact"
  assert_file_contains "$project/.oms/artifacts/call/kept.md" "kept artifact"
  [ "$(wc -l < "$index")" = "3" ] || fail "dry-run must not rewrite the index"

  out="$(OMS_ARTIFACT_ORPHAN_GRACE=0 \
    "$ROOT/scripts/artifact-index.sh" --repo "$project" prune 1 --files)"
  contains "$out" 'deleted: .oms/artifacts/call/old.md' ||
    fail "prune --files should print deleted artifact"
  contains "$out" 'deleted: .oms/artifacts/delegate/old.patch' ||
    fail "prune --files should print deleted patch"
  contains "$out" 'deleted 2 orphan file(s)' ||
    fail "prune --files should print final delete count"
  assert_not_exists "$project/.oms/artifacts/call/old.md"
  assert_not_exists "$project/.oms/artifacts/delegate/old.patch"
  assert_file_contains "$project/.oms/artifacts/call/kept.md" "kept artifact"
  assert_file_contains "$project/.oms/artifacts/.gitignore" "keep me"
  assert_file_contains "$outside" "outside"
  [ -L "$project/.oms/artifacts/call/outside-link.md" ] ||
    fail "prune --files must not remove symlinks"
}

test_delegate_records_task_outcome() {
  local project="$TMP/agent-run-task-outcome"
  local home_dir="$project/home"
  local artifact_dir="$project/artifacts"

  make_committed_repo "$project"
  mkdir -p "$home_dir"
  "$ROOT/scripts/agent-task.sh" --repo "$project" init \
    --goal "Record delegated artifact" \
    --next "Inspect artifact index" >/dev/null

  HOME="$home_dir" "$ROOT/scripts/peer-delegate.sh" --dry-run \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --to codex \
    --prompt "Implement helper" >/dev/null

  assert_file_contains "$project/.oms/task/current.md" "peer-delegate codex exit=0"
  assert_file_contains "$project/.oms/task/current.md" "artifact=artifacts/codex-implement-helper-"
  assert_file_contains "$project/.oms/task/current.md" "patch=artifacts/codex-implement-helper-"
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"kind": "delegate"'
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"patch": "artifacts/codex-implement-helper-'
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"task_goal": "Record delegated artifact"'

  HOME="$home_dir" "$ROOT/scripts/peer-delegate.sh" --dry-run \
    --repo "$project" --artifact-dir "$artifact_dir" --to codex \
    --read-only --prompt "Inspect helper" >/dev/null
  assert_file_contains "$project/.oms/task/current.md" 'artifact=artifacts/codex-inspect-helper-'
  if grep 'artifact=artifacts/codex-inspect-helper-' "$project/.oms/task/current.md" | grep -F 'patch=' > /dev/null; then
    fail "read-only task outcome must omit patch guidance"
  fi
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY_READ' || fail "read-only task outcome index missing"
import json, pathlib, sys
row = json.loads(pathlib.Path(sys.argv[1]).read_text().splitlines()[-1])
assert row['task_goal'] == 'Record delegated artifact', row
assert 'patch' not in row and 'patch_sha256' not in row, row
PY_READ
}

test_consult_memory_is_opt_in() {
  local project="$TMP/consult-memory-opt-in"
  local home_dir="$project/home"
  local bin_dir="$project/bin"

  make_committed_repo "$project"
  mkdir -p "$home_dir" "$bin_dir"
  printf '%s\n' '#!/usr/bin/env bash' 'exit 0' > "$bin_dir/codex"
  chmod +x "$bin_dir/codex"
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" append --agent codex --text "Prefer narrow verification commands." >/dev/null

  # Shared memory holds prior conclusions; a consulted peer reads them only on
  # request, so the second opinion is not anchored on the first.
  HOME="$home_dir" PATH="$bin_dir:$PATH" OMS_AGENT=claude "$ROOT/scripts/consult.sh" \
    --repo "$project" --to codex --dry-run --quiet \
    --prompt "Assess this plan" >/dev/null
  if grep -R -Fq 'Prefer narrow verification commands.' "$project/.oms/artifacts/consult"; then
    fail "consult should omit shared memory by default"
  fi

  HOME="$home_dir" PATH="$bin_dir:$PATH" OMS_AGENT=claude "$ROOT/scripts/consult.sh" \
    --repo "$project" --to codex --memory --dry-run --quiet \
    --prompt "Assess this plan" >/dev/null
  grep -R -Fq 'Prefer narrow verification commands.' "$project/.oms/artifacts/consult" ||
    fail "consult --memory should attach shared memory"
}

# smoke-weight: 8
test_pi_json_usage_and_fallback() {
  local dir="$TMP/pi-json" mode
  mkdir -p "$dir/bin"
  cat > "$dir/bin/pi" <<'SH'
#!/usr/bin/env bash
case " $* " in *" --mode json "*) ;; *) exit 9 ;; esac
cat "$PI_STREAM"
SH
  chmod +x "$dir/bin/pi"
  printf 'prompt\n' > "$dir/prompt"
  cat > "$dir/good" <<'EOF'
{"type":"message_end","message":{"role":"assistant","usage":{"input":2,"output":3,"cacheRead":4,"cacheWrite":5},"content":[{"type":"toolCall"}]}}
{"type":"message_end","message":{"role":"assistant","usage":{"input":7,"output":11,"cacheRead":13,"cacheWrite":17},"content":[{"type":"text","text":"Answer."}]}}
{"type":"agent_end","messages":[{"role":"assistant","content":[{"type":"text","text":"Answer."}]}]}
EOF
  printf '{broken\n' > "$dir/bad"
  for mode in good bad; do
    PI_STREAM="$dir/$mode" PATH="$dir/bin:$PATH" bash -c '
      . "$1/scripts/lib/peer-common.sh"
      oms_provider_normalize() { printf "%s" "$1"; }
      oms_provider_supports_access() { return 0; }
      oms_provider_supports_model_override() { return 0; }
      oms_provider_transport() { return 0; }
      oms_provider_cli_discovered() { return 0; }
      oms_provider_cli_available() { return 0; }
      ma_export_child_env() { :; }
      run_with_timeout() { "$@"; }
      ma_provider_attempt pi read "$2/prompt" "$2/output" "$2" provider-default "" test "$2" irrelevant
    ' _ "$ROOT" "$dir" || fail 'Pi JSON transport failed'
    if [ "$mode" = good ]; then
      python3 - "$dir/output" <<'PYCASE' || fail 'Pi usage mismatch'
import json, sys
lines = open(sys.argv[1]).read().splitlines()
assert lines[0] == 'Answer.', lines
row = json.loads(next(line[14:] for line in lines if line.startswith('usage detail: ')))
keys = (
        'input_' + 'tokens', 'output_' + 'tokens', 'cache_read_' + 'tokens',
        'cache_write_' + 'tokens', 'tool_calls', 'cache_in_input')
assert [row[k] for k in keys] == [9,14,17,22,1,False], row
PYCASE
    else
      cmp "$dir/bad" "$dir/output" || fail 'malformed Pi output was not preserved'
      ! grep -q '^usage detail:' "$dir/output" || fail 'malformed Pi output reported usage'
    fi
  done
  printf '%s\n' 'stop-reason: provider=pi reason=max_tokens subtype=length is_error=0' > "$dir/attempt"
  bash -c '. "$1/scripts/lib/peer-common.sh"; ma_record_attempt "$2/seat.md" pi model "" 0 "" "$2/attempt"' _ "$ROOT" "$dir"
  python3 - "$dir/seat.attempts.json" <<'PYATTEMPT' || fail 'Pi attempt stop reason missing'
import json, sys
row = json.load(open(sys.argv[1]))['attempts'][0]
assert row['stop_reason'] == 'provider=pi reason=max_tokens subtype=length is_error=0', row
PYATTEMPT
  python3 - "$ROOT" "$dir" <<'PYCASE' || fail 'Pi JSON edge cases failed'
import json, pathlib, subprocess, sys
root, directory = map(pathlib.Path, sys.argv[1:])
message = {'role': 'assistant', 'content': [{'type': 'text', 'text': 'zero'}],
           'usage': {'input': 0, 'output': 0, 'cacheRead': 0, 'cacheWrite': 0}}
def convert(name, events):
    path = directory / name
    raw = ''.join(json.dumps(event) + '\n' for event in events)
    path.write_text(raw)
    subprocess.run(['bash', '-c', '. "$1/scripts/lib/peer-common.sh"; ma_pi_jsonl_to_text "$2"',
                    '_', str(root), str(path)], check=True)
    return raw, path.read_text()
end = {'type': 'agent_end', 'messages': [message]}
raw, output = convert('zero', [{'type': 'message_end', 'message': message}, end])
assert output.startswith('zero\n') and '"input_tokens": 0' in output, output
for name, events in [('empty', [])]:
    raw, output = convert(name, events)
    assert output == raw, (name, output)
raw, output = convert('invalid-count', [{'type': 'message_end', 'message': dict(message, usage={'input': -1})}, end])
assert output == 'zero\n', output
for stop, expected in [('length', 'max_tokens'), ('max_output', 'max_tokens'), ('stop', 'stop'), ('', '')]:
    final = dict(message, stopReason=stop)
    earlier = dict(message, stopReason='length')
    raw, output = convert('stop-case', [{'type': 'message_end', 'message': earlier},
                                       {'type': 'agent_end', 'messages': [earlier, final]}])
    if expected:
        assert output.startswith('stop-reason: provider=pi reason=%s subtype=%s is_error=0\n' % (expected, stop)), output
    else:
        assert output.startswith('zero\n'), output
raw, output = convert('no-assistant', [{'type': 'agent_end', 'messages': []}])
assert output == raw, output
PYCASE
}

test_pi_retry_and_noise() {
  local dir="$TMP/pi-retry"
  mkdir -p "$dir/bin"
  cat > "$dir/bin/pi" <<'SH'
#!/usr/bin/env bash
[ "${PI_NOISE:-0}" != 1 ] || printf 'node warning\n' >&2
cat "$PI_STREAM"
SH
  chmod +x "$dir/bin/pi"
  printf 'prompt\n' > "$dir/prompt"
  python3 - "$ROOT" "$dir" <<'PYCASE' || fail 'Pi retry or mixed output conversion failed'
import json, os, pathlib, subprocess, sys
root, directory = map(pathlib.Path, sys.argv[1:])
def msg(text, stop):
    return {'role': 'assistant', 'content': [{'type': 'text', 'text': text}],
            'stopReason': stop, 'usage': {'input': 1, 'output': 2, 'cacheRead': 3, 'cacheWrite': 4}}
a, b = msg('old', 'error'), msg('new', 'stop')
events = [{'type': 'message_end', 'message': a}, {'type': 'agent_end', 'messages': [a], 'willRetry': True},
          {'type': 'auto_retry_start'}, {'type': 'message_end', 'message': b},
          {'type': 'agent_end', 'messages': [a, b]}, {'type': 'auto_retry_end'}]
for name, raw in [('retry', ''.join(json.dumps(e) + '\n' for e in events)),
                  ('noise', json.dumps(events[3]) + '\n' + json.dumps(events[4]) + '\n'),
                  ('message-only', json.dumps(events[3]) + '\n')]:
    path = directory / name
    path.write_text(raw)
    env = dict(os.environ, PI_STREAM=str(path), PI_NOISE='1' if name == 'noise' else '0')
    env['PATH'] = str(directory / 'bin') + os.pathsep + env['PATH']
    command = ''' . "$1/scripts/lib/peer-common.sh"
      oms_provider_normalize() { printf "%s" "$1"; }
      oms_provider_supports_access() { return 0; }
      oms_provider_supports_model_override() { return 0; }
      oms_provider_transport() { return 0; }
      oms_provider_cli_discovered() { return 0; }
      oms_provider_cli_available() { return 0; }
      ma_export_child_env() { :; }
      run_with_timeout() { "$@"; }
      ma_provider_attempt pi read "$2/prompt" "$2/output" "$2" provider-default "" test "$2" irrelevant
    '''
    subprocess.run(['bash', '-c', command, '_', str(root), str(directory)], env=env, check=True)
    output = (directory / 'output').read_text()
    assert output.startswith('stop-reason: provider=pi reason=stop subtype=stop is_error=0\nnew\n') and 'node warning' not in output, (name, output)
    usage = json.loads(next(line.split(': ', 1)[1] for line in output.splitlines() if line.startswith('usage detail: ')))
    field = 'input_' + 'to' + 'kens'
    assert usage[field] == (2 if name == 'retry' else 1), usage
PYCASE
}

