test_panel_write_workers_get_private_test_state() {
  local fixture="$TMP/panel-private-test-state"
  local root lifecycle repo out retained_root map_output retry_status
  local caller_fixture="${OMS_FIXTURE_ROOT-}"
  local original_lock="${OMS_LOCK_DIR-}" original_state="${XDG_STATE_HOME-}" original_cache="${XDG_CACHE_HOME-}"
  local fixture_lock="${OMS_LOCK_DIR:-$fixture/original-locks}"
  local fixture_state="${XDG_STATE_HOME:-$fixture/original-state}"
  local fixture_cache="${XDG_CACHE_HOME:-$fixture/original-cache}"
  local original_tmux="$fixture/original-tmux"
  classify_provider_error() {
    bash -c ". \"\$1/scripts/lib/peer-common.sh\"; oms_panel_provider_error_classify \"\$2\" \"\$3\" \"\$4\"" \
      _ "$ROOT" "$@"
  }
  mkdir -p "$fixture/bin" "$fixture/parent/worktree"
  cat > "$fixture/bin/codex" <<'EOF'
#!/usr/bin/env bash
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac
[ -z "${PANEL_RUNS:-}" ] || printf '%s\n' codex >> "$PANEL_RUNS"
printf '%s\n' "$@" > "$PANEL_ARGV"
printf '%s\n' "${OMS_FIXTURE_ROOT:-}" "${TMUX_TMPDIR:-}" "${OMS_LOCK_DIR:-}" \
  "${XDG_STATE_HOME:-}" "${XDG_CACHE_HOME:-}" "${TMUX:-}" "${TMUX_PANE:-}" > "$PANEL_ENV"
[ "${PANEL_FAIL:-0}" != 1 ] || {
  [ -z "${PANEL_ERROR:-}" ] || printf '%s\n' "$PANEL_ERROR" >&2
  [ -z "${PANEL_SPOOF:-}" ] || printf '%s\n' "$PANEL_SPOOF"
  exit 7
}
printf '{}\n'
EOF
  cat > "$fixture/bin/claude" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in --version|--help) exit 0 ;; esac
[ -z "${PANEL_RUNS:-}" ] || printf '%s\n' claude >> "$PANEL_RUNS"
if [ -n "${PANEL_WEEKLY_CASE:-}" ]; then
  printf '%s\n' '{"type":"rate_limit_event","rate_limit_info":{"status":"rejected","rateLimitType":"seven_day","overageDisabledReason":"org_level_disabled"}}'
  case "$PANEL_WEEKLY_CASE" in
    reconnect-success) printf '%s\n' '{"type":"error","message":"API Error: 503 service unavailable"}' ;;
    error-success) printf '%s\n' '{"type":"result","subtype":"success","is_error":true,"result":"API Error: 503 service unavailable"}' ;;
    terminal-errors) printf '%s\n' '{"type":"result","subtype":"success","is_error":true,"result":"API Error: 429 too many requests"}' ;;
  esac
  if [ "$PANEL_WEEKLY_CASE" != failure ] && [ "$PANEL_WEEKLY_CASE" != terminal-errors ]; then
    printf '%s\n' '{"type":"result","subtype":"success","is_error":false,"result":"ok"}'
  fi
  case "$PANEL_WEEKLY_CASE" in
    success-failure|terminal-errors) printf '%s\n' '{"type":"result","subtype":"success","is_error":true,"result":"API Error: 503 service unavailable"}' ;;
    success-error-notice) printf '%s\n' '{"type":"error","message":"API Error: 503 service unavailable"}' ;;
    success-quota-notice) printf '%s\n' '{"type":"rate_limit_event","rate_limit_info":{"status":"rejected","rateLimitType":"seven_day"}}' ;;
  esac
  exit 1
fi
printf '%s\n' "$@" > "$PANEL_ARGV"
printf '%s\n' "${OMS_FIXTURE_ROOT:-}" "${TMUX_TMPDIR:-}" "${OMS_LOCK_DIR:-}" \
  "${XDG_STATE_HOME:-}" "${XDG_CACHE_HOME:-}" "${TMUX:-}" "${TMUX_PANE:-}" > "$PANEL_ENV"
printf '%s\n' \
  '{"type":"system","subtype":"init"}' \
  '{"type":"assistant","message":{"id":"writer-1","content":[{"type":"text","text":"Claude write worker answer."},{"type":"tool_use","id":"writer-tool-1","name":"Bash","input":{"command":"printf done"}}]}}' \
  '{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"writer-tool-1","is_error":false,"content":"done"}]}}' \
  '{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"Claude write worker answer.","usage":{"input_tokens":12,"output_tokens":3,"cache_read_input_tokens":100,"cache_creation_input_tokens":50}}'
EOF
  chmod +x "$fixture/bin/codex" "$fixture/bin/claude"
  printf 'fixture prompt\n' > "$fixture/prompt"

  map_output="$(OMS_FIXTURE_ROOT="$fixture/mapped-suite" bash -c \
    '. "$1/tests/lib/smoke-env.sh"; oms_smoke_use_fixture_root; printf "%s\\n%s\\n%s\\n" "$OMS_LOCK_DIR" "$XDG_STATE_HOME" "$XDG_CACHE_HOME"' \
    _ "$ROOT")"
  [ "$map_output" = "$fixture/mapped-suite/locks
$fixture/mapped-suite/state
$fixture/mapped-suite/cache" ] || fail "suite fixture root mapping was wrong: $map_output"
  [ "${OMS_LOCK_DIR-}" = "$original_lock" ] || fail 'suite fixture mapping changed the caller lock path'
  [ "${XDG_STATE_HOME-}" = "$original_state" ] || fail 'suite fixture mapping changed the caller XDG state path'
  [ "${XDG_CACHE_HOME-}" = "$original_cache" ] || fail 'suite fixture mapping changed the caller XDG cache path'

  # Every smoke suite runs from a worker shell too, so each must source the
  # helper that clears the inherited harness state before its first fixture.
  local smoke_suite
  for smoke_suite in "$ROOT"/tests/*-smoke.sh; do
    grep -Fq 'lib/smoke-env.sh' "$smoke_suite" ||
      fail "$(basename "$smoke_suite") must source tests/lib/smoke-env.sh"
  done

  for provider in codex claude; do
    root="$fixture/$provider"
    mkdir -p "$root/parent/worktree"
    PANEL_ARGV="$root/argv" PANEL_ENV="$root/env" PATH="$fixture/bin:$PATH" \
      OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker MA_KIND=delegate REPO="$root/parent/worktree" \
      OMS_ROOM_ID=room-one OMS_ROOM_PARTICIPANT=worker-one OMS_ROOM_ADMITTED_PARTICIPANT=worker-one \
      OMS_ROOM_REPO="$root/room repo" OMS_ROOM_RELAY_QUEUE="$root/relay queue" OMS_ROOM_RELAY_ALLOWED=1 \
      OMS_LOCK_DIR="$fixture_lock" XDG_STATE_HOME="$fixture_state" \
      XDG_CACHE_HOME="$fixture_cache" TMUX_TMPDIR="$original_tmux" TMUX=/tmp/other,1,0 TMUX_PANE=%9 \
      bash -c '. "$1/scripts/lib/peer-common.sh"; MA_KIND=delegate; REPO="$4"; ma_provider_attempt "$2" write "$3/prompt" "$3/output" "$4" provider-default "" delegate "" ""' \
      _ "$ROOT" "$provider" "$fixture" "$root/parent/worktree" || fail "$provider panel write fixture failed"
    local writable_root
    writable_root="$(awk 'prev == "--add-dir" { print; exit } { prev = $0 }' "$root/argv")"
    [ -n "$writable_root" ] || fail "$provider write argv omitted the private writable root"
    [ -d "$writable_root" ] || fail "$provider successful provider return removed state before worktree cleanup"
    [ "$(sed -n '1p' "$root/env")" = "$writable_root" ] || fail "$provider fixture root env differed from --add-dir"
    [ "$(sed -n '2p' "$root/env")" = "$writable_root/tmux" ] || fail "$provider tmux root escaped fixture root"
    [ "$(sed -n '3p' "$root/env")" = "$fixture_lock" ] || fail "$provider worker OMS_LOCK_DIR changed"
    [ "$(sed -n '4p' "$root/env")" = "$fixture_state" ] || fail "$provider worker XDG_STATE_HOME changed"
    [ "$(sed -n '5p' "$root/env")" = "$fixture_cache" ] || fail "$provider worker XDG_CACHE_HOME changed"
    [ -z "$(sed -n '6p' "$root/env")" ] || fail "$provider worker kept the inherited TMUX socket"
    [ -z "$(sed -n '7p' "$root/env")" ] || fail "$provider worker kept the inherited TMUX_PANE"
    [ "$provider" != codex ] || grep -Fxq -- 'workspace-write' "$root/argv" || fail 'Codex workspace-write sandbox changed'
    if [ "$provider" = claude ]; then
      grep -Fxq -- 'stream-json' "$root/argv" || fail 'Claude write workers must stream activity'
      grep -Fxq -- '--verbose' "$root/argv" || fail 'Claude stream-json requires verbose output'
      grep -Fq 'stop-reason: provider=claude reason=end_turn subtype=success is_error=0' "$fixture/output" ||
        fail 'Claude writer stream lost its terminal reason'
      grep -Fq 'Claude write worker answer.' "$fixture/output" || fail 'Claude writer stream lost its answer'
      grep -Fq '"tool_calls": 1' "$fixture/output" || fail 'Claude writer stream lost its tool-call usage'
    fi
    if [ "$provider" = codex ]; then
      for room_value in 'OMS_ROOM_ID="room-one"' 'OMS_ROOM_PARTICIPANT="worker-one"' \
        "OMS_ROOM_REPO=\"$root/room repo\"" 'OMS_ROOM_ADMITTED_PARTICIPANT="worker-one"' \
        "OMS_ROOM_RELAY_QUEUE=\"$root/relay queue\"" 'OMS_ROOM_RELAY_ALLOWED="1"'; do
        grep -Fxq -- "shell_environment_policy.set.$room_value" "$root/argv" ||
          fail "Codex admitted room override missing: $room_value"
      done
    fi
  done

  # Generic/non-admitted panel calls must not turn room-shaped ambient values
  # into shell-environment exceptions in Codex.
  root="$fixture/codex-unadmitted"
  mkdir -p "$root/parent/worktree"
  PANEL_ARGV="$root/argv" PANEL_ENV="$root/env" PATH="$fixture/bin:$PATH" \
    OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker MA_KIND=delegate REPO="$root/parent/worktree" \
    OMS_ROOM_ID=room-one OMS_ROOM_PARTICIPANT=worker-one OMS_ROOM_ADMITTED_PARTICIPANT=other \
    OMS_ROOM_REPO="$root/room repo" OMS_ROOM_RELAY_QUEUE="$root/relay queue" OMS_ROOM_RELAY_ALLOWED=1 \
    OMS_LOCK_DIR="$fixture_lock" XDG_STATE_HOME="$fixture_state" XDG_CACHE_HOME="$fixture_cache" \
    TMUX_TMPDIR="$original_tmux" \
    bash -c '. "$1/scripts/lib/peer-common.sh"; MA_KIND=delegate; REPO="$4"; ma_provider_attempt codex write "$3/prompt" "$3/output" "$4" provider-default "" delegate "" ""' \
    _ "$ROOT" codex "$fixture" "$root/parent/worktree" || fail 'Codex non-admitted room fixture failed'
  if grep -q 'shell_environment_policy.set.OMS_ROOM_' "$root/argv"; then
    fail 'Codex non-admitted room overrides were passed'
  fi
  # Non-ASCII room paths stay literal UTF-8: TOML rejects JSON surrogate escapes.
  [ "$(bash -c '. "$1/scripts/lib/peer-common.sh"; ma_toml_basic_string "$2"' _ "$ROOT" '/tmp/room-é "q"')" = '"/tmp/room-é \"q\""' ] ||
    fail 'Codex room override must encode non-ASCII paths as literal UTF-8'

  # Provider fallback classification reads only a CLI's own error signatures:
  # error/turn.failed events, an API-error result envelope and fixed ERROR:
  # line prefixes. Free text from the agent's own work classifies as nothing.
  local pe="$fixture/provider-output" crlf_line
  classify_case() { # EXPECTED PROVIDER EXIT LABEL (output on stdin)
    cat > "$pe"
    classified="$(classify_provider_error "$2" "$3" "$pe")"
    [ "$classified" = "$1" ] || fail "provider error case '$4': expected '$1', got '$classified'"
  }
  printf '%s\n' '429: {"message":"Rate limit exceeded","code":429}' |
    classify_case capacity pi 1 'pi HTTP 429'
  printf '%s\n' '429: {"message":"Rate limit exceeded","code":429}' |
    classify_case '' pi 0 'pi successful status'
  printf '%s\n' '429:' | classify_case '' pi 1 'pi empty error'
  printf '%s\n' '429 malformed' | classify_case '' pi 1 'pi malformed error'
  printf '' | classify_case '' pi 1 'pi empty output'
