  out="$(HOME="$lifecycle/home" PATH="$fixture/bin:$PATH" \
    OMS_DELEGATE_WORKTREE_ROOT="$lifecycle/worktrees" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker \
    OMS_LOCK_DIR="$fixture_lock" XDG_STATE_HOME="$fixture_state" XDG_CACHE_HOME="$fixture_cache" \
    PANEL_ARGV="$lifecycle/argv" PANEL_ENV="$lifecycle/env" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$repo" --to codex --prompt 'fixture task' --no-verify --allow-no-change 2>&1)" ||
    fail "panel delegate success fixture failed: $out"
  retained_root="$(sed -n '1p' "$lifecycle/env")"
  [ -n "$retained_root" ] && [ ! -e "$retained_root" ] &&
    [ ! -e "$(dirname "$retained_root")" ] || fail 'successful delegate did not remove fixture root with its managed worktree'

  out="$(HOME="$lifecycle/home" PATH="$fixture/bin:$PATH" \
    OMS_DELEGATE_WORKTREE_ROOT="$lifecycle/worktrees" OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker \
    OMS_LOCK_DIR="$fixture_lock" XDG_STATE_HOME="$fixture_state" XDG_CACHE_HOME="$fixture_cache" \
    PANEL_ARGV="$lifecycle/argv" PANEL_ENV="$lifecycle/env" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$repo" --to codex --prompt 'fixture task' --no-verify --keep-worktree --allow-no-change 2>&1)" ||
    fail "panel delegate keep-worktree fixture failed: $out"
  retained_root="$(sed -n '1p' "$lifecycle/env")"
  [ -n "$retained_root" ] && [ -d "$retained_root" ] && [ -d "$(dirname "$retained_root")" ] ||
    fail 'kept delegate worktree did not retain its fixture root'
}

# smoke-weight: 6
test_claude_envelope_carries_stop_reason() {
  local project="$TMP/claude-envelope"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local artifact_dir="$project/artifacts"

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  # The stub answers in claude's print-mode JSON envelope and records its
  # argv, so the test pins both halves of the transport: the flags we send
  # and the parse of what comes back.
  cat > "$bin_dir/claude" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$@" > "$HOME/claude-argv"
# Act like plan mode writing its plan file, so the test sees it removed.
plans="$(printf '%s\n' "$@" | sed -n 's/^{"plansDirectory":"\(.*\)"}$/\1/p')"
if [ -n "$plans" ]; then
  mkdir -p "$plans" && printf 'seat plan\n' > "$plans/seat.md"
  printf '%s/%s\n' "$(pwd -P)" "$plans" > "$HOME/claude-plans"
fi
cat > /dev/null
printf '{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"Envelope answer body: pong.","usage":{"input_tokens":12,"output_tokens":3,"cache_read_input_tokens":100,"cache_creation_input_tokens":50},"total_cost_usd":0.0123,"modelUsage":{"claude-opus-5":{"inputTokens":12,"outputTokens":3,"costUSD":0.0123}}}\n'
EOF
  chmod +x "$bin_dir/claude"

  env -u OMS_RESUME_SESSION HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_ROLE=reviewer "$ROOT/scripts/agent-call.sh" \
    --repo "$project" --artifact-dir "$artifact_dir" --to claude \
    --prompt "Envelope probe" >/dev/null

  # The envelope is parsed back to text: the answer reads as prose, and the
  # facts plain text cannot carry — why the model stopped, which model was
  # actually served, what it cost — are kept as footer lines.
  assert_one_artifact_contains "$artifact_dir" 'claude-envelope-probe-*.md' \
    'stop-reason: provider=claude reason=end_turn subtype=success is_error=0'
  assert_one_artifact_contains "$artifact_dir" 'claude-envelope-probe-*.md' \
    'Envelope answer body: pong.'
  if grep -R -Fq '"type":"result"' "$artifact_dir"/claude-envelope-probe-*.md; then
    fail "the JSON envelope must be parsed away, not quoted as the answer"
  fi
  # A provider-default route is the one place the selected model says nothing;
  # the served model is what the envelope reports, and it rides the index row
  # so a later report can group by it without the artifact still existing.
  assert_one_artifact_contains "$artifact_dir" 'claude-envelope-probe-*.md' 'served model'
  assert_one_artifact_contains "$artifact_dir" 'claude-envelope-probe-*.md' 'claude-opus-5'
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "the index row must carry the served model, tokens, and cost"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
row = [r for r in rows if r.get("provider") == "claude"][-1]
assert row["served_model"] == "claude-opus-5", row
assert row["tokens"] == 15, row
assert abs(row["cost_usd"] - 0.0123) < 1e-9, row
assert row['provider_usage']['cache_read_tokens'] == 100, row
assert row['provider_usage']['cache_write_tokens'] == 50, row
assert row['provider_usage']['cache_in_input'] is False, row
assert row['provider_usage'].get('tool_calls') is None, row  # no stream, no tool count
assert not row['provider_usage'].get('session_cumulative'), row
PY
  # Resume changes token accounting without re-recording the restored session
  # cost; the served-model attribution remains available on the index row.
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_RESUME_SESSION=resumed-session \
    "$ROOT/scripts/agent-call.sh" --repo "$project" --artifact-dir "$artifact_dir" --to claude \
    --prompt "Envelope resume probe" >/dev/null
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "a resumed claude call must suppress cumulative cost and retain model/token usage"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
row = [r for r in rows if r.get("provider") == "claude"][-1]
assert row["served_model"] == "claude-opus-5", row
assert row.get("cost_usd") is None, row
assert row["tokens"] == 15, row
PY
  grep -Fxq -- '--output-format' "$home_dir/claude-argv" ||
    fail "claude must be asked for the JSON envelope: $(cat "$home_dir/claude-argv")"
  grep -Fxq -- 'stream-json' "$home_dir/claude-argv" || fail 'read seats need complete assistant messages'
  grep -Fxq -- '--verbose' "$home_dir/claude-argv" || fail 'stream-json requires verbose output'
  # A read seat judges text and gets no MCP tool surface.
  grep -Fxq -- '--strict-mcp-config' "$home_dir/claude-argv" ||
    fail "a read seat must not inherit the user-scope MCP servers: $(cat "$home_dir/claude-argv")"
  # Four tools is the whole belt a judging seat carries.
  grep -Fxq -- 'Read,Grep,Glob,Bash' "$home_dir/claude-argv" ||
    fail "a read seat must carry the bounded tool belt: $(cat "$home_dir/claude-argv")"
  cp "$home_dir/claude-argv" "$home_dir/claude-reviewer-argv"
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_ROLE=researcher OMS_PANEL_DISPATCH=1 OMS_PANEL_PURPOSE=research \
    "$ROOT/scripts/agent-call.sh" --repo "$project" --artifact-dir "$artifact_dir" --to claude \
    --model claude-haiku-5-5 --reasoning-effort low --prompt "Researcher web tools probe" >/dev/null
  cp "$home_dir/claude-argv" "$home_dir/claude-researcher-argv"
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_ROLE=researcher OMS_PANEL_STRATEGY=scholar OMS_PANEL_DISPATCH=1 OMS_PANEL_PURPOSE=research \
    "$ROOT/scripts/agent-call.sh" --repo "$project" --artifact-dir "$artifact_dir" --to claude \
    --model claude-opus-5-5 --reasoning-effort high --prompt "Scholar web tools probe" >/dev/null
  grep -Fxq -- 'Read,Grep,Glob,Bash,WebSearch,WebFetch' "$home_dir/claude-argv" || fail 'scholar needs web tools'
  for spec in 'researcher high claude-haiku-5-5 research' 'researcher low claude-opus-5-5 research' 'scholar high claude-opus-5-5 invalid' 'invalid low claude-haiku-5-5 research'; do
    set -- $spec
    if HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_ROLE=researcher OMS_PANEL_STRATEGY="$1" OMS_PANEL_DISPATCH=1 OMS_PANEL_PURPOSE="$4" \
      "$ROOT/scripts/agent-call.sh" --repo "$project" --artifact-dir "$artifact_dir" --to claude \
      --model "$3" --reasoning-effort "$2" --prompt "Invalid research probe" >/dev/null 2>&1; then
      fail "invalid researcher strategy or route accepted: $spec"
    fi
  done
  # A researcher role left in the environment is not a panel researcher dispatch.
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_PANEL_ROLE=researcher \
    "$ROOT/scripts/agent-call.sh" --repo "$project" --artifact-dir "$artifact_dir" --to claude \
    --prompt "Ambient researcher role probe" >/dev/null
  grep -Fxq -- 'Read,Grep,Glob,Bash' "$home_dir/claude-argv" ||
    fail 'an ambient researcher role outside a panel dispatch widened the tool belt'
  grep -Fxq -- 'Read,Grep,Glob,Bash,WebSearch,WebFetch' "$home_dir/claude-researcher-argv" ||
    fail 'a researcher read seat must carry bounded web lookup tools'
  grep -Fxq -- 'Read,Grep,Glob,Bash' "$home_dir/claude-reviewer-argv" ||
    fail 'a reviewer read seat must keep the bounded judge tool belt'
  # Settings carry the hooks, and a judging seat inheriting the parent's hook
  # table gets the parent's resume block injected into a context stripped to
  # four tools -- and writes the parent's .oms while it judges.
  grep -Fxq -- '--setting-sources' "$home_dir/claude-argv" ||
    fail "a read seat must not inherit the user-scope hooks: $(cat "$home_dir/claude-argv")"
  # Plan mode's plan file goes to a per-call project directory, not the
  # owner's ~/.claude/plans, and does not outlive the call.
  grep -Eqx '\{"plansDirectory":"\.oms/tmp/claude-plans-[0-9a-f]{8}"\}' "$home_dir/claude-argv" ||
    fail "a read seat must keep plan files out of the owner's home: $(cat "$home_dir/claude-argv")"
  [ -s "$home_dir/claude-plans" ] || fail 'the stub never saw a plans directory'
  [ ! -e "$(cat "$home_dir/claude-plans")" ] || fail "the seat's plan directory outlived the call"
  # Opted in, the same inline settings also deny the Read tool the secret paths.
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" OMS_WORKER_SECRET_GUARD=1 \
    "$ROOT/scripts/agent-call.sh" --repo "$project" --artifact-dir "$artifact_dir" --to claude \
    --prompt "Guarded read seat probe" >/dev/null
  grep -Eq '^\{"plansDirectory":"\.oms/tmp/claude-plans-[0-9a-f]{8}","permissions":\{"deny":\["Read\(\*\*/\.env\*\)",.*\]\}\}$' \
    "$home_dir/claude-argv" || fail "a guarded read seat must carry the Read deny rules: $(cat "$home_dir/claude-argv")"

  # A closing remark must not replace the substantive preceding answer.
  cat > "$project/stream" <<'EOF'
{"type":"system","subtype":"init"}
{"type":"user","message":{"content":"USER-CONTENT-NOT-ANSWER"}}
{"type":"assistant","parent_tool_use_id":"child-tool","message":{"content":[{"type":"tool_use","name":"Read","input":{}},{"type":"text","text":"CHILD-NOT-SEAT"}]}}
{"type":"assistant","message":{"id":"m1","content":[{"type":"thinking","thinking":"THINKING-NOT-ANSWER"},{"type":"tool_use","name":"Bash","input":{"command":"TOOL-NOT-ANSWER"}},{"type":"text","text":"Answer: substantive evidence."}]}}
{"type":"assistant","message":{"id":"m2","content":[{"type":"text","text":"The council answer above is my complete deliverable."}]}}
{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"The council answer above is my complete deliverable.","usage":{"input_tokens":12,"output_tokens":3}}
EOF
  cp "$project/stream" "$project/cut-stream"
  # A refusal keeps its safeguard category even without a result envelope,
  # stays a policy decline, and leaves a clean end_turn line untouched.
  printf '%s\n' '{"type":"system","subtype":"init"}' \
    '{"type":"assistant","message":{"id":"r1","stop_reason":"refusal","stop_details":{"type":"refusal","category":"reasoning_extraction"},"content":[{"type":"text","text":"Declined."}]}}' > "$project/refused"
  bash -c '. "$1/scripts/lib/peer-common.sh"; ma_claude_envelope_to_text "$2"' _ "$ROOT" "$project/refused"
  [ "$(head -n 1 "$project/refused")" = 'stop-reason: provider=claude reason=refusal subtype=missing_result is_error=0 category=reasoning_extraction' ] ||
    fail "a refused stream lost its reason or category: $(head -n 1 "$project/refused")"
  bash -c '. "$1/scripts/lib/model-routing.sh"; oms_model_is_policy_decline_output "$2"' _ "$ROOT" "$project/refused" ||
    fail 'a categorized refusal must stay a policy decline'
  # The stop-reason parser still reads a line that carries a category.
  printf '%s\n' 'stop-reason: provider=claude reason=refusal subtype=success is_error=1 category=bio' > "$project/refused-error"
  [ "$(python3 "$ROOT/scripts/lib/answer-quality.py" "$project/refused-error")" = blocked ] ||
    fail 'answer-quality must parse a categorized stop-reason line'
  # An open category that is not one token is marked, not renamed.
  printf '%s\n' '{"type":"assistant","message":{"id":"r2","stop_reason":"refusal","stop_details":{"category":"bio / cyber"},"content":[{"type":"text","text":"Declined."}]}}' > "$project/refused-odd"
  bash -c '. "$1/scripts/lib/peer-common.sh"; ma_claude_envelope_to_text "$2"' _ "$ROOT" "$project/refused-odd"
  [ "$(head -n 1 "$project/refused-odd")" = 'stop-reason: provider=claude reason=refusal subtype=missing_result is_error=0 category=unrecognized' ] ||
    fail "an odd category was rewritten: $(head -n 1 "$project/refused-odd")"
  # The room relay is stopped by its PID: a worker-planted .stop symlink is
  # never opened, and a process that ignores TERM is killed after the bounded wait.
  mkdir -p "$project/relay-stop"
  printf 'keep\n' > "$project/relay-stop/outside"
  ln -s "$project/relay-stop/outside" "$project/relay-stop/.stop"
  bash -c '. "$1/scripts/lib/peer-common.sh"; trap "" TERM; sleep 30 & pid=$!; ma_room_relay_stop "$pid" 2; ! kill -0 "$pid" 2>/dev/null' _ "$ROOT" ||
    fail 'ma_room_relay_stop must kill a relay that ignores TERM after the bounded wait'
  [ "$(cat "$project/relay-stop/outside")" = keep ] || fail 'relay shutdown wrote through a planted .stop symlink'
  # End to end: a reasoning_extraction decline is terminal after one call and
  # says what to change instead of retrying.
  mkdir -p "$project/refuse-bin"
  cat > "$project/refuse-bin/claude" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in --version) echo 'claude 1.0'; exit 0 ;; esac
printf 'call\n' >> "$HOME/refuse-calls"
cat > /dev/null
printf '%s\n' '{"type":"system","subtype":"init"}' \
  '{"type":"assistant","message":{"id":"r1","stop_reason":"refusal","stop_details":{"category":"reasoning_extraction"},"content":[{"type":"text","text":"Declined."}]}}' \
  '{"type":"result","subtype":"success","is_error":false,"stop_reason":"refusal","result":"Declined."}'
EOF
  chmod +x "$project/refuse-bin/claude"
  refuse_status=0
  HOME="$home_dir" PATH="$project/refuse-bin:/usr/bin:/bin" "$ROOT/scripts/agent-call.sh" \
    --repo "$project" --artifact-dir "$artifact_dir" --to claude \
    --prompt "Refusal probe" >/dev/null 2>"$project/refuse.err" || refuse_status=$?
  [ "$refuse_status" = 4 ] || fail "a Claude refusal must be a non-retryable decline, got $refuse_status"
  [ "$(wc -l < "$home_dir/refuse-calls" | tr -d ' ')" = 1 ] || fail 'a Claude refusal was retried'
  grep -Fq 'hint: the request asked the model to write out its internal reasoning' "$project/refuse.err" ||
    fail "a reasoning_extraction decline lacks its hint: $(cat "$project/refuse.err")"
  bash -c '. "$1/scripts/lib/peer-common.sh"; ma_claude_envelope_to_text "$2"' _ "$ROOT" "$project/stream"
  [ "$(head -n 1 "$project/stream")" = 'stop-reason: provider=claude reason=end_turn subtype=success is_error=0' ] ||
    fail "a clean end_turn line must stay byte-identical: $(head -n 1 "$project/stream")"
  assert_file_contains "$project/stream" 'Answer: substantive evidence.'
  [ "$(grep -c 'complete deliverable' "$project/stream")" = 1 ] || fail 'terminal result was duplicated'
  grep -Eq '"tool_calls": 1[,}]' "$project/stream" ||
    fail "the seat's own tool call, and not its child's, must be counted: $(tail -1 "$project/stream")"
  if grep -Eq 'NOT-ANSWER|CHILD-NOT-SEAT|"type"' "$project/stream"; then fail 'non-answer events leaked'; fi
  sed '/"type":"result"/d' "$project/cut-stream" > "$project/cut"
  bash -c '. "$1/scripts/lib/peer-common.sh"; ma_claude_envelope_to_text "$2"' _ "$ROOT" "$project/cut"
  assert_file_contains "$project/cut" 'Answer: substantive evidence.'
  [ "$(python3 "$ROOT/scripts/lib/answer-quality.py" "$project/cut")" = truncated ] || fail 'unterminated Claude stream passed'

  # A write worker's JSON result and equivalent stream transcript carry the
  # same answer, stop reason, token totals and non-tool usage fields. Streaming
  # improves tool_calls from unknown to the count in the transcript.
  cat > "$project/write-json" <<'EOF'
{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"Answer: same provider answer.","usage":{"input_tokens":12,"output_tokens":3,"cache_read_input_tokens":100,"cache_creation_input_tokens":50}}
EOF
  cat > "$project/write-stream" <<'EOF'
{"type":"system","subtype":"init"}
{"type":"assistant","message":{"id":"write-1","content":[{"type":"text","text":"Answer: same provider answer."},{"type":"tool_use","id":"tool-1","name":"Read","input":{"file_path":"fixture.txt"}}]}}
{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"tool-1","content":"fixture contents"}]}}
{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"Answer: same provider answer.","usage":{"input_tokens":12,"output_tokens":3,"cache_read_input_tokens":100,"cache_creation_input_tokens":50}}
EOF
  for transcript in write-json write-stream; do
    bash -c '. "$1/scripts/lib/peer-common.sh"; ma_claude_envelope_to_text "$2"' _ "$ROOT" "$project/$transcript"
  done
  python3 - "$project/write-json" "$project/write-stream" <<'PY' || fail 'Claude writer JSON/stream equivalence comparison failed'
import json, sys
json_lines, stream_lines = [open(path, encoding="utf-8").read().splitlines() for path in sys.argv[1:]]
for lines in (json_lines, stream_lines):
    assert lines[0] == "stop-reason: provider=claude reason=end_turn subtype=success is_error=0", lines
    assert lines[1] == "Answer: same provider answer.", lines
    assert lines[2:4] == ["tokens used", "15"], lines
json_usage, stream_usage = (json.loads(lines[4].split(": ", 1)[1]) for lines in (json_lines, stream_lines))
assert {key: value for key, value in json_usage.items() if key != "tool_calls"} == \
       {key: value for key, value in stream_usage.items() if key != "tool_calls"}, (json_usage, stream_usage)
assert json_usage["tool_calls"] is None and stream_usage["tool_calls"] == 1, (json_usage, stream_usage)
PY
  cat > "$project/resumed-stream" <<'EOF'
{"type":"assistant","message":{"id":"resume-1","usage":{"input_tokens":4,"output_tokens":3,"cache_read_input_tokens":12,"cache_creation_input_tokens":2},"content":[{"type":"text","text":"Resumed answer."}]}}
{"type":"assistant","message":{"id":"resume-1","usage":{"input_tokens":6,"output_tokens":5,"cache_read_input_tokens":20,"cache_creation_input_tokens":4},"content":[{"type":"text","text":"Resumed answer."}]}}
{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","result":"Resumed answer.","usage":{"input_tokens":900,"output_tokens":700,"cache_read_input_tokens":800,"cache_creation_input_tokens":400}}
EOF
  OMS_RESUME_SESSION=resumed-session bash -c '. "$1/scripts/lib/peer-common.sh"; ma_claude_envelope_to_text "$2"' _ "$ROOT" "$project/resumed-stream"
  python3 - "$project/resumed-stream" <<'PY' || fail 'Claude resumed stream usage must count this call only'
import json, sys
lines = open(sys.argv[1], encoding="utf-8").read().splitlines()
assert lines[lines.index("tokens used") + 1] == "11", lines
usage = json.loads(next(line[14:] for line in lines if line.startswith("usage detail: ")))
assert usage["input_tokens"] == 6 and usage["output_tokens"] == 5, usage
assert usage["cache_read_tokens"] == 20 and usage["cache_write_tokens"] == 4, usage
assert not usage.get("session_cumulative"), usage
PY
  cat > "$project/resumed-partial-stream" <<'EOF'
{"type":"assistant","message":{"id":"partial-1","usage":{"input_tokens":6,"cache_read_input_tokens":20},"content":[]}}
{"type":"result","subtype":"success","is_error":false,"stop_reason":"end_turn","usage":{"input_tokens":900,"output_tokens":700}}
EOF
  OMS_RESUME_SESSION=resumed-session bash -c '. "$1/scripts/lib/peer-common.sh"; ma_claude_envelope_to_text "$2"' _ "$ROOT" "$project/resumed-partial-stream"
  python3 - "$project/resumed-partial-stream" <<'PY' || fail 'Claude partial stream usage must retain missing fields'
import json, sys
lines = open(sys.argv[1], encoding="utf-8").read().splitlines()
usage = json.loads(next(line[14:] for line in lines if line.startswith("usage detail: ")))
assert usage["input_tokens"] == 6 and usage["output_tokens"] is None, usage
PY
}

test_codex_jsonl_carries_stop_reason() {
  local project="$TMP/codex-jsonl"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local artifact_dir="$project/artifacts"
  local artifact quality

  # The resumed event stream begins with the prior session total and closes
  # with the cumulative total after this call. A fresh call still reports its
  # final usage unchanged.
  python3 - "$ROOT" "$project" <<'PY' || fail "codex resumed usage must exclude earlier rounds"
import json, os, pathlib, subprocess, sys
root, project = map(pathlib.Path, sys.argv[1:])
common = '{"type":"thread.started","thread_id":"thread-resume"}\n'
project.mkdir(parents=True, exist_ok=True)
def run(name, stream, resumed=False, baseline=None):
    path = project / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(stream, encoding="utf-8")
    env = dict(os.environ)
    if resumed:
        env["OMS_RESUME_SESSION"] = "resume-session"
    else:
        env.pop("OMS_RESUME_SESSION", None)
    if baseline is not None:
        env["OMS_RESUME_USAGE_BASELINE"] = json.dumps(baseline)
    else:
        env.pop("OMS_RESUME_USAGE_BASELINE", None)
    subprocess.run(["bash", "-c", '. "$1/scripts/lib/peer-common.sh"; ma_codex_jsonl_to_text "$2"', "_", str(root), str(path)], env=env, check=True)
    lines = path.read_text(encoding="utf-8").splitlines()
    return int(lines[lines.index("tokens used") + 1]), json.loads(next(line[14:] for line in lines if line.startswith("usage detail: ")))
def completed(usage):
    return common + json.dumps({"type":"turn.completed","usage":usage}) + "\n"
fresh_total = {"input_tokens": 1300, "output_tokens": 50, "cached_input_tokens": 1100}
round2_total = {"input_tokens": 1500, "output_tokens": 70, "cached_input_tokens": 1200}
round3_total = {"input_tokens": 1750, "output_tokens": 100, "cached_input_tokens": 1400}
fresh_tokens, fresh_detail = run("chain-fresh.jsonl", completed(fresh_total))
assert fresh_tokens == 1350 and fresh_detail["session_totals"] == fresh_total, (fresh_tokens, fresh_detail)
round2_tokens, round2_detail = run("chain-round2.jsonl", completed(round2_total), True, fresh_detail["session_totals"])
assert round2_tokens == 220 and round2_detail["input_tokens"] == 200 and round2_detail["output_tokens"] == 20, (round2_tokens, round2_detail)
assert round2_detail["session_totals"] == round2_total and not round2_detail.get("session_cumulative"), round2_detail
round3_tokens, round3_detail = run("chain-round3.jsonl", completed(round3_total), True, round2_detail["session_totals"])
assert round3_tokens == 280 and round3_detail["input_tokens"] == 250 and round3_detail["output_tokens"] == 30, (round3_tokens, round3_detail)
assert round3_detail["session_totals"] == round3_total and not round3_detail.get("session_cumulative"), round3_detail
preserved = project / "event-msg-evidence.jsonl"
