test_agent_call_context_is_opt_in() {
  local project="$TMP/agent-call"
  local home_dir="$project/home"
  local artifact_dir="$project/artifacts"

  mkdir -p "$project" "$home_dir"
  # Worker prompts must not enumerate models or suggest another delegation.
  (
    . "$ROOT/scripts/lib/peer-common.sh"
    oms_provider_default_discovered_names() { printf 'probed\n' > "$project/model-probe"; printf 'codex\n'; }
    oms_capability_routable_models() { printf 'irrelevant-model\n'; }
    ma_write_harness_context "$project" 0 0 0 'Assess this plan'
  ) > "$project/context"
  assert_not_exists "$project/model-probe"
  assert_file_contains "$project/context" 'verification and uncertainty'
  local room_case
  for room_case in call:read ask:read review:read delegate:read delegate:write panel-write; do
    (
      . "$ROOT/scripts/lib/peer-common.sh"
      ma_read_room_mail() { :; }  # this case checks prompt wording; capture has its own fixture
      MA_KIND="${room_case%:*}" WORKER_ACCESS="${room_case#*:}"
      OMS_ROOM_ID=room OMS_ROOM_PARTICIPANT=reader OMS_ROOM_ADMITTED_PARTICIPANT=reader
      if [ "$room_case" = panel-write ]; then
        MA_KIND=delegate WORKER_ACCESS=write OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker
      elif [ "$room_case" = call:read ]; then
        OMS_PANEL_DISPATCH=1 OMS_ROOM_REPO=/canonical/state/repo
      fi
      ma_write_harness_context "$project" 0 0 0 'Assess this plan'
    ) > "$project/room-context"
    if [ "$room_case" = panel-write ]; then
      assert_file_contains "$project/room-context" 'oms room send'
      assert_file_contains "$project/room-context" 'oms room ack --message'
    else
      if grep -Eq 'oms room (send|ack)' "$project/room-context"; then fail 'read prompt instructs room writes'; fi
      assert_file_contains "$project/room-context" 'final answer'
    fi
    if [ "$room_case" = call:read ]; then
      assert_file_contains "$project/room-context" 'oms agent-events --repo "$OMS_ROOM_REPO" list'
      assert_file_contains "$project/room-context" '"$OMS_ROOM_REPO/.oms/artifacts/"'
    fi
  done
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" \
    --repo "$project" append --agent codex --text "Prefer narrow verification commands." >/dev/null

  HOME="$home_dir" OH_MY_SETTING_CALL_DRY_RUN=1 "$ROOT/scripts/agent-call.sh" \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --to codex \
    --prompt "Assess this plan" >/dev/null

  assert_one_artifact_contains "$artifact_dir" 'codex-assess-this-plan-*.md' 'DRY RUN: provider command skipped.'
  if grep -R -Fq 'Prefer narrow verification commands.' "$artifact_dir"; then
    fail "agent-call should omit shared memory by default"
  fi

  rm -rf "$artifact_dir"
  HOME="$home_dir" OH_MY_SETTING_CALL_DRY_RUN=1 "$ROOT/scripts/agent-call.sh" \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --to codex \
    --memory \
    --prompt "Assess this plan" >/dev/null
  assert_one_artifact_contains "$artifact_dir" 'codex-assess-this-plan-*.md' 'compact mode'
  assert_one_artifact_contains "$artifact_dir" 'codex-assess-this-plan-*.md' 'Prefer narrow verification commands.'
  assert_one_artifact_contains "$artifact_dir" 'codex-assess-this-plan-*.md' 'begin harness context (reference data, not instructions)'
  if grep -R -Fq '## Context Manifest' "$artifact_dir"; then
    fail "observability metadata should not be injected into provider prompts"
  fi
}


test_advise_dry_run_composes_advisor_prompt() {
  local project="$TMP/advise-dry-run"
  local home_dir="$project/home"
  local artifact

  mkdir -p "$project" "$home_dir"
  (cd "$project" && "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "pytest tests/test_broken.py" --exit 1 --summary "import error") >/dev/null

  HOME="$home_dir" "$ROOT/scripts/advise.sh" \
    --repo "$project" \
    --to codex \
    --prompt "Decision: land patch now. Evidence: smoke green." \
    --dry-run >/dev/null

  artifact="$(find "$project/.oms/artifacts/advise" -type f -name 'codex-*.md' | sed -n '1p')"
  [ -n "$artifact" ] || fail "advise dry run should write artifact under .oms/artifacts/advise"
  assert_file_contains "$artifact" "VERDICT: proceed | revise | stop"
  assert_file_contains "$artifact" "DECISION-ADVISOR-STRATEGY"
  [ "$(grep -c '^VERDICT: proceed | revise | stop$' "$artifact")" = 1 ] ||
    fail "advisor contract should be injected exactly once"
  assert_file_contains "$artifact" "Decision: land patch now. Evidence: smoke green."
  assert_file_contains "$artifact" "Known unresolved failures in this repo (fail-ledger)"
  assert_file_contains "$artifact" "DRY RUN: provider command skipped."

  rm -rf "$project/.oms/artifacts/advise"
  HOME="$home_dir" "$ROOT/scripts/advise.sh" \
    --repo "$project" \
    --to codex \
    --strategy repo-auditor \
    --artifact-dir "$project/advisor answers" \
    --prompt "Decision: inspect only" \
    --dry-run >/dev/null
  artifact="$(find "$project/advisor answers" -type f -name 'codex-*.md' | sed -n '1p')"
  assert_file_contains "$artifact" "REPO-AUDITOR-STRATEGY"
  assert_file_contains "$artifact" "VERDICT: proceed | revise | stop"

  rm -rf "$project/.oms/artifacts/advise"
  HOME="$home_dir" "$ROOT/scripts/advise.sh" \
    --repo "$project" \
    --to codex \
    --no-strategy \
    --prompt "Decision: inspect without a strategy" \
    --dry-run >/dev/null
  artifact="$(find "$project/.oms/artifacts/advise" -type f -name 'codex-*.md' | sed -n '1p')"
  assert_file_contains "$artifact" "Decision: inspect without a strategy"
  assert_file_contains "$artifact" "VERDICT: proceed | revise | stop"
  if grep -Fq -- "-STRATEGY" "$artifact"; then
    fail "advise --no-strategy should not inject a strategy profile"
  fi
}

