# smoke-weight: 6
test_shared_fast_mode_detection_gates_auto_verify() {
  local dir="$TMP/shared-fast-mode"
  local check_sh="$dir/check.sh"

  mkdir -p "$dir"
  printf 'case "${1:-fast}" in\n  fast) echo fast ;;\nesac\n' > "$check_sh"
  bash -c '. "$1"; oms_check_sh_has_fast_mode "$2"' _ "$ROOT/scripts/lib/agent-memory-common.sh" "$check_sh" ||
    fail "fast) arm not detected"

  printf 'case "$1" in\n  --quick) echo quick ;;\nesac\n' > "$check_sh"
  if bash -c '. "$1"; oms_check_sh_has_fast_mode "$2"' _ "$ROOT/scripts/lib/agent-memory-common.sh" "$check_sh"; then
    fail "check.sh without a fast mode must not be probed as having one"
  fi

  # The two contracts the default was written across: the template ships a
  # fast mode, this repo's own gate does not — so the auto-verify default must
  # probe before invoking `check.sh fast`, or the gate blocks on a usage error.
  bash -c '. "$1"; oms_check_sh_has_fast_mode "$2"' _ "$ROOT/scripts/lib/agent-memory-common.sh" "$ROOT/templates/check.sh" ||
    fail "template check.sh fast mode not detected"
  if bash -c '. "$1"; oms_check_sh_has_fast_mode "$2"' _ "$ROOT/scripts/lib/agent-memory-common.sh" "$ROOT/scripts/check.sh"; then
    fail "harness check.sh misdetected as having a fast mode"
  fi
  grep -q 'oms_default_verify_command' "$ROOT/scripts/peer-review.sh" ||
    fail "peer-review gate auto-verify must probe fast mode before defaulting"
  grep -q 'oms_default_verify_command' "$ROOT/scripts/peer-delegate.sh" ||
    fail "peer-delegate auto-verify must probe fast mode before defaulting"
  (
    . "$ROOT/scripts/lib/agent-memory-common.sh"
    printf 'case "$1" in\nfast) : ;;\nml-smoke) : ;;\nesac\n' > "$check_sh"
    [ "$(oms_default_verify_command "$check_sh")" = 'bash scripts/check.sh fast' ] || exit 1
    [ "$(oms_default_verify_command "$check_sh" 1)" = 'bash scripts/check.sh ml-smoke' ] || exit 1
    printf 'echo full-suite\n' > "$check_sh"
    rc=0
    oms_default_verify_command "$check_sh" >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ]
  ) || fail "shared verification selection widened the default"

  mkdir -p "$dir/project/scripts" "$dir/bin"
  cp "$ROOT/templates/check.sh" "$dir/project/scripts/check.sh"
  touch "$dir/project/pyproject.toml"
  printf '#!/usr/bin/env bash\nprintf "%%s\\n" "$*" >> "$OMS_TEST_UV_LOG"\n' > "$dir/bin/uv"
  chmod +x "$dir/bin/uv"
  PATH="$dir/bin:$PATH" OMS_TEST_UV_LOG="$dir/uv.log" bash "$dir/project/scripts/check.sh" fast >/dev/null
  if grep -q pytest "$dir/uv.log"; then
    fail "default fast must not collect the whole test suite"
  fi
  : > "$dir/uv.log"
  PATH="$dir/bin:$PATH" OMS_TEST_UV_LOG="$dir/uv.log" bash "$dir/project/scripts/check.sh" \
    fast 'tests/test_api.py::test_behavior[a b]' >/dev/null
  grep -Fxq 'run --no-sync python -m pytest -q tests/test_api.py::test_behavior[a b]' "$dir/uv.log" ||
    fail "fast must forward the selected test without full-suite collection"
  : > "$dir/uv.log"
  PATH="$dir/bin:$PATH" OMS_TEST_UV_LOG="$dir/uv.log" bash "$dir/project/scripts/check.sh" \
    fast --jobs 2 'tests/test_api.py::test_behavior[a b]' >/dev/null
  [ "$(grep -c pytest "$dir/uv.log")" = 1 ] &&
    grep -Fxq 'run --no-sync python -m pytest -q tests/test_api.py::test_behavior[a b]' "$dir/uv.log" ||
    fail "fast --jobs must run the selected test once with the selector intact"
  if PATH="$dir/bin:$PATH" OMS_TEST_UV_LOG="$dir/uv.log" bash "$dir/project/scripts/check.sh" \
    fast --jobs 0 tests >/dev/null 2>&1; then
    fail "fast --jobs must stay within 1-4"
  fi
  python3 - "$ROOT" <<'PY_PARALLEL'
"""Parent-frozen CPU fixture: measure concurrency and preserve argv/failures."""
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import signal
import sys
import time

ROOT = Path(sys.argv[1])
checker = 'bash'
with tempfile.TemporaryDirectory(prefix='oms-ci-parallel-probe-') as tmp:
    root = Path(tmp)
    (root / 'scripts').mkdir()
    (root / 'src').mkdir()
    (root / 'src/app.py').write_text('value = 1\n')
    (root / 'pyproject.toml').write_text('')
    (root / 'bin').mkdir()
    shutil.copyfile(ROOT / 'templates/check.sh', root / 'scripts/check.sh')
    stub = root / 'bin/uv'
    stub.write_text('''#!/usr/bin/env python3
import json, os, signal, subprocess, sys, time
args = sys.argv[1:]
if 'compileall' in args: stage='compile'
elif 'ruff' in args and 'check' in args: stage='lint'
elif 'pytest' in args: stage='test'
else: sys.exit(0)
def log(phase):
    fd=os.open(os.environ['PROBE_LOG'],os.O_WRONLY|os.O_CREAT|os.O_APPEND,0o600)
    os.write(fd,(json.dumps(dict(stage=stage,phase=phase,time=time.monotonic(),args=args))+'\\n').encode())
    os.close(fd)
log('start')
if os.environ.get('PROBE_FORK'):
    child = "import pathlib,signal,sys,time; p=pathlib.Path(sys.argv[1]); signal.signal(signal.SIGTERM,signal.SIG_IGN if sys.argv[2] else lambda *a:(p.with_suffix('.stopped').write_text('yes'),sys.exit(0))); p.write_text(str(__import__('os').getpid())); time.sleep(30)"
    if os.environ.get('PROBE_IGNORE') == 'both': signal.signal(signal.SIGTERM,signal.SIG_IGN)
    subprocess.run([sys.executable,'-c',child,os.environ['PROBE_LOG']+'.'+stage+'.ready',os.environ.get('PROBE_IGNORE','')])
time.sleep(.25)
log('end')
sys.exit(9 if os.environ.get('PROBE_FAIL')==stage else 0)
''')
    stub.chmod(0o755)
    (root/'logs').mkdir()
    env=dict(os.environ,TMPDIR=str(root/'logs'),PATH=str(root/'bin')+os.pathsep+os.environ['PATH'],PROBE_LOG=str(root/'events'))
    selector='tests/test_api.py::test_case[a b]'
    for jobs in (1,2):
        for failure in ('','lint'):
            (root/'events').write_text('')
            result=subprocess.run([checker,str(root/'scripts/check.sh'),'fast','--jobs',str(jobs),selector],env=dict(env,PROBE_FAIL=failure),capture_output=True,text=True,timeout=15)
            assert (result.returncode==0)==(not failure), result.stdout+result.stderr
            assert not list((root/'logs').iterdir()),'stage logs leaked'
            rows=[json.loads(line) for line in (root/'events').read_text().splitlines()]
            active=peak=0
            for row in sorted(rows,key=lambda r:r['time']):
                active+=1 if row['phase']=='start' else -1
                peak=max(peak,active)
            assert active==0 and peak==jobs,(active,peak,jobs,rows)
            tests=[r for r in rows if r['stage']=='test' and r['phase']=='start']
            assert len(tests)==1 and tests[0]['args']==['run','--no-sync','python','-m','pytest','-q',selector],tests
            assert {r['stage'] for r in rows if r['phase']=='end'}=={'compile','lint','test'},rows
            print('jobs=%s failure=%s peak=%s all stages reaped'%(jobs,failure or 'none',peak))
    (root/'events').write_text('')
    result=subprocess.run([checker,str(root/'scripts/check.sh'),'fast',selector],env=dict(env,PROBE_FAIL='compile'),capture_output=True,timeout=15)
    rows=[json.loads(line) for line in (root/'events').read_text().splitlines()]
    assert result.returncode != 0 and {row['stage'] for row in rows} == {'compile'},rows
    # Include children ignoring TERM and wrappers that ignore it too.
    if os.name == 'posix':
        for ignore in ('', 'descendant', 'both'):
            for entry in root.glob('events.*.*'): entry.unlink()
            proc=subprocess.Popen([checker,str(root/'scripts/check.sh'),'fast','--jobs','2',selector],env=dict(env,PROBE_FORK='1',PROBE_IGNORE=ignore),stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
            children=[]
            def live(pid):
                state=subprocess.run(['ps','-o','stat=','-p',str(pid)],capture_output=True,text=True).stdout.strip()
                return bool(state) and not state.startswith('Z')
            try:
                deadline=time.monotonic()+10
                while time.monotonic()<deadline:
                    ready=list(root.glob('events.*.ready'))
                    if len(ready)==2 and all(p.read_text().isdigit() for p in ready): break
                    time.sleep(.02)
                else: raise AssertionError('children did not start')
                children=[int(p.read_text()) for p in ready]
                proc.terminate()
                assert proc.wait(timeout=5) == 143
                assert not list((root/'logs').iterdir()),'cancelled stage logs leaked'
                deadline=time.monotonic()+2
                while any(live(pid) for pid in children) and time.monotonic()<deadline: time.sleep(.02)
                assert not any(live(pid) for pid in children),'descendant survived cancellation'
            finally:
                if proc.poll() is None:
                    proc.kill()
                    proc.wait()
                for pid in children:
                    if live(pid):
                        try: os.kill(pid,signal.SIGKILL)
                        except ProcessLookupError: pass
    for value in ('0','5','auto','-1'):
        result=subprocess.run([checker,str(root/'scripts/check.sh'),'fast','--jobs',value,selector],env=env,capture_output=True,timeout=15)
        assert result.returncode!=0,value
print('parallel parent probe passed')
PY_PARALLEL
  mkdir -p "$dir/project/src"
  printf '# configured smoke\n' > "$dir/project/scripts/ml_smoke.py"
  PATH="$dir/bin:$PATH" OMS_TEST_UV_LOG="$dir/uv.log" bash "$dir/project/scripts/check.sh" fast >/dev/null
  PATH="$dir/bin:$PATH" OMS_TEST_UV_LOG="$dir/uv.log" bash "$dir/project/scripts/check.sh" ml-smoke >/dev/null
  if grep -Ev '^run --no-sync ' "$dir/uv.log"; then
    fail 'routine checks must reuse the prepared environment without dependency sync'
  fi
  grep -Fq 'python -m compileall' "$dir/uv.log" || fail 'no-sync checks lost Python syntax coverage'
  grep -Fq 'python scripts/ml_smoke.py' "$dir/uv.log" || fail 'no-sync checks lost ML smoke coverage'
}


test_scrubber_blocks_credential_variants() {
  local f="$TMP/scrub-variants"
  local s

  (
  . "$ROOT/scripts/lib/agent-memory-common.sh"
  for s in "MY_API_K""EY=x" "api k""ey: x" "secret k""ey=x" "MY_PRIVATE_K""EY=x" "client_s""ecret = x" "CREDENTIAL""S=x" "aws_credential""s: x" \
    'toke'"n = str(\"literal-private-value\")" 'toke'"n = normalize('literal-private-value')" \
    'toke'"n = lookup(reference) # passw"'ord=literal-private-value'; do
    printf '%s\n' "$s" > "$f"
    agent_memory_file_has_sensitive_content "$f" ||
      fail "scrubber should block: $s"
  done

  printf '+          persist-credentia''ls: false\r\n' > "$f"
  if agent_memory_file_has_sensitive_content "$f" || agent_memory_file_has_secret_content "$f"; then
    fail "public checkout false toggle must not be classified as a secret"
  fi
  [ -z "$(agent_memory_sensitive_report "$f")" ] || fail "scan/report disagreement"
  (
    . "$ROOT/scripts/lib/peer-common.sh"
    if contains_sensitive_content "$f"; then fail "diff scanner must agree on public toggle"; fi
    printf '+api_t''oken=private\n' >> "$f"
    contains_sensitive_content "$f" || fail "diff scanner must retain adjacent secret"
  )
  for s in 'persist-credentia'"ls: unknown" 'persist-credentia'"ls: false # private" 'prefix persist-credentia'"ls: false"; do
    printf '%s\n' "$s" > "$f"
    agent_memory_file_has_secret_content "$f" || fail "only exact public toggle may pass"
  done
  printf 'persist-credentia''ls: false\napi_t''oken=private\n' > "$f"
  agent_memory_file_has_secret_content "$f" || fail "public toggle must not mask adjacent secrets"
  agent_memory_sensitive_report "$f" | grep -F 'line 2:' >/dev/null || fail "scrubber must preserve diagnostic line numbers"

  printf 'max_tokens: 512\nthe private keynote speech\nmonkey: banana\n' > "$f"
  if agent_memory_file_has_sensitive_content "$f"; then
    fail "benign vocabulary should pass the scrubber"
  fi
  )
}

test_scrubber_tiers_split_secret_from_machine() {
  local f="$TMP/scrub-tiers"
  (
  . "$ROOT/scripts/lib/agent-memory-common.sh"

  # Machine tier: home path matches the combined re but NOT the secret tier.
  printf 'edit /ho''me/researcher/proj/loader.py\n' > "$f"
  agent_memory_file_has_sensitive_content "$f" ||
    fail "home path must still match the combined sensitive tier"
  if agent_memory_file_has_secret_content "$f"; then
    fail "home path must not match the secret tier"
  fi

  local path
  for path in '/ho''me/researcher' '+/ho''me/researcher/config' \
    'path="/ho''me/researcher/config"' "'/User""s/researcher/config'" \
    'file:///ho''me/researcher/config' 'file:///User''s/researcher/config' \
    'cat >/ho''me/researcher/config' 'cat </User''s/researcher/config' \
    'cat >>"/ho''me/researcher/config"' 'cat 2>/User''s/researcher/config' \
    '["/ho''me/researcher/config"]' '/ho''me/user@domain/config' '/ho''me/사용자/config'; do
    printf '%s\n' "$path" > "$f"
    agent_memory_file_has_sensitive_content "$f" || fail "absolute home path escaped scanner"
    agent_memory_sensitive_report "$f" | grep -F 'machine-tier match' >/dev/null ||
      fail "absolute home path missing diagnostic"
  done
  for path in '"$TMP/home/researcher/config"' '"${tmp}/home/researcher/config"' \
    'relative/home/researcher/config' './home/researcher/config' \
    '/tmp/fixture/home/researcher/config' '/home/' '/home/$USER/config' \
    '"$TMP/Users/researcher/config"' '$TMP"/home/researcher/config"' \
    'file://$TMP/home/researcher/config' 'cat >"$TMP/home/researcher/config"' \
    'cat <"${tmp}/Users/researcher/config"' 'file:///tmp/fixture/home/researcher/config' \
    'relative"/home/researcher/config"'; do
    printf '%s\n' "$path" > "$f"
    if agent_memory_file_has_sensitive_content "$f"; then
      fail "fixture or incomplete home path must remain clean: $path"
    fi
    [ -z "$(agent_memory_sensitive_report "$f")" ] || fail "fixture scan/report disagreement"
  done
  for path in '$project/scratch/y.txt' 'relative/scratch/y.txt' \
    'repository context mentions scratch/y.txt but is not an absolute path'; do
    printf '%s\n' "$path" > "$f"
    if agent_memory_file_has_sensitive_content "$f"; then
      fail "relative or contextual scratch reference must remain clean: $path"
    fi
  done
  printf '/%s/project/y.txt\n' scratch > "$f"
  agent_memory_file_has_sensitive_content "$f" || fail "absolute scratch path must be blocked"
  # A mid-line cluster path is blocked by the regex, so the report must name it too.
  printf 'write to /%s/project/y.txt\n' scratch > "$f"
  agent_memory_file_has_sensitive_content "$f" || fail "mid-line scratch path must be blocked"
  agent_memory_sensitive_report "$f" | grep -F ':scratch-path' >/dev/null ||
    fail "mid-line scratch path blocked without a report label"
  printf 'OUT=/%s/p/y\n' lustre > "$f"
  agent_memory_file_has_sensitive_content "$f" || fail "assigned lustre path must be blocked"
  agent_memory_sensitive_report "$f" | grep -F ':lustre-path' >/dev/null ||
    fail "assigned lustre path blocked without a report label"

  # Secret tier: a credential assignment matches both.
  printf 'export MY_API_T''OKEN=abc\n' > "$f"
  agent_memory_file_has_secret_content "$f" ||
    fail "credential assignment must match the secret tier"

  # Env tier: literal values of secret-named variables are caught bare and
  # reported with a fixed label. Fixtures are built at runtime.
  local envval="Zq8vN3xK" dbpass="Hs7TgW2pLm9RcQ4"
  envval="${envval}t5Yb1JdFw6UeA0Xi"
  local envname="FIXTURE_API_""KEY"
  printf 'note: the value %s was pasted here\n' "$envval" > "$f"
  (
    export "$envname=$envval"
    agent_memory_file_has_secret_content "$f" || fail "bare env secret value must match the secret tier"
    agent_memory_file_has_sensitive_content "$f" || fail "bare env secret value must block the combined tier"
    local report
    report="$(agent_memory_sensitive_report "$f")"
    printf '%s\n' "$report" | grep -F 'secret-tier match in prompt at line 1:env-secret' >/dev/null ||
      fail "env secret report must name the fixed label and line: $report"
    case "$report" in *"$envname"*) fail "env secret variable name leaked into the report" ;; esac
    case "$report" in *"$envval"*) fail "env secret value leaked into the report" ;; esac
    printf -- '--- a/x\n+++ b/x\n@@ -0,0 +1,1 @@\n+pasted %s\n' "$envval" > "$f.diff"
    report="$(agent_memory_sensitive_diff_scan "$f.diff")" && rc=0 || rc=$?
    [ "$rc" = 0 ] || fail "diff scan must flag an added env secret value"
    case "$report" in *'x:1: secret-tier match: env-secret'*) ;; *) fail "diff scan env label unexpected: $report" ;; esac
    case "$report" in *"$envname"*) fail "diff scan env variable name leaked into the report" ;; esac
    case "$report" in *"$envval"*) fail "env secret value leaked into the diff report" ;; esac
    printf -- '--- a/x\n+++ b/x\n@@ -0,0 +0,0 @@\n+pasted %s\n' "$envval" > "$f.diff"
    report="$(agent_memory_sensitive_diff_scan "$f.diff")" && rc=0 || rc=$?
    [ "$rc" = 0 ] || fail "a match without a positive hunk line must remain a match"
    case "$report" in *'secret-tier: +1 added-line matches'*) ;; *) fail "empty shown set summary is unclear: $report" ;; esac
    case "$report" in *'more added-line matches'*) fail "empty shown set must not be summarized as more: $report" ;; esac
  )
  (
    export "$envname=short"
    printf 'the value short appears\n' > "$f"
    if agent_memory_file_has_secret_content "$f"; then fail "value under 8 characters must not match"; fi
    export "$envname=/opt/some/long/path/value"
    printf 'see /opt/some/long/path/value now\n' > "$f"
    if agent_memory_file_has_secret_content "$f"; then fail "path value must not match"; fi
    export "$envname=true" OTHER_VALUE="$envval"
    printf '%s\n' "$envval" > "$f"
    if agent_memory_file_has_secret_content "$f"; then fail "non-secret variable name must not match"; fi
  )
  (
    local phrase="correct horse battery staple" aname="AUTH""ORIZATION"
    export "FIXTURE_PASS""PHRASE=$phrase" "$aname=Basic dXNlcjpwYXNzd29yZA" \
      GIT_AUTHOR_EMAIL="someone.fixture@example.test"
    printf 'my phrase is %s ok\n' "$phrase" > "$f"
    agent_memory_file_has_secret_content "$f" || fail "passphrase containing spaces must match"
    printf 'header Basic dXNlcjpwYXNzd29yZA end\n' > "$f"
    local report
    report="$(agent_memory_sensitive_report "$f")"
    printf '%s\n' "$report" | grep -F ':env-secret' >/dev/null ||
      fail "bare authorization value must be reported with the fixed label"
    case "$report" in *"$aname"*) fail "authorization variable name leaked into the report" ;; esac
    printf 'contact someone.fixture@example.test\n' > "$f"
    if agent_memory_file_has_secret_content "$f"; then fail "author variables must not match"; fi
  )
  (
    local ml
    ml="$(printf 'first line of phrase\nsecond line of phrase')"
    export "FIXTURE_PASS""PHRASE=$ml"
    printf 'pasted:\n%s\ndone\n' "$ml" > "$f"
    agent_memory_file_has_secret_content "$f" || fail "multi-line passphrase pasted verbatim must match"
    printf 'one\ntwo\vthree\n%s\n' "$ml" > "$f"
    local report
    report="$(agent_memory_sensitive_report "$f")"
    printf '%s\n' "$report" | grep -F 'at line 3:env-secret' >/dev/null ||
      fail "vertical tab must not shift the LF-based line number"
    case "$report" in *'FIXTURE_PASS'*) fail "passphrase variable name leaked into the report" ;; esac
  )
  (
    # Qualification: plain words, metadata-suffixed names and drive paths are
    # ordinary configuration, not credentials.
    export "MON""KEY=ordinary" "AUTH_METHOD=correctpassphrase" \
      "API_KEY""_NAME=OPENAI_API_""KEY" \
      "FIXTURE_API_""KEY=C:\\Users\\someone\\file"
    printf 'an ordinary note\nuse correctpassphrase and OPENAI_API_%s\n' KEY > "$f"
    printf 'C:\\Users\\someone\\file\n' >> "$f"
    if agent_memory_file_has_secret_content "$f"; then
      fail "ordinary configuration values must not block: $(agent_memory_sensitive_report "$f")"
    fi
    # Git's command-scope config key name is not a credential; other key-named
    # variables holding the same value still are.
    export "GIT_CONFIG_KE""Y_0=core.hooksPath"
    printf 'set core.hooksPath here\n' > "$f"
    if agent_memory_file_has_secret_content "$f"; then
      fail "git config key name must not block: $(agent_memory_sensitive_report "$f")"
    fi
    export "FIXTURE_CONFIG_KE""Y_0=core.hooksPath"
    agent_memory_file_has_secret_content "$f" ||
      fail "non-git key-named variable with the same value must still block"
    unset "FIXTURE_CONFIG_KE""Y_0"
    export "GIT_CONFIG_KE""Y_1=url.https://fixtureuserinfo@example.invalid/.insteadOf"
    printf 'url.https://fixtureuserinfo@example.invalid/.insteadOf\n' > "$f"
    agent_memory_file_has_secret_content "$f" ||
      fail "a git config key carrying URL userinfo must still block"
  )
  (
    local shim="$TMP/scrub-python-shim" rc=0
    mkdir -p "$shim"
    printf '#!/bin/sh\nexit 2\n' > "$shim/python3"
    chmod +x "$shim/python3"
    printf 'ordinary text\n' > "$f"
    PATH="$shim:$PATH" agent_memory_file_secret_status "$f" || rc=$?
    [ "$rc" = 2 ] || fail "interpreter failure must be a scan error, got $rc"
    rc=0
    PATH="$shim:$PATH" agent_memory_file_sensitive_status "$f" || rc=$?
    [ "$rc" = 2 ] || fail "interpreter failure must be a sensitive scan error, got $rc"
    printf -- '--- a/x\n+++ b/x\n@@ -0,0 +1,1 @@\n+ordinary\n' > "$f.diff"
    rc=0
    PATH="$shim:$PATH" agent_memory_sensitive_diff_scan "$f.diff" >/dev/null || rc=$?
    [ "$rc" = 2 ] || fail "interpreter failure must fail the diff scan, got $rc"
  )
  (
    local sep=":"
    export FIXTURE_DATABASE_URL="postgres://dbuser${sep}${dbpass}@db.example.test/app"
    printf 'connect with %s please\n' "$dbpass" > "$f"
    agent_memory_file_has_secret_content "$f" || fail "bare URL userinfo password must match the secret tier"
    local report
    report="$(agent_memory_sensitive_report "$f")"
    printf '%s\n' "$report" | grep -F ':env-secret' >/dev/null ||
      fail "URL password report must use the fixed label"
    case "$report" in *'FIXTURE_DATABASE_URL'*) fail "URL variable name leaked into the report" ;; esac
  )

  (
    sed() { printf 'partial ordinary output\n'; return 2; }
    local rc=0
    agent_memory_file_sensitive_status "$f" || rc=$?
    [ "$rc" = 2 ] || fail "filter failure must not become no-match"
    rc=0
    agent_memory_file_secret_status "$f" || rc=$?
    [ "$rc" = 2 ] || fail "secret filter failure must retain its error"
  )

  # Normalizer folds home prefixes to ~ and leaves other paths alone.
  local got
  got="$(printf 'run /ho''me/researcher/proj/train.py --data /data/set\n' |
    agent_memory_normalize_machine_paths)"
  [ "$got" = 'run ~/proj/train.py --data /data/set' ] ||
    fail "normalizer output unexpected: $got"
  )
}


test_scrubber_blocks_outbound_secret_shapes() {
  local f="$TMP/scrub-outbound-shapes"
  local s

  printf '%s%s%s\n' 'https://user' ':pass-value' '@example.com/repo.git' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
    fail "scrubber should block URL userinfo"

  printf '%s%s.%s.%s\n' 'ey' 'JhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9' 'abcdefghijklmnopqrst' 'uvwxyzABCDEFGHIJKLMN' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
    fail "scrubber should block JWT-shaped value"

  for s in \
    "gh""o_abcdefghijklmnopqrstuvwxyz0123456789" \
    "gh""u_abcdefghijklmnopqrstuvwxyz0123456789" \
    "gh""s_abcdefghijklmnopqrstuvwxyz0123456789" \
    "gh""r_abcdefghijklmnopqrstuvwxyz0123456789" \
    "github""_pat_abcdefghijklmnopqrstuvwxyz_0123456789_abcdefghijklmnopqrstuvwxyz"; do
    printf '%s\n' "$s" > "$f"
    bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
      fail "scrubber should block GitHub token family"
  done

  printf '%s%s%s\n' 'np' 'm_' 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJ' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
    fail "scrubber should block npm token"

  # A matched line that merely contains ":env:" must not reach the refusal text.
  local out
  printf '%s%s\n' 'api_to' 'ken=zx81leakedcredential # ref:env:demo' > "$f"
  printf -- '--- a/x\n+++ b/x\n@@ -0,0 +1,1 @@\n+%s\n' "$(cat "$f")" > "$f.diff"
  out="$(bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_sensitive_diff_scan '$f.diff'; agent_memory_sensitive_report '$f'")"
  case "$out" in *leakedcredential*|*ref:env:demo*) fail "refusal output echoed matched content: $out" ;; esac
  case "$out" in *token-assignment*) ;; *) fail "refusal output lost its pattern label: $out" ;; esac

  # Ordinary configuration must not block outbound text through the env tier.
  printf 'an ordinary note\nOPENAI_API_%s is documented\nuse correctpassphrase\nC:\\Users\\x\\y\n' KEY > "$f"
  if env "MON""KEY=ordinary" AUTH_METHOD=correctpassphrase "API_KEY""_NAME=OPENAI_API_KEY" \
    "FIXTURE_API_""KEY=C:\\Users\\x\\y" \
    bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'"; then
    fail "ordinary configuration values must not block outbound text"
  fi

  printf '%s%s%s\n' 'AI' 'za' 'abcdefghijklmnopqrstuvwxyzABCDE1234' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
    fail "scrubber should block GCP API key"

  printf '%s%s%s%s\n' 'n' 'tn_' '12345678901' 'abcdefghijklmnopqrstuvwxyzABCDEFGHI' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
    fail "scrubber should block Notion integration token"

  printf '%s%s%s\n' 'https://hoo' 'ks.slack.com/services/' 'T000/B000/abcdefghijklmnopqrstuvwxyz' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
    fail "scrubber should block Slack webhook"

  printf '%s%s%s\n' 'https://discord' 'app.com/api/webhooks/' '123456789012345678/abcdefghijklmnopqrstuvwxyz' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
    fail "scrubber should block Discord webhook"

  printf '%s %s %s %s %s %s\n' 'machine' 'example.com' 'login' 'deploy' 'password' 'not-for-sharing' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
    fail "scrubber should block netrc grammar"

  # Bare provider tokens with no key= prefix (HuggingFace / GitLab / Stripe).
  for s in \
    "h""f_abcdefghijklmnopqrstuvwxyz0123456789" \
    "glpa""t-abcdefghij1234567890ABCDEF" \
    "sk_li""ve_abcdefghij0123456789ABCD" \
    "sk_te""st_abcdefghij0123456789ABCD" \
    "rk_li""ve_abcdefghij0123456789ABCD"; do
    printf '%s\n' "$s" > "$f"
    bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'" ||
      fail "scrubber should block a bare provider credential (${s%%_*})"
  done

  local diff="$TMP/scrub-diff-report"
  cat > "$diff" <<EOF
diff --git a/config/settings.sh b/config/settings.sh
index 0000000..1111111 100644
--- a/config/settings.sh
+++ b/config/settings.sh
@@ -2,0 +3 @@
EOF
  printf '+API_TOK%s=assembled-at-runtime\n' 'EN' >> "$diff"
  local report
  report="$(bash -c '. "$1/scripts/lib/peer-common.sh"; contains_sensitive_content "$2"' _ "$ROOT" "$diff")" ||
    fail "diff scanner should block a token-shaped addition"
  printf '%s\n' "$report" | grep -F 'config/settings.sh:3: secret-tier match: token-assignment' > /dev/null ||
    fail "diff diagnostic must identify target file line, tier and pattern: $report"
  ! grep -Fq 'assembled-at-runtime' <<< "$report" ||
    fail "diff diagnostic must not echo matched content"

  local scan_bin="$TMP/scan-fail-bin" scan_tmp="$TMP/scan-fail-tmp" real_sed rc=0
  mkdir -p "$scan_bin" "$scan_tmp"
  real_sed="$(command -v sed)"
  cat > "$scan_bin/sed" <<'EOF'
#!/usr/bin/env bash
case " $* " in *"$OMS_TEST_SCAN_FAIL_PATH"*) exit 2 ;; esac
exec "$OMS_TEST_REAL_SED" "$@"
EOF
  chmod +x "$scan_bin/sed"
  PATH="$scan_bin:$PATH" OMS_TEST_REAL_SED="$real_sed" TMPDIR="$scan_tmp" OMS_LIB_TMPDIR="$scan_tmp" OMS_TEST_SCAN_FAIL_PATH="$scan_tmp" \
    bash -c '. "$1/scripts/lib/peer-common.sh"; contains_sensitive_content "$2"' \
      _ "$ROOT" "$diff" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "diff filter errors must remain distinguishable from clean scans, got $rc"

  # A "+++"-prefixed content line inside a hunk is content: it advances the
  # new-file line counter, so the flagged line after it keeps an exact number.
  local plus_diff="$TMP/scrub-diff-plusplus"
  cat > "$plus_diff" <<EOF
diff --git a/lib/a.sh b/lib/a.sh
--- a/lib/a.sh
+++ b/lib/a.sh
@@ -4,0 +5,3 @@
+first
+++second
EOF
  printf '+API_TOK%s=assembled-at-runtime\n' 'EN' >> "$plus_diff"
  report="$(bash -c '. "$1/scripts/lib/peer-common.sh"; contains_sensitive_content "$2"' _ "$ROOT" "$plus_diff")" ||
    fail "diff scanner should block a token after a ++-prefixed content line"
  printf '%s\n' "$report" | grep -Fx 'lib/a.sh:7: secret-tier match: token-assignment' > /dev/null ||
    fail "line number after a ++-prefixed content line must be exact: $report"
  # A "+++ " content line carrying the token is scanned, not skipped as a header.
  printf -- '--- a/x\n+++ b/x\n@@ -0,0 +1,2 @@\n+ok\n+++ API_TOK%s=assembled-at-runtime\n' 'EN' > "$plus_diff"
  report="$(bash -c '. "$1/scripts/lib/peer-common.sh"; contains_sensitive_content "$2"' _ "$ROOT" "$plus_diff")" ||
    fail "a +++ content line inside a hunk must still be scanned"
  printf '%s\n' "$report" | grep -Fx 'x:2: secret-tier match: token-assignment' > /dev/null ||
    fail "+++ content line location wrong: $report"

  # The two hidden-directory machine patterns match without a leading slash.
  printf -- '--- a/h\n+++ b/h\n@@ -0,0 +1 @@\n+dir=.ss%s/id\n' 'h' > "$plus_diff"
  report="$(bash -c '. "$1/scripts/lib/peer-common.sh"; contains_sensitive_content "$2"' _ "$ROOT" "$plus_diff")" ||
    fail "diff scanner should block a hidden credential directory"
  printf '%s\n' "$report" | grep -Fx 'h:1: machine-tier match: ssh-dir' > /dev/null ||
    fail "machine-tier label must name the slashless hidden directory: $report"

  # A clean diff of thousands of added lines is one pass, not a fork per line.
  local big_diff="$TMP/scrub-diff-big" i=0
  { printf -- '--- a/big.txt\n+++ b/big.txt\n@@ -0,0 +1,6000 @@\n'
    while [ "$i" -lt 6000 ]; do printf '+line %s of ordinary prose\n' "$i"; i=$((i + 1)); done
  } > "$big_diff"
  rc=0
  if command -v timeout >/dev/null 2>&1; then
    timeout 20 bash -c '. "$1/scripts/lib/peer-common.sh"; contains_sensitive_content "$2"' _ "$ROOT" "$big_diff" >/dev/null 2>&1 || rc=$?
  else
    bash -c '. "$1/scripts/lib/peer-common.sh"; contains_sensitive_content "$2"' _ "$ROOT" "$big_diff" >/dev/null 2>&1 || rc=$?
  fi
  [ "$rc" = 1 ] || fail "a clean multi-thousand-line diff must scan clean within the bound, got $rc"

  # peer-ask reports a scan failure as such, not as a failed git diff.
  local ask_project="$TMP/ask-scan-failure"
  make_committed_repo "$ask_project"
  printf 'changed\n' >> "$ask_project/file.txt"
  rc=0
  PATH="$scan_bin:$PATH" OMS_TEST_REAL_SED="$real_sed" TMPDIR="$scan_tmp" OMS_LIB_TMPDIR="$scan_tmp" OMS_TEST_SCAN_FAIL_PATH="$scan_tmp" \
    OH_MY_SETTING_ASK_DRY_RUN=1 "$ROOT/scripts/peer-ask.sh" --repo "$ask_project" \
      --artifact-dir "$ask_project/artifacts" --providers claude --diff --prompt 'review' \
      >"$ask_project/out" 2>"$ask_project/error" || rc=$?
  [ "$rc" = 3 ] || fail "peer-ask must block on a diff scan failure, got $rc"
  assert_file_contains "$ask_project/error" "sensitive-content scan failed"
  if grep -Fq "git diff failed" "$ask_project/error"; then
    fail "peer-ask must not report a scan failure as a git diff failure"
  fi
}

test_scrubber_allows_common_clean_text() {
  local f="$TMP/scrub-clean-text"

  cat > "$f" <<'EOF'
https://example.com/org/repo.git
git@github.com:org/repo.git
the word password appears here without a value assignment
max_tokens: 512
def resolve(token, cwd=""):
for token in tokens:
    token = os.path.relpath(token, wt).replace(os.sep, "/")
    token = posixpath.join(cwd, token)
EOF
  printf '%s%s.%s.%s\n' 'ey' 'J' 'short' 'short' >> "$f"
  if bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'"; then
    fail "ordinary clean text should pass the scrubber"
  fi

  printf '%s%s%s\n' 'https://user' ':********' '@example.com/repo.git' > "$f"
  if bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$f'"; then
    fail "placeholder-only URL password should pass the scrubber"
  fi

  # A reference-only expression exemption must keep known key material visible.
  printf 'toke''n = normalize(gh''p_abcdefghijklmnopqrstuvwxyz0123456789)\n' > "$f"
  bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_secret_content '$f'" ||
    fail "code reference filtering hid a known key format in an argument"
}

