test_uninstall_purge_guard_refuses_home_and_root() {
  local home_dir="$TMP/uninstall-guard-home"
  local home_script="$home_dir/scripts/uninstall.sh"
  local root_script="/tmp/oms-uninstall-root-guard.$$"

  mkdir -p "$home_dir/scripts"
  cp "$ROOT/scripts/uninstall.sh" "$home_script"
  chmod +x "$home_script"

  if HOME="$home_dir" "$home_script" --purge --yes >"$home_dir/home-out" 2>"$home_dir/home-err"; then
    fail "uninstall purge should refuse ROOT=HOME"
  fi
  assert_file_contains "$home_dir/home-err" "error: refusing to purge $home_dir"
  [ -d "$home_dir" ] || fail "purge guard removed HOME"
  # A symlinked HOME resolves to the same physical checkout.
  ln -s "$home_dir" "$TMP/uninstall-guard-home-link"
  if HOME="$TMP/uninstall-guard-home-link" "$home_script" --purge --yes >"$home_dir/link-out" 2>"$home_dir/link-err"; then
    fail "uninstall purge should refuse ROOT=HOME through a symlinked HOME"
  fi
  [ -d "$home_dir/scripts" ] || fail "purge guard removed a symlinked HOME"

  cp "$ROOT/scripts/uninstall.sh" "$root_script"
  chmod +x "$root_script"
  if HOME="$home_dir" "$root_script" --purge --yes >"$home_dir/root-out" 2>"$home_dir/root-err"; then
    rm -f "$root_script"
    fail "uninstall purge should refuse ROOT=/"
  fi
  rm -f "$root_script"
  assert_file_contains "$home_dir/root-err" "error: refusing to purge /"
}


test_link_and_unlink_with_home_override() {
  local home_dir="$TMP/link-home"
  local root name
  mkdir -p "$home_dir/.codex/skills" "$home_dir/.claude/skills" "$home_dir/.agents/skills" \
    "$home_dir/.pi/agent/skills" "$home_dir/.gemini" "$home_dir/old-skills" \
    "$home_dir/elsewhere" "$home_dir/user-trace"
  printf 'a skill the user wrote\n' > "$home_dir/user-trace/SKILL.md"
  ln -s "$home_dir/old-skills/peer-ask" \
    "$home_dir/.codex/skills/peer-ask"
  ln -s "$home_dir/old-skills/peer-review" \
    "$home_dir/.codex/skills/peer-review.backup.legacy"
  ln -s "$ROOT/custom-skills" "$home_dir/.codex/skills/oh-my-setting"
  ln -s "$ROOT/custom-skills/removed-skill" "$home_dir/.codex/skills/removed-skill"
  ln -s "$home_dir/elsewhere/gone" "$home_dir/.codex/skills/foreign-dangling"
  ln -s "$ROOT/custom-skills/peer-ask" \
    "$home_dir/.agents/skills/peer-ask"
  ln -s "$ROOT/custom-skills/peer-review" \
    "$home_dir/.pi/agent/skills/peer-review"
  ln -s "$ROOT/AGENTS.md" "$home_dir/.gemini/GEMINI.md"
  # agy 1.4 reads ~/.gemini/config/skills only: an earlier install's owned
  # links in the old root migrate away while user entries there stay.
  mkdir -p "$home_dir/.gemini/antigravity/skills/user-skill" \
    "$home_dir/.gemini/antigravity/skills/oms-trace.backup.20260101000000"
  echo "user trace" > \
    "$home_dir/.gemini/antigravity/skills/oms-trace.backup.20260101000000/USER.txt"
  ln -s "$ROOT/custom-skills/oms-trace" "$home_dir/.gemini/antigravity/skills/oms-trace"
  ln -s "$home_dir/old-skills/foreign" "$home_dir/.gemini/antigravity/skills/foreign"

  HOME="$home_dir" "$ROOT/scripts/link.sh" >/dev/null
  HOME="$home_dir" "$ROOT/scripts/link.sh" >/dev/null

  [ ! -L "$home_dir/.codex/skills/removed-skill" ] ||
    fail "dangling link owned by this checkout should be removed"
  [ -L "$home_dir/.codex/skills/foreign-dangling" ] ||
    fail "foreign dangling link should be preserved"
  [ ! -L "$home_dir/.gemini/antigravity/skills/oms-trace" ] ||
    fail "owned link in the retired antigravity skills root not migrated"
  # The skill an earlier install displaced there comes back, or uninstall
  # would later skip the missing target and never restore it.
  assert_file_contains "$home_dir/.gemini/antigravity/skills/oms-trace/USER.txt" "user trace"
  [ ! -e "$home_dir/.gemini/antigravity/skills/oms-trace.backup.20260101000000" ] ||
    fail "migration left the displaced skill backup behind"
  [ -d "$home_dir/.gemini/antigravity/skills/user-skill" ] &&
    [ -L "$home_dir/.gemini/antigravity/skills/foreign" ] ||
    fail "user entries in the retired antigravity skills root must stay"
  # A legacy root aliased to the active one is the active root; reruns must
  # not retire the links they just installed through it.
  local alias_home="$TMP/link-home-alias"
  mkdir -p "$alias_home/.gemini/antigravity/skills" "$alias_home/.gemini/config"
  ln -s "$alias_home/.gemini/antigravity/skills" "$alias_home/.gemini/config/skills"
  HOME="$alias_home" "$ROOT/scripts/link.sh" >/dev/null
  HOME="$alias_home" "$ROOT/scripts/link.sh" >/dev/null
  assert_symlink_to "$alias_home/.gemini/config/skills/oms-agent-harness" "$ROOT/custom-skills/oms-agent-harness"

  assert_symlink_to "$home_dir/.codex/AGENTS.md" "$ROOT/rules/global-AGENTS.md"
  assert_symlink_to "$home_dir/.claude/CLAUDE.md" "$ROOT/rules/global-AGENTS.md"
  assert_symlink_to "$home_dir/.gemini/AGENTS.md" "$ROOT/rules/global-AGENTS.md"
  # All providers receive the same current waiting policy, not a stale copy.
  cmp -s "$home_dir/.codex/AGENTS.md" "$ROOT/rules/global-AGENTS.md" || fail "Codex global policy drift"
  cmp -s "$home_dir/.claude/CLAUDE.md" "$ROOT/rules/global-AGENTS.md" || fail "Claude global policy drift"
  cmp -s "$home_dir/.gemini/AGENTS.md" "$ROOT/rules/global-AGENTS.md" || fail "Antigravity global policy drift"
  for root in "$home_dir/.codex/skills" "$home_dir/.claude/skills" \
    "$home_dir/.gemini/config/skills"; do
    for name in oms-agent-harness oms-ops oms-spec-interview oms-trace \
      oms-trust-boundary oms-careful; do
      assert_symlink_to "$root/$name" "$ROOT/custom-skills/$name"
    done
    for name in agent-harness oh-my-setting-ops spec-interview trace \
      trust-boundary careful slurm gpu-workstation; do
      [ ! -L "$root/$name" ] && [ ! -e "$root/$name" ] ||
        fail "link installed a superseded skill name: $root/$name"
    done
  done
  assert_symlink_to "$home_dir/.codex/skills/peer-ask" "$home_dir/old-skills/peer-ask"
  if find "$home_dir/.codex/skills" -maxdepth 1 -name 'peer-ask.backup.*' | grep . > /dev/null; then
    fail "retired peer skill must not replace or back up a foreign skill"
  fi
  [ ! -e "$home_dir/.codex/skills/oh-my-setting" ] ||
    fail "legacy grouped skill symlink not removed"
  [ ! -e "$home_dir/.agents/skills/peer-ask" ] ||
    fail "legacy .agents skill symlink not removed"
  [ ! -e "$home_dir/.pi/agent/skills/peer-review" ] ||
    fail "legacy pi skill symlink not removed"
  [ ! -e "$home_dir/.gemini/GEMINI.md" ] ||
    fail "legacy gemini file not removed"

  # An install that predates the move still has links in the old root.
  ln -s "$ROOT/custom-skills/oms-ops" "$home_dir/.gemini/antigravity/skills/oms-ops"
  ln -s "$ROOT/custom-skills/agent-harness" "$home_dir/.claude/skills/agent-harness"
  ln -s "$home_dir/user-trace" "$home_dir/.claude/skills/trace"

  HOME="$home_dir" "$ROOT/scripts/unlink.sh" >/dev/null

  assert_symlink_to "$home_dir/.codex/skills/peer-ask" "$home_dir/old-skills/peer-ask"
  [ ! -L "$home_dir/.claude/skills/agent-harness" ] ||
    fail "uninstall left a superseded skill name linked into this checkout"
  assert_symlink_to "$home_dir/.claude/skills/trace" "$home_dir/user-trace"
  [ ! -e "$home_dir/.gemini/AGENTS.md" ] || fail "gemini AGENTS.md not unlinked"
  [ ! -e "$home_dir/.gemini/config/skills/oms-spec-interview" ] ||
    fail "antigravity skills not unlinked"
  [ ! -L "$home_dir/.gemini/antigravity/skills/oms-ops" ] ||
    fail "uninstall left an owned link in the retired antigravity root"
  [ -d "$home_dir/.gemini/antigravity/skills/user-skill" ] ||
    fail "uninstall removed a user entry from the retired antigravity root"
}

# smoke-weight: 61
test_skill_doctor_detects_duplicate_names() {
  local home_dir="$TMP/skill-doctor-dup"
  local root
  mkdir -p "$home_dir/.codex/skills/a" "$home_dir/.codex/skills/b"

  cat > "$home_dir/.codex/skills/a/SKILL.md" <<'EOF'
---
name: duplicate-skill
---
EOF
  cat > "$home_dir/.codex/skills/b/SKILL.md" <<'EOF'
---
name: duplicate-skill
---
EOF

  if HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/out" 2>&1; then
    fail "skill-doctor should fail on duplicate names"
  fi
  assert_file_contains "$home_dir/out" "duplicate skill name: duplicate-skill"

  home_dir="$TMP/skill-doctor-codex-overlay"
  mkdir -p "$home_dir/.codex/skills/local" "$home_dir/.agents/skills/shared"
  printf -- '---\nname: duplicate-skill\n---\n' > "$home_dir/.codex/skills/local/SKILL.md"
  printf -- '---\nname: duplicate-skill\n---\n' > "$home_dir/.agents/skills/shared/SKILL.md"
  if HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/out" 2>&1; then
    fail "skill-doctor should detect a duplicate across Codex skill roots"
  fi
  assert_file_contains "$home_dir/out" "duplicate skill name: duplicate-skill"
  assert_file_contains "$home_dir/out" "$home_dir/.codex/skills/local/SKILL.md"
  assert_file_contains "$home_dir/out" "$home_dir/.agents/skills/shared/SKILL.md"

  # The active Antigravity root is scanned; the retired one is migration-only.
  home_dir="$TMP/skill-doctor-dup-agy"
  for root in antigravity config; do
    mkdir -p "$home_dir/.gemini/$root/skills/a" "$home_dir/.gemini/$root/skills/b"
    printf -- '---\nname: duplicate-skill\n---\n' > "$home_dir/.gemini/$root/skills/a/SKILL.md"
    printf -- '---\nname: duplicate-skill\n---\n' > "$home_dir/.gemini/$root/skills/b/SKILL.md"
    if [ "$root" = antigravity ]; then
      HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/out" 2>&1 ||
        fail "skill-doctor must ignore the retired antigravity skills root"
    elif HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/out" 2>&1; then
      fail "skill-doctor should fail on duplicates in the active antigravity root"
    fi
  done
  assert_file_contains "$home_dir/out" "duplicate skill name: duplicate-skill"
}

# smoke-weight: 40
test_skill_doctor_reports_superseded_skill_names() {
  local home_dir="$TMP/skill-doctor-legacy"

  mkdir -p "$home_dir/.claude/skills/agent-harness" "$home_dir/.agents/skills"
  cat > "$home_dir/.claude/skills/agent-harness/SKILL.md" <<'EOF'
---
name: agent-harness
description: A skill directory a previous install left under its old name.
---
EOF
  # The other shape of the same leftover: a link whose renamed source is gone.
  # `-e` is false for it and the SKILL.md scan skips it, so only an explicit
  # legacy-name probe finds it.
  ln -s "$ROOT/custom-skills/oh-my-setting-ops" \
    "$home_dir/.agents/skills/oh-my-setting-ops"

  HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/out" 2>&1 ||
    fail "a superseded skill name is advisory, not a doctor failure: $(cat "$home_dir/out")"

  assert_file_contains "$home_dir/out" \
    "warn: legacy skill name 'agent-harness' at $home_dir/.claude/skills/agent-harness"
  assert_file_contains "$home_dir/out" "superseded by 'oms-agent-harness'"
  assert_file_contains "$home_dir/out" \
    "warn: legacy skill name 'oh-my-setting-ops' at $home_dir/.agents/skills/oh-my-setting-ops"
  assert_file_contains "$home_dir/out" "superseded by 'oms-ops'"
  assert_file_contains "$home_dir/out" "skill-doctor: ok"

  rm -rf "$home_dir/.claude/skills/agent-harness" \
    "$home_dir/.agents/skills/oh-my-setting-ops"
  HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/clean" 2>&1 ||
    fail "a clean install should pass the doctor: $(cat "$home_dir/clean")"
  assert_file_contains "$home_dir/clean" "no skills installed under a superseded name"
  # The doctor totals what a session carries before any task: the global rules
  # plus one listing description per catalog skill, never a skill body.
  local rules_bytes described
  rules_bytes="$(wc -c < "$ROOT/rules/global-AGENTS.md" | tr -d ' ')"
  described="$(find "$ROOT/custom-skills" -mindepth 2 -maxdepth 2 -name SKILL.md | wc -l | tr -d ' ')"
  grep -Eq "^note: always-loaded OMS text is [0-9]+ bytes: global rules $rules_bytes \+ $described skill description\(s\) [0-9]+ \(longest oms-[a-z-]+, [0-9]+\)\$" \
    "$home_dir/clean" || fail "skill-doctor did not total the always-loaded text: $(cat "$home_dir/clean")"

  # The listing budget is advisory: what every installed description costs each
  # CLI before a skill is opened. It never fails the doctor.
  local long_text near
  long_text="$(printf 'routing detail %.0s' $(seq 1 120))"
  near="Review a pull request diff for correctness regressions security problems and missing tests before merge"
  mkdir -p "$home_dir/.claude/skills/oms-long" "$home_dir/.claude/skills/oms-twin-a" \
    "$home_dir/.claude/skills/oms-twin-b" "$home_dir/.codex/skills/oms-small" \
    "$home_dir/.claude/plugins/cache/market/vendor-plugin/1.0.0/skills/oms-twin-a"
  printf -- '---\nname: oms-long\ndescription: %s\nwhen_to_use: %s\n---\n' "$long_text" "$long_text" \
    > "$home_dir/.claude/skills/oms-long/SKILL.md"
  printf -- '---\nname: oms-twin-a\ndescription: %s\n---\n' "$near" > "$home_dir/.claude/skills/oms-twin-a/SKILL.md"
  printf -- '---\nname: oms-twin-b\ndescription: %s now\n---\n' "$near" > "$home_dir/.claude/skills/oms-twin-b/SKILL.md"
  printf -- '---\nname: oms-small\ndescription: A short description for one small Codex skill.\n---\n' \
    > "$home_dir/.codex/skills/oms-small/SKILL.md"
  printf -- '---\nname: oms-twin-a\ndescription: The copy a plugin ships under the same name.\n---\n' \
    > "$home_dir/.claude/plugins/cache/market/vendor-plugin/1.0.0/skills/oms-twin-a/SKILL.md"
  HOME="$home_dir" OMS_SKILL_LISTING_CHARS=1000 "$ROOT/scripts/skill-doctor.sh" >"$home_dir/budget" 2>&1 ||
    fail "the listing budget is advisory, not a doctor failure: $(cat "$home_dir/budget")"
  assert_file_contains "$home_dir/budget" "## Skill listing budget"
  assert_file_contains "$home_dir/budget" "ok: Codex: 1 skill(s), descriptions total 46 characters (budget 1000)"
  assert_file_contains "$home_dir/budget" "warn: Claude: 3 skill(s), descriptions total"
  assert_file_contains "$home_dir/budget" "over the 1000-character listing budget (OMS_SKILL_LISTING_CHARS)"
  assert_file_contains "$home_dir/budget" "warn: Claude skill oms-long lists"
  assert_file_contains "$home_dir/budget" "Claude Code cuts the listing at 1536"
  assert_file_contains "$home_dir/budget" "note: Claude skills oms-twin-a and oms-twin-b have nearly the same description"
  assert_file_contains "$home_dir/budget" \
    "note: skill oms-twin-a is installed at user level and also shipped by a Claude plugin (cache: market/vendor-plugin/1.0.0)"
  assert_file_contains "$home_dir/budget" "skill-doctor: ok"
  ! grep -Fq "routing detail routing detail" "$home_dir/budget" ||
    fail "the listing budget must not print a description"
}

test_skill_doctor_checks_agy_loaded_skills() {
  local home_dir="$TMP/skill-doctor-agy"
  local stub_dir="$home_dir/stub-bin"
  local fx_path="$stub_dir:/usr/bin:/bin"

  mkdir -p "$home_dir" "$stub_dir"
  # A stub timeout keeps the case independent of the host's timeout tool; it
  # drops "-k 5 20" and runs the command.
  printf '#!/usr/bin/env bash\nshift 3\nexec "$@"\n' > "$stub_dir/timeout"
  chmod +x "$stub_dir/timeout"
  # A stub agy prints the loaded-skill JSON shape agy 1.4 reports for /skills:
  # every enabled oms-* manifest skill whose `requires` commands exist on the
  # fixture PATH (the selection link.sh installs), except the one named in $1.
  write_agy_stub() {
    PATH="$fx_path" python3 -I - "$ROOT/skills.manifest.json" "$home_dir/loaded.json" "$1" <<'PY'
import json
import shutil
import sys

manifest, out, omit = sys.argv[1:4]
names = [s["name"] for s in json.load(open(manifest))["skills"]
         if s.get("enabled") and s["name"].startswith("oms-")
         and all(shutil.which(r) for r in s.get("requires") or [])]
loaded = [{"name": n} for n in names if n != omit] + [{"name": "automation"}]
json.dump({"status": "SUCCESS", "command": {"data": {"skills": loaded}}}, open(out, "w"))
PY
    printf '#!/usr/bin/env bash\ncat "%s"\n' "$home_dir/loaded.json" > "$stub_dir/agy"
    chmod +x "$stub_dir/agy"
  }

  write_agy_stub oms-ops
  if PATH="$fx_path" HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/missing" 2>&1; then
    fail "skill-doctor should fail when agy does not load an enabled oms-* skill"
  fi
  assert_file_contains "$home_dir/missing" "fail: agy did not load enabled skill oms-ops"
  assert_file_contains "$home_dir/missing" "skill-doctor: failed"

  write_agy_stub ""
  PATH="$fx_path" HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/complete" 2>&1 ||
    fail "skill-doctor should pass when agy loads every enabled oms-* skill: $(cat "$home_dir/complete")"
  assert_file_contains "$home_dir/complete" "ok: agy loaded all"

  # link.sh skips a skill whose `requires` command is absent, so agy not
  # loading it is correct; once the command exists, the skill is expected.
  if ! PATH="$fx_path" command -v sinfo >/dev/null 2>&1; then
    write_agy_stub oms-slurm
    PATH="$fx_path" HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/unmet" 2>&1 ||
      fail "a skill whose requires are unmet must not be expected from agy: $(cat "$home_dir/unmet")"
    printf '#!/usr/bin/env bash\nexit 0\n' > "$stub_dir/sinfo"
    chmod +x "$stub_dir/sinfo"
    if PATH="$fx_path" HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/met" 2>&1; then
      fail "a skill whose requires are met must be loaded by agy"
    fi
    assert_file_contains "$home_dir/met" "fail: agy did not load enabled skill oms-slurm"
  fi

  # No agy on PATH: the check skips with a note and never fails the doctor.
  rm -f "$stub_dir/agy"
  PATH="$fx_path" HOME="$home_dir" "$ROOT/scripts/skill-doctor.sh" >"$home_dir/absent" 2>&1 ||
    fail "skill-doctor must skip, not fail, when agy is absent: $(cat "$home_dir/absent")"
  assert_file_contains "$home_dir/absent" "skip: agy is not on PATH"
}

test_global_skill_names_are_namespaced() {
  local renames

  python3 "$ROOT/scripts/validate-skills.py" "$ROOT" >"$TMP/validate-skills.out" 2>&1 ||
    fail "the skill catalog should validate: $(cat "$TMP/validate-skills.out")"

  # The static Claude Code marketplace manifest offers exactly the enabled
  # custom skills; nothing installs or registers it, so drift is caught here.
  local market="$TMP/marketplace-drift"
  mkdir -p "$market/scripts" "$market/.claude-plugin"
  cp -R "$ROOT/custom-skills" "$market/custom-skills"
  cp "$ROOT/skills.manifest.json" "$market/skills.manifest.json"
  cp "$ROOT/scripts/validate-skills.py" "$market/scripts/validate-skills.py"
  cp "$ROOT/.claude-plugin/marketplace.json" "$market/.claude-plugin/marketplace.json"
  python3 "$market/scripts/validate-skills.py" "$market" >"$market/out" 2>&1 ||
    fail "the shipped marketplace manifest should validate: $(cat "$market/out")"
  rm "$market/.claude-plugin/marketplace.json"
  python3 "$market/scripts/validate-skills.py" "$market" >"$market/out" 2>&1 ||
    fail "a checkout without the marketplace manifest is still valid: $(cat "$market/out")"
  python3 - "$ROOT/.claude-plugin/marketplace.json" "$market/.claude-plugin/marketplace.json" <<'PY'
import json, sys
doc = json.load(open(sys.argv[1]))
plugin = doc["plugins"][0]
assert plugin["strict"] is False and plugin["source"] == "./custom-skills", plugin
plugin["skills"] = [item for item in plugin["skills"] if item != "./oms-trace"] + ["./oms-absent"]
plugin["strict"] = True
plugin["description"] = "no prerequisite named"
json.dump(doc, open(sys.argv[2], "w"))
PY
  if python3 "$market/scripts/validate-skills.py" "$market" >"$market/out" 2>&1; then
    fail "a marketplace manifest that drifted from the skill catalog must fail validation"
  fi
  assert_file_contains "$market/out" "enabled skill is not offered by any plugin: custom-skills/oms-trace"
  assert_file_contains "$market/out" "lists a path with no SKILL.md: custom-skills/oms-absent"
  assert_file_contains "$market/out" "offers a skill skills.manifest.json does not enable: custom-skills/oms-absent"
  assert_file_contains "$market/out" "needs \"strict\": false"
  assert_file_contains "$market/out" "must say its skills need the oms command"

  renames="$(bash -c '. "$1/scripts/lib/agent-install-state.sh"; oms_ops_legacy_skill_renames' \
    _ "$ROOT")" || fail "the rename table should be readable"

  OMS_T_RENAMES="$renames" python3 - "$ROOT" <<'PY' || fail "skill names are not namespaced"
import json
import os
import pathlib
import sys

root = pathlib.Path(sys.argv[1])
manifest = json.loads((root / "skills.manifest.json").read_text(encoding="utf-8"))
rows = manifest["skills"]
assert rows, "the manifest ships no skills"

# The old names, still reachable from installs made before the rename. None of
# them may return as a shipped skill: the rename table would then claim a live
# name is superseded, and the doctor would tell users to delete a current one.
renames = dict(
    line.split(":", 1)
    for line in os.environ["OMS_T_RENAMES"].split()
    if ":" in line
)
assert len(renames) >= 5, renames

for row in rows:
    name = row["name"]
    source = row["source"]
    assert name.startswith("oms-"), "global skill is not namespaced: %s" % name
    assert source == "custom-skills/%s" % name, (name, source)
    assert (root / source / "SKILL.md").is_file(), source
    assert name not in renames, "a superseded name is shipped again: %s" % name

shipped = {row["name"] for row in rows}
missing = set(renames.values()) - shipped
assert not missing, "the rename table points at skills that do not exist: %s" % sorted(missing)
PY
}

# smoke-weight: 21
test_cleanup_dry_run_and_apply() {
  local home_dir="$TMP/cleanup-home"
  mkdir -p "$home_dir/.codex/skills" "$home_dir/.agents/skills" \
    "$home_dir/.pi/agent/skills" "$home_dir/.gemini"
  ln -s "$ROOT/custom-skills/oms-trace" \
    "$home_dir/.codex/skills/oms-trace.backup.legacy"
  ln -s "$ROOT/custom-skills/oms-trust-boundary" \
    "$home_dir/.agents/skills/oms-trust-boundary"
  # A skill installed before the `oms-` namespace. The current-name sweep
  # cannot see it, and its source is gone, so only the rename table removes it.
  ln -s "$ROOT/custom-skills/spec-interview" \
    "$home_dir/.pi/agent/skills/spec-interview"
  ln -s "$ROOT/AGENTS.md" "$home_dir/.gemini/GEMINI.md"
  # A user's own backup link must survive: it does not point into this install.
  mkdir -p "$home_dir/mine"
  ln -s "$home_dir/mine" "$home_dir/.codex/skills/mine.backup.legacy"
  ln -s "$ROOT/.." "$home_dir/.codex/skills/parent.backup.legacy"
  # The helper treats $HOME/.oh-my-setting as an install root, so the in-root
  # intermediate links live there and the source checkout stays untouched.
  local final_link="$home_dir/.oh-my-setting/final-link"
  mkdir -p "$home_dir/.oh-my-setting"
  ln -s "$home_dir/mine" "$final_link"
  ln -s "$final_link" "$home_dir/.codex/skills/final-link.backup.legacy"
  # "hop" is an in-install symlink to an outside directory: hop/.. is the
  # outside parent for the kernel but would be the install for a logical cd.
  ln -s "$home_dir/mine" "$home_dir/.oh-my-setting/hop"
  ln -s "$home_dir/.oh-my-setting/hop/.." \
    "$home_dir/.codex/skills/hop.backup.legacy"
  # A dangling target ending in a newline must not collapse onto the existing
  # AGENTS.md once command substitution strips the newline.
  ln -s "$ROOT/AGENTS.md"$'\n' "$home_dir/.codex/skills/newline.backup.legacy"
  # An existing outside directory named "$ROOT<LF>" must not read as $ROOT once
  # pwd -P output loses its trailing newline, directly or through "..".
  # The directory is a sibling of the checkout, so remove it before asserting.
  local lf_dir="$ROOT"$'\n' lf_dry lf_apply
  mkdir "$lf_dir" || fail "cannot create the newline-named sibling directory"
  ln -s "$ROOT"$'\n' "$home_dir/.codex/skills/rootlf.backup.legacy"
  ln -s "$ROOT"$'\n/..' "$home_dir/.codex/skills/rootlf-dotdot.backup.legacy"

  # The suite-wide cache holds other tests' dead harness dirs; count only this home.
  HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" "$ROOT/scripts/cleanup.sh" --dry-run >"$home_dir/dry-run"
  lf_dry=ok
  [ -L "$home_dir/.codex/skills/rootlf.backup.legacy" ] &&
    [ -L "$home_dir/.codex/skills/rootlf-dotdot.backup.legacy" ] || lf_dry=removed
  assert_file_contains "$home_dir/dry-run" "cleanup: 4 removable item(s) found"
  [ -e "$home_dir/.codex/skills/oms-trace.backup.legacy" ] ||
    fail "dry-run removed backup symlink"
  [ -L "$home_dir/.codex/skills/parent.backup.legacy" ] ||
    fail "dry-run removed parent backup symlink"
  [ -L "$home_dir/.codex/skills/final-link.backup.legacy" ] ||
    fail "dry-run removed final-symlink backup link"
  [ -L "$home_dir/.codex/skills/hop.backup.legacy" ] ||
    fail "dry-run removed symlink-then-.. backup link"
  [ -L "$home_dir/.codex/skills/newline.backup.legacy" ] ||
    fail "dry-run removed trailing-newline backup link"

  HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" "$ROOT/scripts/cleanup.sh" --apply >"$home_dir/apply"
  lf_apply=ok
  [ -L "$home_dir/.codex/skills/rootlf.backup.legacy" ] &&
    [ -L "$home_dir/.codex/skills/rootlf-dotdot.backup.legacy" ] || lf_apply=removed
  rmdir "$lf_dir"
  [ "$lf_dry" = ok ] || fail "dry-run removed a backup link to a newline-named outside dir"
  [ "$lf_apply" = ok ] || fail "cleanup removed a backup link to a newline-named outside dir"
  [ ! -e "$home_dir/.codex/skills/oms-trace.backup.legacy" ] ||
    fail "cleanup did not remove backup symlink"
  [ -L "$home_dir/.codex/skills/mine.backup.legacy" ] ||
    fail "cleanup removed a backup link outside this install"
  [ -L "$home_dir/.codex/skills/parent.backup.legacy" ] ||
    fail "cleanup removed parent backup symlink"
  [ -L "$home_dir/.codex/skills/final-link.backup.legacy" ] ||
    fail "cleanup removed final-symlink backup link"
  [ -L "$home_dir/.codex/skills/hop.backup.legacy" ] ||
    fail "cleanup removed symlink-then-.. backup link"
  [ -L "$home_dir/.codex/skills/newline.backup.legacy" ] ||
    fail "cleanup removed trailing-newline backup link"
  [ ! -e "$home_dir/.agents/skills/oms-trust-boundary" ] ||
    fail "cleanup did not remove legacy .agents skill"
  # -L, not -e: the link dangles once its renamed source is gone, and -e would
  # call a surviving link removed.
  [ ! -L "$home_dir/.pi/agent/skills/spec-interview" ] ||
    fail "cleanup did not remove the superseded-name pi skill"
  [ ! -e "$home_dir/.gemini/GEMINI.md" ] ||
    fail "cleanup did not remove legacy gemini file"
  assert_file_contains "$home_dir/apply" "skill-doctor: ok"

  # link.sh's stale sweep and Antigravity retirement judge ownership by the
  # spelled prefix; a ".." component must not let them delete foreign links.
  local sweep_home="$TMP/cleanup-sweep-home"
  mkdir -p "$sweep_home/.codex/skills" "$sweep_home/.gemini/antigravity/skills"
  ln -s "$ROOT/custom-skills/../../outside/missing" \
    "$sweep_home/.codex/skills/stale.backup.20260101000000"
  ln -s "$ROOT/custom-skills/../../outside" \
    "$sweep_home/.gemini/antigravity/skills/retired"
  HOME="$sweep_home" "$ROOT/scripts/link.sh" >/dev/null
  [ -L "$sweep_home/.codex/skills/stale.backup.20260101000000" ] ||
    fail "stale sweep removed a backup link escaping via .."
  [ -L "$sweep_home/.gemini/antigravity/skills/retired" ] ||
    fail "skill retirement removed a link escaping via .."
}


# smoke-weight: 21
test_cleanup_prunes_stale_worktree_registration() {
