test_update_refreshes_providers_by_default_and_tools_on_request() {
  local project="$TMP/update-tools-opt-in"
  local bin="$project/bin"
  local receipt="$TMP/update-tools-opt-in-receipt.json"
  local marker="$TMP/update-tools-called"
  local permission_marker="$TMP/update-permissions-called"
  local branch legacy_target

  make_committed_repo "$project"
  mkdir -p "$project/scripts/lib" "$bin"
  cp "$ROOT/scripts/update.sh" "$project/scripts/update.sh"
  cp "$ROOT/scripts/lib/install-contract.sh" "$project/scripts/lib/install-contract.sh"
  cp "$ROOT/scripts/lib/install-lifecycle-lock.sh" "$project/scripts/lib/install-lifecycle-lock.sh"
  cp "$ROOT/scripts/lib/canonical-sync.sh" "$project/scripts/lib/canonical-sync.sh"
  cp "$ROOT/scripts/lib/file-lock.sh" "$project/scripts/lib/file-lock.sh"
  cp "$ROOT/scripts/lib/harness-residue.sh" "$project/scripts/lib/harness-residue.sh"
  cp "$ROOT/scripts/lib/oms-common.sh" "$project/scripts/lib/oms-common.sh"
  cp "$ROOT/scripts/lib/poll.sh" "$project/scripts/lib/poll.sh"
  for script in link doctor install-autoupdate uninstall-autoupdate install-claude-hooks install-mcp install-agy-plugin; do
    printf '#!/usr/bin/env bash\nexit 0\n' > "$project/scripts/$script.sh"
    chmod +x "$project/scripts/$script.sh"
  done
  cat > "$project/scripts/install-tools.sh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" > "$OMS_TEST_TOOLS_MARKER"
EOF
  chmod +x "$project/scripts/install-tools.sh"
  cat > "$project/scripts/provider-permissions.sh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" > "$OMS_TEST_PERMISSION_MARKER"
exit "${OMS_TEST_PERMISSION_STATUS:-0}"
EOF
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  chmod +x "$project/scripts/provider-permissions.sh" "$bin/agy"
  cat > "$bin/git" <<'EOF'
#!/usr/bin/env bash
case "$*" in
  *' pull --ff-only') exit 0 ;;
esac
exec /usr/bin/git "$@"
EOF
  chmod +x "$bin/git"
  git -C "$project" add scripts bin
  git -C "$project" commit -qm "test: legacy update fixture"
  legacy_target="$(git -C "$project" rev-parse HEAD)"
  # Presence of the resolver is the selected checkout's provider-refresh
  # contract. Older targets lack it and only accept install-tools --upgrade.
  : > "$project/scripts/lib/provider-latest.py"
  git -C "$project" add scripts/lib/provider-latest.py
  git -C "$project" commit -qm "test: modern provider refresh fixture"
  branch="$(git -C "$project" symbolic-ref --short HEAD)"
  git -C "$project" remote add origin "$project"
  git -C "$project" fetch -q origin "$branch"
  git -C "$project" branch --set-upstream-to="origin/$branch" "$branch" >/dev/null
  python3 - "$receipt" "$project" <<'PY'
import json, sys
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({
        "schema": 1,
        "source_root": sys.argv[2],
        "commit": "0123456789abcdef0123456789abcdef01234567",
        "channel": "main",
        "version": "0.3.0",
        "installed_at": "2026-07-12T00:00:00Z",
        "plugin": {"name": "oh-my-setting", "version": "0.1.0", "sha256": "test"},
    }, handle)
PY

  export OMS_TEST_PERMISSION_MARKER="$permission_marker"
  PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" OMS_TEST_TOOLS_MARKER="$marker" \
    OH_MY_SETTING_CLAUDE_HOOKS=0 OH_MY_SETTING_CODEX_PLUGIN=0 OH_MY_SETTING_AUTO_UPDATE=0 \
    "$project/scripts/update.sh" --no-tools --no-doctor >/dev/null
  assert_not_exists "$marker"
  assert_not_exists "$permission_marker"

  PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" OMS_TEST_TOOLS_MARKER="$marker" \
    OH_MY_SETTING_CLAUDE_HOOKS=0 OH_MY_SETTING_CODEX_PLUGIN=0 OH_MY_SETTING_AUTO_UPDATE=0 \
    "$project/scripts/update.sh" --no-doctor >/dev/null
  assert_file_contains "$marker" '--providers'
  assert_file_contains "$permission_marker" '--apply --profile delegate --allow-toolchains'

  rm -f "$permission_marker"
  PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" OMS_TEST_TOOLS_MARKER="$marker" \
    OH_MY_SETTING_PEER_PERMISSIONS=0 OH_MY_SETTING_CLAUDE_HOOKS=0 OH_MY_SETTING_CODEX_PLUGIN=0 OH_MY_SETTING_AUTO_UPDATE=0 \
    "$project/scripts/update.sh" --no-doctor >/dev/null
  assert_not_exists "$permission_marker"

  PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" OMS_TEST_TOOLS_MARKER="$marker" \
    OMS_TEST_PERMISSION_STATUS=1 OH_MY_SETTING_CLAUDE_HOOKS=0 OH_MY_SETTING_CODEX_PLUGIN=0 OH_MY_SETTING_AUTO_UPDATE=0 \
    "$project/scripts/update.sh" --no-doctor > "$TMP/update-permission-warning" 2>&1 ||
    fail "provider permission failure aborted update"
  assert_file_contains "$TMP/update-permission-warning" 'oms provider-permissions --apply --profile delegate --allow-toolchains'

  PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" OMS_TEST_TOOLS_MARKER="$marker" \
    OH_MY_SETTING_CLAUDE_HOOKS=0 OH_MY_SETTING_CODEX_PLUGIN=0 OH_MY_SETTING_AUTO_UPDATE=0 \
    "$project/scripts/update.sh" --tools --no-doctor >/dev/null
  assert_file_contains "$marker" '--upgrade'

  rm -f "$marker"
  PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" OMS_TEST_TOOLS_MARKER="$marker" \
    OH_MY_SETTING_CLAUDE_HOOKS=0 OH_MY_SETTING_CODEX_PLUGIN=0 OH_MY_SETTING_AUTO_UPDATE=0 \
    "$project/scripts/update.sh" --ref "$legacy_target" --no-doctor \
      > "$TMP/update-legacy-provider.out" 2>&1 ||
    fail "an older selected target rejected the new default provider refresh"
  assert_not_exists "$marker"
  assert_file_contains "$TMP/update-legacy-provider.out" \
    'selected target predates automatic provider refresh'
}

test_update_auto_refreshes_only_installed_codex_plugin() {
  local project="$TMP/update-plugin-auto"
  local bin="$project/bin"
  local receipt="$TMP/update-plugin-auto-receipt.json"
  local marker="$project/plugin-called"
  local branch

  make_committed_repo "$project"
  mkdir -p "$project/scripts/lib" "$bin"
  cp "$ROOT/scripts/update.sh" "$project/scripts/update.sh"
  cp "$ROOT/scripts/lib/install-contract.sh" "$project/scripts/lib/install-contract.sh"
  cp "$ROOT/scripts/lib/install-lifecycle-lock.sh" "$project/scripts/lib/install-lifecycle-lock.sh"
  cp "$ROOT/scripts/lib/canonical-sync.sh" "$project/scripts/lib/canonical-sync.sh"
  cp "$ROOT/scripts/lib/file-lock.sh" "$project/scripts/lib/file-lock.sh"
  cp "$ROOT/scripts/lib/harness-residue.sh" "$project/scripts/lib/harness-residue.sh"
  cp "$ROOT/scripts/lib/oms-common.sh" "$project/scripts/lib/oms-common.sh"
  cp "$ROOT/scripts/lib/poll.sh" "$project/scripts/lib/poll.sh"
  for script in link doctor install-autoupdate uninstall-autoupdate install-tools install-claude-hooks install-mcp install-agy-plugin; do
    printf '#!/usr/bin/env bash\nexit 0\n' > "$project/scripts/$script.sh"
    chmod +x "$project/scripts/$script.sh"
  done
cat > "$project/scripts/install-codex-plugin.sh" <<'EOF'
#!/usr/bin/env bash
[ "${1:-}" != "--remove" ] || exit 0
touch "$OMS_TEST_PLUGIN_MARKER"
EOF
  chmod +x "$project/scripts/install-codex-plugin.sh"
  cat > "$bin/git" <<'EOF'
#!/usr/bin/env bash
case "$*" in
  *' pull --ff-only') exit 0 ;;
esac
exec /usr/bin/git "$@"
EOF
  cat > "$bin/codex" <<'EOF'
#!/usr/bin/env bash
if [ "$1 $2 $3" = "plugin list --json" ]; then
  if [ "${OMS_TEST_PLUGIN_INSTALLED:-0}" = "1" ]; then
    printf '%s\n' '{"installed":[{"pluginId":"oh-my-setting@oh-my-setting-local","installed":true}]}'
  else
    printf '%s\n' '{"installed":[]}'
  fi
fi
EOF
  chmod +x "$bin/git" "$bin/codex"
  git -C "$project" add scripts bin
  git -C "$project" commit -qm "test: plugin update fixture"
  branch="$(git -C "$project" symbolic-ref --short HEAD)"
  git -C "$project" remote add origin "$project"
  git -C "$project" fetch -q origin "$branch"
  git -C "$project" branch --set-upstream-to="origin/$branch" "$branch" >/dev/null
  python3 - "$receipt" "$project" <<'PY'
import json, sys
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({
        "schema": 1,
        "source_root": sys.argv[2],
        "commit": "0123456789abcdef0123456789abcdef01234567",
        "channel": "main",
        "version": "0.3.0",
        "installed_at": "2026-07-12T00:00:00Z",
        "plugin": {"name": "oh-my-setting", "version": "0.1.0", "sha256": "test"},
    }, handle)
PY

  env -u OH_MY_SETTING_CODEX_PLUGIN \
    PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" \
    OMS_TEST_PLUGIN_MARKER="$marker" OH_MY_SETTING_CLAUDE_HOOKS=0 \
    OH_MY_SETTING_AUTO_UPDATE=0 "$project/scripts/update.sh" --no-doctor >/dev/null
  assert_not_exists "$marker"

  env -u OH_MY_SETTING_CODEX_PLUGIN \
    PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" \
    OMS_TEST_PLUGIN_MARKER="$marker" OMS_TEST_PLUGIN_INSTALLED=1 \
    OH_MY_SETTING_CLAUDE_HOOKS=0 OH_MY_SETTING_AUTO_UPDATE=0 \
    "$project/scripts/update.sh" --no-doctor >/dev/null
  [ -f "$marker" ] || fail "update auto mode should refresh an installed codex plugin"
}

