}

test_autoupdate_systemd_failure_restores_state() {
  local dir="$TMP/autoupdate-rollback" scenario kind stage units file
  mkdir -p "$dir/bin" "$dir/home"
  cat > "$dir/bin/systemctl" <<'EOF'
#!/usr/bin/env bash
set -eu
case "$2" in
  show-environment) exit 0 ;;
  is-enabled) cat "$OMS_TEST_SYSTEMD/enabled"; exit 0 ;;
  is-active) [ "$(cat "$OMS_TEST_SYSTEMD/active")" = 1 ]; exit $? ;;
  daemon-reload)
    if [ "$OMS_TEST_FAILURE" = daemon ] && [ ! -f "$OMS_TEST_SYSTEMD/failed" ]; then
      touch "$OMS_TEST_SYSTEMD/failed"; exit 1
    fi ;;
  enable)
    echo enabled > "$OMS_TEST_SYSTEMD/enabled"
    if [ "${3:-}" = --now ]; then
      echo 1 > "$OMS_TEST_SYSTEMD/active"
      if [ "$OMS_TEST_FAILURE" = enable ]; then exit 1; fi
    fi ;;
  disable) echo disabled > "$OMS_TEST_SYSTEMD/enabled" ;;
  start) echo 1 > "$OMS_TEST_SYSTEMD/active" ;;
  stop) echo 0 > "$OMS_TEST_SYSTEMD/active" ;;
esac
EOF
  cat > "$dir/bin/loginctl" <<'EOF'
#!/usr/bin/env bash
set -eu
case "$*" in
  *show-user*) printf 'Linger=%s\n' "$(cat "$OMS_TEST_SYSTEMD/linger")" ;;
  *enable-linger*) echo yes > "$OMS_TEST_SYSTEMD/linger"; [ "$OMS_TEST_FAILURE" != linger ] ;;
  *disable-linger*) echo no > "$OMS_TEST_SYSTEMD/linger" ;;
esac
EOF
  chmod +x "$dir/bin/systemctl" "$dir/bin/loginctl"
  for scenario in existing:daemon existing:enable existing:linger new:enable; do
    kind="${scenario%:*}" stage="${scenario#*:}"
    units="$dir/$kind-$stage/config/systemd/user"
    mkdir -p "$units" "$dir/$kind-$stage/runtime"
    if [ "$kind" = existing ]; then
      for file in service timer; do
        printf 'operator-owned %s contents\n' "$file" > "$units/oh-my-setting-autoupdate.$file"
      done
      echo enabled > "$dir/$kind-$stage/enabled"
      echo 1 > "$dir/$kind-$stage/active"
    else
      echo disabled > "$dir/$kind-$stage/enabled"
      echo 0 > "$dir/$kind-$stage/active"
    fi
    echo no > "$dir/$kind-$stage/linger"
    if HOME="$dir/home" XDG_CONFIG_HOME="$dir/$kind-$stage/config" \
        XDG_RUNTIME_DIR="$dir/$kind-$stage/runtime" PATH="$dir/bin:$PATH" \
        OMS_INSTALL_RECEIPT="$dir/absent-receipt.json" \
        OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$dir/cron" OH_MY_SETTING_AUTO_UPDATE_LINGER=1 \
        OMS_TEST_SYSTEMD="$dir/$kind-$stage" OMS_TEST_FAILURE="$stage" \
        "$ROOT/scripts/install-autoupdate.sh" --method systemd > "$dir/out" 2>&1; then
      fail "scheduler failure injection unexpectedly passed: $scenario"
    fi
    grep -Fq 'previous unit files and timer state restored' "$dir/out" || fail "$scenario rollback failed: $(cat "$dir/out")"
    [ "$(cat "$dir/$kind-$stage/linger")" = no ] || fail 'rollback lost logout state'
    if [ "$kind" = existing ]; then
      for file in service timer; do
        [ "$(cat "$units/oh-my-setting-autoupdate.$file")" = "operator-owned $file contents" ] || fail 'rollback lost original unit'
      done
      [ "$(cat "$dir/$kind-$stage/enabled")" = enabled ] || fail 'rollback disabled original timer'
      [ "$(cat "$dir/$kind-$stage/active")" = 1 ] || fail 'rollback stopped original timer'
    else
      [ ! -e "$units/oh-my-setting-autoupdate.service" ] || fail 'new unit survived failed install'
      [ ! -e "$units/oh-my-setting-autoupdate.timer" ] || fail 'new timer survived failed install'
      [ "$(cat "$dir/$kind-$stage/enabled")" = disabled ] || fail 'new timer remained enabled'
      [ "$(cat "$dir/$kind-$stage/active")" = 0 ] || fail 'new timer remained active'
    fi
  done
}

test_autoupdate_cron_install_and_uninstall() {
  local cron_file="$TMP/autoupdate.cron"
  local config_home="$TMP/autoupdate-config"
  local dry_home="$TMP/autoupdate-dry-home"
  local receipt="$TMP/autoupdate-receipt.json"
  local out

  mkdir -p "$config_home" "$dry_home"
  HOME="$dry_home" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron --dry-run >/dev/null
  [ ! -e "$cron_file" ] || fail "install-autoupdate dry-run wrote cron file"
  [ -z "$(find "$dry_home" -mindepth 1 -print -quit 2>/dev/null)" ] ||
    fail "install-autoupdate dry-run wrote under HOME"
  # Default mode is apply: a fresh install keeps itself current on the
  # schedule (fast-forward only; auto-update.sh skips dirty/diverged trees).
  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron >"$TMP/autoupdate-default"
  assert_file_contains "$TMP/autoupdate-default" "cron installed (apply)"
  assert_file_contains "$cron_file" "OMS_AUTO_UPDATE_MANAGED=1"
  grep -Fq 'auto-update.sh" apply' "$cron_file" ||
    fail "default auto-update trigger must schedule apply"
  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" >/dev/null

  # --check-only opts down to recording update availability without touching
  # the checkout.
  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron --check-only \
    >"$TMP/autoupdate-checkonly"
  assert_file_contains "$TMP/autoupdate-checkonly" "cron installed (check)"
  if grep -Fq 'auto-update.sh" apply' "$cron_file"; then
    fail "--check-only trigger must not schedule apply"
  fi
  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" >/dev/null

  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    OH_MY_SETTING_CLAUDE_HOOKS=0 OH_MY_SETTING_CODEX_PLUGIN=0 \
    OH_MY_SETTING_MCP=0 OH_MY_SETTING_AGY_PLUGIN=0 \
    "$ROOT/scripts/install-autoupdate.sh" --method cron --apply >"$TMP/autoupdate-install"
  assert_file_contains "$TMP/autoupdate-install" "cron installed (apply)"
  assert_file_contains "$cron_file" "# oh-my-setting autoupdate:begin"
  assert_file_contains "$cron_file" "auto-update.sh\" apply"
  assert_file_contains "$cron_file" "OH_MY_SETTING_CLAUDE_HOOKS=0"
  assert_file_contains "$cron_file" "OH_MY_SETTING_CODEX_PLUGIN=0"
  assert_file_contains "$cron_file" "OH_MY_SETTING_MCP=0"
  assert_file_contains "$cron_file" "OH_MY_SETTING_AGY_PLUGIN=0"

  out="$(XDG_CONFIG_HOME="$config_home" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" "$ROOT/scripts/status.sh" 2>/dev/null)"
  contains "$out" '- trigger: cron' || fail "status.sh missing cron trigger"

  # A stale disabled unit file must not hide the active cron trigger.
  mkdir -p "$config_home/systemd/user"
  printf '[Timer]\nOnCalendar=daily\n' > "$config_home/systemd/user/oh-my-setting-autoupdate.timer"
  out="$(XDG_CONFIG_HOME="$config_home" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" "$ROOT/scripts/status.sh" 2>/dev/null)"
  contains "$out" '- trigger: cron' || fail "disabled systemd file hid active cron trigger"

  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" >"$TMP/autoupdate-uninstall"
  assert_file_contains "$TMP/autoupdate-uninstall" "auto-update trigger: removed"
  if grep -Fq "oh-my-setting autoupdate" "$cron_file"; then
    fail "uninstall-autoupdate should remove cron marker block"
  fi
}

# The unit name is global to the user's systemd manager, but the unit file the
# uninstaller manages lives under XDG_CONFIG_HOME. Removing the trigger from a
# foreign config home (a test fixture, another profile) used to reach the real
# manager anyway, so every gate run disabled the operator's own updater: the
# daily timer went inactive at the exact minute of a push gate.
test_autoupdate_uninstall_touches_only_its_own_systemd_unit() {
  local cron_file="$TMP/autoupdate-foreign.cron"
  local config_home="$TMP/autoupdate-foreign-config"
  local bin="$TMP/autoupdate-foreign-bin"
  local log="$TMP/autoupdate-foreign-systemctl.log"
  local unit_dir="$config_home/systemd/user"
  local timer="$unit_dir/oh-my-setting-autoupdate.timer"
  local service="$unit_dir/oh-my-setting-autoupdate.service"

  mkdir -p "$bin" "$unit_dir"
  cat > "$bin/systemctl" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$OMS_TEST_SYSTEMCTL_LOG"
case "$*" in
  *show*FragmentPath*) printf '%s\n' "${OMS_TEST_SYSTEMCTL_FRAGMENT:-}" ;;
esac
exit 0
EOF
  chmod +x "$bin/systemctl"

  uninstall_here() {  # uninstall_here FRAGMENT_PATH
    XDG_CONFIG_HOME="$config_home" XDG_RUNTIME_DIR="$TMP/autoupdate-foreign-runtime" \
      OMS_INSTALL_RECEIPT="$TMP/autoupdate-foreign-receipt.json" \
      OMS_TEST_SYSTEMCTL_LOG="$log" OMS_TEST_SYSTEMCTL_FRAGMENT="$1" \
      OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
      PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/uninstall-autoupdate.sh" >/dev/null
  }

  # 1. No unit file under this config home: the manager is never consulted.
  OMS_INSTALL_RECEIPT="$TMP/autoupdate-foreign-receipt.json" \
    OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron >/dev/null
  uninstall_here ""
  [ ! -e "$log" ] ||
    fail "uninstall without a unit file reached systemctl: $(cat "$log")"
  if grep -Fq "oh-my-setting autoupdate" "$cron_file"; then
    fail "uninstall must still remove its cron block"
  fi

  # 2. A unit file here, but the manager loaded one from elsewhere: remove
  #    the file, leave the manager's unit alone.
  printf '[Timer]\nOnCalendar=daily\n' > "$timer"
  printf '[Service]\nType=oneshot\n' > "$service"
  uninstall_here "$TMP/elsewhere/oh-my-setting-autoupdate.timer"
  [ ! -e "$timer" ] && [ ! -e "$service" ] ||
    fail "uninstall left its own unit files behind"
  if grep -Eq 'disable|daemon-reload' "$log"; then
    fail "uninstall touched a manager unit it does not own: $(cat "$log")"
  fi

  # 3. The manager's unit is this very file: disable it and reload.
  : > "$log"
  printf '[Timer]\nOnCalendar=daily\n' > "$timer"
  printf '[Service]\nType=oneshot\n' > "$service"
  uninstall_here "$timer"
  grep -Fq -- '--user disable --now oh-my-setting-autoupdate.timer' "$log" ||
    fail "uninstall must disable the unit it owns: $(cat "$log")"
  grep -Fq -- '--user daemon-reload' "$log" ||
    fail "uninstall must reload the manager after removing its unit: $(cat "$log")"
  [ ! -e "$timer" ] || fail "uninstall left its owned unit file behind"
}

# A begin marker without its matching end marker is not an owned block. The
# installer used to stream-filter that input through awk, consume everything
# after the orphan marker, and then write a fresh block in its place. That can
# delete unrelated user cron entries, so every scheduler mutation must refuse
# the malformed state before writing any bytes.
test_autoupdate_malformed_cron_fails_closed() {
  local cron_file="$TMP/autoupdate-malformed.cron"
  local before="$TMP/autoupdate-malformed.before"
  local config_home="$TMP/autoupdate-malformed-config"
  local out="$TMP/autoupdate-malformed.out"

  mkdir -p "$config_home/systemd/user"
  printf '%s\n%s\n%s\n' \
    'MAILTO=owner@example.test' \
    '# oh-my-setting autoupdate:begin' \
    '0 0 * * * keep-this-unrelated-job' > "$cron_file"
  cp "$cron_file" "$before"

  if OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron >"$out" 2>&1; then
    fail "install-autoupdate accepted an unterminated managed cron block"
  fi
  cmp -s "$before" "$cron_file" ||
    fail "install-autoupdate changed malformed cron bytes"
  if OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron --dry-run \
      >"$TMP/autoupdate-malformed-install-dry.out" 2>&1; then
    fail "install-autoupdate dry-run accepted malformed cron"
  fi
  cmp -s "$before" "$cron_file" ||
    fail "install-autoupdate dry-run changed malformed cron bytes"
  grep -Fq 'malformed auto-update cron block' "$out" ||
    fail "install-autoupdate malformed refusal was not actionable: $(cat "$out")"

  # Removal owns both trigger kinds. It must classify cron before removing a
  # systemd unit or recording auto_update=false.
  printf '[Timer]\nOnCalendar=daily\n' > \
    "$config_home/systemd/user/oh-my-setting-autoupdate.timer"
  if XDG_CONFIG_HOME="$config_home" XDG_RUNTIME_DIR='' \
    OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" >"$TMP/autoupdate-malformed-remove.out" 2>&1; then
    fail "uninstall-autoupdate accepted an unterminated managed cron block"
  fi
  cmp -s "$before" "$cron_file" ||
    fail "uninstall-autoupdate changed malformed cron bytes"
  if XDG_CONFIG_HOME="$config_home" XDG_RUNTIME_DIR='' \
    OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" --dry-run \
      >"$TMP/autoupdate-malformed-remove-dry.out" 2>&1; then
    fail "uninstall-autoupdate dry-run accepted malformed cron"
  fi
  cmp -s "$before" "$cron_file" ||
    fail "uninstall-autoupdate dry-run changed malformed cron bytes"
  [ -f "$config_home/systemd/user/oh-my-setting-autoupdate.timer" ] ||
    fail "uninstall-autoupdate changed systemd state before rejecting malformed cron"
}

assert_malformed_cron_blocks_systemd_install() {
  local label="$1"
  local method="$2"
  local cron_file="$TMP/autoupdate-malformed-$label.cron"
  local cron_before="$TMP/autoupdate-malformed-$label.before"
  local config_home="$TMP/autoupdate-malformed-$label-config"
  local home_dir="$TMP/autoupdate-malformed-$label-home"
  local bin="$TMP/autoupdate-malformed-$label-bin"
  local systemctl_log="$TMP/autoupdate-malformed-$label-systemctl.log"
  local receipt="$TMP/autoupdate-malformed-$label-receipt.json"
  local receipt_before="$TMP/autoupdate-malformed-$label-receipt.before"
  local out="$TMP/autoupdate-malformed-$label.out"

  mkdir -p "$bin" "$home_dir"
  cat > "$bin/systemctl" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$OMS_TEST_SYSTEMCTL_LOG"
exit 0
EOF
  chmod +x "$bin/systemctl"
  printf '%s\n%s\n' '# oh-my-setting autoupdate:begin' \
    '0 0 * * * keep-this-unrelated-job' > "$cron_file"
  cp "$cron_file" "$cron_before"
  python3 - "$receipt" "$ROOT" <<'PY'
import json
import sys

json.dump({
    "schema": 2,
    "source_root": sys.argv[2],
    "commit": "0123456789abcdef0123456789abcdef01234567",
    "channel": "main",
    "version": "0.3.0",
    "profile": "custom",
    "ref": "main",
    "previous_commit": "",
    "link_mode": "symlink",
    "installed_at": "2026-07-12T00:00:00Z",
    "components": {
        "tools": False,
        "claude_hooks": False,
        "codex_plugin": False,
        "auto_update": False,
        "machine_snapshot": False,
        "slurm_snapshot": False,
    },
    "managed_targets": [".local/bin/oms"],
    "plugin": {"name": "oh-my-setting", "version": "0.1.0", "sha256": "test"},
}, open(sys.argv[1], "w", encoding="utf-8"))
PY
  cp "$receipt" "$receipt_before"

  if HOME="$home_dir" XDG_CONFIG_HOME="$config_home" \
    XDG_RUNTIME_DIR="$TMP/autoupdate-malformed-$label-runtime" \
    OMS_INSTALL_RECEIPT="$receipt" OMS_TEST_SYSTEMCTL_LOG="$systemctl_log" \
    OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/install-autoupdate.sh" \
      --method "$method" >"$out" 2>&1; then
    fail "$label systemd install accepted malformed cron"
  fi
  grep -Fq 'malformed auto-update cron block' "$out" ||
    fail "$label systemd malformed refusal was not actionable: $(cat "$out")"
  cmp -s "$cron_before" "$cron_file" ||
    fail "$label systemd install changed malformed cron bytes"
  cmp -s "$receipt_before" "$receipt" ||
    fail "$label systemd install changed the receipt before rejecting cron"
  [ ! -e "$config_home/systemd/user/oh-my-setting-autoupdate.service" ] ||
    fail "$label systemd install wrote a service before rejecting cron"
  [ ! -e "$config_home/systemd/user/oh-my-setting-autoupdate.timer" ] ||
    fail "$label systemd install wrote a timer before rejecting cron"
  [ ! -e "$systemctl_log" ] ||
    fail "$label systemd install probed systemctl before rejecting cron"
}

test_autoupdate_malformed_cron_blocks_systemd_installs() {
  assert_malformed_cron_blocks_systemd_install explicit-systemd systemd
  assert_malformed_cron_blocks_systemd_install auto-systemd auto
}

test_autoupdate_malformed_cron_precedes_systemd_status() {
  local cron_file="$TMP/autoupdate-malformed-systemd.cron"
  local config_home="$TMP/autoupdate-malformed-systemd-config"
  local timer_dir="$config_home/systemd/user"
  local out

  mkdir -p "$timer_dir/timers.target.wants"
  printf '%s\n%s\n' '# oh-my-setting autoupdate:begin' \
    '0 0 * * * keep-this-unrelated-job' > "$cron_file"
  printf '[Timer]\nOnCalendar=daily\n' > \
    "$timer_dir/oh-my-setting-autoupdate.timer"
  ln -s ../oh-my-setting-autoupdate.timer \
    "$timer_dir/timers.target.wants/oh-my-setting-autoupdate.timer"

  out="$(XDG_CONFIG_HOME="$config_home" \
    OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/status.sh" 2>/dev/null)"
  printf '%s\n' "$out" | grep >/dev/null -Fx -- '- trigger: cron (malformed)' ||
    fail "active systemd masked malformed cron status: $out"
}

test_update_malformed_cron_precedes_launchd_inference() {
  local cron_file="$TMP/autoupdate-malformed-launchd.cron"
  local before="$TMP/autoupdate-malformed-launchd.before"
  local project="$TMP/autoupdate-malformed-launchd-update"
  local receipt="$TMP/autoupdate-malformed-launchd-receipt.json"
  local update_home="$TMP/autoupdate-malformed-launchd-home"
  local out="$TMP/autoupdate-malformed-launchd.out"

  printf '%s\n%s\n' '# oh-my-setting autoupdate:begin' \
    '0 0 * * * keep-this-unrelated-job' > "$cron_file"
  cp "$cron_file" "$before"
  git clone -q "$ROOT" "$project"
  cp "$ROOT/scripts/update.sh" "$project/scripts/update.sh"
  cp "$ROOT/scripts/lib/install-contract.sh" \
    "$project/scripts/lib/install-contract.sh"
  mkdir -p "$update_home/Library/LaunchAgents"
  : > "$update_home/Library/LaunchAgents/com.oh-my-setting.autoupdate.plist"
  python3 - "$receipt" "$project" <<'PY'
import json
import sys

json.dump({
    "schema": 1,
    "source_root": sys.argv[2],
    "commit": "0123456789abcdef0123456789abcdef01234567",
    "channel": "main",
    "version": "0.3.0",
    "installed_at": "2026-07-12T00:00:00Z",
    "plugin": {"name": "oh-my-setting", "version": "0.1.0", "sha256": "x" * 64},
}, open(sys.argv[1], "w", encoding="utf-8"))
PY
  if HOME="$update_home" XDG_CONFIG_HOME="$update_home/.config" \
    OMS_INSTALL_RECEIPT="$receipt" \
    OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    PATH="/usr/bin:/bin" "$project/scripts/update.sh" --check >"$out" 2>&1; then
    fail "launchd masked malformed cron during legacy component inference"
  fi
  grep -Fq 'refusing to infer the legacy component profile' "$out" ||
    fail "update malformed refusal was not actionable: $(cat "$out")"
  cmp -s "$before" "$cron_file" ||
    fail "update changed malformed cron bytes when launchd was present"
}

# An out-of-band `oms auto-update install` used to leave the receipt saying
# auto_update=false, so the next `oms update` reconciled components from the
# receipt and silently uninstalled the timer it had just been asked to keep.
test_autoupdate_trigger_records_receipt_component() {
  local cron_file="$TMP/autoupdate-receipt.cron"
  local receipt="$TMP/autoupdate-receipt.json"
  local out

  python3 - "$receipt" "$ROOT" <<'PY'
import json, sys
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({
        "schema": 2,
        "source_root": sys.argv[2],
        "commit": "0123456789abcdef0123456789abcdef01234567",
        "channel": "main",
        "version": "0.3.0",
        "profile": "custom",
        "ref": "main",
        "previous_commit": "",
        "link_mode": "symlink",
        "installed_at": "2026-07-12T00:00:00Z",
        "components": {
            "tools": False,
            "claude_hooks": True,
            "codex_plugin": False,
            "auto_update": False,
            "machine_snapshot": False,
            "slurm_snapshot": False,
        },
        "managed_targets": [".local/bin/oms"],
        "plugin": {"name": "oh-my-setting", "version": "0.1.0", "sha256": "test"},
    }, handle)
PY

  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron >/dev/null
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is True, row["components"]
assert row["component_modes"]["auto_update"] == "apply", row
assert row["components"]["claude_hooks"] is True, row["components"]
assert row["version"] == "0.3.0", row
PY

  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" >/dev/null
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is False, row["components"]
PY

  # --check-only records the chosen mode so a later update reinstalls check,
  # not the apply default; disabling keeps the mode for the next enable.
  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron --check-only >/dev/null
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is True, row["components"]
assert row["component_modes"]["auto_update"] == "check", row
PY
  OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/uninstall-autoupdate.sh" >/dev/null
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is False, row["components"]
assert row["component_modes"]["auto_update"] == "check", row
PY

  # Dry-run previews the receipt write without performing it.
  out="$(OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron --dry-run)"
  contains "$out" 'would record auto_update=true' ||
    fail "dry-run should preview the receipt write: $out"
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is False, row["components"]
PY

  # A checkout that does not own the receipt must not flip the flag.
  python3 - "$receipt" "$TMP" <<'PY'
import json, sys
with open(sys.argv[1], encoding="utf-8") as handle:
    row = json.load(handle)
row["source_root"] = sys.argv[2]
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump(row, handle)
PY
  out="$(OMS_INSTALL_RECEIPT="$receipt" OH_MY_SETTING_AUTO_UPDATE_CRON_FILE="$cron_file" \
    "$ROOT/scripts/install-autoupdate.sh" --method cron 2>&1)"
  contains "$out" 'not recorded' ||
    fail "foreign-owner install should note the skipped receipt write: $out"
  python3 - "$receipt" <<'PY'
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["components"]["auto_update"] is False, row["components"]
PY
}

# update.sh reinstalls the trigger on every run; before the mode lived in the
# receipt's component_modes, that reinstall silently downgraded an apply-mode
# timer to the check default.
test_update_preserves_auto_update_mode() {
  local project="$TMP/update-autoupdate-mode"
  local bin="$project/bin"
  local receipt="$TMP/update-autoupdate-mode-receipt.json"
  local marker="$project/mode-marker"
  local branch

  make_committed_repo "$project"
  mkdir -p "$project/scripts/lib" "$bin"
  cp "$ROOT/scripts/update.sh" "$project/scripts/update.sh"
  cp "$ROOT/scripts/lib/install-contract.sh" "$project/scripts/lib/install-contract.sh"
  cp "$ROOT/scripts/lib/install-lifecycle-lock.sh" "$project/scripts/lib/install-lifecycle-lock.sh"
  cp "$ROOT/scripts/lib/canonical-sync.sh" "$project/scripts/lib/canonical-sync.sh"
  cp "$ROOT/scripts/lib/file-lock.sh" "$project/scripts/lib/file-lock.sh"
  cp "$ROOT/scripts/lib/harness-residue.sh" "$project/scripts/lib/harness-residue.sh"
  cp "$ROOT/scripts/lib/oms-common.sh" "$project/scripts/lib/oms-common.sh"
  cp "$ROOT/scripts/lib/poll.sh" "$project/scripts/lib/poll.sh"
  for script in link doctor uninstall-autoupdate install-tools install-claude-hooks install-mcp install-agy-plugin; do
    printf '#!/usr/bin/env bash\nexit 0\n' > "$project/scripts/$script.sh"
    chmod +x "$project/scripts/$script.sh"
  done
  cat > "$project/scripts/install-autoupdate.sh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "${OH_MY_SETTING_AUTO_UPDATE_MODE:-unset}" > "$OMS_TEST_MODE_MARKER"
EOF
  chmod +x "$project/scripts/install-autoupdate.sh"
  cat > "$bin/git" <<'EOF'
#!/usr/bin/env bash
case "$*" in
  *' pull --ff-only') exit 0 ;;
esac
exec /usr/bin/git "$@"
EOF
  chmod +x "$bin/git"
  git -C "$project" add scripts bin
  git -C "$project" commit -qm "test: auto-update mode fixture"
  branch="$(git -C "$project" symbolic-ref --short HEAD)"
  git -C "$project" remote add origin "$project"
  git -C "$project" fetch -q origin "$branch"
  git -C "$project" branch --set-upstream-to="origin/$branch" "$branch" >/dev/null
  python3 - "$receipt" "$project" <<'PY'
import json, sys
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({
        "schema": 2,
        "source_root": sys.argv[2],
        "commit": "0123456789abcdef0123456789abcdef01234567",
        "channel": "main",
        "version": "0.3.0",
        "profile": "custom",
        "ref": "main",
        "previous_commit": "",
        "link_mode": "symlink",
        "installed_at": "2026-07-12T00:00:00Z",
        "components": {
            "tools": False,
            "claude_hooks": False,
            "codex_plugin": False,
            "auto_update": True,
            "machine_snapshot": False,
            "slurm_snapshot": False,
        },
        "component_modes": {
            "auto_update": "apply",
            "machine_snapshot": "0",
            "slurm_snapshot": "0",
        },
        "managed_targets": [".local/bin/oms"],
        "plugin": {"name": "oh-my-setting", "version": "0.1.0", "sha256": "test"},
    }, handle)
PY

  env -u OH_MY_SETTING_AUTO_UPDATE -u OH_MY_SETTING_AUTO_UPDATE_MODE \
    PATH="$bin:/usr/bin:/bin" OMS_INSTALL_RECEIPT="$receipt" \
    OMS_TEST_MODE_MARKER="$marker" OH_MY_SETTING_CLAUDE_HOOKS=0 \
    OH_MY_SETTING_CODEX_PLUGIN=0 \
    "$project/scripts/update.sh" --no-doctor >/dev/null
  [ -f "$marker" ] || fail "update should reinstall the recorded auto-update trigger"
  grep -Fxq apply "$marker" ||
    fail "update downgraded the recorded apply mode: $(cat "$marker")"
}

test_check_parallel_fail_fast() {
  local probe="$TMP/check-parallel-fail-fast"
  mkdir -p "$probe"
  cat > "$probe/check.sh" <<'SH'
#!/usr/bin/env bash
case "$1:${3:-}" in
  --focused-only:1/8)
    touch "$PROBE/started"
    trap 'exit 143' TERM
    while :; do sleep 1; done ;;
  --focused-only:2/8)
    while [ ! -e "$PROBE/started" ]; do sleep 0.1; done
    echo 'focused failure evidence'
    exit 1 ;;
  *) touch "$PROBE/unexpected" ;;
esac
SH
  python3 - "$ROOT" "$probe" <<'PYTEST' || fail "parallel gate did not stop after the failed lane"
import os, pathlib, subprocess, sys
root, probe = sys.argv[1:]
env = dict(os.environ, PROBE=probe, OMS_CHECK_JOBS="2")
command = '. "$1/scripts/lib/check-parallel.sh"; oms_check_parallel "$2/check.sh" "$2/logs" 1'
try:
    result = subprocess.run(["bash", "-c", command, "bash", root, probe], env=env,
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                            timeout=int(os.environ.get("OMS_TEST_CALL_TIMEOUT", "120")))
except subprocess.TimeoutExpired:
    raise AssertionError("gate waited for a running lane after failure")
assert result.returncode != 0, result.stdout
assert "focused failure evidence" in result.stdout, result.stdout
assert "check: parallel gate stopped after focused-2 failed; not run: focused-1, focused-3, focused-4, focused-5, focused-6, focused-7, focused-8, smoke" in result.stdout, result.stdout
assert not (pathlib.Path(probe) / "unexpected").exists(), result.stdout
PYTEST
}

