test_check_gate_hard_fails_without_shellcheck() {
  # The gate must FAIL (not silently skip) when shellcheck is absent — the
  # exact false-confidence that hid a session of red CI.
  local out
  # Point the gate at a nonexistent shellcheck binary so it hits the
  # missing-tool path deterministically (no PATH surgery, no recursion).
  # --lint-only is passed explicitly: a gate with lint disabled has no reason to
  # look for shellcheck, and when the split was an inherited environment variable
  # CI's smoke job turned this test into a full recursive gate run instead of the
  # fast failure the line above promises.
  out="$(OMS_SHELLCHECK_BIN=__oms_absent_shellcheck__ \
    "$ROOT/scripts/check.sh" --lint-only 2>&1)" && \
    fail "check.sh must exit nonzero when shellcheck is missing"
  contains "$out" "shellcheck is not installed" ||
    fail "check.sh missing-tool message absent: $out"
}

# smoke-weight: 6
test_check_gate_is_hermetic_to_hook_git_env() {
  # Git exports GIT_DIR to hooks; from a linked worktree it is absolute and
  # redirects every fixture's git calls into the enclosing checkout — a
  # pre-push from a worktree rewrote the checkout with fixture commits and
  # failed autonomy-plan-run on the enclosing tree's dirtiness. The gate
  # must drop the inherited git context before any stage runs.
  grep -Fq 'unset GIT_DIR GIT_WORK_TREE GIT_COMMON_DIR GIT_INDEX_FILE' \
    "$ROOT/scripts/check.sh" ||
    fail "check.sh must unset the inherited hook git env (GIT_DIR family)"
  # A native room is invoker state too; a verifier must not enroll fixtures in it.
  local checker="$TMP/room-env-shellcheck"
  cat > "$checker" <<'SH'
#!/usr/bin/env bash
set -eu
[ -z "${OMS_ROOM_ID:-}" ] && [ -z "${OMS_ROOM_PARTICIPANT:-}" ] &&
  [ -z "${OMS_ROOM_REPO:-}" ] && [ -z "${OMS_ROOM_ADMITTED_PARTICIPANT:-}" ] &&
  [ -z "${OMS_PANEL_CONTINUATION:-}" ] && [ -z "${OMS_PANEL_ACCEPT_RECORD_JSON:-}" ] &&
  [ -z "${OMS_HARNESS_DELEGATE_DEPTH:-}" ] && [ -z "${OMS_PEER_TIMEOUT:-}" ] &&
  [ -z "${OMS_PEER_PRINT_TIMEOUT:-}" ] && [ -z "${OMS_WORKER_GUARD_STRICT:-}" ] &&
  [ -z "${OMS_WORKER_GUARD_OFF:-}" ]
SH
  chmod +x "$checker"
  OMS_ROOM_ID=outer-room OMS_ROOM_PARTICIPANT=outer-main OMS_ROOM_REPO="$TMP/outer" \
    OMS_ROOM_ADMITTED_PARTICIPANT=outer-main OMS_HARNESS_DELEGATE_DEPTH=1 \
    OMS_PANEL_CONTINUATION=outer-continuation OMS_PANEL_ACCEPT_RECORD_JSON='{}' \
    OMS_PEER_TIMEOUT=30m OMS_PEER_PRINT_TIMEOUT=30m OMS_WORKER_GUARD_STRICT=1 \
    OMS_WORKER_GUARD_OFF=0 OMS_SHELLCHECK_BIN="$checker" OMS_LINT_JOBS_MAX=1 \
    bash "$ROOT/scripts/check.sh" --lint-only > "$TMP/room-env-gate.log" 2>&1 ||
    fail "gate leaked the invoker's room identity into fixture tools"
}

# link.sh ignored its arguments and ran. `link.sh --help` therefore relinked a
# live install and moved canonical ownership to whichever checkout was asked for
# help — the receipt names an owner, so that is a transfer, not a no-op. It
# happened during this session's own analysis, cost 78 stray backup symlinks and
# a doctor: failed, and nothing would have caught it. Every entrypoint that
# writes install state must answer --help and refuse anything else.
test_state_writing_entrypoints_reject_unknown_arguments() {
  local script
  local out

  for script in link.sh install-hooks.sh check-python.sh skill-doctor.sh; do
    out="$("$ROOT/scripts/$script" --help 2>&1)" ||
      fail "$script --help should exit 0: $out"
    contains "$out" "usage: $script" ||
      fail "$script --help should print its usage: $out"
    if out="$("$ROOT/scripts/$script" --definitely-not-a-flag 2>&1)"; then
      fail "$script must refuse an unknown argument instead of running: $out"
    fi
  done
}

# check.sh exits at the first failing stage. CI runs lint and tests as separate
# jobs so one shellcheck nit cannot suppress every test result, which only
# works if each half can run without the other.
# smoke-weight: 5
test_check_gate_splits_lint_from_tests() {
  local out
  local shellcheck_stub="$TMP/check-split-shellcheck"

  # This is a mode-routing contract, not a second shellcheck correctness run.
  # The top-level lint gate checks every file; repeating the real linter here
  # added roughly 45 seconds to one scripts-smoke shard with no new evidence.
  cat > "$shellcheck_stub" <<'EOF'
#!/usr/bin/env bash
exit 0
EOF
  chmod +x "$shellcheck_stub"

  out="$(cd "$ROOT" && OMS_SHELLCHECK_BIN="$shellcheck_stub" \
    bash scripts/check.sh --lint-only 2>&1)" ||
    fail "lint-only gate should pass: $out"
  contains "$out" 'ok: shellcheck' ||
    fail "lint-only gate must run shellcheck: $out"
  contains "$out" 'check: ok (lint only)' ||
    fail "lint-only gate must say what it skipped: $out"
  if contains "$out" 'ok: context-core'; then
    fail "lint-only gate must not run the test suites: $out"
  fi

  if out="$(cd "$ROOT" && bash scripts/check.sh --no-lint --lint-only 2>&1)"; then
    fail "a gate that runs nothing must be refused: $out"
  fi
  contains "$out" 'leave nothing to run' ||
    fail "refusal must name the cause: $out"
}

# Every .sh here is linted; the Python helpers had nothing, and one of them now
# decides what the installer may delete.
# smoke-weight: 5
test_python_helpers_are_syntax_checked() {
  local out dir="$TMP/selected-python" undefined="$TMP/undefined-global.py" defined="$TMP/defined-global.py" vars_file="$TMP/vars-args.py" globals_file="$TMP/globals-write.py" pop_file="$TMP/globals-pop.py" del_file="$TMP/globals-del.py" isolated_repo="$TMP/python-skip-repo" isolated_checker isolated_operator isolated_dynamic

  out="$(cd "$ROOT" && bash scripts/check-python.sh 2>&1)" ||
    fail "python syntax gate should pass: $out"
  printf '%s' "$out" | grep >/dev/null -E 'python-syntax: ok \([0-9]+ files([;)]|$)' ||
    fail "python syntax gate must report what it checked: $out"
  mkdir -p "$dir"
  printf 'try:\n  valid = 1\nexcept* Exception:\n  valid = 2\n' > "$dir/good.py"
  printf 'invalid = (\n' > "$dir/bad.py"
  out="$(bash "$ROOT/scripts/check-python.sh" "$dir/good.py")" || fail "selected valid Python failed"
  [ "$out" = 'python-syntax: ok (1 files)' ] || fail "syntax gate inspected unrelated files: $out"
  if bash "$ROOT/scripts/check-python.sh" "$dir/bad.py" >/dev/null 2>&1; then
    fail "invalid selected Python passed"
  fi
  if bash "$ROOT/scripts/check-python.sh" "$dir/missing.py" >/dev/null 2>&1; then
    fail "missing selected Python passed"
  fi
  cat > "$undefined" <<'EOF'
def first():
  hidden = 1

def second():
  return hidden
EOF
  if out="$(bash "$ROOT/scripts/check-python.sh" "$undefined" 2>&1)"; then
    fail "function-local name used by another function passed"
  fi
  contains "$out" "$undefined:5: undefined name hidden" ||
    fail "undefined-name diagnostic must identify the read line: $out"
  cat > "$defined" <<'EOF'
def read_before_writer():
  def nested_reader():
    return written
  return written

def write_global():
  global written
  written = len(())

def read_later_before_definition():
  return later

later = 1
EOF
  bash "$ROOT/scripts/check-python.sh" "$defined" >/dev/null ||
    fail "builtin, later module binding, nested reader, or later global write was rejected"
  cat > "$vars_file" <<'EOF'
def inspect_args(args):
  options = vars(args)
  return absent_name
EOF
  if out="$(bash "$ROOT/scripts/check-python.sh" "$vars_file" 2>&1)"; then
    fail "vars(args) must not disable undefined-name checks"
  fi
  contains "$out" "$vars_file:3: undefined name absent_name" ||
    fail "vars(args) undefined name diagnostic missing: $out"
  cat > "$globals_file" <<'EOF'
globals()['provided_later'] = 1
def read_dynamic_name():
  return external_name
EOF
  out="$(bash "$ROOT/scripts/check-python.sh" "$globals_file" 2>&1)" ||
    fail "dynamic module namespace write should skip undefined-name check"
  contains "$out" 'undefined-name rule skipped 1: globals-write.py' ||
    fail "dynamic module must be named in skip summary: $out"
  cat > "$pop_file" <<'EOF'
globals().pop("optional_name", None)
def read_missing():
  return absent_after_pop
EOF
  if out="$(bash "$ROOT/scripts/check-python.sh" "$pop_file" 2>&1)"; then
    fail "globals().pop must not disable undefined-name checks"
  fi
  contains "$out" "$pop_file:3: undefined name absent_after_pop" ||
    fail "globals().pop must preserve undefined-name diagnostic: $out"
  cat > "$del_file" <<'EOF'
del globals()['optional_name']
def read_missing():
  return absent_after_del
EOF
  if out="$(bash "$ROOT/scripts/check-python.sh" "$del_file" 2>&1)"; then
    fail "del globals()['name'] must not disable undefined-name checks"
  fi
  contains "$out" "$del_file:3: undefined name absent_after_del" ||
    fail "del globals()['name'] must preserve undefined-name diagnostic: $out"
  # Newer interpreters accept what the 3.11 floor refuses: 19 context managers
  # around a try whose handler body is the 21st block.
  python3 -c 'print("def deep():\n    with " + ", ".join(["open(0)"] * 19) + ":\n        try:\n            pass\n        except ValueError:\n            pass")' > "$del_file"
  if out="$(bash "$ROOT/scripts/check-python.sh" "$del_file" 2>&1)"; then
    fail "the syntax gate must refuse nesting past the Python 3.11 block limit"
  fi
  contains "$out" "more than 20 statically nested blocks" || fail "nesting diagnostic missing: $out"

  isolated_checker="$isolated_repo/scripts/check-python.sh"
  isolated_operator="$isolated_repo/tests/operator/fixture.py"
  isolated_dynamic="$isolated_repo/tests/dynamic.py"
  mkdir -p "$isolated_repo/scripts" "$isolated_repo/tests/operator"
  cp "$ROOT/scripts/check-python.sh" "$isolated_checker"
  mkdir -p "$isolated_repo/scripts/lib"
  cp "$ROOT/scripts/lib/python-runtime.sh" "$isolated_repo/scripts/lib/"
  printf 'def fixture():\n  return sibling_binding\n' > "$isolated_operator"
  cat > "$isolated_dynamic" <<'EOF'
globals()['provided_later'] = 1
def read_dynamic_name():
  return external_name
EOF
  out="$(bash "$isolated_checker" "$isolated_operator" "$isolated_dynamic" 2>&1)" ||
    fail "isolated operator fixture should be syntax checked with exemption: $out"
  [ "$out" = 'python-syntax: ok (2 files; undefined-name rule skipped 2: dynamic.py, tests/operator/* (1))' ] ||
    fail "dynamic and operator skips must be summarized together: $out"
}

test_ci_status_reports_conclusion() {
  local d="$TMP/ci-status" original_dir="$PWD" out sha
  mkdir -p "$d/bin"
  # Match a tracked fixture HEAD; the caller's checkout must not choose the verdict.
  make_committed_repo "$d/repo"
  git -C "$d/repo" config branch.main.remote .
  git -C "$d/repo" config branch.main.merge refs/heads/main
  sha="$(git -C "$d/repo" rev-parse HEAD)"
  cd "$d/repo"
  # Stub gh: a failed run for HEAD -> ci-status must exit nonzero.
  cat > "$d/bin/gh" <<EOF
#!/usr/bin/env bash
echo '[{"status":"completed","conclusion":"failure","workflowName":"test","headSha":"$sha","url":"http://x"}]'
EOF
  chmod +x "$d/bin/gh"
  out="$(OMS_GH_BIN="$d/bin/gh" "$ROOT/scripts/ci-status.sh" main 2>&1)" && \
    fail "ci-status must exit nonzero on a failed run"
  contains "$out" "failure" || fail "ci-status missing conclusion: $out"

  # A successful run for HEAD -> exit 0.
  cat > "$d/bin/gh" <<EOF
#!/usr/bin/env bash
echo '[{"status":"completed","conclusion":"success","workflowName":"test","headSha":"$sha","url":"http://x"}]'
EOF
  OMS_GH_BIN="$d/bin/gh" "$ROOT/scripts/ci-status.sh" main >/dev/null 2>&1 ||
    fail "ci-status should exit 0 on a successful run"

  # Missing gh -> exit 2 (clear, not a silent pass).
  if OMS_GH_BIN=__oms_absent_gh__ "$ROOT/scripts/ci-status.sh" main >/dev/null 2>&1; then
    fail "ci-status should fail when gh is absent"
  fi

  # History is read-only, bounded, and aggregates jobs/tests once per run.
  cat > "$d/bin/gh" <<'EOF'
#!/usr/bin/env bash
case "$*" in
  *"run list"*)
    echo '[{"databaseId":11,"headSha":"abcdef0123456789","status":"completed","conclusion":"failure","createdAt":"2026-10-14T00:00:00Z","updatedAt":"2026-10-14T00:35:00Z"},{"databaseId":12,"headSha":"123456789abcdeff","status":"completed","conclusion":"failure","createdAt":"2026-10-13T00:00:00Z","updatedAt":"2026-10-13T00:20:00Z"},{"databaseId":13,"headSha":"fedcba9876543210","status":"completed","conclusion":"success","createdAt":"2026-10-12T00:00:00Z","updatedAt":"2026-10-12T00:10:00Z"}]'
    ;;
  *"run view 11"*|*"run view 12"*)
    printf 'Linux smoke\tcheck\tcheck: scripts-smoke.test_tmux_flake FAILED\n'
    printf 'Linux smoke\tcheck\tcheck: scripts-smoke.test_once FAILED\n'
    ;;
  *) exit 1 ;;
esac
EOF
  chmod +x "$d/bin/gh"
  out="$(OMS_GH_BIN="$d/bin/gh" "$ROOT/scripts/ci-status.sh" history --limit 2 main)" ||
    fail "ci-status history failed: $out"
  contains "$out" "abcdef012345  failure  35m" || fail "history missing run duration: $out"
  contains "$out" "Linux smoke: 2" || fail "history missing ranked job count: $out"
  contains "$out" "scripts-smoke.test_tmux_flake: 2 — quarantine candidate" ||
    fail "history missing repeated-test quarantine candidate: $out"
  contains "$out" "scripts-smoke.test_once: 2 — quarantine candidate" ||
    fail "history missing parsed failed test: $out"
  if OMS_GH_BIN=__oms_absent_gh__ "$ROOT/scripts/ci-status.sh" history >/dev/null 2>&1; then
    fail "ci-status history should fail when gh is absent"
  else
    [ "$?" -eq 2 ] || fail "ci-status history missing-gh exit must be 2"
  fi

  # Protection reads whether CI's gate job is a required check on the
  # destination. It has three answers and one unreadable source makes it
  # unknown, never absent: proven exits 0, absent 1, unknown 2.
  local calls="$d/protection-calls" rc
  cat > "$d/bin/gh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$PROTECTION_CALLS"
path=""; for path in "$@"; do :; done
unprotected() { echo '{"message":"Branch not protected","documentation_url":"https://docs.example/x","status":"404"}'; exit 1; }
case "${PROTECTION_CASE}:$path" in
  hang:*) exec sleep 30 ;;
  garbage:*) echo '<html>proxy error</html>'; exit 0 ;;
  *:'repos/{owner}/{repo}') echo '{"default_branch":"trunk","private":false}' ;;
  badbytes:*/protection) printf '\377\376'; exit 0 ;;
  malformed:*/protection) echo '{"required_status_checks":{"contexts":"gate","checks":5},"allow_force_pushes":{"enabled":true}}' ;;
  zero-read:*/protection) echo '{"required_pull_request_reviews":{"required_approving_review_count":0}}' ;;
  split-gate:*/rules/branches/*|zero:*/protection) echo '{"message":"Resource not accessible","status":"403"}'; exit 1 ;;
  split-rules:*/protection) echo '{"message":"Resource not accessible","status":"403"}'; exit 1 ;;
  split-rules:*/rules/branches/*|zero:*/rules/branches/*)
    echo '[{"type":"pull_request","parameters":{"required_approving_review_count":0}},{"type":"required_status_checks","parameters":{"required_status_checks":[{"context":"gate"}]}}]' ;;
  split-gate:*/protection) echo '{"required_status_checks":{"contexts":["gate"]}}' ;;
  classic-gate:*/protection)
    echo '{"required_status_checks":{"strict":true,"contexts":["lint"],"checks":[{"context":"gate","app_id":15368}]},"required_pull_request_reviews":{"dismiss_stale_reviews":true,"required_approving_review_count":1},"allow_force_pushes":{"enabled":false}}' ;;
  classic-other:*/protection)
    echo '{"required_status_checks":{"strict":false,"contexts":["lint","gateway"],"checks":[{"context":"lint","app_id":15368}]},"allow_force_pushes":{"enabled":true}}' ;;
  ruleset-gate:*/protection|unprotected:*/protection) unprotected ;;
  forbidden:*/protection)
    echo '{"message":"Resource not accessible by fixture-credential-marker","status":"403"}'; exit 1 ;;
  ruleset-gate:*/rules/branches/*)
    echo '[{"type":"deletion"},{"type":"non_fast_forward"},{"type":"pull_request","parameters":{"required_approving_review_count":2,"dismiss_stale_reviews_on_push":false}},{"type":"required_status_checks","parameters":{"required_status_checks":[{"context":"gate","integration_id":15368}]}}]' ;;
  *:*/rules/branches/*) echo '[]' ;;
  *) exit 1 ;;
esac
EOF
  chmod +x "$d/bin/gh"
  protection() {
    local mode="$1"; shift
    rc=0
    out="$(PROTECTION_CASE="$mode" PROTECTION_CALLS="$calls" OMS_GH_BIN="$d/bin/gh" \
      OMS_CI_PROTECTION_TIMEOUT=1 "$ROOT/scripts/ci-status.sh" protection "$@" 2>&1)" || rc=$?
  }
  : > "$calls"
  protection classic-gate
  [ "$rc" -eq 0 ] || fail "a required gate check should exit 0 (rc=$rc): $out"
  contains "$out" "ci-status protection [trunk]: required check 'gate' proven (branch protection)" ||
    fail "protection should prove the gate on the default branch: $out"
  contains "$out" "approving reviews required: 1" && contains "$out" "stale approvals dismissed: yes" &&
    contains "$out" "force pushes: blocked" || fail "protection missing the review and force-push facts: $out"
  protection classic-other
  [ "$rc" -eq 1 ] || fail "protection without the gate should exit 1 (rc=$rc): $out"
  contains "$out" "required check 'gate' absent (branch protection: does not require it; rulesets: does not require it)" ||
    fail "a check that merely resembles gate must not count: $out"
  contains "$out" "approving reviews required: none" && contains "$out" "force pushes: allowed" ||
    fail "protection without reviews should say so: $out"
  protection ruleset-gate release/1.x
  [ "$rc" -eq 0 ] || fail "a ruleset requiring the gate should exit 0 (rc=$rc): $out"
  contains "$out" "ci-status protection [release/1.x]: required check 'gate' proven (rulesets)" ||
    fail "an active ruleset should prove the gate: $out"
  contains "$out" "approving reviews required: 2" && contains "$out" "stale approvals dismissed: no" &&
    contains "$out" "force pushes: blocked" || fail "ruleset facts missing: $out"
  protection unprotected main
  [ "$rc" -eq 1 ] || fail "an unprotected branch should exit 1 (rc=$rc): $out"
  contains "$out" "required check 'gate' absent (branch protection: not protected; rulesets: does not require it)" ||
    fail "an unprotected branch with no ruleset is absent: $out"
  contains "$out" "a workflow alone does not protect the branch" || fail "absent should say what to keep: $out"
  # No permission to read protection cannot tell "unprotected" from "hidden".
  protection forbidden main
  [ "$rc" -eq 2 ] || fail "an unreadable protection answer should exit 2 (rc=$rc): $out"
  contains "$out" "required check 'gate' unknown (branch protection: HTTP 403; rulesets: does not require it)" ||
    fail "a refused read is unknown, not absent: $out"
  contains "$out" "force pushes: unknown" && contains "$out" "unknown is not a pass" ||
    fail "unknown facts should stay unknown: $out"
  ! contains "$out" "fixture-credential-marker" && ! contains "$out" "absent" ||
    fail "protection must not print the API body or read a refusal as absent: $out"
  # The gate read from one source is not a pass while the other is unreadable.
  for mode in split-gate split-rules; do
    protection "$mode" main
    [ "$rc" -eq 2 ] && contains "$out" "required check 'gate' unknown (" && ! contains "$out" "proven" ||
      fail "$mode: an unread source must keep a found gate unknown (rc=$rc): $out"
  done
  contains "$out" "branch protection: HTTP 403; rulesets: requires it" ||
    fail "the source that requires the gate should be named: $out"
  # A zero approval count is no requirement: unknown while a source is unread, none once all are read.
  protection zero main
  contains "$out" "approving reviews required: unknown" || fail "zero approvals with an unread source must be unknown: $out"
  protection zero-read main
  contains "$out" "approving reviews required: none" || fail "zero approvals with every source read is none: $out"
  # Undecodable bytes and wrongly typed lists are unknown or absent, never a crash exit 1 read as absent.
  protection badbytes main
  [ "$rc" -eq 2 ] && ! contains "$out" "Traceback" || fail "non-UTF-8 output must be unknown (rc=$rc): $out"
  protection malformed main
  [ "$rc" -eq 1 ] && ! contains "$out" "Traceback" && contains "$out" "required check 'gate' absent" ||
    fail "malformed list fields must not crash or count (rc=$rc): $out"
  protection garbage main
  [ "$rc" -eq 2 ] || fail "an unreadable answer should exit 2 (rc=$rc): $out"
  contains "$out" "unknown (branch protection: unreadable answer; rulesets: unreadable answer)" && ! contains "$out" "proxy error" ||
    fail "a non-JSON answer is unknown and stays unprinted: $out"
  protection garbage
  [ "$rc" -eq 2 ] && contains "$out" "required check 'gate' unknown (default branch: unreadable answer)" ||
    fail "an unreadable default branch is unknown (rc=$rc): $out"
  protection hang
  [ "$rc" -eq 2 ] && contains "$out" "required check 'gate' unknown (default branch: timed out)" ||
    fail "a lookup past its budget is unknown (rc=$rc): $out"
  # Every request is an explicit GET; nothing else is asked of gh, and no ledger appears.
  [ "$(wc -l < "$calls" | tr -d ' ')" -eq 28 ] || fail "unexpected number of protection lookups: $(cat "$calls")"
  ! grep -Fv -e 'api --method GET -H Accept: application/vnd.github+json repos/{owner}/{repo}' "$calls" ||
    fail "protection must only issue GET requests for this repository"
  ! grep -Eq -e '-X|--input|-f |-F |--field' "$calls" || fail "protection must not send request fields"
  rc=0
  out="$(OMS_GH_BIN=__oms_absent_gh__ "$ROOT/scripts/ci-status.sh" protection main 2>&1)" || rc=$?
  [ "$rc" -eq 2 ] && contains "$out" "required check 'gate' unknown (gh CLI not installed)" ||
    fail "protection without gh is unknown (rc=$rc): $out"

  # Triage explains a red run without touching it: failing jobs and steps, a
  # bounded scanned log tail, and each job against the base branch. A read that
  # fails is unknown (exit 2), never "nothing red".
  local tcalls="$d/triage-calls"
  cat > "$d/bin/gh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$TRIAGE_CALLS"
run() { printf '{"databaseId":%s,"status":"%s","conclusion":"%s","workflowName":"CI","headSha":"%s","url":"http://ci/%s"}' "$1" "$2" "$3" "$4" "$1"; }
case "$TRIAGE_CASE:$*" in
  down:*) exit 1 ;;
  *:"api --method GET repos/{owner}/{repo}")
    [ "$TRIAGE_CASE" != nobase ] || exit 1
    echo '{"default_branch":"trunk"}' ;;
  green:"run list --branch feature"*) echo "[$(run 31 completed success aaaa111122223333)]" ;;
  pending:"run list --branch feature"*) echo "[$(run 32 in_progress "" aaaa111122223333)]" ;;
  *:"run list --branch feature"*)
    echo "[$(run 21 completed failure aaaa111122223333),$(run 20 completed success 9999000011112222)]" ;;
  *:"run list --branch trunk"*) echo "[$(run 10 completed failure bbbb111122223333)]" ;;
  nojobs:"run view 21 --json jobs") echo 'proxy error' ;;
  *:"run view 21 --json jobs")
    printf '%s' '{"jobs":[{"name":"lint","conclusion":"failure","steps":[{"name":"Set up","conclusion":"success"},{"name":"shellcheck","conclusion":"failure"}]},'
    printf '%s' '{"name":"smoke (1/4)","conclusion":"failure","steps":[{"name":"smoke shard","conclusion":"failure"}]},'
    printf '%s' '{"name":"leaky\u001b[31m job","conclusion":"failure","steps":"oops"},'
    printf '%s\n' '{"name":"docs","conclusion":"success"}]}' ;;
  *:"run view 10 --json jobs")
    echo '{"jobs":[{"name":"lint","conclusion":"success"},{"name":"smoke (1/4)","conclusion":"failure"}]}' ;;
  slowlog:"run view 21 --log-failed") sleep 5 ;;
  *:"run view 21 --log-failed")
    i=0; while [ "$i" -lt 40 ]; do printf 'lint\tshellcheck\t2026-11-10T00:00:00.0000000Z early line %s\n' "$i"; i=$((i + 1)); done
    printf 'lint\tshellcheck\t2026-11-10T00:00:01.0000000Z \033[31mSC2034 (warning): unused appears unused\033[0m\n'
    printf 'smoke (1/4)\tsmoke shard\t2026-11-10T00:00:02.0000000Z check: scripts-smoke.test_alpha FAILED\n'
    printf 'leaky\033[31m job\tstep\t2026-11-10T00:00:03.0000000Z pass''word=hunter2hunter2-fixture\n' ;;
  *) exit 1 ;;
esac
EOF
  chmod +x "$d/bin/gh"
  triage() {  # MODE [ARGS...] -> $out, $rc
    local mode="$1"
    shift
    rc=0
    out="$(TRIAGE_CASE="$mode" TRIAGE_CALLS="$tcalls" OMS_GH_BIN="$d/bin/gh" OMS_CI_TRIAGE_TIMEOUT=2 \
      "$ROOT/scripts/ci-status.sh" triage "$@" 2>&1)" || rc=$?
  }
  : > "$tcalls"
  triage red feature
  [ "$rc" -eq 1 ] || fail "a triaged red run should exit 1 (rc=$rc): $out"
  contains "$out" "ci-status triage [feature]: failure on aaaa11112222: 3 failing jobs  http://ci/21" ||
    fail "triage should name the red run: $out"
  contains "$out" "compared with: trunk bbbb11112222" || fail "triage should name the base run: $out"
  contains "$out" "- job: lint"$'\n'"  base: green on base (regression candidate)"$'\n'"  failed step: shellcheck" ||
    fail "a job green on base is a regression candidate with its failed step: $out"
  contains "$out" "- job: smoke (1/4)"$'\n'"  base: also red on base (preexisting)" ||
    fail "a job red on base is preexisting: $out"
  contains "$out" "failed checks: scripts-smoke.test_alpha" || fail "triage should name the failed check: $out"
  # The tail is the end of the log, without timestamps or colour codes, and bounded.
  contains "$out" "    | SC2034 (warning): unused appears unused" && contains "$out" "log tail (last 25 lines):" &&
    contains "$out" "    | early line 39" && ! contains "$out" "early line 15" ||
    fail "the log excerpt should be the cleaned last 25 lines: $out"
  # A job the base run does not have is unknown; a sensitive-looking tail and control bytes never print.
  contains "$out" "- job: leaky?[31m job"$'\n'"  base: unknown (job not in the base run)" &&
    contains "$out" "  log: withheld (sensitive-looking content)" || fail "an unsafe job should stay unprinted: $out"
  ! contains "$out" "hunter2" && ! contains "$out" $'\033' && ! contains "$out" "Traceback" ||
    fail "triage leaked log content or control bytes: $out"
  contains "$out" "not verification evidence; nothing was re-run, retried, pushed or recorded" ||
    fail "the brief should say what it is: $out"
  triage green feature
  [ "$rc" -eq 0 ] && contains "$out" "ci-status triage [feature]: nothing red on aaaa11112222 (1 completed run)" ||
    fail "a green head has nothing to triage (rc=$rc): $out"
  # --sha picks that commit's run on the branch; one the listing does not hold is unknown.
  triage red --sha 9999000 feature
  [ "$rc" -eq 0 ] && contains "$out" "nothing red on 999900001111" || fail "--sha should select that commit (rc=$rc): $out"
  triage red --sha deadbeef feature
  [ "$rc" -eq 2 ] && contains "$out" "unknown (deadbeef has no run among the branch's newest 2)" ||
    fail "a commit without a listed run is unknown (rc=$rc): $out"
  triage pending feature
  [ "$rc" -eq 2 ] && contains "$out" "unknown (no completed run on this branch)" ||
    fail "an unfinished run is unknown, not green (rc=$rc): $out"
  triage down feature
  [ "$rc" -eq 2 ] && contains "$out" "unknown (run list: gh not authenticated, unreachable or unreadable)" &&
    contains "$out" "unknown is not a pass" || fail "an unreadable run list is unknown (rc=$rc): $out"
  triage nojobs feature
  [ "$rc" -eq 2 ] && contains "$out" "unknown (job list unreadable)" && ! contains "$out" "proxy error" ||
    fail "an unreadable job list is unknown and stays unprinted (rc=$rc): $out"
  # An unreadable base or a log past its budget costs that part only.
  triage nobase feature
  [ "$rc" -eq 1 ] && contains "$out" "compared with: unknown (base branch unreadable)" &&
    contains "$out" "- job: lint"$'\n'"  base: unknown" || fail "an unread base leaves the comparison unknown (rc=$rc): $out"
  triage slowlog feature
  [ "$rc" -eq 1 ] && contains "$out" "log: not downloaded (gh could not read it in time)" ||
    fail "a log past its budget is reported, not waited for (rc=$rc): $out"
  # Only reads were asked of gh, and nothing was written beside the repository.
  ! grep -Ev -e '^(run list --branch [a-z]+ --limit 20 --json |run view [0-9]+ (--json jobs|--log-failed)$|api --method GET repos/\{owner\}/\{repo\}$)' "$tcalls" ||
    fail "triage must only list runs, view jobs and logs, and read the repository"
  rc=0
  out="$(OMS_GH_BIN=__oms_absent_gh__ "$ROOT/scripts/ci-status.sh" triage feature 2>&1)" || rc=$?
  [ "$rc" -eq 2 ] && contains "$out" "ci-status triage: unknown (gh CLI not installed)" ||
    fail "triage without gh is unknown (rc=$rc): $out"
  rc=0
  out="$(OMS_GH_BIN="$d/bin/gh" "$ROOT/scripts/ci-status.sh" --sha abcdef01 main 2>&1)" || rc=$?
  [ "$rc" -eq 2 ] && contains "$out" "--sha is only read by triage" || fail "--sha outside triage must be refused (rc=$rc): $out"
  cd "$original_dir"
}

test_install_hooks_writes_pre_push() {
  local repo="$TMP/install-hooks"
  mkdir -p "$repo/scripts"
  git -C "$repo" init -b main >/dev/null
  cp "$ROOT/scripts/install-hooks.sh" "$repo/scripts/install-hooks.sh"
  ( cd "$repo" && bash scripts/install-hooks.sh >/dev/null ) || fail "install-hooks failed"
  [ -x "$repo/.git/hooks/pre-push" ] || fail "pre-push hook not installed/executable"
  grep -Fq 'scripts/pre-push-check.sh" --full' "$repo/.git/hooks/pre-push" || fail "hook does not select the full gate"

  ( cd "$repo" && bash scripts/install-hooks.sh --quick >/dev/null ) ||
    fail "install-hooks --quick failed"
  grep -Fq 'scripts/pre-push-check.sh' "$repo/.git/hooks/pre-push" ||
    fail "quick hook does not route through pre-push-check.sh"
  grep -Fq 'risk-based CI gate' "$repo/.git/hooks/pre-push" ||
    fail "quick hook must say that its local result is partial"

  # --quick names the read-only probe and stays offline; --check-protection
  # runs the probe once and installs only on proven (exit 0).
  local probe="$TMP/install-hooks-probe.sh" calls="$TMP/install-hooks-probe.calls" out rc=0
  cat > "$probe" <<'EOF'
#!/usr/bin/env bash
echo "$*" >> "$PROBE_CALLS"
case "$PROBE_CASE" in
  proven) echo "ci-status protection [main]: required check 'gate' proven (branch protection)"; echo "  extra fact"; exit 0 ;;
  absent) echo "ci-status protection [main]: required check 'gate' absent (branch protection: not protected)"; exit 1 ;;
  *) echo "ci-status protection: required check 'gate' unknown (gh CLI not installed)"; exit 2 ;;
esac
EOF
  chmod +x "$probe"
  : > "$calls"
  out="$(cd "$repo" && PROBE_CASE=proven PROBE_CALLS="$calls" OMS_CI_STATUS_BIN="$probe" bash scripts/install-hooks.sh --quick 2>&1)" ||
    fail "--quick without the flag must still install: $out"
  contains "$out" "oms ci-status protection" || fail "--quick must print the probe command: $out"
  [ ! -s "$calls" ] || fail "--quick without --check-protection must not run the probe"
  ( cd "$repo" && bash scripts/install-hooks.sh >/dev/null ) # back to the full hook
  for mode in absent unknown; do
    rc=0
    out="$(cd "$repo" && PROBE_CASE="$mode" PROBE_CALLS="$calls" OMS_CI_STATUS_BIN="$probe" \
      bash scripts/install-hooks.sh --quick --check-protection 2>&1)" || rc=$?
    [ "$rc" -eq 1 ] || fail "$mode must refuse the quick hook (rc=$rc): $out"
    contains "$out" "required check 'gate'" && contains "$out" "quick hook not installed" ||
      fail "$mode refusal must show the probe line: $out"
    grep -Fq 'scripts/pre-push-check.sh" --full' "$repo/.git/hooks/pre-push" ||
      fail "$mode refusal must leave the full hook in place"
  done
  out="$(cd "$repo" && PROBE_CASE=proven PROBE_CALLS="$calls" OMS_CI_STATUS_BIN="$probe" \
    bash scripts/install-hooks.sh --quick --check-protection 2>&1)" || fail "proven must install: $out"
  contains "$out" "'gate' proven" || fail "proven line missing: $out"
  grep -Fq 'risk-based CI gate' "$repo/.git/hooks/pre-push" || fail "proven must install the quick hook"
  [ "$(wc -l < "$calls" | tr -d ' ')" -eq 3 ] || fail "probe must run once per request: $(cat "$calls")"
  ( cd "$repo" && bash scripts/install-hooks.sh --check-protection >/dev/null 2>&1 ) &&
    fail "--check-protection without --quick must be refused"

  git -C "$repo" add scripts
  git -C "$repo" -c user.email=test@example.com -c user.name=Test commit -qm fixture
  git -C "$repo" worktree add --detach "$TMP/install-hooks-linked" >/dev/null
  (cd "$TMP/install-hooks-linked" && bash scripts/install-hooks.sh >/dev/null) ||
    fail "install-hooks must work from a linked worktree"
  grep -Fq 'scripts/pre-push-check.sh" --full' "$repo/.git/hooks/pre-push" ||
    fail "linked checkout must install the shared full hook"
}

test_pre_push_quick_gate_uses_the_exact_push_range() {
  local repo="$TMP/pre-push-quick"
  local first second zero

  mkdir -p "$repo/scripts"
  git -C "$repo" init -b main >/dev/null
  cp "$ROOT/scripts/pre-push-check.sh" "$repo/scripts/pre-push-check.sh"
  cat > "$repo/scripts/check.sh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" > "$OMS_TEST_CHECK_ARGS"
EOF
  chmod +x "$repo/scripts/check.sh" "$repo/scripts/pre-push-check.sh"
  printf 'one\n' > "$repo/tracked.txt"
  git -C "$repo" add scripts tracked.txt
  git -C "$repo" commit -m first >/dev/null
  first="$(git -C "$repo" rev-parse HEAD)"
  printf 'two\n' > "$repo/tracked.txt"
  git -C "$repo" add tracked.txt
  git -C "$repo" commit -m second >/dev/null
  second="$(git -C "$repo" rev-parse HEAD)"

  printf 'refs/heads/main %s refs/heads/main %s\n' "$second" "$first" |
    (cd "$repo" && OMS_TEST_CHECK_ARGS="$repo/check.args" \
      bash scripts/pre-push-check.sh origin example.invalid >/dev/null)
  [ "$(cat "$repo/check.args")" = "--quick --changed-from $first --changed-to $second" ] ||
    fail "quick pre-push did not preserve the exact update range: $(cat "$repo/check.args")"

  zero=0000000000000000000000000000000000000000
  for gate_flag in "" --full; do
    rm -f "$repo/check.args"
    printf 'refs/heads/old %s refs/heads/old %s\n' "$zero" "$second" |
      (cd "$repo" && OMS_TEST_CHECK_ARGS="$repo/check.args" \
        bash scripts/pre-push-check.sh $gate_flag origin example.invalid >/dev/null)
    [ ! -e "$repo/check.args" ] || fail "a deletion-only push ran a gate (flag: ${gate_flag:-quick})"
  done

  rm -f "$repo/check.args"
  printf 'refs/heads/main %s refs/heads/main %s\nrefs/heads/old %s refs/heads/old %s\n' \
    "$second" "$first" "$zero" "$second" |
    (cd "$repo" && OMS_TEST_CHECK_ARGS="$repo/check.args" \
      bash scripts/pre-push-check.sh --full origin example.invalid >/dev/null)
  [ -e "$repo/check.args" ] || fail "a mixed deletion and update push skipped the full gate"

  rm -f "$repo/check.args"
  printf 'refs/heads/old %s refs/heads/old\n' "$zero" |
    (cd "$repo" && OMS_TEST_CHECK_ARGS="$repo/check.args" \
      bash scripts/pre-push-check.sh --full origin example.invalid >/dev/null)
  [ -e "$repo/check.args" ] || fail "a malformed deletion record skipped the full gate"

  rm -f "$repo/check.args"
  printf '' |
    (cd "$repo" && OMS_TEST_CHECK_ARGS="$repo/check.args" \
      bash scripts/pre-push-check.sh --full origin example.invalid >/dev/null)
  [ -e "$repo/check.args" ] || fail "an empty full push (zero records) skipped the full gate"
}

test_pre_push_published_tags() {
  local repo="$TMP/pre-push-tags" first second zero mode record output
  mkdir -p "$repo/scripts"
  git -C "$repo" init -b main >/dev/null
  cp "$ROOT/scripts/install-hooks.sh" "$ROOT/scripts/pre-push-check.sh" "$repo/scripts/"
  cat > "$repo/scripts/check.sh" <<'EOF'
#!/usr/bin/env bash
printf 'gate\n' > "$OMS_TEST_CHECK_MARKER"
EOF
  chmod +x "$repo/scripts/check.sh" "$repo/scripts/pre-push-check.sh"
  printf 'one\n' > "$repo/tracked"
  git -C "$repo" add .
  git -C "$repo" commit -qm first
  first="$(git -C "$repo" rev-parse HEAD)"
  git -C "$repo" update-ref refs/remotes/origin/main "$first"
  printf 'two\n' > "$repo/tracked"
  git -C "$repo" commit -qam second
  second="$(git -C "$repo" rev-parse HEAD)"
  zero=0000000000000000000000000000000000000000
  for mode in full quick; do
    if [ "$mode" = quick ]; then
      (cd "$repo" && bash scripts/install-hooks.sh --quick >/dev/null)
    else
      (cd "$repo" && bash scripts/install-hooks.sh >/dev/null)
    fi
    for record in       "refs/tags/v1 $first refs/tags/v1 $zero"       "refs/tags/v1 $first refs/tags/v1 $first"; do
      rm -f "$repo/gate"
      output="$(printf '%s\n' "$record" | (cd "$repo" && OMS_TEST_CHECK_MARKER="$repo/gate" .git/hooks/pre-push origin url))"
      [ ! -e "$repo/gate" ] || fail "$mode published tag ran gate"
      [ "$output" = 'pre-push: tag-only push of published commits; gate skipped' ] || fail "$mode skip message: $output"
    done
    for record in       "refs/tags/v2 $second refs/tags/v2 $zero"       "refs/tags/v1 $first refs/tags/v1 $second"       "refs/tags/v1 $first refs/heads/main $zero"       "refs/tags/v1 $first refs/tags/v1 malformed"       "refs/tags/v1 $first refs/tags/v1"       "refs/tags/v1 $first refs/tags/v1 $zero extra"       "refs/tags/v1 $first refs/tags/v1 $zero
refs/heads/main $second refs/heads/main $first"; do
      rm -f "$repo/gate"
      printf '%b\n' "$record" | (cd "$repo" && OMS_TEST_CHECK_MARKER="$repo/gate" .git/hooks/pre-push origin url >/dev/null 2>&1)
      [ -e "$repo/gate" ] || fail "$mode unsafe tag update skipped gate: $record"
    done
    rm -f "$repo/gate"
    printf 'refs/tags/v1 %s refs/tags/v1 %s\n' "$zero" "$first" |
      (cd "$repo" && OMS_TEST_CHECK_MARKER="$repo/gate" .git/hooks/pre-push origin url >/dev/null)
    [ ! -e "$repo/gate" ] || fail "$mode tag deletion ran gate"
  done
}

test_install_skills_detects_name_mismatch() {
  local repo="$TMP/install-skills-mismatch"

  mkdir -p "$repo/custom-skills/demo" "$repo/scripts"
  cp "$ROOT/scripts/install-skills.sh" "$repo/scripts/install-skills.sh"
  [ ! -f "$ROOT/scripts/validate-skills.py" ] || cp "$ROOT/scripts/validate-skills.py" "$repo/scripts/validate-skills.py"
  cat > "$repo/skills.manifest.json" <<'EOF'
{
  "skills": [
    {
      "name": "expected-name",
      "source": "custom-skills/demo",
      "enabled": true
    }
  ]
}
EOF
  cat > "$repo/custom-skills/demo/SKILL.md" <<'EOF'
---
name: actual-name
---
EOF

  if "$repo/scripts/install-skills.sh" >"$repo/out" 2>&1; then
    fail "install-skills should fail on manifest/SKILL.md name mismatch"
  fi
  assert_file_contains "$repo/out" "name mismatch: expected-name"

  # Project skill templates use the same validator without joining the catalog.
  printf '{"skills":[]}\n' > "$repo/skills.manifest.json"
  mkdir -p "$repo/templates/project-skills"
  mv "$repo/custom-skills/demo" "$repo/templates/project-skills/demo"
  if "$repo/scripts/install-skills.sh" > "$repo/out" 2>&1; then
    fail "project template name mismatch must fail direct validation"
  fi
  assert_file_contains "$repo/out" 'name mismatch: demo -> templates/project-skills/demo/SKILL.md'
  cat > "$repo/templates/project-skills/demo/SKILL.md" <<'EOF'
---
name: demo
description: Inspect the demo project contract using the existing source and tests.
---
Read [details](references/missing.md).
EOF
  if "$repo/scripts/install-skills.sh" > "$repo/out" 2>&1; then
    fail "project template broken reference must fail direct validation"
  fi
  assert_file_contains "$repo/out" 'missing local reference: templates/project-skills/demo/references/missing.md'
  mkdir -p "$repo/templates/project-skills/demo/references"
  printf '# Details\n' > "$repo/templates/project-skills/demo/references/missing.md"
  "$repo/scripts/install-skills.sh" > "$repo/out" 2>&1 || fail "valid project template rejected"
}

test_install_skills_detects_unlisted_and_broken_resources() {
  local repo="$TMP/install-skills-resources"

  mkdir -p "$repo/custom-skills/demo/references" "$repo/custom-skills/orphan" "$repo/scripts"
  cp "$ROOT/scripts/install-skills.sh" "$repo/scripts/install-skills.sh"
  [ ! -f "$ROOT/scripts/validate-skills.py" ] || cp "$ROOT/scripts/validate-skills.py" "$repo/scripts/validate-skills.py"
  cat > "$repo/skills.manifest.json" <<'EOF'
{"skills":[{"name":"demo","source":"custom-skills/demo","enabled":true}]}
EOF
  cat > "$repo/custom-skills/demo/SKILL.md" <<'EOF'
---
name: demo
description: Demo skill.
---
Read [missing](references/missing.md).
EOF
  cat > "$repo/custom-skills/orphan/SKILL.md" <<'EOF'
---
name: orphan
description: Unlisted skill.
---
EOF

  if "$repo/scripts/install-skills.sh" >"$repo/out" 2>&1; then
    fail "install-skills should reject unlisted skills and broken local references"
  fi
  assert_file_contains "$repo/out" "unlisted custom skill: custom-skills/orphan"
  assert_file_contains "$repo/out" "missing local reference: custom-skills/demo/references/missing.md"

  mv "$repo/custom-skills/orphan" "$repo/orphan-fixture"
  cat > "$repo/custom-skills/demo/SKILL.md" <<'EOF'
---
name: demo
description: Inspect the demo contract and load only the relevant supporting reference.
---
Read [entry](references/entry.md).
EOF
  mkdir -p "$repo/custom-skills/demo/references/nested"
  printf '[detail](nested/detail.md#contract)\n' > "$repo/custom-skills/demo/references/entry.md"
  printf '[back](../entry.md)\n' > "$repo/custom-skills/demo/references/nested/detail.md"
  "$repo/scripts/install-skills.sh" > "$repo/out" 2>&1 ||
    fail "nested references and cycles should validate: $(cat "$repo/out")"
  printf '[missing](missing.md)\n' >> "$repo/custom-skills/demo/references/nested/detail.md"
  if "$repo/scripts/install-skills.sh" > "$repo/out" 2>&1; then
    fail "missing nested references must still fail"
  fi
  assert_file_contains "$repo/out" 'missing local reference: custom-skills/demo/references/nested/missing.md'
  printf '[back](../entry.md)\n' > "$repo/custom-skills/demo/references/nested/detail.md"
  printf 'unreachable\n' > "$repo/custom-skills/demo/references/orphan.md"
  if "$repo/scripts/install-skills.sh" > "$repo/out" 2>&1; then
    fail "unreachable references must still fail"
  fi
  assert_file_contains "$repo/out" 'orphan local reference: custom-skills/demo/references/orphan.md'
  mv "$repo/custom-skills/demo/references/orphan.md" "$repo/outside.md"
  if ln -s "$repo/outside.md" "$repo/custom-skills/demo/references/link.md" 2>/dev/null; then
    printf '[link](link.md)\n' >> "$repo/custom-skills/demo/references/entry.md"
    if "$repo/scripts/install-skills.sh" > "$repo/out" 2>&1; then
      fail "reference traversal must not follow symlinks"
    fi
    assert_file_contains "$repo/out" 'symlink local reference: custom-skills/demo/references/link.md'
  fi
}

test_session_handoff_blocks_sensitive_digest() {
  local home="$TMP/sh-sensitive-home"
  local cwd="/proj/sens-app"
  local proj="$home/projects/-proj-sens-app"
  local SH="$ROOT/scripts/session-handoff.sh"

  mkdir -p "$proj"
  # A user turn carrying a credential-shaped value, assembled at runtime so the
  # test source itself stays scrubber-clean (split literal; plain var name).
  local vector="AK""IAIOSFODNN7EXAMPLE"
  printf '{"type":"user","message":{"role":"user","content":"deploy with %s"}}\n' \
    "$vector" > "$proj/sess.jsonl"
  printf '{"type":"user","message":{"role":"user","content":"then roll it back"}}\n' \
    >> "$proj/sess.jsonl"

  # Default: refuse to write, nonzero exit, no file.
  if ( OMS_CLAUDE_HOME="$home" "$SH" capture --agent claude --cwd "$cwd" \
       --out "$home/d.md" >/dev/null 2>&1 ); then
    fail "sensitive handoff digest must be refused by default"
  fi
  [ -f "$home/d.md" ] && fail "refused digest must not be left on disk"

  # --allow-sensitive: writes it.
  OMS_CLAUDE_HOME="$home" "$SH" capture --agent claude --cwd "$cwd" \
    --out "$home/d.md" --allow-sensitive >/dev/null 2>&1 ||
    fail "--allow-sensitive should write the digest"
  [ -f "$home/d.md" ] || fail "--allow-sensitive digest not written"

  # Regression: a CLEAN transcript must NOT self-block just because the harness
  # writes an absolute home path into the digest header. --cwd under /home/ would
  # trip the scrubber if the whole digest (not just user content) were scanned.
  # Build the /home cwd at runtime so this test source stays scrubber-clean,
  # and place the session under that cwd's encoded project dir.
  local hcwd="/ho""me/researcher/proj"
  local hdir
  hdir="$home/projects/$(printf '%s' "$hcwd" | sed 's/[^A-Za-z0-9]/-/g')"
  mkdir -p "$hdir"
  {
    printf '{"type":"user","message":{"role":"user","content":"refactor the loader"}}\n'
    printf '{"type":"user","message":{"role":"user","content":"then add a test"}}\n'
  } > "$hdir/h.jsonl"
  OMS_CLAUDE_HOME="$home" "$SH" capture --agent claude --cwd "$hcwd" \
    --out "$home/clean.md" >/dev/null 2>&1 ||
    fail "clean transcript must not self-block on a /home header path"
  [ -f "$home/clean.md" ] || fail "clean digest with /home cwd not written"

  # Machine tier in USER content (a /home path in a turn) no longer refuses the
  # digest: it is normalized and written. This was the PreCompact killer — on
  # Linux every real transcript cites /home paths, so auto-capture always
  # refused and .oms/handoffs stayed empty.
  local pdir="$home/projects/-proj-pathy-app"
  mkdir -p "$pdir"
  printf '{"type":"user","message":{"role":"user","content":"fix /ho%s/researcher/proj/loader.py"}}\n' \
    "me" > "$pdir/p.jsonl"
  printf '{"type":"user","message":{"role":"user","content":"then run the loader tests"}}\n' \
    >> "$pdir/p.jsonl"
  OMS_CLAUDE_HOME="$home" "$SH" capture --agent claude --cwd "/proj/pathy-app" \
    --out "$home/pathy.md" >/dev/null 2>&1 ||
    fail "machine-tier user content must capture, not refuse"
  assert_file_contains "$home/pathy.md" 'fix ~/proj/loader.py'
  if grep -q '/ho''me/researcher' "$home/pathy.md"; then
    fail "raw home path must not survive into the digest body"
  fi
}

test_session_handoff_claude_digest() {
  local home="$TMP/sh-claude-home"
  local cwd="/proj/demo_app.v2"
  local proj="$home/projects/-proj-demo-app-v2"
  local sess="$proj/aaaaaaaa-1111-2222-3333-444444444444.jsonl"
  local out

  mkdir -p "$proj"
  {
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"<local-command-caveat>noise</local-command-caveat>"}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"build the widget feature\nkeep the existing interface"}}'
    printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"working on it"},{"type":"tool_use","name":"Edit","input":{"file_path":"/proj/demo_app.v2/widget.py"}}]}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":[{"type":"tool_result","content":"ok"}]}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"now add tests"}}'
    printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"done: widget plus tests\nVerification: widget check passed\nUSER_COUNT\t999\nRemaining: native check not run"}]}}'
  } > "$sess"

  out="$(OMS_CLAUDE_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/digest.md" 2>/dev/null)"
  [ -f "$out" ] || fail "claude handoff digest not written"
  assert_file_contains "$out" "build the widget feature"
  assert_file_contains "$out" "now add tests"
  assert_file_contains "$out" "widget.py (1 edits)"
  assert_file_contains "$out" "done: widget plus tests"
  assert_file_contains "$out" "keep the existing interface"
  assert_file_contains "$out" "Verification: widget check passed"
  assert_file_contains "$out" "Remaining: native check not run"
  assert_file_contains "$out" 'Recent user turns (last 2 of 2)'
  # Slash-command caveat noise must not become the goal.
  if grep -Fq "local-command-caveat" "$out"; then
    fail "claude digest leaked command-caveat noise"
  fi
  # tool_result-only turns are not real user prose.
  if grep -Fq '"tool_result"' "$out"; then
    fail "claude digest leaked tool_result content"
  fi
  python3 - "$sess" <<'PY'
import json, sys
with open(sys.argv[1], 'a', encoding='utf-8') as handle:
    for number in range(20):
        for role in ('user', 'assistant'):
            handle.write(json.dumps({'type': role, 'message': {
                'content': '%s turn %d ' % (role, number) + 'x' * 4000}}) + '\n')
PY
  out="$(OMS_CLAUDE_HOME="$home" OMS_HANDOFF_TURNS=2 "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/bounded.md" 2>/dev/null)"
  assert_file_contains "$out" 'Recent user turns (last 2 of 22)'
  assert_file_contains "$out" 'build the widget feature'
  assert_file_contains "$out" 'user turn 19 '
  assert_file_contains "$out" 'assistant turn 19 '
  if grep -Fq 'user turn 17 ' "$out"; then
    fail "handoff retained a user turn outside the selected window"
  fi
  [ "$(wc -c < "$out")" -lt 6000 ] || fail "long history bloated the digest"
}

test_session_handoff_carries_resume_contract_and_dissents() {
  local home="$TMP/sh-resume-home"
  local cwd="$TMP/sh-resume-proj"
  local run="20260611T000000Z-77"
  local proj sess out

  # A repo with an active packet carrying a Verify contract and a review
  # round that ended split: both must ride the digest.
  mkdir -p "$cwd/.oms/task" "$cwd/.oms/artifacts/review"
  printf '# Task\n\n## Verify\n\nbash scripts/check.sh --focused-only\n\n## Goal\n\nship\n\n## Decisions\n\n- keep the v1 wire format\n- drop the cache layer\n' \
    > "$cwd/.oms/task/current.md"
  # Recorded state the digest derives instead of trusting the model's summary:
  # plan status, changed files (git) and the newest unresolved failure.
  mkdir -p "$cwd/.oms/plan"
  printf '{"goal":"ship the widget","tasks":{"a":{"state":"done"},"b":{"state":"ready"},"c":{"state":"ready"}}}\n' \
    > "$cwd/.oms/plan/tasks.json"
  git -C "$cwd" init -q 2>/dev/null
  printf 'x\n' > "$cwd/zeta.py"
  printf 'x\n' > "$cwd/alpha.py"
  "$ROOT/scripts/fail-ledger.sh" --repo "$cwd" record --cmd "bash scripts/check.sh --widget" \
    --exit 1 --summary "widget check failed on alpha.py" >/dev/null 2>&1 ||
    fail "fail-ledger record failed in handoff fixture"
  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$cwd/.oms/artifacts/review/codex-x-$run.md"
  printf '# claude review\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' \
    > "$cwd/.oms/artifacts/review/claude-x-$run.md"

  proj="$home/projects/$(printf '%s' "$cwd" | sed 's/[^A-Za-z0-9]/-/g')"
  sess="$proj/bbbbbbbb-1111-2222-3333-444444444444.jsonl"
  mkdir -p "$proj"
  {
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"continue the feature"}}'
    printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"paused at review"}]}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"resume where it stopped"}}'
  } > "$sess"

  out="$(OMS_CLAUDE_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/digest.md" 2>/dev/null)"
  [ -f "$out" ] || fail "resume-contract digest not written"
  assert_file_contains "$out" "## Resume contract"
  assert_file_contains "$out" "## Current task snapshot (advisory)"
  assert_file_contains "$out" "- Goal: ship"
  assert_file_contains "$out" "- plan: ship the widget [done=1 ready=2]"
  assert_file_contains "$out" "  - drop the cache layer"
  assert_file_contains "$out" "- changed files (2, git status): alpha.py, zeta.py"
  assert_file_contains "$out" "- last failing check: widget check failed on alpha.py"
  # Mechanical block precedes the model-written summary, within its own cap.
  [ "$(grep -n '^## Recorded state' "$out" | cut -d: -f1)" -lt "$(grep -n '^## Last assistant summary' "$out" | cut -d: -f1)" ] ||
    fail "recorded state must come before the assistant summary"
  [ "$(sed -n '/^## Recorded state/,/^## Last assistant summary/p' "$out" | wc -c)" -le 1700 ] ||
    fail "recorded state block exceeded its byte cap"
  assert_file_contains "$out" "- verification_observed_at:"
  assert_file_contains "$out" "## Original request (historical)"
  assert_file_contains "$out" "bash scripts/check.sh --focused-only"
  assert_file_contains "$out" "## Open dissents"
  assert_file_contains "$out" "codex: pass"
  assert_file_contains "$out" "claude: fail"

  # Decision log: recorded decision + reason + rejected alternative ride the
  # digest; the newest N stay, older ones are dropped with a count.
  local n
  for n in 1 2 3 4; do
    "$ROOT/scripts/agent-task.sh" --repo "$cwd" update --decision "choice $n" \
      --decision-reason "because $n" --rejected "alt $n" >/dev/null ||
      fail "agent-task --decision with reason/rejected failed ($n)"
  done
  if "$ROOT/scripts/agent-task.sh" --repo "$cwd" update --rejected "orphan" \
    >/dev/null 2>&1; then
    fail "--rejected without --decision must be refused"
  fi
  out="$(OMS_CLAUDE_HOME="$home" OMS_HANDOFF_DECISIONS=3 "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/decisions.md" 2>/dev/null)"
  assert_file_contains "$out" "## Decisions (recorded"
  assert_file_contains "$out" "choice 4 | why: because 4 | rejected: alt 4"
  assert_file_contains "$out" "choice 2 | why: because 2 | rejected: alt 2"
  assert_file_contains "$out" "(1 older decision(s) dropped"
  assert_file_contains "$out" "- decisions: 4 recorded (newest under ## Decisions)"
  assert_file_contains "$out" "  - drop the cache layer"
  if grep -Fq "choice 1 " "$out"; then
    fail "oldest decision must be dropped first"
  fi
  "$ROOT/scripts/agent-task.sh" --repo "$cwd" update \
    --decision "$(printf 'long%.0s' $(seq 1 40))" \
    --decision-reason "$(printf 'why%.0s' $(seq 1 60))" >/dev/null ||
    fail "long decision must be capped, not refused"
  out="$(OMS_CLAUDE_HOME="$home" OMS_HANDOFF_DECISION_BYTES=256 "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/decisions-cap.md" 2>/dev/null)"
  assert_file_contains "$out" "longlonglong"
  assert_file_contains "$out" "older decision(s) dropped"
  if grep -Fq "choice 3 " "$out"; then fail "byte cap must drop older decisions"; fi
  # A row the decision log does not parse still renders, exactly once.
  printf -- '-   2026-01-01T00:00:00Z [x] spaced choice\n' >> "$cwd/.oms/task/current.md"
  out="$(OMS_CLAUDE_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/decisions-spaced.md" 2>/dev/null)"
  [ "$(grep -c 'spaced choice' "$out")" = 1 ] || fail "every decision row must render exactly once: $out"
}

test_session_handoff_dissents_from_typed_outcome() {
  local home="$TMP/sh-typed-home"
  local cwd="$TMP/sh-typed-proj"
  local proj sess out

  # Typed review-outcome rows and NO review artifacts: the dissent block must
  # come from the typed rows, not from re-parsing rendered Markdown, and it
  # must select the latest UNRESOLVED genuine split — a resolved split (an
  # artifact-resolution receipt names its event) and an incomplete round
  # (overall=2) are not open dissents, and a later non-split gate must not
  # bury an older split that nobody acknowledged.
  mkdir -p "$cwd/.oms/artifacts"
  python3 - "$cwd/.oms/artifacts/index.jsonl" <<'PY'
import json, sys

rows = [
    # A resolved split: its receipt below retires it.
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 1,
     "event_id": "evt_resolved_split",
     "review": {"overall": 1, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.9, "round": 1},
         {"provider": "claude", "verdict": "fail", "confidence": None, "round": 1}]}},
    {"schema": 1, "kind": "artifact-resolution", "provider": "local", "exit": 0,
     "event_id": "evt_receipt", "resolves_event_id": "evt_resolved_split"},
    # The open split this digest must carry.
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 1,
     "event_id": "evt_open_split",
     "review": {"overall": 1, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.8, "round": 2},
         {"provider": "claude", "verdict": "fail", "confidence": None, "round": 2}]}},
    # An incomplete later round: pass+fail+incomplete is overall=2, not a split.
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 2,
     "event_id": "evt_incomplete",
     "review": {"overall": 2, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.7, "round": 1},
         {"provider": "claude", "verdict": "fail", "confidence": None, "round": 1},
         {"provider": "antigravity", "verdict": "incomplete", "confidence": None, "round": 1}]}},
    # A later all-pass gate must not bury the unacknowledged split above.
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 0,
     "event_id": "evt_green",
     "review": {"overall": 0, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.9, "round": 1}]}},
]
with open(sys.argv[1], "w", encoding="utf-8") as fh:
    for row in rows:
        fh.write(json.dumps(row) + "\n")
PY
  proj="$home/projects/$(printf '%s' "$cwd" | sed 's/[^A-Za-z0-9]/-/g')"
  sess="$proj/cccccccc-1111-2222-3333-444444444444.jsonl"
  mkdir -p "$proj"
  {
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"continue the feature"}}'
    printf '%s\n' '{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"paused at review"}]}}'
    printf '%s\n' '{"type":"user","message":{"role":"user","content":"resume where it stopped"}}'
  } > "$sess"

  out="$(OMS_CLAUDE_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd" --out "$home/digest.md" 2>/dev/null)"
  [ -f "$out" ] || fail "typed-dissent digest not written"
  assert_file_contains "$out" "## Open dissents"
  assert_file_contains "$out" "codex: pass (confidence 0.8)"
  assert_file_contains "$out" "claude: fail"
  # The selected split names its event and the exact resolution entrance.
  assert_file_contains "$out" "evt_open_split"
  assert_file_contains "$out" "artifact-index"
  if grep -Fq "evt_resolved_split" "$out"; then
    fail "a resolved split reached the digest despite its receipt"
  fi
  if grep -Fq "confidence 0.9" "$out"; then
    fail "a resolved or non-split row's seats reached the digest"
  fi
  if grep -Fq "antigravity: incomplete" "$out"; then
    fail "an incomplete round was rendered as an open split"
  fi

  # Every typed split resolved: the stale rendered artifacts of that same
  # round must not resurrect it through the legacy parser.
  local cwd2="$TMP/sh-typed-resolved-proj"
  mkdir -p "$cwd2/.oms/artifacts/review"
  python3 - "$cwd2/.oms/artifacts/index.jsonl" <<'PY'
import json, sys

rows = [
    {"schema": 1, "kind": "review-outcome", "provider": "local", "exit": 1,
     "event_id": "evt_only_split",
     "review": {"overall": 1, "gate_verify_exit": 0, "seats": [
         {"provider": "codex", "verdict": "pass", "confidence": 0.9, "round": 1},
         {"provider": "claude", "verdict": "fail", "confidence": None, "round": 1}]}},
    {"schema": 1, "kind": "artifact-resolution", "provider": "local", "exit": 0,
     "event_id": "evt_receipt2", "resolves_event_id": "evt_only_split"},
]
with open(sys.argv[1], "w", encoding="utf-8") as fh:
    for row in rows:
        fh.write(json.dumps(row) + "\n")
PY
  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$cwd2/.oms/artifacts/review/codex-x-20260611T000000Z-78.md"
  printf '# claude review\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' \
    > "$cwd2/.oms/artifacts/review/claude-x-20260611T000000Z-78.md"
  mkdir -p "$home/projects/$(printf '%s' "$cwd2" | sed 's/[^A-Za-z0-9]/-/g')"
  cp "$sess" "$home/projects/$(printf '%s' "$cwd2" | sed 's/[^A-Za-z0-9]/-/g')/"
  out="$(OMS_CLAUDE_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent claude --cwd "$cwd2" --out "$home/digest-resolved.md" 2>/dev/null)"
  [ -f "$out" ] || fail "resolved-dissent digest not written"
  if grep -Fq "## Open dissents" "$out"; then
    fail "a resolved typed split was resurrected from legacy review artifacts"
  fi
}

test_session_handoff_prompt_from_records() {
  local cwd="$TMP/sh-prompt-proj" SH="$ROOT/scripts/session-handoff.sh"
  local out vector="AK""IAIOSFODNN7EXAMPLE" tid

  make_committed_repo "$cwd"
  # Empty repo: works with nothing recorded and says so instead of omitting.
  out="$("$SH" prompt --cwd "$cwd")" || fail "prompt must work with no task or plan"
  printf '%s\n' "$out" | grep -q 'task goal: not recorded (no active task)' || fail "no-task prompt lost its not-recorded goal"
  printf '%s\n' "$out" | grep -q '^truncated: no$' || fail "prompt must always carry a truncated line"
  printf '%s\n' "$out" | grep -q 'previous handoff: not recorded' || fail "missing handoff must print not recorded"

  "$ROOT/scripts/agent-task.sh" --repo "$cwd" init --goal "ship the feature" --verify true \
    --next "write the docs" >/dev/null
  "$ROOT/scripts/agent-task.sh" --repo "$cwd" update --done "criterion one" --decision "use sqlite" \
    --verification "ran unit tests: ok" >/dev/null
  tid="$("$ROOT/scripts/agent-task.sh" --repo "$cwd" status --json | python3 -c 'import json,sys; print(json.load(sys.stdin)["task_id"])')"
  "$ROOT/scripts/agent-plan.sh" --repo "$cwd" init --goal "plan goal" --accept true >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$cwd" add --id t1 --title first >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$cwd" add --id t2 --title second --depends t1 >/dev/null
  mkdir -p "$cwd/.oms/artifacts/review" "$cwd/.oms/handoffs"
  printf 'x\n' > "$cwd/.oms/handoffs/claude-prev-20261110.md"
  python3 - "$cwd/.oms/artifacts/review/_findings-RUN1.jsonl" "$vector" <<'PY'
import json, sys
rows = [
    {"schema": 1, "kind": "review-finding", "id": "f-aaaaaaaaaaaa", "run": "RUN1", "ts": "2026-11-10T00:00:00Z",
     "severity": "advisory", "file": "a.txt", "line": 1, "summary": "style nit", "anchor": "in-diff", "seat": "codex"},
    {"schema": 1, "kind": "review-finding", "id": "f-bbbbbbbbbbbb", "run": "RUN1", "ts": "2026-11-10T00:00:00Z",
     "severity": "blocking", "file": "b.txt", "line": 2, "summary": "wrong bound", "anchor": "in-diff", "seat": "codex"},
    {"schema": 1, "kind": "review-finding", "id": "f-cccccccccccc", "run": "RUN1", "ts": "2026-11-10T00:00:00Z",
     "severity": "blocking", "file": "c.txt", "line": 3, "summary": "leaks " + sys.argv[2], "anchor": "in-diff", "seat": "codex"},
]
with open(sys.argv[1], "w", encoding="utf-8") as fh:
    for row in rows:
        fh.write(json.dumps(row) + "\n")
PY

  out="$("$SH" prompt --cwd "$cwd")" || fail "prompt failed on a populated repo"
  local section
  for section in Goal State Decisions 'Open findings' 'Verified / Not verified' 'Next step' Pointers; do
    printf '%s\n' "$out" | grep -q "^## $section\$" || fail "prompt lost section: $section"
  done
  printf '%s\n' "$out" | grep -qF "task goal: ship the feature [src: task $tid]" || fail "goal needs the task id"
  printf '%s\n' "$out" | grep -q 'criteria ids: criterion-' || fail "goal needs criteria ids"
  printf '%s\n' "$out" | grep -q 'blocked t2: second -- dependencies-unfinished; waits on t1\[ready\] \[src: task t2\]' ||
    fail "blocked plan task needs its reason and source"
  printf '%s\n' "$out" | grep -q 'use sqlite \[src: wj_' || fail "decision needs its journal event id"
  printf '%s\n' "$out" | grep -qF -- '- blocking b.txt:2 -- wrong bound [src: f-bbbbbbbbbbbb]' || fail "blocking finding line missing"
  [ "$(printf '%s\n' "$out" | grep -n 'f-bbbbbbbbbbbb\]' | cut -d: -f1)" -lt "$(printf '%s\n' "$out" | grep -n 'f-aaaaaaaaaaaa\]' | cut -d: -f1)" ] ||
    fail "blocking findings must come before advisory ones"
  printf '%s\n' "$out" | grep -q 'recorded: .*ran unit tests: ok \[src: task '"$tid"' verification ' || fail "verification record missing"
  printf '%s\n' "$out" | grep -q 'task gate: none' || fail "an unverified task must not read as verified"
  printf '%s\n' "$out" | grep -q 'NOT verified plan-task-t1 ' || fail "unverified criteria must be listed"
  printf '%s\n' "$out" | grep -qF -- "- write the docs [src: task $tid]" || fail "next step missing"
  printf '%s\n' "$out" | grep -qF 'oms session-handoff show claude-prev-20261110.md' || fail "previous handoff pointer missing"
  printf '%s\n' "$out" | grep -q 'f-cccccccccccc\]' || fail "withheld line must keep its source id"
  printf '%s\n' "$out" | grep -q 'withheld: this line matched the sensitive-content scan' || fail "flagged line must be withheld"
  printf '%s\n' "$out" | grep -q 'withheld: 1 line(s)' || fail "withheld count line missing"
  printf '%s\n' "$out" | grep -qF "$vector" && fail "scan let a credential-shaped value through"

  # Byte bound: never above the cap, and the cut is named.
  out="$("$SH" prompt --cwd "$cwd" --max-bytes 900)" || fail "bounded prompt failed"
  [ "$(printf '%s\n' "$out" | wc -c)" -le 900 ] || fail "prompt exceeded --max-bytes"
  printf '%s\n' "$out" | grep -q '^truncated: [0-9]* line(s) omitted' || fail "bounded prompt must name the cut"
  "$SH" prompt --cwd "$cwd" --max-bytes 10 >/dev/null 2>&1 && fail "--max-bytes below the floor must be refused"

  # --output refuses to overwrite.
  "$SH" prompt --cwd "$cwd" --output "$TMP/sh-prompt-out.md" >/dev/null || fail "--output must write a new file"
  grep -q '^## Next step$' "$TMP/sh-prompt-out.md" || fail "--output file lacks the prompt"
  if "$SH" prompt --cwd "$cwd" --output "$TMP/sh-prompt-out.md" >/dev/null 2>&1; then
    fail "--output must refuse to overwrite"
  fi
  # Read-only: nothing under .oms/task or plan changed shape.
  git -C "$cwd" status --porcelain | grep -q . && fail "prompt must not touch tracked files"
  return 0
}

test_session_handoff_codex_digest() {
  local home="$TMP/sh-codex-home"
  local cwd="/proj/codex-app"
  local sess="$home/sessions/2026/06/01/rollout-2026-06-01T00-00-00-deadbeef.jsonl"
  local out

  mkdir -p "$(dirname "$sess")"
  {
    printf '%s\n' "{\"type\":\"session_meta\",\"payload\":{\"id\":\"deadbeef\",\"cwd\":\"$cwd\"}}"
    printf '%s\n' '{"type":"event_msg","payload":{"type":"user_message","message":"refactor the parser"}}'
    printf '%s\n' '{"type":"event_msg","payload":{"type":"agent_message","message":"thinking"}}'
    printf '%s\n' '{"type":"event_msg","payload":{"type":"user_message","message":"now cover the edge cases"}}'
    printf '%s\n' '{"type":"event_msg","payload":{"type":"task_complete","last_agent_message":"parser refactored and tested\nVerification: parser check passed\nRemaining: portability untested"}}'
  } > "$sess"

  out="$(OMS_CODEX_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent codex --cwd "$cwd" --out "$home/digest.md" 2>/dev/null)"
  [ -f "$out" ] || fail "codex handoff digest not written"
  assert_file_contains "$out" "refactor the parser"
  assert_file_contains "$out" "parser refactored and tested"
  assert_file_contains "$out" "Verification: parser check passed"
  assert_file_contains "$out" "Remaining: portability untested"

  out="$(OMS_CODEX_HOME="$home" OMS_HANDOFF_TURNS=0 "$ROOT/scripts/session-handoff.sh" \
    capture --agent codex --cwd "$cwd" --out "$home/zero.md" 2>/dev/null)"
  assert_file_contains "$out" 'Recent user turns (last 0 of 2)'
  if OMS_CODEX_HOME="$home" OMS_HANDOFF_TURNS=-1 "$ROOT/scripts/session-handoff.sh" \
      capture --agent codex --cwd "$cwd" --out "$home/invalid.md" >/dev/null 2>&1; then
    fail "negative handoff turn budget was accepted"
  fi
  python3 - "$sess" <<'PY'
import json, sys
answer = 'Parser repaired.\n' + 'details ' * 250 + '\nVerification: failed\nRemaining: migration unsafe'
with open(sys.argv[1], 'a', encoding='utf-8') as handle:
    handle.write(json.dumps({'type': 'event_msg', 'payload': {
        'type': 'task_complete', 'last_agent_message': answer}}) + '\n')
PY
  out="$(OMS_CODEX_HOME="$home" "$ROOT/scripts/session-handoff.sh" \
    capture --agent codex --cwd "$cwd" --out "$home/long.md" 2>/dev/null)"
  assert_file_contains "$out" 'Parser repaired.'
  assert_file_contains "$out" 'Verification: failed'
  assert_file_contains "$out" 'Remaining: migration unsafe'
  assert_file_contains "$out" '(truncated)'
}

