# smoke-weight: 6
test_run_capsule_captures_and_reproduces() {
  local proj="$TMP/capsule-basic"
  local runs="$proj/.oms/runs"
  local id

  make_committed_repo "$proj"
  printf 'dirty\n' >> "$proj/file.txt"           # make the tree dirty
  printf '{"accuracy": 0.9}\n' > "$proj/metrics.json"
  printf 'seed: 7\n' > "$proj/config.yaml"
  # Project interpreter stub: reports a distinct python/torch so the capsule
  # must come from .venv, not OMS's bare python3.
  mkdir -p "$proj/.venv/bin"
  cat > "$proj/.venv/bin/python" <<'STUB'
#!/bin/sh
if [ "$#" -eq 0 ] || [ "$1" = "-" ]; then
  [ "$#" -eq 0 ] || shift
  exec python3 -c 'import platform,sys;platform.python_version=lambda:"9.8.7";sys.argv=["-"]+sys.argv[1:];exec(sys.stdin.read())' "$@"
fi
case "$2" in
  *torch.__version__*) echo 8.8.8 ;;
  *torch.version.cuda*) echo 7.7 ;;
esac
STUB
  chmod +x "$proj/.venv/bin/python"
  # Conda stand-in: the export carries a machine prefix and, in one mode, a credential-shaped channel.
  local stub="$TMP/capsule-conda-bin" calls="$TMP/capsule-conda-calls"
  mkdir -p "$stub"
  cat > "$stub/conda" <<'STUB'
#!/bin/sh
printf '%s\n' "$*" >> "$CONDA_STUB_CALLS"
case "${CONDA_STUB_MODE:-ok}" in
  fail) echo 'conda: broken install' >&2; exit 1 ;;
  hang) exec sleep 30 ;;
esac
printf 'name: chem\nchannels:\n  - conda-forge\n'
[ "${CONDA_STUB_MODE:-ok}" != secret ] || printf '  - https://repo.example/t/aws_secret_access_''key=EXAMPLEVALUE/private\n'
[ "${CONDA_STUB_MODE:-ok}" != token ] || printf '  - https://conda.anaconda.org/t/tk-EXAMPLETOKEN123/private\n'
printf 'dependencies:\n  - rdkit=2026.03.1\nprefix: /ho''me/someone/miniconda3/envs/chem\n'
printf 'variables:\n  SLURM_JOB_USER: alice\n  CAPSULE_FIXTURE_EXTRA: unlisted-value-9f3c\n'
STUB
  chmod +x "$stub/conda"
  : > "$calls"

  id="$(cd "$proj" && OMS_RUNS_DIR="$runs" OMS_AGENT=claude PATH="$stub:$PATH" CONDA_STUB_CALLS="$calls" \
    CONDA_DEFAULT_ENV=chem LOADEDMODULES='gcc/12.2:cuda/12.1' CUDA_VISIBLE_DEVICES=0 SLURM_JOB_ID=4242 \
    SLURM_JOB_USER=alice CAPSULE_FIXTURE_EXTRA=unlisted-value-9f3c \
    "$ROOT/scripts/run-capsule.sh" run --note cap --config config.yaml \
    --output file.txt --seed 7 --metrics metrics.json --no-ledger \
    -- bash -c 'echo trained' 2>/dev/null)"
  [ -n "$id" ] || fail "capsule run printed no id"
  local cap="$runs/$id/capsule.json"
  [ -f "$cap" ] || fail "capsule.json not written"
  [ -f "$runs/$id/uncommitted.diff" ] || fail "dirty diff not captured"
  assert_file_contains "$cap" '"schema": 1'
  assert_file_contains "$cap" '"accuracy": 0.9'
  assert_file_contains "$cap" '"python": "9.8.7"'
  assert_file_contains "$cap" '"torch": "8.8.8"'
  assert_file_contains "$cap" '"cuda": "7.7"'
  assert_file_contains "$cap" '.venv/bin/python"'
  assert_file_contains "$cap" '"seed'
  assert_file_contains "$cap" 'config.yaml'
  assert_file_contains "$runs/$id/output.log" "trained"
  # Where the run executed: present things are recorded, the export without its machine prefix, and no
  # variable outside the fixed list is read.
  python3 - "$cap" "$runs/$id/env.conda.yml" <<'PY' || fail "capsule did not record the execution environment"
import hashlib, json, sys
env = json.load(open(sys.argv[1]))["env"]
export = open(sys.argv[2], "rb").read()
assert export == b"name: chem\nchannels:\n  - conda-forge\ndependencies:\n  - rdkit=2026.03.1\n", export
assert env["conda"] == {"env": "chem", "tool": "conda", "export_sha256": hashlib.sha256(export).hexdigest()}, env["conda"]
assert env["modules"] == ["gcc/12.2", "cuda/12.1"], env["modules"]
assert env["env_vars"] == {"CUDA_VISIBLE_DEVICES": "0", "SLURM_JOB_ID": "4242"}, env["env_vars"]
assert isinstance(env["host"], str) and env["host"] and "." not in env["host"], env["host"]
assert type(env["cpu_count"]) is int and env["cpu_count"] > 0, env["cpu_count"]
assert env["gpu_count"] is None or env["gpu_count"] == len(env["gpu_names"]) > 0, env
PY
  if grep -Fq -e 'unlisted-value-9f3c' -e 'alice' -e '/ho''me/someone' "$cap" "$runs/$id/env.conda.yml"; then
    fail "capsule captured a variable outside the allow-list or the machine prefix"
  fi
  [ "$(cat "$calls")" = 'env export --no-builds' ] || fail "conda should be asked once for the export"

  # reproduce prints the exact checkout + diff-apply for the captured state.
  local repro
  repro="$(cd "$proj" && OMS_RUNS_DIR="$runs" "$ROOT/scripts/run-capsule.sh" reproduce "$id")"
  contains "$repro" "git checkout" || fail "reproduce missing checkout"
  contains "$repro" "uncommitted.diff" || fail "reproduce missing diff apply"

  # Env is captured reconstructably (lock or freeze) and reproduce points at it.
  [ -f "$runs/$id/env.uv.lock" ] || [ -f "$runs/$id/env.freeze.txt" ] ||
    fail "no reconstructable env lock saved"
  printf '%s' "$repro" | grep >/dev/null -E 'uv sync|pip install' || fail "reproduce missing env recreate step"
  contains "$repro" "conda env create -f $runs/$id/env.conda.yml" || fail "reproduce missing the conda export"
  contains "$repro" "# modules at capture: gcc/12.2 cuda/12.1" || fail "reproduce missing the loaded modules"

  # verify: clean against the same tree, drift after a change.
  local vout
  vout="$(cd "$proj" && OMS_RUNS_DIR="$runs" env -u CONDA_DEFAULT_ENV -u LOADEDMODULES \
    "$ROOT/scripts/run-capsule.sh" verify "$id" 2>&1)" ||
    fail "verify should pass on the unchanged tree"
  contains "$vout" "env-python" || fail "verify missing env-drift report"
  contains "$vout" "ok    env-python: capsule=9.8.7 current=9.8.7" || fail "verify must re-probe with the project interpreter"
  contains "$vout" "env-interpreter" || fail "verify missing interpreter line"
  # Without the conda environment and modules the capsule ran under, verify warns but tree drift alone fails it.
  contains "$vout" "WARN  env-conda: capsule=chem@" || fail "verify should warn that the conda environment differs"
  contains "$vout" "WARN  env-modules: capsule=gcc/12.2,cuda/12.1 current=(none)" || fail "verify should warn that modules differ"
  contains "$vout" "info env-host:" || fail "verify missing host line"
  vout="$(cd "$proj" && OMS_RUNS_DIR="$runs" PATH="$stub:$PATH" CONDA_STUB_CALLS="$calls" CONDA_DEFAULT_ENV=chem \
    LOADEDMODULES='gcc/12.2:cuda/12.1' "$ROOT/scripts/run-capsule.sh" verify "$id" 2>&1)" ||
    fail "verify should pass under the captured environment"
  contains "$vout" "ok    env-conda: capsule=chem@" || fail "verify should match the same conda export"
  contains "$vout" "ok    env-modules: capsule=gcc/12.2,cuda/12.1 current=gcc/12.2,cuda/12.1" || fail "verify should match the same modules"
  [ ! -f "$proj/env.conda.yml" ] || fail "verify must not save an export"

  # Detection only. No active environment: conda is never run and the block is null, as are unset modules and
  # variables. A failing, hanging or credential-bearing export never fails the capture.
  local case_id mode
  : > "$calls"
  case_id="$(cd "$proj" && OMS_RUNS_DIR="$runs" PATH="$stub:$PATH" CONDA_STUB_CALLS="$calls" \
    env -u CONDA_DEFAULT_ENV -u LOADEDMODULES -u CUDA_VISIBLE_DEVICES -u OMP_NUM_THREADS -u SLURM_JOB_ID \
      -u SLURM_ARRAY_TASK_ID -u SLURM_JOB_NODELIST -u SLURM_JOB_PARTITION \
    "$ROOT/scripts/run-capsule.sh" run --no-ledger -- true 2>/dev/null)"
  [ ! -s "$calls" ] || fail "conda must not run without an active environment"
  [ ! -f "$runs/$case_id/env.conda.yml" ] || fail "no export should be saved without an active environment"
  python3 - "$runs/$case_id/capsule.json" <<'PY' || fail "absent environment details must be null"
import json, sys
env = json.load(open(sys.argv[1]))["env"]
assert env["conda"] is None and env["modules"] is None and env["env_vars"] is None, env
PY
  if ! command -v conda >/dev/null 2>&1 && ! command -v mamba >/dev/null 2>&1; then
    case_id="$(cd "$proj" && OMS_RUNS_DIR="$runs" CONDA_DEFAULT_ENV=chem \
      "$ROOT/scripts/run-capsule.sh" run --no-ledger -- true 2>/dev/null)"
    assert_file_contains "$runs/$case_id/capsule.json" '"conda": null'
  fi
  for mode in fail hang secret token; do
    case_id="$(cd "$proj" && OMS_RUNS_DIR="$runs" PATH="$stub:$PATH" CONDA_STUB_CALLS="$calls" \
      CONDA_STUB_MODE="$mode" CONDA_DEFAULT_ENV=chem OMS_RUN_CAPSULE_CONDA_TIMEOUT=1 \
      "$ROOT/scripts/run-capsule.sh" run --no-ledger -- true 2>"$proj/capsule-$mode.err")" ||
      fail "a $mode conda export must not fail the capture"
    [ ! -f "$runs/$case_id/env.conda.yml" ] || fail "a $mode conda export must not be saved"
    assert_file_contains "$runs/$case_id/capsule.json" '"env": "chem"'
    case "$mode" in
      secret|token)
        assert_file_contains "$proj/capsule-$mode.err" 'conda export contains sensitive-looking content; kept its digest only'
        grep -Eq '"export_sha256": "[0-9a-f]{64}"' "$runs/$case_id/capsule.json" || fail "a withheld export keeps its digest"
        ! grep -Fq -e 'EXAMPLEVALUE' -e 'EXAMPLETOKEN123' "$runs/$case_id/capsule.json" || fail "the credential-shaped channel reached the capsule"
        ! grep -Fq 'unlisted-value-9f3c' "$runs/$case_id/capsule.json" || fail "a variables block reached the capsule"
        compgen -G "$runs/$case_id/*conda*" >/dev/null && fail "a withheld export left a file in the bundle" ;;
      *) assert_file_contains "$runs/$case_id/capsule.json" '"export_sha256": null' ;;
    esac
  done
  printf 'changed\n' >> "$proj/file.txt"
  if ( cd "$proj" && OMS_RUNS_DIR="$runs" "$ROOT/scripts/run-capsule.sh" verify "$id" >/dev/null ); then
    fail "verify should report drift after a change"
  fi

  # A JSON config is stored flattened; a sensitive-looking or oversized one keeps its digest only.
  local cfg_err="$proj/cfg.err" cfg_view
  printf '{"lr": 0.001, "model": {"depth": 4}, "nan_ok": [1, 2]}\n' > "$proj/hp.json"
  printf '{"lr": 0.001, "pass''word": "hunter2-hunter2-hunter2"}\n' > "$proj/creds.json"
  python3 -c 'import json; print(json.dumps({"k%d" % i: i for i in range(201)}))' > "$proj/wide.json"
  printf '[1, 2]\n' > "$proj/list.json"
  id="$(cd "$proj" && OMS_RUNS_DIR="$runs" "$ROOT/scripts/run-capsule.sh" run --config hp.json \
    --config creds.json --config wide.json --config list.json --no-ledger -- true 2>"$cfg_err")"
  [ -n "$id" ] || fail "capsule run with configs printed no id: $(cat "$cfg_err")"
  cfg_view="$(python3 - "$runs/$id/capsule.json" <<'PY'
import json, sys
for row in json.load(open(sys.argv[1]))["configs"]:
    print("%s|%s|%s" % (row["path"], row.get("params_status"), json.dumps(row.get("params"), sort_keys=True)))
PY
)"
  contains "$cfg_view" 'hp.json|parsed|{"lr": 0.001, "model.depth": 4, "nan_ok": "[1,2]"}' ||
    fail "a JSON config should be stored flattened: $cfg_view"
  contains "$cfg_view" 'creds.json|withheld: sensitive-looking content|null' ||
    fail "a sensitive-looking config must keep its digest only: $cfg_view"
  contains "$cfg_view" 'wide.json|not recorded: over the cap' || fail "an oversized config must keep its digest only: $cfg_view"
  contains "$cfg_view" 'list.json|not parsed: top level is not a mapping|null' || fail "a non-mapping config is not flattened: $cfg_view"
  assert_file_contains "$cfg_err" "capsule: config creds.json contains sensitive-looking values; kept its digest only"
  ! grep -Fq "hunter2" "$runs/$id/capsule.json" || fail "a withheld config value reached the capsule"
  [ "$(grep -c '"sha256"' "$runs/$id/capsule.json")" = 4 ] || fail "every config keeps its digest"

  # --data links the run to a recorded data manifest: its fingerprint and split row counts, never data.
  local manifests="$proj/.oms/manifests" data_id data_out before
  printf 'a\nb\nc\n' > "$proj/train.txt"
  printf 'd\n' > "$proj/val.txt"
  ( cd "$proj" && OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/data-manifest.sh" create --name ds \
    --split train=train.txt --split val=val.txt >/dev/null 2>&1 ) || fail "manifest create failed"
  # An unknown or unsafe name stops before the command runs and leaves no bundle.
  before="$(find "$runs" -name capsule.json | wc -l | tr -d ' ')"
  if ( cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/run-capsule.sh" run \
    --data nope --no-ledger -- touch "$proj/ran-anyway" >/dev/null 2>"$proj/data.err" ); then
    fail "an unknown --data manifest must fail the capture"
  fi
  assert_file_contains "$proj/data.err" "--data nope: no such data manifest"
  [ ! -e "$proj/ran-anyway" ] || fail "the command ran despite an unknown --data manifest"
  if ( cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/run-capsule.sh" run \
    --data ../ds --no-ledger -- true >/dev/null 2>&1 ); then
    fail "a --data name with a path separator must be refused"
  fi
  [ "$(find "$runs" -name capsule.json | wc -l | tr -d ' ')" = "$before" ] || fail "a refused --data left a capsule"
  data_id="$(cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/run-capsule.sh" run \
    --data ds --data ds --no-ledger -- true 2>/dev/null)"
  [ -n "$data_id" ] || fail "capsule run with --data printed no id"
  data_out="$(python3 - "$runs/$data_id/capsule.json" <<'PY'
import json, sys
data = json.load(open(sys.argv[1]))["data"]
print(len(data), data[0]["name"], len(data[0]["manifest_sha256"]), json.dumps(data[0]["splits"], sort_keys=True))
PY
)"
  [ "$data_out" = '1 ds 64 {"train": 3, "val": 1}' ] || fail "--data should record one fingerprinted manifest: $data_out"
  ! grep -Fq '"data"' "$runs/$id/capsule.json" || fail "a capsule without --data must not grow a data block"
  # Recreating the manifest over unchanged splits (new timestamp and note) keeps the fingerprint.
  ( cd "$proj" && OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/data-manifest.sh" create --name ds --note again \
    --split train=train.txt --split val=val.txt >/dev/null 2>&1 ) || fail "manifest recreate failed"
  data_out="$(cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" \
    "$ROOT/scripts/run-capsule.sh" verify "$data_id" 2>/dev/null || true)"
  contains "$data_out" "ok    data-ds:" || fail "an unchanged manifest should verify ok: $data_out"
  # A manifest recorded over changed splits is a warning, and does not add drift of its own.
  printf 'e\n' >> "$proj/train.txt"
  ( cd "$proj" && OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/data-manifest.sh" create --name ds \
    --split train=train.txt --split val=val.txt >/dev/null 2>&1 ) || fail "manifest update failed"
  data_out="$(cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" \
    "$ROOT/scripts/run-capsule.sh" verify "$data_id" 2>/dev/null || true)"
  contains "$data_out" "WARN  data-ds:" || fail "a changed manifest should warn: $data_out"
  ! printf '%s\n' "$data_out" | grep -q '^DRIFT data' || fail "a data warning must not be drift: $data_out"
  rm -f "$manifests/ds.json"
  data_out="$(cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" \
    "$ROOT/scripts/run-capsule.sh" verify "$data_id" 2>/dev/null || true)"
  contains "$data_out" "current=(missing)" || fail "a removed manifest should read as missing: $data_out"
  data_out="$(cd "$proj" && OMS_RUNS_DIR="$runs" "$ROOT/scripts/run-capsule.sh" reproduce "$data_id")"
  contains "$data_out" "# data at capture: ds manifest " || fail "reproduce should name the data manifest: $data_out"
  # No policy declared: the row has no policy key. A capture without --data prints one advisory line and still succeeds.
  ( cd "$proj" && OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/data-manifest.sh" create --name ds \
    --split train=train.txt --split val=val.txt >/dev/null 2>&1 ) || fail "manifest recreate failed"
  data_id="$(cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/run-capsule.sh" run \
    --data ds --no-ledger -- true 2>/dev/null)"
  [ "$(python3 -c 'import json,sys;print("policy" in json.load(open(sys.argv[1]))["data"][0])' "$runs/$data_id/capsule.json")" = False ] ||
    fail "a manifest without a policy must not add a policy key"
  ( cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/run-capsule.sh" run \
    --no-ledger -- true >/dev/null 2>"$proj/hint.err" ) || fail "the data hint must never fail a capture"
  assert_file_contains "$proj/hint.err" "capsule: data manifests exist (ds) but no --data was given; add --data NAME"
  [ "$(grep -c 'data manifests exist' "$proj/hint.err")" = 1 ] || fail "the data hint should be one line: $(cat "$proj/hint.err")"
  ( cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/run-capsule.sh" run \
    --data ds --no-ledger -- true >/dev/null 2>"$proj/hint.err" )
  ! grep -q "data manifests exist" "$proj/hint.err" || fail "no hint when --data is given: $(cat "$proj/hint.err")"
  ( cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$proj/no-manifests" "$ROOT/scripts/run-capsule.sh" run \
    --no-ledger -- true >/dev/null 2>"$proj/hint.err" )
  ! grep -q "data manifests exist" "$proj/hint.err" || fail "no hint when the repo has no manifest: $(cat "$proj/hint.err")"
  # A declared policy is recorded on the data row.
  ( cd "$proj" && OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/data-manifest.sh" create --name pol --policy random \
    --split train=train.txt --split val=val.txt >/dev/null 2>&1 ) || fail "policy manifest create failed"
  data_id="$(cd "$proj" && OMS_RUNS_DIR="$runs" OMS_MANIFEST_DIR="$manifests" "$ROOT/scripts/run-capsule.sh" run \
    --data pol --no-ledger -- true 2>/dev/null)"
  [ "$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["data"][0].get("policy"))' "$runs/$data_id/capsule.json")" = random ] ||
    fail "the declared policy should be recorded on the data row"
}

test_run_capsule_propagates_exit_and_runs_once() {
  local proj="$TMP/capsule-exit"
  local runs="$proj/.oms/runs"
  local rc=0

  make_committed_repo "$proj"
  ( cd "$proj" && OMS_RUNS_DIR="$runs" \
    "$ROOT/scripts/run-capsule.sh" run --no-ledger \
    -- bash -c 'echo x >> marker; exit 7' >/dev/null 2>&1 ) || rc=$?
  [ "$rc" = "7" ] || fail "capsule should propagate the command exit code (got $rc)"
  [ "$(wc -l < "$proj/marker" | tr -d ' ')" = "1" ] || fail "command must run exactly once"
}

test_run_capsule_whence_traces_checkpoint() {
  local proj="$TMP/capsule-whence"
  local runs="$proj/.oms/runs"
  local id

  make_committed_repo "$proj"
  printf 'fake-weights\n' > "$proj/model.pt"
  id="$(cd "$proj" && OMS_RUNS_DIR="$runs" \
    "$ROOT/scripts/run-capsule.sh" run --output model.pt --no-ledger \
    -- bash -c 'echo trained' 2>/dev/null)"
  [ -n "$id" ] || fail "capsule run printed no id"
  assert_file_contains "$runs/$id/capsule.json" '"sha256"'

  # whence traces the checkpoint back to its producing run.
  local out
  out="$(cd "$proj" && OMS_RUNS_DIR="$runs" \
    "$ROOT/scripts/run-capsule.sh" whence model.pt 2>/dev/null)"
  contains "$out" "$id" || fail "whence did not find the producing run"

  # An unrelated file has no producing run.
  printf 'unrelated\n' > "$proj/other.pt"
  if ( cd "$proj" && OMS_RUNS_DIR="$runs" \
    "$ROOT/scripts/run-capsule.sh" whence other.pt >/dev/null 2>&1 ); then
    fail "whence should fail for a file no run produced"
  fi

  # Outputs must be hashed AFTER the command runs: a checkpoint the run itself
  # produces (not pre-existing) must still be traceable.
  local id2
  id2="$(cd "$proj" && OMS_RUNS_DIR="$runs" \
    "$ROOT/scripts/run-capsule.sh" run --output produced.pt --no-ledger \
    -- bash -c 'echo weights > produced.pt' 2>/dev/null)"
  assert_file_contains "$runs/$id2/capsule.json" '"hashed": true'
  out="$(cd "$proj" && OMS_RUNS_DIR="$runs" \
    "$ROOT/scripts/run-capsule.sh" whence produced.pt 2>/dev/null)"
  contains "$out" "$id2" || fail "whence must trace a run-produced output"
}

test_data_manifest_check_and_leakage() {
  local d="$TMP/data-manifest"
  local md="$d/.oms/manifests"
  local SH="$ROOT/scripts/data-manifest.sh"

  mkdir -p "$d"
  printf 'a\nb\nc\n' > "$d/train.txt"
  printf 'd\ne\n' > "$d/val.txt"

  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name ds \
    --split train=train.txt --split val=val.txt >/dev/null ) || fail "create failed"
  [ -f "$md/ds.json" ] || fail "manifest not written"

  # Clean: check passes, no leakage.
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name ds >/dev/null ) ||
    fail "check should pass on unchanged splits"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" leakage --name ds >/dev/null ) ||
    fail "leakage should be clean on disjoint splits"

  # Drift: change an ID set -> check fails.
  printf 'a\nb\nZ\n' > "$d/train.txt"
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name ds >/dev/null ); then
    fail "check should report drift after ID set change"
  fi

  # Leakage: shared ID across splits -> leakage fails.
  printf 'a\nb\nc\n' > "$d/train.txt"
  printf 'd\ne\na\n' > "$d/val.txt"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name leak \
    --split train=train.txt --split val=val.txt >/dev/null ) || fail "create leak failed"
  local out
  out="$( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" leakage --name leak 2>&1 )" && \
    fail "leakage should exit nonzero on overlap"
  contains "$out" "LEAKAGE" || fail "leakage output missing LEAKAGE marker"
}

test_data_manifest_csv_column() {
  local d="$TMP/data-manifest-csv"
  local md="$d/.oms/manifests"
  local SH="$ROOT/scripts/data-manifest.sh"

  mkdir -p "$d"
  printf 'id,label\nx1,1\nx2,0\n' > "$d/train.csv"
  printf 'id,label\nx3,1\n' > "$d/test.csv"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name c --id-column id \
    --split train=train.csv --split test=test.csv >/dev/null ) || fail "csv create failed"
  # Changing only the label column must NOT count as drift (ID set is stable).
  printf 'id,label\nx1,0\nx2,1\n' > "$d/train.csv"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name c >/dev/null ) ||
    fail "label-only change must not be drift when keyed by id column"
}


test_data_manifest_key_column_leakage() {
  local d="$TMP/data-manifest-key"
  local md="$d/.oms/manifests"
  local SH="$ROOT/scripts/data-manifest.sh"

  mkdir -p "$d"
  # Disjoint IDs, but train and test share a Bemis-Murcko scaffold: exact-ID
  # overlap is clean while scaffold-level leakage is real.
  printf 'id,scaffold,y\nm1,c1ccccc1,1\nm2,C1CCCCC1,0\n' > "$d/train.csv"
  printf 'id,scaffold,y\nm3,c1ccccc1,1\n' > "$d/test.csv"

  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name c --id-column id \
    --key-column scaffold --split train=train.csv --split test=test.csv >/dev/null ) ||
    fail "key-column create failed"
  grep -Fq '"leakage_keys"' "$md/c.json" || fail "manifest should record leakage_keys"

  local out rc=0
  out="$( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" leakage --name c )" || rc=$?
  [ "$rc" = 1 ] || fail "scaffold leakage should exit 1"
  contains "$out" 'ok      train ∩ test: no overlap' ||
    fail "exact-ID overlap should be clean"
  contains "$out" 'LEAKAGE[scaffold] train ∩ test: 1 shared key(s)' ||
    fail "scaffold-level leakage must be flagged"

  # A missing key column is rejected at create (cannot silently no-op).
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name bad --id-column id \
    --key-column nope --split train=train.csv >/dev/null 2>&1 ); then
    fail "unknown key-column must fail create"
  fi

  # Every leakage report says what it did not compare, and names the policy.
  contains "$out" 'policy: none declared (checked: ID overlap; key overlap on scaffold)' ||
    fail "an undeclared policy must be reported as undeclared"
  contains "$out" 'note: exact matches only' || fail "leakage must say it compared exact matches only"

  # A declared policy is checked for what it needs before anything is written.
  dm() { ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" "$@" ); }
  dm create --name p1 --id-column id --policy scaffold --split train=train.csv >/dev/null 2>&1 &&
    fail "--policy scaffold without a key column must fail create"
  dm create --name p1 --id-column id --policy cold --split train=train.csv >/dev/null 2>&1 &&
    fail "--policy cold without an entity column must fail create"
  dm create --name p1 --id-column id --policy time --split train=train.csv >/dev/null 2>&1 &&
    fail "--policy time without a time column must fail create"
  dm create --name p1 --id-column id --policy stratified --split train=train.csv >/dev/null 2>&1 &&
    fail "an unknown policy must fail create"
  dm create --name p1 --id-column id --time-column y --split train=train.csv >/dev/null 2>&1 &&
    fail "--time-column without --policy time must fail create"
  [ ! -e "$md/p1.json" ] || fail "a refused create must not leave a manifest"

  # scaffold: the declared policy is violated by the shared key, and the report says which policy.
  dm create --name sc --id-column id --policy scaffold --key-column scaffold \
    --split train=train.csv --split test=test.csv >/dev/null || fail "scaffold policy create failed"
  rc=0; out="$(dm leakage --name sc)" || rc=$?
  [ "$rc" = 1 ] || fail "a scaffold shared across splits must exit 1 under --policy scaffold"
  contains "$out" 'policy: scaffold (checked: ID overlap; key overlap on scaffold)' ||
    fail "leakage must name the declared policy: $out"

  # cold: every entity column on its own; a shared target leaks though drugs are disjoint.
  printf 'id,drug,target,date\np1,d1,t1,2020-01-05\np2,d2,t2,2020-03-01\np2,d2,t2,2020-03-01\n' > "$d/ctrain.csv"
  printf 'id,drug,target,date\np3,d3,t1,2021-02-01\np4,d4,t9,2020-02-01\n' > "$d/ctest.csv"
  dm create --name cold --id-column id --policy cold --entity-column drug --entity-column target \
    --split train=ctrain.csv --split test=ctest.csv >/dev/null || fail "cold policy create failed"
  rc=0; out="$(dm leakage --name cold)" || rc=$?
  [ "$rc" = 1 ] || fail "a shared target must exit 1 under --policy cold"
  contains "$out" 'ok[drug]      train ∩ test: no overlap' || fail "disjoint drugs must read clean: $out"
  contains "$out" 'LEAKAGE[target] train ∩ test: 1 shared key(s)' || fail "the shared target must be flagged: $out"
  # A row repeated inside one split is a warning, never the exit code.
  contains "$out" 'WARN    train: 1 ID(s) appear more than once inside the split' ||
    fail "a repeated ID inside a split must be warned about: $out"
  dm check --name cold >/dev/null || fail "entity columns must be fingerprinted like key columns"

  # time: splits are listed oldest first; one test row older than the newest train row leaks.
  dm create --name tm --id-column id --policy time --time-column date \
    --split train=ctrain.csv --split test=ctest.csv >/dev/null || fail "time policy create failed"
  rc=0; out="$(dm leakage --name tm)" || rc=$?
  [ "$rc" = 1 ] || fail "a test row older than train must exit 1 under --policy time"
  contains "$out" 'LEAKAGE[time:date] train -> test: 1 row(s) of test are not later than the newest train row' ||
    fail "the out-of-order row must be counted: $out"
  ! contains "$out" '2020-03-01' || fail "time values stay out of the report without --show-examples"
  out="$(dm leakage --name tm --show-examples)" || true
  contains "$out" 'newest train: 2020-03-01; oldest test: 2020-02-01' || fail "--show-examples must show the boundary: $out"
  printf 'id,drug,target,date\np3,d3,t1,2021-02-01\np4,d4,t9,2020-03-02\n' > "$d/ctest.csv"
  dm create --name tm --id-column id --policy time --time-column date \
    --split train=ctrain.csv --split test=ctest.csv >/dev/null || fail "time policy recreate failed"
  out="$(dm leakage --name tm)" || fail "an ordered time split must pass: $out"
  contains "$out" 'ok[time:date]      train -> test: every test row is later' || fail "ordered splits must read ok: $out"
  # Numbers order as numbers (9 < 10), and a column that is neither fails closed.
  printf 'id,t\na,9\n' > "$d/n1.csv"; printf 'id,t\nb,10\n' > "$d/n2.csv"
  dm create --name num --id-column id --policy time --time-column t --split a=n1.csv --split b=n2.csv >/dev/null ||
    fail "numeric time create failed"
  dm leakage --name num >/dev/null || fail "numeric time values must order as numbers"
  printf 'id,t\nb,soon\n' > "$d/n2.csv"
  rc=0; dm leakage --name num >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "an unorderable time column must fail closed (exit 2), got $rc"

  # Where the keys came from: the command as text, the script by digest; check warns, never drifts.
  printf 'print("scaffold")\n' > "$d/keys.py"
  dm create --name dv --id-column id --policy scaffold --key-column scaffold \
    --derive-cmd 'python keys.py   train.csv' --derive-script keys.py --split train=train.csv >/dev/null ||
    fail "derive create failed"
  grep -Fq '"cmd": "python keys.py train.csv"' "$md/dv.json" || fail "derive command must be recorded as one line"
  grep -Fq '"script_sha256"' "$md/dv.json" || fail "derive script digest must be recorded"
  out="$(dm check --name dv)" || fail "an unchanged key script must not fail check"
  contains "$out" 'ok    derive: key script unchanged' || fail "check must report the key script: $out"
  printf 'print("scaffold v2")\n' > "$d/keys.py"
  out="$(dm check --name dv)" || fail "a changed key script is a warning, not drift"
  contains "$out" 'WARN  derive: key script changed since the manifest was written' ||
    fail "check must warn about a changed key script: $out"
  dm create --name dv2 --id-column id --derive-script nope.py --split train=train.csv >/dev/null 2>&1 &&
    fail "a missing --derive-script must fail create"

  # Provenance: upstream sources, why this split, what a key column identifies. Labels and text only.
  local dig; dig="$(printf 'ab%.0s' $(seq 32))"
  dm create --name pv --id-column id --policy cold --entity-column drug --entity-column target \
    --entity-kind drug=ligand --entity-kind target=protein \
    --source pdbbind=v2020 --source chembl=34 --source-digest pdbbind="$dig" \
    --split-rationale 'cold by protein family: test families unseen in train' \
    --split train=ctrain.csv --split test=ctest.csv >/dev/null || fail "provenance create failed"
  grep -Fq '"ref": "v2020"' "$md/pv.json" || fail "a source reference must be stored as given"
  grep -Fq "\"sha256\": \"$dig\"" "$md/pv.json" || fail "a source digest must be stored"
  grep -Fq '"entity_kinds"' "$md/pv.json" || fail "entity kinds must be stored"
  dm show --name pv | grep -Fq 'cold by protein family' || fail "show must print the rationale"
  out="$(dm check --name pv)" || fail "provenance must not make check fail: $out"
  contains "$out" 'info  source chembl: 34' || fail "check must print the sources: $out"
  contains "$out" 'info  split rationale: cold by protein family' || fail "check must print the rationale: $out"
  rc=0; out="$(dm leakage --name pv)" || rc=$?
  [ "$rc" = 1 ] || fail "the shared target still leaks under a labelled cold policy (exit 1), got $rc"
  contains "$out" 'policy: cold by ligand+protein (checked:' || fail "leakage must use the entity kinds: $out"
  contains "$out" 'rationale: cold by protein family' || fail "leakage must print the rationale: $out"
  ! contains "$out" 'WARN    policy' || fail "a labelled policy with a rationale must not warn: $out"
  # No kind or no rationale under cold/scaffold: advisory warning, exit code unchanged.
  rc=0; out="$(dm leakage --name cold)" || rc=$?
  [ "$rc" = 1 ] || fail "the advisory warning must not change the exit code, got $rc"
  contains "$out" 'WARN    policy cold has no --entity-kind recorded' || fail "missing entity kind must warn: $out"
  contains "$out" 'WARN    policy cold has no --split-rationale recorded' || fail "missing rationale must warn: $out"
  contains "$out" 'policy: cold (checked:' || fail "an old-style manifest keeps its policy line: $out"
  out="$(dm check --name cold)" || fail "an old-style manifest must still check"
  ! contains "$out" 'info  ' || fail "an old-style manifest prints no provenance lines: $out"
  # Refusals are exit 2, leave no manifest, and never echo the reference.
  local bad at='@'  # kept out of the literals so the outbound scrubber does not see a URL credential
  for bad in \
    "--source x=gh""p_aaaaaaaaaaaaaaaaaaaaaaaaaaaa" \
    "--source x=https://user:pw${at}host.example/archive" \
    "--source x=https://user${at}host.example/archive" \
    "--source x=" "--source =v1" "--source nameonly" \
    "--source-digest pdbbind=$dig" "--source-digest x=nothex" \
    "--entity-kind drug=molecule" "--entity-kind nope=ligand" ; do
    rc=0
    # shellcheck disable=SC2086
    out="$(dm create --name bad --id-column id --policy cold --entity-column drug $bad \
      --split train=ctrain.csv 2>&1 >/dev/null)" || rc=$?
    [ "$rc" = 2 ] || fail "refused provenance must exit 2 ($bad), got $rc"
    ! contains "$out" 'aaaaaaaaaa' || fail "a refused reference must not be echoed: $out"
  done
  rc=0; dm create --name bad --id-column id --source x=v1 --source-digest x=0123 --split train=ctrain.csv \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a short source digest must exit 2, got $rc"
  rc=0; dm create --name bad --id-column id --split-rationale '   ' --split train=ctrain.csv \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a blank rationale must exit 2, got $rc"
  rc=0; dm create --name bad --id-column id --source x=v1 --source x=v2 --split train=ctrain.csv \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a repeated source name must exit 2, got $rc"
  [ ! -e "$md/bad.json" ] || fail "a refused provenance create must not leave a manifest"
  return 0
}

test_data_manifest_fail_closed_and_name() {
  local d="$TMP/data-manifest-failclosed"
  local md="$d/.oms/manifests"
  local SH="$ROOT/scripts/data-manifest.sh"

  mkdir -p "$d"
  printf 'id,scaffold,y\nm1,s1,1\nm2,s2,0\n' > "$d/train.csv"
  printf 'id,scaffold,y\nm3,s3,1\n' > "$d/test.csv"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name c --id-column id \
    --key-column scaffold --split train=train.csv --split test=test.csv >/dev/null ) ||
    fail "create failed"

  # A recorded split file that disappears must fail the leakage gate, not pass.
  mv "$d/test.csv" "$d/test.csv.bak"
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" leakage --name c >/dev/null 2>&1 ); then
    fail "leakage must fail closed when a recorded split file is missing"
  fi
  mv "$d/test.csv.bak" "$d/test.csv"

  # A recorded key column that disappears (header drift) must fail closed.
  printf 'id,y\nm3,1\n' > "$d/test.csv"
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" leakage --name c >/dev/null 2>&1 ); then
    fail "leakage must fail closed when a recorded key column is gone"
  fi

  # A recorded id column that disappears must fail closed too.
  printf 'scaffold,y\ns3,1\n' > "$d/test.csv"
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" leakage --name c >/dev/null 2>&1 ); then
    fail "leakage must fail closed when the recorded id column is gone"
  fi

  # Path-traversal / unsafe manifest names are rejected.
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name ../escape \
    --split train=train.csv >/dev/null 2>&1 ); then
    fail "create must reject a name with path traversal"
  fi
  [ ! -e "$d/.oms/escape.json" ] || fail "traversal name must not have written outside MANIFEST_DIR"

  # --id-column and --id-index together are ambiguous and rejected.
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name c2 --id-column id --id-index 0 \
    --split train=train.csv >/dev/null 2>&1 ); then
    fail "--id-column and --id-index must be mutually exclusive"
  fi
}

test_data_manifest_key_set_drift() {
  local d="$TMP/data-manifest-keydrift"
  local md="$d/.oms/manifests"
  local SH="$ROOT/scripts/data-manifest.sh"

  mkdir -p "$d"
  printf 'id,scaffold,y\nm1,s1,1\nm2,s2,0\n' > "$d/train.csv"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name c --id-column id \
    --key-column scaffold --split train=train.csv >/dev/null ) || fail "create failed"
  grep -Fq '"keys"' "$md/c.json" || fail "manifest should fingerprint key sets"

  # Changing a non-key column (label) with the ID and scaffold sets stable: WARN, not drift.
  printf 'id,scaffold,y\nm1,s1,0\nm2,s2,1\n' > "$d/train.csv"
  local out
  out="$( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name c )" ||
    fail "label-only change must not be drift"
  contains "$out" 'WARN' || fail "expected WARN for byte-only change"

  # Changing the scaffold assignment (ID set still identical) IS drift.
  printf 'id,scaffold,y\nm1,sX,0\nm2,s2,1\n' > "$d/train.csv"
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name c >"$d/out2" 2>&1 ); then
    fail "changed key set must be reported as drift (nonzero)"
  fi
  grep -Fq "key 'scaffold'" "$d/out2" || fail "drift message should name the changed key"
}

test_data_manifest_key_mapping_drift_and_empty() {
  local d="$TMP/data-manifest-keymap"
  local md="$d/.oms/manifests"
  local SH="$ROOT/scripts/data-manifest.sh"

  mkdir -p "$d"
  # One row has an empty scaffold (legitimate: acyclic molecule has no Murcko scaffold).
  printf 'id,scaffold\nm1,sA\nm2,sB\nm3,\n' > "$d/train.csv"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name c --id-column id \
    --key-column scaffold --split train=train.csv >/dev/null ) || fail "create failed"
  # Empty key value is recorded, not dropped silently.
  python3 -c 'import json,sys; m=json.load(open(sys.argv[1]))
e=m["splits"][0]["keys"]["scaffold"]["empty"]
sys.exit(0 if e==1 else 1)' "$md/c.json" || fail "empty key count should be recorded (expected 1)"

  # Permute the scaffold assignment (m1<->m2): the value SET {sA,sB} is identical
  # but the id->scaffold mapping changed. Must be drift, not WARN.
  printf 'id,scaffold\nm1,sB\nm2,sA\nm3,\n' > "$d/train.csv"
  if ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name c >"$d/out" 2>&1 ); then
    fail "permuted id->key mapping must be reported as drift"
  fi
  grep -Fq "key 'scaffold'" "$d/out" || fail "drift should name the remapped key"

  # A manifest predating pair_sha256 (keys recorded, no pair field) must not
  # false-drift on an unchanged file.
  printf 'id,scaffold\nm1,sA\nm2,sB\nm3,\n' > "$d/train.csv"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name old --id-column id \
    --key-column scaffold --split train=train.csv >/dev/null ) || fail "create failed"
  python3 -c 'import json,sys
p=sys.argv[1]; m=json.load(open(p))
for s in m["splits"]:
    for kv in s.get("keys",{}).values(): kv.pop("pair_sha256",None)
json.dump(m,open(p,"w"))' "$md/old.json"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name old >/dev/null ) ||
    fail "manifest without pair_sha256 must not false-drift on unchanged file"
}

test_data_manifest_reads_schema1() {
  local d="$TMP/data-manifest-schema1"
  local md="$d/.oms/manifests"
  local SH="$ROOT/scripts/data-manifest.sh"

  mkdir -p "$d"
  printf 'a\nb\n' > "$d/train.txt"
  printf 'c\n' > "$d/test.txt"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name c \
    --split train=train.txt --split test=test.txt >/dev/null ) || fail "create failed"

  # Downgrade the manifest to a pre-key-column schema-1 shape and confirm the
  # current tool still reads it (check + leakage) without error.
  python3 - "$md/c.json" <<'PY'
import json, sys
p = sys.argv[1]; m = json.load(open(p))
m["schema"] = 1
m.pop("leakage_keys", None)
for s in m["splits"]:
    s.pop("keys", None)
json.dump(m, open(p, "w"))
PY
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name c >/dev/null ) ||
    fail "schema-1 manifest must still pass check"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" leakage --name c >/dev/null ) ||
    fail "schema-1 manifest must still run leakage"
}

test_data_manifest_hostile_split_values() {
  local d="$TMP/data-manifest-hostile"
  local md="$d/.oms/manifests"
  local SH="$ROOT/scripts/data-manifest.sh"
  local label=$'train/odd\tA\nB'
  local file=$'-split a=b\tc\nn.txt'

  mkdir -p "$d"
  printf 'a\nb\n' > "$d/$file"
  printf 'c\nd\n' > "$d/val.txt"

  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" create --name weird \
    --split "$label=$file" --split val=val.txt >/dev/null ) ||
    fail "hostile split create failed"
  python3 -m json.tool "$md/weird.json" >/dev/null || fail "manifest must be valid JSON"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" check --name weird >/dev/null ) ||
    fail "hostile split check should round-trip"
  ( cd "$d" && OMS_MANIFEST_DIR="$md" "$SH" leakage --name weird >/dev/null ) ||
    fail "hostile split leakage should not misparse labels or paths"
}

test_generate_slurm_reference_captures_effective_resources() {
  local d="$TMP/slurm-reference"
  local bin="$d/bin"
  local out="$d/cluster.md"
  local capture="$d/commands.log"

  mkdir -p "$bin"
  cat > "$bin/sinfo" <<'EOF'
#!/usr/bin/env bash
case "$*" in
  *'%P|%a|%l|%D|%G|%m|%c|%N'*)
    printf 'gpu*|up|2-00:00:00|2|gpu:a100:4|512000|64|gpu[01-02]\n'
    ;;
  *'%P|%l|%D|%G|%c|%N'*)
    printf 'gpu*|2-00:00:00|2|gpu:a100:4|64|gpu[01-02]\n'
    ;;
  *'%P'*) printf 'gpu*\n' ;;
esac
EOF
  cat > "$bin/squeue" <<'EOF'
#!/usr/bin/env bash
printf 'JOBID PARTITION NAME ST TIME NODES NODELIST(REASON)\n'
EOF
  cat > "$bin/scontrol" <<'EOF'
#!/usr/bin/env bash
printf 'scontrol %s\n' "$*" >> "$SLURM_CAPTURE"
case "$*" in
  '-o show partition')
    printf '%s\n' 'PartitionName=gpu Default=YES QoS=high AllowQos=high,normal DefaultTime=01:00:00 MaxTime=2-00:00:00 MaxCPUsPerNode=64 Nodes=gpu[01-02] State=UP TotalCPUs=128 TotalNodes=2 DefMemPerCPU=8192 MaxMemPerCPU=16384 JobDefaults=DefCpuPerGPU=8,DefMemPerGPU=65536 TRES=cpu=128,mem=1000G,node=2,gres/gpu=8'
    ;;
  '-o show node')
    printf '%s\n' \
      'NodeName=gpu01 State=IDLE CPUs=64 AllocCPUs=0 RealMemory=512000 FreeMem=500000 Gres=gpu:a100:4 CfgTRES=cpu=64,mem=500G,gres/gpu=4 Partitions=gpu' \
      'NodeName=gpu02 State=MIXED CPUs=64 AllocCPUs=16 RealMemory=512000 FreeMem=410000 Gres=gpu:a100:4 CfgTRES=cpu=64,mem=500G,gres/gpu=4 Partitions=gpu'
    ;;
esac
EOF
  cat > "$bin/sacctmgr" <<'EOF'
#!/usr/bin/env bash
printf 'sacctmgr %s\n' "$*" >> "$SLURM_CAPTURE"
case "$*" in
  *'show assoc'*)
    printf '%s\n' 'cluster-a|acct-a|alice|gpu|high|high,normal|cpu=64,mem=512G|gres/gpu=4|gres/gpu=2|8|32|2-00:00:00'
    ;;
  *'show qos'*)
    printf '%s\n' 'high|100|normal|REQUEUE||1.0|cpu=128,gres/gpu=8|gres/gpu=4|gres/gpu=2|2-00:00:00|8|32'
    ;;
esac
EOF
  chmod +x "$bin/sinfo" "$bin/squeue" "$bin/scontrol" "$bin/sacctmgr"

  SLURM_CAPTURE="$capture" USER=alice PATH="$bin:/usr/bin:/bin" \
    OH_MY_SETTING_SLURM_REF="$out" \
    "$ROOT/scripts/generate-slurm-reference.sh" >/dev/null

  assert_file_contains "$capture" 'sacctmgr -nP show assoc user=alice'
  assert_file_contains "$capture" 'sacctmgr -nP show qos'
  assert_file_contains "$capture" 'scontrol -o show partition'
  assert_file_contains "$capture" 'scontrol -o show node'
  assert_file_contains "$out" '## Associations (current user)'
  assert_file_contains "$out" 'cluster-a|acct-a|alice|gpu|high|high,normal|cpu=64,mem=512G'
  assert_file_contains "$out" '## QOS'
  assert_file_contains "$out" 'high|100|normal|REQUEUE'
  assert_file_contains "$out" '## Partition Configuration'
  assert_file_contains "$out" 'DefMemPerCPU=8192'
  assert_file_contains "$out" 'JobDefaults=DefCpuPerGPU=8,DefMemPerGPU=65536'
  assert_file_contains "$out" '## Node Configuration'
  assert_file_contains "$out" 'NodeName=gpu01 State=IDLE CPUs=64'
  assert_file_contains "$out" '- Account: acct-a'
  assert_file_contains "$out" '- QOS default: high'
  assert_file_contains "$out" '- CPU default: DefCpuPerGPU=8'
  assert_file_contains "$out" '- Memory default: DefMemPerCPU=8192, DefMemPerGPU=65536'
  assert_file_contains "$out" '- Time default: 01:00:00'

  # slurm-lint reads that snapshot's QOS table: the default QOS "high" preempts
  # by REQUEUE with a two-day MaxWall. It reads the script and never runs it.
  local lint="$d/lint" LINT="$ROOT/scripts/slurm-lint.sh" rc
  mkdir -p "$lint"
  printf '%s\n' '#!/bin/bash' '#SBATCH -o run.log' '#SBATCH --array=0-9' '#SBATCH -t 3-00:00:00' \
    ': > "'"$lint"'/executed"' '#SBATCH --requeue' > "$lint/bad.sh"
  rc=0
  "$LINT" "$lint/bad.sh" --snapshot "$out" > "$lint/bad.out" 2>&1 || rc=$?
  [ "$rc" = 1 ] || fail "slurm-lint must exit 1 on warnings (got $rc): $(cat "$lint/bad.out")"
  [ ! -e "$lint/executed" ] || fail "slurm-lint must not run the script"
  assert_file_contains "$lint/bad.out" "5 warning(s); static check, nothing was submitted or run"
  assert_file_contains "$lint/bad.out" "warn: log: --output run.log is not job-specific"
  assert_file_contains "$lint/bad.out" "warn: array: --array 0-9 has no concurrency limit"
  # A directive after the first command is a comment to sbatch, so --requeue was not asked for.
  assert_file_contains "$lint/bad.out" "warn: requeue: QOS high preempts by REQUEUE but the script does not ask for --requeue"
  assert_file_contains "$lint/bad.out" "warn: signal: QOS high requeues, and the script has neither --signal nor a trap"
  assert_file_contains "$lint/bad.out" "warn: maxwall: --time 3-00:00:00 is longer than QOS high MaxWall 2-00:00:00"
  # A trap in the batch shell never fires unless the signal is sent to it (B:).
  printf '%s\n' '#!/bin/bash' '#SBATCH --time=30' '#SBATCH --requeue' '#SBATCH --signal=USR1@60' \
    '#SBATCH --array=0-9%2' '#SBATCH --output=logs/%A.out' "trap 'true' USR1" 'srun true' > "$lint/step.sh"
  rc=0
  "$LINT" "$lint/step.sh" --snapshot "$out" > "$lint/step.out" 2>&1 || rc=$?
  [ "$rc" = 1 ] || fail "slurm-lint should warn about a step-only signal (got $rc)"
  assert_file_contains "$lint/step.out" "warn: signal: --signal=USR1@60 reaches the job steps only"
  assert_file_contains "$lint/step.out" "warn: log: --output logs/%A.out is shared by every array task: add %a"
  assert_file_contains "$lint/step.out" "2 warning(s)"
  # The template it prints is clean against a requeueing QOS once the time is filled in.
  "$LINT" --template | sed 's/TODO-D-HH:MM:SS/1-00:00:00/' > "$lint/job.sh"
  cmp -s <("$LINT" --template) "$ROOT/templates/slurm-job.sh" || fail "--template must print templates/slurm-job.sh"
  bash -n "$lint/job.sh" || fail "the job template must parse"
  "$LINT" "$lint/job.sh" --snapshot "$out" > "$lint/job.out" 2>&1 ||
    fail "the job template should lint clean: $(cat "$lint/job.out")"
  assert_file_contains "$lint/job.out" "0 warning(s)"
  # A QOS that does not requeue gets no requeue warning, and says why.
  printf '%s\n' '#!/bin/bash' '#SBATCH --time=10' '#SBATCH --qos=normal' 'true' > "$lint/plain.sh"
  printf '%s\n' '## QOS' '' 'Name|PreemptMode|MaxWall' 'normal|CANCEL|01:00:00' > "$lint/snap.md"
  "$LINT" "$lint/plain.sh" --snapshot "$lint/snap.md" > "$lint/plain.out" 2>&1 || fail "a non-requeue QOS should lint clean"
  assert_file_contains "$lint/plain.out" "note: preemption: QOS normal PreemptMode is CANCEL; no requeue check applies"
  # No snapshot, or a QOS it does not list, is unknown: said so, never a pass on preemption.
  "$LINT" "$lint/plain.sh" --snapshot "$lint/missing.md" > "$lint/unknown.out" 2>&1 || fail "lint without a snapshot failed"
  assert_file_contains "$lint/unknown.out" "note: preemption: unknown (no cluster snapshot; run: oms snapshot --cluster)"
  "$LINT" "$lint/plain.sh" --snapshot "$out" > "$lint/unlisted.out" 2>&1 || fail "lint with an unlisted QOS failed"
  assert_file_contains "$lint/unlisted.out" "note: preemption: unknown (QOS normal is not in the snapshot)"
  # --preview: request totals from #SBATCH lines against the snapshot's GPU limits, with its age; nothing runs.
  printf '%s\n' '# Local Slurm Cluster' '' 'Generated: 2026-01-01T00:00:00Z' '' '- QOS default: high' '' \
    '## Associations (current user)' '' 'Cluster|Account|User|Partition|DefaultQOS|QOS|GrpTRES|MaxTRES|MaxTRESPJ|MaxJobs|MaxSubmit|MaxWall' \
    'c|a|alice|gpu|high|high|gres/gpu=8||gres/gpu=4|||' '' '## QOS' '' \
    'Name|Priority|Preempt|PreemptMode|Flags|UsageFactor|GrpTRES|MaxTRESPU|MaxTRESPJ|MaxWall|MaxJobsPU|MaxSubmitPU' \
    'high|100|normal|REQUEUE||1||gres/gpu=6|gres/gpu=2|2-00:00:00||' > "$lint/pv-snap.md"
  printf '%s\n' '#!/bin/bash' '#SBATCH --gres=gpu:a100:2' '#SBATCH -t 1-00:00:00' '#SBATCH --array=0-9%4' \
    ': > "'"$lint"'/pv-executed"' > "$lint/pv.sh"
  rc=0
  "$LINT" --preview "$lint/pv.sh" --snapshot "$lint/pv-snap.md" > "$lint/pv.out" 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "slurm-lint --preview must exit 0 (got $rc): $(cat "$lint/pv.out")"
  [ ! -e "$lint/pv-executed" ] || fail "slurm-lint --preview must not run the script"
  assert_file_contains "$lint/pv.out" "GPU-hours, upper bound       480.0"
  assert_file_contains "$lint/pv.out" "GPUs held at once, peak      8"
  assert_file_contains "$lint/pv.out" "older than 7 days"
  assert_file_contains "$lint/pv.out" "QOS high MaxTRESPJ                           gres/gpu=2    per job asks 2    within"
  assert_file_contains "$lint/pv.out" "OVER by 2"
  assert_file_contains "$lint/pv.out" "Slurm --test-only was not used"
  # Without --time or a snapshot the totals are unknown, never a guess.
  printf '%s\n' '#!/bin/bash' '#SBATCH --gpus=4' > "$lint/pv-bare.sh"
  "$LINT" --preview "$lint/pv-bare.sh" --snapshot "$lint/missing.md" > "$lint/pv-bare.out" 2>&1 || fail "preview without a snapshot failed"
  assert_file_contains "$lint/pv-bare.out" "GPU-hours, upper bound       unknown"
  assert_file_contains "$lint/pv-bare.out" "snapshot: none readable"
  rc=0
  "$LINT" "$lint/absent.sh" > /dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "slurm-lint must exit 2 for an unreadable script (got $rc)"
}

# Stub sacct/squeue: terminal states for given ids, RUNNING otherwise.
write_fake_slurm() {
  local bin="$1"
  mkdir -p "$bin"
  cat > "$bin/sacct" <<'EOF'
#!/usr/bin/env bash
jid=""; prev=""
for a in "$@"; do [ "$prev" = "-j" ] && jid="$a"; prev="$a"; done
case "$jid" in
  3001) echo "COMPLETED|0:0|00:10:00" ;;
  3002) echo "FAILED|1:0|00:02:00" ;;
  3004) echo "CANCELLED by 1000|0:15|00:00:05" ;;
  3005) printf '%s\n' "COMPLETED|0:0|00:01:00" "RUNNING|0:0|00:02:00" ;;
  3006) printf '%s\n' "COMPLETED|0:0|00:01:00" "FAILED|1:0|00:02:00" ;;
  # Rows in the fields run-reconcile asks for (JobID first). 3007 is an array;
  # 3008 is preempted and requeued until "$0.done" exists, then its second
  # record completes; 3009 lost its node and was not requeued.
  3007) printf '%s\n' \
    "3007_1|COMPLETED|0:0|00:01:00|c1|2026-01-02T03:00:00|2026-01-02T03:01:00|2026-01-02T03:02:00|billing=4,cpu=4,gres/gpu=1|gpu01" \
    "3007_2|OUT_OF_MEMORY|0:125|00:00:30|c1|2026-01-02T03:00:00|2026-01-02T03:01:00|2026-01-02T03:01:30|billing=4,cpu=4,gres/gpu=1|gpu02" ;;
  3008) echo "3008|PREEMPTED|0:0|00:05:00|c1|2026-01-02T04:00:00|2026-01-02T04:01:00|2026-01-02T04:06:00|cpu=8|gpu01"
    [ ! -e "$0.done" ] ||
      echo "3008|COMPLETED|0:0|00:07:00|c1|2026-01-02T04:06:00|2026-01-02T04:10:00|2026-01-02T04:17:00|cpu=8|gpu03" ;;
  3009) echo "3009|NODE_FAIL|0:0|00:00:40|c1|2026-01-02T05:00:00|2026-01-02T05:01:00|Unknown||None assigned" ;;
  # 3010 carries the limit and CPU fields too: two GPUs for 30 minutes of a
  # one-hour limit, 16 CPUs that did four CPU-hours of work.
  3010) echo "3010|COMPLETED|0:0|00:30:00|c1|2026-01-02T06:00:00|2026-01-02T06:10:00|2026-01-02T06:40:00|billing=16,cpu=16,gres/gpu:a100=2,mem=64G|gpu04|01:00:00|16|04:00:00" ;;
  *) : ;;
esac
EOF
  cat > "$bin/squeue" <<'EOF'
#!/usr/bin/env bash
jid=""; prev=""
for a in "$@"; do [ "$prev" = "-j" ] && jid="$a"; prev="$a"; done
case "$jid" in
  3003) echo "RUNNING" ;;
  3008) [ -e "${0%/*}/sacct.done" ] || echo "PENDING" ;;
esac
EOF
  chmod +x "$bin/sacct" "$bin/squeue"
}

# smoke-weight: 5
test_run_reconcile_records_terminal_jobs() {
  local d="$TMP/reconcile"
  local bin="$d/bin"
  local SH="$ROOT/scripts/run-reconcile.sh"

  mkdir -p "$d"
  write_fake_slurm "$bin"
  # A login-node submission records the id sbatch printed, plain or --parsable.
  printf '#!/bin/sh\ncase "$1" in --parsable) echo "3002" ;; -M) echo "Submitted batch job 3101 on cluster c1" ;; -Mp) echo "3102;c1" ;; -S) echo "Submitted batch job 3201"; sleep 2 ;; *) echo "Submitted batch job 3001" ;; esac\n' > "$bin/sbatch"
  chmod +x "$bin/sbatch"
  ( cd "$d" && env -u SLURM_JOB_ID PATH="$bin:$PATH" "$ROOT/scripts/run-ledger.sh" --file "$d/ledger.jsonl" -- sbatch job.sh &&
    env -u SLURM_JOB_ID PATH="$bin:$PATH" "$ROOT/scripts/run-ledger.sh" --file "$d/ledger.jsonl" -- sbatch --parsable job.sh &&
    env SLURM_JOB_ID=9000 PATH="$bin:$PATH" "$ROOT/scripts/run-ledger.sh" --file "$d/ledger.jsonl" -- sbatch -M job.sh &&
    env -u SLURM_JOB_ID PATH="$bin:$PATH" "$ROOT/scripts/run-ledger.sh" --file "$d/ledger.jsonl" -- sbatch -Mp job.sh ) >"$d/submit.out" 2>&1 ||
    fail "ledgered sbatch failed"
  # A cluster-qualified id could name another cluster's job: record none.
  assert_file_contains "$d/submit.out" "on cluster c1"
  [ "$(grep -c '"slurm_job_id": ""' "$d/ledger.jsonl")" = 2 ] ||
    fail "cluster-qualified sbatch ids must not be recorded"
  # An inherited SLURM_JOB_ID names the submitting job, not the submission.
  if grep -Fq '"slurm_job_id": "9000"' "$d/ledger.jsonl"; then
    fail "a submission must not record the inherited SLURM_JOB_ID"
  fi
  # The id streams live while sbatch is still running.
  ( cd "$d" && PATH="$bin:$PATH" "$ROOT/scripts/run-ledger.sh" --file "$d/live.jsonl" -- sbatch -S job.sh >"$d/live.out" 2>&1 ) &
  local live_pid=$! live_i=0
  while ! grep -Fq 3201 "$d/live.out" 2>/dev/null && [ "$live_i" -lt 60 ]; do
    sleep 0.05
    live_i=$((live_i + 1))
  done
  kill -0 "$live_pid" 2>/dev/null || fail "sbatch output must stream before the command exits"
  wait "$live_pid" || fail "streamed sbatch failed"
  assert_file_contains "$d/live.jsonl" '"slurm_job_id": "3201"'
  assert_file_contains "$d/submit.out" "Submitted batch job 3001"
  {
    printf '%s\n' '{"ts":"t","slurm_job_id":"3003","exit":0,"note":"C","cmd":["c"]}'
    printf '%s\n' '{"ts":"t","slurm_job_id":"","exit":0,"note":"local","cmd":["d"]}'
    printf '%s\n' '{"ts":"t","slurm_job_id":"3004","exit":0,"note":"E","cmd":["e"]}'
    printf '%s\n' '{"ts":"t","slurm_job_id":"3005","exit":0,"note":"F","cmd":["f"]}'
    printf '%s\n' '{"ts":"t","slurm_job_id":"3006","exit":0,"note":"G","cmd":["g"]}'
  } >> "$d/ledger.jsonl"

  local env_pfx=(
    "OMS_SACCT_CMD=$bin/sacct" "OMS_SQUEUE_CMD=$bin/squeue"
    "OMS_RECONCILE_FILE=$d/.oms/runs/reconcile.jsonl"
    "OMS_RECONCILE_DIGEST_DIR=$d/dg"
  )
  ( cd "$d" && env "${env_pfx[@]}" "$SH" apply --ledger "$d/ledger.jsonl" >"$d/out" 2>&1 ) || fail "apply failed"
  assert_file_contains "$d/.oms/runs/reconcile.jsonl" '"job_id": "3001"'
  assert_file_contains "$d/.oms/runs/reconcile.jsonl" '"state": "COMPLETED"'
  assert_file_contains "$d/.oms/runs/reconcile.jsonl" '"job_id": "3002"'
  assert_file_contains "$d/.oms/runs/reconcile.jsonl" '"state": "FAILED"'
  # 3003 is RUNNING -> must NOT be reconciled; empty id is ignored.
  if grep -Fq '"job_id": "3003"' "$d/.oms/runs/reconcile.jsonl"; then
    fail "running job must not be reconciled"
  fi
  # "CANCELLED by <uid>" keeps its first word; array rows aggregate.
  assert_file_contains "$d/.oms/runs/reconcile.jsonl" '"job_id": "3004", "state": "CANCELLED"'
  if grep -Fq '"job_id": "3005"' "$d/.oms/runs/reconcile.jsonl"; then
    fail "array job with a running task must not be reconciled"
  fi
  assert_file_contains "$d/.oms/runs/reconcile.jsonl" '"job_id": "3006", "state": "FAILED", "exit_code": "1:0"'

  # Idempotent: a second apply reconciles nothing new.
  local before after
  before="$(wc -l < "$d/.oms/runs/reconcile.jsonl")"
  ( cd "$d" && env "${env_pfx[@]}" "$SH" apply --ledger "$d/ledger.jsonl" >/dev/null 2>&1 ) || fail "second apply failed"
  after="$(wc -l < "$d/.oms/runs/reconcile.jsonl")"
  [ "$before" = "$after" ] || fail "reconcile is not idempotent"

  # sacct's own fields land on the row: cluster, times, allocation, and each
  # array task's ending beside the aggregate.
  local rec="$d/.oms/runs/reconcile.jsonl" sacct_only=("OMS_SACCT_CMD=$bin/sacct" "OMS_SQUEUE_CMD=$bin/squeue")
  ( cd "$d" && env "${env_pfx[@]}" "$SH" apply --job 3007 >"$d/array.out" 2>&1 ) || fail "array apply failed"
  assert_file_contains "$rec" '"job_id": "3007", "state": "OUT_OF_MEMORY", "exit_code": "0:125"'
  assert_file_contains "$rec" '"cluster": "c1", "submit": "2026-01-02T03:00:00", "start": "2026-01-02T03:01:00", "end": "2026-01-02T03:02:00", "alloc_tres": "billing=4,cpu=4,gres/gpu=1", "nodelist": "gpu01"'
  assert_file_contains "$rec" '"task_states": {"COMPLETED": 1, "OUT_OF_MEMORY": 1}'
  assert_file_contains "$rec" '{"id": "3007_2", "state": "OUT_OF_MEMORY", "exit_code": "0:125", "elapsed": "00:00:30"}'
  ( cd "$d" && env "${sacct_only[@]}" "$SH" scan --job 3007 >"$d/array.scan" 2>&1 ) || fail "array scan failed"
  assert_file_contains "$d/array.scan" "3007	OUT_OF_MEMORY	tasks: COMPLETED=1, OUT_OF_MEMORY=1"

  # PREEMPTED with the id still queued is a requeue, not an ending: nothing is
  # recorded until the next attempt finishes, and that row carries the count.
  ( cd "$d" && env "${env_pfx[@]}" "$SH" apply --job 3008 >"$d/requeue.out" 2>&1 ) || fail "requeued apply failed"
  assert_file_contains "$d/requeue.out" "requeued: job 3008 (requeued after PREEMPTED, attempt 2); not recorded as finished"
  assert_file_contains "$d/requeue.out" "0 reconciled, 1 still running/pending"
  if grep -Fq '"job_id": "3008"' "$rec"; then
    fail "a preempted job that was requeued must not be recorded as finished"
  fi
  ( cd "$d" && env "${sacct_only[@]}" "$SH" scan --job 3008 >"$d/requeue.scan" 2>&1 ) || fail "requeued scan failed"
  assert_file_contains "$d/requeue.scan" "3008	REQUEUED	requeued after PREEMPTED, attempt 2"
  : > "$bin/sacct.done"
  ( cd "$d" && env "${env_pfx[@]}" "$SH" apply --job 3008 >"$d/requeue2.out" 2>&1 ) || fail "second-attempt apply failed"
  assert_file_contains "$rec" '"job_id": "3008", "state": "COMPLETED", "exit_code": "0:0", "elapsed": "00:07:00"'
  assert_file_contains "$rec" '"submit": "2026-01-02T04:00:00", "start": "2026-01-02T04:10:00", "end": "2026-01-02T04:17:00"'
  assert_file_contains "$rec" '"nodelist": "gpu03", "attempts": 2, "requeues": 1'
  ( cd "$d" && env "${env_pfx[@]}" OMS_RECONCILE_FILE="$rec" "$SH" list 20 >"$d/list.out" 2>&1 ) || fail "list failed"
  assert_file_contains "$d/list.out" "job=3008  COMPLETED  exit=0:0  00:07:00  on c1  requeues=1"
  assert_file_contains "$d/list.out" "job=3007  OUT_OF_MEMORY  exit=0:125  00:00:30  on c1  tasks=COMPLETED:1,OUT_OF_MEMORY:1"

  # NODE_FAIL that left the queue is an ending; sacct's "Unknown" and "None
  # assigned" are absent fields, not values. An earlier submission that used
  # the same id does not hide this one.
  printf '%s\n' '{"schema": 1, "job_id": "3009", "state": "COMPLETED", "submit": "2025-06-01T00:00:00"}' >> "$rec"
  ( cd "$d" && env "${env_pfx[@]}" "$SH" apply --job 3009 >"$d/nodefail.out" 2>&1 ) || fail "node-fail apply failed"
  assert_file_contains "$rec" '"job_id": "3009", "state": "NODE_FAIL"'
  assert_file_contains "$rec" '"cluster": "c1", "submit": "2026-01-02T05:00:00", "start": "2026-01-02T05:01:00", "usage": {"elapsed_seconds": 40, "queue_wait_seconds": 60}}'

  # What a job consumed is arithmetic over sacct's own fields: allocated GPUs
  # times elapsed, start minus submit, elapsed over the limit, TotalCPU over
  # allocated CPU time. An array sums its tasks; a requeued job counts the
  # preempted attempt too. A field sacct did not give leaves its figure out.
  printf '%s\n' '{"ts":"t","slurm_job_id":"3010","exit":0,"note":"experiment=exp-a arm=baseline","cmd":["g"]}' >> "$d/ledger.jsonl"
  ( cd "$d" && env "${env_pfx[@]}" "$SH" apply --job 3010 >"$d/usage.apply" 2>&1 ) || fail "usage apply failed"
  assert_file_contains "$rec" '"usage": {"elapsed_seconds": 1800, "queue_wait_seconds": 600, "gpu_hours": 1.0, "time_efficiency": 0.5, "cpu_efficiency": 0.5}'
  assert_file_contains "$rec" '"usage": {"elapsed_seconds": 90, "queue_wait_seconds": 120, "gpu_hours": 0.025}'
  assert_file_contains "$rec" '"usage": {"elapsed_seconds": 720, "queue_wait_seconds": 300, "gpu_hours": 0.0}'
  ( cd "$d" && env "${env_pfx[@]}" "$SH" usage --ledger "$d/ledger.jsonl" >"$d/usage.out" 2>&1 ) || fail "usage failed"
  assert_file_contains "$d/usage.out" "gpu-hours: 1.025 allocated over 3 job(s); "
  assert_file_contains "$d/usage.out" "time efficiency (elapsed / requested limit): 50% mean over 1 job(s); "
  assert_file_contains "$d/usage.out" "cpu efficiency (TotalCPU / allocated cpu time): 50% mean over 1 job(s); "
  assert_file_contains "$d/usage.out" "gpu utilisation: unknown"
  assert_file_contains "$d/usage.out" "memory efficiency: unknown"
  ( cd "$d" && env "${env_pfx[@]}" "$SH" usage --ledger "$d/ledger.jsonl" --experiment exp-a >"$d/usage.exp" 2>&1 ) ||
    fail "experiment usage failed"
  assert_file_contains "$d/usage.exp" "run usage for experiment exp-a: 1 recorded job(s) (COMPLETED=1)"
  assert_file_contains "$d/usage.exp" "gpu-hours: 1.0 allocated over 1 job(s)"
  assert_file_contains "$d/usage.exp" "queue wait: 00:10:00 total over 1 job(s)"
  ( cd "$d" && env "${env_pfx[@]}" "$SH" usage --ledger "$d/ledger.jsonl" --experiment none --json >"$d/usage.json" 2>&1 ) ||
    fail "empty usage failed"
  assert_file_contains "$d/usage.json" '"gpu_hours": null'
  assert_file_contains "$d/usage.json" '"jobs": 0'
  # Usage reads recorded rows only: with no sacct at all it answers the same.
  ( cd "$d" && env OMS_SACCT_CMD=/nonexistent OMS_SQUEUE_CMD=/nonexistent OMS_RECONCILE_FILE="$rec" \
    "$SH" usage --ledger "$d/ledger.jsonl" --job 3010 >"$d/usage.job" 2>&1 ) || fail "offline usage failed"
  assert_file_contains "$d/usage.job" "gpu-hours: 1.0 allocated over 1 job(s)"
  before="$(wc -l < "$rec")"
  ( cd "$d" && env "${env_pfx[@]}" "$SH" apply --job 3009 >/dev/null 2>&1 &&
    env "${env_pfx[@]}" "$SH" apply --job 3008 >/dev/null 2>&1 &&
    env "${env_pfx[@]}" "$SH" apply --job 3007 >/dev/null 2>&1 ) || fail "repeat apply failed"
  [ "$before" = "$(wc -l < "$rec")" ] || fail "a recorded submission must not be recorded twice"
}

# smoke-weight: 4
test_slurm_submit_detects_repeat_submissions() {
  local d="$TMP/slurm-submit"
  local bin="$d/bin"
  local SH="$ROOT/scripts/slurm-submit.sh"
  local calls="$d/calls" led="$d/.oms/slurm-submits.jsonl" rc key

  mkdir -p "$bin"
  git init -q "$d"
  # A fake sbatch records every invocation and prints a numbered job id; the
  # sleep widens the window a concurrent duplicate would need.
  printf '%s\n' '#!/bin/sh' \
    'echo "$*" >> "'"$calls"'"' \
    '[ -z "$FAKE_SBATCH_FAIL" ] || { echo "sbatch: error: denied" >&2; exit "$FAKE_SBATCH_FAIL"; }' \
    'sleep 0.3' \
    'echo "Submitted batch job $((5000 + $(wc -l < "'"$calls"'")))"' > "$bin/sbatch"
  chmod +x "$bin/sbatch"
  printf '#!/bin/bash\n#SBATCH --time=01:00:00\necho one\n' > "$d/a.sh"
  local submit=(env "PATH=$bin:$PATH" "OMS_LOCK_DIR=$d/locks")

  # First submit runs sbatch once, tags the comment and records the id.
  ( cd "$d" && "${submit[@]}" "$SH" -- sbatch --gres=gpu:1 a.sh >"$d/first.out" 2>&1 ) || fail "first slurm-submit failed: $(cat "$d/first.out")"
  [ "$(wc -l < "$calls")" = 1 ] || fail "first submit must call sbatch once"
  assert_file_contains "$calls" "--comment oms-key="
  assert_file_contains "$d/first.out" "Submitted batch job 5001"
  assert_file_contains "$led" '"type": "intent"'
  assert_file_contains "$led" '"job_id": "5001"'

  # An identical repeat does not run sbatch: exit 3, earlier id, how to check.
  rc=0
  ( cd "$d" && "${submit[@]}" "$SH" -- sbatch --gres=gpu:1 a.sh >"$d/repeat.out" 2>&1 ) || rc=$?
  [ "$rc" = 3 ] || fail "identical repeat must exit 3 (got $rc): $(cat "$d/repeat.out")"
  [ "$(wc -l < "$calls")" = 1 ] || fail "a repeat must not call sbatch"
  assert_file_contains "$d/repeat.out" "already submitted as job 5001"
  assert_file_contains "$d/repeat.out" "oms run-reconcile list"
  assert_file_contains "$d/repeat.out" "not exactly-once across machines or clones"

  # A changed script is a new key.
  printf 'echo two\n' >> "$d/a.sh"
  ( cd "$d" && "${submit[@]}" "$SH" -- sbatch --gres=gpu:1 a.sh >/dev/null 2>&1 ) || fail "changed script must submit"
  [ "$(wc -l < "$calls")" = 2 ] || fail "changed script must call sbatch"
  [ "$(grep -o '"key": "[0-9a-f]*"' "$led" | sort -u | wc -l)" = 2 ] || fail "changed script must change the key"

  # A failed sbatch is recorded and does not block the retry.
  printf '#!/bin/bash\necho f\n' > "$d/f.sh"
  rc=0
  ( cd "$d" && "${submit[@]}" FAKE_SBATCH_FAIL=7 "$SH" -- sbatch f.sh >/dev/null 2>&1 ) || rc=$?
  [ "$rc" = 7 ] || fail "failed sbatch must exit with its status (got $rc)"
  assert_file_contains "$led" '"type": "failed"'
  ( cd "$d" && "${submit[@]}" "$SH" -- sbatch f.sh >/dev/null 2>&1 ) || fail "retry after a failed submission must run"
  [ "$(wc -l < "$calls")" = 4 ] || fail "failed attempt and retry must each call sbatch"

  # A crash between intent and submitted: the key is unknown, not guessed.
  printf '#!/bin/bash\necho c\n' > "$d/c.sh"
  key="$(cd "$d" && "${submit[@]}" "$SH" --dry-run -- sbatch c.sh 2>/dev/null | sed -n 's/^key: //p')"
  [ -n "$key" ] || fail "dry-run must print the key"
  printf '{"schema": 1, "type": "intent", "key": "%s", "attempt": "dead00000000", "ts": "t", "tag": true}\n' "$key" >> "$led"
  rc=0
  ( cd "$d" && "${submit[@]}" "$SH" -- sbatch c.sh >"$d/unknown.out" 2>&1 ) || rc=$?
  [ "$rc" = 3 ] || fail "an unresolved intent must exit 3 (got $rc)"
  assert_file_contains "$d/unknown.out" "unknown: an earlier submission with this key may have gone through"
  assert_file_contains "$d/unknown.out" "oms-key="
  [ "$(wc -l < "$calls")" = 4 ] || fail "an unknown key must not call sbatch"

  # --force-resubmit needs a reason, records it, and then the new job is the duplicate.
  rc=0
  ( cd "$d" && "${submit[@]}" "$SH" --force-resubmit -- sbatch c.sh >/dev/null 2>&1 ) || rc=$?
  [ "$rc" = 2 ] || fail "--force-resubmit without --reason must exit 2 (got $rc)"
  ( cd "$d" && "${submit[@]}" "$SH" --force-resubmit --reason "checked squeue, nothing queued" -- sbatch c.sh >/dev/null 2>&1 ) ||
    fail "forced resubmit failed"
  assert_file_contains "$led" '"reason": "checked squeue, nothing queued"'
  [ "$(wc -l < "$calls")" = 5 ] || fail "forced resubmit must call sbatch"
  rc=0
  ( cd "$d" && "${submit[@]}" "$SH" -- sbatch c.sh >/dev/null 2>&1 ) || rc=$?
  [ "$rc" = 3 ] || fail "after a forced resubmit the new job is the duplicate (got $rc)"

  # --dry-run runs nothing and writes nothing.
  printf '#!/bin/bash\necho d\n' > "$d/d.sh"
  local rows_before
  rows_before="$(wc -l < "$led")"
  ( cd "$d" && "${submit[@]}" "$SH" --dry-run -- sbatch d.sh >"$d/dry.out" 2>&1 ) || fail "dry-run failed"
  assert_file_contains "$d/dry.out" "would run: sbatch --comment oms-key="
  [ "$(wc -l < "$led")" = "$rows_before" ] || fail "dry-run must not write"
  [ "$(wc -l < "$calls")" = 5 ] || fail "dry-run must not call sbatch"

  # Concurrent identical submits: exactly one sbatch call.
  printf '#!/bin/bash\necho e\n' > "$d/e.sh"
  ( cd "$d" && prc=0; "${submit[@]}" "$SH" -- sbatch e.sh >/dev/null 2>&1 || prc=$?; echo "$prc" > "$d/par1.rc" ) &
  ( cd "$d" && prc=0; "${submit[@]}" "$SH" -- sbatch e.sh >/dev/null 2>&1 || prc=$?; echo "$prc" > "$d/par2.rc" ) &
  wait
  [ "$(wc -l < "$calls")" = 6 ] || fail "concurrent identical submits must call sbatch once"
  [ "$(cat "$d/par1.rc" "$d/par2.rc" | sort | tr -d '\n')" = 03 ] || fail "one concurrent submit must win and one exit 3"

  # A caller-supplied key stands in for the content hash; arguments that trip
  # the sensitive scan are stored as a digest only.
  ( cd "$d" && "${submit[@]}" "$SH" --key cell-7 -- sbatch "--export=PASS""WORD=hunter2" d.sh >/dev/null 2>&1 ) || fail "custom key submit failed"
  rc=0
  ( cd "$d" && "${submit[@]}" "$SH" --key cell-7 -- sbatch e.sh >/dev/null 2>&1 ) || rc=$?
  [ "$rc" = 3 ] || fail "a repeated --key must exit 3 whatever the script (got $rc)"
  if grep -Fq hunter2 "$led"; then fail "sensitive sbatch arguments must not be stored"; fi
  assert_file_contains "$led" '"args_sha256"'
}

test_experiment_board_lifecycle_and_duplicate_guard() {
  local d="$TMP/exp-board"
  local board="$d/.oms/experiments.jsonl"
  local SH="$ROOT/scripts/experiment-board.sh"
  local id rc

  mkdir -p "$d"
  id="$(OMS_EXPERIMENT_BOARD="$board" OMS_AGENT=claude "$SH" claim \
    --hypothesis "scaffold split helps" --baseline "random" 2>/dev/null)"
  [ -n "$id" ] || fail "claim printed no id"

  # Duplicate claim by another agent is refused (exit 4), owner preserved.
  rc=0
  OMS_EXPERIMENT_BOARD="$board" OMS_AGENT=codex "$SH" claim \
    --hypothesis "scaffold split helps" >/dev/null 2>&1 || rc=$?
  [ "$rc" = "4" ] || fail "duplicate claim should exit 4 (got $rc)"

  OMS_EXPERIMENT_BOARD="$board" "$SH" start --id "$id" --job 9001 >/dev/null 2>&1 ||
    fail "start failed"
  OMS_EXPERIMENT_BOARD="$board" "$SH" finish --id "$id" --result "AUC up" >/dev/null 2>&1 ||
    fail "finish failed"

  # The board's terminal spelling is part of the shared JSONL contract. A
  # healthy finish must remain valid when the run spine audits every stream.
  ( cd "$d" && "$ROOT/scripts/run.sh" validate --dir "$d/.oms" ) >/dev/null 2>&1 ||
    fail "run validation rejected a healthy finished experiment"

  # Active list hides the finished experiment; --all shows it, owner = claimer.
  local active all
  active="$(OMS_EXPERIMENT_BOARD="$board" "$SH" list 2>/dev/null)"
  contains "$active" "$id" && fail "finished experiment must not be active"
  all="$(OMS_EXPERIMENT_BOARD="$board" "$SH" list --all 2>/dev/null)"
  contains "$all" "$id" || fail "--all must show finished experiment"
  contains "$all" "owner=claude" || fail "owner must stay the claimer"

  # A negative result is findable before the next claim: finish records a
  # verdict and tags, and a claim sharing a tag (exact match) lists it first.
  local b=(env "OMS_EXPERIMENT_BOARD=$board" OMS_AGENT=claude "$SH")
  "${b[@]}" claim --id warmup-a --hypothesis "longer warmup helps" --tags "Warmup, lr" >/dev/null 2>"$d/claim1.err" ||
    fail "tagged claim failed"
  ! grep -q 'finished experiment' "$d/claim1.err" || fail "a first tagged claim has nothing earlier to list"
  "${b[@]}" finish --id warmup-a --verdict not_supported --result "no gain over 3 seeds" >/dev/null 2>"$d/finish.err" ||
    fail "finish with a verdict failed"
  assert_file_contains "$d/finish.err" "done: warmup-a (not_supported)"
  assert_file_contains "$board" '"verdict": "not_supported"'
  assert_file_contains "$board" '"tags": ["warmup", "lr"]'
  ( cd "$d" && "$ROOT/scripts/run.sh" validate --dir "$d/.oms" ) >/dev/null 2>&1 ||
    fail "run validation rejected a finished experiment that carries a verdict and tags"
  "${b[@]}" claim --id warmup-b --hypothesis "cosine warmup helps" --tags warmup >/dev/null 2>"$d/claim2.err" ||
    fail "a claim sharing a tag with a rejected experiment must still succeed"
  assert_file_contains "$d/claim2.err" "1 finished experiment(s) share this claim's tags or id:"
  assert_file_contains "$d/claim2.err" "  warmup-a  not_supported  [warmup]  no gain over 3 seeds"
  assert_file_contains "$d/claim2.err" "a not_supported result is a recorded outcome, not a ban"
  # Exact tags only: a different tag, or one that merely contains it, lists nothing.
  "${b[@]}" claim --id other --hypothesis "unrelated" --tags warmup-long,schedule >/dev/null 2>"$d/claim3.err" ||
    fail "unrelated tagged claim failed"
  ! grep -q 'finished experiment' "$d/claim3.err" || fail "tags must match exactly: $(cat "$d/claim3.err")"
  # Re-claiming an id that already ended lists its outcome without any tag.
  "${b[@]}" claim --id warmup-a --hypothesis "longer warmup helps" >/dev/null 2>"$d/claim4.err" ||
    fail "re-claiming a finished id failed"
  assert_file_contains "$d/claim4.err" "  warmup-a  not_supported  [same id]  no gain over 3 seeds"
  "${b[@]}" show --id warmup-a > "$d/show.out" 2>&1 || fail "show failed"
  assert_file_contains "$d/show.out" "verdict=not_supported"
  assert_file_contains "$d/show.out" "tags=warmup,lr"
  # The verdict vocabulary and tag spelling are closed; a bad one writes nothing.
  local rows
  rows="$(wc -l < "$board")"
  rc=0; "${b[@]}" finish --id warmup-b --verdict maybe >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "an unknown verdict must be refused (got $rc)"
  rc=0; "${b[@]}" claim --id bad --hypothesis h --tags "has space" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a tag outside [a-z0-9._-] must be refused (got $rc)"
  rc=0; "${b[@]}" start --id warmup-b --tags warmup >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "--tags outside claim and finish must be refused (got $rc)"
  rc=0; "${b[@]}" claim --id bad --hypothesis h --verdict supported >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "--verdict on claim must be refused (got $rc)"
  [ "$rows" = "$(wc -l < "$board")" ] || fail "a refused request must not append to the board"
}

test_experiment_board_stale_reclaim() {
  local d="$TMP/exp-stale"
  local board="$d/.oms/experiments.jsonl"
  local SH="$ROOT/scripts/experiment-board.sh"

  mkdir -p "$d"
  OMS_EXPERIMENT_BOARD="$board" OMS_AGENT=claude "$SH" claim --id e --hypothesis h \
    >/dev/null 2>&1 || fail "first claim failed"
  # Fresh claim is blocked...
  if OMS_EXPERIMENT_BOARD="$board" OMS_EXPERIMENT_CLAIM_TTL=86400 OMS_AGENT=codex \
    "$SH" claim --id e --hypothesis h >/dev/null 2>&1; then
    fail "fresh duplicate claim should be blocked"
  fi
  # ...but a stale claim (TTL 0) is reclaimable and transfers ownership.
  OMS_EXPERIMENT_BOARD="$board" OMS_EXPERIMENT_CLAIM_TTL=0 OMS_AGENT=codex \
    "$SH" claim --id e --hypothesis h >/dev/null 2>&1 ||
    fail "stale claim should be reclaimable"
  OMS_EXPERIMENT_BOARD="$board" "$SH" list | grep e | grep "owner=codex" > /dev/null ||
    fail "a stale reclaim must transfer ownership to the reclaiming agent"
  OMS_EXPERIMENT_BOARD="$board" OMS_AGENT=codex "$SH" start --id e >/dev/null 2>&1
  OMS_EXPERIMENT_BOARD="$board" "$SH" list | grep e | grep "owner=codex" > /dev/null ||
    fail "start must not change the owner"
}


# smoke-weight: 11
test_experiment_board_claim_is_atomic() {
  local d="$TMP/exp-claim-race"
  local board="$d/.oms/experiments.jsonl"
  local SH="$ROOT/scripts/experiment-board.sh"
  local holder
  local -a pids=()
  local i p rc ok blocked other lines

  mkdir -p "$d"
  (
    . "$ROOT/scripts/lib/file-lock.sh"
    oms_with_file_lock "$board" bash -c 'printf locked > "$1"; sleep 2' _ "$d/lock-held"
  ) &
  holder=$!
  for i in $(seq 1 50); do
    [ -f "$d/lock-held" ] && break
    sleep 0.05
  done
  [ -f "$d/lock-held" ] || fail "claim race lock holder did not start"

  for i in $(seq 1 10); do
    (
      set +e
      OMS_EXPERIMENT_BOARD="$board" OMS_AGENT="agent-$i" \
        "$SH" claim --id race --hypothesis "same hypothesis" \
        >"$d/out.$i" 2>"$d/err.$i"
      printf '%s\n' "$?" > "$d/rc.$i"
    ) &
    pids+=("$!")
  done
  wait "$holder" || fail "claim race lock holder failed"
  for p in "${pids[@]}"; do wait "$p" || true; done

  ok=0; blocked=0; other=0
  for i in $(seq 1 10); do
    rc="$(cat "$d/rc.$i")"
    case "$rc" in
      0) ok=$((ok + 1)) ;;
      4) blocked=$((blocked + 1)) ;;
      *) other=$((other + 1)) ;;
    esac
  done
  [ "$ok" = 1 ] || fail "exactly one concurrent claim should win, got $ok"
  [ "$blocked" = 9 ] || fail "nine concurrent claims should be blocked, got $blocked"
  [ "$other" = 0 ] || fail "unexpected claim exit count: $other"
  lines="$(wc -l < "$board" | tr -d ' ')"
  [ "$lines" = 1 ] || fail "atomic claim should append one event, got $lines"
}

# Beside the experiment-board coordination tests: advisory file leases.
# smoke-weight: 10
test_lease_is_advisory_visible_intent_with_expiry() {
  local project="$TMP/lease-repo" lease="$ROOT/scripts/lease.sh" store out id i rc before
  local -a pids=()
  make_committed_repo "$project"
  mkdir -p "$project/src/sub" "$TMP/lease-outside"
  store="$project/.oms/leases.jsonl"
  (
    cd "$project"
    export OMS_ATTEMPT_ID=worker-a
    out="$("$lease" add 'src/*.py' --ttl 10m --reason refactor 2>/dev/null)" || fail "add failed"
    contains "$out" 'paths src/*.py' || fail "add should echo the repo-relative glob: $out"

    # Another holder: exclusive lease of a worker is reported with holder, reason, time left.
    export OMS_ATTEMPT_ID=worker-b
    out="$("$lease" check src/x.py)" && fail "a path under another holder's exclusive lease must exit 1"
    contains "$out" 'by worker-a' || fail "check must name the holder: $out"
    contains "$out" '"refactor"' || fail "check must name the reason: $out"
    contains "$out" 'm left' || fail "check must show time left: $out"
    "$lease" check lib/x.md >/dev/null || fail "a path outside the glob's static prefix must be free"
    "$lease" check README.md >/dev/null || fail "an unrelated literal path must be free"
    # Glob versus a deeper literal is not decided exactly, so it is reported.
    if "$lease" check src/sub/x.md >/dev/null; then fail "a conservative overlap must be reported held"; fi
    # Undecidable (glob without a static prefix against a literal) counts as overlap.
    if "$lease" check '*.md' >/dev/null; then fail "an undecidable overlap must be reported held"; fi
    if "$lease" check src/a.py src/sub/ >/dev/null; then fail "one held path among several must exit 1"; fi
    out="$("$lease" add src/x.py 2>&1 >/dev/null)" || fail "add must warn, not refuse"
    contains "$out" 'warning: overlaps' || fail "overlapping add must warn: $out"

    # The holder is never blocked by its own lease.
    export OMS_ATTEMPT_ID=worker-a
    "$lease" check src/y.py >/dev/null || fail "own lease must not conflict"

    # Shared leases do not conflict with each other; an exclusive ask still sees them.
    export OMS_ATTEMPT_ID=worker-c
    "$lease" add docs/guide.md --shared >/dev/null 2>&1 || fail "shared add failed"
    export OMS_ATTEMPT_ID=worker-d
    out="$("$lease" add docs/guide.md --shared 2>&1)" || fail "second shared add failed"
    contains "$out" 'warning' && fail "two shared leases must not conflict: $out"
    out="$("$lease" add docs/guide.md 2>&1)" || fail "exclusive add over shared failed"
    contains "$out" 'warning: overlaps' || fail "exclusive over shared must warn: $out"

    # Usage and boundary errors exit 2.
    rc=0; "$lease" check >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ] || fail "check without paths is a usage error, got $rc"
    rc=0; "$lease" add --ttl 9h x >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ] || fail "ttl above 8h must be refused, got $rc"
    rc=0; "$lease" add --ttl 30s x >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ] || fail "ttl below 1m must be refused, got $rc"
    rc=0; "$lease" add "$TMP/lease-outside/f" >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ] || fail "an absolute path outside the repository must be refused, got $rc"
    rc=0; "$lease" add ../escape >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ] || fail "a .. escape must be refused, got $rc"
    ln -s "$TMP/lease-outside" link
    rc=0; "$lease" add link/f >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ] || fail "a symlink leading outside must be refused, got $rc"

    # --staged
    export OMS_ATTEMPT_ID=worker-b
    printf 'x\n' > src/staged.py
    printf 'y\n' > other.txt
    git add other.txt
    "$lease" check --staged >/dev/null || fail "staged path outside any lease must be free"
    git add src/staged.py
    out="$("$lease" check --staged)" && fail "a staged path under another holder's lease must exit 1"
    contains "$out" 'src/staged.py' || fail "staged conflict must name the path: $out"
    export OMS_ATTEMPT_ID=worker-a
    "$lease" check --staged >/dev/null || fail "the holder's own staged path is free"
  ) || return 1

  # Expiry is computed on read: an already-expired row is listed as expired and no longer conflicts.
  printf '%s\n' '{"expires":"2020-01-01T00:30:00Z","holder":"ghost","id":"l-old00001","op":"add","paths":["gone/*"],"reason":"","schema":1,"shared":false,"ts":"2020-01-01T00:00:00Z"}' >> "$store"
  mkdir -p "$project/gone"
  out="$(cd "$project" && "$lease" list)"
  contains "$out" 'l-old00001 expired' || fail "an expired lease must be listed as expired: $out"
  (cd "$project" && OMS_ATTEMPT_ID=worker-b "$lease" check gone/f >/dev/null) || fail "an expired lease must not conflict"
  grep -Fq l-old00001 "$store" || fail "expiry must not delete rows"

  # Release: by id (holder only) and --mine; released leases drop out of list but stay in the file.
  id="$(cd "$project" && OMS_ATTEMPT_ID=worker-a "$lease" list --json | python3 -c 'import json,sys; print([l["id"] for l in json.load(sys.stdin) if l["holder"]=="worker-a"][0])')"
  rc=0; (cd "$project" && OMS_ATTEMPT_ID=worker-b "$lease" release "$id" >/dev/null 2>&1) || rc=$?
  [ "$rc" = 1 ] || fail "releasing another holder's live lease must exit 1, got $rc"
  (cd "$project" && OMS_ATTEMPT_ID=worker-a "$lease" release --mine >/dev/null) || fail "release --mine failed"
  out="$(cd "$project" && "$lease" list)"
  contains "$out" "$id" && fail "a released lease must leave the list: $out"
  (cd "$project" && OMS_ATTEMPT_ID=worker-b "$lease" check src/x.py >/dev/null) || fail "released lease must free the path"
  grep -Fq '"op": "release"' "$store" || grep -Fq '"op":"release"' "$store" || fail "release must append a row"

  # Concurrent adds append whole rows only.
  before="$(wc -l < "$store" | tr -d ' ')"
  for i in $(seq 1 12); do
    (cd "$project" && OMS_ATTEMPT_ID="racer-$i" "$lease" add "race/$i.txt" --shared >/dev/null 2>&1) &
    pids+=("$!")
  done
  for i in "${pids[@]}"; do wait "$i" || fail "concurrent add failed"; done
  [ "$(wc -l < "$store" | tr -d ' ')" = "$((before + 12))" ] || fail "concurrent adds must each append one row"
  python3 -c 'import json,sys; [json.loads(l) for l in open(sys.argv[1])]' "$store" ||
    fail "concurrent adds corrupted the lease file"
}

# Build a repo with a base commit and a patch of `branch` vs main on file.txt.
make_patch_repo() {
  local repo="$1"
  local branch_content="$2"
  make_committed_repo "$repo"
  git -C "$repo" checkout -q -b feat
  printf '%s' "$branch_content" > "$repo/file.txt"
  git -C "$repo" -c user.email=t@e -c user.name=t commit -qam change
  git -C "$repo" diff main feat > "$repo/change.patch"
  git -C "$repo" checkout -q main
  git -C "$repo" branch -q -D feat
}

# smoke-weight: 11
test_patch_admit_admits_clean_patch() {
  local repo="$TMP/admit-clean"
  local SH="$ROOT/scripts/patch-admit.sh"
  local admission_stderr="$repo/admission.stderr"
  make_patch_repo "$repo" $'base\nmore\n'
  ( "$SH" --patch "$repo/change.patch" --repo "$repo" >/dev/null 2>"$admission_stderr" ) ||
    fail "clean patch should be admitted (exit 0)"
  # The final patch-admit status line is its established stderr contract.
  [ "$(wc -l < "$admission_stderr" | tr -d '[:space:]')" = "1" ] &&
    grep -Eq '^patch-admit: ADMIT [(].+[)]$' "$admission_stderr" ||
    fail "clean patch admission wrote unexpected stderr"
  local r
  r="$(find "$repo/.oms/artifacts/admit" -name '*.md' | sed -n '1p')"
  [ -n "$r" ] || fail "no admission report written"
  assert_file_contains "$r" "Patch admission: ADMIT"
  assert_file_contains "$r" "apply: PASS"
  grep -Fqx -- "- security: SKIP — no risk paths" "$r" ||
    fail "clean patch security ladder line is not exact"

  local risk_repo="$TMP/admit-risky"
  local risk_report="$risk_repo/security-advice.md"
  make_committed_repo "$risk_repo"
  mkdir -p "$risk_repo/src"
  printf 'import os\n\ndef cleanup(path):\n    return path\n' > "$risk_repo/src/café.py"
  git -C "$risk_repo" add src/café.py
  git -C "$risk_repo" commit -qm 'add cleanup fixture'
  git -C "$risk_repo" checkout -q -b feat
  printf 'import os\n\ndef cleanup(path):\n    os.unlink(path)\n' > "$risk_repo/src/café.py"
  git -C "$risk_repo" add src/café.py
  git -C "$risk_repo" commit -qm 'remove a path'
  git -C "$risk_repo" diff main feat > "$risk_repo/change.patch"
  git -C "$risk_repo" checkout -q main
  git -C "$risk_repo" branch -q -D feat
  "$SH" --patch "$risk_repo/change.patch" --repo "$risk_repo" --report "$risk_report" >/dev/null ||
    fail "risky patch should remain admitted"
  assert_file_contains "$risk_report" "Patch admission: ADMIT"
  assert_file_contains "$risk_report" "security: ADVISE"
  assert_file_contains "$risk_report" 'caf\u00e9.py'

  local docs_repo="$TMP/admit-docs"
  local docs_report="$docs_repo/security-advice.md"
  make_committed_repo "$docs_repo"
  mkdir -p "$docs_repo/docs"
  printf 'Cleanup examples mention os.unlink(path).\n' > "$docs_repo/docs/obsolete.md"
  git -C "$docs_repo" add docs/obsolete.md
  git -C "$docs_repo" commit -qm 'add documentation fixture'
  git -C "$docs_repo" checkout -q -b feat
  git -C "$docs_repo" rm -q docs/obsolete.md
  git -C "$docs_repo" commit -qm 'remove documentation fixture'
  git -C "$docs_repo" diff main feat > "$docs_repo/change.patch"
  git -C "$docs_repo" checkout -q main
  git -C "$docs_repo" branch -q -D feat
  "$SH" --patch "$docs_repo/change.patch" --repo "$docs_repo" --report "$docs_report" >/dev/null ||
    fail "docs-only patch should remain admitted"
  assert_file_contains "$docs_report" "Patch admission: ADMIT"
  assert_file_contains "$docs_report" "security: SKIP"
  assert_file_contains "$docs_report" "no risk paths"

  # A project check without fast must not silently become a full-suite gate.
  mkdir -p "$repo/scripts"
  printf '#!/usr/bin/env bash\ntouch "%s"\n' "$repo/full-gate-ran" > "$repo/scripts/check.sh"
  chmod +x "$repo/scripts/check.sh"
  git -C "$repo" add scripts/check.sh
  git -C "$repo" commit -qm 'fixture check contract'
  local rc=0
  "$SH" --patch "$repo/change.patch" --repo "$repo" > "$repo/no-fast.out" 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "admission without bounded default must require explicit verification"
  [ ! -e "$repo/full-gate-ran" ] || fail "admission ran an unrequested full suite"
  assert_file_contains "$repo/no-fast.out" 'no bounded fast mode'
  "$SH" --patch "$repo/change.patch" --repo "$repo" --verify true >/dev/null ||
    fail "explicit verification must override default detection"
  # Direct managed admission is a real local operation throughout verification.
  python3 - "$ROOT" "$repo" <<'PY_REFERENCE'
import hashlib, pathlib, runpy, sys
root, repo = map(pathlib.Path, sys.argv[1:])
c = runpy.run_path(str(root / 'scripts/lib/landing-capture.py'))
source = repo / 'change.patch'
private = c['allocate'](str(repo), str(source), 'land-direct-reference', hashlib.sha256(source.read_bytes()).hexdigest())
c['publish'](str(repo), private, str(repo / '.oms/landing-patches/land-direct-reference.patch'))
PY_REFERENCE
  local managed="$repo/.oms/landing-patches/land-direct-reference.patch"
  # Unsafe managed inputs are refused before a local operation starts.
  cp "$repo/.oms/lifecycle/events.jsonl" "$repo/before-refusal.jsonl"
  if ln -s "$managed" "$repo/redirected.patch" 2>/dev/null; then
    if "$SH" --repo "$repo" --patch "$repo/redirected.patch" --verify true >/dev/null 2>&1; then
      fail "redirected managed admission input bypassed ownership validation"
    fi
  fi
  if "$SH" --repo "$repo" --patch "$managed" --verify true --report "$repo/external.md" >/dev/null 2>&1; then
    fail "managed admission accepted an external report"
  fi
  [ ! -e "$repo/external.md" ] || fail "external managed report was written"
  cmp -s "$repo/before-refusal.jsonl" "$repo/.oms/lifecycle/events.jsonl" ||
    fail "unsafe managed input started or changed a local operation"
  cat > "$repo/observe-reference.py" <<'PY_REFERENCE'
import pathlib, runpy, sys
root, repo = map(pathlib.Path, sys.argv[1:])
e = runpy.run_path(str(root / 'scripts/lib/agent-events.py'))
_, attempts = e['load_projection'](repo)
import os
assert os.environ.get('OMS_ATTEMPT_ID') == 'att_original_native'
assert any(a.get('provider') == 'local' and a.get('tool') == 'patch-admit' and
           a.get('state') == 'working' and not a.get('parent_attempt_id') for a in attempts.values())
PY_REFERENCE
  OMS_ATTEMPT_ID=att_original_native "$SH" --repo "$repo" --patch "$managed" \
    --verify "python3 '$repo/observe-reference.py' '$ROOT' '$repo'" >/dev/null ||
    fail "managed direct admission did not keep its own local operation active"
  # A failed durable pin must leave the operation nonterminal, even with a report.
  mv "$repo/.oms/artifacts/index.jsonl" "$repo/.oms/artifacts/index.saved"
  mkdir "$repo/.oms/artifacts/index.jsonl"
  if "$SH" --repo "$repo" --patch "$managed" --verify true >/dev/null 2>&1; then
    fail "managed admission ignored index publication failure"
  fi
  python3 - "$ROOT" "$repo" <<'PY_REFERENCE'
import pathlib, runpy, sys
root, repo = map(pathlib.Path, sys.argv[1:])
e = runpy.run_path(str(root / 'scripts/lib/agent-events.py'))
_, attempts = e['load_projection'](repo)
rows = e['read_rows'](e['event_path'](repo))
last = [r['attempt_id'] for r in rows if r['event_type'] == 'attempt.created'][-1]
assert attempts[last]['tool'] == 'patch-admit' and attempts[last]['state'] == 'blocked'
assert attempts[last]['terminal'] is not True
c = runpy.run_path(str(root / 'scripts/lib/landing-capture.py'))
# The fixture owns these captures; retain no private temporary directory.
import shutil
for item in c['reservations'](str(repo)).values():
    shutil.rmtree(item['directory'])
PY_REFERENCE

}

# smoke-weight: 6
test_patch_admit_scope_uses_canonical_glob_and_deny_precedence() {
  local repo="$TMP/admit-canonical-scope"
  local sh="$ROOT/scripts/patch-admit.sh"
  local report

  make_patch_repo "$repo" $'base\nmore\n'
  "$ROOT/scripts/agent-plan.sh" --repo "$repo" init --goal scope --accept true >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$repo" add --id allowed \
    --title allowed --allowed '*.txt' --verify true >/dev/null
  "$sh" --patch "$repo/change.patch" --repo "$repo" --plan-task allowed >/dev/null ||
    fail "patch-admit did not accept the canonical glob scope"

  "$ROOT/scripts/agent-plan.sh" --repo "$repo" add --id denied \
    --title denied --allowed '*.txt' --forbidden file.txt --verify true >/dev/null
  if "$sh" --patch "$repo/change.patch" --repo "$repo" --plan-task denied >/dev/null; then
    fail "a forbidden path was admitted because it also matched the allow glob"
  fi
  report="$(find "$repo/.oms/artifacts/admit" -name '*.md' -type f \
    -exec ls -t {} + | sed -n '1p')"
  [ -n "$report" ] || fail "forbidden-scope admission report missing"
  assert_file_contains "$report" "forbidden: file.txt"
}

test_patch_admit_rejects_stale_patch() {
  local repo="$TMP/admit-stale"
  local SH="$ROOT/scripts/patch-admit.sh"
  make_patch_repo "$repo" $'base\nmore\n'
  # Move the base so the patch no longer applies.
  printf 'moved\n' > "$repo/file.txt"
  git -C "$repo" -c user.email=t@e -c user.name=t commit -qam move
  if ( "$SH" --patch "$repo/change.patch" --repo "$repo" >/dev/null 2>&1 ); then
    fail "stale patch should be rejected (nonzero)"
  fi
}

test_patch_admit_rejects_failed_verify() {
  local repo="$TMP/admit-verify"
  local SH="$ROOT/scripts/patch-admit.sh"
  make_patch_repo "$repo" $'base\nmore\n'
  if ( OMS_PEER_VERIFY_TIMEOUT=1s "$SH" --patch "$repo/change.patch" --repo "$repo" --verify 'echo verifier-started; sleep 30' >/dev/null 2>&1 ); then
    fail "failed verify should reject the patch"
  fi
  local report
  report="$(find "$repo/.oms/artifacts/admit" -name '*.md' | sed -n '1p')"
  [ -n "$report" ] || fail "no admission report written for timed-out verify"
  assert_file_contains "$report" "verify: FAIL"
  assert_file_contains "$report" "timed out after 1s (raise OMS_PEER_VERIFY_TIMEOUT)"
  assert_file_contains "$report" "verifier-started"
}

test_patch_admit_rejects_secret_in_patch() {
  local repo="$TMP/admit-secret"
  local SH="$ROOT/scripts/patch-admit.sh"
  # A patch that applies and parses cleanly but adds a credential must be
  # rejected by the secret-scan gate before it can land. The secret string is
  # assembled at runtime so this test file does not trip the self-review gate.
  local cred_line="aws_secret""_access_key = abcdEFGH1234ijklMNOP5678qrstUVWX90zzAAA"
  make_patch_repo "$repo" "base"$'\n'"$cred_line"$'\n'
  if ( "$SH" --patch "$repo/change.patch" --repo "$repo" --verify 'true' >/dev/null 2>&1 ); then
    fail "patch adding a secret should be rejected"
  fi
  local r
  r="$(find "$repo/.oms/artifacts/admit" -name '*.md' | sed -n '1p')"
  [ -n "$r" ] || fail "no admission report written"
  assert_file_contains "$r" "secrets: FAIL"
  assert_file_contains "$r" "file.txt:2: secret-tier match: token-assignment"

  local scan_bin="$TMP/admit-scan-bin" real_sed rc=0
  mkdir -p "$scan_bin"
  real_sed="$(command -v sed)"
  cat > "$scan_bin/sed" <<'EOF'
#!/usr/bin/env bash
case " $* " in *"$OMS_TEST_SCAN_FAIL_PATH"*) exit 2 ;; esac
exec "$OMS_TEST_REAL_SED" "$@"
EOF
  chmod +x "$scan_bin/sed"
  mkdir -p "$TMP/admit-scan-tmp"
  PATH="$scan_bin:$PATH" OMS_TEST_REAL_SED="$real_sed" TMPDIR="$TMP/admit-scan-tmp" \
    OMS_LIB_TMPDIR="$TMP/admit-scan-tmp" \
    OMS_TEST_SCAN_FAIL_PATH="$TMP/admit-scan-tmp" \
    "$SH" --patch "$repo/change.patch" --repo "$repo" --verify true \
    > "$repo/scan-failure.out" 2>&1 || rc=$?
  [ "$rc" -ne 0 ] || fail "admission must reject a failed sensitive-content scan"
  local scan_report_line scan_report
  scan_report_line="$(grep -F 'patch-admit: REJECT (' "$repo/scan-failure.out")"
  scan_report="${scan_report_line#*\(}"
  scan_report="${scan_report%)}"
  [ -n "$scan_report" ] && [ -f "$scan_report" ] || fail "admission scan-failure report path missing"
  grep -Fq "sensitive-content scan failed" "$scan_report" ||
    fail "admission report must record scan failure: $(cat "$scan_report")"
}

test_patch_admit_rejects_invalid_source_syntax() {
  local repo="$TMP/admit-python-syntax"
  local SH="$ROOT/scripts/patch-admit.sh"
  local r

  make_committed_repo "$repo"
  git -C "$repo" checkout -q -b pybad
  printf 'def broken(:\n    pass\n' > "$repo/bad.py"
  git -C "$repo" add bad.py
  git -C "$repo" commit -qm pybad
  git -C "$repo" diff main pybad > "$repo/pybad.patch"
  git -C "$repo" checkout -q main
  git -C "$repo" branch -q -D pybad

  if ( "$SH" --patch "$repo/pybad.patch" --repo "$repo" --verify true >/dev/null 2>&1 ); then
    fail "python syntax error should reject the patch"
  fi
  r="$(find "$repo/.oms/artifacts/admit" -name '*.md' | sed -n '1p')"
  [ -n "$r" ] || fail "no admission report written"
  assert_file_contains "$r" "syntax: FAIL"
  assert_file_contains "$r" "python compile failed: bad.py"

  repo="$TMP/admit-json-syntax"
  make_committed_repo "$repo"
  git -C "$repo" checkout -q -b jsonbad
  printf '{ bad json\n' > "$repo/bad.json"
  git -C "$repo" add bad.json
  git -C "$repo" commit -qm jsonbad
  git -C "$repo" diff main jsonbad > "$repo/jsonbad.patch"
  git -C "$repo" checkout -q main
  git -C "$repo" branch -q -D jsonbad

  if ( "$SH" --patch "$repo/jsonbad.patch" --repo "$repo" --verify true >/dev/null 2>&1 ); then
    fail "json syntax error should reject the patch"
  fi
  r="$(find "$repo/.oms/artifacts/admit" -name '*.md' | sed -n '1p')"
  [ -n "$r" ] || fail "no admission report written"
  assert_file_contains "$r" "syntax: FAIL"
  assert_file_contains "$r" "json parse failed: bad.json"

  repo="$TMP/admit-shellcheck"
  local lint_bin="$TMP/admit lint" lint_command mode rc
  make_committed_repo "$repo"
  mkdir -p "$repo/sub dir"
  printf 'printf ok\n' > "$repo/sub dir/run.sh"
  printf '#!/usr/bin/env bash\nprintf unchanged\n' > "$repo/unchanged.sh"
  git -C "$repo" add .
  git -C "$repo" commit -qm shellcheck-base
  printf 'printf changed\n' >> "$repo/sub dir/run.sh"
  git -C "$repo" diff > "$repo/lint.patch"
  git -C "$repo" checkout -q -- "sub dir/run.sh"
  if command -v shellcheck >/dev/null 2>&1; then
    OMS_SHELLCHECK_BIN="$(command -v shellcheck)" \
      "$SH" --patch "$repo/lint.patch" --repo "$repo" --verify true --report "$repo/headerless.md" \
      > "$repo/headerless.out" 2>&1 || fail "a Bash-parseable shell file needs no shebang: $(cat "$repo/headerless.out")"
    assert_file_contains "$repo/headerless.md" "syntax: PASS"
  fi
  cat > "$lint_bin" <<'EOF'
#!/usr/bin/env bash
[ "$#" = 5 ] && [ "$1" = -S ] && [ "$2" = warning ] && [ "$3" = -e ] &&
  [ "$4" = SC1090,SC1091,SC2034,SC2148,SC2154 ] || exit 2
case "$5" in *'/sub dir/run.sh') ;; *) exit 2 ;; esac
case "$OMS_TEST_LINT_MODE" in
  clean) exit 0 ;;
  empty) exit 1 ;;
  blank) printf '\n \t\n'; exit 1 ;;
  warning)
    printf '\n \t\nIn %s line 1:\n' "$5"
    printf '%s%0187d%s\n' 'echo $value #' 0 'unshown-column'
    printf '%s\n' '^-- SC2086 (warning): Double quote to prevent globbing and word splitting.' 'unshown diagnostic'
    exit 1 ;;
esac
exit 2
EOF
  chmod +x "$lint_bin"
  for mode in warning empty blank clean missing; do
    r="$repo/$mode.md"
    rc=0
    lint_command="$lint_bin"
    [ "$mode" != missing ] || lint_command="$lint_bin.missing"
    OMS_TEST_LINT_MODE="$mode" OMS_SHELLCHECK_BIN="$lint_command" \
      "$SH" --patch "$repo/lint.patch" --repo "$repo" --verify true --report "$r" \
      > "$repo/$mode.out" 2>&1 || rc=$?
    case "$mode" in
      warning|empty|blank)
        [ "$rc" -ne 0 ] || fail "ShellCheck finding must reject admission ($mode)"
        assert_file_contains "$r" "syntax: FAIL"
        assert_file_contains "$r" "shellcheck failed: sub dir/run.sh"
        if [ "$mode" = warning ]; then
          grep -Eq 'syntax: FAIL.*SC2086 \(warning\): Double quote' "$r" ||
            fail "syntax detail must retain the ShellCheck code and message"
          assert_file_contains "$r" "$(printf '%s%0187d' 'echo $value #' 0)"
          if grep -Eq 'unshown diagnostic|unshown-column' "$r"; then
            fail "ShellCheck report must keep only the first diagnostics"
          fi
        fi
        ;;
      clean|missing)
        [ "$rc" = 0 ] || fail "ShellCheck $mode case should admit: $(cat "$repo/$mode.out")"
        assert_file_contains "$r" "syntax: PASS"
        if [ "$mode" = missing ]; then
          assert_file_contains "$r" "shellcheck: SKIP — ShellCheck not installed"
          [ "$(grep -c 'ShellCheck not installed' "$r")" = 1 ] || fail "report ShellCheck skip once"
        fi
        ;;
    esac
  done
  mkdir -p "$repo/sub dir"
  printf 'ok\n' > "$repo/sub dir/x.sh"
  git -C "$repo" add "sub dir/x.sh"
  git -C "$repo" commit -q -m "add spaced"
  printf 'if then fi oops (\n' >> "$repo/sub dir/x.sh"
  git -C "$repo" diff > "$repo/space.patch"
  git -C "$repo" checkout -q "sub dir/x.sh"
  if ( cd "$repo" && "$SH" --patch "$repo/space.patch" --verify true >/dev/null 2>&1 ); then
    fail "a broken shell file with a spaced path must be caught by syntax gate"
  fi
}

test_agent_task_context_preserves_tail_sections() {
  local repo="$TMP/task-prune"
  make_committed_repo "$repo"
  (
    cd "$repo"
    . "$ROOT/scripts/lib/oms-common.sh"
    . "$ROOT/scripts/lib/agent-memory-common.sh"
    . "$ROOT/scripts/lib/agent-task-common.sh"
    local f="$repo/task.md"
    {
      printf '## Goal\n\nShip fix\n\n## Loop State\n\n'
      local i
      for i in $(seq 1 300); do printf -- '- old loop bullet %s padding padding padding\n' "$i"; done
      printf '\n## Current State\n\nhalfway done\n\n## Next Step\n\nRUN THE FINAL TEST\n'
    } > "$f"
    # Over-budget file: top-cut would drop Next Step; section-aware keeps it.
    OMS_AGENT_TASK_CONTEXT_CHARS=800 agent_task_emit_context "$repo" "$f" > "$repo/ctx.out"
  ) || fail "emit_context failed"
  assert_file_contains "$repo/ctx.out" "RUN THE FINAL TEST"
  assert_file_contains "$repo/ctx.out" "## Current State"
  assert_file_contains "$repo/ctx.out" "older entries dropped"
}

test_debate_prompt_masks_quoted_paths() {
  # Build the path fragments at runtime so this test file itself never carries
  # a literal absolute path that would trip the self-review scrubber gate.
  local h="/ho""me" u="/Use""rs" sch="file:""//"
  local out
  out="$(
    . "$ROOT/scripts/lib/oms-common.sh"
    . "$ROOT/scripts/lib/agent-memory-common.sh"
    . "$ROOT/scripts/lib/agent-task-common.sh"
    . "$ROOT/scripts/lib/peer-common.sh"
    printf 'ref %s/x and %s/u/p.sh\n' "$sch$h/u/x.sh" "$u" | ma_mask_quoted_paths
  )"
  case "$out" in
    *'<PATH>'*) ;;
    *) fail "path mask did not produce <PATH>" ;;
  esac
  case "$out" in
    *"$h/"*|*"$u/"*|*"file:"*) fail "absolute paths survived masking: $out" ;;
  esac
}

test_debate_prompt_sanitizes_sensitive_quoted_lines() {
  local h="/ho""me" auth_scheme="Bea""rer"
  local out
  local tmp
  tmp="$(mktemp "$TMP/sanitized.XXXXXX")"
  out="$(
    . "$ROOT/scripts/lib/oms-common.sh"
    . "$ROOT/scripts/lib/agent-memory-common.sh"
    . "$ROOT/scripts/lib/agent-task-common.sh"
    . "$ROOT/scripts/lib/peer-common.sh"
    printf 'keep this answer\n%s resource_metadata="https://mcp.example.invalid/resource"\npath %s/u/p.sh\n' "$auth_scheme" "$h" |
      ma_sanitize_quoted_output
  )"
  printf '%s\n' "$out" > "$tmp"
  assert_file_contains "$tmp" "keep this answer"
  assert_file_contains "$tmp" "[REDACTED: sensitive-looking provider output line omitted]"
  case "$out" in
    *"$auth_scheme"*|*"$h/"*) fail "sensitive quoted provider output survived sanitizer: $out" ;;
  esac
  if bash -c ". '$ROOT/scripts/lib/agent-memory-common.sh'; agent_memory_file_has_sensitive_content '$tmp'"; then
    fail "sanitized quoted output must pass outbound sensitive scan"
  fi
}

test_debate_prompt_marks_hidden_unicode_in_quoted_output() {
  local out
  out="$(
    . "$ROOT/scripts/lib/oms-common.sh"
    . "$ROOT/scripts/lib/agent-memory-common.sh"
    . "$ROOT/scripts/lib/agent-task-common.sh"
    . "$ROOT/scripts/lib/peer-common.sh"
    printf 'plain \xc3\xa9 text\nzero\xe2\x80\x8bwidth bidi\xe2\x80\xaeflip tag\xf3\xa0\x80\xa1x\n' |
      ma_sanitize_quoted_output
  )"
  case "$out" in
    *'zero<U+200B>width'*'bidi<U+202E>flip'*'tag<U+E0021>x'*) ;;
    *) fail "hidden unicode was not marked: $out" ;;
  esac
  case "$out" in
    *$'\xe2\x80\x8b'*|*$'\xe2\x80\xae'*|*$'\xf3\xa0\x80\xa1'*) fail "invisible characters survived: $out" ;;
  esac
  case "$out" in
    *$'plain \xc3\xa9 text'*) ;;
    *) fail "ordinary non-ASCII text was altered: $out" ;;
  esac
}

test_oms_run_spine_links_and_joins() {
  local d="$TMP/oms-run-spine"
  local index="$d/.oms/runs/spine.jsonl"
  local SH="$ROOT/scripts/run.sh"
  local id

  mkdir -p "$d"
  id="$(cd "$d" && OMS_RUN_INDEX="$index" "$SH" new --note start 2>/dev/null)"
  [ -n "$id" ] || fail "new printed no run id"
  OMS_RUN_INDEX="$index" OMS_RUN_ID="$id" "$SH" link --tool run-ledger --event append \
    --path x.jsonl >/dev/null 2>&1 || fail "link failed"
  OMS_RUN_INDEX="$index" OMS_RUN_ID="$id" "$SH" link --tool run-capsule --event capture \
    --path c.json >/dev/null 2>&1 || fail "link failed"

  local out
  out="$(OMS_RUN_INDEX="$index" "$SH" show "$id" 2>/dev/null)"
  contains "$out" "run-ledger" || fail "show missing ledger link"
  contains "$out" "run-capsule" || fail "show missing capsule link"
  OMS_RUN_INDEX="$index" "$SH" ls 2>/dev/null | grep -F "$id" > /dev/null || fail "ls missing run"

  # Unknown run id -> nonzero.
  if OMS_RUN_INDEX="$index" "$SH" show no-such-run >/dev/null 2>&1; then
    fail "show of unknown run should fail"
  fi
}

test_oms_run_auto_link_from_capsule() {
  local d="$TMP/oms-run-autolink"
  local spine="$d/.oms/runs/spine.jsonl"
  local SH="$ROOT/scripts/run.sh"
  local id

  make_committed_repo "$d"
  id="$(cd "$d" && OMS_RUN_INDEX="$spine" "$SH" new 2>/dev/null)"
  ( cd "$d" && OMS_RUNS_DIR="$d/.oms/runs" OMS_RUN_INDEX="$spine" OMS_RUN_ID="$id" \
    "$ROOT/scripts/run-capsule.sh" run --no-ledger -- bash -c 'echo hi' >/dev/null 2>&1 ) ||
    fail "capsule run failed"
  # The capsule auto-linked itself into the spine for this run id.
  OMS_RUN_INDEX="$spine" "$SH" show "$id" 2>/dev/null | grep -F "run-capsule" > /dev/null ||
    fail "capsule did not auto-link into the run spine"
}

test_oms_run_validate_detects_malformed_jsonl() {
  local d="$TMP/oms-run-validate"
  local SH="$ROOT/scripts/run.sh"
  local out

  mkdir -p "$d/.oms/runs"
  printf '%s\n' '{"schema":1,"run_id":"r","tool":"t","event":"e"}' > "$d/.oms/runs/spine.jsonl"
  ( cd "$d" && "$SH" validate --dir "$d/.oms" >/dev/null 2>&1 ) ||
    fail "validate should pass on well-formed jsonl"
  printf '%s\n' 'this is not json{' >> "$d/.oms/runs/spine.jsonl"
  if ( cd "$d" && "$SH" validate --dir "$d/.oms" >/dev/null 2>&1 ); then
    fail "validate should fail on a malformed jsonl line"
  fi
  printf '%s\n' '{"schema":1,"run_id":"r","tool":"t","event":"new"}' \
    '{"schema":0,"run_id":"r2","tool":"t","event":"new"}' > "$d/.oms/runs/spine.jsonl"
  out="$(cd "$d" && "$SH" validate --dir "$d/.oms" 2>&1)" &&
    fail "schema drift must make validate exit nonzero"
  contains "$out" "DRIFT" || fail "validate should tag the drifted family"
}

test_oms_run_diff_compares_capsules() {
  local d="$TMP/oms-run-diff"
  local spine="$d/.oms/runs/spine.jsonl"
  local SH="$ROOT/scripts/run.sh"
  local cap="$ROOT/scripts/run-capsule.sh"
  local a b out

  make_committed_repo "$d"
  printf '{"auc": 0.74, "ok": false, "label": "old", "empty": null}\n' > "$d/mA.json"
  printf '{"auc": 0.82, "ok": true, "label": "new", "empty": null}\n' > "$d/mB.json"
  # Run A reads the manifest before a row is added to train; run B after. A second manifest only B names.
  printf 'a\nb\n' > "$d/train.txt"
  ( cd "$d" && "$ROOT/scripts/data-manifest.sh" create --name ds --split train=train.txt >/dev/null 2>&1 ) ||
    fail "manifest create failed"
  ( cd "$d" && "$ROOT/scripts/data-manifest.sh" create --name extra --split train=train.txt >/dev/null 2>&1 ) ||
    fail "second manifest create failed"
  # The same config path changes between the runs; a second one is unparsed text.
  printf '{"lr": 0.001, "model": {"depth": 4, "act": "relu"}, "tags": ["a", "b"], "drop": 0.1}\n' > "$d/hp.json"
  printf 'lr=0.001\n' > "$d/hp.ini"
  a="$(cd "$d" && OMS_RUN_INDEX="$spine" "$SH" new 2>/dev/null)"
  ( cd "$d" && OMS_RUNS_DIR="$d/.oms/runs" OMS_RUN_INDEX="$spine" OMS_RUN_ID="$a" env -u LOADEDMODULES \
    "$cap" run --seed 1 --metrics mA.json --config hp.json --config hp.ini --data ds --no-ledger -- true >/dev/null 2>&1 ) ||
    fail "run A failed"
  printf 'c\n' >> "$d/train.txt"
  ( cd "$d" && "$ROOT/scripts/data-manifest.sh" create --name ds --policy random --split train=train.txt >/dev/null 2>&1 ) ||
    fail "manifest update failed"
  printf '{"lr": 0.0003, "model": {"depth": 6, "act": "relu"}, "tags": ["a"], "warmup": 100}\n' > "$d/hp.json"
  printf 'lr=0.0003\n' > "$d/hp.ini"
  b="$(cd "$d" && OMS_RUN_INDEX="$spine" "$SH" new 2>/dev/null)"
  ( cd "$d" && OMS_RUNS_DIR="$d/.oms/runs" OMS_RUN_INDEX="$spine" OMS_RUN_ID="$b" LOADEDMODULES='cuda/12.1' \
    "$cap" run --seed 2 --metrics mB.json --config hp.json --config hp.ini --data ds --data extra --no-ledger \
    -- true >/dev/null 2>&1 ) || fail "run B failed"

  out="$(cd "$d" && OMS_RUN_INDEX="$spine" "$SH" diff "$a" "$b" 2>/dev/null)"
  contains "$out" "metric:auc" || fail "diff missing metric line"
  contains "$out" "0.08" || fail "diff missing metric delta"
  contains "$out" "seeds" || fail "diff missing seeds line"
  printf '%s\n' "$out" | grep -E '^modules +!=  \(none\)  \|  cuda/12\.1$' > /dev/null || fail "diff missing the modules line"
  printf '%s\n' "$out" | grep -E '^host +== ' > /dev/null || fail "diff missing the host line"
  printf '%s\n' "$out" | grep -E '^data:ds +!=  [0-9a-f]{12} \(train=2\)  \|  [0-9a-f]{12} \(train=3\) policy=random$' > /dev/null ||
    fail "diff missing the changed data manifest or its policy: $out"
  printf '%s\n' "$out" | grep -E '^data:extra +!=  -  \|  [0-9a-f]{12} \(train=2\)$' > /dev/null ||
    fail "diff missing the manifest only one run named: $out"
  # Config differences are named key by key; an unchanged key is not listed.
  printf '%s\n' "$out" | grep -Fx '  lr: 0.001 → 0.0003' > /dev/null || fail "diff missing the changed key: $out"
  printf '%s\n' "$out" | grep -Fx '  model.depth: 4 → 6' > /dev/null || fail "diff missing the nested key: $out"
  printf '%s\n' "$out" | grep -Fx '  tags: ["a","b"] → ["a"]' > /dev/null || fail "diff missing the list value: $out"
  printf '%s\n' "$out" | grep -Fx '  - drop: 0.1' > /dev/null || fail "diff missing the removed key: $out"
  printf '%s\n' "$out" | grep -Fx '  + warmup: 100' > /dev/null || fail "diff missing the added key: $out"
  ! contains "$out" "model.act" || fail "an unchanged key must not be listed: $out"
  contains "$out" "(keys of $a: not parsed: only JSON and YAML configs are flattened)" ||
    fail "diff should say why an unparsed config has no key view: $out"
  printf '%s\n' "$out" | grep -F "metric:ok" > "$d/okline" || fail "diff missing bool metric"
  if grep -Fq "(Δ" "$d/okline"; then
    fail "bool metrics must not be treated as numeric deltas"
  fi

  # Missing capsule -> nonzero.
  if ( cd "$d" && OMS_RUN_INDEX="$spine" "$SH" diff "$a" no-such-run >/dev/null 2>&1 ); then
    fail "diff with an unknown run should fail"
  fi

  # Claims tie a number a report states to the capsule that recorded it, and
  # figure records tie an image to its script and input runs. Both only read:
  # nothing is re-run. Most checks skip the external tree probe with
  # --no-verify; capsule bytes are still checked against their recorded pins.
  local claims="$d/.oms/claims.jsonl" figures="$d/.oms/figures.jsonl" rc=0
  run_prov() { ( cd "$d" && OMS_RUNS_DIR="$d/.oms/runs" OMS_RUN_INDEX="$spine" "$SH" "$@" ); }
  run_prov claims add --metric auc --value 0.82 --run "$b" --where 'paper/results.tex:42' --id tab1-auc \
    >/dev/null 2>"$d/claim-add.err" || fail "claims add failed: $(cat "$d/claim-add.err")"
  assert_file_contains "$d/claim-add.err" "claim tab1-auc: auc=0.82 matches the recorded 0.82"
  run_prov claims add --metric auc --value 0.75 --tolerance 0.02 --run "$a" --id base-auc >/dev/null 2>&1 ||
    fail "claims add with a tolerance failed"
  [ "$(wc -l < "$claims" | tr -d ' ')" = 2 ] || fail "each claim is one appended row"
  out="$(run_prov claims check --no-verify)" || fail "claims inside tolerance must check clean: $out"
  contains "$out" "match    tab1-auc  auc: claimed 0.82, recorded 0.82 (tolerance 0)" || fail "claims check missing the exact match: $out"
  contains "$out" "@ paper/results.tex:42" || fail "claims check dropped where the number is stated"
  contains "$out" "match    base-auc  auc: claimed 0.75, recorded 0.74 (tolerance 0.02)" || fail "tolerance not applied: $out"
  contains "$out" "note: single seed" || fail "a one-seed run must be noted, not ranked: $out"
  contains "$out" "nothing was re-run and a match is not a reproduction" || fail "claims check must not read as a reproduction"
  # A number the capsule did not record is a mismatch and fails the check; re-recording the id corrects it.
  run_prov claims add --metric auc --value 0.9 --run "$b" --id tab1-auc >/dev/null 2>"$d/claim-add.err" ||
    fail "a claim that disagrees is still recorded so check can report it"
  assert_file_contains "$d/claim-add.err" "DOES NOT MATCH"
  rc=0; out="$(run_prov claims check --no-verify)" || rc=$?
  [ "$rc" = 1 ] || fail "a mismatched claim must exit 1, got $rc"
  contains "$out" "mismatch tab1-auc  auc: claimed 0.9, recorded 0.82" || fail "mismatch not reported: $out"
  contains "$out" "1 match, 1 mismatch" || fail "claims summary wrong: $out"
  out="$(run_prov claims check --no-verify --json)" || true
  contains "$out" '"kind": "oms-run-claims-check"' || fail "claims check --json missing its kind"
  run_prov claims add --metric auc --value 0.82 --run "$b" --id tab1-auc >/dev/null 2>&1 || fail "correcting a claim failed"
  run_prov claims check --no-verify tab1-auc >/dev/null || fail "the corrected claim must check clean"
  # Refusals write nothing: unknown run, a metric the capsule lacks, a non-number, a bool metric.
  rc=0; run_prov claims add --metric auc --value 0.5 --run no-such-run >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "an unknown run must be refused"
  rc=0; run_prov claims add --metric f1 --value 0.5 --run "$b" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a metric the capsule did not record must be refused"
  rc=0; run_prov claims add --metric ok --value 1 --run "$b" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a boolean metric is not a number to claim"
  rc=0; run_prov claims add --metric auc --value high --run "$b" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a non-numeric value must be refused"
  [ "$(wc -l < "$claims" | tr -d ' ')" = 4 ] || fail "a refused claim must not be written"
  # A capsule that is gone makes its claim missing, never a silent pass.
  mv "$d/.oms/runs" "$d/.oms/runs.away"
  rc=0; out="$(run_prov claims check --no-verify 2>&1)" || rc=$?
  mv "$d/.oms/runs.away" "$d/.oms/runs"
  [ "$rc" = 1 ] || fail "claims whose capsules are gone must exit 1"
  contains "$out" "missing  tab1-auc" || fail "missing capsule not reported: $out"

  # Figures: digests of the output and the script, the input runs, and a command kept as text.
  mkdir -p "$d/figs" "$d/plots"
  printf 'png-bytes-v1\n' > "$d/figs/roc.png"
  printf 'print("plot")\n' > "$d/plots/roc.py"
  printf 'touch "%s/figure-command-ran"\n' "$d" > "$d/regen.sh"
  run_prov figure record --output figs/roc.png --script plots/roc.py --run "$a" --run "$b" \
    --command "sh regen.sh" --id fig-roc >/dev/null 2>"$d/fig.err" || fail "figure record failed: $(cat "$d/fig.err")"
  assert_file_contains "$d/fig.err" "figure fig-roc: recorded figs/roc.png from plots/roc.py (2 input run(s)); nothing was run"
  out="$(run_prov figure verify)" || fail "an untouched figure must verify: $out"
  contains "$out" "current  fig-roc  figs/roc.png  <- plots/roc.py  (2 input run(s))" || fail "figure verify line wrong: $out"
  python3 - "$ROOT" "$d" <<'PY' || fail "claim/figure capsule snapshots lost freshness or changed records"
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys

root, project = map(Path, sys.argv[1:])
claims = project / '.oms/claims.jsonl'
figures = project / '.oms/figures.jsonl'
spine = project / '.oms/runs/spine.jsonl'
claim_rows = [json.loads(line) for line in claims.read_text().splitlines()]
claim = next(row for row in reversed(claim_rows) if row['id'] == 'tab1-auc')
figure = json.loads(figures.read_text())
capsule = project / '.oms/runs' / claim['capsule'] / 'capsule.json'
saved = {path: path.read_bytes() for path in (claims, figures, spine, capsule)}
env = dict(os.environ, OMS_RUNS_DIR=str(project / '.oms/runs'), OMS_RUN_INDEX=str(spine))

def run(*args, code=0, reader=True):
    before = {path: path.read_bytes() if path.exists() else None for path in saved}
    done = subprocess.run([str(root / 'scripts/run.sh'), *args], cwd=project, env=env,
                          capture_output=True, text=True, timeout=30)
    assert done.returncode == code, (args, done.returncode, done.stdout, done.stderr)
    if reader:
        assert before == {path: path.read_bytes() if path.exists() else None for path in saved}, args
        return json.loads(done.stdout)

def check_claim(code=0, strict=False):
    args = ['claims', 'check', 'tab1-auc', '--no-verify', '--json']
    return run(*args, *(['--strict'] if strict else []), code=code)

def write_claim(row):
    claims.write_text(json.dumps(row) + '\n')

def write_figure(row):
    figures.write_text(json.dumps(row) + '\n')

try:
    changed = json.loads(saved[capsule])
    changed['configs'][0]['sha256'] = 'f' * 32
    changed['seeds'] = ['91']
    capsule.write_text(json.dumps(changed))
    # The old verifier passes here: same path/id/metric, different input metadata.
    result = run('figure', 'verify', 'fig-roc', '--json', code=1)
    assert result['figures'][0]['status'] == 'stale', result
    assert any('input capsule changed since it was recorded' in why
               for why in result['figures'][0]['reasons']), result
    result = check_claim()
    row = result['claims'][0]
    assert row['status'] == 'match' and row['claimed'] == row['recorded'] == 0.82, result
    assert row['capsule_content_verifies'] is False and result['stale'] == 1, result
    check_claim(code=1, strict=True)

    # Re-recording is explicit; checks never replace the earlier baseline.
    run('claims', 'add', '--metric', 'auc', '--value', '0.82', '--run', claim['capsule'],
        '--id', 'tab1-auc', reader=False)
    run('figure', 'record', '--output', 'figs/roc.png', '--script', 'plots/roc.py',
        '--run', claim['capsule'], '--id', 'fig-roc', reader=False)
    assert check_claim()['claims'][0]['capsule_content_verifies'] is True
    assert run('figure', 'verify', 'fig-roc', '--json')['stale'] == 0
    claims.write_bytes(saved[claims]); figures.write_bytes(saved[figures])
    capsule.write_bytes(saved[capsule])
    assert claim['capsule_sha256'] == hashlib.sha256(saved[capsule]).hexdigest()
    assert figure['capsule_sha256'][claim['capsule']] == claim['capsule_sha256']
    assert check_claim(strict=True)['claims'][0]['capsule_content_verifies'] is True
    assert run('figure', 'verify', 'fig-roc', '--json')['stale'] == 0
    capsule.write_bytes(saved[capsule] + b'\n')
    assert check_claim()['claims'][0]['capsule_content_verifies'] is False
    run('figure', 'verify', 'fig-roc', '--json', code=1)
    capsule.write_bytes(saved[capsule])

    legacy_claim = {key: value for key, value in claim.items() if key != 'capsule_sha256'}
    legacy_figure = {key: value for key, value in figure.items() if key != 'capsule_sha256'}
    write_claim(legacy_claim); write_figure(legacy_figure)
    result = check_claim()
    assert result['claims'][0]['status'] == 'match', result
    assert result['claims'][0]['capsule_content_verifies'] is None and result['unverified'] == 1, result
    assert any('unverified' in note for note in result['claims'][0]['notes']), result
    check_claim(code=1, strict=True)
    result = run('figure', 'verify', 'fig-roc', '--json', code=1)
    assert any('not pinned' in why for why in result['figures'][0]['reasons']), result

    for bad in (None, [], 'not-a-sha256'):
        write_claim(dict(claim, capsule_sha256=bad))
        write_figure(dict(figure, capsule_sha256={**figure['capsule_sha256'], claim['capsule']: bad}))
        result = check_claim(code=1, strict=True)
        assert result['claims'][0]['capsule_content_verifies'] is False, result
        assert result['stale'] == 1, result
        result = run('figure', 'verify', 'fig-roc', '--json', code=1)
        assert len(result['figures'][0]['reasons']) == 1, result
        assert 'digest is invalid' in result['figures'][0]['reasons'][0], result
    write_figure(dict(figure, capsule_sha256=[]))
    run('figure', 'verify', 'fig-roc', '--json', code=1)
    claims.write_bytes(saved[claims]); figures.write_bytes(saved[figures])

    # Malformed documents, mismatched IDs, and unsafe IDs cannot resolve as the pinned capsule.
    for raw in (b'{', b'\xff', b'[]', b'[' * 2000,
                json.dumps(dict(changed, id='different')).encode(),
                json.dumps(dict(changed, id='../outside')).encode()):
        capsule.write_bytes(raw)
        assert check_claim(code=1)['claims'][0]['status'] == 'missing'
        run('figure', 'verify', 'fig-roc', '--json', code=1)
    capsule.unlink()
    # A new alias with the old capsule id must not retarget a saved record.
    other = project / '.oms/runs' / figure['capsules'][0] / 'capsule.json'
    spine.write_bytes(saved[spine] + (json.dumps({'run_id': claim['capsule'], 'tool': 'run-capsule',
                                                'path': str(other)}) + '\n').encode())
    assert check_claim(code=1)['claims'][0]['status'] == 'missing'
    run('figure', 'verify', 'fig-roc', '--json', code=1)
    spine.write_bytes(saved[spine])
    capsule.write_bytes(saved[capsule] + b' ' * (8 * 1024 * 1024 + 1 - len(saved[capsule])))
    assert check_claim(code=1)['claims'][0]['status'] == 'missing'
    run('figure', 'verify', 'fig-roc', '--json', code=1)
    capsule.write_bytes(saved[capsule])

    literal = project / '.oms/runs/run..retry/capsule.json'
    literal.parent.mkdir()
    literal.write_text(json.dumps(dict(changed, id='run..retry')))
    run('claims', 'add', '--metric', 'auc', '--value', '0.82', '--run', 'run..retry',
        '--id', 'literal-id', reader=False)
    assert run('claims', 'check', 'literal-id', '--no-verify', '--json')['claims'][0]['capsule_content_verifies'] is True

    run('figure', 'record', '--output', 'figs/roc.png', '--script', 'plots/roc.py',
        '--id', 'fig-no-input', reader=False)
    assert run('figure', 'verify', 'fig-no-input', '--json')['stale'] == 0
    no_input = json.loads(figures.read_text().splitlines()[-1])
    no_input.pop('capsule_sha256', None)
    write_figure(no_input)
    assert run('figure', 'verify', 'fig-no-input', '--json')['stale'] == 0
    assert not (project / 'figure-command-ran').exists()
finally:
    for path, raw in saved.items():
        path.write_bytes(raw)
PY
  printf 'print("plot v2")\n' > "$d/plots/roc.py"
  rc=0; out="$(run_prov figure verify)" || rc=$?
  [ "$rc" = 1 ] || fail "a figure whose script changed must exit 1"
  contains "$out" "stale    fig-roc" || fail "stale figure not reported: $out"
  contains "$out" "script changed since it was recorded: plots/roc.py" || fail "stale reason missing: $out"
  contains "$out" "recorded command (not run): sh regen.sh" || fail "the recorded command must be shown, not run: $out"
  [ ! -e "$d/figure-command-ran" ] || fail "figure verify must never run the recorded command"
  rm -f "$d/figs/roc.png"
  rc=0; out="$(run_prov figure verify fig-roc --json)" || rc=$?
  [ "$rc" = 1 ] || fail "a missing figure output must exit 1"
  contains "$out" "output is gone or unreadable: figs/roc.png" || fail "missing output not reported: $out"
  # Paths outside the repository and unknown input runs are refused; nothing is written.
  printf 'x\n' > "$TMP/outside.png"
  rc=0; run_prov figure record --output "$TMP/outside.png" --script plots/roc.py >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "an output outside the repository must be refused"
  printf 'png\n' > "$d/figs/roc.png"
  rc=0; run_prov figure record --output figs/roc.png --script plots/roc.py --run no-such-run >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "an unknown input run must be refused"
  [ "$(wc -l < "$figures" | tr -d ' ')" = 1 ] || fail "a refused figure must not be written"
  # With the capsule comparison on, a claim whose run still matches the tree is clean; once the tree
  # moves on the number still matches but is stale, which only --strict turns into a failure.
  out="$(run_prov claims check)" || fail "claims on an unchanged tree must check clean: $out"
  ! contains "$out" "stale" || fail "an unchanged tree is not stale: $out"
  git -C "$d" commit --allow-empty -m later >/dev/null
  out="$(run_prov claims check)" || fail "a stale capsule alone must not fail the check: $out"
  contains "$out" "note: stale: the tree no longer matches the run's capsule" || fail "stale capsule not noted: $out"
  contains "$out" "2 match, 2 stale" || fail "stale count missing: $out"
  rc=0; run_prov claims check --strict >/dev/null || rc=$?
  [ "$rc" = 1 ] || fail "claims check --strict must fail on a stale capsule"
  # The records are ordinary .oms JSONL: the spine's validator reads them.
  run_prov validate >/dev/null 2>&1 || fail "claims and figures rows must pass run validate"
}

test_run_ledger_top_ranks_metrics() {
  local d="$TMP/ledger-top"
  local SH="$ROOT/scripts/run-ledger.sh"
  local ledger="$d/EXPERIMENTS.jsonl"
  local out
  local rc=0

  mkdir -p "$d"
  cat > "$ledger" <<'EOF'
{"ts":"2026-01-01T00:00:00Z","git_sha":"aaa1111","dirty":0,"dirty_hash":"","slurm_job_id":"","exit":0,"duration_s":10,"note":"baseline","cmd":["train","--lr","1e-3"],"metrics":{"auc":0.71,"loss":0.40}}
{"ts":"2026-01-02T00:00:00Z","git_sha":"bbb2222","dirty":0,"dirty_hash":"","slurm_job_id":"","exit":0,"duration_s":10,"note":"best","cmd":["train","--lr","3e-4"],"metrics":{"auc":0.83,"loss":0.31}}
{"ts":"2026-01-03T00:00:00Z","git_sha":"ccc3333","dirty":0,"dirty_hash":"","slurm_job_id":"","exit":1,"duration_s":10,"note":"crashed","cmd":["train","--lr","1e-2"],"metrics":{"auc":0.99}}
{"ts":"2026-01-04T00:00:00Z","git_sha":"ddd4444","dirty":0,"dirty_hash":"","slurm_job_id":"","exit":0,"duration_s":10,"note":"strval","cmd":["train"],"metrics":{"auc":"bad"}}
EOF

  out="$("$SH" top --metric auc --file "$ledger")"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "auc=0.83" > /dev/null || {
    local top_status=("${PIPESTATUS[@]}")
    fail "top should rank the best exit-0 run first (pipeline status: ${top_status[*]}; output: $out)"
  }
  if contains "$out" "0.99"; then
    fail "failed runs must be excluded without --all"
  fi

  out="$("$SH" top --metric auc --all --file "$ledger")"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "auc=0.99" > /dev/null || fail "--all should include failed runs"

  out="$("$SH" top --metric loss --min --file "$ledger" 1)"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "loss=0.31" > /dev/null || fail "--min should rank the lowest loss first"
  [ "$(printf '%s\n' "$out" | wc -l | tr -d ' ')" = "1" ] || fail "N should cap the ranked table"

  "$SH" top --metric nope --file "$ledger" >/dev/null 2>"$d/err" || rc=$?
  [ "$rc" = "3" ] || fail "a missing metric should exit 3, got $rc"
  assert_file_contains "$d/err" "no ledger rows"

  # A metric contract beside the ledger: each finished row records what it said,
  # top takes its direction, and only runs measured under today's contract rank.
  local repo="$d/repo" row
  mkdir -p "$repo/docs"
  git -C "$repo" init -q
  printf 'print(1)\n' > "$repo/eval.py"
  cat > "$repo/docs/metric-contract.json" <<'EOF'
{"schema": 1, "metrics": {"loss": {"direction": "min", "unit": "nats", "split": "val",
  "aggregation": "mean", "eval_command": "python eval.py", "eval_code": ["eval.py"]}}}
EOF
  ledger_record() {  # LOSS then ledger options and the command
    local value="$1"
    shift
    printf '{"loss": %s}\n' "$value" > "$repo/m.json"
    (cd "$repo" && "$SH" --metrics m.json "$@" >/dev/null 2>"$d/record-err") ||
      fail "recording a run under a metric contract failed: $(cat "$d/record-err")"
  }
  # An old row: same metric name, no contract recorded.
  printf '%s\n' '{"ts":"2026-01-01T00:00:00Z","git_sha":"aaa1111","dirty":0,"dirty_hash":"","slurm_job_id":"","exit":0,"duration_s":1,"note":"","cmd":["old"],"metrics":{"loss":0.01}}' \
    > "$repo/docs/EXPERIMENTS.jsonl"
  ledger_record 0.50 -- true --seed 1
  ledger_record 0.30 -- true --seed 2
  ledger_record 0.90 --seed 7 --group other -- true
  row="$(sed -n '2p' "$repo/docs/EXPERIMENTS.jsonl")"
  printf '%s' "$row" | python3 -c '
import json, sys
row = json.load(sys.stdin)
entry = row["metric_contract"]["loss"]
assert entry["direction"] == "min" and entry["split"] == "val" and entry["unit"] == "nats", entry
assert len(entry["digest"]) == 64 and len(entry["eval_sha256"]) == 64, entry
assert "eval_command" not in entry, entry
assert row["seed"] == 1 and len(row["group"]) == 12, row
' || fail "a finished row should record the metric contract, its seed and its group: $row"
  [ "$(sed -n '2p;3p' "$repo/docs/EXPERIMENTS.jsonl" | python3 -c '
import json, sys
print(len({json.loads(line)["group"] for line in sys.stdin}))')" = 1 ] ||
    fail "runs that differ only by seed should share one group"
  out="$(cd "$repo" && "$SH" top --metric loss 2>"$d/top-err")" || fail "top under a contract failed: $(cat "$d/top-err")"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "loss=0.3" > /dev/null ||
    fail "top should take the contract's direction (min) without a flag: $out"
  if contains "$out" "loss=0.01"; then
    fail "a run with no recorded contract must not rank beside contract runs: $out"
  fi
  assert_file_contains "$d/top-err" "left out as not comparable under today's contract for loss: 1 run(s): no contract recorded"
  out="$(cd "$repo" && "$SH" top --metric loss --max 2>"$d/top-err")"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "loss=0.9" > /dev/null || fail "an explicit --max still wins: $out"
  assert_file_contains "$d/top-err" "the metric contract declares min for loss"
  out="$(cd "$repo" && "$SH" top --metric loss --mixed 2>"$d/top-err")"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "loss=0.01" > /dev/null || fail "--mixed ranks every row: $out"
  assert_file_contains "$d/top-err" "--mixed ranks runs measured under different metric contracts together"

  # Seed groups rank by mean; a single seed is listed apart and claims nothing.
  out="$(cd "$repo" && "$SH" top --metric loss --by-group 2>"$d/top-err")" || fail "--by-group failed: $(cat "$d/top-err")"
  printf '%s\n' "$out" | sed -n '1p' | grep -F " 1  loss mean=0.4  stdev=0.141421  ci95=[" > /dev/null ||
    fail "--by-group should print the mean, stdev and interval of the two-seed group: $out"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "n=2" | grep -F "seeds=1,2" > /dev/null || fail "--by-group should name n and seeds: $out"
  printf '%s\n' "$out" | sed -n '2p' | grep -F "single seed (no claim that one is better):" > /dev/null ||
    fail "a one-seed group must be listed apart: $out"
  printf '%s\n' "$out" | sed -n '3p' | grep -F "loss=0.9  n=1  group=other  seed=7" > /dev/null || fail "single-seed row: $out"

  # `table` prints the same aggregates paste-ready: ranked, single seeds marked and never bold.
  out="$(cd "$repo" && "$SH" table --metric loss 2>"$d/top-err")" || fail "table failed: $(cat "$d/top-err")"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "4 significant digits" > /dev/null || fail "table header should state the digit rule: $out"
  printf '%s\n' "$out" | grep -F "| 1 | " | grep -F "0.4000 ± 0.1414 | [" | grep -F "| 2 |" > /dev/null ||
    fail "table should print mean ± stdev, ci95 and n of the two-seed group: $out"
  printf '%s\n' "$out" | grep -F "| - | other | 0.9000 | - | 1 | single seed |" > /dev/null || fail "table single-seed row: $out"
  mkdir -p "$d/tbl"
  for spec in 'a_b 1 1' 'a_b 2 3' 'c_d 1 5' 'c_d 2 7' 'solo_x 1 0.5'; do
    set -- $spec
    printf '{"ts":"2026-01-01T00:00:00Z","git_sha":"a","dirty":0,"exit":0,"cmd":["t"],"group":"%s","seed":%s,"metrics":{"loss":%s}}\n' \
      "$1" "$2" "$3" >> "$d/tbl/L.jsonl"
  done
  out="$("$SH" table --metric loss --min --file "$d/tbl/L.jsonl")" || fail "table --min failed"
  printf '%s\n' "$out" | grep -F "| 1 | a_b | **2.000 ± 1.414** |" > /dev/null || fail "table should rank and bold the best group: $out"
  printf '%s\n' "$out" | grep -F "| 2 | c_d | 6.000 ± 1.414 |" > /dev/null || fail "table second group: $out"
  printf '%s\n' "$out" | grep -F "| - | solo_x | 0.5000 | - | 1 | single seed |" > /dev/null || fail "a one-seed group is marked, not bold: $out"
  out="$("$SH" table --metric loss --max --format tsv --file "$d/tbl/L.jsonl")"
  printf '%s\n' "$out" | sed -n '3p' | grep -F "$(printf '1\tc_d\t6.000 ± 1.414')" > /dev/null || fail "tsv with --max: $out"
  out="$("$SH" table --metric loss --min --format tex --file "$d/tbl/L.jsonl")"
  printf '%s\n' "$out" | grep -F 'a\_b' | grep -F '\textbf{$2.000 \pm 1.414$}' > /dev/null || fail "tex should escape underscores: $out"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "% loss:" > /dev/null || fail "tex header comment: $out"
  rc=0
  "$SH" table --metric loss --format html --file "$d/tbl/L.jsonl" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "an unknown table format must exit 2, got $rc"
  rc=0
  "$SH" table --metric nope --file "$d/tbl/L.jsonl" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "table on a missing metric exits 3 like top, got $rc"

  # Changing what the number means makes the earlier runs not comparable.
  printf 'print(2)\n' > "$repo/eval.py"
  rc=0
  (cd "$repo" && "$SH" top --metric loss >/dev/null 2>"$d/top-err") || rc=$?
  [ "$rc" = 4 ] || fail "runs measured by different eval code must not rank (exit 4), got $rc"
  assert_file_contains "$d/top-err" "top: not comparable: loss runs do not share one metric contract"
  assert_file_contains "$d/top-err" "3 run(s): eval_sha256"
  ledger_record 0.20 -- true --seed 1
  out="$(cd "$repo" && "$SH" top --metric loss 2>/dev/null)"
  [ "$(printf '%s\n' "$out" | wc -l | tr -d ' ')" = 1 ] || fail "only the run under the new eval code should rank: $out"

  # A broken contract never blocks a run, and never silently ranks.
  printf '{"schema": 1, "metrics": {"loss": {"direction": "up"}}}\n' > "$repo/docs/metric-contract.json"
  ledger_record 0.10 -- true
  assert_file_contains "$d/record-err" "ledger: metric contract ignored"
  if tail -n 1 "$repo/docs/EXPERIMENTS.jsonl" | grep -q metric_contract; then
    fail "a broken contract must not be recorded"
  fi
  rc=0
  (cd "$repo" && "$SH" top --metric loss >/dev/null 2>"$d/top-err") || rc=$?
  [ "$rc" = 2 ] || fail "top must refuse an unreadable contract (exit 2), got $rc"
  assert_file_contains "$d/top-err" "metric contract unreadable"

  # Split roles are advisory: a final split's evaluations are counted, nothing is gated.
  cat > "$repo/docs/metric-contract.json" <<'EOF'
{"schema": 1, "metrics": {"loss": {"direction": "min", "split": "val"},
  "test_loss": {"direction": "min", "split": "test"}},
 "splits": {"val": {"role": "selection"}, "test": {"role": "final"}}}
EOF
  rm -f "$repo/docs/EXPERIMENTS.jsonl"
  split_record() {  # METRICS-JSON then the command
    printf '%s\n' "$1" > "$repo/m.json"
    shift
    (cd "$repo" && "$SH" --metrics m.json -- "$@" >/dev/null 2>"$d/record-err") ||
      fail "recording a run with a final split failed: $(cat "$d/record-err")"
  }
  split_record '{"loss": 0.5}' true --seed 1
  split_record '{"loss": 0.4, "test_loss": 0.45}' true --seed 1
  split_record '{"loss": 0.4, "test_loss": 0.46}' true --seed 2
  out="$(cd "$repo" && "$SH" top --metric loss 2>"$d/top-err")" || fail "top with split roles failed: $(cat "$d/top-err")"
  assert_file_contains "$d/top-err" "2 recorded run(s) reported a metric on the final split test"
  assert_file_contains "$d/top-err" "seed group "
  assert_file_contains "$d/top-err" ": 2 run(s)"
  if grep -Fq "evaluated" "$d/top-err"; then
    fail "one variant evaluated twice is not several variants: $(cat "$d/top-err")"
  fi
  split_record '{"loss": 0.3, "test_loss": 0.4}' true other --seed 1
  split_record '{"test_loss": 0.35}' true third
  (cd "$repo" && "$SH" top --metric loss >"$d/top-out" 2>"$d/top-err") || fail "top with split roles failed"
  assert_file_contains "$d/top-err" "4 recorded run(s) reported a metric on the final split test"
  assert_file_contains "$d/top-err" "no seed group: 1 run(s)"
  assert_file_contains "$d/top-err" "test split evaluated 4 times across 3 variants"
  # Without the block the same ledger prints exactly what it printed.
  cp "$d/top-out" "$d/top-out-roles"
  printf '{"schema": 1, "metrics": {"loss": {"direction": "min", "split": "val"}}}\n' > "$repo/docs/metric-contract.json"
  (cd "$repo" && "$SH" top --metric loss >"$d/top-out" 2>"$d/top-err") || fail "top without split roles failed"
  if grep -Fq "advisory" "$d/top-err"; then
    fail "a contract without split roles must stay silent: $(cat "$d/top-err")"
  fi
  cmp -s "$d/top-out" "$d/top-out-roles" || fail "split roles must not change the ranking output"
  # A malformed block warns and ranks on.
  printf '{"schema": 1, "metrics": {"loss": {"direction": "min", "split": "val"}}, "splits": {"test": {"role": "last"}}}\n' \
    > "$repo/docs/metric-contract.json"
  (cd "$repo" && "$SH" top --metric loss >/dev/null 2>"$d/top-err") || fail "a bad splits block must not fail top"
  assert_file_contains "$d/top-err" "warning: split roles ignored"
}

test_oms_run_timeline_merges_streams() {
  local d="$TMP/timeline"
  local SH="$ROOT/scripts/run.sh"
  local out

  mkdir -p "$d/.oms/runs" "$d/.oms/artifacts" "$d/docs"
  printf '{"schema":1,"run_id":"r1","ts":"2026-01-01T01:00:00Z","tool":"oms-run","event":"new","agent":"codex"}\n' > "$d/.oms/runs/spine.jsonl"
  out="$(cd "$d" && "$SH" timeline --json)" ||
    fail "timeline --json should succeed"
  printf '%s' "$out" | python3 -c '
import json, sys
d = json.load(sys.stdin)
assert d.get("schema") == 1
assert d.get("omitted") == 0, d
evs = d.get("events")
assert isinstance(evs, list) and len(evs) == 1, evs
assert evs[0]["ts"] == "2026-01-01T01:00:00Z", evs[0]
assert evs[0]["stream"] == "runs/spine", evs[0]
assert evs[0]["row"]["run_id"] == "r1", evs[0]
' || fail "timeline --json must emit schema-1 events with raw rows"

  printf '{"ts":"2026-01-01T02:00:00Z","kind":"delegate","provider":"codex","exit":0,"task_id":"t1"}\n' > "$d/.oms/artifacts/index.jsonl"
  printf '{"ts":"2026-01-01T03:00:00Z","git_sha":"abc","dirty":0,"exit":0,"duration_s":5,"note":"tl run","cmd":["train"]}\n' > "$d/docs/EXPERIMENTS.jsonl"

  out="$(cd "$d" && "$SH" timeline)"
  contains "$out" "runs/spine" || fail "timeline should include the spine stream"
  contains "$out" "artifacts/index" || fail "timeline should include the artifact index stream"
  contains "$out" "ledger" || fail "timeline should include the run ledger"
  printf '%s\n' "$out" | sed -n '1p' | grep -F "01:00:00Z" > /dev/null || fail "timeline should be time-ordered (oldest first)"
  printf '%s\n' "$out" | tail -n 1 | grep -F "03:00:00Z" > /dev/null || fail "the newest event should print last"

  out="$(cd "$d" && "$SH" timeline --since 2026-01-01T02:30:00Z)"
  if contains "$out" "spine"; then
    fail "--since should filter out earlier events"
  fi
  contains "$out" "ledger" || fail "--since should keep later events"

  out="$(cd "$d" && "$SH" timeline --limit 1)"
  contains "$out" "omitted" || fail "--limit should report omitted earlier events"

  ( cd "$d" && OMS_AGENT=antigravity "$SH" link --run-id r1 --tool run-ledger --event append >/dev/null 2>&1 )
  ( cd "$d" && "$SH" timeline --agent antigravity 2>/dev/null | grep -F "agent=antigravity" > /dev/null ) ||
    fail "timeline --agent should include matching rows"
  if ( cd "$d" && "$SH" timeline --agent codex 2>/dev/null | grep -F "agent=antigravity" > /dev/null ); then
    fail "timeline --agent should exclude non-matching rows"
  fi
  ( cd "$d" && "$SH" timeline --tool run-ledger 2>/dev/null | grep -F "run-ledger" > /dev/null ) ||
    fail "timeline --tool should include matching rows"
}

test_oms_run_checkpoints_flags_piles_and_never_deletes() {
  local d="$TMP/ckpt-audit"
  local SH="$ROOT/scripts/run.sh"
  local out rc=0 n

  mkdir -p "$d/checkpoints/ok" "$d/checkpoints/pile" "$d/checkpoints/topk" "$d/outside"
  printf 'x' > "$d/checkpoints/ok/latest.pt"
  printf 'x' > "$d/checkpoints/ok/best.pt"
  printf 'x' > "$d/checkpoints/ok/notes.txt"
  for n in 001 002 003; do printf 'xxxx' > "$d/checkpoints/pile/epoch_$n.pt"; done
  printf 'x' > "$d/checkpoints/topk/best.pt"
  printf 'x' > "$d/checkpoints/topk/best.safetensors"
  printf 'x' > "$d/checkpoints/topk/latest.pt"
  # A symlinked directory and file holding checkpoints must not be followed.
  printf 'x' > "$d/outside/epoch_9.pt"
  ln -s "$d/outside" "$d/checkpoints/linked"
  ln -s "$d/outside/epoch_9.pt" "$d/checkpoints/ok/link.pt"

  out="$(cd "$d" && "$SH" checkpoints)" || fail "checkpoints should exit 0 without --strict"
  contains "$out" "ok: checkpoints/ok  2 files" || fail "conforming dir should be ok and ignore symlinks and non-checkpoints: $out"
  contains "$out" "warn: checkpoints/pile holds 3 checkpoint files (12 B)" || fail "per-epoch pile should warn: $out"
  contains "$out" "epoch_001.pt" || fail "warning should name example files: $out"
  contains "$out" "warn: checkpoints/topk holds 3 checkpoint files" || fail "3 files exceed the default max 2: $out"
  if contains "$out" "outside" || contains "$out" "epoch_9"; then
    fail "symlinks must not be followed: $out"
  fi
  contains "$out" 'has no "- Checkpoints:" value' || fail "should say PROJECT.md names no directory: $out"
  contains "$out" "nothing was deleted" || fail "summary should say nothing was deleted: $out"

  out="$(cd "$d" && "$SH" checkpoints checkpoints/topk --max 5)" || fail "--max 5 run should exit 0"
  contains "$out" "ok: checkpoints/topk  3 files" || fail "--max 5 should accept the top-k dir: $out"

  (cd "$d" && "$SH" checkpoints --strict >/dev/null) || rc=$?
  [ "$rc" = 1 ] || fail "--strict should exit 1 when a directory warns, got $rc"
  rc=0
  (cd "$d" && "$SH" checkpoints checkpoints/ok --strict >/dev/null) || rc=$?
  [ "$rc" = 0 ] || fail "--strict should exit 0 when every directory conforms, got $rc"
  rc=0
  (cd "$d" && "$SH" checkpoints --max x >/dev/null 2>&1) || rc=$?
  [ "$rc" = 2 ] || fail "bad --max should exit 2, got $rc"
  rc=0
  (cd "$d" && "$SH" checkpoints no-such-dir >/dev/null 2>&1) || rc=$?
  [ "$rc" = 2 ] || fail "a missing DIR should exit 2, got $rc"

  out="$(cd "$d" && "$SH" checkpoints --json)" || fail "--json should exit 0"
  printf '%s' "$out" | python3 -c '
import json, sys
d = json.load(sys.stdin)
assert d["schema"] == 1 and d["kind"] == "oms-run-checkpoints", d
assert d["deleted"] == 0 and d["max"] == 2, d
runs = {r["path"]: r for r in d["runs"]}
assert set(runs) == {"checkpoints/ok", "checkpoints/pile", "checkpoints/topk"}, runs
assert runs["checkpoints/ok"]["follows_default"] is True, runs
assert runs["checkpoints/pile"]["follows_default"] is False and runs["checkpoints/pile"]["bytes"] == 12, runs
assert d["totals"]["warnings"] == 2 and d["totals"]["files"] == 8, d["totals"]
' || fail "--json must emit the schema-1 oms-run-checkpoints shape"

  [ -f "$d/checkpoints/pile/epoch_003.pt" ] && [ -f "$d/outside/epoch_9.pt" ] ||
    fail "checkpoints must never be deleted"
}

# smoke-weight: 7
test_agent_plan_reclaim_requeues_stale_claim() {
  local d="$TMP/plan-reclaim"
  local SH="$ROOT/scripts/agent-plan.sh"
  local out

  mkdir -p "$d"
  "$SH" --repo "$d" init --goal "reclaim test" >/dev/null
  "$SH" --repo "$d" add --id t1 --title "stale claim" >/dev/null
  "$SH" --repo "$d" add --id t2 --title "fresh claim" >/dev/null
  "$SH" --repo "$d" add --id t3 --title "stale running" >/dev/null
  "$SH" --repo "$d" add --id t4 --title "in review" >/dev/null
  "$SH" --repo "$d" claim --id t1 --provider codex --ttl 0 >/dev/null
  "$SH" --repo "$d" claim --id t2 --provider codex --ttl 9999 >/dev/null
  "$SH" --repo "$d" claim --id t3 --provider codex --ttl 0 >/dev/null
  "$SH" --repo "$d" start --id t3 >/dev/null
  "$SH" --repo "$d" claim --id t4 --provider codex --ttl 0 >/dev/null
  "$SH" --repo "$d" review --id t4 >/dev/null

  out="$("$SH" --repo "$d" reclaim)"
  contains "$out" "reclaimed t1" || fail "expired claimed task should be reclaimed"
  contains "$out" "reclaimed 1 task(s)" || fail "only the expired claimed task should be reclaimed by default"
  "$SH" --repo "$d" show --id t1 | grep -F '"state": "ready"' > /dev/null || fail "t1 should be requeued to ready"
  "$SH" --repo "$d" show --id t2 | grep -F '"state": "claimed"' > /dev/null || fail "a fresh claim must stay claimed"
  "$SH" --repo "$d" show --id t3 | grep -F '"state": "running"' > /dev/null || fail "running must require --include-running"
  "$SH" --repo "$d" show --id t4 | grep -F '"state": "review"' > /dev/null || fail "review must never be reclaimed"

  out="$("$SH" --repo "$d" reclaim --include-running)"
  contains "$out" "reclaimed t3" || fail "--include-running should reclaim the stale running task"

  if "$SH" --repo "$d" reclaim --ttl abc >/dev/null 2>"$d/err"; then
    fail "non-numeric reclaim --ttl must be rejected"
  fi
  assert_file_contains "$d/err" "must be an integer"
  local bad_ttl="$d-bad-ttl"
  mkdir -p "$bad_ttl"
  "$SH" --repo "$bad_ttl" init --goal "ttl test" >/dev/null
  "$SH" --repo "$bad_ttl" add --id t2 --title "bad ttl" >/dev/null
  if "$SH" --repo "$bad_ttl" claim --id t2 --provider codex --ttl 30m >/dev/null 2>"$d/err"; then
    fail "non-numeric claim --ttl must be rejected"
  fi
  assert_file_contains "$d/err" "must be an integer"
  "$SH" --repo "$bad_ttl" show --id t2 | grep -F '"state": "ready"' > /dev/null || fail "a rejected --ttl must leave the task ready"

  python3 - "$SH" "$d" <<'PY' || fail "worker evidence must fence TTL reuse consistently"
import json
import os
from pathlib import Path
import subprocess
import sys

cli, directory = sys.argv[1:]
plan = Path(directory) / ".oms/plan/tasks.json"
markers = Path(directory) / ".oms/delegations"
markers.mkdir()
def invoke(*options, expected=0):
    result = subprocess.run(["bash", cli, "--repo", directory, *options], text=True, capture_output=True)
    assert result.returncode == expected, (options, result.returncode, result.stderr)
    return result.stdout

def lease(task):
    return json.loads(plan.read_text())["tasks"][task]["lease_id"]

def write_marker(name, task, token, pid):
    row = dict(schema=3, id=name, task_id=task, lease_id=token, pid=pid)
    if os.name == "nt" and type(pid) is int:
        row.update(native_pid=pid, native_pid_source="msys-proc-v1")
    (markers / (name + ".json")).write_text(json.dumps(row))

for task in ("t1", "t3"):
    invoke("claim", "--id", task, "--provider", "codex", "--ttl", "0")
    write_marker(task, task, lease(task), os.getpid())
invoke("start", "--id", "t3", "--lease-id", lease("t3"))
for task in ("unknown", "unknown-running"):
    invoke("add", "--id", task, "--title", task)
    invoke("claim", "--id", task, "--provider", "codex", "--ttl", "0")
    write_marker(task, task, lease(task), None)
invoke("start", "--id", "unknown-running", "--lease-id", lease("unknown-running"))
dead_process = subprocess.Popen([sys.executable, "-c", "pass"])
dead_process.wait()
write_marker("old-retry", "t1", lease("t1"), dead_process.pid)
snapshot = plan.read_bytes()
for task in ("t1", "t3", "unknown", "unknown-running"):
    assert not json.loads(invoke("show", "--id", task))["claim_expired"], task
    assert "EXPIRED" not in invoke("brief", "--id", task)
assert not any(t["claim_expired"] for t in json.loads(invoke("list", "--json"))["tasks"])
assert "EXPIRED" not in invoke("list") and "ready now: (none)" in invoke("status")
status = json.loads(invoke("status", "--json"))
assert status["stale"] == status["actionable"] == [], status
assert not invoke("ready").strip()
invoke("next", expected=3)
invoke("next", "--claim", "--provider", "claude", expected=3)
assert "reclaimed 0 task(s)" in invoke("reclaim", "--include-running")
assert plan.read_bytes() == snapshot, "protected claims were renewed or requeued"

tokens = {}
for task in ("dead", "dead-running", "wrong-lease", "wrong-task", "markerless"):
    invoke("add", "--id", task, "--title", task)
    invoke("claim", "--id", task, "--provider", "codex", "--ttl", "0")
    tokens[task] = lease(task)
invoke("start", "--id", "dead-running", "--lease-id", tokens["dead-running"])
for task in ("dead", "dead-running"):
    write_marker(task, task, tokens[task], dead_process.pid)
write_marker("wrong-lease", "wrong-lease", "lease_previous", os.getpid())
write_marker("wrong-task", "different-task", tokens["wrong-task"], os.getpid())
recoverable = {"dead", "wrong-lease", "wrong-task", "markerless"}
assert set(invoke("ready").split()) == recoverable
assert set(json.loads(invoke("status", "--json"))["actionable"]) == recoverable
chosen = json.loads(invoke("next", "--claim", "--provider", "claude", "--ttl", "9999", "--json"))
assert chosen["id"] == "dead" and chosen["lease_id"] != tokens["dead"], chosen
for action in ("touch", "start"):
    invoke(action, "--id", "dead", "--lease-id", tokens["dead"], expected=2)
invoke("touch", "--id", "dead", "--lease-id", chosen["lease_id"])
assert "reclaimed 4 task(s)" in invoke("reclaim", "--include-running")
for task in ("dead-running", "wrong-lease", "wrong-task", "markerless"):
    assert json.loads(invoke("show", "--id", task))["state"] == "ready", task

# Unrelated undecodable records still pass through the canonical strict reader.
(markers / "unrelated.json").write_text('{"task_id":"unrelated","pid":NaN}')
snapshot = plan.read_bytes()
invoke("show", "--id", "dead")  # fresh TTL needs no marker scan
for options in (("show", "--id", "t1"), ("ready",), ("reclaim", "--include-running"),
                ("next", "--claim", "--provider", "claude")):
    invoke(*options, expected=2)
assert snapshot == plan.read_bytes()
PY
}

# smoke-weight: 6
test_delegate_plan_task_lifecycle() {
  local project="$TMP/delegate-plan-task"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local PLAN="$ROOT/scripts/agent-plan.sh"
  local rc=0

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
printf 'done\n' > delegated.txt
echo "worker done"
EOF
  chmod +x "$bin_dir/codex"

  "$PLAN" --repo "$project" init --goal "plan-task coupling" >/dev/null
  "$PLAN" --repo "$project" add --id ok.task --title "succeeds" >/dev/null
  "$PLAN" --repo "$project" add --id bad.task --title "fails verify" >/dev/null
  "$PLAN" --repo "$project" claim --id ok.task --provider codex >/dev/null
  "$PLAN" --repo "$project" claim --id bad.task --provider codex >/dev/null

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" \
    --artifact-dir "$project/artifacts" \
    --plan-task ok.task \
    --prompt "Create delegated file" >/dev/null 2>&1
  "$PLAN" --repo "$project" show --id ok.task > "$project/ok.json"
  grep -Fq '"state": "review"' "$project/ok.json" || fail "successful delegation should move the plan task to review"
  grep -Fq 'artifacts' "$project/ok.json" || fail "review transition should record the artifact path"

  rc=0
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" \
    --artifact-dir "$project/artifacts" \
    --plan-task bad.task \
    --verify "false" \
    --prompt "Create delegated file badly" >/dev/null 2>&1 || rc=$?
  [ "$rc" = "1" ] || fail "failing verify should exit 1, got $rc"
  "$PLAN" --repo "$project" show --id bad.task > "$project/bad.json"
  grep -Fq '"state": "ready"' "$project/bad.json" || fail "failed delegation should release the plan claim"

  grep -Fq '"task_id": "ok.task"' "$project/.oms/artifacts/index.jsonl" ||
    fail "--plan-task should stamp task_id lineage on artifact-index rows"
}

# smoke-weight: 7
test_peer_review_gate_verify_backstop() {
  local project="$TMP/review-gate-verify"
  local artifact_dir="$project/artifacts"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local rc=0

  make_committed_repo "$project"
  mkdir -p "$home_dir" "$project/scripts"
  write_fake_review_gate_provider "$bin_dir" claude pass
  write_fake_review_gate_provider "$bin_dir" antigravity pass
  cat > "$project/scripts/check.sh" <<'EOF'
#!/usr/bin/env bash
echo "contract broken"
exit 1
EOF
  chmod +x "$project/scripts/check.sh"

  # No bounded default: stop before providers and ask the caller for a check.
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --gate --export-only --prompt "Select a bounded check" \
    > "$project/no-default" 2>&1 || rc=$?
  [ "$rc" != 0 ] || fail "review silently selected the full release suite"
  assert_file_contains "$project/no-default" 'select affected checks explicitly with --verify CMD'

  # All reviewers self-report pass, but the project's own check fails: the
  # mechanical backstop must force the gate to fail.
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" \
    --artifact-dir "$artifact_dir" \
    --providers claude,antigravity \
    --no-diff \
    --gate --verify "bash scripts/check.sh" \
    --prompt "Gate verify backstop" >"$project/out" 2>&1 || rc=$?
  [ "$rc" = "1" ] || fail "failing mechanical verify must force gate fail, got $rc"
  # An explicit verifier stays authoritative even without a fast mode.
  assert_file_contains "$project/out" "gate verify: fail (exit 1, "
  assert_file_contains "$project/out" "claude: pass"
  assert_one_artifact_contains "$artifact_dir" '_verify-gate-verify-backstop-*.md' 'contract broken'

  # Passing contract + passing reviewers -> gate passes. Provider routing is
  # private to the review calls and must not contaminate the project verifier.
  # Review artifacts/indexes also must not exist until after verification: a
  # repository purity check should judge the submitted tree, not this gate's
  # own `.oms` bookkeeping.
  rm -rf "$project/.oms"
  cat > "$project/scripts/check.sh" <<'EOF'
#!/usr/bin/env bash
[ ! -e .oms ]
[ -z "${OMS_MODEL_OPERATION:-}" ]
[ -z "${OMS_MODEL_CLASS_REQUEST:-}" ]
[ -z "${OMS_REASONING_EFFORT_REQUEST:-}" ]
EOF
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" \
    --artifact-dir "$project/artifacts-pass" \
    --providers claude,antigravity \
    --no-diff \
    --gate --verify "bash scripts/check.sh" \
    --prompt "Gate verify backstop" >"$project/out-pass" 2>&1 || rc=$?
  [ "$rc" = "0" ] || fail "verify pass + reviewer pass should exit 0, got $rc"
  assert_file_contains "$project/out-pass" "gate verify: pass ("

  # --no-verify keeps the old self-report-only behavior.
  printf '#!/usr/bin/env bash\nexit 1\n' > "$project/scripts/check.sh"
  rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" "$ROOT/scripts/peer-review.sh" \
    --repo "$project" \
    --artifact-dir "$project/artifacts-noverify" \
    --providers claude,antigravity \
    --no-diff \
    --gate \
    --no-verify \
    --prompt "Gate verify backstop" >"$project/out-noverify" 2>&1 || rc=$?
  [ "$rc" = "0" ] || fail "--no-verify should skip the backstop, got $rc"
  if grep -Fq "gate verify:" "$project/out-noverify"; then
    fail "--no-verify must not run the gate verify backstop"
  fi
}

# smoke-weight: 58
test_delegate_repair_retries_failed_verify() {
  local project="$TMP/delegate-repair"
  local kept
  local artifact_dir="$project/artifacts"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local rc=0
  local verify_script="$TMP/delegate-repair-no-change-verify.sh"
  local plan_worktree_root="$project/plan-no-change-worktrees"
  local signal_worktree_root="$project/signal-worktrees"
  local filter_marker="$project/signal-filter-ran"
  local signal_pid signal_kept

  python3 - "$ROOT/scripts/lib" <<'PY' || fail "repair replay policy contract failed"
import copy, sys
sys.path.insert(0, sys.argv[1])
from repair_replay import digest, replay, select, valid_trace
key = digest(b"context")
bad = dict(candidate=digest(b"patch"), failure=digest(b"error"), worker=0, verify=1)
good = dict(candidate=digest(b"fixed"), failure=digest(b"ok"), worker=0, verify=0)
def row(i, steps):
    return dict(kind="delegate", exit=int(steps[-1]["verify"] != 0), verify_exit=steps[-1]["verify"], prompt_hash=digest(str(i).encode()),
                repair_replay=dict(schema=1, cohort=key, budget=2, policy="budget", samples=0, steps=steps))
rows = [row(i, [bad, bad, bad]) for i in range(12)]
assert valid_trace(rows[0]["repair_replay"])
assert select(rows[:11], key, 2) == ("budget", 11)
assert select(rows, key, 2) == ("stop-repeat", 12)
assert select(rows, digest(b"different checkout"), 2) == ("budget", 0)
assert select(rows, key, 3) == ("budget", 0)
assert select([rows[0]] * 12, key, 2) == ("budget", 1)
# A later recovery on a repeated prompt must not be hidden by deduplication;
# neither may a newer failure erase an already observed recovery.
recovery = row(0, [bad, bad, good])
assert select(rows + [recovery], key, 2) == ("budget", 12)
assert select([recovery] + rows, key, 2) == ("budget", 12)
# Periodically retain the original budget to observe censored continuations.
stopped = copy.deepcopy(rows[0])
stopped["repair_replay"].update(policy="stop-repeat", steps=[bad, bad])
