  (cd "$d" && "$SH" show "$id" 2>/dev/null | grep -F "agent=codex" > /dev/null ) ||
    fail "spine rows should record the calling agent from OMS_AGENT"

  # The generic fallback is not an identity and must not be stamped.
  id="$(cd "$d" && env -u OMS_AGENT -u CLAUDECODE -u CLAUDE_CODE_ENTRYPOINT -u CODEX_SANDBOX "$SH" new 2>/dev/null)"
  if (cd "$d" && "$SH" show "$id" 2>/dev/null | grep -F "agent=" > /dev/null ); then
    fail "spine rows should omit the agent field when no identity is known"
  fi
}

test_agent_plan_normalizes_provider() {
  local project="$TMP/plan-provider"

  make_committed_repo "$project"
  (cd "$project" && "$ROOT/scripts/agent-plan.sh" add --id t1 --title "one" >/dev/null)
  (cd "$project" && "$ROOT/scripts/agent-plan.sh" claim --id t1 --provider agy >/dev/null)
  python3 -c '
import json, sys
d = json.load(open(sys.argv[1]))
sys.exit(0 if d["tasks"]["t1"]["provider"] == "antigravity" else 1)
' "$project/.oms/plan/tasks.json" || fail "claim should canonicalize agy to antigravity"

  (cd "$project" && "$ROOT/scripts/agent-plan.sh" add --id t2 --title "two" >/dev/null)
  if (cd "$project" && "$ROOT/scripts/agent-plan.sh" claim --id t2 --provider gpt5 >/dev/null 2>&1); then
    fail "claim must reject an unknown provider name"
  fi

  # A panel main's claim names its room participant; a second main is refused and a release forgets the claimant.
  (cd "$project" && "$ROOT/scripts/agent-plan.sh" add --id t3 --title "three" >/dev/null)
  (cd "$project" && OMS_PANEL_MAIN_ATTEMPT=a1 OMS_ROOM_PARTICIPANT=main-one "$ROOT/scripts/agent-plan.sh" claim --id t3 --provider claude >/dev/null)
  if (cd "$project" && OMS_PANEL_MAIN_ATTEMPT=a2 OMS_ROOM_PARTICIPANT=main-two "$ROOT/scripts/agent-plan.sh" claim --id t3 --provider claude >/dev/null 2>&1); then
    fail "a second main must not claim a task another main holds"
  fi
  python3 -c '
import json, sys
t = json.load(open(sys.argv[1]))["tasks"]
sys.exit(0 if t["t3"].get("claimed_by_participant") == "main-one" and "claimed_by_participant" not in t["t1"] else 1)
' "$project/.oms/plan/tasks.json" || fail "claim should record the panel main participant only for a panel main"
  (cd "$project" && "$ROOT/scripts/agent-plan.sh" release --id t3 >/dev/null)
  python3 -c '
import json, sys
sys.exit(1 if "claimed_by_participant" in json.load(open(sys.argv[1]))["tasks"]["t3"] else 0)
' "$project/.oms/plan/tasks.json" || fail "release should clear the claimant"
}

test_oms_run_current_pointer_joins_and_expires() {
  local d="$TMP/oms-run-current"
  local SH="$ROOT/scripts/run.sh"
  local id
  local cur

  mkdir -p "$d"
  id="$(cd "$d" && env -u OMS_RUN_ID "$SH" new 2>/dev/null)"
  find "$d/.oms/runs" -maxdepth 1 -name 'CURRENT.*' | grep . > /dev/null &&
    fail "atomic pointer write left temp residue"
  cur="$(cd "$d" && env -u OMS_RUN_ID "$SH" current 2>/dev/null)" ||
    fail "current should resolve the freshly minted run"
  [ "$cur" = "$id" ] || fail "current should print the freshly minted run id"

  # A second process with no OMS_RUN_ID in its env joins via CURRENT.
  (cd "$d" && env -u OMS_RUN_ID "$SH" link --tool probe --event join >/dev/null 2>&1) ||
    fail "link should fall back to the fresh CURRENT pointer"
  (cd "$d" && "$SH" show "$id" 2>/dev/null | grep -F "join" > /dev/null ) ||
    fail "the fallback link should join the minted run"

  # A stale pointer must not misjoin later work.
  awk '{print $1, $2 - 999999}' "$d/.oms/runs/CURRENT" > "$d/.oms/runs/CURRENT.tmp"
  mv "$d/.oms/runs/CURRENT.tmp" "$d/.oms/runs/CURRENT"
  if (cd "$d" && env -u OMS_RUN_ID "$SH" current >/dev/null 2>&1); then
    fail "a stale CURRENT pointer must expire"
  fi
  if (cd "$d" && env -u OMS_RUN_ID "$SH" link --tool probe --event late >/dev/null 2>&1); then
    fail "link must not join through a stale CURRENT pointer"
  fi
}

test_oms_dispatcher_lists_and_dispatches() {
  local bin="$TMP/oms-dispatch-bin"
  local d="$TMP/oms-dispatch-repo"
  local out frontdoors help_text review_help primary duplicate description rc

  mkdir -p "$bin" "$d"
  ln -sfn "$ROOT/scripts/oms" "$bin/oms"

  # Capture first: grep -q on a live pipe SIGPIPEs the dispatcher under
  # pipefail as soon as the match is found.
  out="$("$bin/oms" list)" || fail "oms list should succeed"
  frontdoors="$out"
  [ "$out" = "$("$bin/oms" list)" ] || fail "default catalog must be compact"
  printf '%s' "$out" | grep >/dev/null -E '^inbox ' || fail "compact catalog needs inbox"
  if printf '%s' "$out" | grep >/dev/null -E '^agent-run |^herdr-adapter '; then
    fail "default catalog leaked primitive, optional or retired tools"
  fi
  out="$("$bin/oms" list --all)" || fail "expanded catalog should succeed"
  printf '%s' "$out" | grep >/dev/null -E '^run-ledger ' || fail "oms list should include run-ledger"
  for public in agent-events agent-supervisor approval-inbox autopilot draft-pr \
    runtime report sync-shared; do
    printf '%s\n' "$out" | grep >/dev/null -E "^${public} " ||
      fail "oms list should include new public tool: $public"
    "$bin/oms" "$public" --help >/dev/null 2>&1 ||
      fail "oms should dispatch new public tool: $public"
  done
  for retired in herdr-adapter a2a-bridge agent-card ops-cockpit agent-run research-runner; do
    if printf '%s\n' "$out" | grep >/dev/null -E "^${retired} "; then
      fail "retired adapter leaked into core catalog: $retired"
    fi
    if "$bin/oms" "$retired" --help >/dev/null 2>&1; then
      fail "retired adapter still dispatched: $retired"
    fi
  done
  for hidden in skill-router turn-guard install-tools multi-agent-ask multi-agent-review multi-agent-delegate \
    generate-slurm-reference generate-slurm-skill github-source import-agent-result install-autoupdate run-capsule tool-lock uninstall-autoupdate write-machine-snapshot; do
    if printf '%s' "$out" | grep >/dev/null -E "^${hidden} "; then
      fail "oms list should hide internal/deprecated tool: $hidden"
    fi
  done
  printf '%s' "$out" | grep >/dev/null -E '^snapshot ' || fail "oms list should include snapshot"
  "$bin/oms" run-ledger --help >/dev/null 2>&1 || fail "oms should dispatch run-ledger via its symlink"
  (cd "$d" && "$bin/oms" run ls >/dev/null 2>&1) || fail "oms run door broke"
  # One spelling per verb: the dispatcher used to accept both a short alias
  # and a long name for five tools, which is the same shim this project
  # refuses everywhere else. The long spellings are gone, not redirected.
  for retired in oms-run oms-init repo-state agent-thread runtime-core; do
    if "$bin/oms" "$retired" --help >/dev/null 2>&1; then
      fail "the retired second spelling must not dispatch: $retired"
    fi
  done
  # One entrance per capability: the consolidated front doors work, and the
  # retired direct names are refused outright — no compat dispatch.
  "$bin/oms" run capsule --help >/dev/null 2>&1 || fail "oms run capsule door broke"
  "$bin/oms" artifact-index import --help >/dev/null 2>&1 || fail "artifact-index import door broke"
  "$bin/oms" snapshot --help >/dev/null 2>&1 || fail "snapshot front door broke"
  if "$bin/oms" no-such-tool >/dev/null 2>&1; then
    fail "oms must reject an unknown tool"
  fi
  if "$bin/oms" ../oms >/dev/null 2>&1; then
    fail "oms must reject path-like tool names"
  fi
  if "$bin/oms" lib/tool-lock >/dev/null 2>&1; then
    fail "oms must reject the internal lib/tool-lock implementation"
  fi
  for hidden in skill-router turn-guard install-tools \
    run-capsule generate-slurm-skill generate-slurm-reference github-source \
    import-agent-result install-autoupdate uninstall-autoupdate \
    write-machine-snapshot; do
    rc=0
    "$bin/oms" "$hidden" --help >/dev/null 2>&1 || rc=$?
    [ "$rc" = 2 ] || fail "oms should reject hidden tool $hidden with exit 2, got $rc"
  done

  help_text="$("$bin/oms" --help)" || fail "oms --help should succeed"
  review_help="$("$bin/oms" peer-review --help)" || fail "peer-review --help should succeed"
  printf '%s\n' "$help_text" | grep >/dev/null -F 'reveals core primitives' ||
    fail "oms help should distinguish the full public catalog from subsystem front doors"
  printf '%s\n' "$review_help" | grep >/dev/null -F 'Plain review persists seat answers as artifacts.' ||
    fail "peer-review help should not promise a typed gate outcome in plain mode"
  printf '%s\n' "$review_help" | grep >/dev/null -F 'With --gate, enforce and record the typed gate outcome.' ||
    fail "peer-review help should scope its typed outcome to gate mode"

  for primary in init agent-plan install-profile status uninstall autopilot consult dashboard doctor inbox journal land panel patch-admit patch-land \
    peer-delegate peer-review room runtime tick update; do
    printf '%s\n' "$frontdoors" | grep >/dev/null -E "^${primary} " ||
      fail "frontdoor catalog should route the canonical workflow: $primary"
  done

  if printf '%s\n' "$frontdoors" | grep >/dev/null -E '^agent-call '; then
    fail "read primitive should stay behind list --all: agent-call"
  fi
  printf '%s\n' "$out" | grep >/dev/null -E '^agent-call ' ||
    fail "list --all should retain the read primitive: agent-call"

  printf '%s\n' "$frontdoors" | awk '
    /^Setup and capabilities:/ { group="setup"; next }
    /^Goals and daily work:/ { group="work"; next }
    /^Maintenance and removal:/ { group="maintenance"; next }
    $1 == "init" || $1 == "install-profile" { if (group != "setup") exit 1 }
    $1 == "agent-plan" || $1 == "status" { if (group != "work") exit 1 }
    $1 == "uninstall" { if (group != "maintenance") exit 1 }
  ' || fail "lifecycle commands are not grouped by intent"
  duplicate="$(printf "%s\n" "$frontdoors" | awk "/^[a-z][a-z-]* +/ { seen[\$1]++ } END { for (name in seen) if (seen[name] > 1) print name }")"
  [ -z "$duplicate" ] || fail "frontdoor catalog contains duplicate tools: $duplicate"
  printf '%s\n' "$frontdoors" | grep >/dev/null -E '^peer-review .*diff' ||
    fail "peer-review catalog description should distinguish diff review from peer-ask"

  # Header comments span lines; the catalog must show the whole first
  # sentence, not the first physical comment line.
  printf '%s\n' "$out" | grep >/dev/null -E '^advise .*agent-call\.sh\.$' ||
    fail "advise description should join its full first sentence"
  # Usage-fallback descriptions get the same sentence join + cut.
  printf '%s\n' "$out" | grep >/dev/null -E '^agent-call .*read-only independent pass\.$' ||
    fail "agent-call description should end at its first sentence"
  if printf '%s\n' "$out" | grep >/dev/null -E '^agent-call .*write tasks'; then
    fail "agent-call description should not leak the second sentence"
  fi
  sed -n '/^describe() {$/,/^}$/p' "$ROOT/scripts/oms" > "$bin/describe.sh"
  printf '#!/usr/bin/env bash\n\n# Explain e.g. choices, i.e. defaults. Another sentence.\ntrue\n' > "$bin/header"
  printf '#!/usr/bin/env bash\n\nusage() {\nUsage: fixture\n\nExplain e.g. choices, i.e. defaults. Another sentence.\n  options\nEOF\n}\n' > "$bin/usage"
  for description in header usage; do
    out="$(bash -c '. "$1"; describe "$2"' _ "$bin/describe.sh" "$bin/$description")"
    [ "$out" = 'Explain e.g. choices, i.e. defaults.' ] || fail "abbreviation cut the description: $out"
  done
  printf '#!/usr/bin/env bash\n\ntrue\n' > "$bin/empty"
  out="$(bash -c '. "$1"; describe "$2"' _ "$bin/describe.sh" "$bin/empty")"
  [ -z "$out" ] || fail "empty description gained text: $out"
}

# smoke-weight: 23
test_doctor_detects_foreign_config_link() {
