  [ "$(cd "$project" && "$ROOT/scripts/agent-memory.sh" search --text pgvector 2>/dev/null | grep -c pgvector)" -eq 2 ] ||
    fail "search should match both the shared note and the pin"
  ( cd "$project" && "$ROOT/scripts/agent-memory.sh" search --text sqlite --agent claude 2>/dev/null | grep sqlite > /dev/null ) ||
    fail "search --agent should match the author's entry"
  if ( cd "$project" && "$ROOT/scripts/agent-memory.sh" search --text sqlite --agent codex >/dev/null 2>&1 ); then
    fail "search --agent should exclude other authors"
  fi
  if ( cd "$project" && "$ROOT/scripts/agent-memory.sh" search --text nomatchxyz >/dev/null 2>&1 ); then
    fail "a search miss must exit nonzero"
  fi
}

# smoke-weight: 7
test_agent_role_and_delegate_injection() {
  local project="$TMP/role-inject"
  local empty_project="$TMP/role-empty"
  local roles

  make_committed_repo "$empty_project"
  roles="$(cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
    "$ROOT/scripts/agent-role.sh" list)"
  printf '%s\n' "$roles" | grep >/dev/null -Fx decision-advisor ||
    fail "agent-role list should include bundled decision-advisor"
  printf '%s\n' "$roles" | grep >/dev/null -Fx repo-auditor ||
    fail "agent-role list should include bundled repo-auditor"
  printf '%s' "$roles" | grep -Fx researcher > /dev/null ||
    fail "agent-role list should include bundled researcher"
  # The cheap explorer is researcher, not a 21st role: its return contract is
  # pointer lines, a bounded summary and an explicit not-checked line.
  assert_file_contains "$ROOT/roles/researcher.md" 'at most 8 findings as `path:line'
  assert_file_contains "$ROOT/roles/researcher.md" 'at most 120 words'
  assert_file_contains "$ROOT/roles/researcher.md" 'Not found / not checked:'
  assert_file_contains "$ROOT/roles/researcher.md" 'Stop once the question is answered.'
  [ "$(printf '%s\n' "$roles" | grep -c .)" -le 20 ] ||
    fail "bundled role count grew past 20; justify a new role or extend an existing one"
  [ "$(cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
    "$ROOT/scripts/agent-role.sh" --name decision-advisor resolve)" = "$ROOT/roles/decision-advisor.md" ] ||
    fail "agent-role should fall back to bundled roles"
  local role
  for role in builder refactorer reviewer architect advisor critic security-auditor \
      verifier integrator performance-engineer documenter release-engineer; do
    printf '%s\n' "$roles" | grep -Fx "$role" > /dev/null ||
      fail "agent-role list should include bundled $role"
    [ "$(cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
      "$ROOT/scripts/agent-role.sh" --name "$role" resolve)" = "$ROOT/roles/$role.md" ] ||
      fail "agent-role should resolve bundled $role"
    assert_file_contains "$ROOT/roles/$role.md" \
      'Do not delegate recursively or grant new authority.'
  done
  assert_file_contains "$ROOT/roles/reviewer.md" \
    'Use before acceptance in a separate context from the implementer.'
  assert_file_contains "$ROOT/roles/analysis-worker.md" \
    'write the failing case only in that scratch'
  assert_file_contains "$ROOT/roles/analysis-worker.md" \
    'one failure class'
  assert_file_contains "$ROOT/roles/analysis-worker.md" \
    '(environment, test, code or flaky)'
  assert_file_contains "$ROOT/roles/critic.md" \
    'judge the plan text only, ignore any author rationale supplied'
  assert_file_contains "$ROOT/roles/reviewer.md" 'Read-only.'
  assert_file_contains "$ROOT/roles/reviewer.md" 'Do not edit, apply patches or accept your own implementation.'

  [ "$(cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
    "$ROOT/scripts/agent-role.sh" --name scholar resolve)" = "$ROOT/roles/scholar.md" ] ||
    fail "agent-role should resolve scholar"

  # render: every bundled role renders deterministically for both providers;
  # access is never broader than the role (read-only unless a bundled write role).
  local provider out1 out2 writers="builder documenter implementation-worker integrator performance-engineer refactorer"
  for role in $(cd "$ROOT/roles" && ls ./*.md | sed 's|^\./||; s|\.md$||'); do
    for provider in claude codex; do
      out1="$(cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
        "$ROOT/scripts/agent-role.sh" --provider "$provider" --name "$role" render)" ||
        fail "agent-role render $provider $role failed"
      out2="$(cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
        "$ROOT/scripts/agent-role.sh" --provider "$provider" --name "$role" render)"
      [ "$out1" = "$out2" ] || fail "agent-role render $provider $role is not deterministic"
      printf '%s\n' "$out1" | grep -Fxq "$([ "$provider" = claude ] && echo "name: oms-$role" || echo "name = \"oms-$role\"")" ||
        fail "render $provider $role should carry the oms- name"
      if printf ' %s ' "$writers" | grep -Fq " $role "; then
        printf '%s\n' "$out1" | grep -Eq '^(tools: .*Edit|sandbox_mode = "workspace-write")' ||
          fail "render $provider $role should grant write access"
      else
        printf '%s\n' "$out1" | grep -Eq '^(tools: .*(Edit|Write|Bash)|sandbox_mode = "workspace-write")' &&
          fail "render $provider $role must stay read-only"
      fi
    done
    printf '%s\n' "$out1" | python3 -c 'import sys,tomllib; d=tomllib.loads(sys.stdin.read()); assert d["developer_instructions"].startswith("# Strategy"), d' ||
      fail "render codex $role should be valid TOML carrying the role text"
  done
  "$ROOT/scripts/agent-role.sh" --provider claude --name reviewer render | grep -Fxq 'model: claude-opus-5-5' ||
    fail "render should take the model from the role's panel tier"
  # A project override of a write role never gains write access.
  mkdir -p "$empty_project/.oms/roles"
  printf '# Role: builder\n\n## Mandate\n\nOverride.\n' > "$empty_project/.oms/roles/builder.md"
  ( cd "$empty_project" && "$ROOT/scripts/agent-role.sh" --provider claude --name builder render ) |
    grep -Fxq 'tools: Read, Grep, Glob' || fail "render of an override must stay read-only"
  rm -rf "$empty_project/.oms/roles"
  ( cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
    OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --to codex --role scholar --read-only --artifact-dir "$empty_project/scholar-arts" --prompt "research" >/dev/null 2>&1 ) ||
    fail "delegate should inject scholar"
  assert_one_artifact_contains "$empty_project/scholar-arts" 'codex-*.md' 'SCHOLAR-STRATEGY'

  # Dry-run checks brief selection for one reusable session; no provider runs.
  for role in builder refactorer; do
    ( cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
      OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
        --to codex --resume-session role-session-123 --role "$role" \
        --artifact-dir "$empty_project/$role-arts" --prompt "bounded $role task" \
        >/dev/null 2>&1 ) || fail "reusable session should accept the $role brief"
    assert_one_artifact_contains "$empty_project/$role-arts" 'codex-*.md' \
      "$(printf '%s' "$role" | tr '[:lower:]' '[:upper:]')-STRATEGY"
    assert_one_artifact_contains "$empty_project/$role-arts" 'codex-*.md' \
      'DRY RUN: worker command skipped.'
  done
  mkdir -p "$TMP/global-roles" "$empty_project/.oms/roles"
  printf 'GLOBAL-ADVISOR\n' > "$TMP/global-roles/decision-advisor.md"
  [ "$(cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/global-roles" \
    "$ROOT/scripts/agent-role.sh" --name decision-advisor resolve)" = "$TMP/global-roles/decision-advisor.md" ] ||
    fail "global role should override the bundled default"
  printf 'PROJECT-ADVISOR\n' > "$empty_project/.oms/roles/decision-advisor.md"
  [ "$(cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/global-roles" \
    "$ROOT/scripts/agent-role.sh" --name decision-advisor resolve)" = "$empty_project/.oms/roles/decision-advisor.md" ] ||
    fail "project role should override global and bundled defaults"
  [ ! -e "$ROOT/prompts/native-subagent-brief.md" ] ||
    fail "unused native subagent prompt template should stay removed"
  [ ! -e "$ROOT/prompts/executor-soul.md" ] || fail "retired Soul template must stay removed"

  ( cd "$empty_project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
    OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --to codex --role implementation-worker --prompt "implement x" >/dev/null 2>&1 ) ||
    fail "delegate should resolve a bundled role"
  assert_one_artifact_contains "$empty_project/.oms/artifacts/delegate" 'codex-*.md' \
    'IMPLEMENTATION-WORKER-STRATEGY'
  make_committed_repo "$project"
  # A bundled read_only role launches with read access unless the caller says otherwise.
  local access_out
  access_case() {  # EXPECTED_ACCESS ENV_ASSIGNMENT ROLE [EXTRA_ARGS...]
    local want="$1" assignment="$2" role="$3"
    shift 3
    access_out="$( cd "$project" && env "$assignment" OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
      OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" --to codex --role "$role" \
      --artifact-dir "$project/access-arts" --prompt "access $role" "$@" 2>&1 )" ||
      fail "dry-run --role $role should succeed"
    case "$access_out" in *"route: codex /"*" / $want"*) ;; *) fail "--role $role should resolve $want access: $access_out" ;; esac
  }
  access_case read X=1 reviewer
  case "$access_out" in *'role reviewer is read_only'*'OMS_DELEGATE_ROLE_WRITE=1'*) ;; *) fail "read default should name the override" ;; esac
  access_case write X=1 builder
  case "$access_out" in *'is read_only'*) fail "a writer role should not print the read default" ;; esac
  access_case read X=1 reviewer --read-only
  case "$access_out" in *'is read_only'*) fail "explicit --read-only should not print the default note" ;; esac
  access_case write OMS_DELEGATE_ROLE_WRITE=1 reviewer
  access_case write X=1 reviewer --apply
  # A project override with the bundled name keeps today's write default.
  mkdir -p "$project/.oms/roles"
  printf '# Role: reviewer\n\nPROJECT-OVERRIDE\n' > "$project/.oms/roles/reviewer.md"
  access_case write X=1 reviewer
  rm -f "$project/.oms/roles/reviewer.md"
  # An unreadable contract must not break dispatch: one warning, write default.
  local fixture_root="$TMP/role-access-fixture"
  mkdir -p "$fixture_root"
  cp -R "$ROOT/scripts" "$ROOT/roles" "$ROOT/config" "$fixture_root/"
  printf '{not json' > "$fixture_root/config/role-contracts.json"
  access_out="$( cd "$project" && OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" OH_MY_SETTING_DELEGATE_DRY_RUN=1 \
    "$fixture_root/scripts/peer-delegate.sh" --to codex --role reviewer \
    --artifact-dir "$project/access-arts" --prompt "access broken" 2>&1 )" ||
    fail "an unreadable role contract must not break dispatch: $access_out"
  case "$access_out" in *'warning: role contract unreadable'*" / write"*) ;; *) fail "unreadable contract should warn and keep write: $access_out" ;; esac
  ( cd "$project" && "$ROOT/scripts/agent-role.sh" --name reviewer init >/dev/null )
  printf '# Role: reviewer\n\nBe a STRICT-API-REVIEWER. Output GATE.\n' > "$project/.oms/roles/reviewer.md"
  (cd "$project" && "$ROOT/scripts/agent-role.sh" list) | grep -Fx reviewer > /dev/null ||
    fail "agent-role list should show the created role"
  ( cd "$project" && "$ROOT/scripts/agent-role.sh" --name reviewer resolve >/dev/null ) ||
    fail "agent-role resolve should find the role"

  # --role injects a Role section into the worker brief.
  ( cd "$project" && OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --role reviewer --prompt "review the diff" >/dev/null 2>&1 ) ||
    fail "delegate --role should succeed"
  assert_one_artifact_contains "$project/.oms/artifacts/delegate" 'codex-*.md' 'STRICT-API-REVIEWER'

  # Review gates cannot promote worker-mutable project profiles to instructions.
  printf 'GLOBAL-REVIEWER-PROFILE\n' > "$TMP/global-roles/reviewer.md"
  local review_scope review_profile review_artifacts
  for review_scope in project global bundled; do
    review_artifacts="$TMP/reviewer-$review_scope-artifacts"
    review_profile=STRICT-API-REVIEWER
    [ "$review_scope" != global ] || review_profile=GLOBAL-REVIEWER-PROFILE
    [ "$review_scope" != bundled ] || review_profile=REVIEWER-STRATEGY
    local review_options=(--providers codex)
    [ "$review_scope" = project ] || review_options+=(--gate --no-verify --no-diff --export-only)
    [ "$review_scope" != bundled ] || rm "$TMP/global-roles/reviewer.md"
    OH_MY_SETTING_ROLES_DIR="$TMP/global-roles" OH_MY_SETTING_REVIEW_DRY_RUN=1 \
      "$ROOT/scripts/peer-review.sh" --repo "$project" "${review_options[@]}" \
      --artifact-dir "$review_artifacts" --prompt "Review current diff" >/dev/null ||
      fail "$review_scope reviewer dry-run should succeed"
    assert_one_artifact_contains "$review_artifacts" 'codex-review-*.md' "$review_profile"
    if [ "$review_scope" != project ] && grep -Fq STRICT-API-REVIEWER "$review_artifacts"/codex-review-*.md; then
      fail "review gate loaded a worker-mutable project reviewer profile"
    fi
  done
  printf 'PANEL-ADVISOR-PROFILE\n' > "$project/.oms/roles/advisor.md"
  "$ROOT/scripts/advise.sh" --repo "$project" --to codex --strategy advisor \
    --artifact-dir "$project/advisor-panel-artifacts" --prompt "Choose a direction" --dry-run >/dev/null ||
    fail "panel advisor dry-run should succeed"
  assert_one_artifact_contains "$project/advisor-panel-artifacts" 'codex-*.md' 'PANEL-ADVISOR-PROFILE'
  PYTHONDONTWRITEBYTECODE=1 python3 - "$ROOT" "$project" <<'PY'
import sys
from pathlib import Path
sys.path.insert(0, str(Path(sys.argv[1]) / "scripts/lib"))
import panel_routing
route = {"role": "advisor", "provider": "codex", "model": "gpt-6-astra", "effort": "high", "access": "read"}
argv = panel_routing.command(Path(sys.argv[1]) / "oms", Path(sys.argv[2]), route, prompt="choose")
assert argv[2] == "advise" and argv[argv.index("--strategy") + 1] == "advisor", argv
PY

  # Unknown role fails fast.
  if ( cd "$project" && OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --role nope --prompt x >/dev/null 2>&1 ); then
    fail "an unknown --role must be rejected"
  fi

  # A plan task's role field is auto-injected via --plan-task (isolated dir).
  ( cd "$project" && "$ROOT/scripts/agent-plan.sh" add --id t1 --title "review it" --role reviewer >/dev/null )
  ( cd "$project" && "$ROOT/scripts/agent-plan.sh" claim --id t1 --provider codex >/dev/null )
  ( cd "$project" && OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
    --to codex --plan-task t1 --artifact-dir "$project/plan-arts" >/dev/null 2>&1 ) ||
    fail "plan-task with role should succeed"
  assert_one_artifact_contains "$project/plan-arts" 'codex-*.md' 'STRICT-API-REVIEWER'

  # The descriptive role contract covers every bundled role and agrees with panel routing.
  python3 "$ROOT/scripts/lib/role_contracts.py" >/dev/null || fail "role contracts should lint clean"
  python3 -I - "$ROOT" "$TMP/role-contract-fixture" <<'PY' || fail "role contract lint should reject drift"
import json, shutil, sys
from pathlib import Path
root, work = Path(sys.argv[1]), Path(sys.argv[2])
sys.path.insert(0, str(root / "scripts/lib"))
import role_contracts

def tree(edit):
    shutil.rmtree(work, ignore_errors=True)
    (work / "config").mkdir(parents=True)
    shutil.copytree(root / "roles", work / "roles")
    (work / "scripts/lib").mkdir(parents=True)
    shutil.copy(root / "scripts/lib/peer-common.sh", work / "scripts/lib/peer-common.sh")
    data = json.loads((root / "config/role-contracts.json").read_text())
    edit(data["roles"], work)
    (work / "config/role-contracts.json").write_text(json.dumps(data))
    return role_contracts.check(work, writers={"builder"}, kinds={})

def expect(edit, needle):
    errors = tree(edit)
    assert any(needle in e for e in errors), (needle, errors)

assert tree(lambda r, w: None) == []
expect(lambda r, w: r.pop("critic"), "without contract entry: critic")
expect(lambda r, w: r.update(ghost=dict(r["critic"])), "without role file: ghost")
expect(lambda r, w: r["critic"].update(writes="everything"), "critic: writes must be one of")
expect(lambda r, w: r["critic"].update(may_delegate=True), "may_delegate must be false")
expect(lambda r, w: r["critic"].update(writes="assigned-paths"), "contradicts")
expect(lambda r, w: r["verifier"].update(returns=["no such line"]), "not present in the role file")
expect(lambda r, w: r["builder"].update(read_only=True, writes="none"), "listed as a writer")

def widen(w):
    path = w / "scripts/lib/peer-common.sh"
    path.write_text(path.read_text().replace('--tools "Read,Grep,Glob,Bash"', '--tools "Read,Grep,Glob,Bash,Edit"'))
expect(lambda r, w: widen(w), "read belt contains write tools: Edit")
expect(lambda r, w: (w / "scripts/lib/peer-common.sh").unlink(), "tool belts cannot be checked")
saved = role_contracts.WEB_ROLES
role_contracts.WEB_ROLES = set()
try:
    assert role_contracts.belt_for("researcher", {"read_only": True})[0] == "read"
finally:
    role_contracts.WEB_ROLES = saved
rows = {r["role"]: r for r in role_contracts.surface(json.loads((root / "config/role-contracts.json").read_text())["roles"])}
assert (rows["reviewer"]["belt"], rows["reviewer"]["tools"], rows["reviewer"]["mcp"]) == ("read", 4, False)
assert (rows["researcher"]["belt"], rows["researcher"]["tools"]) == ("read+web", 6)
assert (rows["builder"]["belt"], rows["builder"]["tools"], rows["builder"]["mcp"]) == ("default", None, True)
assert (rows["reviewer"]["delegate_default"], rows["builder"]["delegate_default"]) == ("read", "write")
assert role_contracts.role_access("reviewer") == "read" and role_contracts.role_access("builder") == "write"
assert role_contracts.role_access("no-such-role") == "write"
try:
    role_contracts.role_access("reviewer", root / "config/missing.json")
except OSError:
    pass
else:
    raise AssertionError("an unreadable contract should raise")
PY

  # Prompt-cache stability: render the same bundled-role prefix in two repos
  # under a different clock second, TZ, TMPDIR, cwd and artifact dir.
  local pfx_a pfx_b
  mkdir -p "$TMP/pfx-tmp"
  ( cd "$empty_project" && TZ=UTC OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
    OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --to codex --role builder --artifact-dir "$TMP/pfx-a" --prompt "first task" >/dev/null 2>&1 ) ||
    fail "prefix render A should succeed"
  sleep 1
  ( cd "$project" && TZ=Asia/Seoul TMPDIR="$TMP/pfx-tmp" OH_MY_SETTING_ROLES_DIR="$TMP/no-global-roles" \
    OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --to codex --role builder --artifact-dir "$TMP/pfx-b" --prompt "second task" >/dev/null 2>&1 ) ||
    fail "prefix render B should succeed"
  pfx_a="$(find "$TMP/pfx-a" -type f -name 'codex-*.md' | sed -n '1p')"
  pfx_b="$(find "$TMP/pfx-b" -type f -name 'codex-*.md' | sed -n '1p')"
  [ -n "$pfx_a" ] && [ -n "$pfx_b" ] || fail "prefix renders should leave artifacts"
  grep -Fq BUILDER-STRATEGY "$pfx_a" || fail "prefix render should carry the role"
  assert_delegate_prefix_stable "$pfx_a" "$pfx_b" "delegate brief (bundled builder role)"

  # The context-pack bundle is the other injected prefix: same files created in
  # opposite order in two repos must compile to identical bytes.
  local ctx_a="$TMP/ctx-a" ctx_b="$TMP/ctx-b" ctx_file
  make_committed_repo "$ctx_a"
  make_committed_repo "$ctx_b"
  for ctx_file in a.py b.py c.py; do printf 'content of %s\n' "$ctx_file" > "$ctx_a/$ctx_file"; done
  for ctx_file in c.py b.py a.py; do printf 'content of %s\n' "$ctx_file" > "$ctx_b/$ctx_file"; done
  TZ=UTC "$ROOT/scripts/runtime.sh" --repo "$ctx_a" context --target a.py --file b.py:x --file c.py:y \
    --bundle "$TMP/ctx-a.txt" --manifest "$TMP/ctx-a.json" >/dev/null 2>&1 || fail "context render A should succeed"
  TZ=Asia/Seoul "$ROOT/scripts/runtime.sh" --repo "$ctx_b" context --target a.py --file b.py:x --file c.py:y \
    --bundle "$TMP/ctx-b.txt" --manifest "$TMP/ctx-b.json" >/dev/null 2>&1 || fail "context render B should succeed"
  cmp -s "$TMP/ctx-a.txt" "$TMP/ctx-b.txt" ||
    fail "context bundle differs between renders: $(diff "$TMP/ctx-a.txt" "$TMP/ctx-b.txt" | sed -n '1,3p')"

  surface_out="$("$ROOT/scripts/agent-role.sh" surface)" || fail "agent-role surface should print the report"
  case "$surface_out" in *'reviewer'*'true'*'read'*'4'*'off'*) ;; *) fail "surface should list reviewer on the read belt" ;; esac
  "$ROOT/scripts/agent-role.sh" surface --json | python3 -c 'import json,sys; assert len(json.load(sys.stdin)["roles"]) == 20' ||
    fail "surface --json should list every role"
}

test_global_rules_stay_compact_and_route_workflows() {
  local global_rules="$ROOT/rules/global-AGENTS.md"
  local word_count line_count

  [ -s "$global_rules" ] || fail "dedicated global rules file should exist"
  # Budget and entrypoint checks are structural, not proof of model behavior.
  # Provider delivery is exercised by test_link_and_unlink_with_home_override;
  # authority and disclosure are covered at their actual command boundaries.
  line_count="$(wc -l < "$global_rules" | tr -d ' ')"
  [ "$line_count" -le 160 ] || fail "global rules exceed 160 lines"
  word_count="$(wc -w < "$global_rules" | tr -d ' ')"
  [ "$word_count" -le 775 ] || fail "global rules exceed 775 words"
  # Named verbs must exist as scripts, or the always-loaded rules send agents nowhere.
  assert_file_contains "$global_rules" 'oms output-digest -- CMD'
  assert_file_contains "$global_rules" 'oms journal show --grep TEXT'
  assert_file_contains "$global_rules" 'oms agent-memory recall QUERY'
  for verb in output-digest journal agent-memory; do
    [ -f "$ROOT/scripts/$verb.sh" ] || fail "global rules name oms $verb without scripts/$verb.sh"
  done
  assert_file_contains "$global_rules" 'Attribution trailers (Co-Authored-By, session link) allowed'
  if grep -q 'No attribution trailers' "$global_rules"; then
    fail "global rules must not forbid attribution trailers"
  fi
  assert_file_contains "$ROOT/AGENTS.md" 'rules/global-AGENTS.md'
  assert_file_contains "$ROOT/AGENTS.md" 'scripts/check.sh'
  assert_file_contains "$global_rules" 'oms-agent-harness'
  [ -s "$ROOT/custom-skills/oms-agent-harness/SKILL.md" ] ||
    fail "global rules route to a missing harness skill"
  if cmp -s "$ROOT/AGENTS.md" "$global_rules"; then
    fail "repo and global rules must remain separate to avoid double injection"
  fi
  # Prompt-cache stability: text every session or worker loads must not embed a
  # value that changes per render (timestamp, $(date), $RANDOM, $$, mktemp,
  # temp path, uuid, epoch). Names the first offending file:line.
  local volatile
  volatile="$(cd "$ROOT" && grep -nE '[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}|\$\(date|\$RANDOM|\$\$|mktemp|/tmp/|/var/folders/|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-|[0-9]{13}' \
    rules/global-AGENTS.md templates/project-*-AGENTS.md roles/*.md output-styles/*.md | sed -n '1p')" || true
  [ -z "$volatile" ] || fail "always-loaded text holds a per-render value (breaks the prompt-cache prefix): $volatile"
}

test_project_policy_templates_stay_compact() {
  local file words limit

  for file in project-general-AGENTS.md project-ml-AGENTS.md project-slurm-AGENTS.md; do
    case "$file" in
      project-general-AGENTS.md) limit=120 ;;
      project-ml-AGENTS.md) limit=440 ;;
      project-slurm-AGENTS.md) limit=130 ;;
    esac
    words="$(wc -w < "$ROOT/templates/$file" | tr -d ' ')"
    [ "$words" -le "$limit" ] || fail "$file exceeds $limit words (got $words)"
  done

  # The ML block is what every ML project's agent reads: it must carry the
  # training defaults, not only point at docs.
  local ml="$ROOT/templates/project-ml-AGENTS.md"
  assert_file_contains "$ml" '`latest` and `best` only'
  assert_file_contains "$ml" "validation interval"
  assert_file_contains "$ml" "at least 3 seeds"
  assert_file_contains "$ml" "test split is for final evaluation only"
  assert_file_contains "$ml" "do not default to random"
  assert_file_contains "$ml" "oms run capsule --config FILE --data NAME"
  assert_file_contains "$ml" "metric-contract.json"
  assert_file_contains "$ml" "oms run-ledger top --by-group"
  assert_file_contains "$ml" "oms data-manifest create --policy"
  assert_file_contains "$ROOT/templates/project-slurm-AGENTS.md" "--requeue"
  assert_file_contains "$ROOT/templates/project-slurm-AGENTS.md" "SIGTERM"
}

test_skill_catalog_is_one_general_purpose_set() {
  python3 - "$ROOT" <<'PY'
import json
import pathlib
import sys

root = pathlib.Path(sys.argv[1])
general = {
    "oms-agent-harness",
    "oms-ops",
    "oms-spec-interview",
    "oms-trace",
    "oms-trust-boundary",
    "oms-careful",
}
# Machine-conditional skills: linked only where every `requires` command
# exists, so unrelated sessions never carry them. A conditional skill without
# `requires` would silently join the general catalog; a general skill with
# `requires` would silently vanish from some machines.
conditional = {
    "oms-slurm",
    "oms-gpu-workstation",
}
expected = general | conditional
skills = json.loads((root / "skills.manifest.json").read_text(encoding="utf-8"))["skills"]
names = {row["name"] for row in skills}
assert names == expected, (sorted(names - expected), sorted(expected - names))
assert all(row.get("enabled") is True for row in skills)
for row in skills:
    if row["name"] in conditional:
        assert row.get("requires"), "conditional skill must declare requires: %s" % row["name"]
    else:
        assert not row.get("requires"), "general skill must not declare requires: %s" % row["name"]

on_disk = {
    path.parent.name
    for path in (root / "custom-skills").glob("*/SKILL.md")
}
assert on_disk == expected, (sorted(on_disk - expected), sorted(expected - on_disk))
slurm_skill = (root / "custom-skills" / "oms-slurm" / "SKILL.md").read_text(encoding="utf-8")
assert "sshare -U" in slurm_skill and "sprio" in slurm_skill, "oms-slurm must point at live fair-share reads"
assert "never in the reference" in slurm_skill, "fair-share must stay out of the snapshot"

owners = {}
duplicates = []
for row in skills:
    for raw in row.get("triggers", []):
        trigger = str(raw).strip().casefold()
        previous = owners.setdefault(trigger, row["name"])
        if previous != row["name"]:
            duplicates.append((trigger, previous, row["name"]))
assert not duplicates, duplicates
PY
}

test_large_skills_use_progressive_disclosure() {
  local skill
  local ref
  local routing

  skill="$ROOT/custom-skills/oms-agent-harness/SKILL.md"
  [ "$(wc -w < "$skill" | tr -d ' ')" -le 650 ] || fail "oms-agent-harness router is too large"
  for ref in command-routing state-memory plans-recovery roles model-routing cross-agent-consultation \
    delegation-artifacts review-gates session-handoff minimal-change; do
    assert_file_contains "$skill" "references/$ref.md"
    [ -f "$ROOT/custom-skills/oms-agent-harness/references/$ref.md" ] || fail "missing oms-agent-harness reference: $ref"
  done
  routing="$ROOT/custom-skills/oms-agent-harness/references/command-routing.md"
  [ "$(wc -w < "$routing" | tr -d ' ')" -le 900 ] || fail "command-routing reference is too large"

  skill="$ROOT/custom-skills/oms-spec-interview/SKILL.md"
  [ "$(wc -w < "$skill" | tr -d ' ')" -le 600 ] || fail "oms-spec-interview router is too large"
  for ref in question-ui project-bootstrap spec-templates; do
    assert_file_contains "$skill" "references/$ref.md"
  done
  # The optional design-note form hangs off the contract shapes, not the router,
  # so the always-loaded skill body does not grow for a step that is never required.
  local shapes="$ROOT/custom-skills/oms-spec-interview/references/spec-templates.md"
  local design_note="$ROOT/custom-skills/oms-spec-interview/references/design-note.md"
  assert_file_contains "$shapes" "(design-note.md)"
  assert_file_contains "$shapes" "- References:"
  for ref in Context Alternatives Decision Interface Risks Verification; do
    grep -Fxq "## $ref" "$design_note" || fail "design note form lacks its $ref section"
  done
  assert_file_contains "$design_note" "not approval or verification evidence"
  [ "$(wc -w < "$design_note" | tr -d ' ')" -le 320 ] || fail "design note reference is too large"
  ! grep -Fq "design-note" "$skill" || fail "the design note must stay out of the spec-interview router"

  # A method, not a catalogue: the whole value is the contract, the evidence
  # ranking, and the three commands it hands off to. Anything longer is prose
  # nobody reads while a run is broken.
  skill="$ROOT/custom-skills/oms-trace/SKILL.md"
  [ "$(wc -w < "$skill" | tr -d ' ')" -le 300 ] || fail "oms-trace front door is too large"

  skill="$ROOT/custom-skills/oms-trust-boundary/SKILL.md"
  [ "$(wc -w < "$skill" | tr -d ' ')" -le 400 ] || fail "oms-trust-boundary method is too large"

  skill="$ROOT/custom-skills/oms-careful/SKILL.md"
  [ "$(wc -w < "$skill" | tr -d ' ')" -le 450 ] || fail "oms-careful method is too large"
  local boundary_repo="$TMP/careful-boundary"
  mkdir -p "$boundary_repo/custom-skills/oms-careful/agents" "$boundary_repo/scripts"
  cp "$ROOT/scripts/install-skills.sh" "$boundary_repo/scripts/install-skills.sh"
  cp "$ROOT/scripts/validate-skills.py" "$boundary_repo/scripts/validate-skills.py"
  cp "$ROOT/custom-skills/oms-careful/agents/openai.yaml" "$boundary_repo/custom-skills/oms-careful/agents/openai.yaml"
  printf '{"skills":[{"name":"oms-careful","source":"custom-skills/oms-careful","enabled":true}]}\n' > "$boundary_repo/skills.manifest.json"
  python3 - "$boundary_repo/custom-skills/oms-careful/SKILL.md" 450 <<'PY'
import pathlib, sys
header = "---\nname: oms-careful\ndescription: Careful mode skill for boundary word count checks in tests.\n---\n"
words = header.split()
rest = int(sys.argv[2]) - len(words)
pathlib.Path(sys.argv[1]).write_text(header + " ".join(["word"] * rest) + "\n", encoding="utf-8")
PY
  [ "$(wc -w < "$boundary_repo/custom-skills/oms-careful/SKILL.md" | tr -d ' ')" -eq 450 ] ||
    fail "boundary fixture should be 450 words"
  "$boundary_repo/scripts/install-skills.sh" >/dev/null || fail "450-word oms-careful fixture should validate"
  printf 'extra\n' >> "$boundary_repo/custom-skills/oms-careful/SKILL.md"
  [ "$(wc -w < "$boundary_repo/custom-skills/oms-careful/SKILL.md" | tr -d ' ')" -gt 450 ] ||
    fail "over-limit fixture should exceed 450 words"
  printf '' > "$boundary_repo/custom-skills/oms-careful/SKILL.md"
  if "$boundary_repo/scripts/install-skills.sh" >/dev/null 2>&1; then
    fail "empty oms-careful SKILL.md must fail validation"
  fi
  printf 'not frontmatter\n' > "$boundary_repo/custom-skills/oms-careful/SKILL.md"
  if "$boundary_repo/scripts/install-skills.sh" >/dev/null 2>&1; then
    fail "malformed oms-careful SKILL.md must fail validation"
  fi
  for line in \
    "- Confidence (high/medium/low) and why:" \
    "- Strongest alternative explanation:" \
    "- Unverified assumptions / next checks:"; do
    assert_file_contains "$ROOT/templates/ml-docs/EXPERIMENTS.md" "$line"
  done
  # And the tools must still accept those forms. Prose that names an interface
  # it no longer has is the defect this repository keeps paying for: a guessed
  # field name left resolved failures looking open, and a hardcoded schema
  # version told every project to run a command that could not help it.
  "$ROOT/scripts/fail-ledger.sh" --help 2>&1 | grep -E 'check[[:space:]]+--cmd' > /dev/null ||
    fail "oms-trace cites fail-ledger check --cmd, which the tool no longer documents"
  "$ROOT/scripts/consult.sh" --help 2>&1 | grep -E '^[[:space:]]+--all' > /dev/null ||
    fail "oms-trace cites consult --all, which the tool no longer documents"
  "$ROOT/scripts/advise.sh" --help 2>&1 | grep -E '^[[:space:]]+--prompt TEXT' > /dev/null ||
    fail "oms-trace cites advise --prompt, which the tool no longer documents"

  # Skills must point at the newer verbs, and each pointer must name a verb the
  # tool still documents.
  local harness_refs="$ROOT/custom-skills/oms-agent-harness/references"
  assert_file_contains "$harness_refs/state-memory.md" 'journal show --grep'
  assert_file_contains "$harness_refs/efficient-waiting.md" 'oms output-digest'
  assert_file_contains "$ROOT/custom-skills/oms-trust-boundary/SKILL.md" 'OMS_WORKER_SECRET_GUARD'
  assert_file_contains "$ROOT/custom-skills/oms-ops/SKILL.md" 'ci-status triage'
  assert_file_contains "$ROOT/templates/project-skills/oms-dataset-safety/SKILL.md" 'similar compounds'
  "$ROOT/scripts/output-digest.sh" --help 2>&1 | grep -F -e '--file PATH' > /dev/null ||
    fail "skills cite output-digest, which the tool no longer documents"
  "$ROOT/scripts/ci-status.sh" --help 2>&1 | grep -F 'triage [--sha' > /dev/null ||
    fail "oms-ops cites ci-status triage, which the tool no longer documents"
  "$ROOT/scripts/data-manifest.sh" --help 2>&1 | grep -F -e '--policy' > /dev/null ||
    fail "oms-dataset-safety cites data-manifest --policy, which the tool no longer documents"
}



test_fail_ledger_names_an_advisor_after_a_repeat() {
  local project="$TMP/fail-ledger-advise"
  local gate='uv run pytest tests/broken.py'
  local out

  # Repeated failures suggest an optional advisor without granting a model call.
  make_committed_repo "$project"
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "$gate" --exit 1 --summary "assert failed" 2>&1)" ||
    fail "first record should succeed"
  if contains "$out" 'oms advise'; then
    fail "a single failure is not a pattern; no advisor yet: $out"
  fi

  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "$gate" --exit 1 --summary "assert failed" 2>&1)" ||
    fail "second record should succeed"
  contains "$out" 'has failed 2x unresolved' ||
    fail "the second unresolved failure should be named as a repeat: $out"
  contains "$out" 'oms advise' ||
    fail "the repeat should name the advisor: $out"
  contains "$out" 'if authorized' ||
    fail "the hint must not authorize another model call: $out"

  # `check` gates the retry, so it carries the same escalation and keeps exit 3.
  local rc=0
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" check --cmd "$gate" 2>&1)" || rc=$?
  [ "$rc" = 3 ] || fail "check must still exit 3 for a known failure, got $rc"
  contains "$out" 'oms advise' ||
    fail "check should name the advisor on a repeat: $out"
  contains "$out" 'if authorized' ||
    fail "check must preserve the optional advisor boundary: $out"

  # A resolve zeroes the run: the next failure is a first failure again.
  ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" resolve --cmd "$gate" ) >/dev/null 2>&1 ||
    fail "resolve should succeed"
  out="$(cd "$project" && "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "$gate" --exit 1 2>&1)" || fail "record after resolve should succeed"
  if contains "$out" 'oms advise'; then
    fail "a resolved fingerprint must start counting again: $out"
  fi

  # Threshold is configurable, and 0 turns it off for a caller that does not
  # want an advisor named at all.
  out="$(cd "$project" && OMS_ADVISE_AFTER_FAILURES=0 "$ROOT/scripts/fail-ledger.sh" record \
    --cmd "$gate" --exit 1 2>&1)" || fail "record with the hint disabled should succeed"
  if contains "$out" 'oms advise'; then
    fail "OMS_ADVISE_AFTER_FAILURES=0 must silence the hint: $out"
  fi
}

test_fail_ledger_hook_gives_failed_commands_a_memory() {
  local project="$TMP/fail-ledger-hook"
  local SH="$ROOT/scripts/fail-ledger-hook.sh"
  local payload='{"tool_name":"Bash","hook_event_name":"PostToolUseFailure","tool_input":{"command":"uv run pytest tests/broken.py"},"error":"Exit code 2\nboom"}'
  local out

  # The ledger only ever spoke when something called it, and the primary agent
  # mid-failure-loop never did. The hook is that call: silent on a first
  # failure, prior context plus the advise hint on the repeat. Speech rides
  # stderr with exit 2 — the channel Claude Code shows to the model on this
  # event without blocking; stdout would reach only the debug log.
  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  out="$(cd "$project" && printf '%s' "$payload" | bash "$SH" 2>&1)" ||
    fail "a first failure has nothing to say, so the hook must exit 0"
  [ -z "$out" ] || fail "a first failure has no context to surface: $out"
  [ "$(wc -l < "$project/.oms/failures.jsonl" | tr -d ' ')" = 1 ] ||
    fail "the hook should have recorded the failure"

  local rc=0 err="$TMP/fail-ledger-hook.err"
  out="$(cd "$project" && printf '%s' "$payload" | bash "$SH" 2>"$err")" || rc=$?
  [ "$rc" = 2 ] || fail "ledger speech must use the exit-2 feedback channel, got exit $rc"
  [ -z "$out" ] || fail "speech on stdout is invisible to the model: $out"
  grep -Fq 'already failed 1x' "$err" ||
    fail "the repeat should surface prior ledger context: $(cat "$err")"
  grep -Fq 'oms advise' "$err" ||
    fail "the repeat should name the advisor: $(cat "$err")"
  if grep -Fq 'recorded ' "$err"; then
    fail "bookkeeping receipts are not agent context: $(cat "$err")"
  fi

  # Non-Bash failures, interrupts, disabled hook, and unadopted repos are
  # exact no-ops — and the hook must never seed .oms as a side effect.
  out="$(cd "$project" && printf '%s' '{"tool_name":"Edit","tool_input":{}}' | bash "$SH")"
  [ -z "$out" ] || fail "non-Bash failures are not ledger material: $out"
  out="$(cd "$project" && printf '%s' \
    '{"tool_name":"Bash","hook_event_name":"PostToolUseFailure","tool_input":{"command":"sleep 999"},"error":"Exit code 130\n","is_interrupt":true}' |
    bash "$SH")"
  [ -z "$out" ] || fail "an interrupt is not a failure worth remembering: $out"
  [ "$(wc -l < "$project/.oms/failures.jsonl" | tr -d ' ')" = 2 ] ||
    fail "no-op paths must not append rows"
  before="$(wc -l < "$project/.oms/failures.jsonl" | tr -d ' ')"
  out="$(cd "$project" && printf '%s' "$payload" | OMS_FAIL_LEDGER_HOOK=0 bash "$SH")"
  [ -z "$out" ] || fail "the opt-out must silence the hook: $out"
  [ "$(wc -l < "$project/.oms/failures.jsonl" | tr -d ' ')" = "$before" ] ||
    fail "the opt-out must not record"
  local plain="$TMP/fail-ledger-hook-plain"
  mkdir -p "$plain"
  out="$(cd "$plain" && printf '%s' "$payload" | bash "$SH")"
  [ -z "$out" ] || fail "an unadopted repo gets no ledger speech: $out"
  [ ! -d "$plain/.oms" ] || fail "the hook must not seed .oms"

}

# The edit-time syntax guard is feedback in the same turn: a file that does not
# parse after an Edit/Write comes back as additionalContext (plain stdout on
# PostToolUse never reaches the model), a clean file stays silent, and the
# hook never blocks, never exits nonzero, and never writes anything.
test_syntax_guard_hook_reports_broken_edits() {
  local project="$TMP/syntax-guard-hook"
  local SH="$ROOT/scripts/syntax-guard-hook.sh"
  local out

  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  payload_for() {  # payload_for TOOL FILE
    printf '{"tool_name":"%s","tool_input":{"file_path":"%s"},"tool_response":{"filePath":"%s"},"hook_event_name":"PostToolUse","cwd":"%s"}' \
      "$1" "$2" "$2" "$project"
  }
  context_of() {  # context_of HOOK_OUTPUT -> additionalContext
    printf '%s' "$1" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["hookSpecificOutput"]["hookEventName"] == "PostToolUse", row
print(row["hookSpecificOutput"]["additionalContext"])
'
  }

  printf 'if true; then\n  echo unclosed\n' > "$project/broken.sh"
  out="$(cd "$project" && payload_for Write "$project/broken.sh" | bash "$SH")" ||
    fail "the hook must never exit nonzero"
  out="$(context_of "$out")" || fail "a broken shell file must come back as additionalContext: $out"
  case "$out" in
    "syntax-guard: broken.sh does not parse after this Write"*"bash -n"*) ;;
    *) fail "the finding must name the file, the tool, and the check: $out" ;;
  esac
  case "$out" in
    *"$project"*) fail "the finding shows a repo-relative path, not the machine path: $out" ;;
  esac

  printf 'echo fine\n' > "$project/fine.sh"
  out="$(cd "$project" && payload_for Edit "$project/fine.sh" | bash "$SH")"
  [ -z "$out" ] || fail "a clean file must stay silent: $out"

  # Python's executable search must not select another Bash installation.
  local shadow="$TMP/syntax-guard-shadow"
  mkdir -p "$shadow"
  printf '#!/bin/sh\nexit 1\n' > "$shadow/bash"
  chmod +x "$shadow/bash"
  # Keep python3 itself off the shadowed Bash (a managed launcher is a Bash script).
  ln -s "$(python3 -I -c 'import os, sys; print(os.path.realpath(sys.executable))')" "$shadow/python3"
  out="$(cd "$project" && payload_for Edit "$project/fine.sh" | PATH="$shadow:$PATH" "$BASH" "$SH")"
  [ -z "$out" ] || fail "the parser must reuse the hook's Bash: $out"
  out="$(cd "$project" && payload_for Write "$project/broken.sh" | PATH="$shadow:$PATH" "$BASH" "$SH")"
  out="$(context_of "$out")" || fail "pinning Bash must preserve broken-file feedback"
  case "$out" in *"broken.sh"*"unexpected"*) ;; *) fail "the parser must report an actual Bash diagnostic: $out" ;; esac

  printf 'def f(:\n    pass\n' > "$project/broken.py"
  out="$(cd "$project" && payload_for Edit "$project/broken.py" | bash "$SH")"
  out="$(context_of "$out")" || fail "a broken python file must come back as additionalContext"
  case "$out" in *"broken.py"*"python:"*) ;; *) fail "python finding is wrong: $out" ;; esac
  [ ! -d "$project/__pycache__" ] || fail "the check must not write bytecode"

  printf '{"a": 1,}\n' > "$project/broken.json"
  out="$(cd "$project" && payload_for Write "$project/broken.json" | bash "$SH")"
  out="$(context_of "$out")" || fail "a broken json file must come back as additionalContext"
  case "$out" in *"broken.json"*"json:"*) ;; *) fail "json finding is wrong: $out" ;; esac
  printf '{\n  // comments are the point of this file\n  "a": 1\n}\n' > "$project/tsconfig.json"
  out="$(cd "$project" && payload_for Write "$project/tsconfig.json" | bash "$SH")"
  [ -z "$out" ] || fail "JSON-with-comments files are not findings: $out"

  printf '#!/usr/bin/env bash\nfor x in; do\n' > "$project/tool"
  out="$(cd "$project" && payload_for Write "$project/tool" | bash "$SH")"
  out="$(context_of "$out")" || fail "a shebang script without an extension is still checked"
  case "$out" in *"tool does not parse"*"bash -n"*) ;; *) fail "shebang finding is wrong: $out" ;; esac

  # Non-edit tools, missing files, unknown kinds, the opt-out, and unadopted
  # repos are exact no-ops — and the hook never seeds .oms.
  out="$(cd "$project" && printf '%s' '{"tool_name":"Bash","tool_input":{"command":"true"}}' | bash "$SH")"
  [ -z "$out" ] || fail "a Bash call is not edit material: $out"
  out="$(cd "$project" && payload_for Write "$project/missing.sh" | bash "$SH")"
  [ -z "$out" ] || fail "a file that is gone has nothing to parse: $out"
  printf 'not code\n' > "$project/notes.md"
  out="$(cd "$project" && payload_for Write "$project/notes.md" | bash "$SH")"
  [ -z "$out" ] || fail "an unjudged file kind must stay silent: $out"
  out="$(cd "$project" && payload_for Write "$project/broken.sh" | OMS_SYNTAX_GUARD_HOOK=0 bash "$SH")"
  [ -z "$out" ] || fail "the opt-out must silence the hook: $out"
  local plain="$TMP/syntax-guard-plain"
  mkdir -p "$plain"
  printf 'if true; then\n' > "$plain/broken.sh"
  out="$(cd "$plain" && printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$plain/broken.sh" | bash "$SH")"
  [ -z "$out" ] || fail "an unadopted repo gets no guard speech: $out"
  [ ! -d "$plain/.oms" ] || fail "the hook must not seed .oms"

  # Hook cwd, not the process cwd, selects the adopted repository. This
  # catches valid payload repos when the provider launched the hook elsewhere.
  local external="$TMP/syntax-guard-external"
  mkdir -p "$external"
  printf 'if true; then\n' > "$project/from-payload.sh"
  out="$(cd "$external" && printf '{"tool_name":"Write","tool_input":{"file_path":"%s/from-payload.sh"},"cwd":"%s"}' "$project" "$project" | env -u OMS_STATE_REPO bash "$SH")"
  out="$(context_of "$out")" || fail "an adopted payload cwd must be checked outside the process repo"
  case "$out" in *"from-payload.sh"*"bash -n"*) ;; *) fail "payload cwd finding was lost: $out" ;; esac

  out="$(cd "$external" && printf '{"tool_name":"Write","tool_input":{"file_path":"from-payload.sh"},"currentWorkingDirectory":"%s"}' "$project" | env -u OMS_STATE_REPO bash "$SH")"
  out="$(context_of "$out")" || fail "cwd alias must also locate relative edited paths"
  case "$out" in *"from-payload.sh"*"bash -n"*) ;; *) fail "cwd alias lost the edited file: $out" ;; esac

  # An unadopted or invalid payload cwd must not borrow adoption from the
  # process cwd and inspect files under another project.
  local invalid="$TMP/syntax-guard-invalid-cwd"
  out="$(cd "$project" && printf '{"tool_name":"Write","tool_input":{"file_path":"%s/from-payload.sh"},"cwd":"%s"}' "$project" "$invalid" | env -u OMS_STATE_REPO bash "$SH")"
  [ -z "$out" ] || fail "an invalid explicit payload cwd must not fall back to process repo: $out"
  out="$(cd "$project" && printf '{"tool_name":"Write","tool_input":{"file_path":"%s/from-payload.sh"},"cwd":7}' "$project" | env -u OMS_STATE_REPO bash "$SH")"
  [ -z "$out" ] || fail "a non-string explicit payload cwd must not fall back to process repo: $out"
  out="$(cd "$project" && printf '{broken json' | env -u OMS_STATE_REPO bash "$SH")"
  [ -z "$out" ] || fail "malformed hook JSON must not fall back to process repo: $out"

  # Codex edits arrive as apply_patch with the patch text in tool_input.command
  # and no file_path: the files the patch names are the ones to check, each
  # finding names its file, and a patch that touches only prose stays silent.
  mkdir -p "$project/src"
  printf 'def g(:\n    pass\n' > "$project/src/bad.py"
  printf 'echo ok\n' > "$project/src/good.sh"
  patch_payload() {  # patch_payload PATCH-TEXT
    python3 -c 'import json, sys; print(json.dumps({"tool_name": "apply_patch", "tool_input": {"command": sys.argv[1]}, "hook_event_name": "PostToolUse", "cwd": sys.argv[2]}))' "$1" "$project"
  }
  out="$(cd "$project" && patch_payload $'*** Begin Patch\n*** Add File: src/bad.py\n+def g(:\n+    pass\n*** Update File: src/good.sh\n@@\n-echo\n+echo ok\n*** End Patch' | bash "$SH")"
  out="$(context_of "$out")" || fail "a codex patch that leaves a broken file must come back as additionalContext"
  case "$out" in *"src/bad.py"*"python:"*|*'src\bad.py'*"python:"*) ;; *) fail "the finding names the patched file: $out" ;; esac
  case "$out" in *"good.sh"*) fail "a clean patched file is not a finding: $out" ;; *) ;; esac
  out="$(cd "$project" && patch_payload $'*** Begin Patch\n*** Update File: notes.md\n@@\n-not code\n+still prose\n*** End Patch' | bash "$SH")"
  [ -z "$out" ] || fail "a patch touching only prose stays silent: $out"



}

test_fail_ledger_report_privacy_and_preview() {
  local project="$TMP/report-ledger" out fp value rc
  make_committed_repo "$project"
  out="$(cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" record \
    --cmd 'oms doctor --project private-project' --exit 1 \
    --summary "failure on $(hostname) in $project" --failure-code verifier_failed 2>&1)"
  fp="$(cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" list --json |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["failures"][0]["fingerprint"])')"
  contains "$out" "report: oms report bug --from-failure $fp" || fail "actionable failure needs report hint"
  out="$(cd "$project" && OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/oms" report bug \
    --from-failure "$fp" --message 'Please improve the diagnostic.' --dry-run </dev/null)"
  contains "$out" 'Verb: oms doctor' || fail "report must retain the bare OMS verb"
  contains "$out" 'Failure code: verifier_failed' || fail "report must retain failure code"
  contains "$out" 'Repeat count: 1' || fail "report must retain count"
  contains "$out" 'Please improve the diagnostic.' || fail "description missing"
  if contains "$out" private-project || contains "$out" "$project" || contains "$out" "$(hostname)"; then
    fail "report leaked free-form ledger or project data"
  fi
  for value in "/ho""me/planted/private" "$(hostname)" '192.0.2.1' '2001:db8::1' '/opt/private'; do
    rc=0
    out="$(OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" bug --dry-run --message "$value" 2>&1)" || rc=$?
    [ "$rc" -ne 0 ] || fail "sensitive description accepted"
    contains "$out" 'report:' || fail "refusal needs a reason"
    if contains "$out" 'Title:'; then fail "refused draft was displayed"; fi
  done
  value="pass""word=planted-material"
  if OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" bug --dry-run --message "$value" >/dev/null 2>&1; then
    fail "sensitive description must use outbound scanner"
  fi
  out="$(cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" record \
    --cmd 'oms doctor' --exit 1 --kind hook 2>&1)"
  if contains "$out" 'report: oms report'; then fail "retiring failure gained report hint"; fi
  out="$(cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" record \
    --cmd 'oms run' --exit 1 --failure-code provider_capacity 2>&1)"
  if contains "$out" 'report: oms report'; then fail "transient failure gained report hint"; fi
  out="$(printf 'Description from stdin' | OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" bug --dry-run)"
  contains "$out" 'Description from stdin' || fail "stdin description missing"
  for value in 'doctor.sh README.md tasks.json' 'package.module e.g. i.e.' \
    'tests/test_doctor.py::test_case at 12:34:56' '/plan' $'First line\r\nSecond line'; do
    out="$(OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" bug --message "$value" --dry-run </dev/null)" ||
      fail "ordinary diagnostic text refused: $value"
    if contains "$out" $'\r'; then fail "CRLF was not normalized"; fi
  done
  (cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" record --cmd "oms not-a-public-tool" --exit 1 >/dev/null 2>&1)
  fp="$(cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" list --json |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["failures"][-1]["fingerprint"])')"
  out="$(cd "$project" && OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" bug --from-failure "$fp" --dry-run </dev/null)"
  contains "$out" 'Verb: unavailable' || fail "unknown tool leaked into verb"
  local before
  before="$(cat "$project/.oms/failures.jsonl")"
  for value in '' ' ' $'\t\r\n'; do
    if (cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" record --cmd "$value" --exit 1 >/dev/null 2>&1); then
      fail "blank command accepted"
    fi
    [ "$before" = "$(cat "$project/.oms/failures.jsonl")" ] || fail "blank command wrote a ledger row"
  done
  printf '[]\n' > "$TMP/report-malformed.jsonl"
  (cd "$project" && OMS_FAIL_LEDGER="$TMP/report-malformed.jsonl" bash "$ROOT/scripts/fail-ledger.sh" \
    record --cmd 'oms doctor' --exit 1 >/dev/null 2>&1) || fail "hint count failure changed record success"
  OMS_STATE_REPO="$project" python3 -B - "$ROOT" <<'PY' || fail "hostname or interactive EOF regression"
import contextlib, io, os, subprocess, sys
from pathlib import Path
from unittest.mock import patch
root = Path(sys.argv[1])
code = (root / 'scripts/report.sh').read_text().split("<<'PY'\n", 1)[1].rsplit('\nPY\n', 1)[0]
real_run = subprocess.run
class Terminal(io.StringIO):
    def isatty(self):
        return True

def invoke(host, args, answers=()):
    calls = []
    def run(command, **kwargs):
        if command[0] != 'gh':
            return real_run(command, **kwargs)
        calls.append(command[:3])
        result = '[{"number":7}]' if command[1:3] == ['issue', 'list'] else ''
        return subprocess.CompletedProcess(command, 0, result, '')
    out, err = io.StringIO(), io.StringIO()
    with patch.dict(os.environ, OMS_REPORT_REPO='sample/oms'), \
         patch.object(sys, 'argv', ['report', str(root)] + args), \
         patch.object(sys, 'stdin', Terminal()), patch('socket.gethostname', return_value=host), \
         patch('builtins.input', side_effect=list(answers)), \
         patch('shutil.which', return_value='stub-gh'), patch('subprocess.run', side_effect=run), \
         contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        try:
            exec(compile(code, 'report', 'exec'), {'__name__': '__main__'})
        except SystemExit as result:
            status = result.code
        else:
            status = 0
    return status, out.getvalue(), err.getvalue(), calls
for host in ('OMS', 'linux', 'wsl', 'macos', 'bash', 'python', 'Bash', 'ab', 'abc', ''):
    status, out, err, calls = invoke(host, ['bug', '--dry-run', '--message', host + ' reports an ordinary failure'])
    assert status == 0, (host, err)
for value in ('node-fixtureish', 'node-fixture.sh', 'package.node-fixture', 'node-fixture::test'):
    assert invoke('node-fixture', ['bug', '--dry-run', '--message', value])[0] == 0, value
for value in ('on node-fixture now', 'on node-fixture: error', 'on node-fixture.'):
    assert invoke('node-fixture', ['bug', '--dry-run', '--message', value])[0] != 0, value
assert invoke('node', ['bug', '--dry-run', '--message', 'on node now'])[0] != 0
status, out, err, calls = invoke('node-fixture', ['bug'], [EOFError()])
assert status == 0 and 'Not published' in out and not calls, (status, out, err, calls)
# Exercise the second confirmation without touching the network or creating an issue.
ledger = root / 'scripts/fail-ledger.sh'
real_run(['bash', str(ledger), 'record', '--cmd', 'oms doctor', '--exit', '1'],
         check=True, capture_output=True)
import json
row = json.loads(real_run(['bash', str(ledger), 'list', '--json'],
                         check=True, capture_output=True, text=True).stdout)['failures'][-1]
status, out, err, calls = invoke('node-fixture', ['bug', '--from-failure', row['fingerprint']], ['y', EOFError()])
assert status == 0 and 'Not published' in out, (status, out, err)
assert ['gh', 'issue', 'list'] in calls and all(c[1:] not in (['issue', 'create'], ['issue', 'comment']) for c in calls)
PY
}

test_fail_ledger_report_consent_and_url() {
  local bin="$TMP/report-no-gh" out rc arg value
  mkdir -p "$bin"
  for arg in bash git dirname sed grep tr cat; do
    ln -s "$(command -v "$arg")" "$bin/$arg"
  done
  # A managed-runtime launcher on PATH finds its root from its own path; link the interpreter.
  ln -s "$(python3 -I -c 'import os, sys; print(os.path.realpath(sys.executable))')" "$bin/python3"
  rc=0
  out="$(PATH="$bin" OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" feature \
    --title 'A better diagnostic' </dev/null 2>&1)" || rc=$?
  [ "$rc" -ne 0 ] || fail "non-tty publication without --yes must refuse"
  contains "$out" 'Title: A better diagnostic' || fail "draft must always display"
  contains "$out" 'https://github.com/sample/oms/issues/new?' || fail "consent refusal needs URL"
  out="$(PATH="$bin" OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" feature \
    --title 'A better diagnostic' --yes </dev/null)"
  contains "$out" 'gh unavailable' || fail "gh absence needs explanation"
  contains "$out" 'title=A+better+diagnostic' || fail "URL must encode title"
  for value in '' '0' '../bad' 'a/b/c'; do
    if OMS_REPORT_REPO="$value" bash "$ROOT/scripts/report.sh" bug --dry-run </dev/null >/dev/null 2>&1; then
      fail "malformed destination accepted"
    fi
  done
  for value in '' '0' 'abcdefabcdefabc' 'abcdefabcdefabcde' 'gggggggggggggggg'; do
    if OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" bug --from-failure "$value" \
      --dry-run </dev/null >/dev/null 2>&1; then fail "malformed fingerprint accepted"; fi
  done
  for value in '' ' '; do
    if OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" feature --title "$value" \
      --dry-run </dev/null >/dev/null 2>&1; then fail "empty feature title accepted"; fi
  done
  # Exercise the exact URL cap and both sides without depending on encoded lengths.
  python3 - "$ROOT" "$bin" <<'PY' || fail "URL bounds failed"
import os, subprocess, sys
from urllib.parse import parse_qs, urlsplit
root, bin_dir = sys.argv[1:]
env = dict(os.environ, PATH=bin_dir, OMS_REPORT_REPO='sample/oms')
base = 'https://github.com/sample/oms/issues/new?title=OMS+bug+report&body='
metadata = subprocess.check_output(['bash', root + '/scripts/report.sh', 'bug', '--dry-run'],
                                   input='', text=True, env=env).split('\n\n', 1)[1]
from urllib.parse import quote_plus
room = 8000 - len(base) - len(quote_plus(metadata.rstrip('\n') + '\n\n\n'))
for size in (0, room - 1, room, room + 1, 16000):
    result = subprocess.run(['bash', root + '/scripts/report.sh', 'bug', '--yes', '--message', 'x' * size],
                            input='', text=True, capture_output=True, env=env)
    assert result.returncode == 0, result.stderr
    url = result.stdout.strip().splitlines()[-1]
    assert len(url) <= 8000, len(url)
    assert parse_qs(urlsplit(url).query)['title'] == ['OMS bug report']
    decoded = parse_qs(urlsplit(url).query)['body'][0]
    assert ('Draft shortened' in decoded) == (size > room)
    if size == room:
        assert len(url) == 8000, len(url)
suffix = '\n[Draft shortened for URL; use --yes with gh for the full draft.]'
fixed = len('https://github.com/sample//issues/new?') + len(quote_plus(suffix))
fixed += len('title=OMS+bug+report&body=')
for delta in (-1, 0, 1):
    env['OMS_REPORT_REPO'] = 'sample/' + 'x' * (8000 - fixed + delta)
    result = subprocess.run(['bash', root + '/scripts/report.sh', 'bug', '--yes'],
                            input='', text=True, capture_output=True, env=env)
    if delta > 0:
        assert result.returncode != 0 and 'URL capacity' in result.stderr
    else:
        assert result.returncode == 0, result.stderr
        assert len(result.stdout.strip().splitlines()[-1]) <= 8000
PY
}

test_fail_ledger_report_gh_publication() {
  local project="$TMP/report-publish" bin="$TMP/report-gh" out fp mode
  make_committed_repo "$project"
  mkdir -p "$bin"
  cat > "$bin/gh" <<'SH'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$REPORT_LOG"
case "$1 $2" in
  'auth status') [ "$REPORT_MODE" != unauthenticated ] ;;
  'issue list')
    [ "$REPORT_MODE" != search-fail ] || exit 1
    if [ "$REPORT_MODE" = duplicate ]; then echo '[{"number":7}]'; else echo '[]'; fi ;;
  'label list')
    [ "$REPORT_MODE" != label-fail ] || exit 1
    if [ "$REPORT_MODE" = label ]; then echo '[{"name":"bug"}]'; else echo '[]'; fi ;;
  'issue create'|'issue comment')
    [ "$REPORT_MODE" != post-fail ] || exit 1
    echo 'https://github.com/sample/oms/issues/7' ;;
  *) exit 99 ;;
esac
SH
  chmod +x "$bin/gh"
  (cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" record --cmd 'oms doctor' --exit 1 >/dev/null 2>&1)
  fp="$(cd "$project" && bash "$ROOT/scripts/fail-ledger.sh" list --json |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["failures"][0]["fingerprint"])')"
  for mode in create label duplicate unauthenticated search-fail label-fail post-fail; do
    : > "$TMP/report-log"
    local rc=0
    out="$(cd "$project" && PATH="$bin:$PATH" REPORT_LOG="$TMP/report-log" REPORT_MODE="$mode" \
      OMS_REPORT_REPO=sample/oms bash "$ROOT/scripts/report.sh" bug --from-failure "$fp" --yes </dev/null 2>&1)" || rc=$?
    case "$mode" in
      *-fail) [ "$rc" -ne 0 ] || fail "gh failure was ignored" ;;
      *) [ "$rc" -eq 0 ] || fail "gh stub failed: $out" ;;
    esac
    case "$mode" in
      duplicate) assert_file_contains "$TMP/report-log" 'issue comment 7' ;;
      create) assert_file_contains "$TMP/report-log" 'issue create';
        if grep -q -- '--label' "$TMP/report-log"; then fail "missing label passed to create"; fi ;;
      label) assert_file_contains "$TMP/report-log" '--label bug' ;;
      unauthenticated|search-fail|label-fail)
        if grep -Eq 'issue (create|comment)' "$TMP/report-log"; then fail "unexpected publication"; fi ;;
    esac
  done
  : > "$TMP/report-log"
  if PATH="$bin:$PATH" REPORT_LOG="$TMP/report-log" REPORT_MODE=create OMS_REPORT_REPO=sample/oms \
      bash "$ROOT/scripts/report.sh" bug </dev/null >/dev/null 2>&1; then fail "consent bypassed"; fi
  [ ! -s "$TMP/report-log" ] || fail "unapproved draft touched gh"
}

test_fail_ledger_records_checks_resolves() {
  local project="$TMP/fail-ledger"
  local SH="$ROOT/scripts/fail-ledger.sh"

  make_committed_repo "$project"
  ( cd "$project" && OMS_AGENT=codex "$SH" record --cmd "uv run pytest -k foo" --exit 1 --summary "ModuleNotFoundError" >/dev/null 2>&1 )
  ( cd "$project" && OMS_AGENT=claude "$SH" record --cmd "uv run pytest -k foo" --exit 1 >/dev/null 2>&1 )
  # A known unresolved failure makes check exit nonzero for any agent.
  if ( cd "$project" && "$SH" check --cmd "uv run pytest -k foo" >/dev/null 2>&1 ); then
    fail "check must flag a known unresolved failure"
  fi
  ( cd "$project" && "$SH" list | grep "count=2" > /dev/null ) || fail "the same command must dedupe to one fingerprint"
  local fp
  fp="$(cd "$project" && "$SH" list | awk '{print $1; exit}')"
  ( cd "$project" && "$SH" resolve --fingerprint "$fp" >/dev/null 2>&1 )
  ( cd "$project" && "$SH" check --cmd "uv run pytest -k foo" >/dev/null 2>&1 ) ||
    fail "resolve must clear the warning"
  # An unseen command passes; a sensitive command is refused. The literal is
  # split with '' so this test source stays clean of a real-looking secret
  # (the harness-source scrubber self-review scans tests/ too).
  ( cd "$project" && "$SH" check --cmd "echo never" >/dev/null 2>&1 ) || fail "unseen command must pass"
  local secret_cmd='export aws_secret_access_''key=EXAMPLEVALUE1234567'
  if ( cd "$project" && "$SH" record --cmd "$secret_cmd" --exit 1 >/dev/null 2>&1 ); then
    fail "a sensitive-looking command must be refused"
  fi
}

test_fail_ledger_records_machine_paths_normalized() {
  local project="$TMP/fail-ledger-paths"
  local SH="$ROOT/scripts/fail-ledger.sh"
  local path_cmd
  # Failed commands routinely carry absolute paths; the ledger must keep the
  # failure (normalized), not refuse it — refusal silently lost the memory.
  path_cmd="python /ho""me/researcher/proj/train.py --epochs 3"

  make_committed_repo "$project"
  ( cd "$project" && "$SH" record --cmd "$path_cmd" --exit 1 \
      --summary "OOM at /ho""me/researcher/proj/data" >/dev/null 2>&1 ) ||
    fail "a path-bearing failed command must be recordable"
  ( cd "$project" && "$SH" list --json | grep 'python ~/proj/train.py' > /dev/null ) ||
    fail "stored command must have its home prefix normalized"
  if ( cd "$project" && "$SH" list --json | grep '/ho''me/researcher' > /dev/null ); then
    fail "raw home path must not reach the ledger"
  fi
  # Lookup consistency: checking the RAW command must hit the stored row
  # because both sides normalize before fingerprinting.
  if ( cd "$project" && "$SH" check --cmd "$path_cmd" >/dev/null 2>&1 ); then
    fail "check must flag the normalized fingerprint for the raw command"
  fi
}

test_fail_ledger_kind_next_how_and_legacy_rows() {
  local project="$TMP/fail-ledger-fields"
  local SH="$ROOT/scripts/fail-ledger.sh"
  local out fp rc=0

  make_committed_repo "$project"
  out="$(cd "$project" && "$SH" --repo "$project" record --cmd "false" --exit 1 --kind invalid 2>&1)" &&
    fail "unknown fail-ledger kind must fail"
  contains "$out" 'cmd, hook, verify, plan-run, delegate, patch-land' ||
    fail "kind rejection must name the allowed set: $out"

  ( cd "$project" && "$SH" --repo "$project" record --cmd "bash broken.sh" --exit 1 \
      --kind verify --next "inspect the failing assertion" ) >/dev/null 2>&1 ||
    fail "record with --next should succeed"
  out="$(cd "$project" && "$SH" --repo "$project" check --cmd "bash broken.sh" 2>&1)" || rc=$?
  [ "$rc" = 3 ] || fail "check must still return 3 with --next, got $rc"
  contains "$out" 'next: inspect the failing assertion' ||
    fail "check must surface the recommended next action: $out"
  out="$(cd "$project" && "$SH" --repo "$project" list)" || fail "list with --next should succeed"
  contains "$out" '  next: inspect the failing assertion' ||
    fail "list must surface --next: $out"
  fp="$(printf '%s\n' "$out" | awk 'NR == 1 { print $1 }')"
  ( cd "$project" && "$SH" --repo "$project" resolve --fingerprint "$fp" --how "fixed the assertion" ) \
    >/dev/null 2>&1 || fail "resolve with --how should succeed"
  out="$(cd "$project" && "$SH" --repo "$project" list)" || fail "list after --how should succeed"
  contains "$out" '  fixed: fixed the assertion' ||
    fail "list must surface --how on resolved rows: $out"
  out="$(cd "$project" && "$SH" --repo "$project" list --json)" || fail "list --json should succeed"
  printf '%s' "$out" | python3 -c '
import json, sys
row = json.load(sys.stdin)["failures"][0]
assert row["next"] == "inspect the failing assertion", row
assert row["how"] == "fixed the assertion", row
' || fail "list --json must retain --next and --how"

  # Credential-looking notes are refused at write time, naming the flag, and
  # leave the ledger untouched; a stored one is withheld by show.
  local before after
  before="$(grep -c '' "$project/.oms/failures.jsonl")"
  rc=0
  out="$(cd "$project" && "$SH" --repo "$project" record --cmd "bash leaky.sh" --exit 1 \
    --next 'set api_k''ey = s''k-abcdefghij1234567890' 2>&1)" || rc=$?
  [ "$rc" = 3 ] || fail "a credential-looking --next must exit 3, got $rc: $out"
  contains "$out" '--next looks like a credential' || fail "refusal must name --next: $out"
  rc=0
  out="$(cd "$project" && "$SH" --repo "$project" resolve --fingerprint "$fp" \
    --how 'used api_k''ey = s''k-abcdefghij1234567890' 2>&1)" || rc=$?
  [ "$rc" = 3 ] || fail "a credential-looking --how must exit 3, got $rc: $out"
  contains "$out" '--how looks like a credential' || fail "refusal must name --how: $out"
  after="$(grep -c '' "$project/.oms/failures.jsonl")"
  [ "$before" = "$after" ] || fail "refused notes must not append rows ($before -> $after)"
  printf '%s\n' '{"schema":2,"event":"fail","ts":"2026-01-01T00:00:00Z","agent":"x","fingerprint":"storedleak0000001","kind":"cmd","cmd":"old leak","exit":1,"next":"export api_k''ey = s''k-abcdefghij1234567890"}' \
    >> "$project/.oms/failures.jsonl"
  out="$(cd "$project" && "$SH" --repo "$project" show --fingerprint storedleak0000001)" ||
    fail "show of a stored leaky row should succeed"
  contains "$out" 'next:       (withheld: looks like a credential)' || fail "show must withhold a stored credential note: $out"
  case "$out" in *abcdefghij*) fail "show leaked a stored credential note: $out" ;; esac
  out="$(cd "$project" && "$SH" --repo "$project" show --fingerprint "$fp")" || fail "show clean row"
  contains "$out" 'fixed the assertion' || fail "show must keep a clean --how: $out"

  printf '{"schema":1,"event":"fail","fingerprint":"legacy-row","kind":"cmd","cmd":"old command","exit":1}\n' \
    >> "$project/.oms/failures.jsonl"
  printf '{"event":"fail","fingerprint":"implicit-schema-row","cmd":"older command","exit":1}\n' \
    >> "$project/.oms/failures.jsonl"
  out="$(cd "$project" && "$SH" --repo "$project" list)" || fail "list should parse old rows"
  contains "$out" 'old command' ||
    fail "old rows without new fields must still list: $out"
  contains "$out" 'older command' ||
    fail "legacy rows without an explicit schema must still list: $out"
}

test_ci_status_record_and_state() {
  local project="$TMP/ci-record"
  local bin="$TMP/ci-record-bin"

  make_committed_repo "$project"
  mkdir -p "$bin"
  cat > "$bin/gh" <<'EOF'
#!/usr/bin/env bash
echo '[{"status":"completed","conclusion":"failure","workflowName":"test","headSha":"deadbeef1234","url":"https://x/1"}]'
EOF
  chmod +x "$bin/gh"
  ( cd "$project" && OMS_GH_BIN="$bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) && \
    fail "ci-status record should exit nonzero on a failing run"
  [ -f "$project/.oms/ci.jsonl" ] || fail "record should write .oms/ci.jsonl"
  grep -Fq '"conclusion": "failure"' "$project/.oms/ci.jsonl" || fail "the failure conclusion should be recorded"
  # Dedupe: same sha+conclusion is not re-appended.
  ( cd "$project" && OMS_GH_BIN="$bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) || true
  [ "$(grep -c '' "$project/.oms/ci.jsonl")" -eq 1 ] || fail "identical CI result must not be re-appended"
  ( cd "$project" && "$ROOT/scripts/state.sh" ) | grep -F "## CI" > /dev/null || fail "oms state should surface CI"

  # A red run's row names what failed, and the same commit turning green later
  # is listed by `flaky` from the ledger alone: observed, never acted on.
  local flaky="$TMP/ci-flaky" flaky_bin="$TMP/ci-flaky-bin" out="$TMP/ci-flaky.out"
  make_committed_repo "$flaky"
  mkdir -p "$flaky_bin"
  cat > "$flaky_bin/gh" <<'EOF'
#!/usr/bin/env bash
state="$(dirname "$0")/conclusion"
case "$1 $2" in
  "run list")
    printf '[{"status":"completed","conclusion":"%s","workflowName":"test","headSha":"feedc0de5678","url":"https://x/7","databaseId":7}]\n' "$(cat "$state")" ;;
  "run view")
    [ ! -f "$(dirname "$0")/no-log" ] || exit 1
    printf 'smoke (2/4)\tstep\tcheck: scripts-smoke.test_alpha FAILED (3s)\n'
    printf 'smoke (2/4)\tstep\tplain line\n'
    printf 'bad\x1bname\tstep\tnoise\n' ;;
  *) echo "no pull requests found for branch" >&2; exit 1 ;;
esac
EOF
  chmod +x "$flaky_bin/gh"
  printf 'failure' > "$flaky_bin/conclusion"
  # tick's own record has no time for the log: the row lands without names.
  ( cd "$flaky" && OMS_CI_RECORD_NAMES=0 OMS_GH_BIN="$flaky_bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) || true
  [ "$(grep -c '' "$flaky/.oms/ci.jsonl")" -eq 1 ] || fail "the red run should be recorded once"
  ! grep -Fq 'failed_jobs' "$flaky/.oms/ci.jsonl" || fail "a record without the log lookup must not name jobs"
  # An explicit record completes that row with the names, once.
  ( cd "$flaky" && OMS_GH_BIN="$flaky_bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) || true
  ( cd "$flaky" && OMS_GH_BIN="$flaky_bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) || true
  [ "$(grep -c '' "$flaky/.oms/ci.jsonl")" -eq 2 ] || fail "the named row should be appended exactly once"
  grep -Fq '"failed_jobs": ["smoke (2/4)"]' "$flaky/.oms/ci.jsonl" || fail "the red row should name its failing job: $(cat "$flaky/.oms/ci.jsonl")"
  grep -Fq '"failed_checks": ["scripts-smoke.test_alpha"]' "$flaky/.oms/ci.jsonl" || fail "the red row should name its failing check"
  ! grep -q 'plain line\|noise\|step' "$flaky/.oms/ci.jsonl" || fail "log text must not reach the ledger"
  ( cd "$flaky" && "$ROOT/scripts/ci-status.sh" flaky main ) > "$out" || fail "flaky is advisory and exits 0"
  assert_file_contains "$out" "0 commit(s) recorded red, then green"
  # The same commit goes green: now it is an observation.
  printf 'success' > "$flaky_bin/conclusion"
  ( cd "$flaky" && OMS_GH_BIN="$flaky_bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) || fail "a green run records cleanly"
  ( cd "$flaky" && PATH="/usr/bin:/bin" "$ROOT/scripts/ci-status.sh" flaky main ) > "$out" || fail "flaky reads the ledger without gh"
  assert_file_contains "$out" "1 commit(s) recorded red, then green without a new commit"
  assert_file_contains "$out" "feedc0de5678"
  assert_file_contains "$out" "smoke (2/4): 1"
  assert_file_contains "$out" "scripts-smoke.test_alpha: 1"
  assert_file_contains "$out" "nothing was skipped, quarantined or re-run"
  ( cd "$flaky" && "$ROOT/scripts/ci-status.sh" flaky other-branch ) > "$out" || fail "flaky on a branch with no rows exits 0"
  assert_file_contains "$out" "0 commit(s) recorded red"
  # A log gh cannot list leaves the row as it always was.
  : > "$flaky_bin/no-log"
  printf 'failure' > "$flaky_bin/conclusion"
  rm -f "$flaky/.oms/ci.jsonl"
  ( cd "$flaky" && OMS_GH_BIN="$flaky_bin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) || true
  grep -Fq '"conclusion": "failure"' "$flaky/.oms/ci.jsonl" || fail "an unreadable failed log must not lose the CI row"
  ! grep -Fq 'failed_jobs' "$flaky/.oms/ci.jsonl" || fail "an unreadable failed log names nothing"

  # `suggest` maps recorded facts to a suggested command and a waiting age. It
  # reads records only, and calls gh only for --refresh (the read-only triage).
  local sg="$TMP/ci-suggest" sgbin="$TMP/ci-suggest-bin" sgout="$TMP/ci-suggest.out" sgtip sgrc
  local sgnow="2026-11-10T01:00:00Z" sgrow
  make_committed_repo "$sg"
  git -C "$sg" checkout -q -b feature
  sgtip="$(git -C "$sg" rev-parse HEAD)"
  mkdir -p "$sgbin" "$sg/.oms"
  cat > "$sgbin/gh" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$(dirname "$0")/calls"
run() { printf '{"databaseId":%s,"status":"completed","conclusion":"%s","workflowName":"CI","headSha":"%s","url":"http://ci/%s"}' "$1" "$2" "$3" "$1"; }
case "$*" in
  "api --method GET repos/{owner}/{repo}") echo '{"default_branch":"trunk"}' ;;
  "run list --branch feature"*) echo "[$(run 21 failure "$(cat "$(dirname "$0")/tip")")]" ;;
  "run list --branch trunk"*) echo "[$(run 10 failure bbbb111122223333)]" ;;
  "run view 21 --json jobs") echo '{"jobs":[{"name":"lint","conclusion":"failure"}]}' ;;
  "run view 10 --json jobs") printf '{"jobs":[{"name":"lint","conclusion":"%s"}]}\n' "$(cat "$(dirname "$0")/base")" ;;
  *) exit 1 ;;
esac
EOF
  chmod +x "$sgbin/gh"
  printf '%s' "$sgtip" > "$sgbin/tip"
  suggest() {  # ARGS... -> $sgout, $sgrc
    sgrc=0
    ( cd "$sg" && OMS_CI_SUGGEST_NOW="$sgnow" OMS_GH_BIN="$sgbin/gh" "$ROOT/scripts/ci-status.sh" suggest "$@" ) > "$sgout" 2>&1 || sgrc=$?
  }
  row() {  # STATUS CONCLUSION TS [EXTRA JSON]
    printf '{"schema":1,"ts":"%s","branch":"feature","sha":"%s","status":"%s","conclusion":"%s"%s}\n' "$3" "$sgtip" "$1" "$2" "${4:-}"
  }
  : > "$sgbin/calls"
  suggest
  [ "$sgrc" -eq 1 ] || fail "nothing recorded exits 1 (rc=$sgrc): $(cat "$sgout")"
  assert_file_contains "$sgout" "nothing is recorded to go on"
  assert_file_contains "$sgout" "run: oms ci-status record feature"
  # a pending run: the same row is under, then over, the 30m line
  row in_progress "" 2026-11-10T00:45:00Z > "$sg/.oms/ci.jsonl"
  suggest
  assert_file_contains "$sgout" "waiting 15m, under the 30m line"
  row in_progress "" 2026-11-10T00:00:00Z > "$sg/.oms/ci.jsonl"
  suggest
  assert_file_contains "$sgout" "waiting 60m, over the 30m line: tell the owner"
  # red, base comparison not recorded
  row completed failure 2026-11-10T00:30:00Z ',"failed_jobs":["lint"]' > "$sg/.oms/ci.jsonl"
  suggest
  [ "$sgrc" -eq 0 ] || fail "suggestions exit 0 (rc=$sgrc)"
  assert_file_contains "$sgout" "ci-red: CI is red on the tip"
  assert_file_contains "$sgout" "failed jobs: lint"
  assert_file_contains "$sgout" "run: oms ci-status triage --sha $sgtip feature"
  assert_file_contains "$sgout" "base comparison: unknown"
  [ ! -s "$sgbin/calls" ] || fail "suggest without --refresh must not call gh: $(cat "$sgbin/calls")"
  # --refresh asks the existing read-only triage; both answers
  printf 'success' > "$sgbin/base"
  suggest --refresh
  assert_file_contains "$sgout" "ci-red-regression:"
  printf 'failure' > "$sgbin/base"
  suggest --refresh
  assert_file_contains "$sgout" "ci-red-preexisting:"
  assert_file_contains "$sgout" "do not block on them"
  grep -q . "$sgbin/calls" || fail "--refresh should have called gh"
  ! grep -Evq '^(run list|run view [0-9]+ --json jobs|run view [0-9]+ --log-failed|api --method GET repos/\{owner\}/\{repo\})' "$sgbin/calls" ||
    fail "--refresh may only issue the read-only triage requests: $(cat "$sgbin/calls")"
  # red then green on the same commit: re-check, and nothing stands in the way
  { row completed failure 2026-11-10T00:10:00Z ',"failed_jobs":["lint"]'; row completed success 2026-11-10T00:20:00Z; } > "$sg/.oms/ci.jsonl"
  suggest
  assert_file_contains "$sgout" "ci-flaky: CI went red and then green"
  assert_file_contains "$sgout" "run: oms ci-status flaky feature"
  assert_file_contains "$sgout" "ready-to-land:"
  assert_file_contains "$sgout" "run: oms land   (for the owner to run"
  assert_file_contains "$sgout" "under the 24h line"
  # a recorded PR without a comment packet leaves comments unknown: not ready
  row completed success 2026-11-10T00:20:00Z ',"pr_number":12' > "$sg/.oms/ci.jsonl"
  suggest
  assert_file_contains "$sgout" "review comments: unknown (no packet for PR #12"
  ! grep -q 'ready-to-land:' "$sgout" || fail "unknown comments must not read as ready"
  # a packet: current comments are suggested, outdated ones are not
  mkdir -p "$sg/.oms/artifacts/pr-comments"
  printf '{"schema":1,"kind":"oms-pr-review-comments","pr":12,"read_at":"2026-11-08T01:00:00Z","pr_head":"%s","comments":[{"id":1,"state":"current"},{"id":2,"state":"outdated"}]}\n' \
    "$sgtip" > "$sg/.oms/artifacts/pr-comments/pr12-aaaa.json"
  suggest
  assert_file_contains "$sgout" "review-comments-current:"
  assert_file_contains "$sgout" "1 current of 2"
  assert_file_contains "$sgout" "oms draft-pr --intent INTENT comments"
  assert_file_contains "$sgout" "waiting 48h, over the 24h line: tell the owner"
  ! grep -q 'ready-to-land:' "$sgout" || fail "a current comment stands in the way of ready"
  sed -i.bak 's/"state":"current"/"state":"outdated"/' "$sg/.oms/artifacts/pr-comments/pr12-aaaa.json"
  rm -f "$sg/.oms/artifacts/pr-comments/pr12-aaaa.json.bak"
  suggest
  ! grep -q 'review-comments-current:' "$sgout" || fail "outdated comments are not suggested"
  assert_file_contains "$sgout" "ready-to-land:"
  # an open blocking finding
  mkdir -p "$sg/.oms/artifacts/review"
  printf '{"schema":1,"kind":"review-finding","id":"f-0123456789ab","severity":"blocking","anchor":"in-diff","file":"a.sh","line":3,"summary":"unquoted variable","seat":"s1","run":"R1","ts":"2026-11-10T00:00:00Z"}\n' \
    > "$sg/.oms/artifacts/review/_findings-R1.jsonl"
  suggest
  assert_file_contains "$sgout" "blocking-findings-open:"
  assert_file_contains "$sgout" "run: oms peer-review findings list --status open"
  ! grep -q 'ready-to-land:' "$sgout" || fail "an open blocking finding stands in the way of ready"
  # a merge whose tree differs from the reviewed tree
  mkdir -p "$sg/.oms/artifacts/pr-merged"
  printf '{"schema":1,"kind":"oms-pr-merge-observation","branch":"feature","pr":12,"tree":"changed-after-review","reviewed_tree":"1111111111111111111111111111111111111111","merged_tree":"2222222222222222222222222222222222222222","observed_at":"2026-11-10T00:50:00Z"}\n' \
    > "$sg/.oms/artifacts/pr-merged/observations.jsonl"
  suggest
  assert_file_contains "$sgout" "merged-tree-changed:"
  assert_file_contains "$sgout" "run: git diff --stat 1111111111111111111111111111111111111111 2222222222222222222222222222222222222222"
  assert_file_contains "$sgout" "nothing was sent to an agent, retried, merged or recorded"
  suggest --json
  python3 -I -c 'import json,sys
d=json.load(open(sys.argv[1]))
assert d["schema"]==1 and d["kind"]=="oms-ci-suggest" and d["branch"]=="feature", d
assert {s["rule"] for s in d["suggestions"]}>={"blocking-findings-open","merged-tree-changed"}, d' "$sgout" ||
    fail "suggest --json should be schema 1 kind oms-ci-suggest: $(cat "$sgout")"
  ( cd "$sg" && "$ROOT/scripts/ci-status.sh" triage --json ) >/dev/null 2>&1 && fail "--json outside suggest must be refused"

  # Every field a rule names must exist in a record of its kind, so a renamed
  # field breaks here instead of silently silencing a rule. The ledger row is
  # a real one written by `record`; comments, merged and findings are fixtures
  # whose field names must also appear in the writing source (findings: the
  # `findings list --json` output the rule reads).
  local fld="$TMP/ci-suggest-fields" fldbin="$TMP/ci-suggest-fields-bin"
  make_committed_repo "$fld"
  mkdir -p "$fldbin"
  cp "$flaky_bin/gh" "$fldbin/gh"
  printf 'failure' > "$fldbin/conclusion"
  ( cd "$fld" && OMS_GH_BIN="$fldbin/gh" "$ROOT/scripts/ci-status.sh" record main >/dev/null 2>&1 ) || true
  sgrow="$(tail -n 1 "$fld/.oms/ci.jsonl")"
  ( cd "$sg" && OMS_GH_BIN="$sgbin/gh" "$ROOT/scripts/ci-status.sh" triage --sha "$sgtip" feature ) > "$TMP/ci-suggest.triage" 2>&1 || true
  python3 -I "$ROOT/scripts/lib/review_findings.py" list --json --repo "$sg" \
    --artifact-dir "$sg/.oms/artifacts/review" > "$TMP/ci-suggest.findings"
  python3 -I - "$ROOT" "$sgrow" "$sg/.oms/artifacts/pr-comments/pr12-aaaa.json" \
    "$sg/.oms/artifacts/pr-merged/observations.jsonl" "$TMP/ci-suggest.findings" \
    "$TMP/ci-suggest.triage" <<'PY' || fail "a rule names a field its record does not have"
import json, os, re, sys
root, ci_row, comments, merged, findings, triage = sys.argv[1:]
rules = json.load(open(os.path.join(root, "config/ci-suggestions.json")))["rules"]

def keys(value, out):
    if isinstance(value, dict):
        for k, v in value.items():
            out.add(k)
            keys(v, out)
    elif isinstance(value, list):
        for v in value:
            keys(v, out)
    return out

def jsonl(path):
    return [json.loads(line) for line in open(path) if line.strip()]

have = {"ci": keys(json.loads(ci_row), set()), "comments": keys(json.load(open(comments)), set()),
        "merged": keys(jsonl(merged), set()), "findings": keys(json.load(open(findings)), set())}
text = open(triage).read()
have["triage"] = {m for m in ("job", "base") if re.search(r"^(- )?\s*%s:" % m, text, re.M)}
writers = {"comments": "scripts/lib/draft_pr_followup.py", "merged": "scripts/lib/draft_pr_followup.py",
           "findings": "scripts/lib/review_findings.py"}
bad = []
for rule in rules:
    kind = rule["record"]
    source = open(os.path.join(root, writers[kind])).read() if kind in writers else ""
    for field in rule["fields"]:
        if field not in have[kind]:
            bad.append((rule["id"], field, "missing from the record"))
        if kind in writers and '"%s"' % field not in source:
            bad.append((rule["id"], field, "not written by " + writers[kind]))
print(bad) if bad else None
sys.exit(1 if bad else 0)
PY
}

test_delegation_liveness_in_state() {
  local project="$TMP/deleg-live"

  make_committed_repo "$project"
  mkdir -p "$project/.oms/delegations"
  printf '{"schema":1,"id":"d1","provider":"codex","role":"","pid":999999,"started_at":"2026-01-01T00:00:00Z","state":"running","worktree":"/x"}\n' \
    > "$project/.oms/delegations/d1.json"
  printf '{"schema":1,"id":"d2","provider":"claude","role":"","pid":%s,"started_at":"2026-01-02T00:00:00Z","state":"running","worktree":"/y"}\n' "$$" \
    > "$project/.oms/delegations/d2.json"
  local out
  out="$(cd "$project" && "$ROOT/scripts/state.sh")"
  printf '%s' "$out" | grep >/dev/null -E "d1.*ORPHAN" || fail "a dead-pid delegation must be flagged as ORPHAN"
  printf '%s' "$out" | grep >/dev/null -E "d2.*live" || fail "a live-pid delegation must show as live"
}

# smoke-weight: 24
test_gc_reclaims_safely() {
  local project="$TMP/gc"
  local gc_err="$project/gc.err"
  local room_kind hook_project hook_case before after rc lock_mode lock_force_mkdir lock_target holder_pid python_real

  gc_hook_digest() {
    python3 -c 'import hashlib,sys
h=hashlib.sha256()
for path in sys.argv[1:]:
    with open(path,"rb") as handle:
        h.update(handle.read())
print(h.hexdigest())' "$@"
  }
  gc_hook_seed() {
    local path="$1"
    mkdir -p "$path/.oms/hooks/sessions"
    printf '%s\n' \
      '{"schema":1,"ts":"2020-01-01T00:00:00Z","action":"old"}' \
      '{"schema":1,"ts":"2099-01-01T00:00:00Z","action":"new"}' \
      > "$path/.oms/hooks/events.jsonl"
    printf '{"session":"old"}\n' > "$path/.oms/hooks/sessions/old.json"
    python3 - "$path/.oms/hooks/sessions/old.json" <<'PY'
import os, sys
os.utime(sys.argv[1], (1, 1))
PY
  }

  make_committed_repo "$project"
  mkdir -p "$project/.oms/delegations" "$project/.oms/task/archive" "$project/.oms/runs/oldrun"
  printf '{"schema":1,"id":"d1","pid":999999,"state":"running"}\n' > "$project/.oms/delegations/d1.json"
  printf '{"schema":1,"id":"d2","pid":%s,"state":"running"}\n' "$$" > "$project/.oms/delegations/d2.json"
  kill -0 "$$" 2>/dev/null || fail "test process PID must be independently live"
  python3 - "$$" "$ROOT/scripts/lib/process_liveness.py" <<'PY' || fail "test PID must be verified live by shared process probe"
import runpy, sys
assert runpy.run_path(sys.argv[2])["pid_alive"](int(sys.argv[1]))
PY
  printf 'x\n' > "$project/.oms/task/archive/current-old.md"
  printf '{}' > "$project/.oms/runs/oldrun/capsule.json"
  printf '%s\n' \
    '{"ts":"2020-01-01T00:00:00Z","fingerprint":"old","event":"fail"}' \
    '{"ts":"2020-01-01T00:00:01Z","fingerprint":"old","event":"resolved"}' \
    > "$project/.oms/failures.jsonl"
  gc_hook_seed "$project"
  touch -t 202601010000 "$project/.oms/task/archive/current-old.md" "$project/.oms/runs/oldrun"

  # Dry-run changes nothing.
  before="$(gc_hook_digest "$project/.oms/hooks/events.jsonl" "$project/.oms/hooks/sessions/old.json")"
  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 30 ) >/dev/null 2>&1
  after="$(gc_hook_digest "$project/.oms/hooks/events.jsonl" "$project/.oms/hooks/sessions/old.json")"
  [ "$before" = "$after" ] || fail "gc dry-run must preserve hook bytes"
  [ -f "$project/.oms/delegations/d1.json" ] || fail "dry-run must not delete anything"
  # Apply reclaims the orphan/old, keeps the live delegation.
  before="$(gc_hook_digest "$project/.oms/hooks/events.jsonl" "$project/.oms/hooks/sessions/old.json")"
  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 0 --apply ) >/dev/null 2>"$gc_err"
  after="$(gc_hook_digest "$project/.oms/hooks/events.jsonl" "$project/.oms/hooks/sessions/old.json")"
  [ "$before" = "$after" ] || fail "verified live PID marker must preserve hook bytes"
  grep -Fq 'hook cleanup skipped' "$gc_err" || fail "live marker should defer hook cleanup: $(cat "$gc_err")"
  [ ! -f "$project/.oms/delegations/d1.json" ] || fail "gc --apply should remove the dead-pid delegation"
  [ -f "$project/.oms/delegations/d2.json" ] || fail "gc must keep a live delegation"
  [ ! -f "$project/.oms/task/archive/current-old.md" ] || fail "gc should remove an aged task archive"
  [ ! -d "$project/.oms/runs/oldrun" ] || fail "gc should remove an aged capsule"
  [ ! -s "$project/.oms/failures.jsonl" ] || fail "gc should compact an all-resolved old ledger to empty"

  # Dispatch retention requires stopped processes, settled attempts and plan
  # coverage, rather than treating an aged output file as proof of completion.
  local dispatch_project="$TMP/gc-dispatch"
  make_committed_repo "$dispatch_project"
  python3 - "$ROOT" "$dispatch_project" "$$" <<'PYDISPATCH'
import contextlib, io, json, os, runpy, subprocess, sys, tempfile, time
from pathlib import Path
from unittest.mock import patch
root, repo = map(Path, sys.argv[1:3])
live_pid = int(sys.argv[3])
sys.path.insert(0, str(root / 'scripts/lib'))
import terminal_panel as panel
if os.name != 'posix':
    print('dispatch retention: native supervisor fixtures require POSIX; unknown evidence stays retained')
    raise SystemExit(0)
Path(os.environ['TMPDIR']).chmod(0o700)
os.environ['XDG_STATE_HOME'] = str(Path(os.environ['TMPDIR']) / 'gc-dispatch-control')
ops = runpy.run_path(str(root / 'scripts/lib/agent-events.py'))
logs = repo / '.oms/panel-state/dispatch-logs'
logs.mkdir(parents=True, mode=0o700)
artifacts = repo / '.oms/artifacts'
events, tasks = [], {}
now = int(time.time())

def age_artifacts(member, stamp):
    for suffix in ('.json', '-pending.json', '-exit.json'):
        os.utime(artifacts / ('panel-' + member + suffix), (stamp, stamp))
    launch = panel.dispatch_store.read(repo, member + '-launch.json')
    launch['generation'] = panel.dispatch_store.generation(repo / panel._dispatch_call_path(member))
    panel.dispatch_store.write(repo, member + '-launch.json', launch)

def seed(name, state='done', task=None, age=31, finished=True, complete=True,
         room_id='gc-dispatch-room', refs_extra=None):
    member = 'call-' + name
    task = task or name
    with patch.object(sys, 'platform', 'linux'):
        call = panel._prepare_dispatch_call(repo, room_id, member, 'owner', task_id=task)
    digest = panel._dispatch_exit_record(call, 0)['launch_sha256']
    panel._record_dispatch_pending(repo, call, 0, task, {'descendants': []})
    pid = 2147483647 if finished else live_pid
    panel.dispatch_store.write(repo, member + '-process.json', {'pid': pid})
    panel.dispatch_store.write(repo, member + '-supervisor.json',
                               dict(launch_sha256=digest, pid=pid, all_reaped=finished, exit=0 if finished else None))
    panel.dispatch_store.write(repo, member + '-settled.json', dict(released=True, exit=0, launch_sha256=digest))
    panel.dispatch_store.write(repo, panel._settlement_claim_path(member),
                               dict(schema=1, member=member, exit=0, active=False, complete=complete,
                                    steps={k: complete for k in ('settlement', 'room_result', 'structured_event', 'auto_review')}))
    panel._write(repo, panel._dispatch_call_path(member, True), panel._dispatch_exit_record(call, 0))
    ident = 'att_' + name
    refs = dict(panel_room_participant=member, panel_room_id=room_id, **(refs_extra or {}))
    created = ops['new_event'](ident, 1, 'attempt.created', from_state=None, to_state='queued',
                               provider='codex', tool='gc-fixture', task_id=task, refs=refs)
    created['ts'] = '2020-01-01T00:00:00Z'
    events.append(created)
    states = ['starting', 'working', 'verifying', 'review', 'done']
    if state not in states:
        states = ['cancelled']
    else:
        states = states[:states.index(state) + 1]
    old = 'queued'
    for seq, target in enumerate(states, 2):
        events.append(ops['new_event'](ident, seq, 'attempt.state_changed', from_state=old, to_state=target))
        old = target
    tasks.setdefault(task, dict(id=task, state='done'))
    for suffix in ('.log', '.activity.json', '.stream', '.transcript'):
        path = logs / (member + suffix)
        path.write_text('output' if suffix == '.log' else '{}')
        os.utime(path, (now - age * 86400, now - age * 86400))
    age_artifacts(member, now - age * 86400)
    return member

seed('settled')
seed('fresh', age=0)
seed('live', finished=False)
live_record = seed('live-record')
panel.dispatch_store.write(repo, live_record + '-process.json', {'pid': live_pid})
panel.dispatch_store.write(repo, live_record + '-supervisor.json',
                           dict(launch_sha256=panel._dispatch_exit_record(
                               panel.dispatch_store.read(repo, live_record + '-launch.json')['call'], 0)['launch_sha256'],
                                pid=live_pid, all_reaped=True, exit=0))
seed('review', state='review')
seed('delivery', complete=False)
conflict = seed('conflict')
released = panel.dispatch_store.read(repo, conflict + '-settled.json')
panel.dispatch_store.write(repo, conflict + '-settled.json', dict(released, exit=1))
unknown = seed('unknown')
(repo / panel._dispatch_call_path(unknown, True)).write_text('{')
seed('latest', task='unfinished')
tasks['unfinished']['state'] = 'ready'
seed('older', task='unfinished')
events[-6]['ts'] = '2019-01-01T00:00:00Z'
for name, stamp in (('reviewer', '2021-01-01T00:00:00Z'), ('latest-reviewer', '2022-01-01T00:00:00Z')):
    seed(name, task='unfinished', refs_extra=dict(panel_role='reviewer', panel_access='read'))
    events[-6]['ts'] = stamp
for name, stamp in (('calendar-old', '2020-2-01T00:00:00Z'), ('calendar-new', '2020-10-01T00:00:00Z'),
                    ('equal-old', '2020-2-1T00:00:00Z'), ('equal-new', '2020-02-01T00:00:00Z')):
    task = 'calendar' if name.startswith('calendar') else 'equal'
    seed(name, task=task)
    events[-6]['ts'] = stamp
    tasks[task]['state'] = 'ready'
seed('lease', task='claimed')
tasks['claimed']['state'] = 'running'
seed('mixed-age')
os.utime(logs / 'call-mixed-age.activity.json', (now, now))
for suffix in ('.stream', '.transcript'):
    member = seed('fresh' + suffix)
    os.utime(logs / (member + suffix), (now, now))
seed('link')
(logs / 'call-link.activity.json').unlink()
(logs / 'call-link.activity.json').symlink_to(logs / 'call-settled.activity.json')
seed('missing')
(logs / 'call-missing.activity.json').unlink()
artifact_only = seed('artifact-only')
for path in logs.glob(artifact_only + '.*'):
    path.unlink()
for suffix in ('-launch.json', '-settled.json', '-process.json', '-claim.json', '-brief.md'):
    path = artifacts / ('panel-' + artifact_only + suffix)
    path.write_text('{}')
    os.utime(path, (1, 1))
seed('settled-extra', age=0)
for suffix in ('-brief.md', '-claim.json'):
    member = seed('fresh' + suffix)
    path = artifacts / ('panel-' + member + suffix)
    path.write_text('{}')
open_member = seed('open-room', room_id='gc-open-dispatch')
panel.room.create(repo, 'gc-open-dispatch', creator='owner')
panel.room.join(repo, 'gc-open-dispatch', 'owner', 'codex')
panel.room.join(repo, 'gc-open-dispatch', open_member, 'codex', role='worker', parent='owner', owns=['scripts'])
(logs / 'call-orphan.log').write_text('unknown')
os.utime(logs / 'call-orphan.log', (1, 1))
(repo / '.oms/lifecycle').mkdir(exist_ok=True)
ledger = repo / '.oms/lifecycle/events.jsonl'
ledger.write_text(''.join(json.dumps(row) + '\n' for row in events))
(repo / '.oms/plan').mkdir(exist_ok=True)
plan = repo / '.oms/plan/tasks.json'
plan.write_text(json.dumps(dict(schema=1, tasks=tasks)))
cli = ['bash', str(root / 'scripts/gc.sh'), '--repo', str(repo), '--days', '30']
call_timeout = int(os.environ.get('OMS_TEST_CALL_TIMEOUT', '120'))
def run(*args):
    result = subprocess.run(cli + list(args), capture_output=True, text=True, check=True, timeout=call_timeout)
    return result.stdout
# Only the inline dispatch helper crashes; all other Python consumers stay real.
with tempfile.TemporaryDirectory(prefix='gc-helper-crash-') as temporary:
    shim = Path(temporary) / 'python3'
    shim.write_text('''#!/usr/bin/env bash
if [ "$#" = 5 ] && [ "$1" = - ] && [ "$2" = "$GC_CRASH_LIB" ] && [ "$3" = "$GC_CRASH_REPO" ]; then
  echo 'simulated dispatch helper crash' >&2
  exit "$GC_CRASH_CODE"
fi
exec "$GC_REAL_PYTHON" "$@"
''')
    shim.chmod(0o700)
    for code in (1, 20, 24, 75):
        environment = dict(os.environ, PATH=temporary + os.pathsep + os.environ['PATH'],
