    fail "gc deleted trigger evidence for a plan task with no typed state"
  grep -Fq 'retired Soul executor invalid-state; keeping legacy marker and evidence' \
    "$project/gc-invalid-state.err" ||
    fail "gc did not explain preservation of the retired executor"
  grep -Fq 'plan task t1 has an invalid state; kept trigger evidence' \
    "$project/gc-invalid-state.err" ||
    fail "gc did not explain the invalid plan state"
}

test_gc_preserves_unknown_exact_marker_schema() {
  local project="$TMP/gc-unknown-exact-marker-schema"
  local plan="$ROOT/scripts/agent-plan.sh"
  local markers lease rc=0 dry_out

  make_committed_repo "$project"
  markers="$project/.oms/delegations"
  mkdir -p "$markers" "$project/.oms/executors/exact"
  printf '{"schema":1,"executor_id":"exact","state":"running"}\n' \
    > "$project/.oms/executors/exact/meta.json"
  "$plan" --repo "$project" init --goal "typed marker evidence" >/dev/null
  "$plan" --repo "$project" add --id t1 --title one >/dev/null
  "$plan" --repo "$project" claim --id t1 --provider codex >/dev/null
  lease="$("$plan" --repo "$project" show --id t1 |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"

  printf '{"schema":2,"id":"plan-dead","pid":999999,"task_id":"t1","lease_id":"%s"}\n' \
    "$lease" > "$markers/a-plan-dead.json"
  printf '{"schema":4,"id":"plan-unproven","pid":999999,"task_id":"t1","lease_id":"%s"}\n' \
    "$lease" > "$markers/b-plan-unproven.json"
  printf '{"schema":3,"id":"executor-dead","pid":999999,"executor_id":"exact"}\n' \
    > "$markers/c-executor-dead.json"
  printf '{"schema":999,"id":"executor-future","pid":999999,"native_pid":999999,"executor_id":"exact"}\n' \
    > "$markers/d-executor-future.json"
  printf '{"schema":999,"id":"future-trigger","pid":999999,"native_pid":999999}\n' \
    > "$markers/e-future-trigger.json"

  rc=0
  "$plan" --repo "$project" recover-lease --id t1 --lease-id "$lease" \
    --expected-state claimed --markers-dir "$markers" --check \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "schema-4 marker without native pid did not veto plan recovery, got $rc"

  dry_out="$(cd "$project" && "$ROOT/scripts/gc.sh" --days 30 2>&1)"
  if printf '%s' "$dry_out" | grep >/dev/null -E 'orphan-delegation-(plan|executor): .* -> (ready|failed)'; then
    fail "gc dry-run consumed semantically unproven exact marker evidence: $dry_out"
  fi
  (cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply \
    >/dev/null 2> "$project/gc-unknown-schema.err") ||
    fail "gc failed while preserving unknown marker schemas"
  "$plan" --repo "$project" show --id t1 | grep -F '"state": "claimed"' > /dev/null ||
    fail "gc requeued a plan task despite an unproven exact marker"
  grep -Fq '"state":"running"' "$project/.oms/executors/exact/meta.json" ||
    fail "gc failed an executor despite an unknown exact marker schema"
  for marker in "$markers"/*.json; do
    [ -f "$marker" ] || fail "gc deleted unproven marker evidence: $marker"
  done
}

# smoke-weight: 5
test_agent_plan_owner_recovery_is_fenced() {
  local project="$TMP/plan-owner-recovery"
  local sh="$ROOT/scripts/agent-plan.sh"
  local markers="$project/.oms/delegations"
  local owner="owner_11111111111111111111111111111111"
  local other="owner_22222222222222222222222222222222"
  local dead_pid lease_live lease_dead lease_other lease_review lease_markerless lease_badmarker
  local out rc=0

  make_committed_repo "$project"
  "$sh" --repo "$project" init --goal "owner-fenced recovery" >/dev/null
  for id in claimed live dead other review markerless badmarker; do
    "$sh" --repo "$project" add --id "$id" --title "$id" >/dev/null
  done

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id claimed --provider codex >/dev/null
  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id live --provider codex >/dev/null
  lease_live="$("$sh" --repo "$project" show --id live |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id live --lease-id "$lease_live" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id dead --provider codex >/dev/null
  lease_dead="$("$sh" --repo "$project" show --id dead |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id dead --lease-id "$lease_dead" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$other" \
    "$sh" --repo "$project" claim --id other --provider claude >/dev/null
  lease_other="$("$sh" --repo "$project" show --id other |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id other --lease-id "$lease_other" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id review --provider codex >/dev/null
  lease_review="$("$sh" --repo "$project" show --id review |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" review --id review --lease-id "$lease_review" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id markerless --provider codex >/dev/null
  lease_markerless="$("$sh" --repo "$project" show --id markerless |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id markerless --lease-id "$lease_markerless" >/dev/null

  OMS_AUTOPILOT_OWNER_ID="$owner" \
    "$sh" --repo "$project" claim --id badmarker --provider codex >/dev/null
  lease_badmarker="$("$sh" --repo "$project" show --id badmarker |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  "$sh" --repo "$project" start --id badmarker --lease-id "$lease_badmarker" >/dev/null

  sh -c ':' & dead_pid=$!
  wait "$dead_pid" 2>/dev/null || true
  mkdir -p "$markers"
  printf '{"schema":3,"id":"live","pid":%d,"task_id":"live","lease_id":"%s","autopilot_owner_id":"%s"}\n' \
    "$$" "$lease_live" "$owner" > "$markers/live.json"
  printf '{"schema":3,"id":"dead","pid":%d,"task_id":"dead","lease_id":"%s","autopilot_owner_id":"%s"}\n' \
    "$dead_pid" "$lease_dead" "$owner" > "$markers/dead.json"
  printf '{"schema":3,"id":"review","pid":%d,"task_id":"review","lease_id":"%s","autopilot_owner_id":"%s"}\n' \
    "$dead_pid" "$lease_review" "$owner" > "$markers/review.json"
  printf '{"schema":3,"id":"badmarker","pid":"not-a-pid","task_id":"badmarker","lease_id":"%s","autopilot_owner_id":"%s"}\n' \
    "$lease_badmarker" "$owner" > "$markers/badmarker.json"

  rc=0
  OMS_HARNESS_CHILD=1 "$sh" --repo "$project" recover-owner \
    --owner-id "$owner" --markers-dir "$markers" --json \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] || fail "a harness child reached owner recovery, got $rc"
  "$sh" --repo "$project" show --id claimed | grep -F '"state": "claimed"' > /dev/null ||
    fail "child owner recovery changed parent authority"

  out="$("$sh" --repo "$project" recover-owner --owner-id "$owner" \
    --markers-dir "$markers" --json)" ||
    fail "owner recovery failed: $out"
  OMS_OWNER_RECOVERY="$out" python3 - <<'PY' || fail "owner recovery returned the wrong task set: $out"
import json
import os

row = json.loads(os.environ["OMS_OWNER_RECOVERY"])
assert row["recovered"] == ["claimed", "dead"], row
assert sorted(row["preserved"]) == ["badmarker", "live", "markerless", "review"], row
PY
  for id in claimed dead; do
    "$sh" --repo "$project" show --id "$id" | grep -F '"state": "ready"' > /dev/null ||
      fail "owner recovery did not requeue $id"
  done
  for id in live markerless badmarker; do
    "$sh" --repo "$project" show --id "$id" | grep -F '"state": "running"' > /dev/null ||
      fail "owner recovery stole live or unproven task $id"
  done
  "$sh" --repo "$project" show --id other | grep -F '"state": "running"' > /dev/null ||
    fail "owner recovery stole another owner's task"
  "$sh" --repo "$project" show --id review | grep -F '"state": "review"' > /dev/null ||
    fail "owner recovery requeued review evidence"

  rc=0
  "$sh" --repo "$project" recover-lease --id review --lease-id "$lease_review" \
    --expected-state review --markers-dir "$markers" \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "atomic lease recovery must refuse review, got $rc"
  "$sh" --repo "$project" show --id review | grep -F '"state": "review"' > /dev/null ||
    fail "atomic lease recovery changed review state"

  rc=0
  "$sh" --repo "$project" recover-lease --id other --lease-id stale-lease \
    --expected-state running --markers-dir "$markers" \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "atomic lease recovery must refuse a stale lease, got $rc"
  "$sh" --repo "$project" show --id other | grep -F '"state": "running"' > /dev/null ||
    fail "stale lease recovery changed the current worker"

  rc=0
  "$sh" --repo "$project" recover-lease --id live --lease-id "$lease_live" \
    --expected-state running --markers-dir "$markers" \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "a live exact marker must veto lease recovery, got $rc"
  "$sh" --repo "$project" show --id live | grep -F '"state": "running"' > /dev/null ||
    fail "lease recovery stole a task with an exact live marker"

  rc=0
  "$sh" --repo "$project" recover-lease --id markerless --lease-id "$lease_markerless" \
    --expected-state claimed --markers-dir "$markers" \
    >/dev/null 2>&1 || rc=$?
  [ "$rc" = 3 ] || fail "an expected-state mismatch must veto lease recovery, got $rc"
  "$sh" --repo "$project" show --id markerless | grep -F '"state": "running"' > /dev/null ||
    fail "state-CAS recovery changed a task after its observed transition"

  if grep -Eq "taskkill|start_new_session=os.name" "$ROOT/scripts/check.sh"; then
    fail "check supervisor must use the supported POSIX process path"
  fi
  if grep -Eq 'bash[.]exe|sh[.]exe|env[.]exe' "$ROOT/scripts/scratch-worktree.sh"; then
    fail "scratch owner selection must use supported shell names"
  fi
}

test_gc_keeps_orphan_artifacts_unless_asked() {
  local project="$TMP/gc-orphan-artifacts"
  local index orphan out

  make_committed_repo "$project"
  mkdir -p "$project/.oms/artifacts/ask"
  index="$project/.oms/artifacts/index.jsonl"
  orphan="$project/.oms/artifacts/ask/council-answer.md"
  printf 'a council answer a later round still cites\n' > "$orphan"
  printf '{"ts":"2026-06-11T00:00:01Z","kind":"call","event_id":"evt_kept","artifact":".oms/artifacts/ask/kept.md"}\n' > "$index"
  printf 'kept\n' > "$project/.oms/artifacts/ask/kept.md"
  # oms output-digest keeps its own newest 50; the orphan sweep must not age it out.
  mkdir -p "$project/.oms/artifacts/output-digest"
  printf 'raw capture\n' > "$project/.oms/artifacts/output-digest/20260101T000000Z-1.log"

  # Rows are retention; an orphaned file is the evidence itself, and its row was
  # retired by an earlier prune at a lower floor. Riding that deletion along
  # with the routine sweep is what made the sweep unrunnable here: seventeen
  # artifacts, including 08-02 council answers, would have gone with it.
  out="$(cd "$project" && OMS_ARTIFACT_ORPHAN_GRACE=0 "$ROOT/scripts/gc.sh" --days 0 --apply)"
  [ -f "$orphan" ] ||
    fail "the routine sweep must not delete an unreferenced artifact: $out"
  contains "$out" 'would delete' &&
    fail "the routine sweep must not even plan a file deletion: $out"

  out="$(cd "$project" && OMS_ARTIFACT_ORPHAN_GRACE=0 "$ROOT/scripts/gc.sh" --days 0 --apply --delete-orphan-files)"
  [ ! -f "$orphan" ] ||
    fail "--delete-orphan-files must remove the unreferenced artifact: $out"
  [ -f "$project/.oms/artifacts/ask/kept.md" ] ||
    fail "a referenced artifact must survive either way: $out"
  [ -f "$project/.oms/artifacts/output-digest/20260101T000000Z-1.log" ] ||
    fail "the orphan sweep must leave the self-retained output-digest store alone: $out"
}

test_gc_maintains_the_lifecycle_stream() {
  local project="$TMP/gc-lifecycle"
  local events="$ROOT/scripts/agent-events.sh"
  local stuck finished out state

  make_committed_repo "$project"
  stuck="$("$events" --repo "$project" start --provider codex --tool peer-delegate)"
  "$events" --repo "$project" transition --attempt "$stuck" --state starting --actor test >/dev/null
  "$events" --repo "$project" transition --attempt "$stuck" --state working --actor test >/dev/null
  finished="$("$events" --repo "$project" start --provider codex --tool ask)"
  for state in starting working verifying review "done"; do
    "$events" --repo "$project" transition --attempt "$finished" --state "$state" --actor test >/dev/null
  done

  # Backdated rather than raced against the clock: compaction compares the
  # terminal attempt's own stamp with the cutoff, and a fixture that finishes
  # inside the same second as the sweep is not old enough by either reading.
  OMS_GC_FIXTURE_ATTEMPT="$finished" python3 - "$project/.oms/lifecycle/events.jsonl" <<'FIXTURE_PY'
import json, os, sys

target = os.environ["OMS_GC_FIXTURE_ATTEMPT"]
path = sys.argv[1]
lines = []
with open(path, encoding="utf-8") as handle:
    for line in handle:
        if not line.strip():
            continue
        row = json.loads(line)
        if row.get("attempt_id") == target:
            row["ts"] = "2026-01-01T00:00:00Z"
        lines.append(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")
with open(path, "w", encoding="utf-8") as handle:
    handle.writelines(lines)
FIXTURE_PY

  # reconcile shipped tested and unreachable: nothing in the product called it,
  # so a worker that died mid-flight left its attempt non-terminal forever.
  # Compaction of the terminal one is the sweep's existing behavior, asserted
  # here because the two halves have to agree on which streams survive.
  out="$(cd "$project" && OMS_ATTEMPT_STALE_SECONDS=0 "$ROOT/scripts/gc.sh" --days 1 --apply)"
  contains "$out" "stale-attempt: $stuck" ||
    fail "gc should reconcile an attempt that stopped reporting: $out"
  "$events" --repo "$project" show --attempt "$stuck" --json |
    grep -F '"state": "blocked"' > /dev/null ||
    fail "a reconciled attempt should be blocked so the inbox can name it"
  "$events" --repo "$project" show --attempt "$stuck" --json |
    grep -F '"reason_code": "heartbeat_expired"' > /dev/null ||
    fail "the reconciled attempt should say why it was closed"
  ! grep -Fq "$finished" "$project/.oms/lifecycle/events.jsonl" ||
    fail "gc should compact the stream of a long-terminal attempt"
  grep -Fq "$stuck" "$project/.oms/lifecycle/events.jsonl" ||
    fail "a non-terminal attempt's stream must survive compaction"
}

test_gc_sweeps_stale_change_guard() {
  local project="$TMP/gc-guard"

  make_committed_repo "$project"
  ( cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . begin >/dev/null )
  [ -f "$project/.oms/guards/change-guard.tsv" ] || fail "guard snapshot missing"
  # Fresh guard survives.
  ( cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply >/dev/null 2>&1 )
  [ -f "$project/.oms/guards/change-guard.tsv" ] || fail "gc must keep a fresh guard"
  # Backdate the started stamp: an abandoned guard is swept.
  python3 - "$project/.oms/guards/change-guard.tsv" <<'PY'
import sys
p = sys.argv[1]
lines = []
for line in open(p):
    if line.startswith("started\t"):
        line = "started\t1000000000\n"
    lines.append(line)
open(p, "w").writelines(lines)
PY
  local out
  out="$(cd "$project" && "$ROOT/scripts/gc.sh" --days 30 --apply 2>&1)"
  contains "$out" "stale-change-guard" || fail "gc should report the stale guard"
  assert_not_exists "$project/.oms/guards/change-guard.tsv"
}

test_change_guard_status_flags_stale() {
  local project="$TMP/guard-stale-status"

  make_committed_repo "$project"
  ( cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . begin >/dev/null )
  local out
  out="$(cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . status)"
  contains "$out" "STALE" && fail "fresh guard must not read as stale"
  out="$(cd "$project" && OMS_GUARD_TTL=0 sh -c 'sleep 1; exec "$0" --repo . status' "$ROOT/scripts/change-guard.sh")"
  contains "$out" "STALE" || fail "aged guard should read as stale with OMS_GUARD_TTL=0"
  # A dead opt-in owner pid is stale regardless of age.
  ( cd "$project" && OMS_GUARD_PID=999999 "$ROOT/scripts/change-guard.sh" --repo . begin >/dev/null )
  out="$(cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . status)"
  contains "$out" "STALE" || fail "dead owner pid should read as stale"
  ( cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . end >/dev/null )
}

# smoke-weight: 13
test_patch_land_reject_records_and_resolves_fail_ledger() {
  local project="$TMP/land-ledger"
  local err1="$TMP/land-ledger.err1"
  local out2="$TMP/land-ledger.out2"
  local err2="$TMP/land-ledger.err2"

  make_committed_repo "$project"
  printf 'change\n' >> "$project/file.txt"
  ( cd "$project" && git diff > "$TMP/land-ledger.patch" && git checkout -- file.txt )
  local rc=0
  # Explicit ready/release files keep admission paused inside a real observer
  # window. Poll the barrier with a deadline; elapsed time never implies readiness.
  rc="$(python3 - "$ROOT" "$project" "$TMP/land-ledger.patch" "$err1" "$TMP" <<'PY'
import hashlib, json, os, pathlib, runpy, shlex, subprocess, sys, time
root, project, patch, errors, tmp = sys.argv[1:]
ready = pathlib.Path(tmp) / "landing-verifier-ready"
release = pathlib.Path(tmp) / "landing-verifier-release"
code = "\n".join([
    "import pathlib,sys,time",
    "pathlib.Path(%r).write_text('ready')" % str(ready),
    "release = pathlib.Path(%r)" % str(release),
    "deadline = time.monotonic() + 30",
    "while not release.exists():",
    "    if time.monotonic() >= deadline: raise SystemExit(9)",
    "    time.sleep(0.05)",
    "sys.exit(1)",
])
verify = "python3 -c " + shlex.quote("exec(" + repr(code) + ")")
snapshot = os.path.join(tmp, "landing-observer")
plan_cli = ["bash", root + "/scripts/agent-plan.sh", "--repo", project]
subprocess.run(plan_cli + ["init", "--goal", "rejected native landing"], check=True, stdout=subprocess.DEVNULL)
subprocess.run(plan_cli + ["add", "--id", "rejected", "--title", "fixture product change", "--verify", verify,
                           "--allowed", "file.txt"], check=True, stdout=subprocess.DEVNULL)
subprocess.run(plan_cli + ["claim", "--id", "rejected", "--provider", "codex"], check=True, stdout=subprocess.DEVNULL)
review = pathlib.Path(tmp) / 'rejected-native-review.md'; review.write_text('Fixture review evidence\n')
subprocess.run(plan_cli + ["review", "--id", "rejected", "--artifact", str(review), "--patch", patch],
               check=True, stdout=subprocess.DEVNULL)
task_before = pathlib.Path(project, ".oms/plan/tasks.json").read_bytes()
request = subprocess.check_output(["bash", root + "/scripts/patch-land.sh", "--repo", project,
                                  "--patch", patch, "--verify", verify, "--plan-task", "rejected", "--request-approval"], text=True).strip()
approval_cli = ["bash", root + "/scripts/approval-inbox.sh", "--repo", project]
grant = subprocess.check_output(approval_cli + ["decide", "--approval", request, "--decision", "approve",
                                                "--expected-version", "1", "--actor", "operator"], text=True).strip()
approval_before = json.loads(subprocess.check_output(approval_cli + ["show", "--approval", request, "--json"], text=True))
source_before = pathlib.Path(patch).read_bytes()
base_before = subprocess.check_output(["git", "-C", project, "rev-parse", "HEAD"])
with open(errors, "w") as err:
    worker = subprocess.Popen(["bash", root + "/scripts/patch-land.sh", "--repo", project,
                               "--patch", patch, "--verify", verify,
                               "--plan-task", "rejected", "--approval", request, "--approval-version", "2", "--approval-token", grant],
                              stdout=subprocess.DEVNULL, stderr=err)
    try:
        deadline = time.monotonic() + 30
        while not ready.exists():
            assert worker.poll() is None, "landing exited before the verifier barrier"
            assert time.monotonic() < deadline, "verifier barrier timed out"
            time.sleep(0.05)
        subprocess.run(["bash", "-c", '. "$1/scripts/lib/oms-common.sh"; '
                        'oms_worker_surface_snapshot "$2" "$3"',
                        "observer", root, project, snapshot], check=True)
        assert ".gitignore EXISTS" in pathlib.Path(snapshot, "omsstate").read_text()
        frozen = pathlib.Path(project) / ".oms/landing-patches"
        assert not list(frozen.glob("*.patch")), "published before ADMIT"
        release.write_text("go")
        assert worker.wait(timeout=30) == 1
        result = subprocess.run(["bash", "-c", '. "$1/scripts/lib/oms-common.sh"; '
                                 'oms_worker_state_violations "$2" "$3/omsstate"',
                                 "observer", root, project, snapshot],
                                check=True, text=True, capture_output=True)
        assert not result.stdout.strip(), result.stdout
        assert not list(frozen.glob("*.patch")), "rejection published a canonical patch"
        index = pathlib.Path(project) / ".oms/artifacts/index.jsonl"
        rows = [json.loads(line) for line in index.read_text().splitlines()]
        row = [row for row in rows if row.get("kind") == "patch-admit"][-1]
        assert row["exit"] == 1 and "patch" not in row
        assert row["patch_external"]["owned"] is False
        expected = hashlib.sha256(pathlib.Path(patch).read_bytes()).hexdigest()
        assert row["patch_sha256"] == row["patch_external"]["sha256"] == expected
        report = pathlib.Path(project) / row["artifact"]
        report_bytes = report.read_bytes()
        capture = pathlib.Path(next(line[len("- patch: "):] for line in report_bytes.decode().splitlines()
                                    if line.startswith("- patch: ")))
        assert not str(capture).startswith(project + "/")
        assert hashlib.sha256(report_bytes).hexdigest() == row["artifact_sha256"]
        helper = runpy.run_path(root + "/scripts/lib/landing-capture.py")
        if capture.exists():
            assert capture.read_bytes() == source_before
        else:
            # A managed rejected generation may be collected only after its
            # actual admission result and terminal release are durably linked.
            item = helper["find"](project, capture=str(capture))
            log = helper["rows"](project)
            encoded, digest = helper["encoded"], helper["digest"]
            assert item["sha256"] == expected and item["bytes"] == 2 * len(pathlib.Path(patch).read_bytes())
            assert item["directory"] == str(capture.parent) and not os.path.lexists(item["directory"])
            assert item["namespace"] == digest(os.path.realpath(project).encode())
            assert capture.name == item["landing_id"] + ".patch"
            terminals = [r for r in log if r.get("event") == "capture-terminal" and
                         r.get("managed_capture") == item]
            assert len(terminals) == 1 and terminals[0]["reason"] == "admission-rejected"
            assert not [r for r in log if r.get("event") == "intent" and r.get("landing_id") == item["landing_id"]]
            engine = runpy.run_path(root + "/scripts/lib/agent-events.py")
            events = engine["read_rows"](engine["event_path"](pathlib.Path(project)))
            created = [r for r in events if r.get("attempt_id") == row["operation_id"] and
                       r.get("event_type") == "attempt.created"]
            done = [r for r in events if r.get("attempt_id") == row["operation_id"] and
                    r.get("event_type") == "attempt.state_changed" and r.get("to_state") == "done"]
            assert len(created) == len(done) == 1
            assert created[0]["provider"] == "local" and created[0]["tool"] == "patch-admit"
            assert created[0]["refs"]["reference_writer"] == "landing-reference-v1"
            assert created[0]["refs"]["reference_input_sha256"] == digest(str(capture).encode())
            assert report_bytes.decode().splitlines()[0] == "# Patch admission: REJECT"
            assert row["artifact_sha256"] == digest(report_bytes) and row["exit"] == 1
            assert engine["parse_ts"](created[0]["ts"]) <= engine["parse_ts"](row["ts"]) <= engine["parse_ts"](done[0]["ts"])
            proof = dict(version=1, generation=item["generation"], attempt=row["operation_id"],
                         created_sha256=digest(encoded(created[0])), report=row["artifact"],
                         report_sha256=digest(report_bytes), index_event_id=row["event_id"],
                         index_row_sha256=digest(encoded(row)), exit=1)
            assert terminals[0]["native_terminal_proof"] == {
                "phase": "admission-rejected", "admission_sha256": digest(encoded(proof))}
            ready = helper["release_ready"](item, log, project)
            assert ready is not None and ready["release_proof"]["terminal_event_sha256"] == digest(encoded(terminals[0]))
            released = [r for r in log if r.get("event") == "capture-released" and
                        r.get("managed_capture") == item]
            assert len(released) == 1 and released[0]["release_ready_sha256"] == digest(encoded(ready))
            assert log.index(terminals[0]) < log.index(ready) < log.index(released[0])
        if os.name == 'nt':
            assert capture.exists(), 'unsupported cleanup must preserve private data'
            assert helper['usage'](project)[0] == 1
        else:
            assert not capture.exists(), "proved rejected private staging was not removed"
            assert not capture.parent.exists(), "rejected generation remains charged"
            assert helper['usage'](project) == (0, 0)
        assert pathlib.Path(patch).read_bytes() == source_before and not list(frozen.glob('*.patch'))
        assert subprocess.check_output(["git", "-C", project, "rev-parse", "HEAD"]) == base_before
        assert json.loads(subprocess.check_output(approval_cli + ["show", "--approval", request, "--json"], text=True)) == approval_before
        assert pathlib.Path(project, ".oms/plan/tasks.json").read_bytes() == task_before
    finally:
        release.write_text("go")
        if worker.poll() is None:
            worker.kill()
            worker.wait()
# A contended immediate cleanup cannot inherit an unbounded caller timeout.
if os.name != 'nt':
    busy = pathlib.Path(tmp) / 'rejected-cleanup-busy'
    subprocess.run(['git', 'clone', '-q', '--local', project, str(busy)], check=True)
    (busy / '.oms/delegations').mkdir(parents=True)
    lock_ready = pathlib.Path(tmp) / 'rejected-cleanup-lock-ready'
    lock_release = pathlib.Path(tmp) / 'rejected-cleanup-lock-release'
    holder = subprocess.Popen(['bash', '-c',
        '. "$1/scripts/lib/file-lock.sh"; hold() { touch "$3"; while [ ! -e "$4" ]; do sleep 0.05; done; }; '
        'oms_with_file_lock "$2" hold "$1" "$2" "$3" "$4"',
        'busy-cleanup', root, str(busy / '.oms/delegations/.marker-set-lock-target'), str(lock_ready), str(lock_release)],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    try:
        deadline = time.monotonic() + 10
        while not lock_ready.exists():
            assert holder.poll() is None and time.monotonic() < deadline
            time.sleep(0.02)
        call_timeout = max(30, int(os.environ.get('OMS_TEST_CALL_TIMEOUT', '120')))
        started = time.monotonic()
        refused = subprocess.run(['bash', root + '/scripts/patch-land.sh', '--repo', str(busy),
                                  '--patch', patch, '--verify', 'false'],
                                 env=dict(os.environ, OMS_LOCK_TIMEOUT=str(call_timeout * 2)),
                                 text=True, capture_output=True, timeout=call_timeout)
        assert refused.returncode == 1 and time.monotonic() - started < call_timeout, refused.stderr
        assert holder.poll() is None
        item = next(iter(helper['reservations'](str(busy)).values()))
        value = helper['certificate'](item)
        assert pathlib.Path(value['objects']['capture']['path']).exists()
        assert (busy / value['admission']['report']).exists()
        assert 'private rejected capture remains reserved' in refused.stderr
    finally:
        lock_release.write_text('release')
        holder.wait(timeout=5)
print(worker.returncode)
PY
)" || fail "concurrent rejection or retained capture check failed"
  [ "$rc" = "1" ] || fail "rejected land should exit 1, got $rc"
  ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" list ) | grep -F "patch-land REJECT" > /dev/null ||
    fail "rejection should be recorded in the fail-ledger"
  # Second attempt warns about the known rejection, then lands and resolves it.
  ( cd "$project" && "$ROOT/scripts/patch-land.sh" --patch "$TMP/land-ledger.patch" --verify true ) \
    >"$out2" 2>"$err2" || fail "admissible retry should land"
  assert_file_contains "$err2" "rejected before"
  assert_file_contains "$out2" "LANDED"
  assert_file_contains "$err2" "(uncommitted); commit it, then: oms land --repo"
  ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" list --unresolved ) | grep -F "patch-land REJECT" > /dev/null &&
    fail "successful land should resolve the recorded rejection"
  assert_file_contains "$project/file.txt" "change"
  "$ROOT/scripts/artifact-index.sh" --repo "$project" --json unresolved 100 \
    > "$TMP/land-ledger-index.json"
  python3 - "$TMP/land-ledger-index.json" <<'PY' || fail "external capture digest lost supersession identity"
import json, sys
rows = json.load(open(sys.argv[1]))["rows"]
failed = [row for row in rows if row.get("kind") == "patch-admit" and row.get("exit") == 1]
assert len(failed) == 1 and failed[0].get("superseded_by"), failed
PY
}

# smoke-weight: 5
test_patch_land_plan_task_supplies_patch() {
  local project="$TMP/land-plan-patch"
  local out="$TMP/land-plan.out"
  local err="$TMP/land-plan.err"

  make_committed_repo "$project"
  printf 'from-plan\n' >> "$project/file.txt"
  ( cd "$project" && git diff > "$TMP/land-plan.patch" && git checkout -- file.txt )
  "$ROOT/scripts/agent-plan.sh" --repo "$project" init --goal g >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t1 --title T --verify true >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" claim --id t1 --provider codex >/dev/null
  printf 'review\n' > "$TMP/land-plan.md"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" review --id t1 --artifact "$TMP/land-plan.md" --patch "$TMP/land-plan.patch" >/dev/null

  ( cd "$project" && "$ROOT/scripts/patch-land.sh" --plan-task t1 --verify true ) \
    >"$out" 2>"$err" || fail "--plan-task with stored patch should land"
  assert_file_contains "$err" "using patch from plan task t1"
  assert_file_contains "$project/file.txt" "from-plan"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" show --id t1 | grep -F '"state": "done"' > /dev/null ||
    fail "landed plan task should be done"
  # Without a stored patch it must fail loudly, not guess.
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t2 --title T2 --verify true >/dev/null
  local rc=0
  ( cd "$project" && "$ROOT/scripts/patch-land.sh" --plan-task t2 ) >/dev/null 2>"$project/err2" || rc=$?
  [ "$rc" = "2" ] || fail "--plan-task without stored patch should exit 2, got $rc"
  assert_file_contains "$project/err2" "no stored patch path"
}

test_patch_land_rejects_stale_review_patch_lease() {
  local project="$TMP/land-stale-review-lease"
  local plan="$ROOT/scripts/agent-plan.sh"
  local rc=0

  make_committed_repo "$project"
  printf 'stale-work\n' >> "$project/file.txt"
  (cd "$project" && git diff > "$TMP/land-stale-review.patch" && git checkout -- file.txt)
  "$plan" --repo "$project" init --goal g >/dev/null
  "$plan" --repo "$project" add --id t1 --title T --verify true >/dev/null
  "$plan" --repo "$project" claim --id t1 --provider codex >/dev/null
  "$plan" --repo "$project" review --id t1 --patch "$TMP/land-stale-review.patch" >/dev/null
  "$plan" --repo "$project" reclaim --include-review --ttl 0 >/dev/null
  "$plan" --repo "$project" claim --id t1 --provider claude >/dev/null

  (cd "$project" && "$ROOT/scripts/patch-land.sh" --plan-task t1 --verify true) \
    >/dev/null 2>"$project/err" || rc=$?
  [ "$rc" = 2 ] || fail "stale stored review patch should be rejected before admission"
  assert_file_contains "$project/err" "not review"
  assert_file_contains "$project/err" "oms agent-plan review --id"
  rc=0
  (cd "$project" && "$ROOT/scripts/patch-land.sh" --plan-task t1 \
    --patch "$TMP/land-stale-review.patch" --verify true) \
    >/dev/null 2>"$project/explicit.err" || rc=$?
  [ "$rc" = 2 ] || fail "explicit --patch must not bypass the stale review lease fence"
  assert_file_contains "$project/explicit.err" "not review"
  if grep -Fq stale-work "$project/file.txt"; then
    fail "a re-claimed task must not land the previous review's stored patch"
  fi
  "$plan" --repo "$project" show --id t1 | grep -F '"state": "claimed"' > /dev/null ||
    fail "stale patch rejection must preserve the new claim"
}

test_agent_plan_reclaim_include_review() {
  local d="$TMP/plan-reclaim-review"
  local SH="$ROOT/scripts/agent-plan.sh"

  mkdir -p "$d"
  "$SH" --repo "$d" init --goal "review reclaim" >/dev/null
  "$SH" --repo "$d" add --id t1 --title one >/dev/null
  "$SH" --repo "$d" claim --id t1 --provider codex >/dev/null
  "$SH" --repo "$d" review --id t1 --patch /tmp/p.patch >/dev/null
  # Fresh review is kept even with the flag (24h default TTL).
  "$SH" --repo "$d" reclaim --include-review >/dev/null
  "$SH" --repo "$d" show --id t1 | grep -F '"state": "review"' > /dev/null ||
    fail "a fresh review must survive reclaim --include-review"
  python3 - "$d/.oms/plan/tasks.json" <<'PY'
import json, sys
p = sys.argv[1]
d = json.load(open(p))
d["tasks"]["t1"]["updated"] = "2020-01-01T00:00:00Z"
json.dump(d, open(p, "w"))
PY
  "$SH" --repo "$d" status | grep -F "stale review t1:" > /dev/null ||
    fail "plain status must name a review nobody has answered"
  "$SH" --repo "$d" list | grep -F "STALE(review" > /dev/null ||
    fail "plan list must tag a stale review"
  # Aged review is only reclaimed with the opt-in flag.
  "$SH" --repo "$d" reclaim >/dev/null
  "$SH" --repo "$d" show --id t1 | grep -F '"state": "review"' > /dev/null ||
    fail "default reclaim must never touch review"
  local out
  out="$("$SH" --repo "$d" reclaim --include-review)"
  contains "$out" "reclaimed t1 from review" || fail "aged review should be reclaimed with the flag"
  "$SH" --repo "$d" show --id t1 | grep -F '"patch": "/tmp/p.patch"' > /dev/null ||
    fail "reclaiming a review must keep its artifact/patch"
}

