d = json.load(open(p))
d["tasks"]["t1"]["updated"] = "2020-01-01T00:00:00Z"
json.dump(d, open(p, "w"))
PY
  ( cd "$project" && "$ROOT/scripts/change-guard.sh" --repo . begin >/dev/null )
