test_skill_router_separates_consultation_from_delegation() {
  local OMS_SKILL_HINTS=1
  export OMS_SKILL_HINTS
  local d="$TMP/skill-router-actions"
  local project="$d/project"
  local out

  make_committed_repo "$project"
  out="$(printf '{"prompt":"codex한테 의견 물어봐","session_id":"ask1","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" 'oms-agent-harness' || fail "consultation should route to oms-agent-harness"
  if printf '%s' "$out" | grep >/dev/null -E 'peer-(ask|review|delegate)'; then
    fail "consultation must not expose a retired peer skill"
  fi

  out="$(printf '{"prompt":"codex한테 시켜: README 고쳐","session_id":"write1","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" 'oms-agent-harness' || fail "write delegation should route to oms-agent-harness"
  if printf '%s' "$out" | grep >/dev/null -E 'peer-(ask|review|delegate)'; then
    fail "write delegation must not expose a retired peer skill"
  fi
}

test_skill_router_routes_trust_boundary_precisely() {
  local OMS_SKILL_HINTS=1
  export OMS_SKILL_HINTS
  local d="$TMP/skill-router-trust-boundary"
  local project="$d/project"
  local prompt
  local out
  local i=0

  make_committed_repo "$project"
  while IFS= read -r prompt; do
    i=$((i + 1))
    # Stderr goes to a file so a failure names its mechanism: the router is
    # fail-open by design, and a transient helper crash under parallel-shard
    # load surfaces as empty suggestions with exit 0 — indistinguishable from
    # a routing miss unless the diagnostic is kept.
    out="$(printf '{"prompt":"%s","session_id":"security-pos-%s","turn_id":"t1","cwd":"%s"}' \
      "$prompt" "$i" "$project" |
      TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh" \
        2> "$d/router-stderr.txt")"
    contains "$out" 'oms-trust-boundary' ||
      fail "router should suggest oms-trust-boundary for: $prompt (out: $out; stderr: $(cat "$d/router-stderr.txt" 2>/dev/null))"
  done <<'EOF'
threat model this webhook before release
이 결제 권한의 보안 경계를 검토해줘
map the abuse path for this file upload
run a security review of this file upload
add authorization to this API endpoint
check secret handling for this payment webhook
EOF

  i=0
  while IFS= read -r prompt; do
    i=$((i + 1))
    out="$(printf '{"prompt":"%s","session_id":"security-neg-%s","turn_id":"t1","cwd":"%s"}' \
      "$prompt" "$i" "$project" |
      TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
    if contains "$out" 'oms-trust-boundary'; then
      fail "router must not suggest oms-trust-boundary for: $prompt ($out)"
    fi
  done <<'EOF'
rename the internal boundary helper
review the API documentation formatting
fix the authorization spelling in this comment
EOF
}

test_skill_router_keeps_trace_off_ordinary_test_talk() {
  local OMS_SKILL_HINTS=1
  export OMS_SKILL_HINTS
  local d="$TMP/skill-router-precision"
  local project="$d/project"
  local prompt
  local out
  local i=0

  # Triggers are substring-matched against the whole prompt, so precision is a
  # property of the manifest that nothing else checks. A skill pushed into every
  # session that mentions a test is a permanent context tax, and the first thing
  # a reader does with a router that cries wolf is stop reading it.
  make_committed_repo "$project"
  while IFS= read -r prompt; do
    i=$((i + 1))
    out="$(printf '{"prompt":"%s","session_id":"router-pos-%s","turn_id":"t1","cwd":"%s"}' \
      "$prompt" "$i" "$project" |
      TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
    contains "$out" 'skill hint: oms-trace' ||
      fail "router should suggest oms-trace for: $prompt ($out)"
  done <<'EOF'
원인 추적 좀 해줘
what is the root cause of this crash
재현이 안 되는 버그가 있어
간헐적으로 결과가 달라진다
왜 이런 결과가 나왔지
EOF

  i=0
  while IFS= read -r prompt; do
    i=$((i + 1))
    out="$(printf '{"prompt":"%s","session_id":"router-neg-%s","turn_id":"t1","cwd":"%s"}' \
      "$prompt" "$i" "$project" |
      TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
    if contains "$out" 'oms-trace'; then
      fail "router must not suggest oms-trace for: $prompt ($out)"
    fi
  done <<'EOF'
add a regression test for this helper
quarantine the flaky e2e test
refactor this function for clarity
commit and push the change
write the training script
EOF

  # Native matching can handle ordinary work; the hook should not turn a
  # substring or a generic continuation into harness/GPU orchestration.
  mkdir -p "$d/bin"
  printf '#!/usr/bin/env bash\nexit 93\n' > "$d/bin/nvidia-smi"
  chmod +x "$d/bin/nvidia-smi"
  for prompt in 'make room in this dialog' 'resume a paused download' '알아서 구현해줘' '최신 모델 이름은?'; do
    i=$((i + 1))
    out="$(printf '{"prompt":"%s","session_id":"router-near-%s","turn_id":"t1","cwd":"%s"}' \
      "$prompt" "$i" "$project" |
      PATH="$d/bin:$PATH" TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
    if printf '%s' "$out" | grep >/dev/null -E 'skill hint:.*oms-(agent-harness|gpu-workstation|careful)'; then
      fail "generic prompt must not force a specialized skill: $prompt ($out)"
    fi
  done
  for prompt in 'careful mode로 진행해줘' 'use careful collaboration here' '신중 협업 모드로 봐줘' '신중 모드 켜줘' 'Collaboration mode: careful'; do
    i=$((i + 1))
    out="$(printf '{"prompt":"%s","session_id":"router-careful-pos-%s","turn_id":"t1","cwd":"%s"}' \
      "$prompt" "$i" "$project" |
      TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
    contains "$out" 'oms-careful' || fail "explicit careful trigger should route to oms-careful: $prompt ($out)"
  done
  for prompt in 'be careful with edge cases' 'explain the collaboration history' 'mode selector test'; do
    i=$((i + 1))
    out="$(printf '{"prompt":"%s","session_id":"router-careful-neg-%s","turn_id":"t1","cwd":"%s"}' \
      "$prompt" "$i" "$project" |
      TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
    if contains "$out" 'oms-careful'; then
      fail "ordinary prompt must not trigger oms-careful: $prompt ($out)"
    fi
  done
  out="$(printf '{"prompt":"CUDA OOM","session_id":"router-gpu","turn_id":"t1","cwd":"%s"}' "$project" |
    PATH="$d/bin:$PATH" TMPDIR="$d" OMS_AUTO_TASK=0 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" 'oms-gpu-workstation' || fail "real OOM must still route to GPU guidance"
}

# smoke-weight: 8
test_skill_router_auto_records_task_prompts() {
  local d="$TMP/skill-router-auto-task"
  local project="$d/project"
  local payload
  local before
  local after
  local same_prompt_before

  # This case checks recording semantics; the next case owns deadline assertions.
  make_committed_repo "$project"

  payload="$(printf '{"prompt":"고칠 부분 확인하고 있으면 수정해줘","session_id":"auto1","turn_id":"t1","cwd":"%s"}' "$project")"
  printf '%s' "$payload" | TMPDIR="$d" OMS_AUTO_TASK=1 OMS_AUTO_TASK_TIMEOUT=10 bash "$ROOT/scripts/skill-router.sh" >/dev/null
  assert_file_contains "$project/.oms/task/current.md" "Respond to user request:"
  assert_file_contains "$project/.oms/task/current.md" "User prompt (task/medium): 고칠 부분 확인하고 있으면 수정해줘"
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"action": "auto_task"'
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"status": "created"'

  payload="$(printf '{"prompt":"이어서 ablation 기록 자동화도 확인해줘","session_id":"auto1","turn_id":"t2","cwd":"%s"}' "$project")"
  printf '%s' "$payload" | TMPDIR="$d" OMS_AUTO_TASK=1 OMS_AUTO_TASK_TIMEOUT=10 bash "$ROOT/scripts/skill-router.sh" >/dev/null
  assert_file_contains "$project/.oms/task/current.md" "이어서 ablation 기록 자동화도 확인해줘"
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"status": "appended"'

  before="$(grep -F "User prompt" "$project/.oms/task/current.md" | wc -l | tr -d ' ')"
  printf '%s' "$payload" | TMPDIR="$d" OMS_AUTO_TASK=1 OMS_AUTO_TASK_TIMEOUT=10 bash "$ROOT/scripts/skill-router.sh" >/dev/null
  after="$(grep -F "User prompt" "$project/.oms/task/current.md" | wc -l | tr -d ' ')"
  [ "$before" = "$after" ] || fail "same turn/prompt should not append twice"
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"status": "deduped"'

  same_prompt_before="$(grep -F "이어서 ablation 기록 자동화도 확인해줘" "$project/.oms/task/current.md" | wc -l | tr -d ' ')"
  payload="$(printf '{"prompt":"이어서 ablation 기록 자동화도 확인해줘","session_id":"auto1","turn_id":"t3","cwd":"%s"}' "$project")"
  printf '%s' "$payload" | TMPDIR="$d" OMS_AUTO_TASK=1 OMS_AUTO_TASK_TIMEOUT=10 bash "$ROOT/scripts/skill-router.sh" >/dev/null
  [ "$(grep -F "이어서 ablation 기록 자동화도 확인해줘" "$project/.oms/task/current.md" | wc -l | tr -d ' ')" = "$((same_prompt_before + 1))" ] ||
    fail "the same prompt on a new turn is a new request and must be recorded"
}

# smoke-weight: 34
test_skill_router_auto_task_timeout_retries_owned_writer_once() {
  local d="$TMP/skill-router-auto-task-timeout"
  local foreign_pid
  local real_python
  local prompt='고칠 부분 확인하고 있으면 수정해줘'
  local scenario project bin_dir wrapper first second prompt_note

  wait_auto_task_child_exit() {
    local child_pid="$1" attempts=0
    while kill -0 "$child_pid" 2>/dev/null; do
      [ "$attempts" -lt 80 ] || return 1
      sleep 0.1
      attempts=$((attempts + 1))
    done
  }

  real_python="$(command -v python3)"
  sleep 120 &
  foreign_pid=$!
  trap 'kill "$foreign_pid" 2>/dev/null || true; wait "$foreign_pid" 2>/dev/null || true; cleanup' EXIT
  for scenario in init-before append-before append-after success-descendant; do
    prompt_note="User prompt (task/medium): $prompt"
    project="$d/$scenario/project"
    bin_dir="$d/$scenario/bin"
    wrapper="$bin_dir/agent-task-wrapper"
    make_committed_repo "$project"
    mkdir -p "$bin_dir"
    cat > "$wrapper" <<'EOF'
#!/usr/bin/env bash
set -u
mode="${OMS_TEST_DELAY_MODE:-none}"
operation="${3:-}"
delay_once() {
  [ ! -e "$OMS_TEST_DELAY_ONCE" ] || return 0
  : > "$OMS_TEST_DELAY_ONCE"
  (sleep 120; : > "$OMS_TEST_CHILD_MARKER") &
  printf '%s\n' "$!" > "$OMS_TEST_CHILD_PID"
  wait
}
if [ "$mode" = init-before ] && [ "$operation" = init ]; then
  delay_once
elif [ "$mode" = append-before ] && [ "$operation" = append ]; then
  delay_once
elif [ "$mode" = success-descendant ] && [ "$operation" = append ]; then
  "$OMS_TEST_REAL_AGENT_TASK" "$@"
  result=$?
  (sleep 120; : > "$OMS_TEST_CHILD_MARKER") &
  printf '%s\n' "$!" > "$OMS_TEST_CHILD_PID"
  exit "$result"
fi
exec "$OMS_TEST_REAL_AGENT_TASK" "$@"
EOF
    cat > "$bin_dir/python3" <<'EOF'
#!/usr/bin/env bash
set -u
if [ "${OMS_TEST_DELAY_MODE:-none}" = append-after ] &&
   [ "${1:-}" = "$OMS_TEST_LANDING_REFERENCE" ] &&
   [ "${2:-}" = finish ] && [ ! -e "$OMS_TEST_DELAY_ONCE" ] &&
   grep -Fq "$OMS_TEST_PROMPT_NOTE" "$3/.oms/task/current.md" 2>/dev/null; then
  : > "$OMS_TEST_DELAY_ONCE"
  (sleep 120; : > "$OMS_TEST_CHILD_MARKER") &
  printf '%s\n' "$!" > "$OMS_TEST_CHILD_PID"
  wait
fi
exec "$OMS_TEST_REAL_PYTHON" "$@"
EOF
    chmod +x "$wrapper" "$bin_dir/python3"

    invoke_auto_task() {
      local mode="$1" timeout="${2:-10}"
      PATH="$bin_dir:$PATH" OMS_AUTO_TASK=1 OMS_AUTO_TASK_TIMEOUT="$timeout" \
        OMS_HOOK_RESOLVED_REPO="$project" \
        OMS_TEST_REAL_AGENT_TASK="$ROOT/scripts/agent-task.sh" \
        OMS_TEST_REAL_PYTHON="$real_python" \
        OMS_TEST_LANDING_REFERENCE="$ROOT/scripts/lib/landing-reference.py" \
        OMS_TEST_DELAY_MODE="$mode" OMS_TEST_DELAY_ONCE="$d/$scenario/delayed" \
        OMS_TEST_CHILD_MARKER="$d/$scenario/child-wrote" \
        OMS_TEST_CHILD_PID="$d/$scenario/child.pid" \
        OMS_TEST_PROMPT_NOTE="$prompt_note" \
        python3 - "$ROOT" "$project" "$wrapper" "$prompt" <<'PY'
import json
import sys
from pathlib import Path
from unittest.mock import patch

root, project, wrapper, prompt = sys.argv[1:]
sys.path.insert(0, str(Path(root) / "scripts" / "lib"))
import hook_state

payload = {"session_id": "timeout-retry", "turn_id": "t1", "cwd": project}
with patch.object(hook_state, "agent_task_script", return_value=Path(wrapper)):
    hook_state.auto_task_record(payload, prompt, hook_state.classify_prompt(prompt))
state_dir = Path(project) / ".oms" / "hooks" / "sessions"
states = [json.loads(path.read_text(encoding="utf-8")) for path in state_dir.glob("*.task.json")]
print(json.dumps(states[-1] if states else {}))
PY
    }

    first="$(invoke_auto_task "$scenario" 10)"
    if [ "$scenario" = success-descendant ]; then
      python3 -c 'import json,sys; s=json.loads(sys.argv[1]); assert s.get("status") in {"created","appended","rotated"} and s.get("prompt_hash"), s' "$first" ||
        fail "successful publication must be acknowledged: $first"
      [ "$(grep -F "$prompt_note" "$project/.oms/task/current.md" | wc -l | tr -d ' ')" = "1" ] ||
        fail "successful publication must be recorded exactly once"
      [ -s "$d/$scenario/child.pid" ] || fail "success case did not start its owned descendant"
      wait_auto_task_child_exit "$(cat "$d/$scenario/child.pid")" ||
        fail "a successful helper left a detached descendant writing"
      [ ! -e "$d/$scenario/child-wrote" ] || fail "a successful helper left a detached descendant writing"
      kill -0 "$foreign_pid" 2>/dev/null || fail "success cleanup killed or altered the unrelated process"
      continue
    fi
    python3 -c 'import json,sys; s=json.loads(sys.argv[1]); assert not s.get("prompt_hash"), s' "$first" ||
      fail "$scenario timeout must not publish a successful route hash: $first"
    assert_file_contains "$project/.oms/hooks/events.jsonl" '"status": "timeout"'
    [ -s "$d/$scenario/child.pid" ] || fail "$scenario did not start its owned descendant"
    wait_auto_task_child_exit "$(cat "$d/$scenario/child.pid")" ||
      fail "$scenario left a timed-out descendant running"
    [ ! -e "$d/$scenario/child-wrote" ] || fail "$scenario left a timed-out descendant running"
    kill -0 "$foreign_pid" 2>/dev/null || fail "$scenario killed or altered the unrelated process"

    second="$(invoke_auto_task none 10)"
    python3 -c 'import json,sys; s=json.loads(sys.argv[1]); assert s.get("status") in {"created","appended","rotated"} and s.get("prompt_hash"), s' "$second" ||
      fail "$scenario retry must commit its prompt only after publication: $second"
    [ "$(grep -F "$prompt_note" "$project/.oms/task/current.md" | wc -l | tr -d ' ')" = "1" ] ||
      fail "$scenario retry must publish the same request exactly once"
    if [ "$scenario" = append-after ]; then
      python3 - "$ROOT" "$project" <<'PY'
import sys
from pathlib import Path
import runpy

root, project = sys.argv[1:]
events = runpy.run_path(str(Path(root) / "scripts/lib/agent-events.py"))
_, projection = events["load_projection"](Path(project))
unknown = [row for row in projection.values()
           if row.get("provider") == "local" and row.get("tool") == "agent-task"
           and row.get("terminal") is not True]
assert unknown, "timed-out operation evidence must remain nonterminal"
PY
    fi
  done
  python3 - "$ROOT" <<'PY_STDIN_TIMEOUT' || fail "stdin delivery escaped the agent-task timeout"
import os, subprocess, sys, tempfile, time
from pathlib import Path
from unittest.mock import patch

root = Path(sys.argv[1])
sys.path.insert(0, str(root / "scripts" / "lib"))
import hook_state

with tempfile.TemporaryDirectory(prefix="oms-hook-stdin-timeout-") as raw:
    base = Path(raw)
    helper = base / "agent-task"
    marker = base / "late-write"
    pidfile = base / "descendant.pid"
    helper.write_text(
        '''#!/usr/bin/env bash
(sleep 5; : > "$OMS_TEST_MARKER") &
echo $! > "$OMS_TEST_PIDFILE"; wait
''',
        encoding="utf-8",
    )
    helper.chmod(0o755)
    foreign = subprocess.Popen(["sleep", "120"])
    os.environ.update({
        "OMS_AUTO_TASK_TIMEOUT": "1",
        "OMS_TEST_MARKER": str(marker),
        "OMS_TEST_PIDFILE": str(pidfile),
    })
    payload = "가" * 4000
    assert len(payload.encode("utf-8")) == 12000
    try:
        started = time.monotonic()
        with patch.object(hook_state, "agent_task_script", return_value=helper):
            result = hook_state.run_agent_task(base, ["append"], payload)
        elapsed = time.monotonic() - started
        assert result == 124, result
        assert elapsed < 2.5, elapsed
        assert pidfile.is_file(), "fake helper did not start its writer"
        # Observe past the helper's scheduled write time, so absence proves
        # cleanup rather than merely a short race window.
        time.sleep(5.2)
        assert not marker.exists(), "timed-out stdin writer survived cleanup"
        assert foreign.poll() is None, "timeout cleanup affected an unrelated process"
    finally:
        foreign.terminate()
        foreign.wait(timeout=3)
PY_STDIN_TIMEOUT
  kill "$foreign_pid" 2>/dev/null || true
  wait "$foreign_pid" 2>/dev/null || true
  foreign_pid=""
  trap cleanup EXIT
}

test_skill_router_skips_system_prompts() {
  local d="$TMP/skill-router-skip"
  local project="$d/project"
  local out

  make_committed_repo "$project"
  printf '{"prompt":"fix this bug","session_id":"off1","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" bash "$ROOT/scripts/skill-router.sh" >/dev/null
  assert_not_exists "$project/.oms/task/current.md"

  out="$(printf '{"prompt":"oh-my-setting이 뭐야","session_id":"plain1","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_SKILL_HINTS=1 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" 'oms-ops' || fail "plain question should still receive a skill hint"
  assert_not_exists "$project/.oms"

  for p in '/commit' '<task-notification>x</task-notification>' '안녕하세요 좋은 아침' 'not-json'; do
    out="$(printf '%s' "{\"prompt\":\"$p\",\"session_id\":\"s\"}" |
      TMPDIR="$d" bash "$ROOT/scripts/skill-router.sh")" ||
      fail "router must fail-open, got nonzero for: $p"
    [ -z "$out" ] || fail "router should stay silent for: $p"
  done
  # Malformed payload: silent, exit 0.
  out="$(printf 'garbage' | TMPDIR="$d" bash "$ROOT/scripts/skill-router.sh")" ||
    fail "router must fail-open on malformed payload"
  [ -z "$out" ] || fail "router should stay silent on malformed payload"
  # Kill switch.
  out="$(printf '{"prompt":"커밋해줘","session_id":"k"}' |
    TMPDIR="$d" OMS_SKILL_ROUTER_OFF=1 bash "$ROOT/scripts/skill-router.sh")"
  [ -z "$out" ] || fail "OMS_SKILL_ROUTER_OFF=1 must silence the router"

  # Correction capture is opt-in, silent, and only for an adopted repository.
  local pending="$project/.oms/memory/pending.jsonl" correction
  correction='{"prompt":"No, use ruff instead of flake8. Keep the rest.","session_id":"c1","cwd":"%s"}'
  # shellcheck disable=SC2059  # the fixture is the format
  printf "$correction" "$project" | TMPDIR="$d" OMS_LESSON_CAPTURE=1 bash "$ROOT/scripts/skill-router.sh" >/dev/null
  assert_not_exists "$project/.oms"
  mkdir -p "$project/.oms"
  # shellcheck disable=SC2059
  printf "$correction" "$project" | TMPDIR="$d" bash "$ROOT/scripts/skill-router.sh" >/dev/null
  assert_not_exists "$pending"
  # shellcheck disable=SC2059
  printf "$correction" "$project" | TMPDIR="$d" OMS_LESSON_CAPTURE=1 OMS_HARNESS_CHILD=1 \
    bash "$ROOT/scripts/skill-router.sh" >/dev/null
  assert_not_exists "$pending"
  for p in 'Please summarize the README for me.' '<task-notification>no, use x instead</task-notification>'; do
    printf '{"prompt":"%s","session_id":"c2","cwd":"%s"}' "$p" "$project" |
      TMPDIR="$d" OMS_LESSON_CAPTURE=1 bash "$ROOT/scripts/skill-router.sh" >/dev/null
  done
  assert_not_exists "$pending"
  printf '{"prompt":"No, the key is api_k''ey = s''k-abcdefgh''ijklmnop%s","session_id":"c3","cwd":"%s"}' \
    'qrstuvwxyz0123456789' "$project" |
    TMPDIR="$d" OMS_LESSON_CAPTURE=1 bash "$ROOT/scripts/skill-router.sh" >/dev/null
  assert_not_exists "$pending"
  for _ in 1 2; do
    # shellcheck disable=SC2059
    out="$(printf "$correction" "$project" | TMPDIR="$d" OMS_LESSON_CAPTURE=1 OMS_SKILL_ROUTER_OFF=1 \
      bash "$ROOT/scripts/skill-router.sh")"
    [ -z "$out" ] || fail "correction capture must print nothing"
  done
  [ "$(wc -l < "$pending" | tr -d ' ')" = 1 ] || fail "one correction is queued once: $(cat "$pending")"
  assert_file_contains "$pending" "No, use ruff instead of flake8."
  ! grep -q "Keep the rest" "$pending" || fail "capture keeps one sentence, not the prompt"
  assert_not_exists "$project/.oms/memory/shared.md"
  # Only review promotes it; rejecting keeps it out for good.
  (cd "$project" && "$ROOT/scripts/agent-memory.sh" review > "$d/review")
  assert_file_contains "$d/review" "correction"
  correction="$(sed -n 's/.*"id": "\(pend-[0-9a-f]*\)".*/\1/p' "$pending")"
  (cd "$project" && "$ROOT/scripts/agent-memory.sh" review --accept "$correction" >/dev/null)
  assert_file_contains "$project/.oms/memory/shared.md" "No, use ruff instead of flake8."
  assert_file_contains "$project/.oms/memory/shared.md" "kind: lesson"
  (cd "$project" && "$ROOT/scripts/agent-memory.sh" review > "$d/review")
  assert_file_contains "$d/review" "memory review: nothing waiting"
}

ctx_cache_digest() {
  python3 -c 'import hashlib, sys; print(hashlib.sha256(sys.argv[1].encode()).hexdigest()[:24])' "$1"
}

test_context_pressure_warns_once_at_low_context() {
  local d="$TMP/ctx-pressure-warn"
  local project="$d/project"
  local hud="$d/hud-cache"
  local out digest

  make_committed_repo "$project"
  mkdir -p "$project/.oms" "$hud"
  digest="$(ctx_cache_digest ctxwarn1)"
  printf '{"schema":1,"used_percentage":90}\n' > "$hud/ctx-$digest.json"

  out="$(printf '{"prompt":"이어서 계속 봐줘","session_id":"ctxwarn1","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" '[oms] context low (~10% left)' ||
    fail "10% left must trigger the warn advisory: $out"
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"action": "context_pressure"'
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"capture": "skipped"'
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"source": "claude"'
  # The advisory is once per band per session, not once per prompt.
  out="$(printf '{"prompt":"이어서 계속 봐줘 2","session_id":"ctxwarn1","turn_id":"t2","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  if contains "$out" '[oms] context'; then
    fail "warn band must announce once per session: $out"
  fi
}

test_context_capture_starts_silently_at_thirty_percent_left() {
  local d="$TMP/ctx-capture-early"
  local project="$d/project"
  local hud="$d/hud-cache"
  local out digest

  make_committed_repo "$project"
  mkdir -p "$project/.oms" "$hud"
  digest="$(ctx_cache_digest ctxcap1)"
  printf '{"schema":1,"used_percentage":72}\n' > "$hud/ctx-$digest.json"
  out="$(printf '{"prompt":"이어서 계속 봐줘","session_id":"ctxcap1","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  if contains "$out" '[oms] context'; then
    fail "28% left is a capture, not an advisory: $out"
  fi
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"action": "context_capture"'
  # Once per window: the next reading inside the band captures nothing new.
  printf '{"schema":1,"used_percentage":75}\n' > "$hud/ctx-$digest.json"
  printf '{"prompt":"이어서 계속 봐줘 2","session_id":"ctxcap1","turn_id":"t2","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh" >/dev/null
  [ "$(grep -c '"action": "context_capture"' "$project/.oms/hooks/events.jsonl")" -eq 1 ] ||
    fail "the early capture must fire once per window"
  # The advisory band still speaks after the early capture.
  printf '{"schema":1,"used_percentage":90}\n' > "$hud/ctx-$digest.json"
  out="$(printf '{"prompt":"이어서 계속 봐줘 3","session_id":"ctxcap1","turn_id":"t3","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" '[oms] context low (~10% left)' ||
    fail "the warn band must still announce after an early capture: $out"
}

test_context_pressure_escalates_and_rearms() {
  local d="$TMP/ctx-pressure-bands"
  local project="$d/project"
  local hud="$d/hud-cache"
  local out digest state

  make_committed_repo "$project"
  mkdir -p "$project/.oms" "$hud"
  digest="$(ctx_cache_digest ctxband1)"
  state="$project/.oms/hooks/sessions/$(python3 -c 'import hashlib, sys; print(hashlib.sha256(sys.argv[1].encode()).hexdigest()[:32])' ctxband1).ctx.json"

  run_band() {
    printf '{"schema":1,"used_percentage":%s}\n' "$1" > "$hud/ctx-$digest.json"
    printf '{"prompt":"계속 진행해줘","session_id":"ctxband1","turn_id":"%s","cwd":"%s"}' "$2" "$project" |
      TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh"
  }

  out="$(run_band 90 t1)"
  contains "$out" 'context low' || fail "10% left must warn: $out"
  # Crossing into the urgent band speaks once more, then latches.
  out="$(run_band 95 t2)"
  contains "$out" 'context nearly exhausted (~5% left)' ||
    fail "5% left must escalate to urgent: $out"
  out="$(run_band 96 t3)"
  [ -z "$out" ] || fail "urgent band must announce once: $out"
  # Recovery (compaction, fresh window) re-arms both bands.
  out="$(run_band 50 t4)"
  [ -z "$out" ] || fail "recovered context must stay silent: $out"
  grep -Fq '"stage": null' "$state" || fail "recovery must reset the band latch"
  out="$(run_band 88 t5)"
  contains "$out" 'context low (~12% left)' ||
    fail "a fresh crossing after re-arm must warn again: $out"
}

test_context_pressure_reads_codex_transcript() {
  local d="$TMP/ctx-pressure-codex"
  local project="$d/project"
  local transcript="$d/rollout-test.jsonl"
  local out

  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  # Newest token_count wins; trailing non-token rows must not hide it.
  printf '%s\n' '{"type":"event_msg","payload":{"type":"token_count","info":{"last_token_usage":{"total_tokens":100000},"model_context_window":200000}}}' > "$transcript"
  printf '%s\n' '{"type":"event_msg","payload":{"type":"token_count","info":{"last_token_usage":{"total_tokens":178000},"model_context_window":200000}}}' >> "$transcript"
  printf '%s\n' '{"type":"response_item","payload":{"type":"message"}}' >> "$transcript"

  out="$(printf '{"prompt":"계속 진행해줘","session_id":"ctxcodex1","turn_id":"t1","cwd":"%s","transcript_path":"%s"}' "$project" "$transcript" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$d/no-cache" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" 'context low (~11% left)' ||
    fail "codex transcript token_count must feed the advisory: $out"
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"source": "codex"'
}

test_context_pressure_fails_open() {
  local d="$TMP/ctx-pressure-open"
  local project="$d/project"
  local hud="$d/hud-cache"
  local out digest

  make_committed_repo "$project"
  mkdir -p "$project/.oms" "$hud"
  digest="$(ctx_cache_digest ctxopen1)"
  printf '{"schema":1,"used_percentage":90}\n' > "$hud/ctx-$digest.json"

  # Kill switch.
  out="$(printf '{"prompt":"계속 진행해줘","session_id":"ctxopen1","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_PRESSURE=0 bash "$ROOT/scripts/skill-router.sh")"
  if contains "$out" '[oms] context'; then
    fail "OMS_CTX_PRESSURE=0 must silence the advisory: $out"
  fi
  # A stale reading is no reading: the cache outlived its TTL.
  touch -d '2 hours ago' "$hud/ctx-$digest.json"
  out="$(printf '{"prompt":"계속 진행해줘","session_id":"ctxopen1","turn_id":"t2","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  if contains "$out" '[oms] context'; then
    fail "a stale context cache must stay silent: $out"
  fi
  # Unadopted repos hold no latch state, so they get no advisory at all.
  local plain="$d/plain"
  make_committed_repo "$plain"
  digest="$(ctx_cache_digest ctxplain1)"
  printf '{"schema":1,"used_percentage":90}\n' > "$hud/ctx-$digest.json"
  out="$(printf '{"prompt":"이 저장소가 뭐야","session_id":"ctxplain1","turn_id":"t1","cwd":"%s"}' "$plain" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  if contains "$out" '[oms] context'; then
    fail "an unadopted repo must not receive the advisory: $out"
  fi
  assert_not_exists "$plain/.oms"
}

test_claude_hud_feeds_context_pressure() {
  local d="$TMP/ctx-pressure-chain"
  local project="$d/project"
  local hud="$d/hud-cache"
  local out digest

  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  # Producer: the status line persists the authoritative reading...
  printf '{"session_id":"ctxchain1","context_window":{"used_percentage":91.4,"total_input_tokens":182800,"context_window_size":200000},"rate_limits":{"seven_day":{"used_percentage":42.2,"resets_at":2000000000}}}' |
    NO_COLOR=1 OMS_HUD_CACHE_DIR="$hud" python3 "$ROOT/scripts/claude-statusline.py" >/dev/null
  digest="$(ctx_cache_digest ctxchain1)"
  [ -f "$hud/ctx-$digest.json" ] || fail "status line must write the context cache"
  grep -Fq '"used_percentage": 91' "$hud/ctx-$digest.json" ||
    fail "context cache must carry the rounded used percentage"
  grep -Fq '"seven_day": {"resets_at": 2000000000.0, "used_percentage": 42}' "$hud/ctx-$digest.json" ||
    fail "the same cache must retain reported weekly usage for the panel"
  # ...consumer: the prompt hook turns it into one advisory line.
  out="$(printf '{"prompt":"계속 진행해줘","session_id":"ctxchain1","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" 'context low (~9% left)' ||
    fail "the status-line cache must feed the prompt-time advisory: $out"
  # A payload without a context reading writes no cache.
  printf '{"session_id":"ctxchain2","context_window":{}}' |
    NO_COLOR=1 OMS_HUD_CACHE_DIR="$hud" python3 "$ROOT/scripts/claude-statusline.py" >/dev/null
  assert_not_exists "$hud/ctx-$(ctx_cache_digest ctxchain2).json"
}

session_digest() {
  python3 -c 'import hashlib, sys; print(hashlib.sha256(sys.argv[1].encode()).hexdigest()[:32])' "$1"
}

# Append one hook-ledger row for $2's session hash, $3 seconds old; any further
# arguments are extra key=value fields (a child row carries action/origin).
write_peer_event() {
  python3 - "$@" <<'PY'
import hashlib, json, sys
from datetime import datetime, timedelta, timezone

row = {"schema": 1, "hook": "PostToolUse", "agent": "test",
       "session": hashlib.sha256(sys.argv[2].encode()).hexdigest()[:32],
       "ts": (datetime.now(timezone.utc) - timedelta(seconds=int(sys.argv[3])))
             .strftime("%Y-%m-%dT%H:%M:%SZ")}
for pair in sys.argv[4:]:
    key, _, value = pair.partition("=")
    row[key] = value
with open(sys.argv[1], "a", encoding="utf-8") as handle:
    handle.write(json.dumps(row, sort_keys=True) + "\n")
PY
}

peer_prompt() {
  local d="$1"
  local project="$2"
  local session="$3"
  local turn="$4"
  shift 4
  printf '{"prompt":"계속 진행해줘","session_id":"%s","turn_id":"%s","cwd":"%s"}' \
    "$session" "$turn" "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$d/no-cache" env "$@" bash "$ROOT/scripts/skill-router.sh"
}

test_peer_advisory_warns_incumbent_once_per_neighbor() {
  local d="$TMP/peer-advisory-warn"
  local project="$d/project"
  local events hud out latch ctx

  make_committed_repo "$project"
  mkdir -p "$project/.oms/hooks" "$d/hud-cache"
  hud="$d/hud-cache"
  events="$project/.oms/hooks/events.jsonl"
  write_peer_event "$events" peer-a 120

  # The incumbent started before the neighbor, so SessionStart never told it.
  out="$(peer_prompt "$d" "$project" incumbent1 t1)"
  contains "$out" '[oms] another session is live in this worktree' ||
    fail "a live neighbor must warn the incumbent: $out"
  assert_file_contains "$events" '"action": "peer_advisory"'
  latch="$project/.oms/hooks/sessions/$(session_digest incumbent1).peers.json"
  assert_file_contains "$latch" "$(session_digest peer-a)"

  # Once per neighbor, not once per prompt.
  out="$(peer_prompt "$d" "$project" incumbent1 t2)"
  if contains "$out" '[oms] another session is live'; then
    fail "an announced neighbor must not warn again: $out"
  fi

  # A second neighbor is news; the first one's latch survives.
  write_peer_event "$events" peer-b 60
  out="$(peer_prompt "$d" "$project" incumbent1 t3)"
  contains "$out" '[oms] another session is live in this worktree' ||
    fail "a newly arrived neighbor must warn: $out"
  assert_file_contains "$latch" "$(session_digest peer-a)"
  assert_file_contains "$latch" "$(session_digest peer-b)"

  # The peer latch lives beside the context-pressure latch, never inside it:
  # ctx.json's writer full-replaces its document.
  printf '{"schema":1,"used_percentage":90}\n' > "$hud/ctx-$(ctx_cache_digest incumbent2).json"
  write_peer_event "$events" peer-c 30
  out="$(printf '{"prompt":"계속 진행해줘","session_id":"incumbent2","turn_id":"t1","cwd":"%s"}' "$project" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$hud" OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/skill-router.sh")"
  contains "$out" 'context low (~10% left)' ||
    fail "the pressure advisory must still fire alongside the peer advisory: $out"
  contains "$out" '[oms] another session is live' ||
    fail "the peer advisory must fire alongside the pressure advisory: $out"
  ctx="$project/.oms/hooks/sessions/$(session_digest incumbent2).ctx.json"
  assert_file_contains "$ctx" '"stage": "warn"'
  assert_file_contains "$project/.oms/hooks/sessions/$(session_digest incumbent2).peers.json" \
    "$(session_digest peer-c)"
}

test_peer_advisory_ignores_children_and_stale_rows() {
  local d="$TMP/peer-advisory-quiet"
  local project="$d/project"
  local plain="$d/plain"
  local events out

  make_committed_repo "$project"
  mkdir -p "$project/.oms/hooks"
  events="$project/.oms/hooks/events.jsonl"

  # The load-bearing filter: this session's own delegated workers write rows
  # under their own session hashes into the primary repo's ledger, so counting
  # them would fire the advisory on every delegation run.
  write_peer_event "$events" child-a 30 action=ignored_child origin=peer-delegate status=route
  write_peer_event "$events" child-b 30 origin=peer-review
  out="$(peer_prompt "$d" "$project" quiet1 t1)"
  if contains "$out" '[oms] another session is live'; then
    fail "harness child rows must not read as a live peer: $out"
  fi
  assert_not_exists "$project/.oms/hooks/sessions/$(session_digest quiet1).peers.json"

  # A neighbor outside the 15-minute window is history, not a live peer. Each
  # case starts from an empty ledger: a routed prompt leaves rows under its own
  # session hash, and the previous case's session is a genuine live peer.
  : > "$events"
  write_peer_event "$events" peer-old 4000
  out="$(peer_prompt "$d" "$project" quiet2 t1)"
  if contains "$out" '[oms] another session is live'; then
    fail "a stale neighbor row must stay silent: $out"
  fi

  # A clean SessionEnd is stronger evidence than an earlier recent activity
  # row. Keeping the ended session "live" causes false shared-tree warnings
  # for the full 15-minute window after every normal shutdown.
  : > "$events"
  write_peer_event "$events" peer-ended 40
  write_peer_event "$events" peer-ended 5 hook=SessionEnd action=telemetry
  out="$(peer_prompt "$d" "$project" quiet-ended t1)"
  if contains "$out" '[oms] another session is live'; then
    fail "a cleanly ended neighbor must stay silent: $out"
  fi

  # Kill switch, with a genuinely live neighbor present.
  : > "$events"
  write_peer_event "$events" peer-live 30
  out="$(peer_prompt "$d" "$project" quiet3 t1 OMS_PEER_ADVISORY=0)"
  if contains "$out" '[oms] another session is live'; then
    fail "OMS_PEER_ADVISORY=0 must silence the advisory: $out"
  fi

  # This session's own rows are not a neighbor.
  : > "$events"
  write_peer_event "$events" quiet4 30
  out="$(peer_prompt "$d" "$project" quiet4 t1)"
  if contains "$out" '[oms] another session is live'; then
    fail "own session rows must not read as a peer: $out"
  fi

  # Unadopted repos hold no ledger and no latch, so they get no advisory. A
  # question keeps the router itself from adopting the repo, so the absent
  # .oms tree is evidence the advisory created nothing.
  make_committed_repo "$plain"
  out="$(printf '{"prompt":"이 저장소가 뭐야","session_id":"quiet5","turn_id":"t1","cwd":"%s"}' "$plain" |
    TMPDIR="$d" OMS_HUD_CACHE_DIR="$d/no-cache" bash "$ROOT/scripts/skill-router.sh")"
  if contains "$out" '[oms] another session is live'; then
    fail "an unadopted repo must not receive the advisory: $out"
  fi
  assert_not_exists "$plain/.oms"
}

test_session_budget_blocks_once_past_the_turn_cap() {
  local d="$TMP/session-budget"
  local project="$d/project"
  local stop_payload out
  make_committed_repo "$project"
  printf '{"prompt":"fix this helper","session_id":"s-budget","turn_id":"t1","cwd":"%s"}' "$project" |
    OMS_SESSION_BUDGET_TURNS=2 TMPDIR="$d" bash "$ROOT/scripts/skill-router.sh" >/dev/null
  stop_payload="$(printf '{"hook_event_name":"Stop","session_id":"s-budget","turn_id":"t1","cwd":"%s","last_assistant_message":"Done."}' "$project")"
  out="$(printf '%s' "$stop_payload" | OMS_SESSION_BUDGET_TURNS=2 OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/turn-guard.sh")"
  [ -z "$out" ] || fail "one turn is inside a two-turn budget: $out"
  out="$(printf '%s' "$stop_payload" | OMS_SESSION_BUDGET_TURNS=2 OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/turn-guard.sh")"
  contains "$out" '[oms] session budget: 2 turns' ||
    fail "the second stop must hit the budget: $out"
  assert_file_contains "$project/.oms/hooks/events.jsonl" '"action": "session_budget"'
  # The continuation Stop after a block, and the same band, stay silent.
  out="$(printf '%s' "${stop_payload%\}},\"stop_hook_active\":true}" | OMS_SESSION_BUDGET_TURNS=2 OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/turn-guard.sh")"
  [ -z "$out" ] || fail "a stop_hook_active continuation must not be blocked again: $out"
  out="$(printf '%s' "$stop_payload" | OMS_SESSION_BUDGET_TURNS=0 OMS_SESSION_BUDGET_HOURS=0 OMS_CTX_CAPTURE=0 bash "$ROOT/scripts/turn-guard.sh")"
  [ -z "$out" ] || fail "a zero budget disables the block: $out"
}

test_turn_guard_allows_routine_dirty_task() {
  local d="$TMP/turn-guard-routine"
  local project="$d/project"
  local route_payload stop_payload out

  make_committed_repo "$project"
  printf 'change\n' >> "$project/file.txt"
  route_payload="$(printf '{"prompt":"fix this helper","session_id":"s-routine","turn_id":"t1","cwd":"%s"}' "$project")"
  printf '%s' "$route_payload" | TMPDIR="$d" bash "$ROOT/scripts/skill-router.sh" >/dev/null
  stop_payload="$(printf '{"hook_event_name":"Stop","session_id":"s-routine","turn_id":"t1","cwd":"%s","last_assistant_message":"Done."}' "$project")"
  out="$(printf '%s' "$stop_payload" | bash "$ROOT/scripts/turn-guard.sh")"
  [ -z "$out" ] || fail "routine dirty task should not be blocked by the turn guard: $out"
}

