test_turn_relay_crosses_between_claude_and_codex() {
  local d="$TMP/turn-relay"
  local project="$d/project"
  local day out stamp key

  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  day="$d/codex/sessions/$(date +%Y/%m/%d)"
  mkdir -p "$day"
  # Assembled at runtime so this source passes the outbound scrubber itself.
  key="$(printf 'to%sen' k)"
  out="$(printf '{"hook_event_name":"Stop","session_id":"relay-c1","cwd":"%s","transcript_path":"%s/.claude/projects/x.jsonl","last_assistant_message":"Patched it. %s=sk-%s"}' "$project" "$d" "$key" abcdefghijklmnopqrstuvwx |
    OMS_CI_TICK=0 OMS_WORK_JOURNAL=0 bash "$ROOT/scripts/turn-guard.sh")"
  [ -z "$out" ] || fail "the relay writer must keep Stop stdout empty: $out"
  assert_file_contains "$project/.oms/hooks/relay/claude.json" "$key=[REDACTED]"

  # Codex dispatches through the plugin, whose SessionStart has no turn_id.
  out="$(printf '{"hook_event_name":"SessionStart","session_id":"relay-k1","cwd":"%s"}' "$project" |
    OMS_HOOK_AGENT=codex OMS_CODEX_HOME="$d/codex" bash "$ROOT/scripts/resume-hook.sh")"
  contains "$out" '[oms relay] claude finished a turn' ||
    fail "a codex session start must see the claude completion: $out"
  out="$(printf '{"prompt":"status?","session_id":"relay-k1","turn_id":"t2","cwd":"%s"}' "$project" |
    OMS_HOOK_AGENT=codex OMS_CODEX_HOME="$d/codex" OMS_HUD_CACHE_DIR="$d/no-cache" bash "$ROOT/scripts/skill-router.sh")"
  if contains "$out" '[oms relay]'; then fail "a completion is shown once per session: $out"; fi

  stamp="$(date -u +%Y-%m-%dT%H:%M:%S.000Z)"
  printf '{"type":"session_meta","payload":{"cwd":"%s","source":{"subagent":{"other":"guardian"}}}}\n{"timestamp":"%s","type":"event_msg","payload":{"type":"task_complete","last_agent_message":"allow"}}\n' "$project" "$stamp" > "$day/rollout-guard.jsonl"
  printf '{"type":"session_meta","payload":{"cwd":"%s","source":"vscode"}}\n{"timestamp":"%s","type":"event_msg","payload":{"type":"task_complete","last_agent_message":"Codex ran the tests."}}\n' "$project/sub" "$stamp" > "$day/rollout-main.jsonl"
  touch "$day/rollout-guard.jsonl"
  out="$(printf '{"hook_event_name":"SessionStart","session_id":"relay-c2","cwd":"%s"}' "$project" |
    OMS_CODEX_HOME="$d/codex" bash "$ROOT/scripts/resume-hook.sh")"
  contains "$out" '[oms relay] codex finished a turn ~0m ago: Codex ran the tests.' ||
    fail "a claude session start must see the codex rollout completion, not a guardian's: $out"
  if contains "$out" 'claude finished'; then fail "an agent never sees its own card: $out"; fi
  out="$(printf '{"hook_event_name":"SessionStart","session_id":"relay-c3","cwd":"%s"}' "$project" |
    OMS_PANEL_MAIN_ATTEMPT=att-main OMS_PANEL_SESSION=oms-relay OMS_CODEX_HOME="$d/codex" bash "$ROOT/scripts/resume-hook.sh")"
  if contains "$out" '[oms relay]'; then fail "a panel main gets no turn relay: $out"; fi
}



test_claude_hud_renders_usage_safely() {
  local hud="$ROOT/scripts/claude-statusline.py"
  local git_repo="$TMP/claude-hud-git"
  local out

  local full_payload='{"model":{"display_name":"Opus 4.1"},"session_name":"release-run","workspace":{"current_dir":"/x/myrepo"},"context_window":{"used_percentage":62.5,"total_input_tokens":124500,"context_window_size":200000},"rate_limits":{"five_hour":{"used_percentage":23.5,"resets_at":1000007100},"seven_day":{"used_percentage":41.2,"resets_at":1000277200}},"cost":{"total_cost_usd":0.1234},"effort":{"level":"high"},"thinking":{"enabled":true}}'
  out="$(printf '%s' "$full_payload" |
    NO_COLOR=1 OMS_HUD_NOW=1000000000 COLUMNS=200 python3 "$hud")"
  [ "$out" = 'Opus 4.1 | release-run | myrepo | $0.12 | high+think | ctx [######----] 63% 125k/200k | 5h 24% (1h58m) | 7d 41% (3d5h)' ] ||
    fail "Claude HUD wide rendering mismatch: $out"

  # A terminal too narrow for one row splits into a balanced identity row
  # and metrics row instead of letting Claude Code clip the numbers.
  out="$(printf '%s' "$full_payload" |
    NO_COLOR=1 OMS_HUD_NOW=1000000000 COLUMNS=80 python3 "$hud")"
  [ "$out" = 'Opus 4.1 | release-run | myrepo | $0.12 | high+think
ctx [######----] 63% 125k/200k | 5h 24% (1h58m) | 7d 41% (3d5h)' ] ||
    fail "Claude HUD narrow rendering mismatch: $out"

  # Without resets_at (older payloads) the usage percentages render bare.
  out="$(printf '%s' '{"model":{"display_name":"Opus 4.1"},"rate_limits":{"five_hour":{"used_percentage":23.5}}}' |
    NO_COLOR=1 python3 "$hud")"
  [ "$out" = 'Opus 4.1 | ctx -- | 5h 24%' ] ||
    fail "Claude HUD reset-less rendering mismatch: $out"

  out="$(printf '%s' '{"model":{},"context_window":{"used_percentage":null,"current_usage":null}}' |
    NO_COLOR=1 python3 "$hud")"
  [ "$out" = 'Claude | ctx --' ] ||
    fail "Claude HUD should handle fields missing before the first response: $out"

  out="$(printf '{broken' | NO_COLOR=1 python3 "$hud")"
  [ -z "$out" ] || fail "Claude HUD should fail quiet on invalid JSON: $out"

  out="$(printf '%s' '{"model":{"display_name":"Bad\u001b[31m\nName"},"context_window":{"used_percentage":101,"total_input_tokens":999999999999,"context_window_size":200000}}' |
    NO_COLOR=1 python3 "$hud")"
  python3 - "$out" <<'PY' || fail "Claude HUD emitted unsafe or unbounded terminal text"
import sys

row = sys.argv[1]
assert "\x1b" not in row and "\n" not in row and "\r" not in row
assert "100%" in row
assert len(row) <= 160
PY

  make_committed_repo "$git_repo"
  git -C "$git_repo" checkout -qb hud-test
  printf 'staged\n' >> "$git_repo/file.txt"
  git -C "$git_repo" add file.txt
  printf 'unstaged\n' >> "$git_repo/file.txt"
  printf 'new\n' > "$git_repo/new.txt"
  out="$(printf '{"model":{},"session_id":"hud-git","workspace":{"current_dir":"%s"},"fast_mode":true,"context_window":{}}' "$git_repo" |
    NO_COLOR=1 COLUMNS=200 OMS_HUD_CACHE_DIR="$TMP/hud-cache" python3 "$hud")"
  [ "$out" = 'Claude | claude-hud-git | fast | git hud-test +1 ~1 ?1 | ctx --' ] ||
    fail "Claude HUD git/fast rendering mismatch: $out"
  # A repo-local core.fsmonitor helper must not run during the status read.
  printf '#!/bin/sh\ntouch "%s/fsmonitor-ran"\n' "$TMP" > "$TMP/fsmonitor-marker"
  chmod +x "$TMP/fsmonitor-marker"
  git -C "$git_repo" config --local core.fsmonitor "$TMP/fsmonitor-marker"
  out="$(printf '{"model":{},"session_id":"hud-fsmon","workspace":{"current_dir":"%s"},"context_window":{}}' "$git_repo" |
    NO_COLOR=1 COLUMNS=200 OMS_HUD_CACHE_DIR="$TMP/hud-cache-fsmon" python3 "$hud")"
  [ ! -e "$TMP/fsmonitor-ran" ] || fail "Claude HUD ran the repo-local core.fsmonitor helper"
  contains "$out" 'git hud-test' || fail "Claude HUD lost the branch segment under core.fsmonitor: $out"
  git -C "$git_repo" config --local --unset core.fsmonitor
  # status must not refresh the index: that write fires post-index-change.
  mkdir "$TMP/hud-hooks"
  printf '#!/bin/sh\ntouch "%s/index-hook-ran"\n' "$TMP" > "$TMP/hud-hooks/post-index-change"
  chmod +x "$TMP/hud-hooks/post-index-change"
  git -C "$git_repo" config --local core.hooksPath "$TMP/hud-hooks"
  python3 -c 'import os, sys, time; t = time.time() + 3600; os.utime(sys.argv[1], (t, t))' "$git_repo/file.txt"
  out="$(printf '{"model":{},"session_id":"hud-idx","workspace":{"current_dir":"%s"},"context_window":{}}' "$git_repo" |
    NO_COLOR=1 COLUMNS=200 OMS_HUD_CACHE_DIR="$TMP/hud-cache-idx" python3 "$hud")"
  [ ! -e "$TMP/index-hook-ran" ] || fail "Claude HUD status wrote the index and fired post-index-change"
  contains "$out" 'git hud-test' || fail "Claude HUD lost the branch segment under core.hooksPath: $out"
  git -C "$git_repo" config --local --unset core.hooksPath
  out="$(printf '{"model":{},"session_id":"hud-git","workspace":{"current_dir":"%s"},"fast_mode":true,"context_window":{}}' "$git_repo" |
    NO_COLOR=1 COLUMNS=40 OMS_HUD_CACHE_DIR="$TMP/hud-cache" python3 "$hud")"
  python3 - "$out" <<'PY' || fail "Claude HUD narrow Git rendering is not bounded: $out"
import sys

lines = sys.argv[1].splitlines()
assert len(lines) == 2 and all(len(line) <= 40 for line in lines), lines
assert "fast" in lines[0] and lines[0].endswith("…"), lines
PY
}

test_claude_subagent_hud_renders_bounded_rows() {
