test_install_claude_hooks_merge_and_remove() {
  local d="$TMP/claude-hooks"
  local s="$d/settings.json"
  local old_path="$PATH"

  mkdir -p "$d/bin"
  cat > "$d/bin/claude" <<'EOF'
#!/bin/sh
printf '%s\n' '  --autocompact <auto|tokens>  Auto-compact window size (100k–1M tokens)'
EOF
  chmod +x "$d/bin/claude"
  PATH="$d/bin:$PATH"
  export PATH
  cat > "$s" <<'EOF'
{"model": "x", "hooks": {"UserPromptSubmit": [{"hooks": [{"type": "command", "command": "echo user-router"}]}]}}
EOF
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" >/dev/null
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" >/dev/null   # idempotent
  python3 - "$s" <<'PY' || fail "merge should add ours once and preserve existing hooks"
import json, sys
d = json.load(open(sys.argv[1]))
ups = d["hooks"]["UserPromptSubmit"]
stop = d["hooks"]["Stop"]
assert len(ups) == 2, ups
assert len(stop) == 1, stop
cmds = [h["command"] for e in ups for h in e["hooks"]]
assert sum("skill-router.sh" in c for c in cmds) == 1
stop_cmds = [h["command"] for e in stop for h in e["hooks"]]
assert sum("turn-guard.sh" in c for c in stop_cmds) == 1
failure = d["hooks"]["PostToolUseFailure"]
assert len(failure) == 1, failure
assert failure[0]["matcher"] == "Bash"
assert "fail-ledger-hook.sh" in failure[0]["hooks"][0]["command"]
assert failure[0]["hooks"][0]["timeout"] == 5
guard = [
    entry for entry in d["hooks"]["PostToolUse"]
    if "syntax-guard-hook.sh" in entry["hooks"][0]["command"]
]
assert len(guard) == 1, d["hooks"]["PostToolUse"]
# The matcher is a tool list; the surface row must survive its own pipes.
assert guard[0]["matcher"] == "Edit|Write|MultiEdit", guard
assert guard[0]["hooks"][0]["timeout"] == 5, guard
assert not any(
    "tier-guard-hook.sh" in h.get("command", "")
    for entries in d["hooks"].values() for entry in entries for h in entry.get("hooks", [])
), d["hooks"]
precompact = d["hooks"]["PreCompact"]
assert len(precompact) == 1, precompact
assert "precompact-handoff.sh" in precompact[0]["hooks"][0]["command"]
assert precompact[0]["hooks"][0]["timeout"] == 30
resume = [
    entry for entry in d["hooks"]["SessionStart"]
    if "resume-hook.sh" in entry["hooks"][0]["command"]
]
assert len(resume) == 1, d["hooks"]["SessionStart"]
assert resume[0]["hooks"][0]["timeout"] == 10
for event in ("SessionStart", "SessionEnd"):
    telemetry = [
        entry for entry in d["hooks"][event]
        if "telemetry-hook.sh" in entry["hooks"][0]["command"]
    ]
    assert len(telemetry) == 1, (event, d["hooks"][event])
    hook = telemetry[0]["hooks"][0]
    assert hook["timeout"] == 5, (event, hook)
assert "SubagentStop" not in d["hooks"], d["hooks"]
notice = d["hooks"]["Notification"]
assert len(notice) == 1 and notice[0]["matcher"] == "permission_prompt|elicitation_dialog", notice
assert "telemetry-hook.sh" in notice[0]["hooks"][0]["command"] and notice[0]["hooks"][0]["timeout"] == 5, notice
assert sum(
    len(entry["hooks"]) for entries in d["hooks"].values() for entry in entries
) == 13 + 1, d["hooks"]  # the thirteen OMS registrations plus the user router
pre = d["hooks"]["PreToolUse"]
assert len(pre) == 2 and all(row["matcher"] == "Bash" for row in pre), pre
assert "git-move-guard-hook.sh" in pre[0]["hooks"][0]["command"] and pre[0]["hooks"][0]["timeout"] == 5, pre
assert "command-guard-hook.sh" in pre[1]["hooks"][0]["command"] and pre[1]["hooks"][0]["timeout"] == 5, pre
assert not any(
    "telemetry-hook.sh" in h.get("command", "")
    for entry in d["hooks"].get("PostToolUse", []) for h in entry.get("hooks", [])
), d["hooks"].get("PostToolUse", [])
assert any("user-router" in c for c in cmds)
assert d["model"] == "x"
status = d["statusLine"]
assert status["type"] == "command"
assert "claude-statusline.py" in status["command"]
subagent = d["subagentStatusLine"]
assert subagent["type"] == "command"
assert "claude-subagent-statusline.py" in subagent["command"]
assert d["modelSettings"] == {"claude-opus-5-5": {"effortLevel": "high", "autoCompactWindow": 300000}}, d["modelSettings"]
assert d["attribution"] == {"commit": "", "pr": "", "sessionUrl": False}, d.get("attribution")
PY
  [ -f "$s.oms-bak" ] || fail "installer should back up settings before the first change"
  cat > "$d/bin/claude" <<'EOF'
#!/bin/sh
printf '%s\n' 'Claude Code without the auto-compact window option'
exit 1
EOF
  chmod +x "$d/bin/claude"
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" --remove >/dev/null
  python3 - "$s" <<'PY' || fail "remove should delete only the oh-my-setting entry"
import json, sys
d = json.load(open(sys.argv[1]))
ups = d["hooks"]["UserPromptSubmit"]
assert len(ups) == 1 and "user-router" in ups[0]["hooks"][0]["command"]
assert "Stop" not in d["hooks"]
assert "PostToolUseFailure" not in d["hooks"]
assert "PreToolUse" not in d["hooks"]
assert "PreCompact" not in d["hooks"]
for event in ("SessionStart", "PostToolUse", "SubagentStop", "SessionEnd"):
    assert event not in d["hooks"], (event, d["hooks"])
assert "statusLine" not in d
assert "subagentStatusLine" not in d
assert "modelSettings" not in d
assert "attribution" not in d
PY
  printf '{}\n' > "$s"
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" >/dev/null
  python3 - "$s" <<'PY' || fail "unsupported Claude CLI must not receive the auto-compact setting"
import json, sys
assert "autoCompactWindow" not in json.load(open(sys.argv[1])).get("modelSettings", {}).get("claude-opus-5-5", {})
PY
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" --remove >/dev/null
  cat > "$d/bin/claude" <<'EOF'
#!/bin/sh
printf '%s\n' '  --autocompact <auto|tokens>  Auto-compact window size (100k–1M tokens)'
EOF
  chmod +x "$d/bin/claude"
  # A status line the user already owns must survive install and remove.
  python3 - "$s" <<'PY'
import json, sys
path = sys.argv[1]
d = json.load(open(path))
d["statusLine"] = {
    "type": "command",
    "command": "python3 /tmp/claude-statusline.py",
}
d["subagentStatusLine"] = {
    "type": "command",
    "command": "python3 /tmp/claude-subagent-statusline.py",
}
d["modelSettings"] = {
    "claude-opus-5-5": {"effortLevel": "medium", "autoCompactWindow": "auto"},
    "claude-opus-5": {"effortLevel": "high"},
}
d["attribution"] = {"commit": "mine", "pr": "", "sessionUrl": True}
json.dump(d, open(path, "w"))
PY
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" >/dev/null
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" --remove >/dev/null
  python3 - "$s" <<'PY' || fail "installer should preserve user-owned status and model settings"
import json, sys
d = json.load(open(sys.argv[1]))
assert d["statusLine"] == {
    "type": "command",
    "command": "python3 /tmp/claude-statusline.py",
}
assert d["subagentStatusLine"] == {
    "type": "command",
    "command": "python3 /tmp/claude-subagent-statusline.py",
}
assert d["modelSettings"] == {
    "claude-opus-5-5": {"effortLevel": "medium", "autoCompactWindow": "auto"},
    "claude-opus-5": {"effortLevel": "high"},
}, d["modelSettings"]
assert d["attribution"] == {"commit": "mine", "pr": "", "sessionUrl": True}, d["attribution"]
PY
  # A user hook sharing an entry with ours keeps that entry, its metadata and
  # its place on remove; a same-named script outside an OMS checkout and a
  # wrapper naming ours are the user's own and survive both directions.
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" >/dev/null
  python3 - "$s" "$d" "$ROOT" <<'PY'
import json, sys
path, d, root = sys.argv[1:]
data = json.load(open(path))
entry = data["hooks"]["Stop"][0]
entry["x-user"] = True
entry["hooks"][:0] = [{"type": "command", "command": "echo user-before"}]
entry["hooks"] += [
    {"type": "command", "command": "bash %s/scripts/turn-guard.sh" % d},
    {"type": "command", "command": "bash %s/wrap.sh %s/scripts/turn-guard.sh" % (d, root)},
]
json.dump(data, open(path, "w"))
PY
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" | grep "already current" > /dev/null ||
    fail "an OMS hook sharing a user entry is already current"
  OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" --remove >/dev/null
  python3 - "$s" "$d" "$ROOT" <<'PY' || fail "remove must keep user siblings, their entry metadata and order"
import json, sys
path, d, root = sys.argv[1:]
stop = json.load(open(path))["hooks"]["Stop"]
assert stop == [{"x-user": True, "hooks": [
    {"type": "command", "command": "echo user-before"},
    {"type": "command", "command": "bash %s/scripts/turn-guard.sh" % d},
    {"type": "command", "command": "bash %s/wrap.sh %s/scripts/turn-guard.sh" % (d, root)},
]}], stop
PY
  # Broken settings must refuse loudly, not clobber.
  printf '{broken' > "$s"
  if OMS_CLAUDE_SETTINGS="$s" "$ROOT/scripts/install-claude-hooks.sh" >/dev/null 2>&1; then
    fail "installer must refuse to touch invalid settings JSON"
  fi
  grep -Fq '{broken' "$s" || fail "installer must not modify a file it refused"
  PATH="$old_path"
  export PATH
}

test_precompact_handoff_captures_adopted_repo() {
  local guard_repo="$TMP/precompact-guard"
  local repo="$TMP/precompact-capture"
  local claude_home="$TMP/precompact-claude-home"
  local project_dir

  mkdir -p "$guard_repo"
  printf '{"session_id":"s1","cwd":"%s"}' "$guard_repo" |
    "$ROOT/scripts/precompact-handoff.sh" ||
    fail "precompact hook must exit 0 without a .oms tree"
  [ ! -d "$guard_repo/.oms" ] || fail "precompact hook must not create .oms"
  printf 'not json' | "$ROOT/scripts/precompact-handoff.sh" ||
    fail "precompact hook must exit 0 on a garbage payload"
  printf '' | "$ROOT/scripts/precompact-handoff.sh" ||
    fail "precompact hook must exit 0 on an empty payload"
  printf '{}' | OMS_PRECOMPACT_HANDOFF=0 "$ROOT/scripts/precompact-handoff.sh" ||
    fail "precompact hook must exit 0 when disabled"

  mkdir -p "$repo/.oms"
  printf '*\n' > "$repo/.oms/.gitignore"
  project_dir="$claude_home/projects/$(printf '%s' "$repo" | sed 's/[^A-Za-z0-9]/-/g')"
  mkdir -p "$project_dir"
  cat > "$project_dir/sess-1.jsonl" <<EOF
{"type":"user","cwd":"$repo","message":{"role":"user","content":"build the widget"}}
{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"Widget built and tested."}]}}
{"type":"user","cwd":"$repo","message":{"role":"user","content":"now wire it to the queue"}}
EOF

  printf '{"session_id":"sess-1","cwd":"%s"}' "$repo" |
    OMS_CLAUDE_HOME="$claude_home" "$ROOT/scripts/precompact-handoff.sh" ||
    fail "precompact hook must exit 0 on capture"
  find "$repo/.oms/handoffs" -name '*.md' 2>/dev/null | grep . > /dev/null ||
    fail "precompact hook should write a handoff digest for an adopted repo"
}

test_precompact_handoff_nested_cwd_uses_adopted_root() {
  local repo="$TMP/precompact-nested"
  local nested="$TMP/precompact-nested/work/child"
  local claude_home="$TMP/precompact-nested-home"
  local shim_bin="$TMP/precompact-python-crlf"
  local real_python
  local project_dir

  if command -v cygpath >/dev/null 2>&1; then
    repo="$(cygpath -m "$repo")"
    nested="$(cygpath -m "$nested")"
    claude_home="$(cygpath -m "$claude_home")"
  fi
  git init -q "$repo"
  mkdir -p "$repo/.oms" "$nested"
  printf '*\n' > "$repo/.oms/.gitignore"
  # The verifier and an open split live at the adopted root, not at the cwd.
  mkdir -p "$repo/.oms/task" "$repo/.oms/artifacts/review"
  printf '# Task\n\n## Verify\n\nbash scripts/check.sh --nested-probe\n\n## Goal\n\nship\n' \
    > "$repo/.oms/task/current.md"
  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$repo/.oms/artifacts/review/codex-x-20260611T000000Z-77.md"
  printf '# claude review\n\n## Output\n\nGATE: fail\n\n## Exit\n\n0\n' \
    > "$repo/.oms/artifacts/review/claude-x-20260611T000000Z-77.md"
  project_dir="$claude_home/projects/$(cd "$nested" && pwd | sed 's/[^A-Za-z0-9]/-/g')"
  mkdir -p "$project_dir"
  cat > "$project_dir/nested-session.jsonl" <<EOF
{"type":"user","cwd":"$nested","message":{"role":"user","content":"inspect the nested module"}}
{"type":"assistant","message":{"role":"assistant","content":"The nested module is ready."}}
{"type":"user","cwd":"$nested","message":{"role":"user","content":"connect it to the service"}}
EOF

  # Simulate Windows Python's CRLF text output for the hook's JSON scalars.
  real_python="$(command -v python3)"
  mkdir -p "$shim_bin"
  cat > "$shim_bin/python3" <<EOF
#!/usr/bin/env bash
case "\$*" in
  *hook_event_name*)
    output="\$("$real_python" "\$@")" || exit \$?
    printf '%s\\n' "\$output" | "$real_python" -c 'import sys; sys.stdout.write(sys.stdin.read().replace("\\r\\n", "\\n").replace("\\n", "\\r\\n"))'
    ;;
  *) exec "$real_python" "\$@" ;;
esac
EOF
  chmod +x "$shim_bin/python3"

  printf '{"session_id":"nested-session","cwd":"%s"}' "$nested" |
    PATH="$shim_bin:$PATH" OMS_CLAUDE_HOME="$claude_home" "$ROOT/scripts/precompact-handoff.sh" ||
    fail "precompact hook must exit 0 for nested cwd"
  local digest
  digest="$(find "$repo/.oms/handoffs" -type f -name '*.md' 2>/dev/null | sed -n '1p')"
  [ -n "$digest" ] ||
    fail "nested cwd should capture the explicit session into the adopted root"
  grep -Fq "inspect the nested module" "$digest" ||
    fail "nested cwd must capture the payload's explicit session"
  grep -Fq "bash scripts/check.sh --nested-probe" "$digest" ||
    fail "nested cwd capture dropped the verifier from the adopted root"
  grep -Fq "## Open dissents" "$digest" ||
    fail "nested cwd capture dropped the open dissents from the adopted root"
  [ ! -e "$nested/.oms" ] ||
    fail "nested cwd must not become a separate handoff destination"
}

test_precompact_handoff_ignores_nested_decoy_oms() {
  local repo="$TMP/precompact-decoy"
  local nested="$TMP/precompact-decoy/work"
  local claude_home="$TMP/precompact-decoy-home"
  local project_dir

  if command -v cygpath >/dev/null 2>&1; then
    repo="$(cygpath -m "$repo")"
    nested="$(cygpath -m "$nested")"
    claude_home="$(cygpath -m "$claude_home")"
  fi
  git init -q "$repo"
  mkdir -p "$nested/.oms"
  project_dir="$claude_home/projects/$(cd "$nested" && pwd | sed 's/[^A-Za-z0-9]/-/g')"
  mkdir -p "$project_dir"
  cat > "$project_dir/decoy-session.jsonl" <<EOF
{"type":"user","cwd":"$nested","message":{"role":"user","content":"this must not be captured under the decoy"}}
{"type":"user","cwd":"$nested","message":{"role":"user","content":"valid second turn for capture"}}
EOF

  printf '{"session_id":"decoy-session","cwd":"%s"}' "$nested" |
    OMS_CLAUDE_HOME="$claude_home" "$ROOT/scripts/precompact-handoff.sh" ||
    fail "precompact hook must fail open for an unadopted repository"
  [ ! -d "$repo/.oms" ] ||
    fail "a nested .oms decoy must not adopt the repository"
  [ -z "$(find "$nested/.oms" -mindepth 1 -print -quit 2>/dev/null)" ] ||
    fail "nested .oms decoy must not receive a handoff or failure ledger"
}

test_precompact_handoff_records_refusal_in_fail_ledger() {
  local repo="$TMP/precompact-refusal"
  local claude_home="$TMP/precompact-refusal-home"
  local project_dir

  git init -q "$repo"
  mkdir -p "$repo/.oms"
  printf '*\n' > "$repo/.oms/.gitignore"
  project_dir="$claude_home/projects/$(printf '%s' "$repo" | sed 's/[^A-Za-z0-9]/-/g')"
  mkdir -p "$project_dir"
  # Secret-tier content forces a capture refusal (split literal keeps this
  # test source scrubber-clean).
  printf '{"type":"user","cwd":"%s","message":{"role":"user","content":"use AK%s"}}\n' \
    "$repo" "IAIOSFODNN7EXAMPLE" > "$project_dir/sess-r.jsonl"

  printf '{"session_id":"sess-r","cwd":"%s"}' "$repo" |
    OMS_CLAUDE_HOME="$claude_home" "$ROOT/scripts/precompact-handoff.sh" ||
    fail "precompact hook must still exit 0 on a refused capture"
  find "$repo/.oms/handoffs" -name '*.md' 2>/dev/null | grep . > /dev/null &&
    fail "refused capture must not write a digest"
  [ -f "$repo/.oms/failures.jsonl" ] ||
    fail "refused capture must be recorded in the fail-ledger"
  grep -q '"kind": "hook"' "$repo/.oms/failures.jsonl" ||
    fail "refusal row must carry kind=hook"
  grep -q 'pre-compact' "$repo/.oms/failures.jsonl" ||
    fail "refusal row must name the pre-compact capture"
}

# smoke-weight: 11
test_resume_hook_prints_bounded_resume_block() {
  local repo="$TMP/resume-hook-repo"
  local crlf_bin="$TMP/resume-hook-crlf-bin"
  local real_python
  local out

  make_committed_repo "$repo"
  mkdir -p "$repo/.oms/handoffs" "$repo/.oms/hooks"
  ( cd "$repo" && "$ROOT/scripts/agent-task.sh" init --goal "Ship the resume surface" \
      --next "wire hooks.json" --verify "bash tests/x.sh" >/dev/null )
  ( cd "$repo" && "$ROOT/scripts/agent-plan.sh" init --goal "Unify the writer contract" \
      --accept true >/dev/null )
  ( cd "$repo" && "$ROOT/scripts/agent-plan.sh" accept >/dev/null ) ||
    fail "plan acceptance should pass"
  ( cd "$repo" && "$ROOT/scripts/agent-plan.sh" init --goal "New contract" \
      --accept "true " >/dev/null )
  plan_status="$("$ROOT/scripts/agent-plan.sh" --repo "$repo" status)" ||
    fail "plan status should succeed after replacing acceptance command"
  printf '%s\n' "$plan_status" | grep -F 'acceptance: not run for this command' > /dev/null ||
    fail "plan status must not report acceptance from the previous command: $plan_status"
  if printf '%s\n' "$plan_status" | grep -F 'acceptance: pass' > /dev/null; then
    fail "plan status reported a pass from the previous acceptance command: $plan_status"
  fi
  printf 'digest\n' > "$repo/.oms/handoffs/claude-abc.md"
  ( cd "$repo" && "$ROOT/scripts/fail-ledger.sh" record --cmd "pytest -k boom" --exit 1 \
      --summary "flaky assertion" --next "rerun standalone" >/dev/null 2>&1 )
  printf '{"session":"peer111","ts":"%s","cwd_hash":"x","hook":"PostToolUse"}\n' \
    "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$repo/.oms/hooks/events.jsonl"

  out="$(printf '{"session_id":"me","cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")" ||
    fail "resume hook must exit 0"
  printf '%s\n' "$out" | grep >/dev/null '^\[oms resume\]' || fail "missing resume header: $out"
  printf '%s\n' "$out" | grep >/dev/null 'Ship the resume surface' || fail "missing task goal"
  printf '%s\n' "$out" | grep >/dev/null 'next: wire hooks.json' || fail "missing next step"
  printf '%s\n' "$out" | grep >/dev/null 'verify: bash tests/x.sh' || fail "missing verify command"
  # The plan contract must survive a compaction the way the task packet does:
  # a live plan was previously completely silent at session start.
  printf '%s\n' "$out" | grep >/dev/null 'plan: New contract' ||
    fail "missing plan goal: $out"
  printf '%s\n' "$out" | grep >/dev/null 'accept: true' ||
    fail "missing plan acceptance: $out"
  printf '%s\n' "$out" | grep >/dev/null 'session-handoff show claude-abc.md' ||
    fail "missing handoff pointer"
  printf '%s\n' "$out" | grep >/dev/null 'failures: 1 actionable' || fail "missing failure line"
  if printf '%s\n' "$out" | grep >/dev/null 'peers:'; then
    fail "resume hook must leave peer warnings to the prompt router: $out"
  fi
  if printf '%s\n' "$out" | grep >/dev/null -F -- '- graph:'; then
    fail "resume hook must leave graph work to an explicit reader: $out"
  fi
  [ "$(printf '%s\n' "$out" | wc -l)" -le 15 ] || fail "resume block exceeds its line budget"
  # Injection ledger: the block is recorded once as byte and line counts, with
  # none of its text, and the relay hint folded into it is not counted twice.
  resume_injection_rows() {  # EVENTS -> "status bytes lines source" per injection row
    python3 - "$1" <<'PYROWS'
import json, sys
for line in open(sys.argv[1], encoding="utf-8"):
    row = json.loads(line)
    if row.get("action") == "injection":
        print(row["status"], row["bytes"], row["lines"], row.get("source", "-"))
PYROWS
  }
  [ "$(resume_injection_rows "$repo/.oms/hooks/events.jsonl")" = \
    "resume $(printf '%s\n' "$out" | wc -c | tr -d '[:space:]') $(printf '%s\n' "$out" | wc -l | tr -d '[:space:]') -" ] ||
    fail "the resume block must leave exactly one injection row with its size: $(resume_injection_rows "$repo/.oms/hooks/events.jsonl")"
  if grep -F -e 'Ship the resume surface' -e 'wire hooks.json' "$repo/.oms/hooks/events.jsonl" >/dev/null; then
    fail "the injection ledger must not carry the injected text"
  fi
  # Compaction survival: a SessionStart with source=compact re-reads the same
  # state lines and adds one routing line; a startup does not, and the whole
  # block stays far below the size at which a provider swaps hook output for a
  # file pointer.
  local compacted started
  compacted="$(printf '{"session_id":"me","cwd":"%s","hook_event_name":"SessionStart","source":"compact"}' "$repo" |
    "$ROOT/scripts/resume-hook.sh")" || fail "resume hook must exit 0 after a compaction"
  started="$(printf '{"session_id":"me","cwd":"%s","hook_event_name":"SessionStart","source":"startup"}' "$repo" |
    "$ROOT/scripts/resume-hook.sh")" || fail "resume hook must exit 0 on startup"
  [ "$(printf '%s\n' "$compacted" | grep -c '^- after compaction: ')" = 1 ] ||
    fail "a compaction SessionStart must carry the routing line once: $compacted"
  contains "$compacted" '/oms-<skill>' || fail "the compaction line must say how OMS skills are invoked"
  if contains "$started" 'after compaction'; then fail "a startup must not claim a compaction: $started"; fi
  [ "$started" = "$out" ] || fail "a startup block must equal the block for a payload without a source"
  [ "$(printf '%s\n' "$compacted" | grep -v '^- after compaction: ')" = "$out" ] ||
    fail "a compaction must re-read the same state lines as a startup"
  [ "$(printf '%s\n' "$compacted" | wc -c)" -lt 4200 ] || fail "the compaction block left its byte cap"
  [ "$(resume_injection_rows "$repo/.oms/hooks/events.jsonl" | sed -n '2p' | cut -d' ' -f1,4)" = "resume compact" ] ||
    fail "the ledger must name the SessionStart source: $(resume_injection_rows "$repo/.oms/hooks/events.jsonl")"
  # A repository with nothing to resume stays silent after a compaction, and leaves no row.
  make_committed_repo "$TMP/resume-hook-empty"
  mkdir -p "$TMP/resume-hook-empty/.oms"
  [ -z "$(printf '{"session_id":"me","cwd":"%s","hook_event_name":"SessionStart","source":"compact"}' \
    "$TMP/resume-hook-empty" | "$ROOT/scripts/resume-hook.sh")" ] || fail "nothing to resume must stay silent after a compaction"
  [ ! -e "$TMP/resume-hook-empty/.oms/hooks/events.jsonl" ] || fail "a silent resume hook must not write a ledger row"
  # The ledger refuses sizes and kinds it cannot vouch for.
  printf '{"session_id":"me","cwd":"%s"}' "$repo" | python3 "$ROOT/scripts/lib/hook_state.py" injected --kind resume --bytes 0
  printf '{"session_id":"me","cwd":"%s"}' "$repo" | python3 "$ROOT/scripts/lib/hook_state.py" injected --kind 'not a kind!' --bytes 12
  printf '{"session_id":"me","cwd":"%s"}' "$repo" | OMS_HARNESS_CHILD=1 python3 "$ROOT/scripts/lib/hook_state.py" injected --kind resume --bytes 12
  [ "$(resume_injection_rows "$repo/.oms/hooks/events.jsonl" | wc -l | tr -d '[:space:]')" = 3 ] ||
    fail "empty, unnamed and harness-child injections must not be recorded: $(resume_injection_rows "$repo/.oms/hooks/events.jsonl")"

  printf '{"cwd":"%s","hook_event_name":"SessionStart","model":"gpt-6","permission_mode":"default","session_id":"codex-session-start","source":"startup","transcript_path":null}' \
    "$repo" > "$TMP/codex-sessionstart-input.json"
  OMS_HOOK_AGENT=codex OMS_CODEX_HOME="$TMP/codex-home" OMS_LOCK_DIR="$TMP/locks" \
    bash "$ROOT/scripts/resume-hook.sh" < "$TMP/codex-sessionstart-input.json" \
    > "$TMP/codex-sessionstart-expected.txt" || fail "resume hook must accept Codex SessionStart input"
  CLAUDE_PLUGIN_ROOT="$ROOT/plugins/oh-my-setting" \
    OMS_CODEX_HOME="$TMP/codex-home" OMS_LOCK_DIR="$TMP/locks" \
    bash "$ROOT/plugins/oh-my-setting/scripts/harness-hook.sh" resume-hook \
    < "$TMP/codex-sessionstart-input.json" > "$TMP/codex-sessionstart-output.json" ||
    fail "Codex plugin SessionStart hook must exit 0"
  if ! python3 - "$TMP/codex-sessionstart-output.json" "$TMP/codex-sessionstart-expected.txt" <<'PY'
import json, pathlib, sys

actual = json.loads(pathlib.Path(sys.argv[1]).read_text(encoding="utf-8"))
expected = pathlib.Path(sys.argv[2]).read_text(encoding="utf-8")
assert actual == {"hookSpecificOutput": {
    "hookEventName": "SessionStart",
    "additionalContext": expected,
}}, actual
PY
  then
    fail "Codex SessionStart output must use the exact hookSpecificOutput shape"
  fi
  OMS_RESUME_HOOK=0 CLAUDE_PLUGIN_ROOT="$ROOT/plugins/oh-my-setting" \
    bash "$ROOT/plugins/oh-my-setting/scripts/harness-hook.sh" resume-hook \
    < "$TMP/codex-sessionstart-input.json" > "$TMP/codex-sessionstart-silent.txt" ||
    fail "a disabled Codex SessionStart hook must exit 0"
  [ ! -s "$TMP/codex-sessionstart-silent.txt" ] ||
    fail "a silent Codex SessionStart hook must not emit empty JSON"

  mkdir -p "$repo/src/nested"
  out="$(printf '{"cwd":"%s/src/nested"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
  contains "$out" 'Ship the resume surface' || fail "nested cwd lost the active task"
  [ ! -e "$repo/src/nested/.oms" ] || fail "resume created nested state"
  mkdir -p "$repo/src/nested/.oms"
  out="$(printf '{"cwd":"%s/src/nested"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
  contains "$out" 'Ship the resume surface' || fail "nested state shadowed the repository root"

  # Exercise terminal plan states and a read-only land status through a fake root.
  cp "$repo/.oms/plan/tasks.json" "$TMP/resume-plan-original.json"
  local states expected fake_root="$TMP/resume-fake-root" status_file="$TMP/resume-land.json"
  for states in cancelled done,cancelled done,ready ''; do
    python3 - "$repo/.oms/plan/tasks.json" "$states" <<'PYPLAN'
import json, sys
states = sys.argv[2].split(',') if sys.argv[2] else []
with open(sys.argv[1], 'w') as f:
    json.dump({'goal': 'Plan fixture', 'accept': 'true',
               'tasks': {str(i): {'state': state} for i, state in enumerate(states)}}, f)
PYPLAN
    out="$(printf '{"cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
    case "$states" in
      cancelled|done,cancelled) if contains "$out" 'plan: Plan fixture'; then
          fail "closed plan must stay silent: $states"; fi ;;
      *) contains "$out" 'plan: Plan fixture' || fail "open or empty plan disappeared: $states" ;;
    esac
  done
  cp "$TMP/resume-plan-original.json" "$repo/.oms/plan/tasks.json"
  mkdir -p "$fake_root/scripts"
  for script in agent-task.sh fail-ledger.sh auto-update.sh; do
    ln -s "$ROOT/scripts/$script" "$fake_root/scripts/$script"
  done
  ln -s "$ROOT/scripts/lib" "$fake_root/scripts/lib"
  cp "$ROOT/scripts/resume-hook.sh" "$fake_root/scripts/resume-hook.sh"
  cat > "$fake_root/scripts/land.sh" <<'EOFLAND'
#!/usr/bin/env bash
[ "$1" = status ] && [ "$2" = --repo ] && [ "$4" = --json ] && [ "$5" = --active-exit ] || exit 1
cat "$OMS_TEST_LAND_STATUS" || exit 1
exit 3
EOFLAND
  chmod -x "$fake_root/scripts/land.sh"
  for expected in running passed failed interrupted missing ''; do
    python3 - "$status_file" "$expected" <<'PYSTATE'
import json, sys
row = {'active': True, 'sha': '1234567', 'gate': {'rc': 'stale'}}
if sys.argv[2] != 'missing':
    row['state'] = sys.argv[2]
with open(sys.argv[1], 'w') as output:
    json.dump(row, output)
PYSTATE
    out="$(printf '{"cwd":"%s"}' "$repo" | PATH="/usr/bin:/bin" OMS_TEST_LAND_STATUS="$status_file" bash "$fake_root/scripts/resume-hook.sh")"
    land_lines="$(printf '%s\n' "$out" | grep '^- land ' || true)"
    [ "$land_lines" = '- land lock held (possibly another worktree); oms land status' ] ||
      fail "incorrect lock status for $expected: $land_lines"
  done
  printf '%s\n' '{"active":true}' > "$status_file"
  out="$(printf '{"cwd":"%s"}' "$repo" | OMS_TEST_LAND_STATUS="$status_file" bash "$fake_root/scripts/resume-hook.sh")"
  contains "$out" 'land lock held (possibly another worktree); oms land status' || fail "missing receipt hid held lock"
  for expected in false null 0 malformed empty failure; do
    case "$expected" in
      false|null|0) printf '{"active":%s,"state":"running"}\n' "$expected" > "$status_file" ;;
      malformed) printf '{bad\n' > "$status_file" ;;
      empty) : > "$status_file" ;;
      failure) rm -f "$status_file" ;;
    esac
    out="$(printf '{"cwd":"%s"}' "$repo" | OMS_TEST_LAND_STATUS="$status_file" bash "$fake_root/scripts/resume-hook.sh")" ||
      fail "land probe failure broke resume"
    if contains "$out" '- land '; then fail "inactive or invalid land appeared: $expected"; fi
  done
  cat > "$fake_root/scripts/land.sh" <<'EOFTIMEOUT'
#!/usr/bin/env bash
exec python3 -c 'import time; time.sleep(10)'
EOFTIMEOUT
  chmod +x "$fake_root/scripts/land.sh"
  out="$(printf '{"cwd":"%s"}' "$repo" | bash "$fake_root/scripts/resume-hook.sh")" || fail "land timeout broke resume"
  if contains "$out" '- land '; then fail "timed out land appeared"; fi
  rm -f "$fake_root/scripts/land.sh"
  out="$(printf '{"cwd":"%s"}' "$repo" | bash "$fake_root/scripts/resume-hook.sh")" || fail "missing land broke resume"
  if contains "$out" '- land '; then fail "missing land appeared"; fi

  # Native Windows Python writes CRLF to a pipe. Every value read back into
  # Bash must lose the CR before it participates in path checks or output.
  real_python="$(command -v python3)"
  mkdir -p "$crlf_bin"
  cat > "$crlf_bin/python3" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
"$OMS_TEST_REAL_PYTHON" "$@" | sed 's/$/\r/'
EOF
  chmod +x "$crlf_bin/python3"
  out="$(printf '{"session_id":"me","cwd":"%s"}' "$repo" |
    PATH="$crlf_bin:/usr/bin:/bin" OMS_TEST_REAL_PYTHON="$real_python" \
      "$ROOT/scripts/resume-hook.sh")" ||
    fail "CRLF resume hook must exit 0"
  printf '%s\n' "$out" | grep >/dev/null 'plan: New contract' ||
    fail "CRLF Python output hid the active plan: $out"
  case "$out" in
    *$'\r'*) fail "resume block retained a carriage return" ;;
  esac

  # A resolved failure leaves the count — the event name is "resolved", which
  # a prior version of this hook misread and counted forever.
  ( cd "$repo" && "$ROOT/scripts/fail-ledger.sh" resolve --cmd "pytest -k boom" >/dev/null 2>&1 )
  out="$(printf '{"session_id":"me","cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
  if printf '%s\n' "$out" | grep >/dev/null 'failures:'; then
    fail "a resolved failure must drop out of the resume count: $out"
  fi

  # A malformed autopilot receipt must never break session start: the
  # shadow observation is best-effort and stays silent when the receipt
  # refuses to load (the refusal is the receipt's problem, not the hook's).
  mkdir -p "$repo/.oms/plan"
  printf 'not json\n' > "$repo/.oms/plan/autopilot-run.json"
  out="$(printf '{"session_id":"me","cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")" ||
    fail "resume hook must exit 0 with a malformed receipt"
  if printf '%s\n' "$out" | grep >/dev/null 'autopilot:'; then
    fail "a malformed receipt must not produce an autopilot line: $out"
  fi
  rm -f "$repo/.oms/plan/autopilot-run.json"

  # Shared memory rides the block only on request (OMS_RESUME_MEMORY=1). Off,
  # or on with nothing written yet, the block is byte-for-byte what it was.
  local plain memory section pins_file="$repo/.oms/memory/pins.md"
  plain="$(printf '{"cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
  memory="$(printf '{"cwd":"%s"}' "$repo" | OMS_RESUME_MEMORY=1 "$ROOT/scripts/resume-hook.sh")" ||
    fail "resume hook with memory must exit 0"
  [ "$memory" = "$plain" ] || fail "empty memory must add nothing to the resume block: $memory"
  "$ROOT/scripts/agent-memory.sh" --repo "$repo" pin --agent codex --text "Hook rows are pipe-delimited." >/dev/null 2>&1 ||
    fail "pinning a resume fixture note failed"
  "$ROOT/scripts/agent-memory.sh" --repo "$repo" append --agent claude \
    --text "The resume surface must stay under the hook byte cap." >/dev/null 2>&1 ||
    fail "appending a resume fixture note failed"
  "$ROOT/scripts/agent-memory.sh" --repo "$repo" append --agent codex \
    --text "Ship the surface behind the plugin wrapper as well." >/dev/null 2>&1
  "$ROOT/scripts/agent-memory.sh" --repo "$repo" append --agent claude --text "Unrelated tmux binding note." >/dev/null 2>&1
  out="$(printf '{"cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
  [ "$out" = "$plain" ] || fail "memory must stay out of the resume block unless asked for: $out"
  memory="$(printf '{"cwd":"%s"}' "$repo" | OMS_RESUME_MEMORY=1 "$ROOT/scripts/resume-hook.sh")"
  contains "$memory" '- memory (reference only; not approval or verification evidence):' ||
    fail "resume memory section missing its reference-only label: $memory"
  printf '%s\n' "$memory" | grep -E >/dev/null '^  pin mem-[^ ]+: Hook rows are pipe-delimited\.$' ||
    fail "resume memory missing the pin with its event id: $memory"
  printf '%s\n' "$memory" | grep -E >/dev/null '^  recall mem-[^ ]+: The resume surface must stay under the hook byte cap\.$' ||
    fail "resume memory missing the note ranked for the task goal: $memory"
  printf '%s\n' "$memory" | grep -E >/dev/null '^  recall mem-[^ ]+: Ship the surface behind the plugin wrapper as well\.$' ||
    fail "resume memory must give each ranked note as its text alone: $memory"
  if contains "$memory" 'tmux binding'; then fail "resume memory recalled a note unrelated to the goal: $memory"; fi
  contains "$memory" '  more: oms agent-memory recall QUERY' || fail "resume memory missing its pointer: $memory"
  # The section is the block's tail, before the footer: everything above it is unchanged.
  [ "${memory%%- memory (reference only*}" = "${plain%- more: oms state}" ] ||
    fail "memory must be appended after the existing resume lines: $memory"
  # The same section reaches Codex through the plugin's SessionStart wrapper.
  OMS_RESUME_MEMORY=1 CLAUDE_PLUGIN_ROOT="$ROOT/plugins/oh-my-setting" \
    OMS_CODEX_HOME="$TMP/codex-home" OMS_LOCK_DIR="$TMP/locks" \
    bash "$ROOT/plugins/oh-my-setting/scripts/harness-hook.sh" resume-hook \
    < "$TMP/codex-sessionstart-input.json" > "$TMP/codex-sessionstart-memory.json" ||
    fail "Codex SessionStart hook with memory must exit 0"
  grep -Fq 'Hook rows are pipe-delimited.' "$TMP/codex-sessionstart-memory.json" ||
    fail "Codex SessionStart context lost the memory section"

  # Citation metadata, matching pins and failures must not displace shared notes.
  "$ROOT/scripts/agent-memory.sh" --repo "$repo" append --agent codex \
    --source-file "$(git -C "$repo" ls-files | head -n 1)" --source-line 1 --text "resume surface cited fixture" >/dev/null 2>&1 ||
    fail "cited memory fixture failed"
  printf '%s\n' '- 2026-01-01T00:00:00Z [codex] resume surface legacy pin fixture' >> "$pins_file"
  "$ROOT/scripts/agent-memory.sh" --repo "$repo" pin --agent codex --text "resume surface matching pin one" >/dev/null 2>&1
  "$ROOT/scripts/agent-memory.sh" --repo "$repo" pin --agent codex --text "resume surface matching pin two" >/dev/null 2>&1
  ( cd "$repo" && "$ROOT/scripts/fail-ledger.sh" record --cmd "resume surface fixture" --exit 1 \
      --summary "resume surface failure fixture" --next "retry" >/dev/null 2>&1 &&
    "$ROOT/scripts/fail-ledger.sh" resolve --cmd "resume surface fixture" >/dev/null 2>&1 ) ||
    fail "failure ledger fixture failed"
  memory="$(printf '{"cwd":"%s"}' "$repo" | OMS_RESUME_MEMORY=1 "$ROOT/scripts/resume-hook.sh")"
  printf '%s\n' "$memory" | grep -E >/dev/null '^  pin legacy:pins:[^ ]+: resume surface legacy pin fixture$' ||
    fail "legacy pin must retain its stable event id: $memory"
  if printf '%s\n' "$memory" | grep -E >/dev/null '^  recall (legacy:pins:|fail:)|^  recall .*\[source:'; then
    fail "recall must contain shared note bodies only: $memory"
  fi
  contains "$memory" 'resume surface cited fixture' || fail "cited shared note missing: $memory"
  contains "$memory" 'The resume surface must stay under the hook byte cap.' ||
    fail "matching pins must not starve shared notes: $memory"

  # Bounded: the newest three pins, each cut to one short line, and the whole
  # section under its byte cap however much was pinned.
  local pin
  for pin in 1 2 3 4; do
    OMS_AGENT_MEMORY_PIN_CHARS=900 "$ROOT/scripts/agent-memory.sh" --repo "$repo" pin --agent codex \
      --text "pin-$pin $(printf 'word%.0s ' {1..150})tail-$pin" >/dev/null 2>&1 || fail "pinning long note $pin failed"
  done
  memory="$(printf '{"cwd":"%s"}' "$repo" | OMS_RESUME_MEMORY=1 "$ROOT/scripts/resume-hook.sh")"
  section="$(printf '%s\n' "$memory" | sed -n '/^- memory (reference only/,/^  more: oms agent-memory/p')"
  [ "$(printf '%s\n' "$section" | grep -c '^  pin ')" = 3 ] || fail "resume memory must show three pins: $section"
  contains "$section" ': pin-4 word' && contains "$section" ': pin-2 word' ||
    fail "resume memory must show the newest pins: $section"
  if contains "$section" 'pin-1 word' || contains "$section" 'Hook rows' || contains "$section" 'tail-'; then
    fail "resume memory kept an older or uncut pin: $section"
  fi
  [ "$(printf '%s\n' "$section" | wc -c)" -le 1200 ] || fail "resume memory section exceeds its byte cap"
  [ "$(printf '%s' "$memory" | wc -c)" -le 4096 ] || fail "resume block with memory exceeds its byte cap"

  # What the memory layer withholds from provider context is withheld here: a
  # pins file that looks sensitive contributes nothing, and the block survives.
  cp "$pins_file" "$TMP/resume-pins.bak"
  printf -- '- 2026-01-01T00:00:00Z [codex] deploy with API_TOK''EN=abcd1234abcd1234abcd\n' >> "$pins_file"
  memory="$(printf '{"cwd":"%s"}' "$repo" | OMS_RESUME_MEMORY=1 "$ROOT/scripts/resume-hook.sh")" ||
    fail "a withheld pins file broke resume"
  if contains "$memory" 'abcd1234' || printf '%s\n' "$memory" | grep >/dev/null '^  pin '; then
    fail "a sensitive-looking pins file reached the resume block: $memory"
  fi
  if contains "$memory" 'matching pin' || contains "$memory" 'legacy pin fixture'; then
    fail "withheld pins must not reappear through recall: $memory"
  fi
  contains "$memory" 'resume surface cited fixture' || fail "withheld pins hid clean shared notes: $memory"
  contains "$memory" 'Ship the resume surface' || fail "a withheld pins file hid the active task"
  cp "$TMP/resume-pins.bak" "$pins_file"

  # A memory lookup that hangs is dropped at its bound; the block is unchanged.
  # Only the hook's own lookup stalls: every other reader gets the real library.
  local slow_root="$TMP/resume-slow-root" entry
  mkdir -p "$slow_root/scripts/lib"
  for entry in agent-task.sh fail-ledger.sh auto-update.sh; do
    ln -s "$ROOT/scripts/$entry" "$slow_root/scripts/$entry"
  done
  cp "$ROOT/scripts/resume-hook.sh" "$slow_root/scripts/resume-hook.sh"
  for entry in "$ROOT"/scripts/lib/*; do ln -s "$entry" "$slow_root/scripts/lib/${entry##*/}"; done
  rm -f "$slow_root/scripts/lib/agent-memory-common.sh"
  printf '[ "$0" != oms-resume-memory ] || sleep 30\n. "%s/scripts/lib/agent-memory-common.sh"\n' "$ROOT" \
    > "$slow_root/scripts/lib/agent-memory-common.sh"
  plain="$(printf '{"cwd":"%s"}' "$repo" | bash "$slow_root/scripts/resume-hook.sh")"
  memory="$(printf '{"cwd":"%s"}' "$repo" | OMS_RESUME_MEMORY=1 bash "$slow_root/scripts/resume-hook.sh")" ||
    fail "a hung memory lookup broke resume"
  [ "$memory" = "$plain" ] && contains "$memory" 'Ship the resume surface' ||
    fail "a hung memory lookup must leave the resume block unchanged: $memory"

  # Outside an adopted repo, and when disabled: exit 0 with no output.
  out="$(printf '{"session_id":"me","cwd":"%s"}' "$TMP" | "$ROOT/scripts/resume-hook.sh")" ||
    fail "resume hook must exit 0 outside an adopted repo"
  [ -z "$out" ] || fail "non-adopted dir must stay silent"
  # A disabled hook exits before reading stdin; a pipe producer can get SIGPIPE.
  out="$(OMS_RESUME_HOOK=0 "$ROOT/scripts/resume-hook.sh" < "$TMP/codex-sessionstart-input.json")" ||
    fail "disabled resume hook must exit 0"
  [ -z "$out" ] || fail "OMS_RESUME_HOOK=0 must disable the hook"

  # A newer unrelated session must not displace this task's handoff.
  python3 - "$repo" <<'PY'
import hashlib, os, pathlib, re, subprocess, sys, time
repo = pathlib.Path(sys.argv[1])
raw = (repo / '.oms/task/current.md').read_bytes()
task_id = re.search(rb'^- task_id: (.+)$', raw, re.M).group(1).decode()
head = subprocess.check_output(['git', '-C', str(repo), 'rev-parse', 'HEAD'], text=True).strip()
path = repo / '.oms/handoffs/matching.md'
path.write_text('- task_id: %s\n- head: %s\n- task_digest: %s\n' % (task_id, head, hashlib.sha256(raw).hexdigest()))
os.utime(path, (time.time() - 600, time.time() - 600))
(repo / '.oms/handoffs/unrelated.md').write_text('- task_id: different\n')
PY
  out="$(printf '{"cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
  contains "$out" 'current task snapshot' || fail "matching handoff was not recognized"
  contains "$out" 'show matching.md' || fail "newer unrelated handoff displaced the active task"
  (cd "$repo" && "$ROOT/scripts/agent-task.sh" update --next "changed next action" >/dev/null)
  out="$(printf '{"cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
  contains "$out" 'same task, recheck changed state' || fail "changed packet was treated as current"
  (cd "$repo" && "$ROOT/scripts/agent-task.sh" update --goal "$(python3 -c 'print("긴목표" * 2000)')" --replace-goal "bounded-display fixture" >/dev/null)
  out="$(printf '{"cwd":"%s"}' "$repo" | "$ROOT/scripts/resume-hook.sh")"
  [ "$(printf '%s' "$out" | wc -c)" -le 4096 ] || fail "resume byte budget exceeded"
  contains "$out" 'resume truncated' || fail "resume truncation was hidden"
  printf '%s' "$out" | python3 -c 'import sys; sys.stdin.buffer.read().decode("utf-8")' || fail "resume split a UTF-8 character"
}

test_install_codex_plugin_registers_marketplace() {
  local d="$TMP/codex-plugin"
  local bin="$d/bin"
  local log="$d/codex.log"
  local codex_home="$d/codex-home"
  local status out

  mkdir -p "$bin" "$codex_home"
  cat > "$codex_home/config.toml" <<'EOF'
[tui]
animations = true
EOF
  cat > "$bin/codex" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$CODEX_LOG"
if [ "$1 $2" = "features list" ]; then
  # Like the real CLI, loading config.toml is what can fail here.
  [ "${OMS_TEST_CODEX_REJECTS_USAGE:-0}" != 1 ] ||
    ! grep -q '^min_wait_timeout_ms' "$CODEX_HOME/config.toml" || exit 1
  exit 0
fi
if [ "$1 $2 $3" = "plugin marketplace list" ]; then
  [ "${OMS_TEST_CODEX_LOOKUP_FAIL:-}" != marketplace ] || exit 24
  if [ -f "$CODEX_HOME/.test-marketplace-installed" ]; then
    printf 'oh-my-setting-local %s\n' "$OMS_TEST_MARKETPLACE_ROOT"
  fi
  exit 0
fi
case "$1 $2" in
  "plugin list")
    [ "${OMS_TEST_CODEX_LOOKUP_FAIL:-}" != plugin ] || exit 24
    if [ -f "$CODEX_HOME/.test-plugin-installed" ]; then
      printf '%s\n' '{"installed":[{"pluginId":"oh-my-setting@oh-my-setting-local","installed":true}]}'
    else
      printf '%s\n' '{"installed":[]}'
    fi
    ;;
  "plugin add")
    touch "$CODEX_HOME/.test-plugin-installed"
    ;;
  "plugin remove")
    [ "${OMS_TEST_CODEX_REMOVE_FAIL:-0}" != 1 ] || exit 23
    [ -f "$CODEX_HOME/.test-plugin-installed" ] || exit 25
    rm -f "$CODEX_HOME/.test-plugin-installed"
    ;;
esac
case "$1 $2 $3" in
  "plugin marketplace add")
    touch "$CODEX_HOME/.test-marketplace-installed"
    ;;
  "plugin marketplace remove")
    [ -f "$CODEX_HOME/.test-marketplace-installed" ] || exit 25
    # The real CLI rewrites config.toml and drops comments above the table it
    # removes; a managed block must already be gone by then.
    ! grep -q 'oh-my-setting managed Codex' "$CODEX_HOME/config.toml" 2>/dev/null ||
      echo "markers-present-at-marketplace-remove" >> "$CODEX_LOG"
    rm -f "$CODEX_HOME/.test-marketplace-installed"
    ;;
esac
exit 0
EOF
  chmod +x "$bin/codex"

  # Wait floors are cross-validated, and a config Codex rejects stops every
  # session: a codex that cannot load them must get its config back, and an
  # optimization it refuses must not fail the plugin install.
  printf '[tui]\nanimations = true\n\n[features.multi_agent_v2]\nenabled = true\n' \
    > "$codex_home/config.toml"
  out="$(CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    OMS_TEST_CODEX_REJECTS_USAGE=1 PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/install-codex-plugin.sh" 2>&1)" ||
    fail "rejected usage keys must not fail the Codex plugin install: $out"
  contains "$out" 'codex-usage: rolled back' ||
    fail "installer should roll back usage keys this codex rejects: $out"
  if grep -Eq 'min_wait_timeout_ms|background_terminal_max_timeout' "$codex_home/config.toml"; then
    fail "rolled-back usage keys are still in the Codex config"
  fi
  assert_file_contains "$codex_home/config.toml" 'enabled = true'
  # The same config on a codex that accepts it keeps the floors.
  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/install-codex-plugin.sh" >/dev/null
  assert_file_contains "$codex_home/config.toml" 'min_wait_timeout_ms = 120000'
  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/install-codex-plugin.sh" --remove >/dev/null
  printf 'developer_instructions = "Keep my delegation policy."\n[tui]\nanimations = true\n' > "$codex_home/config.toml"
  rm -f "$codex_home/config.toml.oms-bak"
  : > "$log"

  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/install-codex-plugin.sh" >/dev/null
  assert_file_contains "$log" "plugin marketplace list"
  # Writing only the root ceiling is an ordinary install: no provider probe.
  if grep -Fq 'features list' "$log"; then
    fail "an ordinary Codex install must not pay a config-load probe"
  fi
  assert_file_contains "$log" "plugin marketplace add $ROOT"
  assert_file_contains "$log" "plugin add oh-my-setting@oh-my-setting-local"
  assert_file_contains "$codex_home/config.toml" '# >>> oh-my-setting managed Codex HUD >>>'
  assert_file_contains "$codex_home/config.toml" 'status_line = ["model-with-reasoning", "context-remaining", "five-hour-limit", "weekly-limit", "git-branch"]'
  assert_file_contains "$codex_home/config.toml.oms-bak" 'animations = true'
  python3 - "$codex_home/config.toml" <<'PY' || fail "Codex HUD config should remain valid TOML"
import sys
try:
    import tomllib
except ImportError:
    sys.exit(0)
with open(sys.argv[1], "rb") as fh:
    row = tomllib.load(fh)
assert row["tui"]["animations"] is True
assert row["tui"]["status_line"][-1] == "git-branch"
# A root key written after [tui] would become tui.background_terminal_...
assert row["background_terminal_max_timeout"] == 900000
assert "background_terminal_max_timeout" not in row["tui"]
assert row["developer_instructions"] == "Keep my delegation policy."
# Codex runs notify from its daemon's environment: both paths are absolute.
assert row["notify"][0].startswith("/") and row["notify"][1].endswith("/scripts/lib/codex_turn_notify.py"), row["notify"]
PY

  cp "$codex_home/config.toml" "$d/config-installed.toml"
  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/install-codex-plugin.sh" >/dev/null
  cmp -s "$d/config-installed.toml" "$codex_home/config.toml" ||
    fail "Codex reinstall changed existing settings"

  : > "$log"
  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/install-codex-plugin.sh" --remove >/dev/null
  assert_file_contains "$log" "plugin remove oh-my-setting@oh-my-setting-local"
  assert_file_contains "$log" "plugin marketplace remove oh-my-setting-local"
  if grep -Fq 'status_line' "$codex_home/config.toml"; then
    fail "Codex plugin removal left the managed HUD"
  fi
  if grep -Fq 'background_terminal_max_timeout' "$codex_home/config.toml"; then
    fail "Codex plugin removal left the managed usage key"
  fi
  if grep -Fq 'codex_turn_notify' "$codex_home/config.toml"; then
    fail "Codex plugin removal left the managed turn notifier"
  fi
  assert_file_contains "$codex_home/config.toml" 'animations = true'
  assert_file_contains "$codex_home/config.toml" 'developer_instructions = "Keep my delegation policy."'

  cat > "$codex_home/config.toml" <<'EOF'
[tui]
status_line = ["model", "current-dir"]
EOF
  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/install-codex-plugin.sh" >/dev/null
  assert_file_contains "$codex_home/config.toml" 'status_line = ["model", "current-dir"]'
  if grep -Fq 'oh-my-setting managed Codex HUD' "$codex_home/config.toml"; then
    fail "Codex installer should preserve a user-owned status line"
  fi
  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" \
    "$ROOT/scripts/install-codex-plugin.sh" --remove >/dev/null
  assert_file_contains "$codex_home/config.toml" 'status_line = ["model", "current-dir"]'

  cat > "$codex_home/config.toml" <<'EOF'
[tui]
# >>> oh-my-setting managed Codex HUD >>>
status_line = ["model-with-reasoning", "context-remaining", "five-hour-limit", "weekly-limit", "git-branch"]
# <<< oh-my-setting managed Codex HUD <<<
EOF
  touch "$codex_home/.test-plugin-installed" "$codex_home/.test-marketplace-installed"
  : > "$log"
  status=0
  out="$(CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" OMS_TEST_CODEX_REMOVE_FAIL=1 \
    "$ROOT/scripts/install-codex-plugin.sh" --remove 2>&1)" || status=$?
  [ "$status" -ne 0 ] || fail "Codex plugin removal failure was reported as success"
  assert_file_contains "$log" "plugin remove oh-my-setting@oh-my-setting-local"
  assert_file_contains "$log" "plugin marketplace remove oh-my-setting-local"
  if grep -Fq 'oh-my-setting managed Codex HUD' "$codex_home/config.toml"; then
    fail "Codex plugin failure prevented independent managed HUD cleanup"
  fi
  if contains "$out" 'codex-plugin: removed'; then
    fail "Codex plugin removal printed false success"
  fi

  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/install-codex-plugin.sh" --remove >/dev/null ||
    fail "Codex plugin removal could not recover after a partial failure"
  ! grep -Fq markers-present-at-marketplace-remove "$log" ||
    fail "managed Codex blocks outlived the CLI rewrite that drops their markers"
  : > "$log"
  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/install-codex-plugin.sh" --remove >/dev/null ||
    fail "already-absent Codex plugin removal should be idempotent"
  if grep -Eq '^plugin (remove|marketplace remove)' "$log"; then
    fail "already-absent Codex plugin removal invoked a destructive command"
  fi

  touch "$codex_home/.test-plugin-installed" "$codex_home/.test-marketplace-installed"
  : > "$log"
  status=0
  out="$(CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" OMS_TEST_CODEX_LOOKUP_FAIL=plugin \
    "$ROOT/scripts/install-codex-plugin.sh" --remove 2>&1)" || status=$?
  [ "$status" -ne 0 ] || fail "Codex plugin state lookup failure was ignored"
  [ -f "$codex_home/.test-plugin-installed" ] ||
    fail "Codex plugin lookup failure mutated the plugin"
  assert_file_contains "$log" "plugin marketplace remove oh-my-setting-local"
  CODEX_HOME="$codex_home" CODEX_LOG="$log" OMS_TEST_MARKETPLACE_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/install-codex-plugin.sh" --remove >/dev/null ||
    fail "Codex removal could not recover after a state lookup failure"

  # Without the CLI, a config holding our marketplace still fails removal; one
  # holding no plugin or marketplace entry of ours has nothing left to remove.
  for held in 1 0; do
    cat > "$codex_home/config.toml" <<'EOF'
[tui]
# >>> oh-my-setting managed Codex HUD >>>
status_line = ["model-with-reasoning", "context-remaining", "five-hour-limit", "weekly-limit", "git-branch"]
# <<< oh-my-setting managed Codex HUD <<<
EOF
    [ "$held" = 0 ] || printf '\n[marketplaces.oh-my-setting-local]\nsource = "x"\n' >> "$codex_home/config.toml"
    status=0
    out="$(CODEX_HOME="$codex_home" CODEX_LOG="$log" PATH="/usr/bin:/bin" \
      "$ROOT/scripts/install-codex-plugin.sh" --remove 2>&1)" || status=$?
    if [ "$held" = 1 ]; then
      [ "$status" -ne 0 ] || fail "missing codex CLI was accepted while its marketplace entry remains"
    else
      [ "$status" -eq 0 ] || fail "missing codex CLI with no entry of ours blocked removal: $out"
    fi
    if grep -Fq 'oh-my-setting managed Codex HUD' "$codex_home/config.toml"; then
      fail "missing codex CLI prevented independent managed HUD cleanup"
    fi
  done
}

test_install_codex_plugin_skips_current_cache() {
  local d="$TMP/codex-plugin-current"
  local home="$d/home"
  local bin="$d/bin"
  local log="$d/codex.log"
  local version
  local cache

  mkdir -p "$bin"
  version="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["version"])' \
    "$ROOT/plugins/oh-my-setting/.codex-plugin/plugin.json")"
  cache="$home/.codex/plugins/cache/oh-my-setting-local/oh-my-setting/$version"
  mkdir -p "$cache"
  cp -R "$ROOT/plugins/oh-my-setting/." "$cache/"
  oms_smoke_make_fake_provider_stub "$bin/codex" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$CODEX_LOG"
if [ "$1 $2 $3" = "plugin marketplace list" ]; then
  printf 'oh-my-setting-local %s\n' "$OMS_TEST_ROOT"
elif [ "$1 $2 $3" = "plugin list --json" ]; then
  printf '%s\n' '{"installed":[{"pluginId":"oh-my-setting@oh-my-setting-local","installed":true}]}'
fi
EOF

  HOME="$home" CODEX_HOME="$home/.codex" CODEX_LOG="$log" OMS_TEST_ROOT="$ROOT" \
    PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/install-codex-plugin.sh" > "$d/out"
  assert_file_contains "$d/out" "already current"
  if grep -Fq 'plugin add oh-my-setting@oh-my-setting-local' "$log"; then
    fail "current Codex plugin cache must not be re-registered"
  fi
}

test_doctor_auto_repairs_installed_codex_plugin() {
  local d="$TMP/doctor-plugin-auto-repair"
  local home="$d/home"
  local receipt="$d/config/oh-my-setting/install.json"
  local bin="$d/bin"
  local log="$d/codex.log"
  local version
  local cache

  mkdir -p "$home" "$bin"
  HOME="$home" XDG_CONFIG_HOME="$d/config" OMS_INSTALL_RECEIPT="$receipt" \
    "$ROOT/scripts/link.sh" >/dev/null
  python3 - "$receipt" <<'PY'
import json
import sys

path = sys.argv[1]
row = json.load(open(path, encoding="utf-8"))
row["components"]["codex_plugin"] = True
with open(path, "w", encoding="utf-8") as handle:
    json.dump(row, handle, indent=2, sort_keys=True)
    handle.write("\n")
PY
  version="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["version"])' \
    "$ROOT/plugins/oh-my-setting/.codex-plugin/plugin.json")"
  cache="$home/.codex/plugins/cache/oh-my-setting-local/oh-my-setting/$version"
  mkdir -p "$cache"
  printf 'stale\n' > "$cache/stale.txt"

  oms_smoke_make_fake_provider_stub "$bin/codex" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$CODEX_LOG"
if [ "$1 $2 $3" = "plugin list --json" ]; then
  printf '%s\n' '{"installed":[{"pluginId":"oh-my-setting@oh-my-setting-local","installed":true}]}'
elif [ "$1 $2 $3" = "plugin marketplace list" ]; then
  printf 'oh-my-setting-local %s\n' "$OMS_TEST_ROOT"
elif [ "$1 $2" = "plugin add" ]; then
  rm -rf "$OMS_TEST_CACHE"
  mkdir -p "$OMS_TEST_CACHE"
  cp -R "$OMS_TEST_ROOT/plugins/oh-my-setting/." "$OMS_TEST_CACHE/"
  printf 'Installed plugin root: %s\n' "$OMS_TEST_CACHE"
fi
EOF

  env -u OH_MY_SETTING_CODEX_PLUGIN \
    HOME="$home" XDG_CONFIG_HOME="$d/config" CODEX_HOME="$home/.codex" \
    OMS_INSTALL_RECEIPT="$receipt" OMS_TEST_ROOT="$ROOT" OMS_TEST_CACHE="$cache" \
    CODEX_LOG="$log" PATH="$bin:/usr/bin:/bin" OH_MY_SETTING_REQUIRE_TOOLS=0 \
    OH_MY_SETTING_CLAUDE_HOOKS=0 "$ROOT/scripts/doctor.sh" --repair >"$d/out" ||
    fail "doctor --repair should refresh an installed plugin in auto mode"
  assert_file_contains "$log" "plugin add oh-my-setting@oh-my-setting-local"
  assert_file_contains "$d/out" "ok: codex plugin oh-my-setting (cache parity)"
  assert_file_contains "$d/out" "ok: codex HUD configured (managed)"
  assert_file_contains "$d/out" "ok: codex usage keys (terminal-ceiling=managed v2-waits=disabled turn-notify=managed scope=config-file effective=unverified)"
  assert_not_exists "$cache/stale.txt"
}

test_install_receipt_foreign_doctor_and_repair() {
  local d="$TMP/install-receipt"
  local home="$d/home"
  local receipt="$d/config/oh-my-setting/install.json"
  local foreign="$d/foreign"

  mkdir -p "$home"
  HOME="$home" XDG_CONFIG_HOME="$d/config" OMS_INSTALL_RECEIPT="$receipt" \
    "$ROOT/scripts/link.sh" >/dev/null
  python3 - "$receipt" "$ROOT" <<'PY' || fail "link should atomically commit a canonical receipt"
import json, os, sys
d = json.load(open(sys.argv[1], encoding="utf-8"))
assert d["schema"] == 2
assert d["source_root"] == os.path.realpath(sys.argv[2])
assert d["commit"]
assert d["channel"]
assert d["version"]
assert d["installed_at"].endswith("Z")
assert isinstance(d["dirty"], bool)
assert d["profile"] == "custom"
assert d["ref"]
assert d["previous_commit"] == ""
assert all(isinstance(value, bool) for value in d["components"].values())
assert ".local/bin/oms" in d["managed_targets"]
assert d["plugin"]["name"] == "oh-my-setting"
assert len(d["plugin"]["sha256"]) == 64
PY
  assert_symlink_to "$home/.codex/AGENTS.md" "$ROOT/rules/global-AGENTS.md"

  cp -a "$ROOT" "$foreign"
  # The foreign checkout needs this repo's scripts, not its live state. Copying
  # .oms couples the fixture to whatever is being appended there at that instant
  # — the running session's hook events, for one — and doctor audits .oms JSONL,
  # so a torn copy fails it. Observed once as a 4-way-parallel-only failure of
  # the repair assertion below that would not reproduce serially or on re-run;
  # the mechanism fits, and the coupling is wrong either way.
  rm -rf "$foreign/.oms"
  cat > "$foreign/scripts/skill-doctor.sh" <<'EOF'
#!/usr/bin/env bash
echo "foreign skill doctor must not run" >&2
exit 91
EOF
  chmod +x "$foreign/scripts/skill-doctor.sh"
  HOME="$home" XDG_CONFIG_HOME="$d/config" OMS_INSTALL_RECEIPT="$receipt" \
    PATH="/usr/bin:/bin" OH_MY_SETTING_REQUIRE_TOOLS=0 OH_MY_SETTING_CODEX_PLUGIN=0 \
    OH_MY_SETTING_CLAUDE_HOOKS=0 \
    "$foreign/scripts/doctor.sh" >"$d/doctor" ||
    fail "a foreign checkout should validate the canonical receipt owner"
  assert_file_contains "$d/doctor" "delegating doctor to canonical owner"

  ln -sfn "$foreign/AGENTS.md" "$home/.codex/AGENTS.md"
  HOME="$home" XDG_CONFIG_HOME="$d/config" OMS_INSTALL_RECEIPT="$receipt" \
    PATH="/usr/bin:/bin" OH_MY_SETTING_REQUIRE_TOOLS=0 OH_MY_SETTING_CODEX_PLUGIN=0 \
    OH_MY_SETTING_CLAUDE_HOOKS=0 \
    "$foreign/scripts/doctor.sh" --repair >"$d/repair" ||
    fail "doctor --repair should relink from the valid canonical owner"
  assert_symlink_to "$home/.codex/AGENTS.md" "$ROOT/rules/global-AGENTS.md"

  HOME="$home" XDG_CONFIG_HOME="$d/config" OMS_INSTALL_RECEIPT="$receipt" \
    "$ROOT/scripts/unlink.sh" >/dev/null
  assert_not_exists "$receipt"
}

test_skill_router_ignores_harness_child() {
  local primary="$TMP/child-hook-primary"
  local child="$TMP/child-hook-worktree"
  local payload before after out

  make_committed_repo "$primary"
  mkdir -p "$child"
  "$ROOT/scripts/agent-task.sh" --repo "$primary" init --goal "Parent task" >/dev/null
  before="$(sha256sum "$primary/.oms/task/current.md" | awk '{print $1}')"
  payload="$(printf '{"prompt":"fix this internal delegated task","session_id":"child-s","turn_id":"child-t","cwd":"%s"}' "$child")"
  out="$(printf '%s' "$payload" |
    OMS_HARNESS_CHILD=1 OMS_HARNESS_ORIGIN=peer-delegate \
    OMS_STATE_REPO="$primary" TMPDIR="$TMP" bash "$ROOT/scripts/skill-router.sh")"
  after="$(sha256sum "$primary/.oms/task/current.md" | awk '{print $1}')"

  [ -z "$out" ] || fail "a harness child hook should stay silent"
  [ "$before" = "$after" ] || fail "a harness child must not mutate the parent task"
  assert_not_exists "$child/.oms"
  [ ! -e "$primary/.oms/hooks/events.jsonl" ] ||
    ! grep -q ignored_child "$primary/.oms/hooks/events.jsonl" ||
    fail "a harness child hook must write no ignored_child row"
}

test_agent_plan_rejects_stale_lease_after_reclaim() {
  local d="$TMP/plan-lease"
  local sh="$ROOT/scripts/agent-plan.sh"
  local old_lease new_lease

  mkdir -p "$d"
  "$sh" --repo "$d" init --goal "lease fencing" >/dev/null
  "$sh" --repo "$d" add --id t1 --title "fenced" >/dev/null
  "$sh" --repo "$d" claim --id t1 --provider codex --ttl 0 >/dev/null
  old_lease="$("$sh" --repo "$d" show --id t1 |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  [ -n "$old_lease" ] || fail "claim should issue a lease id"

  "$sh" --repo "$d" reclaim >/dev/null
  "$sh" --repo "$d" claim --id t1 --provider claude >/dev/null
  new_lease="$("$sh" --repo "$d" show --id t1 |
    python3 -c 'import json,sys; print(json.load(sys.stdin)["lease_id"])')"
  [ "$old_lease" != "$new_lease" ] || fail "reclaim should fence the old lease"

  if OMS_PLAN_LEASE_ID="$old_lease" OMS_HARNESS_CHILD=1 \
    "$sh" --repo "$d" start --id t1 >/dev/null 2>"$d/err"; then
    fail "a stale worker lease must not mutate a re-claimed task"
  fi
  assert_file_contains "$d/err" "lease mismatch"
  OMS_PLAN_LEASE_ID="$new_lease" OMS_HARNESS_CHILD=1 \
    "$sh" --repo "$d" start --id t1 >/dev/null
  "$sh" --repo "$d" show --id t1 | grep -F '"state": "running"' > /dev/null ||
    fail "the current lease should permit the transition"
}

test_agent_plan_reopen_only_from_blocked() {
  local d="$TMP/plan-reopen-state"
  local sh="$ROOT/scripts/agent-plan.sh"

  mkdir -p "$d"
  "$sh" --repo "$d" init --goal "reopen contract" >/dev/null
  "$sh" --repo "$d" add --id t1 --title "ready" >/dev/null
  if "$sh" --repo "$d" reopen --id t1 >/dev/null 2>"$d/err"; then
    fail "reopen should reject a task that is not blocked"
  fi
  assert_file_contains "$d/err" "only a blocked task"
  "$sh" --repo "$d" block --id t1 --reason "waiting" >/dev/null
  "$sh" --repo "$d" reopen --id t1 >/dev/null
  "$sh" --repo "$d" show --id t1 | grep -F '"state": "ready"' > /dev/null ||
    fail "reopen should return a blocked task to ready"

  # retro counts what the plan and its progress ledger recorded and writes nothing.
  local before after
  "$sh" --repo "$d" add --id t2 --title "second" >/dev/null
  "$sh" --repo "$d" block --id t2 --reason "format undecided" >/dev/null
  {
    printf '%s\n' '{"schema":1,"kind":"goal-cycle","run_id":"r1","cycle":1,"task_id":"t1","lease_id":""}'
    printf '%s\n' '{"schema":1,"kind":"goal-cycle","run_id":"r1","cycle":2,"task_id":"t1","lease_id":""}'
    printf '%s\n' '{"schema":1,"kind":"goal-cycle","run_id":"old","cycle":1,"task_id":"gone","lease_id":""}'
    printf '%s\n' '{"schema":1,"kind":"acceptance","run_id":"r1","status":"fail","exit":1,"reason":""}'
    printf '%s\n' '{"schema":1,"kind":"acceptance","run_id":"old","status":"fail","exit":1,"reason":""}'
    printf '%s\n' '{"schema":1,"kind":"acceptance","run_id":"r1","status":"pass","exit":0,"reason":""}'
    printf '%s\n' '{"schema":1,"kind":"terminal","run_id":"r1","status":"park","reason":"cycles-exhausted"}'
    printf '%s\n' '{"schema":1,"kind":"terminal","run_id":"old","status":"park","reason":"other-plan"}'
    printf '%s\n' 'not json'
  } > "$d/.oms/plan/progress.jsonl"
  before="$(cd "$d/.oms/plan" && cksum tasks.json progress.jsonl && ls)"
  "$sh" --repo "$d" retro > "$d/retro" || fail "retro should read a live plan"
  assert_file_contains "$d/retro" "plan retro: reopen contract"
  assert_file_contains "$d/retro" "drive: 1 run(s), 2 cycle(s), 0 finished"
  assert_file_contains "$d/retro" "parked 1x: cycles-exhausted"
  assert_file_contains "$d/retro" "acceptance: 1 pass, 1 fail"
  assert_file_contains "$d/retro" "t1  cycles=2  ready"
  assert_file_contains "$d/retro" "t2  second  [format undecided]"
  assert_file_contains "$d/retro" "not approval or verification evidence"
  ! grep -q 'other-plan' "$d/retro" || fail "retro must leave out another plan's drive rows"
  "$sh" --repo "$d" retro --json > "$d/retro.json" || fail "retro --json should read a live plan"
  python3 - "$d/retro.json" <<'PY' || fail "retro --json shape"
import json, sys
report = json.load(open(sys.argv[1], encoding="utf-8"))
assert report["kind"] == "oms-plan-retro" and report["schema"] == 1, report
assert report["drive"] == {"runs": 1, "cycles": 2, "finished": 0, "parks": {"cycles-exhausted": 1}}, report["drive"]
assert [item["id"] for item in report["blocked"]] == ["t2"], report["blocked"]
assert report["retried"][0]["id"] == "t1" and report["retried"][0]["cycles"] == 2, report["retried"]
PY
  after="$(cd "$d/.oms/plan" && cksum tasks.json progress.jsonl && ls)"
  [ "$before" = "$after" ] || fail "retro must not write plan state"
  rm -f "$d/.oms/plan/tasks.json"
  if "$sh" --repo "$d" retro >/dev/null 2>"$d/err"; then
    fail "retro without a plan must fail"
  fi
  assert_file_contains "$d/err" "no readable plan"
}

