# smoke-weight: 8
test_task_verification_is_bound_to_repo_state() {
  local project="$TMP/verify-freshness"
  local out

  make_committed_repo "$project"
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "make it work" \
    --verify "true" >/dev/null )

  out="$( cd "$project" && "$ROOT/scripts/agent-task.sh" status )"
  contains "$out" 'verification: none' ||
    fail "an unverified task should report verification: none: $out"

  ( cd "$project" && "$ROOT/scripts/agent-task.sh" verify >/dev/null )
  out="$( cd "$project" && "$ROOT/scripts/agent-task.sh" status )"
  contains "$out" 'verification: fresh' ||
    fail "a passing verify should be fresh: $out"

  # The whole point: a green status must not survive a change to the tree it
  # was green on.
  printf 'changed\n' >> "$project/file.txt"
  out="$( cd "$project" && "$ROOT/scripts/agent-task.sh" status )"
  contains "$out" 'verification: stale' ||
    fail "editing a tracked file should make verification stale: $out"

  ( cd "$project" && "$ROOT/scripts/agent-task.sh" verify >/dev/null )
  printf 'untracked\n' > "$project/new-file.txt"
  out="$( cd "$project" && "$ROOT/scripts/agent-task.sh" status )"
  contains "$out" 'verification: stale' ||
    fail "a new untracked file should make verification stale: $out"

  # A rewritten contract is a different contract, even with an unchanged tree.
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" verify >/dev/null )
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" update --verify "true # different" >/dev/null )
  out="$( cd "$project" && "$ROOT/scripts/agent-task.sh" status )"
  contains "$out" 'verification: stale' ||
    fail "changing the verify command should make verification stale: $out"

  ( cd "$project" && "$ROOT/scripts/agent-task.sh" status --json ) | python3 -c '
import json, sys
d = json.load(sys.stdin)
assert d["verification"] == "stale", d
' || fail "status --json should carry verification freshness"

  # Normalized goal lifecycle: `achieved` only from a fresh passing verify.
  # An agent's own claim, a stale pass and a hand-edited status are `pursuing`.
  lifecycle_of() {
    ( cd "$project" && "$ROOT/scripts/agent-task.sh" status --json ) | python3 -c '
import json, sys
l = json.load(sys.stdin)["lifecycle"]
print(l["state"], l["evidence"]["rule"], l["evidence"].get("budget_limit") or "-")'
  }
  [ "$(lifecycle_of)" = "pursuing not-verified-fresh -" ] ||
    fail "a stale pass must be pursuing: $(lifecycle_of)"
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" update \
    --verification "everything passes, the goal is achieved" >/dev/null )
  [ "$(lifecycle_of)" = "pursuing not-verified-fresh -" ] ||
    fail "the agent's own claim must stay pursuing: $(lifecycle_of)"
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" verify >/dev/null )
  [ "$(lifecycle_of)" = "achieved verified-fresh -" ] ||
    fail "a fresh passing verify must be achieved: $(lifecycle_of)"
  printf 'moved\n' >> "$project/file.txt"
  [ "$(lifecycle_of)" = "pursuing not-verified-fresh -" ] ||
    fail "a verify the tree moved past must not stay achieved: $(lifecycle_of)"

  # goal-drive parks map onto the lifecycle: budget reasons are budget-limited,
  # judged-failure reasons are unmet, any other stop for the parent is paused,
  # and a later passing acceptance row resolves the park.
  mkdir -p "$project/.oms/plan"
  printf '{"goal":"g","tasks":{"t1":{"id":"t1"}}}\n' > "$project/.oms/plan/tasks.json"
  park_with() {
    printf '%s\n' \
      '{"kind":"goal-cycle","task_id":"t1","run_id":"r1"}' \
      "{\"kind\":\"terminal\",\"run_id\":\"r1\",\"cycle\":3,\"status\":\"park\",\"reason\":\"$1\"}" \
      > "$project/.oms/plan/progress.jsonl"
  }
  park_with cycles-exhausted
  [ "$(lifecycle_of)" = "budget-limited park:cycles-exhausted cycles-exhausted" ] ||
    fail "cycles-exhausted must be budget-limited: $(lifecycle_of)"
  park_with stuck
  [ "$(lifecycle_of)" = "unmet park:stuck -" ] || fail "stuck must be unmet: $(lifecycle_of)"
  park_with head-moved
  [ "$(lifecycle_of)" = "paused park:head-moved -" ] || fail "a parent-needed park must be paused: $(lifecycle_of)"
  printf '%s\n' '{"kind":"acceptance","status":"pass","run_id":"r1"}' >> "$project/.oms/plan/progress.jsonl"
  [ "$(lifecycle_of)" = "pursuing not-verified-fresh -" ] ||
    fail "a later passing acceptance must resolve the park: $(lifecycle_of)"
  # A park never makes a verified task less achieved.
  park_with cycles-exhausted
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" verify >/dev/null )
  [ "$(lifecycle_of)" = "achieved verified-fresh -" ] ||
    fail "a fresh verify outranks a park: $(lifecycle_of)"
}

# smoke-weight: 10
test_task_close_refuses_a_false_green() {
  local project="$TMP/close-gate"
  local out

  make_committed_repo "$project"
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "ship it" \
    --verify "true" >/dev/null )

  # Closing promotes "Closed task" into shared memory, so an unverified close
  # hands the next session a false green.
  if ( cd "$project" && "$ROOT/scripts/agent-task.sh" close >/dev/null 2>&1 ); then
    fail "closing an unverified task with a verify contract must be refused"
  fi
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" verify >/dev/null )
  printf 'changed\n' >> "$project/file.txt"
  if ( cd "$project" && "$ROOT/scripts/agent-task.sh" close >/dev/null 2>&1 ); then
    fail "closing on a stale verification must be refused"
  fi

  # An explicit reason is the documented override, and it is recorded.
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" close --reason "abandoned for a different approach" >/dev/null ) ||
    fail "--reason should allow closing without fresh verification"
  out="$(cat "$project"/.oms/task/archive/*.md)"
  contains "$out" 'closed without fresh verification' ||
    fail "the override should be recorded in the archived packet: $out"

  # Re-verified tasks close without ceremony, and a packet with no verification
  # contract is not gated at all.
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "second" --verify "true" >/dev/null )
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" verify >/dev/null )
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" close >/dev/null ) ||
    fail "a freshly verified task should close"
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "exploration only" >/dev/null )
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" close >/dev/null ) ||
    fail "a task without a verify contract should still close"

  # A goal still being pursued is not silently replaced, by init, rotate or
  # update; a parent may pass --replace-goal REASON, and the new packet then
  # names the replaced task id and the reason. A harness child never can.
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "keep me" --verify "true" >/dev/null )
  first_id="$(awk '$1 == "-" && $2 == "task_id:" { print $3; exit }' "$project/.oms/task/current.md")"
  for attempt in "init --goal other" "rotate --goal other" "rotate" "update --goal other"; do
    # shellcheck disable=SC2086
    if out="$( cd "$project" && "$ROOT/scripts/agent-task.sh" $attempt 2>&1 )"; then
      fail "'$attempt' replaced an active goal"
    fi
    contains "$out" 'refusing to replace the goal of active task' ||
      fail "'$attempt' refusal lacks the message: $out"
  done
  grep -Fqx 'keep me' "$project/.oms/task/current.md" || fail "a refused replacement changed the goal"
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "keep me" >/dev/null ) ||
    fail "re-stating the same goal is not a replacement"
  first_id="$(awk '$1 == "-" && $2 == "task_id:" { print $3; exit }' "$project/.oms/task/current.md")"
  for child_env in "OMS_HARNESS_CHILD=1" "OMS_HARNESS_DELEGATE_DEPTH=1"; do
    for attempt in "init --goal other --replace-goal why" "rotate --replace-goal why" \
      "update --goal other" "verify" "init"; do
      # shellcheck disable=SC2086
      if ( cd "$project" && env "$child_env" "$ROOT/scripts/agent-task.sh" $attempt >/dev/null 2>&1 ); then
        fail "a harness child ($child_env) ran '$attempt'"
      fi
    done
  done
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" rotate --goal "replacement" \
    --replace-goal "owner changed the plan" >/dev/null ) ||
    fail "--replace-goal should let a parent replace the goal"
  second_id="$(awk '$1 == "-" && $2 == "task_id:" { print $3; exit }' "$project/.oms/task/current.md")"
  [ "$second_id" != "$first_id" ] || fail "rotate kept the task id"
  assert_file_contains "$project/.oms/task/current.md" "previous task_id=$first_id; reason: owner changed the plan"
  ls "$project/.oms/task/archive/$first_id"-*.md >/dev/null || fail "the replaced packet was not archived"
  # A verified goal is not being pursued, so a new one needs no override.
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" update --verify true >/dev/null &&
    "$ROOT/scripts/agent-task.sh" verify >/dev/null &&
    "$ROOT/scripts/agent-task.sh" init --goal "after achieved" >/dev/null ) ||
    fail "a verified goal should be replaceable without an override"
}

test_repo_state_flags_ci_recorded_for_another_commit() {
  local project="$TMP/ci-freshness"
  local head old out

  make_committed_repo "$project"
  head="$(git -C "$project" rev-parse HEAD)"
  old="0000000000000000000000000000000000000001"
  mkdir -p "$project/.oms"
  printf '{"schema":1,"ts":"2026-07-20T00:00:00Z","branch":"main","sha":"%s","status":"completed","conclusion":"success"}\n' \
    "$old" > "$project/.oms/ci.jsonl"

  out="$("$ROOT/scripts/state.sh" --repo "$project")"
  contains "$out" 'STALE' ||
    fail "CI recorded for another commit should be marked stale: $out"
  contains "$out" 'oms state --refresh-ci' ||
    fail "state should name the refresh command: $out"
  "$ROOT/scripts/state.sh" --repo "$project" --json | python3 -c '
import json, sys
ci = json.load(sys.stdin)["ci"]
assert ci["fresh"] is False, ci
assert ci["current_sha"], ci
' || fail "repo-state --json should expose CI freshness"

  printf '{"schema":1,"ts":"2026-07-21T00:00:00Z","branch":"main","sha":"%s","status":"completed","conclusion":"success"}\n' \
    "$head" >> "$project/.oms/ci.jsonl"
  out="$("$ROOT/scripts/state.sh" --repo "$project")"
  if contains "$out" 'STALE'; then
    fail "CI recorded for HEAD must not be marked stale: $out"
  fi
  "$ROOT/scripts/state.sh" --repo "$project" --json | python3 -c '
import json, sys
assert json.load(sys.stdin)["ci"]["fresh"] is True
' || fail "CI for HEAD should be fresh"
}

# The classifier used to be an inline heredoc and could not go missing. As a
# file it can, and an empty verdict defaulting to "ok" would silently restore
# the bug it exists for: a provider's refusal counted as a real answer, so a
# council reports two independent families when one of them never spoke.
test_answer_quality_fails_closed_without_its_helper() {
  local dir="$TMP/answer-quality-missing"
  local stage="$dir/scripts"
  local verdict
  local err

  # A complete lib with exactly one file removed, so the classifier's absence
  # is the only variable. The artifact is a real answer, which means an "ok"
  # verdict here could only have come from the default, not from a check.
  mkdir -p "$stage"
  cp -R "$ROOT/scripts/lib" "$stage/lib"
  rm -f "$stage/lib/answer-quality.py"
  printf '## Output\nThe split policy should be scaffold-based.\n## Exit\n0\n' \
    > "$dir/answer.md"

  verdict="$(bash -c ". '$stage/lib/peer-common.sh'; ma_answer_quality '$dir/answer.md'" \
    2>"$dir/err")"
  err="$(cat "$dir/err")"
  [ "$verdict" = blocked ] ||
    fail "a missing answer-quality helper must not read as a real answer: $verdict"
  contains "$err" 'answer-quality helper is missing' ||
    fail "the missing helper must be named on stderr: $err"
}

test_answer_quality_separates_a_non_answer_from_an_answer() {
  local dir="$TMP/answer-quality"
  local verdict

  mkdir -p "$dir"
  # A provider can exit 0 and still not answer; only the body decides.
  cat > "$dir/thin.md" <<'ARTIFACT'
# codex call

## Output

model-route: class=deep primary=m fallback=n effort=high fallback_effort=medium
Could you please provide more context on what you mean by `--sandbox`?

## Exit

0
ARTIFACT
  cat > "$dir/empty.md" <<'ARTIFACT'
# codex call

## Output

model-route: class=deep primary=m fallback=n effort=high fallback_effort=medium

## Exit

0
ARTIFACT
  cat > "$dir/ok.md" <<'ARTIFACT'
# codex call

## Output

model-route: class=deep primary=m fallback=n effort=high fallback_effort=medium
Use map-style datasets when you need shuffling and shard by file for streaming
inputs. Evidence: the loader contract in docs/DATA.md pins the sampler seed per
rank, so DDP workers do not duplicate shards. Next action: pin the seed in the
config before the next run.

## Exit

0
ARTIFACT

  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/thin.md'")"
  [ "$verdict" = "ok" ] || fail "a clarifying question is still usable output, got: $verdict"
  for ending in '?' '.'; do
    printf '## Output\nsrc/cache.py:42에서 모델 버전이 키에 빠진 것 아닌가요%s\n## Exit\n0\n' "$ending" > "$dir/question.md"
    verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/question.md'")"
    [ "$verdict" = ok ] || fail "punctuation must not classify semantic quality: $verdict"
    verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_council_nonanswer '$dir/question.md'")"
    [ -z "$verdict" ] || fail "a question must not drop a council seat: $verdict"
  done
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/empty.md'")"
  [ "$verdict" = "empty" ] || fail "a body with only harness lines is empty, got: $verdict"
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/ok.md'")"
  [ "$verdict" = "ok" ] || fail "a substantive answer should be ok, got: $verdict"

  for body in '' 'A partial finding that looks complete.'; do
    printf '## Output\n%s\n[agy] print timeout after 10m0s with turn in progress; returning partial output\r\n## Exit\n0\n' "$body" > "$dir/timeout.md"
    verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/timeout.md'")"
    [ "$verdict" = truncated ] || fail "zero-exit print timeout must not be an answer: $verdict"
  done

  printf '## Output\nAnswer:\nTradeoffs:\nRisks:\nRecommendation:\n' > "$dir/headings.md"
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/headings.md'")"
  [ "$verdict" = empty ] || fail "empty section headings must be empty: $verdict"
  printf '## Output\nAnswer:\nA finding.\nRisks:\n' > "$dir/headings.md"
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/headings.md'")"
  [ "$verdict" = ok ] || fail "section body must remain usable: $verdict"

  # A correct answer can be one sentence. Calling that a non-answer would spend
  # another provider call for nothing, so length alone must not decide.
  cat > "$dir/concise.md" <<'ARTIFACT'
# codex call

## Output

model-route: class=deep primary=m fallback=n effort=high fallback_effort=medium
Use map-style datasets and shard by file.

## Exit

0
ARTIFACT
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/concise.md'")"
  [ "$verdict" = "ok" ] || fail "a concise answer is still an answer, got: $verdict"

  # Antigravity exits 0 after auto-denying a tool it cannot prompt for, printing
  # only its refusal. That text is declarative and long enough to pass every
  # other rule here, so a live council counted it as an answer and reported two
  # independent model families when one provider had spoken.
  cat > "$dir/blocked.md" <<'ARTIFACT'
# antigravity call

## Output

model-route: class=deep primary=m fallback=n effort=high fallback_effort=medium
jetski: no output produced — a tool required the "command" permission that headless mode cannot prompt for, so it was auto-denied. Add an allow-rule under permissions.allow in settings.json (e.g. command(<target>)).

## Exit

0
ARTIFACT
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/blocked.md'")"
  [ "$verdict" = "blocked" ] || fail "a CLI refusal is not an answer, got: $verdict"
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_block_reason '$dir/blocked.md'")"
  case "$verdict" in
    jetski:*) ;;
    *) fail "the operator needs the provider's own reason, got: $verdict" ;;
  esac

  # Provider telemetry is appended after the body in label/value pairs. The
  # numeric value after `tokens used` must not turn a refusal into an answer.
  cat > "$dir/blocked-with-footers.md" <<'ARTIFACT'
# codex call

## Output

stop-reason: provider=codex reason=turn_completed subtype=success is_error=0
error: permission denied while reading the requested repository.
served model
gpt-5.6-terra
tokens used
15
cost usd
0.01

## Exit

0
ARTIFACT
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/blocked-with-footers.md'")"
  [ "$verdict" = "blocked" ] ||
    fail "transport footers must not promote a refusal to an answer, got: $verdict"

  # An answer that discusses permissions is still an answer: the refusal rule
  # fires only when the whole body is diagnostics.
  cat > "$dir/about-permissions.md" <<'ARTIFACT'
# codex call

## Output

model-route: class=deep primary=m fallback=n effort=high fallback_effort=medium
error: permission denied is the failure you should expect here.
Grant the worker read access in the delegation profile, then re-run the gate.

## Exit

0
ARTIFACT
  verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/about-permissions.md'")"
  [ "$verdict" = "ok" ] || fail "an answer about permissions is not a refusal, got: $verdict"

  local item text expected
  for item in "42:ok" "Yes.:ok" "가능합니다.:ok" "Why?:ok"; do
    text="${item%%:*}"
    expected="${item##*:}"
    printf '# codex call\n\n## Output\n\n%s\n\n## Exit\n\n0\n' "$text" > "$dir/short.md"
    verdict="$(bash -c ". '$ROOT/scripts/lib/peer-common.sh'; ma_answer_quality '$dir/short.md'")"
    [ "$verdict" = "$expected" ] ||
      fail "short fixture '$text' expected '$expected', got: $verdict"
  done
}

# smoke-weight: 5
test_consult_falls_back_when_the_first_peer_does_not_answer() {
  local project="$TMP/consult-failover"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local out

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  # First peer exits 0 with an authentication failure; the second answers.
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
echo "error: not authenticated"
EOF
  cat > "$bin_dir/agy" <<'EOF'
#!/usr/bin/env bash
echo "Shard by file for streaming inputs and keep the sampler seeded per rank so"
echo "DDP workers never duplicate shards. Evidence: the loader contract. Next:"
echo "pin the seed in the training config before the next run."
EOF
  chmod +x "$bin_dir/codex" "$bin_dir/agy"
  wrap_agy_stub "$bin_dir/agy"

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_AGENT=claude "$ROOT/scripts/consult.sh" --repo "$project" \
    "which loader?" --quiet 2>&1)" || fail "consult should recover: $out"
  contains "$out" 'did not really answer (blocked); asking antigravity' ||
    fail "consult should report the fallback: $out"

  "$ROOT/scripts/thread.sh" --repo "$project" show --json | python3 -c '
import json, sys
turns = json.load(sys.stdin)["turns"]
roles = [t["role"] for t in turns]
# One question, both attempts recorded, the non-answer labelled as such.
assert roles.count("question") == 1, roles
answers = [t for t in turns if t["role"] == "answer"]
assert [a["provider"] for a in answers] == ["codex", "antigravity"], answers
assert answers[0]["quality"] == "blocked", answers[0]
assert answers[1].get("quality") == "ok", answers[1]
' || fail "the thread should record one question, a blocked attempt, and an answer"

  assert_one_artifact_contains "$project/.oms/artifacts/consult" 'antigravity-*.md' 'usage detail:'

  project="$TMP/consult-short-answer"
  bin_dir="$project/bin"
  home_dir="$project/home"
  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
echo "Could you clarify which input?"
EOF
  cat > "$bin_dir/agy" <<EOF
#!/usr/bin/env bash
case "\${1:-}:\${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac
touch "$project/agy-called"
echo "Fallback answered after an unnecessary provider call."
EOF
  chmod +x "$bin_dir/codex" "$bin_dir/agy"
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_AGENT=claude "$ROOT/scripts/consult.sh" --repo "$project" \
    "what is six times seven?" 2>&1)" || fail "consult should succeed: $out"
  [ "$(printf '%s\n' "$out" | grep -c 'Could you clarify which input?')" = 1 ] ||
    fail "consult should print the current answer once, without replaying thread history: $out"
  if printf '%s\n' "$out" | grep >/dev/null -F 'what is six times seven?'; then
    fail "consult should not replay the caller's question"
  fi
  [ ! -f "$project/agy-called" ] || fail "a short clarification must not call a fallback provider"
  "$ROOT/scripts/thread.sh" --repo "$project" show --json | python3 -c '
import json, sys
answers = [t for t in json.load(sys.stdin)["turns"] if t["role"] == "answer"]
assert len(answers) == 1, answers
assert answers[0]["provider"] == "codex", answers
assert answers[0].get("quality") == "ok", answers
' || fail "a short answer should need exactly one provider call"

  project="$TMP/consult-single-adapter"
  bin_dir="$project/bin"
  home_dir="$project/home"
  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir" "$project/adapters"
  cat > "$bin_dir/claude" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in --version|--help) exit 0 ;; esac
printf 'Fallback answered from the only installed builtin provider.\n'
EOF
  cat > "$project/adapters/oms-agent-adapter-localfoo" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in --version|--help) exit 0 ;; esac
printf 'error: not authenticated\n'
exit 1
EOF
  chmod +x "$bin_dir/claude" "$project/adapters/oms-agent-adapter-localfoo"
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_PROVIDER_ADAPTER_DIR="$project/adapters" OMS_AGENT=claude \
    "$ROOT/scripts/consult.sh" --repo "$project" --all "which loader?" 2>&1)" ||
    fail "a single custom adapter must retain builtin failover: $out"
  contains "$out" 'asking claude instead' || fail "adapter failure lost builtin fallback: $out"
  contains "$out" 'Fallback answered from the only installed builtin provider.' ||
    fail "builtin fallback did not answer: $out"
}

test_consult_does_not_second_guess_a_pinned_peer() {
  local project="$TMP/consult-pinned"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local out

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  # Exercise receipt identity without launching a provider or another repo.
  mkdir -p "$project/receipt-helper"
  printf '#!/usr/bin/env bash\nprintf "%%s\\n" "$OMS_TEST_RECEIPT"\n' > "$project/receipt-helper/agent-call.sh"
  printf 'an old usable answer\n' > "$project/old-answer.md"
  (
    . "$ROOT/scripts/lib/peer-common.sh"
    ma_scripts_dir() { printf '%s\n' "$project/receipt-helper"; }
    ma_answer_quality() { if [ -f "$1" ]; then echo ok; else echo empty; fi; }
    for OMS_TEST_RECEIPT in '' "artifact: $project/missing.md" "$(printf 'artifact: %s\nartifact: %s' "$project/old-answer.md" "$project/old-answer.md")"; do
      export OMS_TEST_RECEIPT
      if ma_call_read_peer "$project/receipt" 0 --to codex --prompt --dry-run >/dev/null 2>&1; then
        fail "missing or ambiguous receipt borrowed an old answer"
      fi
    done
    export OMS_TEST_RECEIPT="artifact: $project/old-answer.md"
    ma_call_read_peer "$project/receipt" 0 --to codex >/dev/null || exit 1
    [ "$(cat "$project/receipt")" = "$project/old-answer.md" ]
  ) || fail "shared peer result identity contract failed"
  cat > "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
echo "Could you clarify?"
EOF
  cat > "$bin_dir/agy" <<'EOF'
#!/usr/bin/env bash
echo "should not be called"
EOF
  chmod +x "$bin_dir/codex" "$bin_dir/agy"

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_AGENT=claude "$ROOT/scripts/consult.sh" --repo "$project" --to codex \
    "which loader?" --quiet 2>&1)" || true
  if contains "$out" 'asking antigravity'; then
    fail "an explicitly pinned peer must not be second-guessed: $out"
  fi
  "$ROOT/scripts/thread.sh" --repo "$project" show --json | python3 -c '
import json, sys
answers = [t for t in json.load(sys.stdin)["turns"] if t["role"] == "answer"]
assert [a["provider"] for a in answers] == ["codex"], answers
' || fail "only the pinned peer should have answered"
}

# smoke-weight: 8
test_patch_land_records_a_recoverable_transaction() {
  local project="$TMP/landing-txn"
  local patch="$TMP/landing-txn.patch"

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )

  "$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" >/dev/null 2>&1 ||
    fail "a clean patch should land"
  python3 - "$project/.oms/landings.jsonl" <<'PY' || fail "a land should be one intent and one completion"
import json, sys
events = [json.loads(line)["event"] for line in open(sys.argv[1])
          if line.strip() and not json.loads(line)["event"].startswith("capture-")]
assert events == ["intent", "complete"], events
PY
  # Nothing outstanding after a clean land.
  "$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1 |
    grep -F '0 recovered, 0 abandoned' > /dev/null ||
    fail "a completed land leaves nothing to recover"
  # A hostile replacement at Git's final read boundary cannot replace the
  # verified buffer. Restore the name afterwards to expose the old silent race.
  git -C "$project" checkout -q -- file.txt
  local replacement="$TMP/landing-txn-replacement.patch"
  local apply_bin="$TMP/landing-txn-bin"
  local marker="$TMP/landing-txn-swap.json"
  local real_git real_python
  real_git="$(command -v git)"
  real_python="$(command -v python3)"
  printf 'base\nforeign\n' > "$project/file.txt"
  git -C "$project" diff > "$replacement"
  git -C "$project" checkout -q -- file.txt
  mkdir -p "$apply_bin"
  cat > "$apply_bin/git" <<'EOFGIT'
#!/usr/bin/env bash
exec "$OMS_T_REAL_PYTHON" "$0.py" "$@"
EOFGIT
  cat > "$apply_bin/git.py" <<'PYGIT'
import hashlib, json, os, subprocess, sys
from pathlib import Path
args = sys.argv[1:]
repo = Path(os.environ['OMS_T_APPLY_REPO'])
if len(args) == 5 and args[:2] == ['-C', str(repo)] and args[2:4] == ['apply', '--binary']:
    rows = [json.loads(line) for line in (repo / '.oms/landings.jsonl').read_text().splitlines()]
    target = Path([row for row in rows if row['event'] == 'intent'][-1]['patch'])
    backup = target.with_name(target.name + '.before-swap')
    target.rename(backup)
    try:
        target.write_bytes(Path(os.environ['OMS_T_APPLY_REPLACEMENT']).read_bytes())
        data = sys.stdin.buffer.read() if args[-1] == '-' else None
        Path(os.environ['OMS_T_APPLY_MARKER']).write_text(json.dumps({
            'argv': args, 'stdin_sha256': hashlib.sha256(data).hexdigest() if data is not None else None}))
        result = subprocess.run([os.environ['OMS_T_REAL_GIT'], *args], input=data)
    finally:
        target.unlink()
        backup.rename(target)
    sys.exit(result.returncode)
os.execv(os.environ['OMS_T_REAL_GIT'], [os.environ['OMS_T_REAL_GIT'], *args])
PYGIT
  chmod +x "$apply_bin/git"
  PATH="$apply_bin:$PATH" OMS_T_REAL_GIT="$real_git" OMS_T_REAL_PYTHON="$real_python" \
    OMS_T_APPLY_REPO="$project" OMS_T_APPLY_REPLACEMENT="$replacement" OMS_T_APPLY_MARKER="$marker" \
    "$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" --verify true >"$TMP/landing-txn-swap.out" 2>&1 ||
    fail "verified-buffer landing failed: $(cat "$TMP/landing-txn-swap.out")"
  grep -Fxq added "$project/file.txt" && ! grep -Fxq foreign "$project/file.txt" ||
    fail "final apply consumed the swapped pathname instead of verified bytes"
  python3 - "$marker" "$patch" <<'PY' || fail "final Git apply did not consume the exact verified buffer"
import hashlib, json, sys
from pathlib import Path
row = json.loads(Path(sys.argv[1]).read_text())
assert row['argv'][-1] == '-', row
assert row['stdin_sha256'] == hashlib.sha256(Path(sys.argv[2]).read_bytes()).hexdigest(), row
PY
  "$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1 |
    grep -F '0 recovered, 0 abandoned' > /dev/null || fail "verified-buffer land lost its terminal receipts"

}

test_patch_land_recovers_an_interrupted_land() {
  local project="$TMP/landing-crash"
  local patch="$project/change.patch"
  local base_sha patch_sha
  local out rc

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  base_sha="$(git -C "$project" rev-parse HEAD | tr -d '\r')"
  patch_sha="$(python3 - "$patch" <<'PY'
import hashlib, pathlib, sys
print(hashlib.sha256(pathlib.Path(sys.argv[1]).read_bytes()).hexdigest())
PY
)"

  # Crash between apply and the records that follow it: the tree moved, the
  # lineage row and the completion never happened.
  mkdir -p "$project/.oms"
  printf '*\n' > "$project/.oms/.gitignore"
  printf '{"schema":1,"ts":"2026-07-26T00:00:00Z","landing_id":"land-crash","event":"intent","patch":"%s","patch_sha":"%s","base_sha":"%s","task":"","lease":"","plan_receipt_sha":"","plan_done_receipt_sha":"","approval":"","approval_version":""}\n' \
    "$patch" "$patch_sha" "$base_sha" > "$project/.oms/landings.jsonl"
  git -C "$project" apply --binary "$patch"

  out="$("$ROOT/scripts/state.sh" --repo "$project")"
  contains "$out" 'Interrupted landings (1)' ||
    fail "state should show the outstanding landing: $out"

  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)"
  contains "$out" 'recovered land-crash' ||
    fail "recovery should finish an applied landing: $out"
  grep -Fq 'patch-land' "$project/.oms/artifacts/index.jsonl" ||
    fail "recovery should record the missing lineage row"

  # Idempotent: a second pass must not re-apply or re-record anything.
  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)"
  contains "$out" '0 recovered, 0 abandoned' ||
    fail "recovery must be idempotent: $out"
  [ "$(grep -c 'patch-land' "$project/.oms/artifacts/index.jsonl")" = "1" ] ||
    fail "recovery must not duplicate the lineage row"
  out="$("$ROOT/scripts/state.sh" --repo "$project")"
  if contains "$out" 'Interrupted landings'; then
    fail "a recovered landing should no longer be outstanding: $out"
  fi

  # A correctly completed plan landing stays provable after its plan is
  # retired, and an older plan's task id never scopes into a newer plan. An
  # archived lease or digest that differs from the intent stays manual and
  # names the failed check instead of the HEAD-moved text.
  local rproject rpatch rart variant plan_sha task_sha landings_backup
  local plan="$ROOT/scripts/agent-plan.sh"
  for variant in exact lease digest; do
    rproject="$TMP/landing-retired-$variant"
    rpatch="$TMP/landing-retired-$variant.patch"
    rart="$TMP/landing-retired-$variant-review.md"
    make_committed_repo "$rproject"
    "$plan" --repo "$rproject" add --id t1 --title x --verify true >/dev/null
    "$plan" --repo "$rproject" claim --id t1 --provider codex >/dev/null
    printf 'work\n' >> "$rproject/file.txt"
    git -C "$rproject" diff > "$rpatch"
    git -C "$rproject" checkout -q file.txt
    printf 'review\n' > "$rart"
    "$plan" --repo "$rproject" review --id t1 --artifact "$rart" --patch "$rpatch" >/dev/null
    ( cd "$rproject" && "$ROOT/scripts/patch-land.sh" --patch "$rpatch" --plan-task t1 --verify true >/dev/null 2>&1 ) ||
      fail "the plan landing fixture should land"
    if [ "$variant" = exact ]; then
      out="$("$ROOT/scripts/patch-land.sh" --repo "$rproject" --recover --plan-task t1 2>&1)" ||
        fail "a scoped recovery of the live plan's complete landing should succeed: $out"
      contains "$out" 'already complete' ||
        fail "the live plan's own intent stays in a scoped recovery: $out"
      # A cancelled task in the archived plan makes the retirement validator
      # read the cancellation decision artifact relative to the repository.
      printf 'Reviewed and rejected.\n' > "$rproject/decision.md"
      "$plan" --repo "$rproject" add --id t2 --title rejected >/dev/null
      plan_sha="$(python3 -c 'import hashlib,sys;print(hashlib.sha256(open(sys.argv[1],"rb").read()).hexdigest())' "$rproject/.oms/plan/tasks.json" | tr -d '\r')"
      task_sha="$("$plan" --repo "$rproject" show --id t2 | python3 -c 'import json,sys;print(json.load(sys.stdin)["task_sha256"])' | tr -d '\r')"
      "$plan" --repo "$rproject" cancel --id t2 --expected-plan-sha256 "$plan_sha" \
        --expected-task-sha256 "$task_sha" --expected-state ready --expected-lease-id none \
        --operator-consent cancel --reason "reviewed rejection" --decision-artifact decision.md \
        --expected-decision-artifact-sha256 "$(python3 -c 'import hashlib,sys;print(hashlib.sha256(open(sys.argv[1],"rb").read()).hexdigest())' "$rproject/decision.md" | tr -d '\r')" >/dev/null ||
        fail "the cancelled-task fixture should cancel"
    else
      VARIANT="$variant" python3 - "$rproject/.oms/plan/tasks.json" <<'PY'
import json, os, sys
path = sys.argv[1]
plan = json.load(open(path))
task = plan["tasks"]["t1"]
if os.environ["VARIANT"] == "lease":
    task["lease_id"] = "lease_" + "0" * 32
else:
    task["title"] = "rewritten after the landing"
open(path, "w").write(json.dumps(plan))
PY
    fi
    plan_sha="$(python3 -c 'import hashlib,sys;print(hashlib.sha256(open(sys.argv[1],"rb").read()).hexdigest())' "$rproject/.oms/plan/tasks.json" | tr -d '\r')"
    "$plan" --repo "$rproject" retire --apply --expected-plan-sha256 "$plan_sha" \
      --disposition superseded --reason "plan replaced" >/dev/null ||
      fail "the finished plan should retire"
    if [ "$variant" = exact ]; then
      # The valid retirement archive cannot substitute for an unreadable live
      # plan: recovery must refuse before changing landing or capture seals.
      mkdir -p "$rproject/.oms/plan"
      printf '{"plan_id":' > "$rproject/.oms/plan/tasks.json"
      local before_state after_state
      before_state="$(python3 - "$rproject/.oms" <<'PY'
import hashlib, os, sys
root = sys.argv[1]
for directory, _, names in os.walk(root):
    for name in sorted(names):
        path = os.path.join(directory, name)
        if path.endswith('/plan/tasks.json'):
            continue
        with open(path, 'rb') as handle:
            print(os.path.relpath(path, root), hashlib.sha256(handle.read()).hexdigest())
PY
)"
      rc=0
      out="$(cd "$TMP" && env -u OMS_REPO "$ROOT/scripts/patch-land.sh" --repo "$rproject" --recover 2>&1)" || rc=$?
      [ "$rc" != 0 ] || fail "a malformed live plan must block archived receipt recovery: $out"
      contains "$out" 'tasks.json' || fail "the refusal should name the live plan file: $out"
      after_state="$(python3 - "$rproject/.oms" <<'PY'
import hashlib, os, sys
root = sys.argv[1]
for directory, _, names in os.walk(root):
    for name in sorted(names):
        path = os.path.join(directory, name)
        if path.endswith('/plan/tasks.json'):
            continue
        with open(path, 'rb') as handle:
            print(os.path.relpath(path, root), hashlib.sha256(handle.read()).hexdigest())
PY
)"
      [ "$after_state" = "$before_state" ] ||
        fail "a refused recovery must leave landing and seal state unchanged"
      rm -f "$rproject/.oms/plan/tasks.json"
    fi
    rc=0
    out="$(cd "$TMP" && env -u OMS_REPO "$ROOT/scripts/patch-land.sh" --repo "$rproject" --recover 2>&1)" || rc=$?
    if [ "$variant" = exact ]; then
      [ "$rc" = 0 ] || fail "a complete landing of a retired plan should converge, got $rc: $out"
      contains "$out" 'already complete' ||
        fail "a retired plan's archive should prove the done receipt: $out"
    else
      [ "$rc" = 1 ] || fail "an archived $variant mismatch must stay manual, got $rc: $out"
      if contains "$out" 'already complete'; then
        fail "an archived $variant mismatch must not count as complete: $out"
      fi
      contains "$out" 'plan done receipt did not converge' ||
        fail "the manual message should name the plan receipt check: $out"
    fi
  done

  rproject="$TMP/landing-retired-exact"
  landings_backup="$rproject/.oms/landings.before"
  cp "$rproject/.oms/landings.jsonl" "$landings_backup"
  # The retired plan's t1 intent is outside a new plan's scoped recovery.
  "$plan" --repo "$rproject" add --id t1 --title again --verify true >/dev/null
  "$plan" --repo "$rproject" ensure-lineage >/dev/null ||
    fail "the new plan should get its lineage id"
  out="$("$ROOT/scripts/patch-land.sh" --repo "$rproject" --recover --plan-task t1 2>&1)" ||
    fail "an older plan's intent must not block the new plan's task: $out"
  contains "$out" '0 recovered, 0 abandoned, 0 need manual' ||
    fail "an older plan's intent must not be counted for the new plan: $out"
  # An intent with no plan_id is outside any scoped recovery too.
  python3 - "$landings_backup" "$rproject/.oms/landings.jsonl" <<'PY'
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1])]
for row in rows:
    row["plan_id"] = ""
open(sys.argv[2], "w").write("".join(json.dumps(row) + "\n" for row in rows))
PY
  out="$("$ROOT/scripts/patch-land.sh" --repo "$rproject" --recover --plan-task t1 2>&1)" ||
    fail "an intent without plan_id must not be recovered under --plan-task: $out"
  contains "$out" '0 recovered, 0 abandoned, 0 need manual' ||
    fail "an intent without plan_id must not be counted under --plan-task: $out"
}

test_patch_land_abandons_a_landing_that_never_applied() {
  local project="$TMP/landing-abandoned"
  local patch="$project/change.patch"
  local base_sha patch_sha
  local out

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  base_sha="$(git -C "$project" rev-parse HEAD | tr -d '\r')"
  patch_sha="$(python3 - "$patch" <<'PY'
import hashlib, pathlib, sys
print(hashlib.sha256(pathlib.Path(sys.argv[1]).read_bytes()).hexdigest())
PY
)"
  mkdir -p "$project/.oms"
  printf '*\n' > "$project/.oms/.gitignore"
  printf '{"schema":1,"ts":"2026-07-26T00:00:00Z","landing_id":"land-never","event":"intent","patch":"%s","patch_sha":"%s","base_sha":"%s","task":"","lease":"","plan_receipt_sha":"","plan_done_receipt_sha":"","approval":"","approval_version":""}\n' \
    "$patch" "$patch_sha" "$base_sha" > "$project/.oms/landings.jsonl"

  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)"
  contains "$out" 'never applied' ||
    fail "recovery should mark an unapplied landing abandoned: $out"
  # Recovery is bookkeeping: it must never apply the patch itself.
  [ "$(git -C "$project" status --porcelain -- file.txt)" = "" ] ||
    fail "recovery must not apply anything"
  contains "$(cat "$project/.oms/landings.jsonl")" '"reason": "not-applied"' ||
    fail "the closing row should carry the not-applied reason"

  # HEAD moved past the base without the patch: still provably never applied.
  rm -f "$project/.oms/landings.jsonl"
  printf 'other\n' > "$project/other.txt"
  git -C "$project" add other.txt
  git -C "$project" -c user.name=t -c user.email=t@example.invalid commit -q -m other
  printf '{"schema":1,"ts":"2026-07-26T00:00:00Z","landing_id":"land-moved","event":"intent","patch":"%s","patch_sha":"%s","base_sha":"%s","task":"","lease":"","plan_receipt_sha":"","plan_done_receipt_sha":"","approval":"","approval_version":""}\n' \
    "$patch" "$patch_sha" "$base_sha" > "$project/.oms/landings.jsonl"
  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)" ||
    fail "a moved HEAD with the patch absent should close cleanly: $out"
  contains "$out" '1 abandoned, 0 need manual' ||
    fail "a moved HEAD with the patch absent should be abandoned: $out"
  contains "$(cat "$project/.oms/landings.jsonl")" '"reason": "head-moved-not-applied"' ||
    fail "the abandoned row should name head-moved-not-applied"

  # A task-scoped recovery leaves another task's intent alone.
  printf '{"schema":1,"ts":"2026-07-26T00:00:00Z","landing_id":"land-other","event":"intent","patch":"%s","patch_sha":"%s","base_sha":"%s","task":"other-task","lease":"","plan_receipt_sha":"","plan_done_receipt_sha":"","approval":"","approval_version":""}\n' \
    "$patch" "$patch_sha" "$base_sha" > "$project/.oms/landings.jsonl"
  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover --plan-task mine 2>&1)" ||
    fail "a scoped recovery must ignore another task's open intent: $out"
  contains "$out" '0 abandoned, 0 need manual' ||
    fail "a scoped recovery should not count another task's intent: $out"
  [ "$(wc -l < "$project/.oms/landings.jsonl" | tr -d ' ')" = 1 ] ||
    fail "a scoped recovery must not write rows for another task"

  mkdir -p "$project/.oms/plan"

  # A present but unusable shared plan stops a scoped recovery instead of
  # narrowing it to nothing; an absent plan file is the only empty scope.
  local bad_plan landings_before
  printf '{"schema":1,"ts":"2026-07-26T00:00:00Z","landing_id":"land-badplan","event":"intent","patch":"%s","patch_sha":"%s","base_sha":"%s","task":"mine","plan_id":"plan_%s","lease":"","plan_receipt_sha":"","plan_done_receipt_sha":"","approval":"","approval_version":"","panel_accept":"true"}\n' \
    "$patch" "$patch_sha" "$base_sha" "$(printf '%032d' 7)" > "$project/.oms/landings.jsonl"
  landings_before="$(cat "$project/.oms/landings.jsonl")"
  for bad_plan in '{"plan_id":' '' '[]' \
    '{"plan_id":7}' '{"plan_id":null,"tasks":[]}' '{"plan_id":"plan_00000000000000000000000000000007"}' \
    '{"plan_id":"plan_00000000000000000000000000000007","tasks":[]}'; do
    printf '%s\n' "$bad_plan" > "$project/.oms/plan/tasks.json"
    rc=0
    out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover --plan-task mine 2>&1)" || rc=$?
    [ "$rc" != 0 ] || fail "a scoped recovery with plan '$bad_plan' must fail, got 0: $out"
    contains "$out" 'tasks.json' ||
      fail "the failure should name the plan file for '$bad_plan': $out"
    [ "$(cat "$project/.oms/landings.jsonl")" = "$landings_before" ] ||
      fail "a refused scoped recovery must not write landing rows"
  done
  # A legacy plan without lineage is readable: unscoped recovery proceeds, and
  # a scoped one matches no intent instead of aborting.
  for bad_plan in '{"tasks":{}}' '{"plan_id":"","tasks":{}}' '{"plan_id":null,"tasks":{}}'; do
    printf '%s\n' "$bad_plan" > "$project/.oms/plan/tasks.json"
    rc=0
    out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover --plan-task mine 2>&1)" || rc=$?
    [ "$rc" = 0 ] && contains "$out" '0 recovered, 0 abandoned, 0 need manual' ||
      fail "a legacy plan '$bad_plan' must scope recovery to nothing, got $rc: $out"
    [ "$(cat "$project/.oms/landings.jsonl")" = "$landings_before" ] ||
      fail "a legacy-plan scoped recovery must not write landing rows"
  done
  printf '{"tasks":{}}\n' > "$project/.oms/plan/tasks.json"
  rc=0
  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)" || rc=$?
  [ "$rc" = 0 ] && contains "$out" '1 abandoned, 0 need manual' ||
    fail "a legacy plan must not abort an unscoped recovery, got $rc: $out"
  printf '%s\n' "$landings_before" > "$project/.oms/landings.jsonl"
  rm -rf "$project/.oms/plan/tasks.json"
  mkdir "$project/.oms/plan/tasks.json"
  rc=0
  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover --plan-task mine 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "a non-regular plan file must fail a scoped recovery: $out"
  rmdir "$project/.oms/plan/tasks.json"
  rc=0
  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover --plan-task mine 2>&1)" || rc=$?
  [ "$rc" = 0 ] && contains "$out" '0 recovered, 0 abandoned, 0 need manual' ||
    fail "an absent plan file is an empty scope, got $rc: $out"
  [ "$(cat "$project/.oms/landings.jsonl")" = "$landings_before" ] ||
    fail "an empty scope must not write landing rows"

  # HEAD moved and the patch is already in the tree: stays manual.
  ( cd "$project" && git apply "$patch" && git add file.txt &&
    git -c user.name=t -c user.email=t@example.invalid commit -q -m applied )
  printf '{"schema":1,"ts":"2026-07-26T00:00:00Z","landing_id":"land-present","event":"intent","patch":"%s","patch_sha":"%s","base_sha":"%s","task":"","lease":"","plan_receipt_sha":"","plan_done_receipt_sha":"","approval":"","approval_version":""}\n' \
    "$patch" "$patch_sha" "$base_sha" > "$project/.oms/landings.jsonl"
  rc=0
  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)" || rc=$?
  [ "$rc" = 1 ] || fail "a moved HEAD with the patch present must exit 1, got $rc: $out"
  contains "$out" 'HEAD no longer matches its exact intent base' ||
    fail "a moved HEAD with the patch present must stay manual: $out"
  [ "$(wc -l < "$project/.oms/landings.jsonl" | tr -d ' ')" = 1 ] ||
    fail "manual recovery must leave the intent untouched"
}

test_state_validator_rejects_parseable_but_invalid_state() {
  local project="$TMP/validate-registry"
  local out
  local rc

  make_committed_repo "$project"
  mkdir -p "$project/.oms/runs" "$project/.oms/threads" "$project/.oms/plan"
  # Every row below is valid JSON, which is all the validator used to check.
  printf '{"schema":1,"run_id":"r1","tool":"t","event":"new"}\n{"schema":1,"tool":"t","event":"new"}\n' \
    > "$project/.oms/runs/spine.jsonl"
  printf '{"schema":1,"thread":"t1","seq":1,"role":"bogus","text":"x"}\n' \
    > "$project/.oms/threads/t1.jsonl"
  printf '{"schema":1,"landing_id":"l1","event":"weird"}\n' \
    > "$project/.oms/landings.jsonl"
  printf '{"tasks":{"a":{"state":"ready","depends":["ghost"]},"b":{"state":"nonsense"}}}\n' \
    > "$project/.oms/plan/tasks.json"

  rc=0
  out="$("$ROOT/scripts/run.sh" validate --dir "$project/.oms" 2>&1)" || rc=$?
  [ "$rc" = 1 ] || fail "invalid state should exit 1, got $rc"
  contains "$out" "missing required field 'run_id'" ||
    fail "a spine row without run_id should be flagged: $out"
  contains "$out" "unknown thread role 'bogus'" ||
    fail "an unknown thread role should be flagged: $out"
  contains "$out" "event='weird' is not one of" ||
    fail "an unknown landing event should be flagged: $out"
  contains "$out" "depends on missing task 'ghost'" ||
    fail "a dangling plan dependency should be flagged: $out"
  contains "$out" "task b has unknown state 'nonsense'" ||
    fail "an unknown plan state should be flagged: $out"
}

test_state_validator_accepts_healthy_state() {
  local project="$TMP/validate-healthy"
  local rc

  make_committed_repo "$project"
  mkdir -p "$project/.oms/runs" "$project/.oms/threads" "$project/.oms/plan"
  printf '{"schema":1,"run_id":"r1","tool":"run-ledger","event":"new"}\n' \
    > "$project/.oms/runs/spine.jsonl"
  printf '{"schema":1,"thread":"t1","seq":1,"role":"question","text":"x"}\n' \
    > "$project/.oms/threads/t1.jsonl"
  printf '{"schema":1,"landing_id":"l1","event":"intent"}\n{"schema":1,"landing_id":"l1","event":"complete"}\n' \
    > "$project/.oms/landings.jsonl"
  printf '{"tasks":{"a":{"state":"done"},"b":{"state":"ready","depends":["a"]},"c":{"state":"running","depends":["a"]}}}\n' \
    > "$project/.oms/plan/tasks.json"

  rc=0
  "$ROOT/scripts/oms" run validate --dir "$project/.oms" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "healthy state must not be reported invalid (exit $rc)"
}

test_antigravity_receives_the_prompt_it_is_given() {
  local project="$TMP/agy-prompt"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local seen extra_dir limit_prompt out rc size ready caller_pid tries max_tries workdir_real tmp_target

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  # agy's --print TAKES the prompt as its value (--prompt is an alias), so a
  # prompt on stdin is dropped and the following flag becomes the prompt. This
  # stub records what the CLI actually received.
  cat > "$bin_dir/agy" <<'EOF'
#!/usr/bin/env bash
prompt=""
: > "$HOME/agy-add-dirs"
rm -f "$HOME/agy-prompt-file" "$HOME/agy-prompt-modes"
while [ "$#" -gt 0 ]; do
  case "$1" in
    --print|--prompt|-p) prompt="${2:-}"; shift 2 ;;
    --add-dir) printf '%s\n' "${2:-}" >> "$HOME/agy-add-dirs"; shift 2 ;;
    *) shift ;;
  esac
done
printf '%s' "$prompt" > "$HOME/agy-received"
extra_dir="$(sed -n '2p' "$HOME/agy-add-dirs")"
if [ -n "$extra_dir" ] && [ -f "$extra_dir/prompt.md" ]; then
  cp "$extra_dir/prompt.md" "$HOME/agy-prompt-file"
  python3 - "$extra_dir" "$extra_dir/prompt.md" > "$HOME/agy-prompt-modes" <<'PY'
import os, stat, sys
print("%o %o" % (stat.S_IMODE(os.lstat(sys.argv[1]).st_mode), stat.S_IMODE(os.lstat(sys.argv[2]).st_mode)))
PY
fi
[ -z "$prompt" ] || [ -z "${OMS_TEST_AGY_READY_FILE:-}" ] || printf '%s\n' "${extra_dir:-none}" > "$OMS_TEST_AGY_READY_FILE"
[ -z "$prompt" ] || [ "${OMS_TEST_AGY_SLEEP:-0}" != 1 ] || sleep "${OMS_TEST_AGY_SLEEP_SEC:-5}"
[ -z "$prompt" ] || [ "${OMS_TEST_AGY_FAIL:-0}" != 1 ] || exit 17
echo "Sharding by file keeps streaming inputs balanced; seed the sampler per rank."
echo "Evidence: the loader contract. Next: pin the seed in the training config."
EOF
  chmod +x "$bin_dir/agy"
  wrap_agy_stub "$bin_dir/agy"

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/agent-call.sh" --to antigravity --repo "$project" \
    --prompt "UNIQUE-PROMPT-MARKER which loader?" >/dev/null 2>&1 ||
    fail "antigravity call should succeed"

  assert_one_artifact_contains "$project/.oms/artifacts/call" 'antigravity-*.md' 'usage detail:'
  seen="$(cat "$home_dir/agy-received" 2>/dev/null || true)"
  contains "$seen" 'UNIQUE-PROMPT-MARKER' ||
    fail "antigravity must receive the composed prompt, got: $seen"
  if printf '%s' "$seen" | grep >/dev/null -Fx -- '--sandbox'; then
    fail "the flag after --print must not become the prompt"
  fi
  [ "$(wc -l < "$home_dir/agy-add-dirs" | tr -d ' ')" = 1 ] ||
    fail "small prompt must not add an extra prompt directory"
  [ ! -e "$home_dir/agy-prompt-file" ] ||
    fail "small prompt must stay on argv"

  limit_prompt="$project/limit-prompt.txt"
  out="$project/attempt-out.txt"
  for size in 0 120000; do
    if [ "$size" -eq 0 ]; then
      : > "$limit_prompt"
    else
      awk -v bytes="$size" 'BEGIN { for (i = 0; i < bytes; i++) printf "x" }' > "$limit_prompt"
    fi
    HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      bash -c '. "$1/scripts/lib/peer-common.sh"
        ma_provider_attempt antigravity read "$2" "$3" "$4" provider-default "" agent-call "$4" "agy-edge"' \
      _ "$ROOT" "$limit_prompt" "$out" "$project" ||
      fail "antigravity prompt of $size bytes should succeed on argv"
    [ "$(wc -c < "$home_dir/agy-received" | tr -d ' ')" = "$size" ] ||
      fail "antigravity prompt of $size bytes should arrive via --print unchanged"
    [ "$(wc -l < "$home_dir/agy-add-dirs" | tr -d ' ')" = 1 ] ||
      fail "antigravity prompt of $size bytes must not add an extra --add-dir"
  done

  awk 'BEGIN {
    printf "OVERSIZED-BEGIN:"
    for (i = 0; i < 120000; i++) printf "y"
    printf ":OVERSIZED-END\n"
  }' > "$limit_prompt"
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/agent-call.sh" --to antigravity --repo "$project" \
    --prompt-file "$limit_prompt" >/dev/null 2>&1 ||
    fail "antigravity call above 120000 bytes should succeed via prompt file"
  seen="$(cat "$home_dir/agy-received" 2>/dev/null || true)"
  extra_dir="$(sed -n '2p' "$home_dir/agy-add-dirs")"
  [ -n "$extra_dir" ] || fail "oversized prompt must pass an extra --add-dir"
  case "$extra_dir" in
    "$project"/*) fail "oversized prompt directory must live outside the worktree: $extra_dir" ;;
    /*) ;;
    *) fail "oversized prompt directory must be an absolute path: $extra_dir" ;;
  esac
  [ "${#seen}" -lt 256 ] || fail "oversized prompt must pass a short --print value, got ${#seen}B"
  contains "$seen" "$extra_dir/prompt.md" ||
    fail "short --print value must name the absolute prompt file path: $seen"
  [ "$(cat "$home_dir/agy-prompt-modes" 2>/dev/null || true)" = "700 600" ] ||
    fail "oversized prompt dir and file must have modes 0700 and 0600, got: $(cat "$home_dir/agy-prompt-modes" 2>/dev/null || true)"
  contains "$(cat "$home_dir/agy-prompt-file" 2>/dev/null || true)" 'OVERSIZED-BEGIN:' ||
    fail "staged prompt file must contain the beginning of the composed prompt"
  contains "$(cat "$home_dir/agy-prompt-file" 2>/dev/null || true)" ':OVERSIZED-END' ||
    fail "staged prompt file must contain the end of the composed prompt"
  [ ! -e "$extra_dir" ] || fail "oversized prompt directory must be removed after the run: $extra_dir"

  awk 'BEGIN { for (i = 0; i < 120001; i++) printf "z" }' > "$limit_prompt"
  mkdir -p "$TMP/rel-tmp-parent/sub"
  (
    cd "$TMP/rel-tmp-parent" &&
    TMPDIR="sub" HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      bash -c '. "$1/scripts/lib/peer-common.sh"
        ma_provider_attempt antigravity read "$2" "$3" "$4" provider-default "" agent-call "$4" "agy-120001"' \
      _ "$ROOT" "$limit_prompt" "$out" "$project"
  ) || fail "antigravity prompt of 120001 bytes should succeed"
  extra_dir="$(sed -n '2p' "$home_dir/agy-add-dirs")"
  case "$extra_dir" in
    /*) ;;
    *) fail "relative TMPDIR must still produce an absolute --add-dir path: $extra_dir" ;;
  esac
  cmp -s "$limit_prompt" "$home_dir/agy-prompt-file" ||
    fail "staged prompt file must match the exact 120001-byte prompt"
  [ ! -e "$extra_dir" ] || fail "oversized prompt directory must be removed after 120001-byte run"

  rc=0
  OMS_TEST_AGY_FAIL=1 HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    bash -c '. "$1/scripts/lib/peer-common.sh"
      ma_provider_attempt antigravity read "$2" "$3" "$4" provider-default "" agent-call "$4" "agy-fail"' \
    _ "$ROOT" "$limit_prompt" "$out" "$project" >/dev/null 2>&1 || rc=$?
  [ "$rc" -ne 0 ] || fail "failing agy stub must return non-zero"
  extra_dir="$(sed -n '2p' "$home_dir/agy-add-dirs")"
  [ -n "$extra_dir" ] || fail "failing oversized run must still record its extra --add-dir"
  [ ! -e "$extra_dir" ] || fail "oversized prompt directory must be removed on failure exit: $extra_dir"

  rc=0
  OMS_PEER_TIMEOUT=1 OMS_TEST_AGY_SLEEP=1 HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    bash -c '. "$1/scripts/lib/peer-common.sh"
      ma_provider_attempt antigravity read "$2" "$3" "$4" provider-default "" agent-call "$4" "agy-timeout"' \
    _ "$ROOT" "$limit_prompt" "$out" "$project" >/dev/null 2>&1 || rc=$?
  [ "$rc" -eq 124 ] || fail "timed-out agy stub must exit 124, got $rc"
  extra_dir="$(sed -n '2p' "$home_dir/agy-add-dirs")"
  [ -n "$extra_dir" ] || fail "timed-out oversized run must still record its extra --add-dir"
  [ ! -e "$extra_dir" ] || fail "oversized prompt directory must be removed on timeout exit: $extra_dir"

  rc=0
  OMS_LIB_TMPDIR="$project/missing-tmpdir/child" TMPDIR="$project/missing-tmpdir/child" HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    bash -c '. "$1/scripts/lib/peer-common.sh"
      ma_provider_attempt antigravity read "$2" "$3" "$4" provider-default "" agent-call "$4" "agy-no-tmp"' \
    _ "$ROOT" "$limit_prompt" "$out" "$project" >/dev/null 2>&1 || rc=$?
  [ "$rc" -eq 2 ] || fail "unwritable TMPDIR on oversized prompt must exit 2, got $rc"
  grep -Fq 'error: could not allocate private Antigravity prompt' "$out" ||
    fail "unwritable TMPDIR should report prompt allocation failure: $(cat "$out" 2>/dev/null || true)"

  mkdir -p "$project/wt-local-tmp"
  workdir_real="$(cd "$project" && pwd -P)"
  rc=0
  TMPDIR="$project" HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    bash -c '. "$1/scripts/lib/peer-common.sh"
      ma_provider_attempt antigravity read "$2" "$3" "$4" provider-default "" agent-call "$4" "agy-wt-missing"' \
    _ "$ROOT" "$limit_prompt" "$out" "$project/missing-worktree" >/dev/null 2>&1 || rc=$?
  [ "$rc" -eq 2 ] || fail "missing workdir on oversized prompt must exit 2, got $rc"
  grep -Fq 'error: could not resolve Antigravity worktree path' "$out" ||
    fail "missing workdir should report worktree path resolution failure: $(cat "$out" 2>/dev/null || true)"

  for tmp_target in "$project" "$project/wt-local-tmp"; do
    OMS_LIB_TMPDIR="$project/wt-local-tmp" TMPDIR="$tmp_target" HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      bash -c '. "$1/scripts/lib/peer-common.sh"
        ma_provider_attempt antigravity read "$2" "$3" "$4" provider-default "" agent-call "$4" "agy-wt-tmp"' \
      _ "$ROOT" "$limit_prompt" "$out" "$project" ||
      fail "worktree-local TMPDIR ($tmp_target) on oversized prompt should relocate outside the worktree"
    extra_dir="$(sed -n '2p' "$home_dir/agy-add-dirs")"
    [ -n "$extra_dir" ] || fail "worktree-local TMPDIR run must still pass an extra --add-dir"
    case "$extra_dir" in
      "$project"|"$project"/*|"$workdir_real"|"$workdir_real"/*)
        fail "worktree-local TMPDIR must not stage the prompt inside the worktree: $extra_dir"
        ;;
      /*) ;;
      *) fail "worktree-local TMPDIR fallback must still produce an absolute --add-dir path: $extra_dir" ;;
    esac
    [ ! -e "$extra_dir" ] || fail "relocated prompt directory must be removed after the run: $extra_dir"
  done
  rmdir "$project/wt-local-tmp"

  rc=0
  OMS_PEER_INTERACTIVE=1 HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    bash -c '. "$1/scripts/lib/peer-common.sh"
      ma_provider_attempt antigravity write "$2" "$3" "$4" provider-default "" peer-delegate "$4" "agy-interactive-over"' \
    _ "$ROOT" "$limit_prompt" "$out" "$project" >/dev/null 2>&1 || rc=$?
  [ "$rc" -eq 2 ] || fail "oversized interactive antigravity attempt must exit 2, got $rc"
  grep -Fq 'error: prompt is 120001B; the antigravity transport carries it as one argv element (limit ~128KiB)' "$out" ||
    fail "oversized interactive antigravity attempt must report explicit size refusal: $(cat "$out" 2>/dev/null || true)"

  ready="$TMP/agy-term-ready"
  rm -f "$ready"
  OMS_TEST_AGY_READY_FILE="$ready" OMS_TEST_AGY_SLEEP=1 OMS_TEST_AGY_SLEEP_SEC=30 \
    HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/agent-call.sh" --to antigravity --repo "$project" \
    --prompt-file "$limit_prompt" >/dev/null 2>&1 &
  caller_pid=$!
  tries=0
  max_tries=$(( ${OMS_TEST_CALL_TIMEOUT:-120} * 20 ))
  while [ ! -s "$ready" ] && kill -0 "$caller_pid" 2>/dev/null && [ "$tries" -lt "$max_tries" ]; do
    sleep 0.05
    tries=$((tries + 1))
  done
  [ -s "$ready" ] || {
    kill -KILL "$caller_pid" 2>/dev/null || true
    wait "$caller_pid" 2>/dev/null || true
    fail "timed out waiting for agy stub to stage oversized prompt before TERM"
  }
  extra_dir="$(sed -n '1p' "$ready")"
  [ -n "$extra_dir" ] && [ "$extra_dir" != "none" ] || {
    kill -KILL "$caller_pid" 2>/dev/null || true
    wait "$caller_pid" 2>/dev/null || true
    fail "TERM cleanup test must observe a live staged prompt directory"
  }
  kill -TERM "$caller_pid" 2>/dev/null || true
  rc=0
  wait "$caller_pid" || rc=$?
  [ "$rc" -ne 0 ] || fail "signaled agent-call must exit non-zero"
  [ ! -e "$extra_dir" ] || fail "staged prompt directory must be removed when caller receives TERM: $extra_dir"

  rm -f "$ready"
  # Refuse before the provider can stage a prompt when grants are missing.
  local preflight_rc=0
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_DELEGATE_WORKTREE_ROOT="$TMP/agy-delegate-wt" \
    "$ROOT/scripts/peer-delegate.sh" --to antigravity --repo "$project" \
    --brief-file "$limit_prompt" >"$project/preflight" 2>&1 || preflight_rc=$?
  [ "$preflight_rc" = 2 ] || fail "missing delegate grant must exit 2"
  grep -Fq 'oms provider-permissions --apply --profile delegate' "$project/preflight" ||
    fail "missing delegate grant must name its remedy"
  HOME="$home_dir" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_DELEGATE_WORKTREE_ROOT="$TMP/agy-delegate-wt" \
    "$ROOT/scripts/provider-permissions.sh" --apply --profile delegate >/dev/null ||
    fail "could not prepare delegate permissions for transport fixture"
  OMS_TEST_AGY_READY_FILE="$ready" OMS_TEST_AGY_SLEEP=1 OMS_TEST_AGY_SLEEP_SEC=30 \
    OMS_LIB_TMPDIR="$TMP" OMS_DELEGATE_WORKTREE_ROOT="$TMP/agy-delegate-wt" \
    HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --to antigravity --repo "$project" \
    --brief-file "$limit_prompt" >/dev/null 2>&1 &
  caller_pid=$!
  tries=0
  while [ ! -s "$ready" ] && kill -0 "$caller_pid" 2>/dev/null && [ "$tries" -lt "$max_tries" ]; do
    sleep 0.05
    tries=$((tries + 1))
  done
  [ -s "$ready" ] || {
    kill -KILL "$caller_pid" 2>/dev/null || true
    wait "$caller_pid" 2>/dev/null || true
    fail "timed out waiting for peer-delegate agy stub to stage oversized prompt before TERM"
  }
  extra_dir="$(sed -n '1p' "$ready")"
  [ -n "$extra_dir" ] && [ "$extra_dir" != "none" ] && [ -d "$extra_dir" ] || {
    kill -KILL "$caller_pid" 2>/dev/null || true
    wait "$caller_pid" 2>/dev/null || true
    fail "peer-delegate TERM cleanup test must observe a live staged prompt directory"
  }
  kill -TERM "$caller_pid" 2>/dev/null || true
  rc=0
  wait "$caller_pid" || rc=$?
  [ "$rc" -ne 0 ] || {
    rm -rf "$TMP/agy-delegate-wt"
    git -C "$project" worktree prune >/dev/null 2>&1 || true
    fail "signaled peer-delegate must exit non-zero"
  }
  [ ! -e "$extra_dir" ] || {
    rm -rf "$TMP/agy-delegate-wt"
    git -C "$project" worktree prune >/dev/null 2>&1 || true
    fail "staged prompt directory must be removed when peer-delegate receives TERM: $extra_dir"
  }
  rm -rf "$TMP/agy-delegate-wt"
  git -C "$project" worktree prune >/dev/null 2>&1 || true
}

test_consult_panel_asks_one_provider_at_several_tiers() {
  local project="$TMP/consult-panel"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local out

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  for provider in codex agy; do
    cat > "$bin_dir/$provider" <<'EOF'
#!/usr/bin/env bash
echo "Shard by file for streaming inputs and seed the sampler per rank so DDP"
echo "workers never duplicate shards. Evidence: the loader contract. Next: pin"
echo "the seed in the training config before the next run."
EOF
    chmod +x "$bin_dir/$provider"
    [ "$provider" != agy ] || wrap_agy_stub "$bin_dir/$provider"
  done

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_AGENT=claude "$ROOT/scripts/consult.sh" --repo "$project" \
    --to codex:model=gpt-5.6-sol --to codex:model=gpt-5.6-terra \
    --to "antigravity:model=Gemini 3.6 Flash (High)" \
    "which loader?" 2>&1)" || fail "panel consult should succeed: $out"

  [ "$(printf '%s\n' "$out" | grep -c 'Shard by file for streaming inputs')" = 3 ] ||
    fail "all three panel answers must remain visible exactly once: $out"

  contains "$out" '3/3 target(s) answered, 2 independent model family(ies)' ||
    fail "the panel should report answers and independent families: $out"

  assert_one_artifact_contains "$project/.oms/artifacts/consult" 'antigravity-*.md' 'usage detail:'
  "$ROOT/scripts/thread.sh" --repo "$project" show --json | python3 -c '
import json, sys
turns = json.load(sys.stdin)["turns"]
answers = [t for t in turns if t["role"] == "answer"]
# One provider asked twice must produce two separately recorded answers, each
# naming the model that produced it.
models = sorted(a.get("model", "") for a in answers)
assert len(answers) == 3, answers
assert models == sorted(["gpt-5.6-sol", "gpt-5.6-terra", "Gemini 3.6 Flash (High)"]), models
assert [t["role"] for t in turns].count("question") == 1, turns
' || fail "each panel member should be recorded with its own model"
}

