test_worker_tier_follows_the_role_before_the_phase() {
  local out

  # Selection is catalog-first: a role or operation label never chooses a
  # model; only an explicit request does, and everything else is the
  # provider's own default.
  out="$(bash -c '. "'"$ROOT"'/scripts/lib/model-routing.sh"
    OMS_MODEL_ROLE=repo-auditor OMS_MODEL_OPERATION=decision oms_model_prepare codex >/dev/null
    printf "%s %s %s" "$OMS_MODEL_RESOLVED_CLASS" "$OMS_MODEL_CLASS_REASON" "$OMS_MODEL_PRIMARY"')"
  [ "$out" = "provider-default provider-default provider-default" ] ||
    fail "a role or phase must not select a model, got: $out"

  out="$(bash -c '. "'"$ROOT"'/scripts/lib/model-routing.sh"
    OMS_MODEL_EXPLICIT=named-model oms_model_prepare codex >/dev/null
    printf "%s %s %s" "$OMS_MODEL_RESOLVED_CLASS" "$OMS_MODEL_CLASS_REASON" "$OMS_MODEL_PRIMARY"')"
  [ "$out" = "explicit explicit named-model" ] ||
    fail "an explicit model must be used as given, got: $out"
}

test_agent_call_declares_its_work_phase() {
  local project="$TMP/phase-routing"
  local artifact

  make_committed_repo "$project"
  # Without an explicit model the provider default runs, and the artifact
  # says so instead of implying a harness choice.
  ( cd "$project" && OH_MY_SETTING_CALL_DRY_RUN=1 "$ROOT/scripts/agent-call.sh" \
    --to codex --repo "$project" --prompt "plain" >/dev/null )
  artifact="$(ls -t "$project"/.oms/artifacts/call/*plain*.md | sed -n '1p')"
  grep -Fq 'model-route: class=provider-default (provider-default) primary=provider-default' "$artifact" ||
    fail "an unrequested pass should record the provider default: $(grep -h '^model-route' "$artifact")"

  ( cd "$project" && OH_MY_SETTING_CALL_DRY_RUN=1 "$ROOT/scripts/agent-call.sh" \
    --to codex --repo "$project" --model named-model --prompt "declared" >/dev/null )
  artifact="$(ls -t "$project"/.oms/artifacts/call/*declared*.md | sed -n '1p')"
  grep -Fq 'model-route: class=explicit (explicit) primary=named-model' "$artifact" ||
    fail "an explicit model should be recorded as given: $(grep -h '^model-route' "$artifact")"
}

test_patch_land_completes_only_when_its_records_land() {
  local project="$TMP/landing-receipts"
  local patch="$TMP/landing-receipts.patch"
  local fault_bin="$TMP/landing-lineage-fault-bin"
  local real_git
  local out
  local rc=0

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  mkdir -p "$project/.oms/artifacts"
  printf '*\n' > "$project/.oms/.gitignore"
  : > "$project/.oms/artifacts/index.jsonl"

  # Admission and publication need the index to remain writable. Inject the
  # failure only after the real apply to this fixture succeeds, immediately
  # before patch-land records its lineage row.
  real_git="$(command -v git)"
  mkdir -p "$fault_bin"
  cat > "$fault_bin/git" <<'SH'
#!/usr/bin/env bash
set -euo pipefail
real_git="${OMS_TEST_REAL_GIT:?}"
project="${OMS_TEST_LANDING_PROJECT:?}"
index="${OMS_TEST_LANDING_INDEX:?}"
marker="${OMS_TEST_LANDING_FAULT_MARKER:?}"
if [ "$#" -eq 5 ] && [ "$1" = "-C" ] && [ "$2" = "$project" ] &&
   [ "$3" = "apply" ] && [ "$4" = "--binary" ]; then
  if "$real_git" "$@"; then
    chmod 444 "$index"
    : > "$marker"
    exit 0
  else
    exit $?
  fi
fi
exec "$real_git" "$@"
SH
  chmod +x "$fault_bin/git"

  out="$(PATH="$fault_bin:$PATH" OMS_TEST_REAL_GIT="$real_git" \
    OMS_TEST_LANDING_PROJECT="$project" \
    OMS_TEST_LANDING_INDEX="$project/.oms/artifacts/index.jsonl" \
    OMS_TEST_LANDING_FAULT_MARKER="$TMP/lineage-fault-injected" \
    "$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" 2>&1)" || rc=$?
  [ -f "$TMP/lineage-fault-injected" ] ||
    fail "the lineage failure must be injected after the real git apply"
  [ "$(cat "$project/file.txt")" = "$(printf 'base\nadded')" ] ||
    fail "the real patch must be applied before lineage failure"
  [ "$rc" -ne 0 ] ||
    fail "an applied patch with missing receipts must not report terminal success: $out"
  contains "$out" 'records are incomplete' ||
    fail "an unwritable lineage row must be reported: $out"
  python3 - "$project/.oms/landings.jsonl" <<'PY' || fail "a land with missing records must not be complete"
import json, sys
events = [json.loads(line)["event"] for line in open(sys.argv[1])
          if line.strip() and not json.loads(line)["event"].startswith("capture-")]
assert events[-1] == "applied-pending-receipt", events
PY
  "$ROOT/scripts/state.sh" --repo "$project" | grep -F 'Interrupted landings' > /dev/null ||
    fail "a pending-receipt landing should stay visible in state"

  chmod 644 "$project/.oms/artifacts/index.jsonl"
  "$ROOT/scripts/patch-land.sh" --repo "$project" --recover >/dev/null 2>&1 ||
    fail "recovery should finish the pending landing"
  python3 - "$project/.oms/landings.jsonl" <<'PY' || fail "recovery should complete it once the records land"
import json, sys
events = [json.loads(line)["event"] for line in open(sys.argv[1])
          if line.strip() and not json.loads(line)["event"].startswith("capture-")]
assert events[-1] == "complete", events
PY
}

test_patch_land_refuses_a_tree_that_moved_during_admission() {
  local project="$TMP/landing-toctou"
  local patch="$TMP/landing-toctou.patch"
  local out
  local rc

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )

  # Admission verifies a worktree built from this base; a concurrent writer
  # moving HEAD means what would land was never the combination that passed.
  rc=0
  out="$("$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" \
    --verify "git -C $project -c user.email=t@example.com -c user.name=t commit --allow-empty -q -m concurrent" 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "landing onto a moved tree should fail: $out"
  contains "$out" 'tree moved during admission' ||
    fail "the refusal should name the race: $out"
  [ "$(git -C "$project" status --porcelain -- file.txt)" = "" ] ||
    fail "nothing should have been applied"
}

make_council_stubs() {  # make_council_stubs BIN_DIR
  local bin_dir="$1"
  local provider

  mkdir -p "$bin_dir"
  for provider in codex claude agy; do
    cat > "$bin_dir/$provider" <<'EOF'
#!/usr/bin/env bash
echo "Verdict: the change is safe to land. Evidence: the loader contract pins the"
echo "sampler seed per rank, so DDP workers cannot duplicate shards, and the diff"
echo "touches only the file body. Risk: none beyond the missing regression test."
echo "Next: run the smoke suite, then land it."
EOF
    chmod +x "$bin_dir/$provider"
    [ "$provider" != agy ] || wrap_agy_stub "$bin_dir/$provider"
  done
}

