    fail "a provider that merely omitted the line keeps the plain message: $out"
}

# smoke-weight: 5
test_delegate_detects_a_worker_writing_outside_its_worktree() {
  local project="$TMP/worker-guard"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local out
  local rc
  local planted_usage='{"provider":"codex","usage":{"reports":1,"measurement":"provider-reported","input_tokens":10,"output_tokens":999,"cache_read_tokens":null,"cache_write_tokens":null,"tool_calls":null,"cache_in_input":null}}'

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  # Scope checks only inspect the returned patch, so a worker that edits the
  # primary worktree by absolute path used to be invisible.
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<EOF
#!/usr/bin/env bash
printf 'written by the worker\n' >> "$project/file.txt"
echo "done"
echo 'usage detail: {"provider":"codex","output_tokens":37}'
EOF

  rc=0
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_WORKER_GUARD_STRICT=1 OMS_INDEX_PROVIDER_USAGE_JSON="$planted_usage" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" \
    --to codex --prompt x --no-verify 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "a worker writing to the primary tree should fail a strict run: $out"
  contains "$out" 'changed protected state outside its worktree: tracked' ||
    fail "the violation should name the surface: $out"
  contains "$out" 'worktree kept at' ||
    fail "the evidence worktree should be preserved: $out"
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "guard-stopped delegate usage missing from artifact index"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1]) if line.strip()]
row = next(row for row in reversed(rows) if row.get("exit") == 1)
assert row.get("provider_usage", {}).get("output_tokens") == 37, row
PY

  # The startup scrub must also protect ordinary rows, where there is no
  # guard-specific capture assignment to replace a caller's annotation.
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
printf 'delegated output\n' > worker-output.txt
echo 'usage detail: {"provider":"codex","output_tokens":37}'
EOF
  rc=0
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_INDEX_PROVIDER_USAGE_JSON="$planted_usage" "$ROOT/scripts/peer-delegate.sh" \
    --repo "$project" --to codex --prompt 'Normal delegate with usage' --no-verify 2>&1)" || rc=$?
  [ "$rc" = 0 ] || fail "normal delegate should succeed with a planted annotation, got $rc: $out"
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "caller usage annotation replaced the provider usage"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1]) if line.strip()]
row = next(row for row in reversed(rows) if row.get("exit") == 0)
assert row.get("provider_usage", {}).get("output_tokens") == 37, row
PY

  mkdir -p "$project/.oms/artifacts"
  printf '# malformed usage fixture\n\n## Output\n\nworker failed\n' > "$project/.oms/artifacts/malformed-usage.md"
  if ! OMS_INDEX_PROVIDER_USAGE_JSON='not-json' bash -c \
    '. "$1"; ma_append_artifact_index "$2" delegate codex 1 "$3" "" "" ""' \
    _ "$ROOT/scripts/lib/peer-common.sh" "$project" "$project/.oms/artifacts/malformed-usage.md" \
    > "$project/malformed-index.out" 2> "$project/malformed-index.err"; then
    fail "malformed provider usage should not prevent an index row"
  fi
  grep -Fq 'warning: invalid provider usage payload; usage omitted' "$project/malformed-index.err" ||
    fail "malformed provider usage should warn before the row is retained"
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "malformed usage row was omitted or annotated"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1]) if line.strip()]
row = rows[-1]
assert row.get("artifact", "").endswith("/malformed-usage.md"), row
assert row.get("exit") == 1 and "provider_usage" not in row, row
PY

  # Detection, not prevention: say so by leaving the write visible.
  grep -Fq 'written by the worker' "$project/file.txt" ||
    fail "the guard cannot prevent the write, only report it"
}

# smoke-weight: 6
test_delegate_detects_git_config_and_hook_tampering() {
  local project="$TMP/worker-guard-config"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local out
  local rc

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<EOF
#!/usr/bin/env bash
git -C "$project" config --local oms.tampered yes
printf '#!/bin/sh\nexit 0\n' > "$project/.git/hooks/pre-commit"
chmod +x "$project/.git/hooks/pre-commit"
echo "done"
EOF

  rc=0
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "config and hook tampering should fail the run: $out"
  contains "$out" 'config' ||
    fail "local git config changes should be named: $out"
  printf '%s' "$out" | grep >/dev/null -E 'hooks|execution-state' ||
    fail "an installed hook/config mutation should name the earliest boundary: $out"

  python3 - "$project" "$ROOT/scripts/lib" <<'PY' || fail "guard hint should be recorded in the artifact and ledger"
import json, sys
from pathlib import Path
sys.path.insert(0, sys.argv[2])
from peer_artifacts import artifact_sections
repo = Path(sys.argv[1])
index = [json.loads(line) for line in (repo / ".oms/artifacts/index.jsonl").read_text().splitlines()]
answer, code = artifact_sections(repo / index[-1]["artifact"])
assert not list((repo / '.oms/locks/canonical-sync.d').iterdir()), 'guard failure leaked its shared lock'
hint = "Protected surfaces changed outside this worker's worktree during the run."
assert code == "1" and hint in answer, (code, answer)
assert "Inspect the preserved evidence and re-dispatch from a fresh base after the concurrent change." in answer, answer
assert "`" not in answer and "git add" not in answer and "git diff" not in answer, answer
failures = [json.loads(line) for line in (repo / ".oms/failures.jsonl").read_text().splitlines()]
failure = [row for row in failures if row.get("cmd") == "peer-delegate --to codex worker-authority"][-1]
assert failure["failure_code"] == "guard_parent_interference", failure
assert "execution-state" in failure["summary"] and "plan" in failure["next"], failure
assert "Inspect the preserved evidence and re-dispatch from a fresh base after the concurrent change." in failure["next"], failure
assert "`" not in failure["next"] and "git add" not in failure["next"] and "git diff" not in failure["next"], failure
PY

  # The refusal is durable memory, not just a message.
  ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" list --unresolved ) |
    grep -F 'worker guard stopped run' > /dev/null ||
    fail "the violation should be recorded in the fail-ledger"
  if printf '%s' "$out" | grep -F 'oms sync-shared' >/dev/null; then
    fail "a config-only change should not blame a main-checkout commit: $out"
  fi

  printf '#!/usr/bin/env bash\necho done\n' > "$bin_dir/codex"
  rc=0
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_WORKER_GUARD_OFF=1 "$ROOT/scripts/peer-delegate.sh" --repo "$project" \
    --to codex --prompt x --no-verify 2>&1)" || rc=$?
  [ "$rc" = 0 ] || fail "unguarded delegate should finish: $out"
  ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" list --unresolved ) |
    grep -F 'worker guard stopped run' > /dev/null ||
    fail "an unguarded run must not resolve the violation"

  python3 - "$project/.oms/failures.jsonl" <<'PY' || fail "timed out waiting for a later guard snapshot"
import datetime, json, os, sys, time
rows = [json.loads(line) for line in open(sys.argv[1]) if line.strip()]
stamp = next(row['ts'] for row in reversed(rows) if row.get('cmd') == 'peer-delegate --to codex worker-authority')
deadline = time.monotonic() + int(os.environ.get('OMS_TEST_CALL_TIMEOUT', '120'))
while datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ') <= stamp:
    if time.monotonic() >= deadline:
        sys.exit(1)
    time.sleep(0.05)
PY
  rc=0
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || rc=$?
  [ "$rc" = 0 ] || fail "clean guarded delegate should finish: $out"
  if ( cd "$project" && "$ROOT/scripts/fail-ledger.sh" list --unresolved ) |
    grep -F 'worker guard stopped run' > /dev/null; then
    fail "a clean guarded run should resolve the violation"
  fi
  rc=0
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || rc=$?
  [ "$rc" = 0 ] || fail "second clean guarded delegate should finish: $out"
  python3 - "$project/.oms/failures.jsonl" <<'PY' || fail "clean runs should resolve the violation only once"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1]) if line.strip()]
fp = next(row['fingerprint'] for row in rows if row.get('cmd') == 'peer-delegate --to codex worker-authority')
assert sum(row.get('event') == 'resolved' and row.get('fingerprint') == fp for row in rows) == 1
PY

  # A commit in the main checkout moves its branch ref; the hint names the
  # usual cause and the remedy.
  cat > "$bin_dir/codex" <<EOF
#!/usr/bin/env bash
git -C "$project" commit --allow-empty -qm 'test: main checkout moved'
echo "done"
EOF
  rc=0
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "a main-checkout commit should fail the run: $out"
  python3 - "$project" <<'PY' || fail "main-checkout hint missing from the fail-ledger"
import json, sys
from pathlib import Path
rows = [json.loads(l) for l in (Path(sys.argv[1]) / ".oms/failures.jsonl").read_text().splitlines()]
row = [r for r in rows if r.get("cmd") == "peer-delegate --to codex worker-authority"][-1]
assert "commit, checkout or fast-forward" in row["next"] and "oms sync-shared" in row["next"], row
assert "`" not in row["next"], row
PY

  # Branch-tracking relief stops at the shape Git writes: a remote that is not
  # configured, or an indented "[core]" Git reads as a new section, stays hard.
  local p
  for p in "$project-remote" "$project-indent"; do
    make_committed_repo "$p"
    case "$p" in
      *-remote) printf 'git -C "%s" config branch.x.remote /tmp/elsewhere\n' "$p" ;;
      *) printf 'printf "[branch \\"x\\"]\\n\\tremote = .\\n\\tmerge = refs/heads/main\\n\\t[core]\\n\\tfsmonitor = /bin/true\\n" >> "%s/.git/config"\n' "$p" ;;
    esac | { printf '#!/usr/bin/env bash\n'; cat; printf 'echo done\n'; } > "$bin_dir/codex"
    rc=0
    out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      "$ROOT/scripts/peer-delegate.sh" --repo "$p" --to codex --prompt x \
      --no-verify 2>&1)" || rc=$?
    [ "$rc" != 0 ] || fail "a non-tracking config delta must fail the run ($p): $out"
    contains "$out" 'execution-state' ||
      fail "a non-tracking config delta should name execution-state ($p): $out"
  done
}

# smoke-weight: 26
test_delegate_execution_config_guard_runs_before_git_capture() {
  local project="$TMP/worker-exec-config"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local marker="$project/marker-fired"
  local base_config="$TMP/worker-exec-config.base"
  local source_clone="$project/source-clone"
  local source_snapshot="$TMP/worker-exec-config-source-snapshot"
  local source_detail="$TMP/worker-exec-config-source-detail"
  local source_sha source_out source_detail_line
  local out rc=0 mode

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  printf '/marker-fired\n' >> "$project/.git/info/exclude"
  cp "$project/.git/config" "$base_config"

  # Exercise real Git syntax, including named and deprecated dotted
  # subsections. Each worker also edits the primary tree: a vulnerable guard
  # would run the planted command while trying to capture that mutation.
  for mode in fsmonitor diff-external diff-driver-escaped diff-driver-tab \
    filter-quoted filter-dotted filter-tab includeif includeif-tab hook-config staged-index; do
    cat > "$bin_dir/codex" <<EOF
#!/usr/bin/env bash
cat >/dev/null
printf 'primary mutation\n' >> "$project/file.txt"
case "$mode" in
  fsmonitor)
    git -C "$project" config --local core.fsmonitor "$bin_dir/marker"
    ;;
  diff-external)
    git -C "$project" config --local diff.external "$bin_dir/marker"
    ;;
  diff-driver-escaped)
    printf '\n[DiFf "hostile\\"quoted"]\n\ttextconv = $bin_dir/marker\n' >> "$project/.git/config"
    ;;
  diff-driver-tab)
    printf '\n[diff\t"hostile"]\n\tcommand = $bin_dir/marker\n' >> "$project/.git/config"
    ;;
  filter-quoted)
    git -C "$project" config --local filter.hostile.clean "$bin_dir/marker"
    ;;
  filter-dotted)
    printf '\n[filter.hostile]\n\tclean = $bin_dir/marker\n' >> "$project/.git/config"
    ;;
  filter-tab)
    printf '\n[filter\t"hostile"]\n\tprocess = $bin_dir/marker\n' >> "$project/.git/config"
    ;;
  includeif)
    printf '\n[includeIf "gitdir:**"]\n\tpath = $project/missing.inc\n' >> "$project/.git/config"
    ;;
  includeif-tab)
    printf '\n[includeIf\t"gitdir:**"]\n\tpath = $project/missing.inc\n' >> "$project/.git/config"
    ;;
  hook-config)
    printf '\n[hook "x"]\n\tcommand = $bin_dir/marker\n\tevent = post-checkout\n' >> "$project/.git/config"
    ;;
  staged-index)
    git -C "$project" add file.txt
    ;;
esac
echo done
EOF
    cat > "$bin_dir/marker" <<EOF
#!/usr/bin/env bash
: > "$marker"
exit 0
EOF
    chmod +x "$bin_dir/codex" "$bin_dir/marker"
    rc=0
    out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
      OMS_WORKER_GUARD_STRICT=1 "$ROOT/scripts/peer-delegate.sh" --repo "$project" \
      --to codex --prompt x --no-verify 2>&1)" || rc=$?
    [ "$rc" != 0 ] || fail "$mode execution config mutation passed: $out"
    [ ! -e "$marker" ] || fail "$mode command executed during post-worker capture"
    contains "$out" 'execution-state' ||
      fail "$mode did not name the raw execution-state boundary: $out"
    if [ "$mode" = fsmonitor ]; then
      contains "$out" 'snapshot=canonical repository path=config kind=config key delta=' ||
        fail "execution-state detail should name the canonical config snapshot and key: $out"
      case "$out" in
        *"$bin_dir/marker"*) fail "config value leaked into guard diagnostics: $out" ;;
      esac
      python3 - "$project" "$ROOT/scripts/lib" "$bin_dir/marker" <<'PY' ||
import json, sys
from pathlib import Path
sys.path.insert(0, sys.argv[2])
from peer_artifacts import artifact_sections
repo = Path(sys.argv[1])
index = [json.loads(line) for line in (repo / ".oms/artifacts/index.jsonl").read_text().splitlines()]
answer, _ = artifact_sections(repo / index[-1]["artifact"])
assert "snapshot=canonical repository path=config kind=config key delta=core.fsmonitor" in answer, answer
assert sys.argv[3] not in answer, "config value leaked into the delegate artifact"
PY
        fail "execution-state detail should be recorded without config values"
    fi
    if [ "$mode" = staged-index ]; then
      contains "$out" 'execution-state canonical index' ||
        fail "execution-state detail should name the canonical index: $out"
      python3 - "$project" <<'PY' || fail "canonical index detail missing from fail ledger"
import json, sys
from pathlib import Path
rows = [json.loads(line) for line in (Path(sys.argv[1]) / '.oms/failures.jsonl').read_text().splitlines()]
row = [item for item in rows if item.get('failure_code') == 'guard_parent_interference'][-1]
assert 'execution-state canonical index' in row['summary'], row
PY
    fi
    # Restore raw trusted bytes without asking Git to parse hostile config.
    cp "$base_config" "$project/.git/config"
    git -c core.fsmonitor=false -c diff.external= -C "$project" reset -q -- file.txt
    git -c core.fsmonitor=false -c diff.external= -C "$project" checkout -- file.txt
  done

  # The same snapshot diagnostics are used for the linked source clone. Keep
  # its component label tied to the role rather than the canonical repository.
  git -C "$project" worktree add -q -b guard-source-index "$source_clone"
  . "$ROOT/scripts/lib/oms-common.sh"
  oms_git_execution_state_snapshot "$source_clone" "$source_snapshot" ||
    fail "could not snapshot source clone execution state"
  source_sha="$(oms_sha256_file "$source_snapshot")"
  printf 'source index mutation\n' >> "$source_clone/file.txt"
  git -C "$source_clone" add file.txt
  rc=0
  source_out="$(oms_git_execution_state_assert_unchanged "$source_clone" \
    "$source_snapshot" "$source_sha" "source clone" "$source_detail" 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "source clone index mutation passed execution-state guard"
  contains "$source_out" 'component=execution-state source index' ||
    fail "source clone index detail did not name its component: $source_out"
  source_detail_line="$(printf '%s\n' "$source_out" | grep -F 'component=execution-state source index' | sed -n '1p')"
  case "$source_detail_line" in
    *canonical*)
      fail "source clone index detail incorrectly named canonical repository: $source_out" ;;
  esac

  # A snapshot error crosses the registry-lock subshell. It must stop before
  # the provider, with the snapshot's diagnostic retained for the caller.
  local snapshot_capture_count="$TMP/worker-exec-config-snapshot-capture-count"
  local provider_invoked="$project/provider-invoked"
  mkdir -p "$snapshot_capture_count"
  cat > "$bin_dir/codex" <<EOF
#!/usr/bin/env bash
: > "$provider_invoked"
echo done
EOF
  chmod +x "$bin_dir/codex"
  rc=0
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_WORKER_GUARD_STRICT=1 \
    OMS_TEST_WG_SNAPSHOT_CAPTURE_COUNT="$snapshot_capture_count" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex \
    --prompt x --no-verify 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "a worker-guard snapshot failure must stop delegation: $out"
  contains "$out" 'could not record worker guard test capture count' ||
    fail "the snapshot failure reason should reach the caller: $out"
  [ ! -e "$provider_invoked" ] ||
    fail "the provider ran after its worker-guard snapshot failed: $out"
}

