echo done
EOF
  chmod +x "$bin_dir/codex" "$bin_dir/marker"
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_WORKER_GUARD_STRICT=1 "$ROOT/scripts/peer-delegate.sh" --repo "$project" \
    --to codex --prompt x --no-verify 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "worker hidden index/config mutation passed: $out"
  [ ! -e "$marker" ] || fail "hidden-index companion command ran during capture"
  contains "$out" 'execution-state' ||
    fail "hidden index mutation did not name raw boundary: $out"
}

test_delegate_tolerates_primary_index_stat_refresh() {
  # Another session's `git status` rewrites the primary index with fresh stat
  # data; only staged content or hiding flags are the worker's business.
  local project="$TMP/worker-index-refresh"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local out rc=0

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  cat > "$bin_dir/codex" <<EOF
#!/usr/bin/env bash
cat >/dev/null
touch -t 200001010000 "$project/file.txt"
git -C "$project" update-index --refresh >/dev/null 2>&1 || true
git -C "$project" status --porcelain >/dev/null
printf 'worker edit\n' >> file.txt
echo done
EOF
  chmod +x "$bin_dir/codex"
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_WORKER_GUARD_STRICT=1 "$ROOT/scripts/peer-delegate.sh" --repo "$project" \
    --to codex --prompt x --no-verify 2>&1)" || rc=$?
  [ "$rc" = 0 ] || fail "a stat-only primary index refresh stopped the worker (rc=$rc): $out"
  if contains "$out" 'execution-state'; then fail "stat refresh named the execution-state boundary: $out"; fi
  # The parser proves an index or declines it: a bad checksum, cut padding or an
  # endless v4 prefix count returns no signature, quickly, so the raw digest decides.
  (. "$ROOT/scripts/lib/oms-common.sh" && python3 -I -B - "$OMS_GIT_INDEX_SIGNATURE_PY" <<'PY') ||
import hashlib, struct, sys, time
exec(sys.argv[1])
def wrap(body):
    return body + hashlib.sha1(body).digest()
entry = b"\0" * 24 + struct.pack(">I", 0o100644) + b"\0" * 12 + b"\x11" * 20 + struct.pack(">H", 1)
good = wrap(b"DIRC" + struct.pack(">II", 2, 1) + entry + b"a\0")
assert index_signature(good, 20)
assert index_signature(good[:-1] + bytes([good[-1] ^ 1]), 20) is None
assert index_signature(wrap(b"DIRC" + struct.pack(">II", 2, 1) + entry + b"a"), 20) is None
started = time.time()
assert index_signature(wrap(b"DIRC" + struct.pack(">II", 4, 1) + entry + b"\xff" * 200000 + b"\0a\0"), 20) is None
assert time.time() - started < 1
PY
    fail "the guard's index parser accepted a malformed index or ran unbounded"
  # A cache-tree edit alone changes the signature: the owner's next commit would use it.
  (. "$ROOT/scripts/lib/oms-common.sh" && git -C "$project" write-tree >/dev/null &&
    python3 -I -B - "$OMS_GIT_INDEX_SIGNATURE_PY" "$project/.git/index" <<'PY') ||
import hashlib, sys
exec(sys.argv[1])
data = open(sys.argv[2], "rb").read()
at = data.find(b"TREE", 12)
assert at > 0, "fixture index has no cache-tree"
forged = bytearray(data[:-20])
forged[at + 8 + forged[at + 8:].index(b"\n") + 1] ^= 1
forged = bytes(forged) + hashlib.sha1(bytes(forged)).digest()
assert index_signature(data, 20) and index_signature(forged, 20) and index_signature(data, 20) != index_signature(forged, 20)
PY
    fail "the guard's index signature ignored a cache-tree change"
}

