}

test_delegate_leaves_a_well_behaved_worker_alone() {
  local project="$TMP/worker-guard-clean"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local out

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  # Edits only its own worktree, which is exactly what a worker should do.
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
printf 'worker edit\n' >> file.txt
echo "edited file.txt in the worktree"
EOF

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || fail "a worktree-only worker should pass: $out"
  if contains "$out" 'changed protected state'; then
    fail "a worker staying in its worktree must not be flagged: $out"
  fi
  [ -s "$(printf '%s' "$out" | sed -n 's/^patch: //p' | sed -n '1p')" ] ||
    fail "the worker's work should still come back as a patch"

  cat > "$bin_dir/codex" <<EOF
#!/usr/bin/env bash
git -C "$project" config --local oms.tampered yes
echo "done"
EOF
  chmod +x "$bin_dir/codex"
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_WORKER_GUARD_OFF=1 "$ROOT/scripts/peer-delegate.sh" --repo "$project" \
    --to codex --prompt x --no-verify >/dev/null 2>&1 ||
    fail "the guard must be escapable for a caller that accepts the risk"
}

# smoke-weight: 5
test_delegate_empty_write_is_no_change_unless_allowed() {
  local project="$TMP/worker-no-change"
  local bin_dir="$project/bin"
  local home_dir="$project/home"
  local verify_marker="$TMP/worker-no-change-verify-ran"
  local out artifact rc=0

  make_committed_repo "$project"
  mkdir -p "$bin_dir" "$home_dir"
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
cat >/dev/null
echo "worker made no changes"
EOF

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_PANEL_DISPATCH=1 OMS_PANEL_ROLE=worker \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --verify "touch '$verify_marker'" 2>&1)" || rc=$?
  [ "$rc" -eq 6 ] || fail "a panel worker's empty write must exit 6 by default, got $rc: $out"
  [ ! -f "$verify_marker" ] || fail "an empty patch without --allow-no-change must not run the verifier"
  contains "$out" 'patch: none (no changes)' || fail "empty writes need a clear patch status: $out"
  contains "$out" 'worker: codex exit 0' || fail "the worker exit should remain accurate: $out"
  artifact="$(printf '%s\n' "$out" | sed -n 's/^artifact: //p' | sed -n '1p')"
  assert_file_contains "$artifact" 'SKIPPED: no change'
  assert_file_contains "$artifact" 'no_change'
  assert_file_contains "$project/.oms/artifacts/index.jsonl" '"exit": 6'

  # With --allow-no-change the verifier runs as before.
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --allow-no-change --verify "touch '$verify_marker'" 2>&1)" ||
    fail "an allowed empty write records no_change and exits 0: $out"
  [ -f "$verify_marker" ] || fail "--allow-no-change must still run the verifier"

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --no-verify 2>&1)" || fail "a direct empty write records no_change and exits 0: $out"
  contains "$out" 'patch: none (no changes)' || fail "allowed empty writes need a clear patch status: $out"
  artifact="$(printf '%s\n' "$out" | sed -n 's/^artifact: //p' | sed -n '1p')"
  assert_file_contains "$artifact" 'no_change'
}

