    task["executor_id"] = "forged-executor"
    task["executor_soul_sha256"] = "0" * 64

replace(sys.argv[1], mutate_plan)
PY
printf 'worker edit\n' >> file.txt
echo done
EOF

  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" \
