make_guard_repo() {  # make_guard_repo DIR — repo with an ignored directory
  local dir="$1"

  make_committed_repo "$dir"
  # Stubs and HOME stay outside the repo: a harness tool the worker invokes can
  # write under HOME, and inside the repo that is indistinguishable from the
  # worker planting files.
  mkdir -p "$dir-bin" "$dir-home" "$dir/venv/bin"
  printf 'venv/\n*.log\n' > "$dir/.gitignore"
  ( cd "$dir" && git add .gitignore &&
    git -c user.email=t@example.com -c user.name=t commit -qm ignore >/dev/null )
  printf 'original\n' > "$dir/venv/bin/python"
}

run_guarded_worker() {  # run_guarded_worker DIR WORKER_BODY -> prints "rc<TAB>output"
  local dir="$1"
  local body="$2"
  local rc=0
  local out
  local guard_home="$dir-home"

  printf '#!/usr/bin/env bash\ncase "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf "codex 1.0\\n"; exit 0 ;; esac\n%s\necho done\n' \
    "$body" > "$dir-bin/codex"
  chmod +x "$dir-bin/codex"
  out="$(HOME="$guard_home" NVM_DIR="$guard_home/.nvm" PATH="$dir-bin:/usr/bin:/bin" \
    OMS_WORKER_GUARD_STRICT="${OMS_WORKER_GUARD_STRICT:-0}" \
    OMS_WORKER_AUTHORITY_EXCLUSIVE="${OMS_WORKER_AUTHORITY_EXCLUSIVE:-0}" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$dir" --to codex --prompt x ${3:+--allow-no-change} \
    ${OMS_TEST_GUARD_READ:+--read-only} --no-verify 2>&1)" || rc=$?
  printf '%s\t%s' "$rc" "$out"
}

# smoke-weight: 6
test_worker_guard_sees_planted_and_ignored_files() {
  local project="$TMP/guard-files"
  local result

  make_guard_repo "$project"
  # A planted untracked file is executable later from the primary tree.
  # Untracked churn cannot be attributed — the user editing their own repo looks
  # identical — so it is reported, not failed, unless the caller asks for strict.
  result="$(run_guarded_worker "$project" "printf 'evil\n' > $project/sitecustomize.py" allow)"
  [ "${result%%	*}" = 0 ] || fail "unattributable churn must not fail an ordinary run: $result"
  contains "$result" 'changed outside the worktree during this run: files' ||
    fail "the untracked surface should still be reported: $result"
  # A reader keeps the section for surfaces it cannot ignore, naming the HEAD
  # its findings come from instead of a patch to review.
  result="$(OMS_TEST_GUARD_READ=1 run_guarded_worker "$project" "printf 'evil3\n' > $project/sitecustomize3.py")"
  [ "${result%%	*}" = 0 ] || fail "a read-only run should survive unattributable churn: $result"
  contains "$result" 'changed outside the worktree during this run: files' ||
    fail "the read-only run should still report files: $result"
  contains "$result" 'review these before landing' && fail "read warning mentions landing: $result"
  local read_artifact
  read_artifact="$(printf '%s\n' "${result#*	}" | sed -n 's/^artifact: //p' | sed -n '1p')"
  assert_file_contains "$read_artifact" '## Repository changed during the run'
  assert_file_contains "$read_artifact" "findings are from $(git -C "$project" rev-parse HEAD)"
  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$project" "printf 'evil2\n' > $project/sitecustomize2.py" allow)"
  [ "${result%%	*}" != 0 ] || fail "strict mode should fail on a planted file: $result"

  # git status collapses a fully ignored directory to one entry, so replacing a
  # file inside it is invisible there; the stat scan is what catches it.
  local swap="$TMP/guard-ignored"
  make_guard_repo "$swap"
  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$swap" "printf 'tampered\n' > $swap/venv/bin/python" allow)"
  [ "${result%%	*}" != 0 ] ||
    fail "replacing a file inside an ignored directory should fail a strict run"
  contains "$result" 'outside its worktree: files' ||
    fail "an ignored-tree replacement should be named: $result"

  # User-level settings and start files decide what the next session runs. A
  # change to one during the run is reported by name only and never fails the
  # run, strict or not: a provider CLI may update its own settings.
  local conf="$TMP/guard-user-config" conf_artifact
  make_guard_repo "$conf"
  mkdir -p "$conf-home/.codex"
  printf 'model = "kept"\n' > "$conf-home/.codex/config.toml"
  printf 'marker-value-7c1\n' > "$conf-home/.gitconfig.sample"
  result="$(run_guarded_worker "$conf" 'true' allow)"
  [ "${result%%	*}" = 0 ] || fail "a quiet run should pass: $result"
  if contains "$result" 'user-level configuration changed'; then
    fail "untouched user configuration must not be reported: $result"
  fi
  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$conf" \
    "printf 'planted-body-7c1\n' >> $conf-home/.codex/config.toml; printf 'planted-body-7c1\n' > $conf-home/.zshrc" allow)"
  [ "${result%%	*}" = 0 ] || fail "a user configuration change must stay a warning, strict included: $result"
  contains "$result" 'warning: user-level configuration changed during this run: codex config.toml, ~/.zshrc;' ||
    fail "the changed user configuration files should be named: $result"
  if contains "$result" 'planted-body-7c1'; then
    fail "the warning must carry file names, never contents: $result"
  fi
  conf_artifact="$(printf '%s\n' "${result#*	}" | sed -n 's/^artifact: //p' | sed -n '1p')"
  assert_file_contains "$conf_artifact" '## User-level configuration changed during the run'
  assert_file_contains "$conf_artifact" '- files: codex config.toml, ~/.zshrc'
  ! grep -q 'planted-body-7c1' "$conf_artifact" || fail "the artifact must not carry configuration contents"
}

test_worker_guard_reports_a_sibling_remote_ref_change_as_soft() {
  local project="$TMP/guard-soft-remote-ref"
  local head
  local result
  local out
  local artifact

  make_guard_repo "$project"
  head="$(git -C "$project" rev-parse HEAD)"
  result="$(run_guarded_worker "$project" \
    "git -C \"$project\" update-ref refs/remotes/origin/main \"$head\"")"
  [ "${result%%$'\t'*}" = 0 ] ||
    fail "a remote-tracking ref change should not fail an ordinary run: $result"
  out="${result#*$'\t'}"
  contains "$out" 'changed outside the worktree during this run: remote-refs' ||
    fail "the remote-ref surface should still be reported: $out"
  contains "$out" 'remote-refs; review these before landing' ||
    fail "the remote-ref warning should name the action: $out"
  artifact="$(printf '%s\n' "$out" | sed -n 's/^artifact: //p' | sed -n '1p')"
  [ -f "$artifact" ] || fail "missing soft remote-ref artifact: $out"
  assert_file_contains "$artifact" '## Repository changed during the run'
  assert_file_contains "$artifact" '- surfaces: remote-refs'
  assert_file_contains "$artifact" '- not attributable to the worker; review the patch before landing'

  # A reader has no patch to land, so a moved remote-tracking ref is not news.
  result="$(OMS_TEST_GUARD_READ=1 run_guarded_worker "$project" \
    "git -C \"$project\" update-ref refs/remotes/origin/main \"\$(git -C \"$project\" rev-parse HEAD~1)\"")"
  [ "${result%%$'\t'*}" = 0 ] || fail "a read-only run failed on a remote-ref change: $result"
  out="${result#*$'\t'}"
  contains "$out" 'Repository changed during the run' && fail "read-only remote-ref section leaked: $out"
  contains "$out" 'changed outside the worktree' && fail "read-only remote-ref warning leaked: $out"
  artifact="$(printf '%s\n' "$out" | sed -n 's/^artifact: //p' | sed -n '1p')"
  [ -f "$artifact" ] || fail "missing read-only artifact: $out"
  ! grep -q 'Repository changed during the run' "$artifact" || fail "read-only artifact has the section"

  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$project" \
    "git -C \"$project\" update-ref -d refs/remotes/origin/main")"
  [ "${result%%$'\t'*}" != 0 ] ||
    fail "strict mode should fail on a remote-tracking ref change: $result"
  contains "$result" 'changed protected state outside its worktree: remote-refs' ||
    fail "strict remote-ref violation should be named: $result"
}

# smoke-weight: 26
test_worker_guard_still_fails_on_a_local_branch_ref_change() {
  local project="$TMP/guard-hard-local-ref"
  local head
  local result

  make_guard_repo "$project"
  head="$(git -C "$project" rev-parse HEAD)"
  result="$(run_guarded_worker "$project" \
    "git -C \"$project\" update-ref refs/heads/guard-local \"$head\"")"
  [ "${result%%$'\t'*}" != 0 ] ||
    fail "a local branch ref change should fail the run: $result"
  contains "$result" 'changed protected state outside its worktree: refs' ||
    fail "the local branch ref violation should remain hard: $result"

  # Reusing an old object, an oms/* spelling, and a foreign checked-out branch
  # cannot make a plain worker update-ref attributable to that checkout.
  local sibling="$TMP/guard-hard-local-sibling"
  local next
  next="$(git -C "$project" commit-tree -p HEAD -m next 'HEAD^{tree}')"
  git -C "$project" worktree add -qb foreign "$sibling"
  result="$(run_guarded_worker "$project" "git update-ref refs/heads/foreign '$next'")"
  [ "${result%%$'\t'*}" != 0 ] || fail "worker update-ref on foreign branch must fail: $result"
  contains "$result" 'outside its worktree: refs' || fail "foreign update-ref was not hard: $result"
  result="$(run_guarded_worker "$project" "git update-ref refs/heads/oms/planted '$head'")"
  [ "${result%%$'\t'*}" != 0 ] || fail "worker-created oms branch must fail: $result"
  result="$(run_guarded_worker "$project" "git -C '$project' update-ref HEAD '$next'")"
  [ "${result%%$'\t'*}" != 0 ] || fail "shared HEAD move must fail: $result"
  contains "$result" 'outside its worktree: refs' || fail "shared HEAD move was not hard: $result"
  result="$(run_guarded_worker "$project" "git -C '$project' checkout -q guard-local")"
  [ "${result%%$'\t'*}" != 0 ] || fail "shared symbolic HEAD change must fail: $result"
  result="$(run_guarded_worker "$project" "git -C '$project' update-ref refs/heads/main '$head'")"
  [ "${result%%$'\t'*}" != 0 ] || fail "primary main branch move must fail: $result"
  result="$(run_guarded_worker "$project" "printf '%s\\n' '$next' > \"\$(git rev-parse --git-dir)/HEAD\"")"
  [ "${result%%$'\t'*}" != 0 ] || fail "own delegated HEAD identity move must fail: $result"
  git -C "$project" config branch.guard-local.merge refs/heads/foreign
  result="$(run_guarded_worker "$project" "git -C '$sibling' reset -q --hard '$head'")"
  [ "${result%%$'\t'*}" != 0 ] || fail "remote target move must fail even with foreign reflogs: $result"
  contains "$result" 'outside its worktree: refs' || fail "remote target ref was not hard: $result"
}

# smoke-weight: 126
test_worker_guard_reports_foreign_checkout_ref_moves() {
  local registry_project="$TMP/registry-contention" registry_root="$TMP/registry-contention-root"
  make_guard_repo "$registry_project"
  local registry_bin="$TMP/registry-bin" registry_mkdir
  registry_mkdir="$(command -v mkdir)"
  mkdir -p "$registry_bin"
  cat > "$registry_bin/mkdir" <<'SH'
#!/usr/bin/env bash
if ! "$REGISTRY_REAL_MKDIR" "$@"; then
  case "$*" in *.lock*) : > "$REGISTRY_WAITING" ;; esac
  exit 1
fi
SH
  chmod +x "$registry_bin/mkdir"
  (
    . "$ROOT/scripts/lib/harness-residue.sh"
    registry_hold() {
      : > "$TMP/registry-held"
      local tries=$(( ${OMS_TEST_CALL_TIMEOUT:-120} * 10 ))
      while [ ! -e "$TMP/registry-release" ] && [ "$tries" -gt 0 ]; do sleep 0.1; tries=$((tries - 1)); done
      [ -e "$TMP/registry-release" ]
    }
    OMS_LOCK_FORCE_MKDIR=1 oms_with_worktree_registry_lock "$registry_project" registry_hold
  ) &
  local registry_holder=$! registry_writer tries=$(( ${OMS_TEST_CALL_TIMEOUT:-120} * 10 ))
  while [ ! -e "$TMP/registry-held" ] && [ "$tries" -gt 0 ]; do sleep 0.1; tries=$((tries - 1)); done
  [ -e "$TMP/registry-held" ] || fail "registry holder did not start"
  PATH="$registry_bin:$PATH" REGISTRY_REAL_MKDIR="$registry_mkdir" REGISTRY_WAITING="$TMP/registry-waiting" \
    OMS_LOCK_FORCE_MKDIR=1 OMS_DELEGATE_WORKTREE_ROOT="$registry_root" \
    "$ROOT/scripts/oms" scratch-worktree add --repo "$registry_project" --owner-pid "$$" >"$TMP/registry-output" 2>"$TMP/registry-error" &
  registry_writer=$!
  tries=$(( ${OMS_TEST_CALL_TIMEOUT:-120} * 10 ))
  while [ ! -e "$TMP/registry-waiting" ] && kill -0 "$registry_writer" 2>/dev/null && [ "$tries" -gt 0 ]; do sleep 0.1; tries=$((tries - 1)); done
  local registry_waited=0
  [ -e "$TMP/registry-waiting" ] && [ ! -s "$TMP/registry-output" ] && registry_waited=1
  : > "$TMP/registry-release"
  wait "$registry_holder" || fail "registry holder failed"
  wait "$registry_writer" || fail "scratch writer failed: $(cat "$TMP/registry-error")"
  [ "$registry_waited" = 1 ] || fail "scratch writer did not wait for registry lock"
  [ -s "$TMP/registry-output" ] || fail "scratch writer did not finish after release"
  local mixed_project="$TMP/guard-mixed-ref"
  local mixed_ready="$TMP/guard-mixed-ref-ready" mixed_fired="$TMP/guard-mixed-ref-fired"
  local mixed_hook="$TMP/guard-mixed-ref-hook.sh" mixed_old mixed_next mixed_index mixed_result
  make_guard_repo "$mixed_project"
  mixed_old="$(git -C "$mixed_project" rev-parse HEAD)"
  mixed_next="$(git -C "$mixed_project" commit-tree -p HEAD -m mixed-diagnostic 'HEAD^{tree}')"
  mixed_index="$(git -C "$mixed_project" hash-object .git/index)"
  {
    printf 'oms_test_refs_repo=%q\n' "$mixed_project"
    printf 'oms_test_refs_ready=%q\n' "$mixed_ready"
    printf 'oms_test_refs_fired=%q\n' "$mixed_fired"
    printf 'oms_test_refs_old=%q\n' "$mixed_old"
    printf 'oms_test_refs_next=%q\n' "$mixed_next"
    printf 'oms_test_refs_git=%q\n' "$(command -v git)"
    cat <<'SH'
oms_test_refs_race() {
  case "$1" in
    'changed="$(worker_protected_surface_diff)"')
      if [ -f "$oms_test_refs_ready" ] && [ ! -e "$oms_test_refs_fired" ]; then
        : > "$oms_test_refs_fired"
        "$oms_test_refs_git" -C "$oms_test_refs_repo" config user.name mixed-diagnostic
        "$oms_test_refs_git" -C "$oms_test_refs_repo" update-ref refs/heads/main \
          "$oms_test_refs_next" "$oms_test_refs_old"
      fi ;;
  esac
  return 0
}
set -T
trap 'oms_test_refs_race "$BASH_COMMAND"' DEBUG
SH
  } > "$mixed_hook"
  mixed_result="$(BASH_ENV="$mixed_hook" run_guarded_worker "$mixed_project" "touch '$mixed_ready'")"
  [ -f "$mixed_fired" ] || fail "mixed refs fixture did not reach the assertion-to-capture window"
  [ "$(git -C "$mixed_project" rev-parse HEAD)" = "$mixed_next" ] || fail "mixed refs fixture did not move HEAD"
  [ "$(git -C "$mixed_project" hash-object .git/index)" = "$mixed_index" ] || fail "mixed refs fixture changed the index"
  [ "${mixed_result%%$'\t'*}" != 0 ] || fail "mixed config/refs change must keep the hard stop"
  contains "$mixed_result" 'config, refs' || fail "mixed config/refs hard list missing: $mixed_result"
  contains "$mixed_result" "refs/heads/main ${mixed_old:0:12}->${mixed_next:0:12} (fast-forward)" ||
    fail "mixed refs trace missing: $mixed_result"
  contains "$mixed_result" 'shared checkout HEAD moved' || fail "mixed HEAD detail missing: $mixed_result"
  contains "$mixed_result" 'shared checkout index unchanged' || fail "mixed index detail missing: $mixed_result"
  contains "$mixed_result" 'another session committing in the shared checkout' || fail "mixed refs hint missing: $mixed_result"

  local project="$TMP/guard-foreign-ref"
  local sibling="$TMP/guard-foreign-ref-sibling"
  local ready="$TMP/guard-foreign-ref-ready" done="$TMP/guard-foreign-ref-done"
  local next result pid branch strict old artifact
  make_guard_repo "$project"
  (
    . "$ROOT/scripts/lib/harness-residue.sh"
    . "$ROOT/scripts/lib/oms-common.sh"
    local snapshot="$TMP/guard-refs-report-freshness" current future report changed capture
    oms_worker_surface_snapshot "$project" "$snapshot" "$project" || exit 1
    current="$(git -C "$project" rev-parse HEAD)"
    future="$(git -C "$project" commit-tree -p HEAD -m diagnostic 'HEAD^{tree}')"
    cp "$snapshot/refs" "$snapshot/refs-now"
    for capture in fresh empty missing; do
      case "$capture" in
        fresh) sed "s/$current/$future/g" "$snapshot/refs" > "$snapshot/guard-report-refs-now" ;;
        empty) : > "$snapshot/guard-report-refs-now" ;;
        missing) rm -f "$snapshot/guard-report-refs-now" ;;
      esac
      report="$(oms_worker_refs_trace_report "$snapshot" "$project")" || exit 1
      if [ "$capture" = fresh ]; then
        contains "$report" "refs/heads/main ${current:0:12}->${future:0:12} (fast-forward)" ||
          fail "fresh failure capture lost to stale refs-now: $report"
        contains "$report" 'shared checkout HEAD moved' || fail "fresh HEAD detail missing: $report"
      else
        contains "$report" 'shared checkout HEAD unchanged' || fail "refs-now fallback missing: $report"
      fi
    done
    cp "$snapshot/refs" "$snapshot/guard-report-refs-now"
    changed="$(oms_worker_surface_diff "$project" "$snapshot" "" "$project")" || exit 1
    [ -z "$changed" ] || fail "unchanged report fixture changed: $changed"
    assert_not_exists "$snapshot/refs-now"
    assert_not_exists "$snapshot/guard-report-refs-now"
  ) || fail "ref report freshness checks failed"
  git -C "$project" worktree add -qb feature "$sibling"
  # A separate session rewrites both ordinary and oms/* branches. The provider
  # only waits; it performs no Git mutation in this fixture.
  for branch in feature oms/foreign; do
    [ "$branch" = feature ] || git -C "$sibling" checkout -qb "$branch"
    for strict in 0 1; do
      old="$(git -C "$project" rev-parse "$branch")"
      if [ "$strict" = 1 ]; then
        next="$(git -C "$project" commit-tree -m rewrite "${branch}^{tree}")"
      else
        next="$(git -C "$project" commit-tree -p "$branch" -m rewrite "${branch}^{tree}")"
      fi
      rm -f "$ready" "$done"
      (
        local tries=0
        while [ ! -f "$ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
        [ -f "$ready" ] || exit 1
        git -C "$sibling" reset -q --hard "$next"
        if [ "$strict" = 0 ]; then
          git -C "$sibling" commit -q --allow-empty -m foreign-sequence
          git -C "$sibling" rebase -q --force-rebase --exec 'git commit -q --allow-empty --amend -m rebased' HEAD~1
        fi
        touch "$done"
      ) &
      pid=$!
      result="$(OMS_WORKER_GUARD_STRICT="$strict" run_guarded_worker "$project" \
        "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
      wait "$pid" || fail "foreign ref fixture timed out"
      if [ "$strict" = 0 ]; then
        [ "${result%%$'\t'*}" = 0 ] || fail "foreign checkout rewrite stopped worker: $result"
        contains "$result" 'during this run: foreign-ref' || fail "foreign ref warning missing: $result"
      else
        [ "${result%%$'\t'*}" != 0 ] || fail "strict mode tolerated foreign rewrite: $result"
        contains "$result" 'outside its worktree: refs' || fail "strict foreign refs not hard: $result"
        contains "$result" "refs/heads/$branch ${old:0:12}->${next:0:12} (non-fast-forward)" || fail "rewrite detail missing: $result"
        contains "$result" 'shared checkout HEAD unchanged' || fail "HEAD detail missing: $result"
        contains "$result" 'shared checkout index unchanged' || fail "index detail missing: $result"
        contains "$result" 'another session committing in the shared checkout' || fail "hint missing: $result"
      fi
    done
  done

  # A main may fast-forward its checked-out branch, then detach at a different
  # tip before the guard polls. Both reflogs must still explain the ref move.
  for branch in feature oms/foreign; do
    for strict in 0 1; do
      git -C "$sibling" checkout -q "$branch"
      old="$(git -C "$project" rev-parse "$branch")"
      next="$(git -C "$project" commit-tree -p "$branch" -m fast-forward "${branch}^{tree}")"
      rm -f "$ready" "$done"
      (
        local tries=0
        while [ ! -f "$ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
        [ -f "$ready" ] || exit 1
        git -C "$sibling" merge -q --ff-only "$next" || exit 1
        git -C "$sibling" checkout -q --detach main || exit 1
        touch "$done"
      ) &
      pid=$!
      result="$(OMS_WORKER_GUARD_STRICT="$strict" run_guarded_worker "$project" \
        "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
      wait "$pid" || fail "foreign fast-forward and detach fixture timed out"
      if [ "$strict" = 0 ]; then
        [ "${result%%$'\t'*}" = 0 ] || fail "foreign fast-forward then detach stopped worker: $result"
        contains "$result" 'during this run: foreign-ref' || fail "detached foreign ref warning missing: $result"
      else
        [ "${result%%$'\t'*}" != 0 ] || fail "strict mode tolerated foreign fast-forward then detach: $result"
        contains "$result" 'outside its worktree: refs' || fail "strict detached foreign refs not hard: $result"
        contains "$result" "refs/heads/$branch ${old:0:12}->${next:0:12} (fast-forward)" || fail "fast-forward detail missing: $result"
        contains "$result" 'shared checkout HEAD unchanged' || fail "HEAD detail missing: $result"
        contains "$result" 'shared checkout index unchanged' || fail "index detail missing: $result"
        contains "$result" 'another session committing in the shared checkout' || fail "hint missing: $result"
      fi
    done
  done

  old="$(git -C "$project" rev-parse HEAD)"
  rm -f "$ready" "$done"
  (
    local tries=0
    while [ ! -f "$ready" ] && [ "$tries" -lt "${OMS_TEST_CALL_TIMEOUT:-100}" ]; do sleep 1; tries=$((tries + 1)); done
    [ -f "$ready" ] || exit 1
    printf 'shared change\n' > "$project/shared-change"
    git -C "$project" add shared-change
    git -C "$project" commit -q -m shared-change || exit 1
    touch "$done"
  ) &
  pid=$!
  result="$(run_guarded_worker "$project" "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt ${OMS_TEST_CALL_TIMEOUT:-100} ]; do sleep 1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
  wait "$pid" || fail "shared commit fixture timed out"
  next="$(git -C "$project" rev-parse HEAD)"
  [ "${result%%$'\t'*}" != 0 ] || fail "shared commit must stop worker: $result"
  contains "$result" "refs/heads/main ${old:0:12}->${next:0:12} (fast-forward)" || fail "shared ref detail missing: $result"
  contains "$result" 'shared checkout HEAD moved' || fail "shared HEAD detail missing: $result"
  contains "$result" 'shared checkout index moved' || fail "shared index detail missing: $result"
  contains "$result" 'another session committing in the shared checkout' || fail "shared commit hint missing: $result"
  artifact="$(find "$project/.oms/artifacts/delegate" -type f -name '*.md' -exec grep -lF "refs/heads/main ${old:0:12}->${next:0:12}" {} \; | sed -n '1p')"
  [ -n "$artifact" ] || fail "shared commit artifact missing"
  assert_file_contains "$artifact" 'shared checkout index moved'
  if grep -Fq 'no path/ref detail available in the preserved manifests' "$artifact"; then
    fail "shared commit artifact retained the unavailable-detail placeholder"
  fi

  # A soft foreign move populates refs-now before verification. A later shared
  # commit must still be diagnosed when the index guard prevents another diff.
  local verify_ready="$TMP/guard-refs-verify-ready" verify_done="$TMP/guard-refs-verify-done"
  local verify_script="$TMP/guard-refs-verify.sh" stale_refs="$TMP/guard-refs-before-verify"
  local wait_limit="${OMS_TEST_CALL_TIMEOUT:-120}" rc=0
  git -C "$sibling" checkout -q feature
  old="$(git -C "$project" rev-parse HEAD)"
  rm -f "$ready" "$done"
  oms_smoke_make_fake_provider_stub "$project-bin/codex" <<EOF
#!/usr/bin/env bash
case "\${1:-}:\${2:-}" in --version:|--help:|exec:--help) echo 'codex 1.0'; exit 0 ;; esac
touch '$ready'
tries=0
while [ ! -f '$done' ] && [ "\$tries" -lt '$wait_limit' ]; do sleep 1; tries=\$((tries + 1)); done
[ -f '$done' ] || exit 1
echo done
EOF
  cat > "$verify_script" <<EOF
cp ../worker-guard/refs-now '$stale_refs' || exit 1
touch '$verify_ready'
tries=0
while [ ! -f '$verify_done' ] && [ "\$tries" -lt '$wait_limit' ]; do sleep 1; tries=\$((tries + 1)); done
[ -f '$verify_done' ]
EOF
  (
    local tries=0 number
    while [ ! -f "$ready" ] && [ "$tries" -lt "$wait_limit" ]; do sleep 1; tries=$((tries + 1)); done
    [ -f "$ready" ] || exit 1
    git -C "$sibling" commit -q --allow-empty -m before-verify || exit 1
    touch "$done"
    tries=0
    while [ ! -f "$verify_ready" ] && [ "$tries" -lt "$wait_limit" ]; do sleep 1; tries=$((tries + 1)); done
    [ -f "$verify_ready" ] || exit 1
    printf 'during verify\n' >> "$project/shared-change"
    git -C "$project" add shared-change
    git -C "$project" commit -q -m during-verify || exit 1
    # More than twelve details must use the artifact's existing omission line.
    for number in {1..12}; do
      git -C "$project" update-ref "refs/heads/zz-diagnostic/$number" HEAD || exit 1
    done
    touch "$verify_done"
  ) &
  pid=$!
  result="$(HOME="$project-home" NVM_DIR="$project-home/.nvm" PATH="$project-bin:/usr/bin:/bin" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --allow-no-change --verify "bash '$verify_script'" 2>&1)" || rc=$?
  wait "$pid" || fail "commit during verification fixture timed out: $result"
  [ "$rc" = 1 ] || fail "commit during verification must fail closed: $rc $result"
  next="$(git -C "$project" rev-parse HEAD)"
  assert_file_contains "$stale_refs" "$old"
  contains "$result" "refs canonical ref refs/heads/main ${old:0:12}->${next:0:12} (fast-forward)" ||
    fail "stale refs-now hid the verification commit: $result"
  contains "$result" 'shared checkout HEAD moved' || fail "verification HEAD detail missing: $result"
  contains "$result" 'shared checkout index moved' || fail "verification index detail missing: $result"
  artifact="$(find "$project/.oms/artifacts/delegate" -type f -name '*.md' -exec grep -lF "refs/heads/main ${old:0:12}->${next:0:12}" {} \; | sed -n '1p')"
  [ -n "$artifact" ] || fail "verification commit artifact missing"
  python3 - "$artifact" <<'PY' || fail "verification ref detail formatting violated its artifact contract"
import sys
text = open(sys.argv[1], encoding="utf-8").read()
assert "no path/ref detail available in the preserved manifests" not in text, text
details = text.rsplit("Changed paths/refs by snapshot (up to 12 sanitized lines):\n", 1)[1].split("\nExecution-state details:", 1)[0].splitlines()
assert len(details) == 13 and details[-1] == "additional changed paths omitted", details
assert details[0].startswith("refs canonical ref refs/heads/"), details
assert all(line.startswith("refs canonical ") for line in details[:12]), details
PY

  # Exercise incomplete receipts without starting a provider for each damaged
  # file. A second checkout of the same branch cannot borrow the first's proof.
  (
    . "$ROOT/scripts/lib/harness-residue.sh"
    . "$ROOT/scripts/lib/oms-common.sh"
    local snapshot="$TMP/guard-detached-evidence"
    local duplicate="$TMP/guard-detached-duplicate"
    local metadata head_log branch_log saved case_name rc
    git -C "$sibling" checkout -q oms/foreign || exit 1
    git -C "$project" worktree add -q --force "$duplicate" oms/foreign || exit 1
    metadata="$(oms_harness_git_path_physical "$sibling" --git-dir)"
    head_log="$metadata/logs/HEAD"
    branch_log="$project/.git/logs/refs/heads/oms/foreign"
    oms_worker_surface_snapshot "$project" "$snapshot" "$project" || exit 1
    rc=0
    oms_worker_refs_only_foreign "$project" "$snapshot" "$project" || rc=$?
    [ "$rc" = 1 ] || fail "unchanged refs must not count as a foreign move"
    next="$(git -C "$project" commit-tree -p oms/foreign -m evidence 'oms/foreign^{tree}')"
    git -C "$sibling" merge -q --ff-only "$next" || exit 1
    git -C "$sibling" checkout -q --detach HEAD || exit 1
    oms_worker_refs_only_foreign "$project" "$snapshot" "$project" ||
      fail "complete detached reflog evidence must be accepted"
    git -C "$sibling" checkout -q --detach main || exit 1
    oms_worker_gitmeta_only_foreign_checkout_heads "$project" "$snapshot" "$project" ||
      fail "the proven detached checkout metadata must be accepted"
    git -C "$sibling" checkout -q feature || exit 1
    oms_worker_gitmeta_only_foreign_checkout_heads "$project" "$snapshot" "$project" ||
      fail "switching to another branch must retain the proven ref move"
    git -C "$sibling" checkout -q --detach main || exit 1
    saved="$snapshot/current"
    mkdir -p "$saved"
    cp "$head_log" "$saved/head-log"
    cp "$branch_log" "$saved/branch-log"
    cp "$metadata/HEAD" "$metadata/gitdir" "$snapshot/refs-protected" "$saved/"
    for case_name in empty-head empty-head-suffix empty-branch-suffix malformed-head \
      discontinuous-head short-oid invalid-oid wrong-tip unknown-ref head-prefix branch-prefix \
      missing-head missing-branch symlink-head symlink-branch registration protected; do
      case "$case_name" in
        empty-head) : > "$metadata/HEAD" ;;
        empty-head-suffix) cp "$snapshot/foreign-worktrees/${metadata##*/}/log" "$head_log" ;;
        empty-branch-suffix) cp "$snapshot/foreign-worktrees/${metadata##*/}/ref-log" "$branch_log" ;;
        malformed-head) printf 'malformed\n' >> "$head_log" ;;
        discontinuous-head) printf '%s %s fixture\n' "$next" "$next" >> "$head_log" ;;
        short-oid) printf '%s zero fixture\n' "$(git -C "$project" rev-parse main)" >> "$head_log" ;;
        invalid-oid) printf '%s %sz fixture\n' "$(git -C "$project" rev-parse main)" "${next%?}" >> "$head_log" ;;
        wrong-tip) printf '%s\n' "$next" > "$metadata/HEAD" ;;
        unknown-ref) printf 'ref: refs/heads/not-present\n' > "$metadata/HEAD" ;;
        head-prefix) printf 'rewritten\n' > "$head_log" ;;
        branch-prefix) printf 'rewritten\n' > "$branch_log" ;;
        missing-head) rm "$head_log" ;;
        missing-branch) rm "$branch_log" ;;
        symlink-head) rm "$head_log"; ln -s "$saved/head-log" "$head_log" ;;
        symlink-branch) rm "$branch_log"; ln -s "$saved/branch-log" "$branch_log" ;;
        registration) printf '\n' >> "$metadata/gitdir" ;;
        protected) printf 'refs/heads/oms/foreign\n' >> "$snapshot/refs-protected" ;;
      esac
      rc=0
      oms_worker_refs_only_foreign "$project" "$snapshot" "$project" >/dev/null 2>&1 || rc=$?
      [ "$rc" = 1 ] || fail "$case_name evidence must reject the foreign move: $rc"
      rm -f "$head_log" "$branch_log"
      cp "$saved/head-log" "$head_log"
      cp "$saved/branch-log" "$branch_log"
      cp "$saved/HEAD" "$saved/gitdir" "$metadata/"
      cp "$saved/refs-protected" "$snapshot/refs-protected"
    done
    oms_worker_refs_only_foreign "$project" "$snapshot" "$project" ||
      fail "restoring intact evidence must restore attribution"
    rc=0
    oms_worker_refs_only_foreign "$project" "$snapshot" "$sibling" || rc=$?
    [ "$rc" = 1 ] || fail "the worker's own checkout must not supply foreign proof"
    git -C "$duplicate" checkout -q --detach main || exit 1
    rc=0
    oms_worker_gitmeta_only_foreign_checkout_heads "$project" "$snapshot" "$project" || rc=$?
    [ "$rc" = 1 ] || fail "another checkout must not borrow the proven checkout's logs"
  ) || fail "detached foreign ref evidence checks failed"

  local managed_root="$TMP/guard-branch-managed"
  local existing="$managed_root/foreign-existing/wt"
  mkdir -p "${existing%/wt}"
  git -C "$project" worktree add -q --detach "$existing" HEAD
  rm -f "$ready" "$done"
  (
    local tries=0
    while [ ! -f "$ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
    [ -f "$ready" ] || exit 1
    git -C "$existing" checkout -q --no-track -b oms/existing-worktree
    touch "$done"
  ) &
  pid=$!
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
  wait "$pid" || fail "managed foreign checkout fixture timed out"
  [ "${result%%$'\t'*}" = 0 ] ||
    fail "a separate managed checkout creating oms/* should be soft: $result"
  contains "$result" 'during this run: foreign-ref' ||
    fail "managed foreign checkout warning missing: $result"

  # A separate actor creates and checks out the branch while the provider only
  # waits. The managed root is outside the delegated worker's writable tree.
  local created="$managed_root/foreign-created/wt"
  mkdir -p "${created%/wt}"
  rm -f "$ready" "$done"
  (
    local tries=0
    while [ ! -f "$ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
    [ -f "$ready" ] || exit 1
    git -C "$project" worktree add -q --detach "$created" HEAD || exit 1
    git -C "$created" checkout -q --no-track -b oms/created || exit 1
    git -C "$created" -c user.name=test -c user.email=test@example.invalid commit -q --allow-empty -m follow-up || exit 1
    touch "$done"
  ) &
  pid=$!
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
  wait "$pid" || fail "managed detached checkout fixture timed out"
  [ "${result%%$'\t'*}" = 0 ] ||
    fail "separate managed branch creation should be soft: $result"
  contains "$result" 'during this run: foreign-ref' ||
    fail "managed branch creation warning missing: $result"

  # Parent-created scratch worktrees carry a live residue marker. Creating a
  # branch there must still use the guarded foreign-ref evidence path.
  local scratch_created
  rm -f "$ready" "$done"
  (
    local tries=0
    while [ ! -f "$ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
    [ -f "$ready" ] || exit 1
    scratch_created="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" \
      "$ROOT/scripts/scratch-worktree.sh" add --repo "$project" --owner-pid "$$")" || exit 1
    git -C "$scratch_created" checkout -q --no-track -b oms/scratch-created || exit 1
    git -C "$scratch_created" -c user.name=test -c user.email=test@example.invalid \
      commit -q --allow-empty -m follow-up || exit 1
    touch "$done"
  ) &
  pid=$!
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
  wait "$pid" || fail "parent scratch branch fixture timed out"
  [ "${result%%$'\t'*}" = 0 ] ||
    fail "parent scratch branch creation should be soft: $result"
  contains "$result" 'during this run: foreign-ref' ||
    fail "parent scratch branch warning missing: $result"

  # Pause after refs have been snapshotted but before gitmeta and reflog
  # receipts, so the branch is created inside the baseline capture window.
  local baseline_ready="$TMP/guard-foreign-ref-baseline-ready"
  local baseline_release="$TMP/guard-foreign-ref-baseline-release"
  local baseline_capture_count="$TMP/guard-foreign-ref-baseline-captures"
  local stable_capture_count="$TMP/guard-foreign-ref-stable-captures"
  local unstable_capture_count="$TMP/guard-foreign-ref-unstable-captures"
  local unstable_fingerprint_state="$TMP/guard-foreign-ref-unstable-fingerprint"
  : > "$stable_capture_count"
  (
    . "$ROOT/scripts/lib/harness-residue.sh"
    . "$ROOT/scripts/lib/oms-common.sh"
    export OMS_TEST_WG_SNAPSHOT_CAPTURE_COUNT="$stable_capture_count"
    oms_worker_surface_snapshot "$project" \
      "$TMP/guard-foreign-ref-stable-baseline" "$project"
  ) || fail "a stable worker guard snapshot failed"
  [ "$(awk 'END { print NR }' "$stable_capture_count")" = 1 ] ||
    fail "an unchanged baseline should use one full capture"

  : > "$unstable_capture_count"
  rm -f "$unstable_fingerprint_state"
  (
    . "$ROOT/scripts/lib/harness-residue.sh"
    . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_boundary_fingerprint() {
      local count=0
      [ ! -f "$unstable_fingerprint_state" ] ||
        count="$(cat "$unstable_fingerprint_state")"
      count=$((count + 1))
      printf '%s\n' "$count" > "$unstable_fingerprint_state"
      printf 'unstable-%s\n' "$count"
    }
    oms_worker_surface_snapshot_capture_once() { return 0; }
    export OMS_TEST_WG_SNAPSHOT_CAPTURE_COUNT="$unstable_capture_count"
    if oms_worker_surface_snapshot "$project" \
      "$TMP/guard-foreign-ref-unstable-baseline" "$project"; then
      exit 1
    fi
    [ "$OMS_WG_SNAPSHOT_ERROR" = \
      "worker guard baseline did not stabilize after 3 attempts" ]
  ) || fail "an unstable baseline must fail closed with its reason"
  [ "$(awk 'END { print NR }' "$unstable_capture_count")" = 3 ] ||
    fail "an unstable baseline must stop after three captures"

  # Boundary churn is tolerated only when every changed slot still validates
  # as a managed sibling. Unrelated common-dir metadata remains fail-closed.
  local churn_repo="$TMP/guard-baseline-sibling-churn"
  local churn_root="$TMP/guard-baseline-sibling-root"
  local churn_sibling="$churn_root/oh-my-setting-delegate.churn"
  local churn_snap="$TMP/guard-baseline-sibling-snapshot"
  make_guard_repo "$churn_repo"
  make_live_managed_sibling "$churn_repo" "$churn_sibling"
  OMS_DELEGATE_WORKTREE_ROOT="$churn_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    repo="$2" sibling="$3" snap="$4"
    oms_worker_surface_snapshot_capture_once "$repo" "$snap" "$repo" || exit 1
    OMS_WG_BOUNDARY_DETAIL_OUT="$snap/boundary-before" \
      oms_worker_surface_boundary_fingerprint "$repo" >/dev/null || exit 2
    metadata="$(git -C "$sibling/wt" rev-parse --git-dir)"
    case "$metadata" in /*) ;; *) metadata="$repo/$metadata" ;; esac
    gitdir="$metadata/gitdir"
    content="$(cat "$gitdir")"
    printf "%s\r\n" "$content" > "$gitdir"
    OMS_WG_BOUNDARY_DETAIL_OUT="$snap/boundary-after" \
      oms_worker_surface_boundary_fingerprint "$repo" >/dev/null || exit 3
    oms_worker_gitmeta_boundary_churn_is_safe "$repo" \
      "$snap/boundary-before" "$snap/boundary-after" "$snap" "$repo" || exit 4
    common="$(oms_harness_git_path_physical "$repo" --git-common-dir)" || exit 5
    printf late > "$common/worktrees/unrelated-admin-entry"
    OMS_WG_BOUNDARY_DETAIL_OUT="$snap/boundary-unrelated" \
      oms_worker_surface_boundary_fingerprint "$repo" >/dev/null || exit 5
    if oms_worker_gitmeta_boundary_churn_is_safe "$repo" \
      "$snap/boundary-before" "$snap/boundary-unrelated" "$snap" "$repo"; then
      exit 6
    fi
  ' _ "$ROOT" "$churn_repo" "$churn_sibling" "$churn_snap" ||
    fail "baseline should accept validated sibling churn and reject unrelated admin churn"

  local actual_churn="$TMP/guard-baseline-actual-sibling-churn"
  local actual_root="$TMP/guard-baseline-actual-sibling-root"
  local actual_sibling="$actual_root/oh-my-setting-delegate.concurrent"
  local actual_ready="$TMP/guard-baseline-actual-ready"
  local actual_release="$TMP/guard-baseline-actual-release"
  local actual_count="$TMP/guard-baseline-actual-count"
  make_guard_repo "$actual_churn"
  make_live_managed_sibling "$actual_churn" "$actual_sibling"
  rm -f "$actual_ready" "$actual_release"
  : > "$actual_count"
  (
    local tries=0
    while [ ! -e "$actual_ready" ] && [ "$tries" -lt 100 ]; do
      sleep 0.05
      tries=$((tries + 1))
    done
    [ -e "$actual_ready" ] || exit 1
    metadata="$(git -C "$actual_sibling/wt" rev-parse --git-dir)"
    case "$metadata" in /*) ;; *) metadata="$actual_churn/$metadata" ;; esac
    content="$(cat "$metadata/gitdir")"
    printf '%s\r\n' "$content" > "$metadata/gitdir"
    touch "$actual_release"
  ) &
  pid=$!
  OMS_TEST_WG_SNAPSHOT_PAUSE_AFTER=refs \
    OMS_TEST_WG_SNAPSHOT_READY="$actual_ready" \
    OMS_TEST_WG_SNAPSHOT_RELEASE="$actual_release" \
    OMS_TEST_WG_SNAPSHOT_CAPTURE_COUNT="$actual_count" \
    OMS_DELEGATE_WORKTREE_ROOT="$actual_root" bash -c '
      . "$1/scripts/lib/harness-residue.sh"
      . "$1/scripts/lib/oms-common.sh"
      oms_worker_surface_snapshot "$2" "$3" "$2"
    ' _ "$ROOT" "$actual_churn" "$TMP/guard-baseline-actual-snapshot" ||
      fail "a managed sibling created during baseline capture must stabilize"
  wait "$pid" || fail "managed sibling baseline churn fixture failed"
  [ "$(awk 'END { print NR }' "$actual_count")" = 1 ] ||
    fail "validated sibling baseline churn should stabilize in one capture: $(cat "$actual_count")"

  # A per-worktree config change during capture must alter the boundary
  # fingerprint and force the baseline to capture the new bytes.
  local config_churn="$TMP/guard-baseline-config-churn"
  local config_root="$TMP/guard-baseline-config-root"
  local config_sibling="$config_root/oh-my-setting-delegate.config-churn"
  local config_ready="$TMP/guard-baseline-config-ready"
  local config_release="$TMP/guard-baseline-config-release"
  local config_count="$TMP/guard-baseline-config-count"
  local config_snap="$TMP/guard-baseline-config-snapshot"
  make_guard_repo "$config_churn"
  make_live_managed_sibling "$config_churn" "$config_sibling"
  rm -f "$config_ready" "$config_release"
  : > "$config_count"
  (
    local tries=0
    while [ ! -e "$config_ready" ] && [ "$tries" -lt 100 ]; do
      sleep 0.05
      tries=$((tries + 1))
    done
    [ -e "$config_ready" ] || exit 1
    local config_metadata
    config_metadata="$(git -C "$config_sibling/wt" rev-parse --git-dir)"
    case "$config_metadata" in /*) ;; *) config_metadata="$config_churn/$config_metadata" ;; esac
    printf '[core]\nfsmonitor=unsafe\n' > "$config_metadata/config.worktree"
    touch "$config_release"
  ) &
  pid=$!
  OMS_TEST_WG_SNAPSHOT_PAUSE_AFTER=refs \
    OMS_TEST_WG_SNAPSHOT_READY="$config_ready" \
    OMS_TEST_WG_SNAPSHOT_RELEASE="$config_release" \
    OMS_TEST_WG_SNAPSHOT_CAPTURE_COUNT="$config_count" \
    OMS_DELEGATE_WORKTREE_ROOT="$config_root" bash -c '
      . "$1/scripts/lib/harness-residue.sh"
      . "$1/scripts/lib/oms-common.sh"
      oms_worker_surface_snapshot "$2" "$3" "$2"
    ' _ "$ROOT" "$config_churn" "$config_snap" ||
      fail "a config.worktree change during baseline capture must stabilize"
  wait "$pid" || fail "config.worktree baseline race fixture failed"
  [ "$(awk 'END { print NR }' "$config_count")" = 2 ] ||
    fail "a config-only boundary race must recapture once: $(cat "$config_count")"
  grep -Fq "worktree worktrees/" "$config_snap/gitmeta" &&
    grep -Fq "/config.worktree " "$config_snap/gitmeta" ||
    fail "the stabilized baseline must include config.worktree bytes"

  # A pending registration can precede complete managed registrations in
  # Git's sorted admin scan. It must not truncate the remaining baseline rows.
  local pending_baseline="$TMP/guard-baseline-pending-sibling"
  local pending_root="$TMP/guard-baseline-pending-root"
  local pending_snap="$TMP/guard-baseline-pending-snapshot"
  make_guard_repo "$pending_baseline"
  OMS_DELEGATE_WORKTREE_ROOT="$pending_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    repo="$2" root="$3" snap="$4"
    pending="$root/oh-my-setting-delegate.pending/wt"
    complete="$root/oh-my-setting-scratch.complete/wt"
    mkdir -p "${pending%/wt}" "${complete%/wt}"
    git -C "$repo" worktree add --quiet --detach "$pending" HEAD || exit 1
    printf "kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s\ntemporary=1\n" \
      "$$" "$repo" "$pending" > "${pending%/wt}/.oh-my-setting-tmp"
    git -C "$repo" worktree add --quiet --detach "$complete" HEAD || exit 2
    printf "kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s\ntemporary=1\n" \
      "$$" "$repo" "$complete" > "${complete%/wt}/.oh-my-setting-tmp"
    common="$(git -C "$repo" rev-parse --git-common-dir)"
    case "$common" in /*) ;; *) common="$repo/$common" ;; esac
    pending_meta="$(git -C "$pending" rev-parse --git-dir)"
    complete_meta="$(git -C "$complete" rev-parse --git-dir)"
    case "$pending_meta" in /*) ;; *) pending_meta="$repo/$pending_meta" ;; esac
    case "$complete_meta" in /*) ;; *) complete_meta="$repo/$complete_meta" ;; esac
    mv "$pending_meta" "$common/worktrees/000-pending" || exit 3
    mv "$complete_meta" "$common/worktrees/999-complete" || exit 4
    printf "gitdir: %s\n" "$common/worktrees/999-complete" > "$complete/.git"
    printf "%s/.git\n" "$complete" > "$common/worktrees/999-complete/gitdir"
    printf "gitdir: %s\n" "$common/worktrees/000-pending" > "$pending/.git"
    printf "%s/.git\n" "$pending" > "$common/worktrees/000-pending/gitdir"
    rm -rf "$pending"
    oms_worker_surface_snapshot "$repo" "$snap" "$repo" || exit 5
    grep -Fxq worktrees/999-complete "$snap/gitmeta-exempt" || exit 6
    awk -F "\t" '\''$1 == "999-complete" { found = 1 } END { exit !found }'\'' \
      "$snap/gitmeta-managed-paths" || exit 7
  ' _ "$ROOT" "$pending_baseline" "$pending_root" "$pending_snap" ||
    fail "a registered pending sibling must not truncate later baseline worktree entries"

  rm -f "$baseline_ready" "$baseline_release" "$ready" "$done"
  : > "$baseline_capture_count"
  # Registration waits for the guard's registry lock, so the scratch exists first and only its branch
  # moves inside the paused baseline window.
  local baseline_scratch
  baseline_scratch="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" \
    "$ROOT/scripts/scratch-worktree.sh" add --repo "$project" --owner-pid "$$")" ||
    fail "baseline-window scratch worktree could not be created"
  (
    local tries=0
    while [ ! -f "$baseline_ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
    [ -f "$baseline_ready" ] || exit 1
    git -C "$baseline_scratch" checkout -q --no-track -b oms/baseline-created || exit 1
    git -C "$baseline_scratch" -c user.name=test -c user.email=test@example.invalid \
      commit -q --allow-empty -m baseline-follow-up || exit 1
    touch "$baseline_release" "$done"
  ) &
  pid=$!
  result="$(OMS_TEST_WG_SNAPSHOT_PAUSE_AFTER=refs \
    OMS_TEST_WG_SNAPSHOT_READY="$baseline_ready" \
    OMS_TEST_WG_SNAPSHOT_RELEASE="$baseline_release" \
    OMS_TEST_WG_SNAPSHOT_CAPTURE_COUNT="$baseline_capture_count" \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
  wait "$pid" || fail "baseline-window scratch branch fixture failed: $result"
  [ "${result%%$'\t'*}" = 0 ] ||
    fail "a scratch branch created during baseline capture stopped the worker: $result"
  [ "$(awk 'END { print NR }' "$baseline_capture_count")" = 2 ] ||
    fail "a torn baseline should be recaptured exactly once: $(cat "$baseline_capture_count")"

  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" "git branch oms/unattached HEAD")"
  [ "${result%%$'\t'*}" != 0 ] ||
    fail "an oms/* branch without a foreign checkout should stay hard: $result"
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "git -C \"\$PWD\" checkout -q -b oms/worker-own")"
  [ "${result%%$'\t'*}" != 0 ] ||
    fail "a new branch checked out in the worker worktree should stay hard: $result"

  local strict_created="$managed_root/foreign-strict/wt"
  mkdir -p "${strict_created%/wt}"
  git -C "$project" worktree add -q --detach "$strict_created" HEAD
  rm -f "$ready" "$done"
  (
    local tries=0
    while [ ! -f "$ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
    [ -f "$ready" ] || exit 1
    git -C "$strict_created" checkout -q --no-track -b oms/strict-created
    touch "$done"
  ) &
  pid=$!
  result="$(OMS_WORKER_GUARD_STRICT=1 OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
  wait "$pid" || fail "strict managed checkout fixture timed out"
  [ "${result%%$'\t'*}" != 0 ] ||
    fail "strict mode tolerated a newly checked-out foreign oms/* branch: $result"
  git -C "$project" worktree remove -f "$strict_created" >/dev/null 2>&1 || true
  git -C "$project" branch -D oms/strict-created >/dev/null 2>&1 || true

  local deleted="$managed_root/foreign-deleted/wt"
  mkdir -p "${deleted%/wt}"
  git -C "$project" worktree add -q --detach "$deleted" HEAD
  git -C "$deleted" checkout -q --no-track -b oms/deleted
  rm -f "$ready" "$done"
  (
    local tries=0
    while [ ! -f "$ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
    [ -f "$ready" ] || exit 1
    git -C "$project" worktree remove -f "$deleted" || exit 1
    git -C "$project" branch -D oms/deleted >/dev/null || exit 1
    touch "$done"
  ) &
  pid=$!
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
  wait "$pid" || fail "managed foreign deletion fixture timed out"
  [ "${result%%$'\t'*}" = 0 ] ||
    fail "removing a managed foreign checkout with its branch should be soft: $result"
  contains "$result" 'during this run: foreign-ref' ||
    fail "managed foreign deletion warning missing: $result"

  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" "git branch -D oms/unattached")"
  [ "${result%%$'\t'*}" != 0 ] ||
    fail "deleting an oms/* branch without foreign checkout evidence should stay hard: $result"
  git -C "$project" branch unrelated HEAD
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" "git branch -D unrelated")"
  [ "${result%%$'\t'*}" != 0 ] ||
    fail "deleting a non-oms branch should stay hard: $result"

  # A worker cannot manufacture the managed-root evidence from writable paths.
  local outside="$TMP/guard-worker-outside/wt"
  mkdir -p "${outside%/wt}"
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "git worktree add -q --detach '$outside' HEAD && git -C '$outside' checkout -q --no-track -b oms/outside")"
  [ "${result%%$'\t'*}" != 0 ] || fail "worker-created /tmp checkout was accepted: $result"
  git -C "$project" worktree remove -f "$outside" >/dev/null 2>&1 || true
  git -C "$project" branch -D oms/outside >/dev/null 2>&1 || true

  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "git worktree add -q --detach \"\$PWD/inside\" HEAD && git -C \"\$PWD/inside\" checkout -q --no-track -b oms/inside")"
  [ "${result%%$'\t'*}" != 0 ] || fail "worker-created nested checkout was accepted: $result"
  # The panel worker's private fixture root is a writable sibling of its worktree.
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "mkdir \"\$PWD/../.oms-panel-fixtures.t\" && git worktree add -q --detach \"\$PWD/../.oms-panel-fixtures.t/co\" HEAD && git -C \"\$PWD/../.oms-panel-fixtures.t/co\" checkout -q --no-track -b oms/fixture")"
  [ "${result%%$'\t'*}" != 0 ] || fail "worker-created fixture checkout was accepted: $result"

  local common fake_entry
  common="$(git -C "$project" rev-parse --git-common-dir)"
  case "$common" in /*) ;; *) common="$project/$common" ;; esac
  fake_entry="$common/worktrees/fake-managed"
  mkdir -p "$managed_root/fake-parent" "$common/worktrees"
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "git branch oms/fake HEAD && mkdir -p '$fake_entry'; printf '%s/.git\\n' '$managed_root/fake-parent/wt' > '$fake_entry/gitdir'; printf 'ref: refs/heads/oms/fake\\n' > '$fake_entry/HEAD'")"
  [ "${result%%$'\t'*}" != 0 ] || fail "fake managed registration was accepted: $result"
  rm -rf "$fake_entry"

  local target="$managed_root/symlink-target/wt" alias="$TMP/guard-symlink-into-managed"
  mkdir -p "${target%/wt}"
  git -C "$project" worktree add -q --detach "$target" HEAD
  ln -s "$target" "$alias"
  fake_entry="$common/worktrees/fake-symlink"
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$managed_root" run_guarded_worker "$project" \
    "git branch oms/symlink HEAD && mkdir -p '$fake_entry'; printf '%s/.git\\n' '$alias' > '$fake_entry/gitdir'; printf 'ref: refs/heads/oms/symlink\\n' > '$fake_entry/HEAD'")"
  [ "${result%%$'\t'*}" != 0 ] || fail "symlinked managed checkout was accepted: $result"
  rm -rf "$fake_entry" "$alias"
  git -C "$project" worktree remove -f "$target" >/dev/null 2>&1 || true
}

# smoke-weight: 9
test_worker_guard_sees_object_store_and_metadata_writes() {
  local project="$TMP/guard-gitmeta"
  local result

  make_guard_repo "$project"
  # An alternate silently widens where objects may come from.
  result="$(run_guarded_worker "$project" \
    "mkdir -p $project/.git/objects/info && printf '/tmp/elsewhere\n' > $project/.git/objects/info/alternates")"
  [ "${result%%	*}" != 0 ] || fail "adding an object alternate should fail the run"
  contains "$result" 'outside its worktree: gitmeta' ||
    fail "the metadata surface should be named: $result"

  local excl="$TMP/guard-exclude"
  make_guard_repo "$excl"
  local recovery_root="$TMP/guard-exclude-worktrees"
  local recovery_body="printf 'recoverable worker edit\\n' >> file.txt
printf 'drop\\n' >> $excl/.git/info/exclude"
  result="$(OMS_DELEGATE_WORKTREE_ROOT="$recovery_root" run_guarded_worker "$excl" "$recovery_body")"
  [ "${result%%	*}" != 0 ] || fail "editing .git/info/exclude should fail the run"
  contains "$result" 'gitmeta' ||
    fail "an exclude-file edit should be named: $result"
  # Exercise real failed-attempt/index evidence, without --keep-worktree or mocks.
  OMS_DELEGATE_WORKTREE_ROOT="$recovery_root" python3 - "$ROOT/scripts/lib" "$excl" <<'PYTEST' ||
import contextlib, hashlib, io, json, sys
from pathlib import Path
sys.path.insert(0, sys.argv[1])
import panel_results, panel_salvage
repo = Path(sys.argv[2])
rows = panel_results._query(repo, 'artifact-index', 'list', '1000000')['rows']
record, = [row for row in rows if row['kind'] == 'delegate']
body = (repo / record['artifact']).read_bytes()
attempt, = [a for a in panel_results._query(repo, 'agent-events', 'list')
            if a['attempt_id'] == record['attempt_id']]
assert attempt['task_id'] == '' and 'task_id' not in record, 'fixture has a linked task'
assert b'- worktree: temporary (removed after run)' in body, 'fixture opted into retention'
assert hashlib.sha256(body).hexdigest() == record['artifact_sha256']
output = io.StringIO()
with contextlib.redirect_stdout(output):
    assert panel_salvage.cli_main(['--repo', str(repo), '--attempt', record['attempt_id'],
                                  '--artifact', record['artifact'], '--json']) == 0
salvaged = json.loads(output.getvalue())
assert {item['path'] for item in salvaged['files']} == {'file.txt'}, salvaged
assert b'+recoverable worker edit' in Path(salvaged['patch_path']).read_bytes()
assert Path(salvaged['salvaged_from']['kept_path']).is_dir()
PYTEST
    fail "default guard retention did not produce recoverable indexed evidence"
}

