make_live_managed_sibling() {  # make_live_managed_sibling PROJECT SIBLING_PARENT — registered wt + live marker
  local project="$1"
  local sibling_parent="$2"
  local sibling="$sibling_parent/wt"

  mkdir -p "$sibling_parent"
  git -C "$project" worktree add --quiet --detach "$sibling" HEAD >/dev/null 2>&1 ||
    fail "could not create the live managed sibling fixture"
  {
    printf 'kind=oh-my-setting-temp\n'
    printf 'pid=%s\n' "$$"
    printf 'repo=%s\n' "$project"
    printf 'worktree=%s\n' "$sibling"
    printf 'temporary=1\n'
  } > "$sibling_parent/.oh-my-setting-tmp"
}

# An Antigravity read seat as its caller runs it: ma_agy_read_dir from the
# caller's own TMPDIR, held alive by exec so the marker pid stays live until the
# test kills it. OUT receives "PID TREE" once the tree exists; with `pending`
# the checkout is then moved aside, the state an add shows before its checkout.
agy_seat_script() {  # agy_seat_script PATH
  cat > "$1" <<EOF_SEAT
#!/usr/bin/env bash
. "$ROOT/scripts/lib/oms-common.sh"
. "$ROOT/scripts/lib/peer-common.sh"
export TMPDIR="\$2"
tree="\$(ma_agy_read_dir "\$1")" || exit 1
[ "\${4:-}" != pending ] || mv "\$tree" "\${tree%/*}/pending"
printf '%s %s\\n' "\$\$" "\$tree" > "\$3"
exec sleep 600
EOF_SEAT
  chmod +x "$1"
}

agy_seat_wait() {  # agy_seat_wait OUT — bounded by the suite call timeout
  local out="$1" tries=$(( ${OMS_TEST_CALL_TIMEOUT:-120} * 10 ))
  while [ ! -s "$out" ] && [ "$tries" -gt 0 ]; do sleep 0.1; tries=$((tries - 1)); done
  [ -s "$out" ] || fail "agy read seat did not create its tree: $out"
}

agy_seat_stop() {  # agy_seat_stop OUT PROJECT — kill the holder, drop its residue
  local out="$1" pid tree
  read -r pid tree < "$out"
  kill "$pid" 2>/dev/null || true
  rm -rf "${tree%/*}"
  git -C "$2" worktree prune
}

run_delegate_beside_sibling() {  # run_delegate_beside_sibling PROJECT MANAGED_ROOT WORKER_BODY -> "rc<TAB>output"
  local project="$1"
  local managed_root="$2"
  local body="$3"
  local bin_dir="$project-bin"
  local home_dir="$project-home"
  local rc=0
  local out
  local keep_arg="${5:-}"

  printf '#!/usr/bin/env bash\ncat >/dev/null\n%s\necho done\n' "$body" > "$bin_dir/codex"
  chmod +x "$bin_dir/codex"
  out="$(HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x ${4:+--allow-no-change} $keep_arg \
    --no-verify 2>&1)" || rc=$?
  printf '%s\t%s' "$rc" "$out"
}

# smoke-weight: 20
test_worker_guard_exempts_a_live_sibling_mid_removal() {
  local project="$TMP/guard-sibling-removal"
  local managed_root="$TMP/guard-sibling-removal-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.sibling"
  local scratch_parent="$managed_root/oh-my-setting-scratch.sibling"
  local result

  make_guard_repo "$project"
  make_live_managed_sibling "$project" "$sibling_parent"
  make_live_managed_sibling "$project" "$scratch_parent"
  # `git worktree remove` deletes the checkout before the registry entry, so a
  # final capture inside that window sees a registered worktree with no
  # checkout while the sibling's marker is still live. A parent's
  # `oms scratch-worktree remove` passes through the same window.
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "rm -rf $sibling_parent/wt $scratch_parent/wt")"
  [ "${result%%	*}" = 0 ] ||
    fail "a live sibling mid-removal must not fail the run: $result"
  if contains "$result" 'outside the worktree'; then
    fail "a live sibling mid-removal should not be reported as a change: $result"
  fi

  # An Antigravity seat's tree is built from the caller's TMPDIR, not the
  # worker's, yet must read like any managed sibling: the seat's own cleanup
  # and the checkout-first removal window both pass.
  local seat="$TMP/guard-agy-seat.sh" seat_out seat_tree seat_project seat_root scenario seat_pid
  agy_seat_script "$seat"
  for scenario in window cleanup; do
    seat_project="$TMP/guard-agy-removal-$scenario"
    seat_root="$TMP/guard-agy-removal-$scenario-root"
    seat_out="$TMP/guard-agy-removal-$scenario-out"
    make_guard_repo "$seat_project"
    mkdir -p "$seat_root" "$seat_root-seat-tmp"
    OMS_DELEGATE_WORKTREE_ROOT="$seat_root" "$seat" "$seat_project" "$seat_root-seat-tmp" "$seat_out" &
    agy_seat_wait "$seat_out"
    read -r _ seat_tree < "$seat_out"
    case "$seat_tree" in "$seat_root"/oh-my-setting-agy-read.*/tree-*) ;; *)
      fail "a read seat's tree must sit under the delegate worktree root, not its caller's TMPDIR: $seat_tree" ;;
    esac
    case "$scenario" in
      cleanup) result="$(run_delegate_beside_sibling "$seat_project" "$seat_root" \
        ". $ROOT/scripts/lib/oms-common.sh; . $ROOT/scripts/lib/peer-common.sh; ma_agy_read_cleanup $seat_project $seat_tree")" ;;
      *) result="$(run_delegate_beside_sibling "$seat_project" "$seat_root" "rm -rf $seat_tree")" ;;
    esac
    [ "${result%%	*}" = 0 ] ||
      fail "a read seat's tree ($scenario) must not stop a running worker: $result"
    if contains "$result" 'outside the worktree'; then
      fail "a read seat's tree ($scenario) should not be reported as a change: $result"
    fi
    agy_seat_stop "$seat_out" "$seat_project"
  done

  # The root must be its own physical, absolute path, as guards and cleanup
  # require: a linked, link-ancestored or relative root sends the seat back to
  # its TMPDIR and registers nothing under the link's target.
  mkdir -p "$TMP/guard-agy-link-real/root"
  ln -s "$TMP/guard-agy-link-real/root" "$TMP/guard-agy-link-leaf"
  ln -s "$TMP/guard-agy-link-real" "$TMP/guard-agy-link-parent"
  for scenario in leaf parent relative; do
    seat_project="$TMP/guard-agy-link-$scenario-project"
    seat_out="$TMP/guard-agy-link-$scenario-out"
    make_guard_repo "$seat_project"
    mkdir -p "$TMP/guard-agy-link-$scenario-tmp"
    case "$scenario" in
      leaf) seat_root="$TMP/guard-agy-link-leaf" ;;
      parent) seat_root="$TMP/guard-agy-link-parent/root" ;;
      relative) seat_root="relative-root" ;;
    esac
    OMS_DELEGATE_WORKTREE_ROOT="$seat_root" "$seat" "$seat_project" "$TMP/guard-agy-link-$scenario-tmp" "$seat_out" &
    agy_seat_wait "$seat_out"
    read -r _ seat_tree < "$seat_out"
    case "$seat_tree" in "$TMP/guard-agy-link-$scenario-tmp"/oh-my-setting-agy-read.*/tree-*) ;; *)
      fail "a read seat must keep its TMPDIR when the delegate root is unusable ($scenario): $seat_tree" ;;
    esac
    agy_seat_stop "$seat_out" "$seat_project"
  done
  [ -z "$(ls "$TMP/guard-agy-link-real/root")" ] && [ ! -e "$ROOT/relative-root" ] && [ ! -e "$PWD/relative-root" ] ||
    fail "no read tree may register under a linked or relative delegate root"

  # The default root stays private, as delegate makes it, even when it exists.
  seat_project="$TMP/guard-agy-default-project"
  seat_out="$TMP/guard-agy-default-out"
  make_guard_repo "$seat_project"
  seat_root="$TMP/guard-agy-default-cache/oh-my-setting/worktrees"
  mkdir -p "$seat_root" "$TMP/guard-agy-default-tmp"
  chmod 755 "$seat_root"
  env -u OMS_DELEGATE_WORKTREE_ROOT XDG_CACHE_HOME="$TMP/guard-agy-default-cache" \
    "$seat" "$seat_project" "$TMP/guard-agy-default-tmp" "$seat_out" &
  agy_seat_wait "$seat_out"
  read -r _ seat_tree < "$seat_out"
  case "$seat_tree" in "$seat_root"/oh-my-setting-agy-read.*/tree-*) ;; *)
    fail "a read seat must use the default delegate root: $seat_tree" ;;
  esac
  [ "$(ls -ld "$seat_root" | cut -c1-10)" = drwx------ ] ||
    fail "the default delegate root must be private: $(ls -ld "$seat_root")"
  agy_seat_stop "$seat_out" "$seat_project"

  # A killed seat leaves a dead marker and a registration at the new location;
  # cleanup reclaims both rather than keeping them as unverifiable.
  seat_project="$TMP/guard-agy-killed"
  seat_root="$TMP/guard-agy-killed-root"
  seat_out="$TMP/guard-agy-killed-out"
  make_guard_repo "$seat_project"
  mkdir -p "$seat_root" "$seat_root-seat-tmp"
  OMS_DELEGATE_WORKTREE_ROOT="$seat_root" "$seat" "$seat_project" "$seat_root-seat-tmp" "$seat_out" &
  agy_seat_wait "$seat_out"
  read -r seat_pid seat_tree < "$seat_out"
  kill -9 "$seat_pid"
  wait "$seat_pid" 2>/dev/null || true
  [ -d "$seat_tree" ] || fail "the killed seat's tree should remain until cleanup: $seat_tree"
  (cd "$seat_project" && OMS_DELEGATE_WORKTREE_ROOT="$seat_root" "$ROOT/scripts/cleanup.sh" --apply >"$seat_out.cleanup" 2>&1) ||
    fail "cleanup failed on a killed read seat: $(cat "$seat_out.cleanup")"
  [ ! -e "${seat_tree%/*}" ] ||
    fail "cleanup must reclaim a killed read seat under the delegate root: $(cat "$seat_out.cleanup")"
  if git -C "$seat_project" worktree list --porcelain | grep -F "${seat_tree%/*}" >/dev/null; then
    fail "cleanup must unregister a killed read seat's tree"
  fi

  local same_common="$TMP/guard-sibling-commondir-same-common"
  local same_common_root="$TMP/guard-sibling-commondir-same-common-root"
  local same_common_sibling="$same_common_root/oh-my-setting-delegate.sibling"
  make_guard_repo "$same_common"
  make_live_managed_sibling "$same_common" "$same_common_sibling"
  local same_common_body
  same_common_body="metadata=\$(git -C '$same_common_sibling/wt' rev-parse --git-dir); case \"\$metadata\" in /*) ;; *) metadata='$same_common/'\$metadata ;; esac; common=\$(git -C '$same_common' rev-parse --git-common-dir); case \"\$common\" in /*) ;; *) common='$same_common/'\$common ;; esac; printf '%s\\n' \"\$common\" > \"\$metadata/commondir\""
  result="$(run_delegate_beside_sibling "$same_common" "$same_common_root" "$same_common_body")"
  [ "${result%%	*}" != 0 ] ||
    fail "changing a sibling commondir's bytes must stop even when it resolves to the same common directory: $result"

  local bad_common="$TMP/guard-sibling-commondir-rewrite"
  local bad_common_root="$TMP/guard-sibling-commondir-rewrite-root"
  local bad_common_sibling="$bad_common_root/oh-my-setting-delegate.sibling"
  local fake_common="$TMP/guard-sibling-fake-common"
  make_guard_repo "$bad_common"
  make_live_managed_sibling "$bad_common" "$bad_common_sibling"
  local bad_common_body
  bad_common_body="metadata=\$(git -C '$bad_common_sibling/wt' rev-parse --git-dir); case \"\$metadata\" in /*) ;; *) metadata='$bad_common/'\$metadata ;; esac; git init -q '$fake_common' && git -C '$fake_common' -c user.name=guard -c user.email=guard@example.invalid commit --allow-empty -qm fake && fake_common=\$(git -C '$fake_common' rev-parse --git-common-dir); case \"\$fake_common\" in /*) ;; *) fake_common='$fake_common/'\$fake_common ;; esac; printf '%s\\n' \"\$fake_common\" > \"\$metadata/commondir\""
  result="$(run_delegate_beside_sibling "$bad_common" "$bad_common_root" "$bad_common_body")"
  [ "${result%%	*}" != 0 ] ||
    fail "rewriting a live sibling commondir to a fake common directory must stop the worker: $result"

  local outside="$TMP/guard-sibling-gitdir-outside"
  local outside_root="$TMP/guard-sibling-gitdir-outside-root"
  local outside_sibling="$outside_root/oh-my-setting-delegate.sibling"
  make_guard_repo "$outside"
  make_live_managed_sibling "$outside" "$outside_sibling"
  local outside_body
  outside_body="metadata=\$(git -C '$outside_sibling/wt' rev-parse --git-dir); case \"\$metadata\" in /*) ;; *) metadata='$outside/'\$metadata ;; esac; printf '/tmp/outside/.git\\n' > \"\$metadata/gitdir\""
  result="$(run_delegate_beside_sibling "$outside" "$outside_root" "$outside_body")"
  [ "${result%%	*}" != 0 ] ||
    fail "a rewritten sibling gitdir outside the managed root must stop the worker: $result"

  local own_base="$TMP/guard-own-registration-base"
  local own_checkout="$TMP/guard-own-registration"
  make_guard_repo "$own_base"
  git -C "$own_base" worktree add --quiet --detach "$own_checkout" HEAD ||
    fail "could not create the guarded worker's linked checkout"
  mkdir -p "$own_checkout-bin" "$own_checkout-home"
  result="$(run_guarded_worker "$own_checkout" \
    "metadata=\$(git -C '$own_checkout' rev-parse --git-dir); case \"\$metadata\" in /*) ;; *) metadata='$own_base/'\$metadata ;; esac; printf '/tmp/forged/.git\\n' > \"\$metadata/gitdir\"")"
  [ "${result%%	*}" != 0 ] ||
    fail "rewriting the worker's own linked-worktree registration must stop the worker: $result"
}

# smoke-weight: 37
test_worker_guard_exempts_a_live_sibling_mid_creation() {
  local kind
  for kind in delegate scratch; do
    (
      . "$ROOT/scripts/lib/harness-residue.sh"
      . "$ROOT/scripts/lib/oms-common.sh"
      local project="$TMP/guard-live-branch-$kind"
      local root="$TMP/guard-live-branch-root-$kind"
      local sibling="$root/oh-my-setting-$kind.live"
      local snapshot="$TMP/guard-live-branch-snapshot-$kind"
      local changed metadata
      make_guard_repo "$project"
      make_live_managed_sibling "$project" "$sibling"
      export OMS_DELEGATE_WORKTREE_ROOT="$root"
      oms_worker_surface_snapshot "$project" "$snapshot" "$project" || fail "live branch baseline failed"
      # Ref policy is checked separately; this regression isolates the sibling
      # HEAD exemption from the new branch ref created by switch.
      rm "$snapshot/refs" "$snapshot/work-branches"
      git -C "$sibling/wt" switch -q -c x || fail "live sibling could not switch branches"
      changed="$(OMS_WORKER_GUARD_STRICT=1 oms_worker_surface_diff "$project" "$snapshot" "" "$project")" ||
        fail "live sibling branch comparison failed ($kind)"
      [ -z "$changed" ] || fail "baseline live sibling HEAD churn must stay quiet ($kind): $changed"
      metadata="$(git -C "$sibling/wt" rev-parse --git-dir)"
      mv "$sibling/wt" "$sibling/pending"
      rm "$metadata/commondir"
      oms_worker_gitmeta_is_live_managed_worktree "$project" "$metadata/gitdir" "$project" ||
        fail "pending sibling must validate before commondir is written ($kind)"
    )
  done

  local project="$TMP/guard-sibling-creation"
  local managed_root="$TMP/guard-sibling-creation-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.sibling"
  local scratch_parent="$managed_root/oh-my-setting-scratch.sibling"
  local agy_parent="$managed_root/oh-my-setting-agy-read.sibling"
  local live_positive_parent="$managed_root/oh-my-setting-scratch.live-positive"
  local live_zero_parent="$managed_root/oh-my-setting-scratch.live-zero"
  local live_body
  local dead_pid
  local result

  make_guard_repo "$project"
  make_live_managed_sibling "$project" "$sibling_parent"
  live_body="mkdir -p $live_positive_parent && git -C $project worktree add --quiet --detach $live_positive_parent/wt HEAD && printf 'kind=oh-my-setting-temp\\npid=000$$\\nrepo=$project\\nworktree=$live_positive_parent/wt\\ntemporary=1\\n' > $live_positive_parent/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" "$live_body")"
  [ "${result%%	*}" = 0 ] ||
    fail "a newly registered live sibling with a zero-padded positive pid must remain exempt: $result"
  live_body="mkdir -p $live_zero_parent && git -C $project worktree add --quiet --detach $live_zero_parent/wt HEAD && printf 'kind=oh-my-setting-temp\\npid=00\\nrepo=$project\\nworktree=$live_zero_parent/wt\\ntemporary=1\\n' > $live_zero_parent/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" "$live_body")"
  [ "${result%%	*}" = 0 ] ||
    fail "a complete foreign registration needs no OMS owner marker: $result"
  contains "$result" 'during this run: foreign-worktree' ||
    fail "an unowned complete registration should be visible as foreign: $result"
  # The marker is written before `git worktree add`, which registers the entry
  # before the checkout exists: the pre-provider snapshot sees a registered
  # worktree with no checkout, the final capture sees the same entry live.
  mv "$sibling_parent/wt" "$sibling_parent/pending"
  # A parent's `oms scratch-worktree add` orders marker and add the same way;
  # here the final capture lands inside that window of an add begun mid-run.
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    'case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac'"
mv $sibling_parent/pending $sibling_parent/wt && mkdir -p $scratch_parent && printf 'kind=oh-my-setting-temp\\npid=000$$\\nrepo=$project\\nworktree=$scratch_parent/wt\\ntemporary=1\\n' > $scratch_parent/.oh-my-setting-tmp && git -C $project worktree add --quiet --detach $scratch_parent/wt HEAD && mv $scratch_parent/wt $scratch_parent/pending && mkdir -p $agy_parent && printf 'kind=oh-my-setting-temp\\npid=000$$\\nrepo=$project\\nworktree=$agy_parent/tree\\ntemporary=1\\n' > $agy_parent/.oh-my-setting-tmp && git -C $project worktree add --quiet --detach $agy_parent/tree HEAD && mv $agy_parent/tree $agy_parent/pending")"
  [ "${result%%	*}" = 0 ] ||
    fail "a live sibling mid-creation must not fail the run: $result"
  if contains "$result" 'outside the worktree'; then
    fail "a live sibling mid-creation should not be reported as a change: $result"
  fi
  # All-zero markers name no owner (kill -0 0 probes our own process group).
  local zero_parent="$managed_root/oh-my-setting-scratch.zero"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    'case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac'"
mkdir -p $zero_parent && printf 'kind=oh-my-setting-temp\\npid=0\\nrepo=$project\\nworktree=$zero_parent/wt\\ntemporary=1\\n' > $zero_parent/.oh-my-setting-tmp && git -C $project worktree add --quiet --detach $zero_parent/wt HEAD && mv $zero_parent/wt $zero_parent/pending")"
  [ "${result%%	*}" != 0 ] || fail "a pid-0 marker must not exempt a new worktree: $result"

  # A dead owner can keep its detached scratch after the worker returns. The
  # kept path still requires a positive decimal pid before allowing that state.
  dead_pid="$(sh -c 'echo $$')"
  local kept_parent="$managed_root/oh-my-setting-scratch.kept-positive"
  local kept_body
  kept_body="mkdir -p $kept_parent && git -C $project worktree add --quiet --detach $kept_parent/wt HEAD && printf 'kind=oh-my-setting-temp\\npid=000$dead_pid\\nrepo=$project\\nworktree=$kept_parent/wt\\ntemporary=1\\n' > $kept_parent/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" "$kept_body")"
  [ "${result%%	*}" = 0 ] ||
    fail "a kept sibling with a zero-padded positive pid must remain exempt: $result"
  contains "$result" 'during this run: kept-sibling' ||
    fail "a kept padded-pid sibling should retain its soft classification: $result"

  local kept_zero_parent="$managed_root/oh-my-setting-scratch.kept-zero"
  local kept_zero_body
  kept_zero_body="mkdir -p $kept_zero_parent && git -C $project worktree add --quiet --detach $kept_zero_parent/wt HEAD && printf 'kind=oh-my-setting-temp\\npid=00\\nrepo=$project\\nworktree=$kept_zero_parent/wt\\ntemporary=1\\n' > $kept_zero_parent/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" "$kept_zero_body")"
  [ "${result%%	*}" = 0 ] ||
    fail "a complete foreign registration needs no kept marker: $result"
  contains "$result" 'during this run: foreign-worktree' ||
    fail "an invalid kept marker must not hide the foreign registration: $result"

  # A read seat registers its tree mid-run from the caller's own TMPDIR; the
  # add's checkout-less window passes only for a marked, live tree, and an
  # unmarked agy-shaped tree in the same window does not.
  local seat="$TMP/guard-agy-creation-seat.sh" seat_out="$TMP/guard-agy-creation-out" seat_tree
  agy_seat_script "$seat"
  mkdir -p "$managed_root-seat-tmp"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "OMS_DELEGATE_WORKTREE_ROOT=$managed_root $seat $project $managed_root-seat-tmp $seat_out pending & i=0; while [ ! -s $seat_out ] && [ \$i -lt \$(( \${OMS_TEST_CALL_TIMEOUT:-120} * 10 )) ]; do sleep 0.1; i=\$((i + 1)); done")"
  agy_seat_wait "$seat_out"
  read -r _ seat_tree < "$seat_out"
  case "$seat_tree" in "$managed_root"/oh-my-setting-agy-read.*/tree-*) ;; *)
    fail "a read seat's tree must sit under the delegate worktree root, not its caller's TMPDIR: $seat_tree" ;;
  esac
  agy_seat_stop "$seat_out" "$project"
  [ "${result%%	*}" = 0 ] ||
    fail "a read seat's tree mid-creation must not stop a running worker: $result"
  if contains "$result" 'outside the worktree'; then
    fail "a read seat's tree mid-creation should not be reported as a change: $result"
  fi
  local unmarked_parent="$managed_root/oh-my-setting-agy-read.unmarked"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    'case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac'"
mkdir -p $unmarked_parent && git -C $project worktree add --quiet --detach $unmarked_parent/tree-unmarked HEAD && mv $unmarked_parent/tree-unmarked $unmarked_parent/pending")"
  [ "${result%%	*}" != 0 ] ||
    fail "an unmarked read tree mid-creation must stop the worker: $result"
}

# The incident: a parent made a scratch worktree with plain `git worktree add`
# while a write worker ran, and the worker failed on gitmeta. The front door
# marks its registrations, so a parent add and remove mid-run pass; a worker
# calling it is refused; plain Git registrations are visible foreign changes
# (strict behavior is in test_worker_guard_sees_submodule_and_worktree_metadata).
# smoke-weight: 10
test_worker_guard_exempts_parent_scratch_worktrees() {
  local project="$TMP/guard-scratch"
  local managed_root="$TMP/guard-scratch-root"
  local parent_cmd="env -u OMS_HARNESS_CHILD OMS_HARNESS_DELEGATE_DEPTH=0 OMS_DELEGATE_WORKTREE_ROOT=$managed_root $ROOT/scripts/scratch-worktree.sh"
  local bin="$TMP/guard-scratch-oms"
  local existing marker_pid marker_parent dead_parent result

  make_guard_repo "$project"
  mkdir -p "$bin"
  ln -sfn "$ROOT/scripts/oms" "$bin/oms"
  # Through the dispatcher and without --owner-pid, the marker must name a
  # process that outlives the command, or the exemption dies on return.
  existing="$(env -u OMS_HARNESS_CHILD OMS_HARNESS_DELEGATE_DEPTH=0 \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" "$bin/oms" scratch-worktree add --repo "$project")" ||
    fail "parent scratch add failed: $existing"
  marker_parent="$(. "$ROOT/scripts/lib/harness-residue.sh"; oms_harness_residue_parent "$existing")" ||
    fail "scratch path must resolve to its residue parent: $existing"
  marker_pid="$(sed -n 's/^pid=//p' "$marker_parent/.oh-my-setting-tmp")"
  kill -0 "$marker_pid" 2>/dev/null ||
    fail "a scratch marker must outlive the add command (pid $marker_pid)"
  $parent_cmd list --repo "$project" | grep -F "$existing" > /dev/null ||
    fail "list must show the live scratch worktree"
  # Only the worker turn acts; capability probes reach the same stub.
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    'case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac'"
$parent_cmd add --repo $project --owner-pid $$ >/dev/null && $parent_cmd remove $marker_parent >/dev/null && if $ROOT/scripts/scratch-worktree.sh add --repo $project --owner-pid $$ 2>$project-refused; then echo refusal-missing; fi")"
  [ "${result%%	*}" = 0 ] ||
    fail "a parent scratch add/remove during a run must not fail the worker: $result"
  if printf '%s' "$result" | grep >/dev/null -E 'outside the worktree|refusal-missing'; then
    fail "parent scratch lifecycle must be silent and workers refused: $result"
  fi
  grep -Fq 'parent-only' "$project-refused" ||
    fail "a worker's scratch add must say why it was refused: $(cat "$project-refused")"
  [ ! -e "$existing" ] || fail "scratch remove must delete the checkout"
  [ "$(git -C "$project" worktree list --porcelain | grep -c 'oh-my-setting-scratch\.')" = 1 ] ||
    fail "only the scratch worktree added mid-run must remain: $(git -C "$project" worktree list)"
  if $parent_cmd remove "$project" >/dev/null 2>&1; then
    fail "scratch remove must refuse a path it did not create"
  fi

  # An explicit legacy path must not select the marker's suffixed sibling;
  # refusing removal must leave dirty sibling bytes and both registrations.
  local mixed mixed_parent legacy
  mixed="$(env -u OMS_HARNESS_CHILD OMS_HARNESS_DELEGATE_DEPTH=0 \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" "$bin/oms" scratch-worktree add --repo "$project")" ||
    fail "mixed-layout scratch add failed: $mixed"
  mixed_parent="$(. "$ROOT/scripts/lib/harness-residue.sh"; oms_harness_residue_parent "$mixed")" ||
    fail "mixed scratch path must resolve to its residue parent: $mixed"
  legacy="$mixed_parent/wt"
  git -C "$project" worktree add --detach "$legacy" HEAD >/dev/null 2>&1 ||
    fail "could not create legacy sibling checkout"
  printf 'legacy sibling notes\n' > "$legacy/notes.txt"
  cp "$legacy/notes.txt" "${project}-notes.expected"
  if $parent_cmd remove "$legacy" > "$project-mixed-remove.out" 2>&1; then
    fail "scratch remove must refuse a requested checkout that disagrees with its marker"
  fi
  [ -d "$mixed" ] && [ -d "$legacy" ] &&
    cmp -s "${project}-notes.expected" "$legacy/notes.txt" ||
    fail "refused mixed-layout removal changed a checkout or sibling bytes"
  git -C "$project" worktree list --porcelain | grep -F "worktree $mixed" > /dev/null &&
    git -C "$project" worktree list --porcelain | grep -F "worktree $legacy" > /dev/null ||
    fail "refused mixed-layout removal changed worktree registrations"
  $parent_cmd remove --force "$mixed" >/dev/null 2>&1 ||
    fail "--force should remove the marker-selected checkout in a mixed parent"
  [ ! -e "$mixed" ] && [ -d "$legacy" ] && [ -d "$mixed_parent" ] &&
    cmp -s "${project}-notes.expected" "$legacy/notes.txt" ||
    fail "forced removal must preserve a sibling and its parent bytes"
  git -C "$project" worktree list --porcelain | grep -F "worktree $legacy" > /dev/null &&
    ! git -C "$project" worktree list --porcelain | grep -F "worktree $mixed" > /dev/null ||
    fail "forced removal must unregister only the marker-selected checkout"
  rm -rf "$mixed_parent"
  git -C "$project" worktree prune

  # Parent paths remain accepted for a legacy checkout as well as the
  # suffixed checkout exercised above.
  local legacy_parent legacy_parent_worktree
  legacy_parent="$(mktemp -d "$managed_root/oh-my-setting-scratch.legacy.XXXXXX")" ||
    fail "could not create legacy scratch parent"
  legacy_parent_worktree="$legacy_parent/wt"
  git -C "$project" worktree add --detach "$legacy_parent_worktree" HEAD >/dev/null 2>&1 ||
    fail "could not create legacy scratch checkout"
  . "$ROOT/scripts/lib/harness-residue.sh"
  oms_harness_mark_tmpdir "$legacy_parent" "$project" "$legacy_parent_worktree" "$$" ||
    fail "could not mark legacy scratch checkout"
  $parent_cmd remove "$legacy_parent" >/dev/null 2>&1 ||
    fail "scratch parent path must remove its marker-selected legacy checkout"
  [ ! -e "$legacy_parent" ] || fail "legacy scratch parent path was not removed"
  if git -C "$project" worktree list --porcelain | grep -F "worktree $legacy_parent_worktree" > /dev/null; then
    fail "legacy scratch parent removal left its worktree registration"
  fi

  # Once its owner exits, a scratch worktree is ordinary harness residue.
  local owner dead
  sleep 30 &
  owner=$!
  dead="$($parent_cmd add --repo "$project" --owner-pid "$owner")" || fail "scratch add for a dying owner failed"
  kill "$owner"
  wait "$owner" 2>/dev/null || true
  OMS_DELEGATE_WORKTREE_ROOT="$managed_root" bash -c '. "$1"; oms_harness_cleanup_temp_dirs 0' _ \
    "$ROOT/scripts/lib/harness-residue.sh" > "$project-cleanup.out"
  dead_parent="$(. "$ROOT/scripts/lib/harness-residue.sh"; oms_harness_residue_parent "$dead")" ||
    fail "dead scratch path must resolve to its residue parent: $dead"
  [ ! -e "$dead_parent" ] || fail "residue cleanup must remove a dead-owner scratch worktree"
  if git -C "$project" worktree list --porcelain | grep -F "$dead" > /dev/null; then
    fail "residue cleanup must unregister a dead-owner scratch worktree"
  fi
  [ "$(git -C "$project" worktree list --porcelain | grep -c 'oh-my-setting-scratch\.')" = 1 ] ||
    fail "residue cleanup must keep a live-owner scratch worktree"

  # A main switching to its task branch from origin/<default> in its scratch
  # writes branch tracking into the shared config: soft, hard under strict.
  local p track
  for p in "$project-track" "$project-track-strict"; do
    make_guard_repo "$p"
    git -C "$p" remote add origin "$p" && git -C "$p" fetch -q origin ||
      fail "could not create the tracking remote fixture"
    make_live_managed_sibling "$p" "$managed_root/oh-my-setting-scratch.${p##*-}"
    git -C "$p" branch oms/t
  done
  track='case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac
git -C SIB branch --set-upstream-to=origin/'"$(git -C "$project-track" symbolic-ref --short HEAD)"' oms/t'
  result="$(run_delegate_beside_sibling "$project-track" "$managed_root" \
    "${track/SIB/$managed_root/oh-my-setting-scratch.track/wt}")"
  [ "${result%%	*}" = 0 ] ||
    fail "branch tracking written by a sibling scratch must not fail the run: $result"
  contains "$result" 'branch-tracking' ||
    fail "branch tracking should be reported softly: $result"
  result="$(OMS_WORKER_GUARD_STRICT=1 run_delegate_beside_sibling "$project-track-strict" \
    "$managed_root" "${track/SIB/$managed_root/oh-my-setting-scratch.strict/wt}")"
  [ "${result%%	*}" != 0 ] ||
    fail "strict mode must keep branch tracking hard: $result"
}

# smoke-weight: 9
test_worker_guard_flags_a_sibling_whose_marker_died() {
  local project="$TMP/guard-sibling-dead"
  local managed_root="$TMP/guard-sibling-dead-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.sibling"
  local sleep_pid start_id metadata
  local result

  make_guard_repo "$project"
  make_live_managed_sibling "$project" "$sibling_parent"
  # The exemption is a liveness claim re-checked at every capture: an entry
  # that was managed at the pre-provider snapshot inherits nothing once its
  # marker is gone, so a worker cannot hide behind a sibling by killing it.
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "rm -f $sibling_parent/.oh-my-setting-tmp")"
  [ "${result%%	*}" != 0 ] ||
    fail "a sibling whose marker died must stay a hard gitmeta violation: $result"
  contains "$result" 'outside its worktree: gitmeta' ||
    fail "a dead-marker sibling should be named as gitmeta: $result"

  # A reused live PID must not revive an old marker. Damage to its HEAD file
  # must remain visible to both snapshots instead of disappearing as an
  # exempt sibling. The separate sleep process keeps kill -0 positive.
  sleep 60 &
  sleep_pid=$!
  start_id="$(bash -c '. "$1/scripts/lib/file-lock.sh"; oms_file_lock_process_start_token "$2"' \
    _ "$ROOT" "$sleep_pid" 2>/dev/null || true)"
  [ -n "$start_id" ] || {
    kill "$sleep_pid" 2>/dev/null || true
    wait "$sleep_pid" 2>/dev/null || true
    fail "could not read a process-start token for the live sibling fixture"
  }
  metadata="$(git -C "$sibling_parent/wt" rev-parse --git-dir)"
  case "$metadata" in /*) ;; *) metadata="$project/$metadata" ;; esac
  printf 'kind=oh-my-setting-temp\npid=%s\nprocess-start=stale:%s\nrepo=%s\nworktree=%s\ntemporary=1\n' \
    "$sleep_pid" "$start_id" "$project" "$sibling_parent/wt" \
    > "$sibling_parent/.oh-my-setting-tmp"
  if OMS_DELEGATE_WORKTREE_ROOT="$managed_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    oms_worker_gitmeta_is_live_managed_worktree "$2" "$3" "$2"
  ' _ "$ROOT" "$project" "$metadata/HEAD"; then
    kill "$sleep_pid" 2>/dev/null || true
    wait "$sleep_pid" 2>/dev/null || true
    fail "a reused live pid must not exempt a sibling with a stale process-start"
  fi
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "rm -f '$metadata/HEAD'")"
  kill "$sleep_pid" 2>/dev/null || true
  wait "$sleep_pid" 2>/dev/null || true
  [ "${result%%\t*}" != 0 ] ||
    fail "a live reused pid must not exempt a sibling with a stale process-start: $result"
  contains "$result" 'outside its worktree: gitmeta' ||
    fail "a stale process-start sibling must remain visible as gitmeta: $result"
}

# smoke-weight: 14
test_worker_guard_softens_a_sibling_that_finished_kept() {
  local project="$TMP/guard-sibling-kept"
  local managed_root="$TMP/guard-sibling-kept-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.sibling"
  local dead_pid
  local result

  make_guard_repo "$project"
  make_live_managed_sibling "$project" "$sibling_parent"
  dead_pid="$(sh -c 'echo $$')"
  # A sibling that fails keeps its worktree and marker; only its pid dies.
  # That is concurrent harness lifecycle, so the run reports it softly.
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "printf 'kind=oh-my-setting-temp\\npid=$dead_pid\\nrepo=$project\\nworktree=$sibling_parent/wt\\ntemporary=1\\n' > $sibling_parent/.oh-my-setting-tmp")"
  [ "${result%%	*}" = 0 ] ||
    fail "a sibling that finished kept must not fail the run: $result"
  contains "$result" 'during this run: kept-sibling' ||
    fail "a kept sibling should be reported as a soft change: $result"

  # A main keeps using its scratch after the owner pid died: only that
  # residue entry's HEAD moves. Soft by default, hard under strict mode.
  local p moved
  for p in "$project-moved" "$project-moved-strict"; do
    make_guard_repo "$p"
    make_live_managed_sibling "$p" "$sibling_parent${p#"$project"}"
    printf 'kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s\ntemporary=1\n' \
      "$dead_pid" "$p" "$sibling_parent${p#"$project"}/wt" \
      > "$sibling_parent${p#"$project"}/.oh-my-setting-tmp"
  done
  moved='case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac
git -C SIB -c user.email=t@example.com -c user.name=t commit -q --allow-empty -m moved'
  result="$(run_delegate_beside_sibling "$project-moved" "$managed_root" \
    "${moved/SIB/$sibling_parent-moved/wt}")"
  [ "${result%%	*}" = 0 ] ||
    fail "a HEAD move in a dead-owner scratch must not fail the run: $result"
  contains "$result" 'during this run: kept-sibling' ||
    fail "a HEAD move in a dead-owner scratch should be reported softly: $result"
  result="$(OMS_WORKER_GUARD_STRICT=1 run_delegate_beside_sibling "$project-moved-strict" \
    "$managed_root" "${moved/SIB/$sibling_parent-moved-strict/wt}")"
  [ "${result%%	*}" != 0 ] ||
    fail "strict mode must keep a dead-owner scratch HEAD move hard: $result"

  # Admission runs beside the delegate root in the caller's temporary base.
  # The post-attempt guard must retain that base while the provider uses its
  # private TMPDIR, including for a sibling registered after the snapshot.
  # Strict mode must retain the quiet live exemption; a soft fallback hides
  # an in-run misclassification once the final guard uses the caller's base.
  local temp_project="$project-tmp"
  local caller_tmp="$TMP/guard-sibling-caller-tmp"
  local admit_parent="$caller_tmp/oh-my-setting-admit.snapshot"
  local admit_worktree="$admit_parent/wt-snapshot"
  local metadata
  make_guard_repo "$temp_project"
  mkdir -p "$caller_tmp"
  result="$(OMS_WORKER_GUARD_STRICT=1 TMPDIR="$caller_tmp" run_delegate_beside_sibling "$temp_project" "$managed_root" \
    'case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac'"
set -e
test \"\$TMPDIR\" != '$caller_tmp'
mkdir -p '$admit_parent'
git -C '$temp_project' worktree add --quiet --detach '$admit_worktree' HEAD
printf 'kind=oh-my-setting-temp\\npid=%s\\nrepo=%s\\nworktree=%s\\ntemporary=1\\n' \
  '$$' '$temp_project' '$admit_worktree' > '$admit_parent/.oh-my-setting-tmp'")"
  [ "${result%%	*}" = 0 ] ||
    fail "a live admit sibling in the snapshot TMPDIR must not fail the run: $result"
  if contains "$result" 'owner authority'; then
    fail "a live admit sibling must not report an owner authority violation: $result"
  fi

  # Restoring the trusted base must preserve the hard surface for an existing
  # sibling's canonical wiring, and name the guard stop accurately.
  metadata="$(git -C "$admit_worktree" rev-parse --git-dir)"
  metadata="${metadata//$'\r'/}"
  case "$metadata" in /*) ;; *) metadata="$temp_project/$metadata" ;; esac
  result="$(TMPDIR="$caller_tmp" run_delegate_beside_sibling "$temp_project" "$managed_root" \
    'case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac'"
printf '%s\\n' '$temp_project/.git' > '$metadata/gitdir'")"
  [ "${result%%	*}" != 0 ] ||
    fail "editing a TMPDIR sibling's gitdir must remain hard: $result"
  contains "$result" 'outside its worktree: gitmeta' ||
    fail "a TMPDIR sibling gitdir edit must name the gitmeta surface: $result"
  if contains "$result" 'changed owner authority shared-state'; then
    fail "a gitmeta guard stop must not be labelled owner authority: $result"
  fi
}

# Force one admin scan across marker visibility, after the baseline and the
# first validated observation. The real metadata remains registered throughout
# that scan, so HEAD and gitdir both enter the delta.
# smoke-weight: 106
test_worker_guard_accepts_new_managed_sibling_after_capture_race() {
  local scenario failed=0
  for scenario in kept removed settling-checkout unsettled-checkout kept-live-head soft-live-head soft-fingerprint-before soft-fingerprint-after protected-ref protected-head protected-index protected-late-ref protected-late-head protected-late-index protected-soft-ref protected-soft-head protected-soft-index head-sha256 settling unsettled unproven-removal unmarked outside symbolic-head mismatched-backpointer \
    changed-gitdir changed-commondir head-empty head-zero head-short head-long \
    head-malformed head-sha256-short head-sha256-long head-sha256-malformed head-symlink head-fifo commondir-symlink extra-exclude own-slot; do
    # Report both reproductions before stopping a failed pre-fix run. Later
    # safety cases exercise the new classifier's stricter admin contract.
    case "$scenario:$failed" in kept:*|removed:*|protected-*:*|*:0) ;; *) break ;; esac
    (
      . "$ROOT/scripts/lib/harness-residue.sh"
      . "$ROOT/scripts/lib/oms-common.sh"
      local project="$TMP/guard-new-sibling-$scenario"
      local managed_root="$TMP/guard-new-sibling-root-$scenario"
      local snapshot="$TMP/guard-new-sibling-snapshot-$scenario"
      local sibling="$managed_root/oh-my-setting-delegate.new"
      local metadata slot changed worker="$project" alternate blob strict=1
      local second_alternate initial_live_head dead_pid
      local existing="$managed_root/oh-my-setting-delegate.existing" existing_metadata
      if [ "$scenario" = head-sha256 ]; then
        if ! git init --quiet --object-format=sha256 "$project" > "$TMP/sha256-probe" 2>&1; then
          printf 'skip: Git does not support SHA-256 repositories\n'
          exit 0
        fi
      fi
      make_guard_repo "$project"
      case "$scenario" in protected-soft-*|kept-live-head|soft-*) strict=0 ;; esac
      case "$scenario" in
        protected-*|kept-live-head|soft-live-head)
          alternate="$(printf 'alternate commit\n' | git -C "$project" commit-tree 'HEAD^{tree}' -p HEAD)" || exit 1
          blob="$(printf 'alternate staged content\n' | git -C "$project" hash-object -w --stdin)" || exit 1
          second_alternate="$(printf 'second alternate commit\n' | git -C "$project" commit-tree 'HEAD^{tree}' -p HEAD)" || exit 1
          ;;
      esac
      export OMS_DELEGATE_WORKTREE_ROOT="$managed_root"
      [ "$scenario" != outside ] || sibling="$TMP/guard-new-outside/oh-my-setting-delegate.new"
      case "$scenario" in
        changed-*|extra-exclude|kept-live-head|soft-live-head)
          make_live_managed_sibling "$project" "$existing"
          existing_metadata="$(git -C "$existing/wt" rev-parse --git-dir)"
          initial_live_head="$(cat "$existing_metadata/HEAD")"
          ;;
      esac
      oms_worker_surface_snapshot "$project" "$snapshot" "$project" || fail "new sibling baseline failed"
      [ -d "$sibling/wt" ] || make_live_managed_sibling "$project" "$sibling"
      metadata="$(git -C "$sibling/wt" rev-parse --git-dir)"
      slot="${metadata##*/}"
      ! grep -Fq "worktrees/$slot/" "$snapshot/gitmeta" || fail "sibling entered baseline"
      if [ "$scenario" = head-sha256 ]; then
        [ "$(git -C "$sibling/wt" rev-parse HEAD | tr -d '\n' | wc -c | tr -d ' ')" = 64 ] ||
          fail "SHA-256 fixture did not create a 64-hex detached HEAD"
      fi
      case "$scenario" in
        kept-live-head)
          dead_pid="$(sh -c 'echo $$')"
          sed "s/^pid=.*/pid=$dead_pid/" "$sibling/.oh-my-setting-tmp" > "$snapshot/dead-marker"
          mv "$snapshot/dead-marker" "$sibling/.oh-my-setting-tmp"
          ;;
        unmarked) rm "$sibling/.oh-my-setting-tmp" ;;
        symbolic-head) printf 'ref: %s\n' "$(git -C "$project" symbolic-ref HEAD)" > "$metadata/HEAD" ;;
        mismatched-backpointer) printf '%s/.git\n' "$project" > "$metadata/gitdir" ;;
        changed-gitdir) printf '%s/wt/./.git\n' "$existing" > "$existing_metadata/gitdir" ;;
        changed-commondir) printf '../../.\n' > "$existing_metadata/commondir" ;;
        head-empty) : > "$metadata/HEAD" ;;
        head-zero) printf '0\n' > "$metadata/HEAD" ;;
        head-short) printf '%039d\n' 0 > "$metadata/HEAD" ;;
        head-long) printf '%041d\n' 0 > "$metadata/HEAD" ;;
        head-malformed) printf '%039dx\n' 0 > "$metadata/HEAD" ;;
        head-sha256-short) printf '%063d\n' 0 > "$metadata/HEAD" ;;
        head-sha256-long) printf '%065d\n' 0 > "$metadata/HEAD" ;;
        head-sha256-malformed) printf '%063dx\n' 0 > "$metadata/HEAD" ;;
        head-symlink|commondir-symlink)
          local field=HEAD
          [ "$scenario" != commondir-symlink ] || field=commondir
          mv "$metadata/$field" "$snapshot/original-$field"
          ln -s "$snapshot/original-$field" "$metadata/$field"
          ;;
        head-fifo) ;;
        extra-exclude) printf '# unrelated edit\n' >> "$project/.git/info/exclude" ;;
        own-slot) worker="$sibling/wt" ;;
      esac
      eval "$(declare -f oms_worker_surface_capture_one |
        sed '1s/oms_worker_surface_capture_one/new_sibling_real_capture/')"
      eval "$(declare -f oms_worker_gitmeta_admin_changes_are_safe |
        sed '1s/oms_worker_gitmeta_admin_changes_are_safe/new_sibling_real_admin/')"
      oms_worker_surface_capture_one() {
        if [ "$2" = gitmeta ] && [ -f "$sibling/.oh-my-setting-tmp" ] &&
          { [ "$scenario" = unproven-removal ] ||
            { [ "${capture_race:-0}" = 1 ] &&
              case "$scenario" in kept|removed|settling|settling-checkout|unsettled|unsettled-checkout|protected-*|head-*|symbolic-head|changed-*|extra-exclude|soft-*) true ;; *) false ;; esac; }; }; then
          mv "$sibling/.oh-my-setting-tmp" "$sibling/marker-pending" || return 1
          new_sibling_real_capture "$@" > "$snapshot/raced-capture" || return 1
          mv "$sibling/marker-pending" "$sibling/.oh-my-setting-tmp" || return 1
          grep -Fq "worktrees/$slot/HEAD " "$snapshot/raced-capture" || return 1
          grep -Fq "worktrees/$slot/gitdir " "$snapshot/raced-capture" || return 1
          cat "$snapshot/raced-capture"
          if [ "${capture_race:-0}" = 1 ] &&
            { [ "$scenario" = removed ] || [ "$scenario" = unproven-removal ]; }; then
            git -C "$project" worktree remove --force "$sibling/wt" || return 1
            rm -rf "$sibling"
          fi
        else
          new_sibling_real_capture "$@"
        fi
      }
      oms_worker_gitmeta_admin_changes_are_safe() {
        local capture_race=1
        new_sibling_real_admin "$@" || return
        if [ "$scenario" = kept-live-head ]; then
          # Exercise real baseline-sibling churn even when the kept candidate
          # correctly skips every added-sibling fingerprint call.
          printf '%s\n' "$alternate" > "$existing_metadata/HEAD"
        fi
      }
      eval "$(declare -f oms_worker_gitmeta_settles |
        sed '1s/oms_worker_gitmeta_settles/new_sibling_real_settles/')"
      oms_worker_gitmeta_settles() {
        [ -z "${4:-}" ] || : > "$snapshot/added-retry"
        new_sibling_real_settles "$@"
      }
      local boundary_calls=0
      eval "$(declare -f oms_worker_surface_boundary_fingerprint |
        sed '1s/oms_worker_surface_boundary_fingerprint/new_sibling_real_boundary/')"
      new_sibling_change_protected() {
        case "$scenario" in
          protected-*ref) git -C "$project" update-ref refs/heads/audit "$alternate" ;;
          protected-*head) printf '%s\n' "$alternate" > "$project/.git/HEAD" ;;
          protected-*index) git -C "$project" update-index --cacheinfo "100644,$blob,file.txt" ;;
        esac
      }
      oms_worker_surface_boundary_fingerprint() {
        printf 'capture\n' >> "$snapshot/added-boundary-calls"
        boundary_calls=$((boundary_calls + 1))
        # A later attempt must retain the first observation even if its own
        # before/after pair sees the same, newly changed protected state.
        case "$scenario" in
          protected-late-*)
            [ "$boundary_calls" != 3 ] || new_sibling_change_protected || return 1
            ;;
        esac
        if [ "$scenario" = soft-fingerprint-before ] ||
          { [ "$scenario" = soft-fingerprint-after ] && [ "$boundary_calls" = 2 ]; }; then
          return 1
        fi
        new_sibling_real_boundary "$@" || return 1
        case "$scenario" in
          settling-checkout|unsettled-checkout)
            if [ "$boundary_calls" = 1 ] && [ -d "$sibling/wt" ]; then
              mv "$sibling/wt" "$sibling/pending"
            elif [ "$boundary_calls" = 2 ] && [ "$scenario" = settling-checkout ]; then
              mv "$sibling/pending" "$sibling/wt"
            fi
            ;;
          kept-live-head|soft-live-head)
            [ "$boundary_calls" != 1 ] || printf '%s\n' "$second_alternate" > "$existing_metadata/HEAD"
            ;;
          protected-*)
            if [ "$boundary_calls" = 1 ]; then
              case "$scenario" in protected-late-*) ;; *) new_sibling_change_protected || return 1 ;; esac
              printf '../../.\n' > "$metadata/commondir"
            fi
            ;;
          settling|unsettled)
            if [ "$scenario" = unsettled ] || [ "$boundary_calls" = 1 ]; then
              if [ "$((boundary_calls % 2))" = 1 ]; then
                printf '../../.\n' > "$metadata/commondir"
              else
                printf '../..\n' > "$metadata/commondir"
              fi
            fi
            ;;
        esac
      }
      if [ "$scenario" = head-fifo ]; then
        # A FIFO is a new-classifier type check, not a change to the shared
        # validator's contract. Freeze the eligible delta before planting it.
        oms_worker_gitmeta_admin_changes_are_safe "$project" "$snapshot" "$worker" ||
          fail "FIFO fixture could not capture its eligible delta"
        rm "$metadata/HEAD"
        mkfifo "$metadata/HEAD"
        if oms_worker_gitmeta_only_added_managed_siblings "$project" "$snapshot" "$worker"; then
          fail "new classifier accepted a FIFO HEAD"
        fi
        exit 0
      fi
      changed="$(OMS_WORKER_GUARD_STRICT="$strict" oms_worker_surface_diff "$project" "$snapshot" "" "$worker")" ||
        fail "new sibling comparison failed ($scenario)"
      case "$scenario" in
        kept-live-head|soft-*)
          [ "$changed" = kept-sibling ] || fail "concurrent sibling lifecycle must remain soft ($scenario): $changed"
          case "$scenario" in
            *live-head)
              [ "$(cat "$existing_metadata/HEAD")" != "$initial_live_head" ] ||
                fail "baseline live sibling did not move its detached HEAD ($scenario)"
              ;;
          esac
          if [ "$scenario" = kept-live-head ]; then
            [ ! -e "$snapshot/added-boundary-calls" ] && [ ! -e "$snapshot/added-retry" ] ||
              fail "kept candidate reached the live added-sibling classifier"
          fi
          ;;
        kept|removed|settling|settling-checkout|head-sha256)
          [ -z "$changed" ] || fail "validated new sibling must stay quiet ($scenario): $changed"
          grep -Fq 'added-managed-sibling=yes' "$snapshot/gitmeta-trace" ||
            fail "new sibling race missed its classifier ($scenario)"
          if [ "$scenario" = settling-checkout ]; then
            [ -e "$snapshot/added-retry" ] || fail "pending checkout did not exercise the live retry"
          fi
          if [ "$scenario" = kept ] && command -v oms_worker_gitmeta_added_admin_is_safe >/dev/null; then
            local common invalid_common
            common="$(oms_harness_git_path_physical "$project" --git-common-dir)"
            cp "$metadata/commondir" "$snapshot/original-commondir"
            for invalid_common in '' 0 missing-common "$TMP"; do
              printf '%s\n' "$invalid_common" > "$metadata/commondir"
              if oms_worker_gitmeta_added_admin_is_safe "$common" "$slot" 2>/dev/null; then
                fail "new classifier accepted an invalid common directory"
              fi
            done
            cp "$snapshot/original-commondir" "$metadata/commondir"
            oms_worker_gitmeta_added_admin_is_safe "$common" "$slot" ||
              fail "new classifier rejected the restored common directory"
          fi
          if [ "$scenario" = kept ] && command -v oms_worker_gitmeta_added_boundary_matches >/dev/null; then
            local malformed malformed_details
            for malformed in '' 0 invalid "$(printf '%063d' 0)" "$(printf '%065d' 0)"; do
              awk -F '\t' -v digest="$malformed" 'BEGIN { OFS="\t" } $1 == "refs" { $2=digest } { print }' \
                "$snapshot/gitmeta-added-details-before" > "$snapshot/malformed-details"
              malformed_details="$(cat "$snapshot/malformed-details")"
              if oms_worker_gitmeta_added_boundary_matches "$malformed_details" "$snapshot/malformed-details"; then
                fail "malformed protected-state evidence was accepted: $malformed"
              fi
            done
          fi
          ;;
        *)
          [ -n "$changed" ] || fail "unsafe sibling stayed quiet ($scenario)"
          case "$scenario" in
            protected-*)
              case "$changed" in *gitmeta*) ;; *) fail "protected retry mutation was softened ($scenario): $changed" ;; esac
              grep -Fq 'added-protected-state-changed=yes' "$snapshot/gitmeta-trace" ||
                fail "protected retry mutation missed the hard classifier ($scenario)"
              ;;
            changed-*|extra-exclude)
              # The eligible new slot must reach the HEAD/directory path even
              # while a separate baseline sibling or non-slot leaf is changed.
              grep -Fq "worktrees/$slot/HEAD " "$snapshot/gitmeta-admin-now" ||
                fail "mixed-change fixture missed its eligible sibling ($scenario)"
              oms_worker_gitmeta_is_live_managed_worktree "$project" "$metadata/gitdir" "$worker" ||
                fail "mixed-change fixture lacks a valid new managed sibling ($scenario)"
              ;;
          esac
          # A standalone call starts a fresh observation; retry mutations
          # are checked by the complete surface comparison above.
          if [ "${scenario#protected-}" = "$scenario" ] &&
            command -v oms_worker_gitmeta_only_added_managed_siblings >/dev/null &&
            oms_worker_gitmeta_only_added_managed_siblings "$project" "$snapshot" "$worker"; then
            fail "new classifier accepted unsafe sibling ($scenario)"
          fi
          case "$scenario" in
            changed-*|extra-exclude)
              [ ! -e "$snapshot/added-boundary-calls" ] && [ ! -e "$snapshot/added-retry" ] ||
                fail "ineligible delta reached a costly added-sibling scan or retry ($scenario)"
              ;;
          esac
          ;;
      esac
    ) || failed=1
  done
  [ "$failed" = 0 ] || fail "new managed sibling capture races failed"
}

# The incident that serialized every main's launches: sibling B starts after
# worker A's snapshot and finishes kept before A's final check. A detached kept
# sibling new to the baseline is reported softly; strict mode and a sibling on
# a branch stay hard. A same-UID worker could forge this shape too, so it is
# false-positive relief for cooperative runs, not attribution.
# smoke-weight: 69
test_worker_guard_softens_a_sibling_started_and_kept_mid_run() {
  local project="$TMP/guard-sibling-late"
  local managed_root="$TMP/guard-sibling-late-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.late"
  local live_a="$managed_root/oh-my-setting-delegate.live-a"
  local live_b="$managed_root/oh-my-setting-scratch.live-b"
  local finished="$managed_root/oh-my-setting-agy-read.finished"
  local common metadata target pending_count=0
  local dead_pid
  local body
  local result
  local first_artifact second_artifact first_tree second_tree first_slot second_slot
  local fake_bin="$TMP/guard-sibling-late-bin"
  local fake_home="$TMP/guard-sibling-late-home"

  make_guard_repo "$project"
  mkdir -p "$fake_bin"
  printf '#!/usr/bin/env bash\ncat >/dev/null\n: > "$TMPDIR/scratch"\necho done\n' > "$fake_bin/codex"
  chmod +x "$fake_bin/codex"
  result="$(PATH="$fake_bin:/usr/bin:/bin" HOME="$fake_home" \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --allow-no-change --no-verify --keep-worktree 2>&1)" ||
    fail "first kept delegate checkout failed: $result"
  first_artifact="$(printf '%s\n' "$result" | sed -n 's/^artifact: //p' | tail -n 1)"
  first_tree="$(sed -n 's/^- worktree: //p' "$first_artifact" | sed -n '1p')"
  [ -d "$first_tree" ] && [ ! -e "${first_tree%/*}/tmp" ] ||
    fail "a kept delegate checkout must not keep its worker temporary directory: $first_tree"
  result="$(PATH="$fake_bin:/usr/bin:/bin" HOME="$fake_home" \
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex --prompt x \
    --allow-no-change --no-verify --keep-worktree 2>&1)" ||
    fail "second kept delegate checkout failed: $result"
  second_artifact="$(printf '%s\n' "$result" | sed -n 's/^artifact: //p' | tail -n 1)"
  second_tree="$(sed -n 's/^- worktree: //p' "$second_artifact" | sed -n '1p')"
  first_slot="$(git -C "$first_tree" rev-parse --git-dir)"; first_slot="${first_slot##*/}"
  second_slot="$(git -C "$second_tree" rev-parse --git-dir)"; second_slot="${second_slot##*/}"
  [ -n "$first_tree" ] && [ -n "$second_tree" ] && [ "$first_slot" != "$second_slot" ] ||
    fail "consecutive delegate checkouts must use different Git admin slots: $first_tree ($first_slot), $second_tree ($second_slot)"
  git -C "$project" worktree remove --force "$first_tree" >/dev/null 2>&1 || true
  git -C "$project" worktree remove --force "$second_tree" >/dev/null 2>&1 || true
  rm -rf "${first_tree%/*}" "${second_tree%/*}"
  git -C "$project" worktree prune >/dev/null 2>&1 || true
  dead_pid="$(sh -c 'echo $$')"
  body="mkdir -p $sibling_parent && git -C $project worktree add --quiet --detach $sibling_parent/wt HEAD >/dev/null 2>&1 && printf 'kind=oh-my-setting-temp\\npid=$dead_pid\\nrepo=$project\\nworktree=$sibling_parent/wt\\ntemporary=1\\n' > $sibling_parent/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" "$body" --allow-no-change)"
  [ "${result%%	*}" = 0 ] ||
    fail "a sibling started and kept mid-run must not fail the run: $result"
  contains "$result" 'during this run: kept-sibling' ||
    fail "a late kept sibling should be reported as a soft change: $result"

  # Match the overlapping-dispatch case: two registered siblings stay live
  # through comparison while a third sibling completes its add/remove cycle.
  # Keep the live entries in Git's registration window (admin leaves exist,
  # checkout is not materialized) so the guard must use its validated quiet
  # lifecycle classification rather than the kept-checkout classifier.
  local concurrent_body
  concurrent_body="set -e
mkdir -p $live_a $live_b $finished
printf 'kind=oh-my-setting-temp\\npid=$$\\nrepo=$project\\nworktree=$live_a/wt\\ntemporary=1\\n' > $live_a/.oh-my-setting-tmp
printf 'kind=oh-my-setting-temp\\npid=$$\\nrepo=$project\\nworktree=$live_b/wt\\ntemporary=1\\n' > $live_b/.oh-my-setting-tmp
git -C $project worktree add --quiet --detach $live_a/wt HEAD && git -C $project worktree add --quiet --detach $live_b/wt HEAD && metadata_a=\$(git -C $live_a/wt rev-parse --git-dir) && metadata_b=\$(git -C $live_b/wt rev-parse --git-dir) && case \"\$metadata_a\" in /*) ;; *) metadata_a=\"$project/\$metadata_a\" ;; esac && case \"\$metadata_b\" in /*) ;; *) metadata_b=\"$project/\$metadata_b\" ;; esac && mv $live_a/wt $live_a/pending && mv $live_b/wt $live_b/pending && rm -f \"\$metadata_a/HEAD\" \"\$metadata_b/HEAD\" && test ! -e \"\$metadata_a/HEAD\" && test ! -e \"\$metadata_b/HEAD\" && printf 'kind=oh-my-setting-temp\\npid=$dead_pid\\nrepo=$project\\nworktree=$finished/tree\\ntemporary=1\\n' > $finished/.oh-my-setting-tmp && git -C $project worktree add --quiet --detach $finished/tree HEAD && git -C $project worktree remove --force $finished/tree && rm -rf $finished && echo pending-registration-repro"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" "$concurrent_body")"
  [ "${result%%	*}" = 0 ] ||
    fail "two live registered siblings plus one completed sibling must stay quiet: $result"
  common="$(git -C "$project" rev-parse --git-common-dir)"
  case "$common" in /*) ;; *) common="$project/$common" ;; esac
  for metadata in "$common"/worktrees/*; do
    [ -f "$metadata/gitdir" ] || continue
    target="$(sed -n '1p' "$metadata/gitdir")"
    target="${target%/.git}"
    case "$target" in
      "$live_a/wt"|"$live_b/wt")
        [ ! -e "$metadata/HEAD" ] && pending_count=$((pending_count + 1))
        ;;
    esac
  done
  [ "$pending_count" = 2 ] ||
    fail "the fixture must leave two live registrations headless at comparison (found $pending_count)"
  git -C "$project" worktree prune --expire now >/dev/null 2>&1 || true
  rm -rf "$live_a" "$live_b"
  if contains "$result" 'outside the worktree'; then
    fail "live sibling registrations must not be reported as gitmeta changes: $result"
  fi

  # Reproduce a non-atomic remove: the intermediate admin capture sees a
  # validated managed add, then compare starts after its checkout and HEAD
  # disappear while the admin leaves remain.
  local transient="$project-transient"
  local transient_snap="$TMP/guard-sibling-transient-snapshot"
  make_guard_repo "$transient"
  OMS_DELEGATE_WORKTREE_ROOT="$managed_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    repo="$2" root="$3" snap="$4"
    ready_fifo="$5" removal_done="$snap/removal-done"
    removal_failed="$snap/removal-failed"
    rm -f "$ready_fifo" "$removal_done" "$removal_failed"
    mkfifo "$ready_fifo" || exit 14
    wait_for_removal() {
      wait_count=0
      while [ ! -e "$removal_done" ] && [ "$wait_count" -lt 1000 ]; do
        command sleep 0.01
        wait_count=$((wait_count + 1))
      done
      [ -e "$removal_done" ]
    }
    poll_signal_sent=0
    # Coordinate the simulated removal with the first partial-removal
    # poll. The 0.3s settle captures still use the real sleep; only the
    # partial-removal wait is held until the fixture removes the sibling.
    sleep() {
      if [ "${1:-}" = 0.1 ] && [ "$poll_signal_sent" = 0 ]; then
        poll_signal_sent=1
        printf "compare-poll\n" > "$ready_fifo" || {
          : > "$removal_failed"
          return 1
        }
        if ! wait_for_removal; then
          : > "$removal_failed"
          return 1
        fi
      fi
      command sleep "$@"
    }
    oms_worker_surface_snapshot "$repo" "$snap" "$repo" || exit 10
    mkdir -p "$root/oh-my-setting-delegate.transient"
    printf "kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s/wt\ntemporary=1\n" \
      "$$" "$repo" "$root/oh-my-setting-delegate.transient" \
      > "$root/oh-my-setting-delegate.transient/.oh-my-setting-tmp"
    git -C "$repo" worktree add --quiet --detach \
      "$root/oh-my-setting-delegate.transient/wt" HEAD || exit 11
    metadata="$(git -C "$root/oh-my-setting-delegate.transient/wt" rev-parse --git-dir)"
    case "$metadata" in /*) ;; *) metadata="$repo/$metadata" ;; esac
    OMS_WG_GITMETA_MANAGED_ADDED_OUT="$snap/gitmeta-managed-added" \
      OMS_WG_GITMETA_MANAGED_COMPLETE_OUT="$snap/gitmeta-managed-complete" \
      oms_worker_surface_capture_one "$repo" gitmeta "$repo" \
      > "$snap/intermediate-gitmeta" || exit 12
    oms_worker_gitmeta_admin_changes_are_safe "$repo" "$snap" "$repo" || exit 12
    [ -s "$snap/gitmeta-managed-added" ] || exit 13
    common="$(git -C "$repo" rev-parse --git-common-dir)"
    case "$common" in /*) ;; *) common="$repo/$common" ;; esac
    entry="$(sed -n 1p "$snap/gitmeta-managed-added")"
    rm -rf "$root/oh-my-setting-delegate.transient/wt"
    rm -f "$metadata/HEAD"
    (
      IFS= read -r _ < "$ready_fifo" || exit 1
      rm -rf "$common/worktrees/$entry" \
        "$root/oh-my-setting-delegate.transient" || exit 1
      : > "$removal_done"
    ) &
    remove_pid=$!
    changed="$(oms_worker_surface_diff "$repo" "$snap" "" "$repo")"
    if [ -e "$removal_failed" ] || ! wait_for_removal; then
      kill -KILL "$remove_pid" 2>/dev/null || true
      exit 18
    fi
    case "$changed" in *gitmeta*) exit 15 ;; esac
    # The FIFO releases removal inside the compare poll; an empty change set
    # is equally correct if the next capture sees the completed cleanup.
    case "$changed" in *kept-sibling*|"") ;; *) exit 16 ;; esac
    if OMS_WORKER_GUARD_STRICT=1 \
      oms_worker_gitmeta_only_added_removed_siblings "$repo" "$snap" "$repo"; then
      exit 17
    fi
  ' _ "$ROOT" "$transient" "$managed_root" "$transient_snap" \
    "$TMP/guard-sibling-transient-ready.fifo" ||
    fail "a validated partially removed sibling that finishes during compare must be soft (rc=$?)"

  local transient_stuck="$project-transient-stuck"
  local transient_stuck_snap="$TMP/guard-sibling-transient-stuck-snapshot"
  make_guard_repo "$transient_stuck"
  OMS_DELEGATE_WORKTREE_ROOT="$managed_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    repo="$2" root="$3" snap="$4"
    oms_worker_surface_snapshot "$repo" "$snap" "$repo" || exit 40
    mkdir -p "$root/oh-my-setting-delegate.transient-stuck"
    printf "kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s/wt\ntemporary=1\n" \
      "$$" "$repo" "$root/oh-my-setting-delegate.transient-stuck" \
      > "$root/oh-my-setting-delegate.transient-stuck/.oh-my-setting-tmp"
    git -C "$repo" worktree add --quiet --detach \
      "$root/oh-my-setting-delegate.transient-stuck/wt" HEAD || exit 41
    OMS_WG_GITMETA_MANAGED_ADDED_OUT="$snap/gitmeta-managed-added" \
      OMS_WG_GITMETA_MANAGED_COMPLETE_OUT="$snap/gitmeta-managed-complete" \
      oms_worker_surface_capture_one "$repo" gitmeta "$repo" \
      > "$snap/intermediate-gitmeta" || exit 42
    oms_worker_gitmeta_admin_changes_are_safe "$repo" "$snap" "$repo" || exit 43
    [ -s "$snap/gitmeta-managed-added" ] || exit 44
    metadata="$(git -C "$root/oh-my-setting-delegate.transient-stuck/wt" rev-parse --git-dir)"
    case "$metadata" in /*) ;; *) metadata="$repo/$metadata" ;; esac
    rm -rf "$root/oh-my-setting-delegate.transient-stuck/wt"
    rm -f "$metadata/HEAD"
    changed="$(oms_worker_surface_diff "$repo" "$snap" "" "$repo")"
    case "$changed" in *gitmeta*) ;; *) exit 45 ;; esac
  ' _ "$ROOT" "$transient_stuck" "$managed_root" "$transient_stuck_snap" ||
    fail "a validated partial sibling removal that remains stuck must stay hard (rc=$?)"

  # A sibling still registering must not mask another sibling's stuck removal.
  local transient_mixed="$project-transient-mixed"
  local transient_mixed_snap="$TMP/guard-sibling-transient-mixed-snapshot"
  make_guard_repo "$transient_mixed"
  OMS_DELEGATE_WORKTREE_ROOT="$managed_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    repo="$2" root="$3" snap="$4"
    oms_worker_surface_snapshot "$repo" "$snap" "$repo" || exit 60
    for name in mixed-stuck mixed-pending; do
      mkdir -p "$root/oh-my-setting-delegate.$name"
      printf "kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s/wt\ntemporary=1\n" \
        "$$" "$repo" "$root/oh-my-setting-delegate.$name" \
        > "$root/oh-my-setting-delegate.$name/.oh-my-setting-tmp"
    done
    git -C "$repo" worktree add --quiet --detach \
      "$root/oh-my-setting-delegate.mixed-stuck/wt" HEAD || exit 61
    OMS_WG_GITMETA_MANAGED_ADDED_OUT="$snap/gitmeta-managed-added" \
      OMS_WG_GITMETA_MANAGED_COMPLETE_OUT="$snap/gitmeta-managed-complete" \
      oms_worker_surface_capture_one "$repo" gitmeta "$repo" \
      > "$snap/intermediate-gitmeta" || exit 62
    oms_worker_gitmeta_admin_changes_are_safe "$repo" "$snap" "$repo" || exit 63
    git -C "$repo" worktree add --quiet --detach \
      "$root/oh-my-setting-delegate.mixed-pending/wt" HEAD || exit 64
    OMS_WG_GITMETA_MANAGED_ADDED_OUT="$snap/gitmeta-managed-added" \
      oms_worker_surface_capture_one "$repo" gitmeta "$repo" > /dev/null || exit 65
    for name in mixed-stuck mixed-pending; do
      metadata="$(git -C "$root/oh-my-setting-delegate.$name/wt" rev-parse --git-dir)"
      case "$metadata" in /*) ;; *) metadata="$repo/$metadata" ;; esac
      rm -f "$metadata/HEAD"
      [ "$name" = mixed-pending ] || rm -rf "$root/oh-my-setting-delegate.$name/wt"
    done
    changed="$(oms_worker_surface_diff "$repo" "$snap" "" "$repo")"
    case "$changed" in *gitmeta*) ;; *) exit 66 ;; esac
  ' _ "$ROOT" "$transient_mixed" "$managed_root" "$transient_mixed_snap" ||
    fail "a registering sibling must not mask another sibling's stuck removal (rc=$?)"

  # An unrelated metadata write during the partial-removal wait must not be
  # excused by the quiet verdict computed before the wait.
  local transient_race="$project-transient-race"
  local transient_race_snap="$TMP/guard-sibling-transient-race-snapshot"
  make_guard_repo "$transient_race"
  OMS_DELEGATE_WORKTREE_ROOT="$managed_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    repo="$2" root="$3" snap="$4"
    exclude_path="$(git -C "$repo" rev-parse --git-path info/exclude)"
    case "$exclude_path" in /*) ;; *) exclude_path="$repo/$exclude_path" ;; esac
    mkdir -p "${exclude_path%/*}"
    : > "$exclude_path"
    oms_worker_surface_snapshot "$repo" "$snap" "$repo" || exit 50
    mkdir -p "$root/oh-my-setting-delegate.transient-race"
    printf "kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s/wt\ntemporary=1\n" \
      "$$" "$repo" "$root/oh-my-setting-delegate.transient-race" \
      > "$root/oh-my-setting-delegate.transient-race/.oh-my-setting-tmp"
    git -C "$repo" worktree add --quiet --detach \
      "$root/oh-my-setting-delegate.transient-race/wt" HEAD || exit 51
    OMS_WG_GITMETA_MANAGED_ADDED_OUT="$snap/gitmeta-managed-added" \
      OMS_WG_GITMETA_MANAGED_COMPLETE_OUT="$snap/gitmeta-managed-complete" \
      oms_worker_surface_capture_one "$repo" gitmeta "$repo" \
      > "$snap/intermediate-gitmeta" || exit 52
    oms_worker_gitmeta_admin_changes_are_safe "$repo" "$snap" "$repo" || exit 53
    common="$(git -C "$repo" rev-parse --git-common-dir)"
    case "$common" in /*) ;; *) common="$repo/$common" ;; esac
    entry="$(sed -n 1p "$snap/gitmeta-managed-added")"
    metadata="$(git -C "$root/oh-my-setting-delegate.transient-race/wt" rev-parse --git-dir)"
    case "$metadata" in /*) ;; *) metadata="$repo/$metadata" ;; esac
    rm -rf "$root/oh-my-setting-delegate.transient-race/wt"
    rm -f "$metadata/HEAD"
    ( sleep 0.4; printf "late\n" >> "$exclude_path"; sleep 0.4
      rm -rf "$common/worktrees/$entry" "$root/oh-my-setting-delegate.transient-race" ) &
    changed="$(oms_worker_surface_diff "$repo" "$snap" "" "$repo")"
    wait
    case "$changed" in *gitmeta*) ;; *) exit 55 ;; esac
  ' _ "$ROOT" "$transient_race" "$managed_root" "$transient_race_snap" ||
    fail "an unrelated metadata write during the partial-removal wait must stay hard (rc=$?)"

  local transient_bad_exclude="$project-transient-exclude"
  local transient_bad_exclude_snap="$TMP/guard-sibling-transient-exclude-snapshot"
  make_guard_repo "$transient_bad_exclude"
  local exclude_path
  exclude_path="$(git -C "$transient_bad_exclude" rev-parse --git-path info/exclude)"
  case "$exclude_path" in /*) ;; *) exclude_path="$transient_bad_exclude/$exclude_path" ;; esac
  mkdir -p "$(dirname "$exclude_path")"
  : > "$exclude_path"
  OMS_DELEGATE_WORKTREE_ROOT="$managed_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    repo="$2" root="$3" snap="$4"
    exclude_path="$(git -C "$repo" rev-parse --git-path info/exclude)"
    case "$exclude_path" in /*) ;; *) exclude_path="$repo/$exclude_path" ;; esac
    oms_worker_surface_snapshot "$repo" "$snap" "$repo" || exit 30
    mkdir -p "$root/oh-my-setting-delegate.transient-exclude"
    printf "kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s/wt\ntemporary=1\n" \
      "$$" "$repo" "$root/oh-my-setting-delegate.transient-exclude" \
      > "$root/oh-my-setting-delegate.transient-exclude/.oh-my-setting-tmp"
    git -C "$repo" worktree add --quiet --detach \
      "$root/oh-my-setting-delegate.transient-exclude/wt" HEAD || exit 31
    OMS_WG_GITMETA_MANAGED_ADDED_OUT="$snap/gitmeta-managed-added" \
      OMS_WG_GITMETA_MANAGED_COMPLETE_OUT="$snap/gitmeta-managed-complete" \
      oms_worker_surface_capture_one "$repo" gitmeta "$repo" \
      > "$snap/intermediate-gitmeta" || exit 32
    oms_worker_gitmeta_admin_changes_are_safe "$repo" "$snap" "$repo" || exit 33
    [ -s "$snap/gitmeta-managed-added" ] || exit 34
    git -C "$repo" worktree remove --force \
      "$root/oh-my-setting-delegate.transient-exclude/wt" || exit 35
    rm -rf "$root/oh-my-setting-delegate.transient-exclude"
    printf "# unrelated worker edit\n" >> "$exclude_path"
    if oms_worker_gitmeta_only_added_removed_siblings "$repo" "$snap" "$repo"; then
      exit 36
    fi
  ' _ "$ROOT" "$transient_bad_exclude" "$managed_root" "$transient_bad_exclude_snap" ||
    fail "an unrelated info/exclude edit must stay hard during a sibling add/remove (rc=$?)"

  # Strict mode and executable per-worktree config remain hard.
  local transient_bad="$project-transient-config"
  local transient_bad_snap="$TMP/guard-sibling-transient-config-snapshot"
  make_guard_repo "$transient_bad"
  OMS_DELEGATE_WORKTREE_ROOT="$managed_root" bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    repo="$2" root="$3" snap="$4"
    oms_worker_surface_snapshot "$repo" "$snap" "$repo" || exit 20
    mkdir -p "$root/oh-my-setting-delegate.transient-config"
    printf "kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s/wt\ntemporary=1\n" \
      "$$" "$repo" "$root/oh-my-setting-delegate.transient-config" \
      > "$root/oh-my-setting-delegate.transient-config/.oh-my-setting-tmp"
    git -C "$repo" worktree add --quiet --detach \
      "$root/oh-my-setting-delegate.transient-config/wt" HEAD || exit 21
    metadata="$(git -C "$root/oh-my-setting-delegate.transient-config/wt" rev-parse --git-dir)"
    case "$metadata" in /*) ;; *) metadata="$repo/$metadata" ;; esac
    printf "[core]\nfsmonitor=unsafe\n" > \
      "$metadata/config.worktree"
    if oms_worker_gitmeta_admin_changes_are_safe "$repo" "$snap" "$repo"; then
      exit 22
    fi
  ' _ "$ROOT" "$transient_bad" "$managed_root" "$transient_bad_snap" ||
    fail "a transient sibling with config.worktree must remain hard"

  # Same wave: one live sibling disappears while another finishes kept.
  local wave="$project-wave" gone="$managed_root/oh-my-setting-delegate.gone"
  local wave_kept="$managed_root/oh-my-setting-delegate.wave"
  make_guard_repo "$wave"
  make_live_managed_sibling "$wave" "$gone"
  local old_metadata
  old_metadata="$(git -C "$gone/wt" rev-parse --git-dir)"
  local wave_body="git -C $wave worktree remove --force $gone/wt && rm -rf $gone
mkdir -p $wave_kept && git -C $wave worktree add --quiet --detach $wave_kept/wt HEAD && printf 'kind=oh-my-setting-temp\\npid=$dead_pid\\nrepo=$wave\\nworktree=$wave_kept/wt\\ntemporary=1\\n' > $wave_kept/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$wave" "$managed_root" "$wave_body" --allow-no-change)"
  [ "${result%%	*}" = 0 ] || fail "mixed sibling removal/kept creation must pass: $result"
  contains "$result" 'kept-sibling' || fail "mixed wave lost kept-sibling classification: $result"
  [ "$(git -C "$wave_kept/wt" rev-parse --git-dir)" = "$old_metadata" ] ||
    fail "mixed-wave fixture did not reuse the deleted registration slot"

  # The replacement can already be live when comparison begins. It must use
  # the same receipt proof as any other slot reuse because its checkout differs
  # from the baseline sibling's checkout.
  local wave_live="$project-wave-live"
  local gone_live="$managed_root/oh-my-setting-delegate.gone-live"
  local wave_live_kept="$managed_root/oh-my-setting-delegate.wave-live"
  make_guard_repo "$wave_live"
  make_live_managed_sibling "$wave_live" "$gone_live"
  local live_old_metadata
  live_old_metadata="$(git -C "$gone_live/wt" rev-parse --git-dir)"
  local wave_live_body="git -C $wave_live worktree remove --force $gone_live/wt && rm -rf $gone_live
mkdir -p $wave_live_kept && git -C $wave_live worktree add --quiet --detach $wave_live_kept/wt HEAD && printf 'kind=oh-my-setting-temp\\npid=$$\\nrepo=$wave_live\\nworktree=$wave_live_kept/wt\\ntemporary=1\\n' > $wave_live_kept/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$wave_live" "$managed_root" "$wave_live_body" --allow-no-change)"
  [ "${result%%	*}" = 0 ] ||
    fail "a live sibling reusing a removed slot must pass: $result"
  grep -Fxq "pid=$$" "$wave_live_kept/.oh-my-setting-tmp" ||
    fail "live slot-reuse fixture did not retain the test process pid"
  [ "$(git -C "$wave_live_kept/wt" rev-parse --git-dir)" = "$live_old_metadata" ] ||
    fail "live mixed-wave fixture did not reuse the deleted registration slot"

  local invalid bad bad_gone bad_kept bad_metadata bad_body
  for invalid in surviving-checkout executable-config outside-root \
    outside-replacement-root symbolic-head; do
    bad="$project-$invalid"; bad_gone="$gone-$invalid"; bad_kept="$wave_kept-$invalid"
    if [ "$invalid" = outside-root ]; then
      bad_gone="$TMP/guard-sibling-old-outside-root"
    elif [ "$invalid" = outside-replacement-root ]; then
      bad_kept="$TMPDIR/oh-my-setting-delegate.outside-replacement-root"
    fi
    make_guard_repo "$bad"
    make_live_managed_sibling "$bad" "$bad_gone"
    bad_metadata="$(git -C "$bad_gone/wt" rev-parse --git-dir)"
    bad_body="git -C $bad worktree remove --force $bad_gone/wt && rm -rf $bad_gone
mkdir -p $bad_kept && git -C $bad worktree add --quiet --detach $bad_kept/wt HEAD && printf 'kind=oh-my-setting-temp\\npid=$dead_pid\\nrepo=$bad\\nworktree=$bad_kept/wt\\ntemporary=1\\n' > $bad_kept/.oh-my-setting-tmp"
    if [ "$invalid" = surviving-checkout ]; then
      bad_body="$bad_body
mkdir -p $bad_gone/wt"
    elif [ "$invalid" = executable-config ]; then
      bad_body="$bad_body
printf '[core]\\nfsmonitor=unsafe\\n' > $bad_metadata/config.worktree"
    elif [ "$invalid" = symbolic-head ]; then
      bad_body="$bad_body
test \"\$(git -C $bad_kept/wt rev-parse --git-dir)\" = '$bad_metadata' && printf 'ref: refs/heads/%s\\n' \"\$(git -C $bad symbolic-ref --short HEAD)\" > '$bad_metadata/HEAD'"
    fi
    result="$(run_delegate_beside_sibling "$bad" "$managed_root" "$bad_body" --allow-no-change)"
    [ "${result%%	*}" != 0 ] || fail "unproven slot replacement passed ($invalid): $result"
    contains "$result" 'outside its worktree: gitmeta' || fail "slot rejection lost gitmeta: $result"
  done

  make_guard_repo "$project-strict"
  result="$(OMS_WORKER_GUARD_STRICT=1 run_delegate_beside_sibling "$project-strict" "$managed_root" \
    "${body//$project/$project-strict}" --allow-no-change)"
  [ "${result%%	*}" != 0 ] ||
    fail "strict mode must keep a late kept sibling hard: $result"

  make_guard_repo "$project-branch"
  body="mkdir -p $sibling_parent-b && git -C $project-branch worktree add --quiet -b late $sibling_parent-b/wt HEAD >/dev/null 2>&1 && printf 'kind=oh-my-setting-temp\\npid=$dead_pid\\nrepo=$project-branch\\nworktree=$sibling_parent-b/wt\\ntemporary=1\\n' > $sibling_parent-b/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$project-branch" "$managed_root" "$body" --allow-no-change)"
  [ "${result%%	*}" != 0 ] ||
    fail "a late sibling on a branch must stay a hard violation: $result"
}

# A baseline can see a sibling's receipt after its gitmeta scan missed the
# registration. Exercise the review entrypoint with that real capture order,
# including a second sibling that completes while the review is running and
# live admit worktrees outside the delegate root, marked from a linked checkout.
test_review_read_guard_accepts_managed_sibling_admin_lifecycle() {
  local strict
  for strict in 0 1; do
    (
      . "$ROOT/scripts/lib/oms-common.sh"
      . "$ROOT/scripts/lib/peer-common.sh"
      local project="$TMP/read-source-kept-state-$strict"
      local source="$TMP/read-source-kept-$strict"
      local managed_root="$TMP/read-source-kept-root-$strict"
      local snapshot="$TMP/read-source-kept-snapshot-$strict"
      local guard_out guard_rc=0 dead_pid
      make_guard_repo "$project"
      make_guard_repo "$source"
      mkdir -p "$managed_root"
      export OMS_DELEGATE_WORKTREE_ROOT="$managed_root"
      export OMS_WORKER_GUARD_STRICT="$strict"
      REPO="$project" MA_READ_SOURCE_REPO="$source"
      ma_read_guard_begin "$snapshot" || fail "source sibling snapshot failed"
      make_live_managed_sibling "$source" "$managed_root/oh-my-setting-delegate.source"
      dead_pid="$(sh -c 'echo $$')"
      printf 'kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s\ntemporary=1\n' \
        "$dead_pid" "$source" "$managed_root/oh-my-setting-delegate.source/wt" \
        > "$managed_root/oh-my-setting-delegate.source/.oh-my-setting-tmp"
      guard_out="$(ma_read_guard_assert 2>&1)" || guard_rc=$?
      contains "$guard_out" kept-sibling || fail "source sibling lost its classification: $guard_out"
      if [ "$strict" = 1 ]; then
        [ "$guard_rc" = 2 ] || fail "strict review accepted a source sibling: $guard_out"
      else
        [ "$guard_rc" = 0 ] || fail "review rejected a validated source sibling: $guard_out"
        ma_read_guard_assert || fail "repeated review rejected a validated source sibling"
      fi
    )
  done

  local scenario
  for scenario in admit-live admit-dead admit-malformed forged altered symlink-proof extra-line-proof kept removed \
    outside-kept outside-removed gitdir commondir config empty-proof zero-proof \
    malformed-proof missing-proof duplicate fifo-proof directory-proof \
    source-forged empty-digest zero-digest short-digest long-digest malformed-digest; do
    (
      . "$ROOT/scripts/lib/oms-common.sh"
      . "$ROOT/scripts/lib/peer-common.sh"
      local project="$TMP/read-admin-$scenario" source="$TMP/read-admin-sources/$scenario"
      local managed_root="$TMP/read-admin-root-$scenario"
      local snapshot="$TMP/read-admin-snapshot-$scenario"
      local sibling_root="$managed_root" metadata slot guard_out guard_rc=0
      make_guard_repo "$project"
      make_guard_repo "$source"
      mkdir -p "$managed_root"
      case "$scenario" in outside-*) sibling_root="$TMPDIR" ;; esac
      local anchor="$managed_root/oh-my-setting-delegate.anchor"
      local kept="$sibling_root/oh-my-setting-delegate.$scenario"
      local gone="$sibling_root/oh-my-setting-delegate.gone-$scenario"
      local linked="$TMP/read-admin-linked-$scenario" checkout=wt
      case "$scenario" in
        admit-*)
          export TMPDIR="$TMP/read-admin-temp-$scenario"
          mkdir -p "$TMPDIR"
          kept="$TMPDIR/oh-my-setting-admit.$scenario"
          checkout="wt-$scenario"
          git -C "$project" worktree add --quiet --detach "$linked" HEAD
          ;;
      esac
      make_live_managed_sibling "$project" "$anchor"
      export OMS_DELEGATE_WORKTREE_ROOT="$managed_root"
      REPO="$project" MA_READ_SOURCE_REPO="$source"
      eval "$(declare -f oms_worker_surface_capture_one |
        sed '1s/oms_worker_surface_capture_one/read_admin_real_capture/')"
      oms_worker_surface_capture_one() {
        read_admin_real_capture "$@" || return
        if [ "$1" = "$project" ] && [ "$2" = hooks ] && [ ! -d "$kept" ]; then
          case "$scenario" in
            admit-*)
              mkdir -p "$kept"
              git -C "$linked" worktree add --quiet --detach "$kept/$checkout" HEAD
              printf 'kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s\ntemporary=1\n' \
                "$$" "$linked" "$kept/$checkout" > "$kept/.oh-my-setting-tmp"
              ;;
            *) make_live_managed_sibling "$project" "$kept" ;;
          esac
          case "$scenario" in *removed) make_live_managed_sibling "$project" "$gone" ;; esac
        fi
      }
      ma_read_guard_begin "$snapshot" || fail "review sibling snapshot failed ($scenario)"
      local state_sha="${MA_READ_STATE_RECEIPTS_SHA:-}" source_sha="${MA_READ_SOURCE_RECEIPTS_SHA:-}"
      [ "${#state_sha}" = 64 ] && [ "${#source_sha}" = 64 ] ||
        fail "review did not freeze both receipt digests in parent memory"
      metadata="$(git -C "$kept/$checkout" rev-parse --git-dir | tr -d '\r')"
      slot="${metadata##*/}"
      ! grep -Fq "worktrees/$slot/" "$MA_READ_GUARD_DIR/state/gitmeta" ||
        fail "late sibling unexpectedly entered the gitmeta baseline"
      [ -f "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical" ] ||
        fail "late sibling receipt was not captured"
      case "$scenario" in
        admit-dead)
          # The receipt remains valid, but its owner must still be live now.
          printf 'kind=oh-my-setting-temp\npid=2147483647\nrepo=%s\nworktree=%s\ntemporary=1\n' \
            "$linked" "$kept/$checkout" > "$kept/.oh-my-setting-tmp"
          ;;
        admit-malformed) printf 'temporary=0\n' > "$kept/.oh-my-setting-tmp" ;;
        source-forged)
          cp -R "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot" \
            "$MA_READ_GUARD_DIR/source/foreign-worktrees/$slot"
          ;;
        empty-digest) MA_READ_STATE_RECEIPTS_SHA="" ;;
        zero-digest) printf -v MA_READ_STATE_RECEIPTS_SHA '%064d' 0 ;;
        short-digest) MA_READ_STATE_RECEIPTS_SHA=0 ;;
        long-digest) printf -v MA_READ_STATE_RECEIPTS_SHA '%065d' 0 ;;
        malformed-digest) MA_READ_STATE_RECEIPTS_SHA=invalid ;;
        forged)
          printf '../../.\n' > "$metadata/commondir"
          oms_worker_gitmeta_admin_file_identity "$metadata/commondir" \
            > "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/commondir-identity"
          ;;
        altered) printf 'forged log\n' >> "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/log" ;;
        symlink-proof)
          mv "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical" "$snapshot/physical"
          ln -s "$snapshot/physical" "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical"
          ;;
        extra-line-proof) printf 'extra\n' >> "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical" ;;
        fifo-proof|directory-proof)
          rm "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical"
          if [ "$scenario" = fifo-proof ]; then
            mkfifo "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical"
          else
            mkdir "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical"
          fi
          ;;
        *removed)
          git -C "$project" worktree remove --force "$gone/wt"
          rm -rf "$gone"
          ;;
        gitdir) printf '%s/wt/./.git\n' "$kept" > "$metadata/gitdir" ;;
        commondir) printf '../../.\n' > "$metadata/commondir" ;;
        config) printf '[core]\nfsmonitor=unsafe\n' > "$metadata/config.worktree" ;;
        empty-proof) : > "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical" ;;
        zero-proof) printf '0\n' > "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical" ;;
        malformed-proof) printf '../unproven\n' > "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical" ;;
        missing-proof) rm "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/commondir-identity" ;;
        duplicate)
          mkdir -p "$MA_READ_GUARD_DIR/state/foreign-worktrees/duplicate"
          cp "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/physical" \
            "$MA_READ_GUARD_DIR/state/foreign-worktrees/duplicate/physical"
          ;;
      esac
      guard_out="$(ma_read_guard_assert 2>&1)" || guard_rc=$?
      case "$scenario" in
        admit-live|kept|removed)
          [ "$guard_rc" = 0 ] || fail "review rejected managed sibling admin changes ($scenario): $guard_out"
          # Each assertion recaptures metadata; the first proof must not be
          # required for a second read of the same surviving registration.
          ma_read_guard_assert || fail "repeated review assertion rejected managed siblings"
          if [ "$scenario" = kept ]; then
            local field value
            for field in physical path HEAD gitdir commondir-identity; do
              cp "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/$field" "$snapshot/scalar"
              for value in '' 0 invalid; do
                printf '%s\n' "$value" > "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/$field"
                if oms_worker_gitmeta_receipts_fingerprint "$MA_READ_GUARD_DIR/state" >/dev/null; then
                  fail "malformed scalar receipt could be frozen ($field: $value)"
                fi
              done
              cp "$snapshot/scalar" "$MA_READ_GUARD_DIR/state/foreign-worktrees/$slot/$field"
            done
            ma_read_guard_assert || fail "restoring exact receipt bytes changed their digest"
          fi
          ;;
        *)
          [ "$guard_rc" = 2 ] || fail "review accepted unproven admin changes ($scenario): $guard_out"
          contains "$guard_out" 'gitmeta' || fail "admin rejection lost its surface ($scenario)"
          ;;
      esac
      case "$scenario" in
        admit-*)
          git -C "$project" worktree remove --force "$kept/$checkout"
          rm -rf "$kept"
          ;;
      esac
      # Structural validation is independent of the digest mismatch: even a
      # parent trying to freeze these malformed receipts must refuse them.
      case "$scenario" in
        symlink-proof|extra-line-proof|empty-proof|zero-proof|malformed-proof|missing-proof|duplicate|fifo-proof|directory-proof)
          if oms_worker_gitmeta_receipts_fingerprint "$MA_READ_GUARD_DIR/state" >/dev/null; then
            fail "malformed receipt inventory could be frozen ($scenario)"
          fi
          ;;
      esac
    )
  done

  (
    . "$ROOT/scripts/lib/oms-common.sh"
    . "$ROOT/scripts/lib/peer-common.sh"
    local project="$TMP/read-uncaptured" source="$TMP/read-uncaptured-source"
    local managed_root="$TMP/read-uncaptured-root" snapshot="$TMP/read-uncaptured-snapshot"
    local gone="$managed_root/oh-my-setting-delegate.gone" gone_admin="" guard_out guard_rc=0
    make_guard_repo "$project"
    make_guard_repo "$source"
    make_live_managed_sibling "$project" "$managed_root/oh-my-setting-delegate.anchor"
    export OMS_DELEGATE_WORKTREE_ROOT="$managed_root"
    REPO="$project" MA_READ_SOURCE_REPO="$source"
    eval "$(declare -f oms_worker_gitmeta_is_live_managed_worktree |
      sed '1s/oms_worker_gitmeta_is_live_managed_worktree/uncaptured_real_live/')"
    oms_worker_gitmeta_is_live_managed_worktree() {
      if [ "$2" = "$gone_admin/gitdir" ] && [ -d "$gone/wt" ]; then
        git -C "$project" worktree remove --force "$gone/wt" || return 1
        rm -rf "$gone"
        return 1
      fi
      uncaptured_real_live "$@"
    }
    eval "$(declare -f oms_worker_surface_capture_one |
      sed '1s/oms_worker_surface_capture_one/uncaptured_real_capture/')"
    oms_worker_surface_capture_one() {
      if [ "$1" = "$project" ] && [ "$2" = gitmeta ] && [ -z "$gone_admin" ]; then
        make_live_managed_sibling "$project" "$gone"
        gone_admin="$(git -C "$gone/wt" rev-parse --git-dir | tr -d '\r')"
      fi
      uncaptured_real_capture "$@"
    }
    ma_read_guard_begin "$snapshot" || fail "uncaptured sibling baseline failed"
    [ ! -e "$MA_READ_GUARD_DIR/state/foreign-worktrees/${gone_admin##*/}" ] ||
      fail "removed sibling unexpectedly acquired a receipt"
    guard_out="$(ma_read_guard_assert 2>&1)" || guard_rc=$?
    [ "$guard_rc" = 2 ] && contains "$guard_out" gitmeta ||
      fail "review accepted sibling removal without baseline identity proof: $guard_out"
  )

  local project="$TMP/write-receipt-tamper" managed_root="$TMP/write-receipt-root"
  local result
  make_guard_repo "$project"
  make_live_managed_sibling "$project" "$managed_root/oh-my-setting-delegate.anchor"
  result="$(run_delegate_beside_sibling "$project" "$managed_root" '
    case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac
    found=0
    for receipt in ../worker-guard/foreign-worktrees/*/physical; do
      [ -f "$receipt" ] || continue
      printf "extra\n" >> "$receipt"
      found=1
      break
    done
    [ "$found" = 1 ] || exit 1
  ' --allow-no-change)"
  [ "${result%%$'\t'*}" != 0 ] || fail "write worker accepted altered receipts: $result"
  contains "$result" 'gitmeta receipt inventory' || fail "write receipt refusal lost its reason: $result"
}

# The incident: another main's residue cleanup removed a sibling that was
# already dead and kept at the worker's snapshot. Removing that whole entry is
# reported softly; strict mode and a partial removal stay hard.
# oms land and scratch can run from a linked worktree; their marker then names
# that checkout, not the primary one. Same Git common dir is the same repository.
# smoke-weight: 5
test_worker_guard_exempts_a_sibling_marked_from_a_linked_worktree() {
  local project="$TMP/guard-sibling-linked"
  local managed_root="$TMP/guard-sibling-linked-root"
  local linked="$TMP/guard-sibling-linked-checkout"
  local sibling_parent="$managed_root/oh-my-setting-land.linked"
  local result

  make_guard_repo "$project"
  git -C "$project" worktree add --quiet --detach "$linked" HEAD >/dev/null 2>&1 ||
    fail "could not create the linked checkout fixture"
  mkdir -p "$managed_root" "$TMP/agy-other-tmp"
  # The linked checkout predates the run; only the sibling added mid-run is in question.
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "mkdir -p $sibling_parent && printf 'kind=oh-my-setting-temp\\npid=$$\\nrepo=$linked\\nworktree=$sibling_parent/wt\\ntemporary=1\\n' > $sibling_parent/.oh-my-setting-tmp && git -C $linked worktree add --quiet --detach $sibling_parent/wt HEAD >/dev/null 2>&1")"
  [ "${result%%	*}" = 0 ] ||
    fail "a live sibling marked from a linked worktree must not fail the run: $result"
  if contains "$result" 'outside its worktree'; then
    fail "a linked-worktree marker should vouch for its sibling: $result"
  fi
}

# smoke-weight: 22
test_worker_guard_softens_cleanup_of_a_dead_kept_sibling() {
  local project="$TMP/guard-sibling-cleanup"
  local managed_root="$TMP/guard-sibling-cleanup-root"
  local sibling_parent="$managed_root/oh-my-setting-delegate.residue"
  local dead_pid
  local common_dir
  local p
  local result
  # Only the worker turn acts; capability probes reach the same stub.
  local probe='case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac'

  dead_pid="$(sh -c 'echo $$')"
  for p in "$project" "$project-strict" "$project-partial" "$project-reused"; do
    make_guard_repo "$p"
    make_live_managed_sibling "$p" "$sibling_parent${p#"$project"}"
    printf 'kind=oh-my-setting-temp\npid=%s\nrepo=%s\nworktree=%s\ntemporary=1\n' \
      "$dead_pid" "$p" "$sibling_parent${p#"$project"}/wt" \
      > "$sibling_parent${p#"$project"}/.oh-my-setting-tmp"
  done
  result="$(run_delegate_beside_sibling "$project" "$managed_root" \
    "$probe
git -C $project worktree remove --force $sibling_parent/wt && rm -rf $sibling_parent")"
  [ "${result%%	*}" = 0 ] ||
    fail "cleanup of a dead kept sibling must not fail the run: $result"
  contains "$result" 'during this run: sibling-cleanup' ||
    fail "cleanup of a dead kept sibling should be reported softly: $result"

  # Cleanup can free the same registry slot for another stopped delegate.
  local replacement="$managed_root/oh-my-setting-delegate.replacement" previous_metadata reuse_body
  previous_metadata="$(git -C "$sibling_parent-reused/wt" rev-parse --git-dir)"
  reuse_body="$probe
git -C $project-reused worktree remove --force $sibling_parent-reused/wt && rm -rf $sibling_parent-reused
mkdir -p $replacement && git -C $project-reused worktree add --quiet --detach $replacement/wt HEAD && printf 'kind=oh-my-setting-temp\\npid=$dead_pid\\nrepo=$project-reused\\nworktree=$replacement/wt\\ntemporary=1\\n' > $replacement/.oh-my-setting-tmp"
  result="$(run_delegate_beside_sibling "$project-reused" "$managed_root" "$reuse_body")"
  [ "${result%%	*}" = 0 ] || fail "cleanup then reuse of an already-kept slot must pass: $result"
  contains "$result" 'kept-sibling' || fail "kept replacement lost its classification: $result"
  [ "$(git -C "$replacement/wt" rev-parse --git-dir)" = "$previous_metadata" ] ||
    fail "kept replacement fixture did not reuse the registration slot"

  result="$(OMS_WORKER_GUARD_STRICT=1 run_delegate_beside_sibling "$project-strict" "$managed_root" \
    "$probe
git -C $project-strict worktree remove --force $sibling_parent-strict/wt && rm -rf $sibling_parent-strict")"
  [ "${result%%	*}" != 0 ] ||
    fail "strict mode must keep sibling cleanup hard: $result"

  common_dir="$(git -C "$project-partial" rev-parse --git-common-dir)"
  case "$common_dir" in /*) ;; *) common_dir="$project-partial/$common_dir" ;; esac
  result="$(run_delegate_beside_sibling "$project-partial" "$managed_root" \
    "$probe
rm -f $common_dir/worktrees/wt/HEAD")"
  [ "${result%%	*}" != 0 ] ||
    fail "a partial removal of a residue entry must stay hard: $result"
  contains "$result" 'outside its worktree: gitmeta' ||
    fail "a partial residue removal should be named as gitmeta: $result"

  make_guard_repo "$project-plain"
  git -C "$project-plain" worktree add --quiet --detach "$project-plain-wt" HEAD >/dev/null 2>&1 ||
    fail "could not create the plain worktree fixture"
  result="$(run_delegate_beside_sibling "$project-plain" "$managed_root" \
    "$probe
git -C $project-plain worktree remove --force $project-plain-wt")"
  [ "${result%%	*}" = 0 ] ||
    fail "removing a validated plain foreign worktree must pass: $result"
  contains "$result" 'during this run: foreign-worktree' ||
    fail "a removed plain worktree should be named as foreign: $result"
}

test_worker_guard_reports_a_bounded_scan() {
  local project="$TMP/guard-budget"
  local out
  local guard_home="$project-home"

  make_guard_repo "$project"
  printf '#!/usr/bin/env bash\necho done\n' > "$project-bin/codex"
  chmod +x "$project-bin/codex"
  printf 'a\n' > "$project/one.txt"
  printf 'b\n' > "$project/two.txt"

  # A cap that hides how much it skipped reads as full coverage. Here the cap
  # is too small to even reach the end of the untracked files, which is the
  # serious case: coverage is genuinely partial, not merely short of the
  # ignored churn.
  out="$(HOME="$guard_home" NVM_DIR="$guard_home/.nvm" PATH="$project-bin:/usr/bin:/bin" \
    OMS_WORKER_GUARD_MAX_FILES=1 "$ROOT/scripts/peer-delegate.sh" --repo "$project" \
    --to codex --prompt x --no-verify 2>&1)" || fail "a bounded scan should not fail the run: $out"
  contains "$out" 'coverage is partial' ||
    fail "a truncated scan must say so: $out"
}

# smoke-weight: 112
test_worker_guard_rejects_any_worker_authority_state_change() {
  local project="$TMP/guard-state"
  local result

  make_guard_repo "$project"
  mkdir -p "$project/.oms/threads"
  printf '*\n' > "$project/.oms/.gitignore"
  printf '{"schema":1,"fingerprint":"abc","exit":1,"cmd":"pytest"}\n' \
    > "$project/.oms/failures.jsonl"
  printf '{"schema":1,"thread":"t1","seq":1,"role":"answer","text":"first"}\n' \
    > "$project/.oms/threads/t1.jsonl"

  # A delegated worker returns an artifact and patch; it has no authority to
  # write the primary control plane. Even a syntactically valid append can
  # forge a lifecycle/landing record that later readers treat as authority.
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$project" \
    "printf '{\"schema\":1,\"fingerprint\":\"def\",\"exit\":1}\n' >> $project/.oms/failures.jsonl")"
  [ "${result%%	*}" != 0 ] || fail "appending primary authority state should fail the run: $result"
  contains "$result" 'shared-state' ||
    fail "an appended authority row should name the shared-state surface: $result"
  if grep -Fq '"fingerprint":"def"' "$project/.oms/failures.jsonl"; then
    fail "the appended authority row should be rolled back"
  fi

  # Rewritten JSON state is equally authoritative. Presence-only checks let a
  # worker widen its path scope or replace the lease that patch-land trusts.
  local plan_rewrite="$TMP/guard-state-plan-rewrite"
  make_guard_repo "$plan_rewrite"
  mkdir -p "$plan_rewrite/.oms/plan"
  printf '{"tasks":[{"id":"t1","allowed_paths":["src/"]}]}\n' \
    > "$plan_rewrite/.oms/plan/tasks.json"
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$plan_rewrite" \
    "printf '{\"tasks\":[{\"id\":\"t1\",\"allowed_paths\":[\"/\"]}]}\\n' > $plan_rewrite/.oms/plan/tasks.json")"
  [ "${result%%	*}" != 0 ] || fail "rewriting plan authority should fail the run: $result"
  contains "$result" 'plan/tasks.json' ||
    fail "the rewritten authority file should be named: $result"
  if contains "$result" 'shared-state: failures.jsonl'; then
    fail "parent failure bookkeeping must not be blamed on the plan-mutating worker: $result"
  fi
  grep -Fq '"allowed_paths":["src/"]' "$plan_rewrite/.oms/plan/tasks.json" ||
    fail "rewritten plan authority should be restored"

  # Rewriting rows already there is how a worker would erase the failure that
  # blocks its retry, or forge a turn another agent reads as evidence.
  local rewrite="$TMP/guard-state-rewrite"
  make_guard_repo "$rewrite"
  mkdir -p "$rewrite/.oms"
  printf '*\n' > "$rewrite/.oms/.gitignore"
  printf '{"schema":1,"fingerprint":"abc","exit":1,"cmd":"pytest"}\n' \
    > "$rewrite/.oms/failures.jsonl"
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$rewrite" \
    "printf '{\"schema\":1,\"fingerprint\":\"zzz\",\"exit\":0}\n' > $rewrite/.oms/failures.jsonl")"
  [ "${result%%	*}" != 0 ] || fail "rewriting shared state should fail the run: $result"
  contains "$result" 'shared-state' ||
    fail "the shared-state surface should be named: $result"
  contains "$result" 'failures.jsonl changed' ||
    fail "the violation should name the file and what happened: $result"
  grep -Fq '"fingerprint":"abc"' "$rewrite/.oms/failures.jsonl" ||
    fail "rewritten shared state should be restored"

  # Concurrent mode still protects immutable panel launch/outcome records;
  # presence-only tracking previously accepted both rewrites and appends.
  local panel_records="$TMP/guard-state-panel-records"
  local panel_record mutation mutation_body
  make_guard_repo "$panel_records"
  mkdir -p "$panel_records/.oms/artifacts"
  printf '*\n' > "$panel_records/.oms/.gitignore"
  printf '{"pid":1}\n' > "$panel_records/.oms/artifacts/sibling.json"
  # One run per mutation kind changes every record at once; the guard lists
  # each changed record, so each must still be named.
  local panel_records_list="panel-call-eeeeeeeeeeeeeeee.json panel-call-eeeeeeeeeeeeeeee-exit.json panel-call-eeeeeeeeeeeeeeee-pending.json"
  for mutation in rewrite append symlink fifo; do
    mutation_body=""
    for panel_record in $panel_records_list; do
      rm -f "$panel_records/.oms/artifacts/$panel_record"
      printf '{"pid":1}\n' > "$panel_records/.oms/artifacts/$panel_record"
      case "$mutation" in
        rewrite) mutation_body="$mutation_body printf '{\"pid\":2}\\n' > '$panel_records/.oms/artifacts/$panel_record';" ;;
        append) mutation_body="$mutation_body printf 'extra\\n' >> '$panel_records/.oms/artifacts/$panel_record';" ;;
        symlink) mutation_body="$mutation_body rm -f '$panel_records/.oms/artifacts/$panel_record'; ln -s sibling.json '$panel_records/.oms/artifacts/$panel_record';" ;;
        fifo) mutation_body="$mutation_body rm -f '$panel_records/.oms/artifacts/$panel_record'; mkfifo '$panel_records/.oms/artifacts/$panel_record';" ;;
      esac
    done
    result="$(run_guarded_worker "$panel_records" "$mutation_body")"
    [ "${result%%	*}" != 0 ] || fail "$mutation of panel controller state should fail: $result"
    for panel_record in $panel_records_list; do
      contains "$result" "artifacts/$panel_record controller record" ||
        fail "panel controller $mutation should name its immutable record $panel_record: $result"
    done
  done
  for panel_record in $panel_records_list; do
    rm -f "$panel_records/.oms/artifacts/$panel_record"
  done
  # Concurrent mode is the guard-stop path: the ledger row and the relayed
  # Output are what a later triage reads, so they name the changed record
  # instead of the generic no-detail line.
  local guard_artifact
  guard_artifact="$(ls -t "$panel_records"/.oms/artifacts/delegate/*.md 2>/dev/null | sed -n '1p')"
  python3 - "$panel_records/.oms/failures.jsonl" "$guard_artifact" <<'PY' || fail "guard stop lost the shared-state path"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
rows = [row for row in rows if row.get("cmd", "").endswith("worker-authority")]
assert rows, rows
summary = rows[-1]["summary"]
assert "panel-call-eeeeeeeeeeeeeeee-pending.json" in summary and "no path/ref detail" not in summary, summary
output = open(sys.argv[2], encoding="utf-8").read().split("## Output", 1)[1]
assert "shared-state artifacts/panel-call-eeeeeeeeeeeeeeee-pending.json" in output, output
PY

  local removed="$TMP/guard-state-deleted"
  make_guard_repo "$removed"
  mkdir -p "$removed/.oms"
  printf '*\n' > "$removed/.oms/.gitignore"
  printf '{"schema":1,"fingerprint":"abc","exit":1}\n' > "$removed/.oms/failures.jsonl"
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$removed" \
    "rm -f $removed/.oms/failures.jsonl")"
  [ "${result%%	*}" != 0 ] || fail "deleting shared state should fail the run: $result"
  contains "$result" 'was deleted' ||
    fail "a deleted state file should be named: $result"
  grep -Fq '"fingerprint":"abc"' "$removed/.oms/failures.jsonl" ||
    fail "deleted shared state should be restored"

  local receipt_case receipt_repo receipt_script
  receipt_script='
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    mkdir -p "$2/.oms/plan"
    printf "{\"run\":1}\n" > "$2/.oms/plan/autopilot-run.json"
    if [ "$4" = unlistable ]; then printf "{\"schema\":1}\n" > "$2/.oms/failures.jsonl"; fi
    oms_worker_surface_capture_one "$2" omsstate "$2" > "$3" || exit 30
    case "$4" in
      archive|exclusive|wrong|symlink)
        digest="$(oms_sha256_file "$2/.oms/plan/autopilot-run.json" | tr -d "\r")"
        if [ "$4" = wrong ]; then digest="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"; fi
        if [ "$4" = symlink ]; then ln -s autopilot-run.json "$2/.oms/plan/autopilot-run.$digest.json"; else cp "$2/.oms/plan/autopilot-run.json" "$2/.oms/plan/autopilot-run.$digest.json"; fi
        rm -f "$2/.oms/plan/autopilot-run.json"
        ;;
      rewrite)
        printf "{\"run\":2}\n" > "$2/.oms/plan/autopilot-run.json"
        digest="$(oms_sha256_file "$2/.oms/plan/autopilot-run.json" | tr -d "\r")"
        cp "$2/.oms/plan/autopilot-run.json" "$2/.oms/plan/autopilot-run.$digest.json"
        rm -f "$2/.oms/plan/autopilot-run.json"
        ;;
      limit|oversize)
        dd if=/dev/zero of="$2/.oms/plan/autopilot-run.json" bs=65536 count=1 2>/dev/null
        if [ "$4" = oversize ]; then printf x >> "$2/.oms/plan/autopilot-run.json"; fi
        digest="$(oms_sha256_file "$2/.oms/plan/autopilot-run.json" | tr -d "\r")"
        cp "$2/.oms/plan/autopilot-run.json" "$2/.oms/plan/autopilot-run.$digest.json"
        rm -f "$2/.oms/plan/autopilot-run.json"
        ;;
      plain) rm -f "$2/.oms/plan/autopilot-run.json" ;;
      unlistable)
        rm -f "$2/.oms/plan/autopilot-run.json" "$2/.oms/failures.jsonl"
        chmod 300 "$2/.oms/plan"
        if ls "$2/.oms/plan" >/dev/null 2>&1; then chmod 755 "$2/.oms/plan"; exit 0; fi
        ;;
    esac
    if [ "$4" = exclusive ]; then
      OMS_WORKER_AUTHORITY_EXCLUSIVE=1 oms_worker_state_violations "$2" "$3" > "$3-detail"
    else
      oms_worker_state_violations "$2" "$3" > "$3-detail"
    fi
    if [ "$4" = unlistable ]; then
      chmod 755 "$2/.oms/plan"
      grep -Fq "failures.jsonl was deleted" "$3-detail"
    elif [ "$4" = plain ] || [ "$4" = wrong ] || [ "$4" = symlink ] || [ "$4" = exclusive ] || [ "$4" = oversize ]; then
      grep -Fq "plan/autopilot-run.json was deleted" "$3-detail"
    else
      [ ! -s "$3-detail" ]
    fi
  '
  for receipt_case in archive rewrite limit oversize plain wrong symlink exclusive unlistable; do
    receipt_repo="$TMP/guard-receipt-$receipt_case"
    make_guard_repo "$receipt_repo"
    bash -c "$receipt_script" _ "$ROOT" "$receipt_repo" \
      "$TMP/guard-receipt-$receipt_case.snapshot" "$receipt_case" ||
      fail "autopilot receipt retirement case $receipt_case was misclassified"
  done

  local graph_cache="$TMP/guard-state-graph-cache"
  local graph_cache_file="$TMP/guard-state-graph-cache/.oms/project-graph/cache/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.json"
  local graph_cache_snapshot="$TMP/guard-state-graph-cache-snapshot"
  make_guard_repo "$graph_cache"
  mkdir -p "$(dirname "$graph_cache_file")"
  printf '{"derived":true}\n' > "$graph_cache_file"
  bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    oms_worker_surface_capture_one "$2" omsstate "$2" > "$3" || exit 10
    rm -f "$4"
    oms_worker_state_violations "$2" "$3" > "$3-detail" || exit 11
    [ ! -s "$3-detail" ]
  ' _ "$ROOT" "$graph_cache" "$graph_cache_snapshot" "$graph_cache_file" ||
    fail "deleting an exact regular project-graph cache file should pass"
  printf '{"derived":true}\n' > "$graph_cache_file"
  OMS_WORKER_GUARD_STRICT=1 bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    oms_worker_surface_capture_one "$2" omsstate "$2" > "$3" || exit 10
    rm -f "$4"
    oms_worker_state_violations "$2" "$3" > "$3-detail" || exit 11
    [ ! -s "$3-detail" ]
  ' _ "$ROOT" "$graph_cache" "$graph_cache_snapshot" "$graph_cache_file" ||
    fail "strict mode should also tolerate a project-graph cache deletion: the main checkout's graph rebuild prunes it"

  local graph_cache_rewrite="$TMP/guard-state-graph-cache-rewrite"
  local graph_cache_rewrite_file="$TMP/guard-state-graph-cache-rewrite/.oms/project-graph/cache/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb.json"
  local graph_cache_rewrite_snapshot="$TMP/guard-state-graph-cache-rewrite-snapshot"
  make_guard_repo "$graph_cache_rewrite"
  mkdir -p "$(dirname "$graph_cache_rewrite_file")"
  printf '{"derived":"before"}\n' > "$graph_cache_rewrite_file"
  bash -c '
    . "$1/scripts/lib/harness-residue.sh"
    . "$1/scripts/lib/oms-common.sh"
    oms_worker_surface_capture_one "$2" omsstate "$2" > "$3" || exit 20
    printf "{\"derived\":\"after\"}\\n" > "$4"
    oms_worker_state_violations "$2" "$3" > "$3-detail" || exit 21
    grep -Fq "project-graph/cache/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb.json derived cache changed" "$3-detail"
  ' _ "$ROOT" "$graph_cache_rewrite" "$graph_cache_rewrite_snapshot" \
    "$graph_cache_rewrite_file" ||
    fail "rewriting a surviving project-graph cache file should stay hard"

  # The parent's own prompt hook consumes its resume hint mid-run.
  local hint="$TMP/guard-state-hook-hint"
  make_guard_repo "$hint"
  mkdir -p "$hint/.oms/hooks/sessions"
  printf '*\n' > "$hint/.oms/.gitignore"
  printf '{"source":"compact"}\n' > "$hint/.oms/hooks/sessions/abc.resume.json"
  result="$(run_guarded_worker "$hint" "rm -f $hint/.oms/hooks/sessions/abc.resume.json")"
  [ "${result%%	*}" = 0 ] || fail "a consumed hook session hint is not worker authority: $result"
  printf '{"hint":1}\n' > "$hint/.oms/hooks/sessions/abc.hint.json"
  result="$(run_guarded_worker "$hint" "rm -f $hint/.oms/hooks/sessions/abc.hint.json")"
  [ "${result%%	*}" = 0 ] || fail "a consumed panel dedup hint is not worker authority: $result"
  printf '{"s":1}\n' > "$hint/.oms/hooks/sessions/abc.json"
  result="$(run_guarded_worker "$hint" "rm -f $hint/.oms/hooks/sessions/abc.json")"
  [ "${result%%	*}" != 0 ] || fail "other hooks/sessions files stay worker authority: $result"

  # Known same-directory writer temps are scratch while present in either
  # provider snapshot. Their cleanup after capture must not look like deleting
  # a shared target in either the ordinary or exclusive guard.
  local transient_mode transient transients_body rel
  local -a transient_paths=(
    "hooks/sessions/0123456789abcdef0123456789abcdef.json.abc123_4.tmp"
    "hooks/panel-activity/call-0123456789abcdef01234567.json.abc123_4.tmp"
    "hooks/relay/claude.json.abc123_4.tmp"
    "hooks/.oms-replace.abc12345"
    "memory/.oms-replace.abc123"
    "work-journal/index.sqlite3-journal"
    "work-journal/index.sqlite3-wal"
    "work-journal/index.sqlite3-shm"
    "memory/memory.sqlite3-journal"
    "memory/memory.sqlite3-wal"
    "memory/memory.sqlite3-shm"
    "plan/tmpabc123_4"
    "plan/.tasks.aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.archive.json.tmp"
    "plan/.tasks.aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.retire-intent.json.tmp"
    "..gitignore.tmp.123.0123456789abcdef0123456789abcdef"
    "artifacts/.index.jsonl.tmp.123.0123456789abcdef0123456789abcdef"
    "artifacts/.index.jsonl.tmp.123"
    "artifacts/quarantine/.artifact-index-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.raw.tmp.123.0123456789abcdef0123456789abcdef"
    "hooks/panel-cache/.dashboard.json.tmp.123.0123456789abcdef0123456789abcdef"
    "hooks/panel-cache/.plan-list.json.tmp.123.0123456789abcdef0123456789abcdef"
    "hooks/panel-cache/.dashboard.0123456789ab.json.tmp.123.0123456789abcdef0123456789abcdef"
    "hooks/panel-cache/.result-records.0123456789ab.json.tmp.123"
    "artifacts/panel-results/.result-task-0123456789abcdef01234567.json.tmp.123.0123456789abcdef0123456789abcdef"
    "artifacts/panel-results/.delivery-task-0123456789abcdef01234567-0123456789abcdef-pending.json.tmp.123.0123456789abcdef0123456789abcdef"
  )
  for transient_mode in 0 1; do
    transient="$TMP/guard-state-transient-$transient_mode"
    transients_body="rm -f"
    make_guard_repo "$transient"
    for rel in "${transient_paths[@]}"; do
      mkdir -p "$(dirname "$transient/.oms/$rel")"
      printf 'staging bytes\n' > "$transient/.oms/$rel"
      transients_body="$transients_body $transient/.oms/$rel"
    done
    result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE="$transient_mode" \
      run_guarded_worker "$transient" "$transients_body")"
    [ "${result%%	*}" = 0 ] ||
      fail "exclusive=$transient_mode cleanup of captured writer temps should pass: $result"
    if printf '%s' "$result" | grep -F 'shared-state' > /dev/null; then
      fail "captured writer-temp cleanup was reported as shared-state in mode $transient_mode: $result"
    fi
  done

  # A versioned panel-cache entry first appears after an install: its staging
  # file is created, renamed into place and the old entry stays; none of it is a
  # violation. A captured non-cache file there is still authority state.
  for transient_mode in 0 1; do
    transient="$TMP/guard-state-panel-cache-$transient_mode"
    make_guard_repo "$transient"
    mkdir -p "$transient/.oms/hooks/panel-cache"
    printf '{}\n' > "$transient/.oms/hooks/panel-cache/dashboard.json"
    result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE="$transient_mode" run_guarded_worker "$transient" \
      "d='$transient/.oms/hooks/panel-cache'; printf 'x\\n' > \"\$d/.dashboard.0123456789ab.json.tmp.1.0123456789abcdef0123456789abcdef\"; mv \"\$d/.dashboard.0123456789ab.json.tmp.1.0123456789abcdef0123456789abcdef\" \"\$d/dashboard.0123456789ab.json\"")"
    [ "${result%%	*}" = 0 ] ||
      fail "exclusive=$transient_mode a new versioned panel-cache entry should pass: $result"
    [ -f "$transient/.oms/hooks/panel-cache/dashboard.0123456789ab.json" ] ||
      fail "the versioned panel-cache entry should be kept"
    transient="$TMP/guard-state-panel-cache-forged-$transient_mode"
    make_guard_repo "$transient"
    mkdir -p "$transient/.oms/hooks/panel-cache"
    printf '{}\n' > "$transient/.oms/hooks/panel-cache/.forged.0123456789ab.json.tmp.1.0123456789abcdef0123456789abcdef"
    result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE="$transient_mode" run_guarded_worker "$transient" \
      "rm -f '$transient/.oms/hooks/panel-cache/.forged.0123456789ab.json.tmp.1.0123456789abcdef0123456789abcdef'")"
    [ "${result%%	*}" != 0 ] ||
      fail "exclusive=$transient_mode deleting a forged non-cache file under panel-cache should fail: $result"
  done

  # Transcript retention is owner bookkeeping: panel_activity.py prunes old
  # call captures and removes its .transcript-* staging files in either mode.
  for transient_mode in 0 1; do
    transient="$TMP/guard-state-transcript-$transient_mode"
    make_guard_repo "$transient"
    mkdir -p "$transient/.oms/panel-state/dispatch-logs"
    printf 'display capture\n' > "$transient/.oms/panel-state/dispatch-logs/call-0123456789abcdef.transcript"
    result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE="$transient_mode" run_guarded_worker "$transient" \
      "rm -f '$transient/.oms/panel-state/dispatch-logs/call-0123456789abcdef.transcript'; printf 'staging\\n' > '$transient/.oms/panel-state/dispatch-logs/.transcript-abc123_4'; rm -f '$transient/.oms/panel-state/dispatch-logs/.transcript-abc123_4'")"
    [ "${result%%	*}" = 0 ] ||
      fail "exclusive=$transient_mode transcript retention bookkeeping should pass: $result"
  done

  # The same producer-shaped regular-file staging names may be created after
  # capture; pre-existing parent directories isolate file classification.
  for transient_mode in 0 1; do
    transient="$TMP/guard-state-transient-created-$transient_mode"
    transients_body=""
    make_guard_repo "$transient"
    for rel in "${transient_paths[@]}"; do
      mkdir -p "$(dirname "$transient/.oms/$rel")"
      transients_body="$transients_body mkdir -p \$(dirname '$transient/.oms/$rel'); printf 'staging bytes\\n' > '$transient/.oms/$rel';"
    done
    result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE="$transient_mode" \
      run_guarded_worker "$transient" "$transients_body")"
    [ "${result%%	*}" = 0 ] ||
      fail "exclusive=$transient_mode creation of producer temps should pass: $result"
  done

  # The display-once rollover cache permits only valid-date empty regular files.
  for transient_mode in 0 1; do
    transient="$TMP/guard-state-hint-rollover-$transient_mode"
    make_guard_repo "$transient"
    mkdir -p "$transient/.oms/hooks"
    : > "$transient/.oms/hooks/state-hint.2026-10-09"
    result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE="$transient_mode" run_guarded_worker "$transient" \
      "rm -f '$transient/.oms/hooks/state-hint.2026-10-09'; : > '$transient/.oms/hooks/state-hint.2026-10-10'")"
    [ "${result%%	*}" = 0 ] ||
      fail "exclusive=$transient_mode day rollover of empty state hints should pass: $result"
  done

  # Similar names and non-regular entries remain protected. Isolate controls so
  # every expected violation is asserted independently.
  local control expected control_body
  for transient_mode in 0 1; do
    for control in stable-session malformed wrong-dir task plan symlink jsonl hint-date hint-content hint-link sqlite-wrong-dir sqlite-link sqlite-database transcript-log transcript-link transcript-name; do
      transient="$TMP/guard-state-transient-control-$transient_mode-$control"
      make_guard_repo "$transient"
      case "$control" in
        stable-session)
          rel="hooks/sessions/0123456789abcdef0123456789abcdef.json"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/hooks/sessions"
          printf '{"schema":1}\n' > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        malformed)
          rel="hooks/sessions/0123456789abcdef0123456789abcdef.json.abc1234.tmp"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/hooks/sessions"
          printf 'lookalike\n' > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        wrong-dir)
          rel="hooks/other/0123456789abcdef01234567.json.abc123_4.tmp"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/hooks/other"
          printf 'wrong directory\n' > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        task)
          rel="task/current.md"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/task"
          printf 'task scope\n' > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        plan)
          rel="plan/tasks.json"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/plan"
          printf '{"tasks":{"t1":{"lease_id":"lease_0123"}}}\n' > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        symlink)
          rel="hooks/sessions/linked.json.abc123_4.tmp"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/hooks/sessions"
          ln -s target "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        hint-date)
          rel="hooks/state-hint.2026-02-30"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/hooks"
          : > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        hint-content)
          rel="hooks/state-hint.2026-10-09"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/hooks"
          printf 'retained content\n' > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        hint-link)
          rel="hooks/state-hint.2026-10-09"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/hooks"
          ln -s target "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        sqlite-wrong-dir)
          rel="plan/index.sqlite3-journal"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/plan"
          : > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        sqlite-link)
          rel="work-journal/index.sqlite3-journal"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/work-journal"
          ln -s target "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        sqlite-database)
          rel="work-journal/index.sqlite3"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/work-journal"
          : > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        transcript-log)
          rel="panel-state/dispatch-logs/call-0123456789abcdef.log"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/panel-state/dispatch-logs"
          : > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        transcript-link)
          rel="panel-state/dispatch-logs/call-0123456789abcdef.transcript"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/panel-state/dispatch-logs"
          ln -s target "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        transcript-name)
          rel="panel-state/dispatch-logs/other.transcript"
          expected="$rel was deleted"
          mkdir -p "$transient/.oms/panel-state/dispatch-logs"
          : > "$transient/.oms/$rel"
          control_body="rm -f '$transient/.oms/$rel'"
          ;;
        jsonl)
          rel="failures.jsonl"
          mkdir -p "$transient/.oms"
          printf '{"schema":1,"fingerprint":"stable"}\n' > "$transient/.oms/$rel"
          control_body="printf '{\"schema\":1,\"fingerprint\":\"rewritten\"}\\n' > '$transient/.oms/$rel'"
          if [ "$transient_mode" = 1 ]; then
            expected="$rel changed"
          else
            expected="$rel had existing rows rewritten"
          fi
          ;;
      esac
      result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE="$transient_mode" \
        run_guarded_worker "$transient" "$control_body")"
      [ "${result%%	*}" != 0 ] ||
        fail "exclusive=$transient_mode control $control should fail: $result"
      printf '%s' "$result" | grep -F "$expected" > /dev/null ||
        fail "exclusive=$transient_mode did not report protected control $control ($expected): $result"
    done
    if [ "$transient_mode" = 1 ]; then
      transient="$TMP/guard-state-hint-directory-control"
      make_guard_repo "$transient"
      mkdir -p "$transient/.oms/hooks/state-hint.2026-10-09"
      python3 -c "import runpy; m=runpy.run_path('$ROOT/scripts/lib/worker-state-transients.py'); assert not m['is_internal_atomic_temp']('$transient/.oms', 'hooks/state-hint.2026-10-09')" ||
        fail "a state-hint directory must not be classified as an internal transient"
      transient="$TMP/guard-state-transient-control-$transient_mode-temp-dir"
      make_guard_repo "$transient"
      mkdir -p "$transient/.oms/memory/.oms-replace.abc123"
      result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$transient" \
        "rmdir '$transient/.oms/memory/.oms-replace.abc123'")"
      [ "${result%%	*}" != 0 ] ||
        fail "a directory matching a producer temp name must remain protected"
      printf '%s' "$result" | grep -F 'memory/.oms-replace.abc123 was deleted' > /dev/null ||
        fail "a directory matching a producer temp name was exempted: $result"
    fi
  done
}

test_worker_authority_guard_restores_primary_state() {
  local project="$TMP/guard-state-restore"
  local state="$project/.oms/authority"
  local result

  make_guard_repo "$project"
  mkdir -p "$state" "$project/.oms/hooks" "$project/.oms/work-journal"
  printf '*\n' > "$project/.oms/.gitignore"
  printf 'original content\n' > "$state/content.txt"
  printf 'restore this file\n' > "$state/deleted.txt"
  printf 'mode stays stable\n' > "$state/mode.txt"
  printf 'target a\n' > "$state/target-a"
  printf 'target b\n' > "$state/target-b"
  chmod 0750 "$state"
  chmod 0750 "$project/.oms"
  chmod 0600 "$state/mode.txt"
  ln -s target-a "$state/current"

  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$project" "
printf 'worker rewrite\\n' > $state/content.txt
printf 'worker creation\\n' > $state/created.txt
rm -f $state/deleted.txt
chmod 0777 $state/mode.txt
chmod 0700 $state
chmod 0777 $project/.oms
rm -f $state/current
ln -s target-b $state/current
printf 'ambient hook\\n' > $project/.oms/hooks/worker-event
printf 'ambient journal\\n' > $project/.oms/work-journal/worker-event
")"
  [ "${result%%	*}" != 0 ] ||
    fail "authority mutation should block the delegated worker: $result"
  contains "$result" 'owner authority shared-state' ||
    fail "authority mutation should report the provider-window boundary: $result"
  for detail in \
    'authority changed' \
    'authority/content.txt changed' \
    'authority/created.txt was created' \
    'authority/current changed' \
    'authority/deleted.txt was deleted' \
    'authority/mode.txt changed' \
    '.oms root changed'; do
    contains "$result" "$detail" ||
      fail "authority report lost the actual worker mutation ($detail): $result"
  done
  if contains "$result" 'shared-state: failures.jsonl'; then
    fail "parent failure bookkeeping must not enter the provider mutation report: $result"
  fi
  contains "$result" 'restored from pre-provider snapshot' ||
    fail "authority report should confirm successful rollback: $result"

  [ "$(cat "$state/content.txt")" = "original content" ] ||
    fail "rewritten authority content was not restored"
  if [ -e "$state/created.txt" ] || [ -L "$state/created.txt" ]; then
    fail "worker-created authority state was not removed"
  fi
  [ "$(cat "$state/deleted.txt")" = "restore this file" ] ||
    fail "worker-deleted authority state was not restored"
  [ "$(readlink "$state/current")" = target-a ] ||
    fail "replaced authority symlink was not restored"
  python3 - "$state" <<'PY' || fail "authority modes were not restored"
import os
import stat
import sys

root = sys.argv[1]
assert stat.S_IMODE(os.lstat(root).st_mode) == 0o750
assert stat.S_IMODE(os.lstat(os.path.join(root, "mode.txt")).st_mode) == 0o600
assert stat.S_IMODE(os.lstat(os.path.dirname(root)).st_mode) == 0o750
PY

  # These two trees are ambient telemetry, not landing/lease/scope authority.
  [ "$(cat "$project/.oms/hooks/worker-event")" = "ambient hook" ] ||
    fail "hooks exclusion should remain outside authority rollback"
  [ "$(cat "$project/.oms/work-journal/worker-event")" = "ambient journal" ] ||
    fail "work-journal exclusion should remain outside authority rollback"

  # Replacing `.oms` itself must not make the manifest walk the symlink target.
  # Because the telemetry roots disappear with the container, the disaster
  # path restores their pre-provider bytes along with authority state.
  local replaced="$TMP/guard-state-root-replaced"
  local outside="$TMP/guard-state-root-outside"
  make_guard_repo "$replaced"
  mkdir -p "$replaced/.oms/authority" "$replaced/.oms/hooks" \
    "$replaced/.oms/work-journal" "$outside"
  printf '*\n' > "$replaced/.oms/.gitignore"
  printf 'root authority\n' > "$replaced/.oms/authority/value"
  printf 'original hook\n' > "$replaced/.oms/hooks/events.jsonl"
  printf 'original journal\n' > "$replaced/.oms/work-journal/index.json"
  printf 'external target\n' > "$outside/foreign.txt"
  chmod 0750 "$replaced/.oms"

  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$replaced" "
rm -rf $replaced/.oms
ln -s $outside $replaced/.oms
printf 'outside remains outside\\n' > $outside/worker-marker
")"
  [ "${result%%	*}" != 0 ] ||
    fail "replacing the authority root should block the delegated worker: $result"
  contains "$result" '.oms root changed' ||
    fail "root replacement should be named without traversing it: $result"
  if contains "$result" 'foreign.txt'; then
    fail "authority scan followed the worker-planted root symlink: $result"
  fi
  if [ -L "$replaced/.oms" ] || [ ! -d "$replaced/.oms" ]; then
    fail "the authority root directory was not restored"
  fi
  [ "$(cat "$replaced/.oms/authority/value")" = "root authority" ] ||
    fail "authority bytes lost when the root was replaced"
  grep -Fq 'original hook' "$replaced/.oms/hooks/events.jsonl" ||
    fail "hook telemetry lost when the root was replaced"
  grep -Fq 'original journal' "$replaced/.oms/work-journal/index.json" ||
    fail "work-journal telemetry lost when the root was replaced"
  [ "$(cat "$outside/worker-marker")" = "outside remains outside" ] ||
    fail "rollback should not mutate the planted symlink target"
}

# smoke-weight: 9
test_parallel_delegates_do_not_erase_each_others_authority_state() {
  local project="$TMP/guard-state-parallel"
  local barrier="$TMP/guard-state-parallel-barrier"
  local bin_dir="$project-bin"
  local home_dir="$project-home"
  local pid_a pid_b rc_a=0 rc_b=0 ticks=0
  local artifact_a artifact_b patch_a patch_b index
  local land_rc=0

  make_guard_repo "$project"
  mkdir -p "$barrier"
  oms_smoke_make_fake_provider_stub "$bin_dir/codex" <<'EOF'
#!/usr/bin/env bash
set -eu
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf 'codex 1.0\n'; exit 0 ;; esac
prompt="$(cat)"
case "$prompt" in
  *parallel-a*) name=a ;;
  *parallel-b*) name=b ;;
  *) echo "unexpected parallel test prompt"; exit 90 ;;
esac
printf 'worker %s edit\n' "$name" >> file.txt
: > "$OMS_TEST_BARRIER/$name.ready"
while [ ! -f "$OMS_TEST_BARRIER/$name.release" ]; do sleep 0.05; done
echo "parallel worker $name done"
EOF

  # Start B first so its snapshots are complete before A exists. FIFO release
  # below then proves B tolerates A's live managed worktree appearing during its
  # guard window, rather than merely getting a before/after state that matches.
  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_TEST_BARRIER="$barrier" OMS_PEER_TIMEOUT=15 OMS_OPERATION_ID=parallel-b \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex \
      --prompt parallel-b --no-verify > "$barrier/b.out" 2> "$barrier/b.err" &
  pid_b=$!
  while [ ! -f "$barrier/b.ready" ] && [ "$ticks" -lt 300 ] &&
    kill -0 "$pid_b" 2>/dev/null; do
    ticks=$((ticks + 1))
    sleep 0.05
  done
  if [ ! -f "$barrier/b.ready" ]; then
    : > "$barrier/b.release"
    wait "$pid_b" 2>/dev/null || true
    fail "first parallel delegate did not reach the provider barrier: $(cat "$barrier/b.err")"
  fi

  HOME="$home_dir" NVM_DIR="$home_dir/.nvm" PATH="$bin_dir:/usr/bin:/bin" \
    OMS_TEST_BARRIER="$barrier" OMS_PEER_TIMEOUT=15 OMS_OPERATION_ID=parallel-a \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to codex \
      --prompt parallel-a --no-verify > "$barrier/a.out" 2> "$barrier/a.err" &
  pid_a=$!
  ticks=0
  while [ ! -f "$barrier/a.ready" ] && [ "$ticks" -lt 300 ] &&
    kill -0 "$pid_a" 2>/dev/null; do
    ticks=$((ticks + 1))
    sleep 0.05
  done
  if [ ! -f "$barrier/a.ready" ]; then
    : > "$barrier/a.release"
    : > "$barrier/b.release"
    wait "$pid_a" 2>/dev/null || true
    wait "$pid_b" 2>/dev/null || true
    fail "second parallel delegate did not overlap at the provider barrier: $(cat "$barrier/a.err" "$barrier/b.err")"
  fi

  # A land gate must leave the canonical registry intact even while two
  # workers hold snapshots. Exercise the real gate path without publishing.
  cp -R "$project/.git/worktrees" "$barrier/registry-before"
  (
    . "$ROOT/scripts/lib/harness-residue.sh"
    export REPO SHA LOG GATE
    REPO="$project" SHA="$(git -C "$project" rev-parse HEAD)" LOG="$barrier/land.log"
    printf -v GATE 'diff -r %q %q' "$project/.git/worktrees" "$barrier/registry-before"
    eval "$(sed -n '/^run_gate() (/,/^)/p' "$ROOT/scripts/land.sh")"
    run_gate
  ) || land_rc=$?
  diff -r "$project/.git/worktrees" "$barrier/registry-before" > "$barrier/registry.diff" || land_rc=1

  # FIFO completion is the harder case: B's outer guard began before A's
  # managed worktree existed, and ends while A is still live. That registration
  # and A's liveness state are owner-managed concurrency, not worker tampering.
  : > "$barrier/b.release"
  wait "$pid_b" || rc_b=$?
  artifact_b="$(sed -n 's/^artifact: //p' "$barrier/b.out" | sed -n '1p')"
  patch_b="$(sed -n 's/^patch: //p' "$barrier/b.out" | sed -n '1p')"
  : > "$barrier/a.release"
  wait "$pid_a" || rc_a=$?
  artifact_a="$(sed -n 's/^artifact: //p' "$barrier/a.out" | sed -n '1p')"
  patch_a="$(sed -n 's/^patch: //p' "$barrier/a.out" | sed -n '1p')"
  [ "$land_rc" = 0 ] || fail "land changed the workers' registry: $(cat "$barrier/land.log" "$barrier/registry.diff")"
  [ "$rc_a" = 0 ] && [ "$rc_b" = 0 ] ||
    fail "well-behaved parallel delegates should both pass (a=$rc_a b=$rc_b): $(cat "$barrier/a.err" "$barrier/b.err")"
  [ -s "$artifact_a" ] && [ -s "$artifact_b" ] && [ -s "$patch_a" ] && [ -s "$patch_b" ] ||
    fail "parallel delegates lost an artifact or patch (a=$artifact_a/$patch_a b=$artifact_b/$patch_b)"
  assert_file_contains "$artifact_a" 'parallel worker a done'
  assert_file_contains "$artifact_b" 'parallel worker b done'
  index="$project/.oms/artifacts/index.jsonl"
  assert_file_contains "$index" "$(basename "$artifact_a")"
  assert_file_contains "$index" "$(basename "$artifact_b")"
  if grep -Fq 'changed owner authority shared-state' "$barrier/a.err" "$barrier/b.err"; then
    fail "sibling owner writes must not be attributed to either worker"
  fi
}

# smoke-weight: 96
test_worker_guard_sees_submodule_and_worktree_metadata() {
  local project="$TMP/guard-submodule"
  local source="$TMP/guard-submodule-src"
  local result

  make_committed_repo "$source"
  make_guard_repo "$project"
  # A submodule keeps its own config, refs, and hooks under .git/modules, which
  # the parent's status never shows.
  ( cd "$project" && git -c protocol.file.allow=always -c user.email=t@example.com \
    -c user.name=t submodule add -q "$source" vendor >/dev/null 2>&1 &&
    git -c user.email=t@example.com -c user.name=t commit -qm submodule >/dev/null )
  [ -d "$project/.git/modules/vendor" ] || fail "submodule fixture did not materialize"

  result="$(run_guarded_worker "$project" \
    "git -C $project/vendor config --local oms.tampered yes")"
  [ "${result%%	*}" != 0 ] || fail "submodule config tampering should fail the run: $result"
  contains "$result" 'gitmeta' ||
    fail "submodule metadata should be named: $result"

  # A linked worktree is another checkout of the same repo, registered in the
  # common git dir.
  local wt="$TMP/guard-worktree"
  make_guard_repo "$wt"
  local scratch="$TMP/guard-unmanaged-scratch"
  local ready="$TMP/guard-unmanaged-ready" done="$TMP/guard-unmanaged-done"
  local action pid
  for action in add remove; do
    rm -f "$ready" "$done"
    (
      local tries=0
      while [ ! -f "$ready" ] && [ "$tries" -lt 100 ]; do sleep 0.1; tries=$((tries + 1)); done
      [ -f "$ready" ] || exit 1
      if [ "$action" = add ]; then
        git -C "$wt" worktree add -q --detach "$scratch" HEAD
      else
        git -C "$wt" worktree remove "$scratch"
      fi
      touch "$done"
    ) &
    pid=$!
    result="$(run_guarded_worker "$wt" \
      "touch '$ready'; tries=0; while [ ! -f '$done' ] && [ \"\$tries\" -lt 100 ]; do sleep 0.1; tries=\$((tries + 1)); done; [ -f '$done' ] || exit 1")"
    wait "$pid" || fail "foreign worktree $action fixture timed out"
    [ "${result%%$'\t'*}" = 0 ] || fail "foreign worktree $action stopped the worker: $result"
    contains "$result" 'during this run: foreign-worktree' || fail "foreign lifecycle warning missing: $result"
  done
  result="$(OMS_WORKER_GUARD_STRICT=1 OMS_TASK_ID=guard-worktree run_guarded_worker "$wt" \
    "git -C $wt worktree add --detach $wt/../guard-worktree-extra HEAD")"
  [ "${result%%	*}" != 0 ] || fail "registering a worktree should fail the run: $result"
  contains "$result" 'gitmeta' ||
    fail "a new worktree registration should be named: $result"
  # The room and panel relay the artifact's closing Output, not stderr.
  python3 - "$wt" "$ROOT/scripts/lib" <<'PY' || fail "a guard failure must leave a readable reason"
import json, sys
from pathlib import Path
sys.path.insert(0, sys.argv[2])
from peer_artifacts import artifact_sections
import panel_results
repo = Path(sys.argv[1])
row = [json.loads(line) for line in (repo / ".oms/artifacts/index.jsonl").read_text().splitlines()][-1]
answer, code = artifact_sections(repo / row["artifact"])
reason = "The worker guard stopped this run: protected state changed outside the worker's worktree (gitmeta)."
assert code == "1" and answer.startswith(reason) and "nothing was landed" in answer, (code, answer)
assert "snapshot=canonical repository gitmeta worktrees/" in answer, answer
details = answer.split("Changed paths/refs by snapshot (up to 12 sanitized lines):\n", 1)[1].split("\nExecution-state details:", 1)[0]
assert 1 <= len(details.splitlines()) <= 12, details
assert str(repo) not in answer, answer
failures = [json.loads(line) for line in (repo / ".oms/failures.jsonl").read_text().splitlines()]
failure = [row for row in failures if row.get("cmd") == "peer-delegate --to codex worker-authority"][-1]
assert failure["failure_code"] == "guard_parent_interference", failure
assert failure["recovery"] == "inspect_guard_evidence_and_redispatch", failure
assert "gitmeta worktrees/" in failure["summary"], failure
assert "Inspect the preserved evidence and re-dispatch from a fresh base after the concurrent change." in failure["next"], failure
assert "`" not in failure["next"] and "git add" not in failure["next"] and "git diff" not in failure["next"], failure
assert str(repo) not in answer, answer
calls = panel_results.results(repo, "guard-worktree")["rows"][0]["calls"]
assert any(reason in call.get("answer", "") for call in calls), calls
PY

  # A scratch-shaped marker outside the managed roots vouches for nothing.
  local forged="$TMP/guard-worktree-forged"
  local forged_parent="$TMP/guard-worktree-forged-dir/oh-my-setting-scratch.forged"
  make_guard_repo "$forged"
  mkdir -p "$forged_parent"
  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$forged" \
    "printf 'kind=oh-my-setting-temp\\npid=$$\\nrepo=$forged\\nworktree=$forged_parent/wt\\ntemporary=1\\n' > $forged_parent/.oh-my-setting-tmp && git -C $forged worktree add --detach $forged_parent/wt HEAD")"
  [ "${result%%	*}" != 0 ] || fail "a forged scratch marker must not exempt a worker's add: $result"
  contains "$result" 'gitmeta' ||
    fail "a forged scratch registration should be named: $result"

  # Per-worktree config can execute on a sibling's next Git command. Protect
  # in-place edits and registration swaps, including live managed entries.
  local admin="$TMP/guard-foreign-admin"
  local managed_root="$TMP/guard-foreign-admin-root"
  local sibling_parent="$managed_root/oh-my-setting-scratch.admin"
  local sibling="$sibling_parent/wt"
  local entry replacement field target body managed
  for managed in 0 1; do
    for field in config.worktree commondir gitdir swap swap-config; do
      target="$admin-$managed-$field"
      make_guard_repo "$target"
      git -C "$target" config extensions.worktreeConfig true
      if [ "$managed" = 1 ]; then
        make_live_managed_sibling "$target" "$sibling_parent-$managed-$field"
        sibling="$sibling_parent-$managed-$field/wt"
      else
        sibling="$sibling_parent-$managed-$field/plain foreign"
        git -C "$target" worktree add -q --detach "$sibling" HEAD
      fi
      entry="$(git -C "$sibling" rev-parse --git-dir)"
      entry="${entry//$'\r'/}"
      case "$entry" in /*) ;; *) entry="$sibling/$entry" ;; esac
      case "$field" in
        config.worktree) body="printf '[core]\\n\\thooksPath = /tmp/guard-no-hooks\\n' > '$entry/config.worktree'" ;;
        commondir) body="printf '../../.\\n' > '$entry/commondir'" ;;
        gitdir) body="printf '%s\\n' '$sibling/./.git' > '$entry/gitdir'" ;;
        swap*)
          replacement="${entry%/*}/swapped"
          body="cp -R '$entry' '$replacement'"
          [ "$field" != swap-config ] || body="$body
  printf '[core]\\n\\thooksPath = /tmp/guard-no-hooks\\n' > '$replacement/config.worktree'"
          body="$body
  printf 'gitdir: %s\\n' '$replacement' > '$sibling/.git'
  rm -rf '$entry'"
          ;;
      esac
      body='case "${1:-}:${2:-}" in --version:|--help:|exec:--help) exit 0 ;; esac'"
$body"
      result="$(run_delegate_beside_sibling "$target" "$managed_root" "$body")"
      [ "${result%%$'\t'*}" != 0 ] || fail "foreign entry $field mutation must stay hard: $result"
      contains "$result" 'outside its worktree: gitmeta' || fail "foreign $field mutation was not named: $result"
    done
  done

  local read_root="$TMP/guard-read-managed-replacement-root"
