      sed '1s/oms_worker_gitmeta_only_added_removed_siblings/ma_read_guard_real_only_added_removed_siblings/')"
    eval "$(declare -f oms_worker_gitmeta_only_kept_siblings |
      sed '1s/oms_worker_gitmeta_only_kept_siblings/ma_read_guard_real_only_kept_siblings/')"
    oms_worker_gitmeta_only_added_removed_siblings() {
      local status=0
      if [ "${MA_READ_GUARD_TEST_PLANT_AFTER_ADMIN:-0}" = 1 ] &&
        [ ! -e "$MA_READ_GUARD_TEST_PLANTED_WORKTREE" ]; then
        mkdir -p "${MA_READ_GUARD_TEST_PLANTED_WORKTREE%/wt}" || return 1
        git -C "$MA_READ_GUARD_TEST_REPO" worktree add --quiet --detach \
          "$MA_READ_GUARD_TEST_PLANTED_WORKTREE" HEAD || return 1
      fi
      if [ "${MA_READ_GUARD_TEST_REPLACE_AFTER_ADMIN:-0}" = 1 ] &&
        [ ! -e "$MA_READ_GUARD_TEST_SLOT_REPLACEMENT" ]; then
        git -C "$MA_READ_GUARD_TEST_REPO" worktree remove --force \
          "$MA_READ_GUARD_TEST_MANAGED_WORKTREE" || return 1
        rm -rf "$MA_READ_GUARD_TEST_MANAGED_PARENT" || return 1
        mkdir -p "${MA_READ_GUARD_TEST_SLOT_REPLACEMENT%/wt}" || return 1
        git -C "$MA_READ_GUARD_TEST_REPO" worktree add --quiet --detach \
          "$MA_READ_GUARD_TEST_SLOT_REPLACEMENT" HEAD || return 1
      fi
      ma_read_guard_real_only_added_removed_siblings "$@" || status=$?
      [ "${MA_READ_GUARD_TEST_FORCE_RAW_GITMETA:-0}" != 1 ] || return 1
      return "$status"
    }
    oms_worker_gitmeta_only_kept_siblings() {
      local status=0
      ma_read_guard_real_only_kept_siblings "$@" || status=$?
      [ "${MA_READ_GUARD_TEST_FORCE_RAW_GITMETA:-0}" != 1 ] || return 1
      return "$status"
    }
    export MA_READ_GUARD_TEST_FORCE_RAW_GITMETA=1
    read_surface="$(oms_worker_surface_diff "$wt" "$MA_READ_GUARD_DIR/state" "" "$source" | tr -d '\r')"
    [ "$read_surface" = gitmeta ] ||
      fail "managed replacement repro did not emit bare gitmeta: $read_surface"
    grep -Fxq "worktrees/$read_slot" "$MA_READ_GUARD_DIR/state/gitmeta-managed-replaced" ||
      fail "bare-gitmeta repro lacks validated same-slot proof: $read_surface"
    read_rc=0
    read_out="$(ma_read_guard_assert 2>&1)" || read_rc=$?
    [ "$read_rc" = 0 ] || fail "read guard rejected managed slot replacement: $read_out"
    grep -Fxq "worktrees/$read_slot" "$MA_READ_GUARD_DIR/state/gitmeta-managed-replaced" ||
      fail "read guard skipped the validated replacement record ($(cat "$MA_READ_GUARD_DIR/state/gitmeta-managed-replaced")): $read_out"
    contains "$read_out" 'state repository changes: gitmeta-managed-replaced' ||
      fail "read guard did not name the narrow replacement relief: $read_out"

    # A distinct unmanaged entry in the final surface capture invalidates the
    # replacement-only proof even though the managed slot itself was validated.
    local planted_root="$TMP/guard-read-planted-alongside-replacement"
    local planted="$planted_root/wt"
    local planted_old_admin planted_new_admin planted_entry_slot planted_replacement_slot
    local planted_old="$read_root/oh-my-setting-delegate.planted-old"
    local planted_new="$read_root/oh-my-setting-delegate.planted-new"
    make_live_managed_sibling "$wt" "$planted_old"
    planted_old_admin="$(git -C "$planted_old/wt" rev-parse --git-dir)"
    planted_old_admin="${planted_old_admin//$'\r'/}"
    case "$planted_old_admin" in /*) ;; *) planted_old_admin="$wt/$planted_old_admin" ;; esac
    sed 's/^pid=.*/pid=999999999/' "$planted_old/.oh-my-setting-tmp" \
      > "$planted_old/.oh-my-setting-tmp.dead"
    mv "$planted_old/.oh-my-setting-tmp.dead" "$planted_old/.oh-my-setting-tmp"
    ma_read_guard_begin "$read_snapshot/planted-alongside" ||
      fail "planted replacement snapshot failed"
    git -C "$wt" worktree remove --force "$planted_old/wt"
    rm -rf "$planted_old"
    make_live_managed_sibling "$wt" "$planted_new"
    planted_new_admin="$(git -C "$planted_new/wt" rev-parse --git-dir)"
    planted_new_admin="${planted_new_admin//$'\r'/}"
    case "$planted_new_admin" in /*) ;; *) planted_new_admin="$read_root/$planted_new_admin" ;; esac
    [ "$planted_new_admin" = "$planted_old_admin" ] ||
      fail "planted replacement fixture did not reuse the managed admin slot"
    planted_replacement_slot="${planted_new_admin##*/}"
    export MA_READ_GUARD_TEST_PLANT_AFTER_ADMIN=1
    export MA_READ_GUARD_TEST_PLANTED_WORKTREE="$planted"
    export MA_READ_GUARD_TEST_REPO="$wt"
    read_rc=0
    read_out="$(ma_read_guard_assert 2>&1)" || read_rc=$?
    unset MA_READ_GUARD_TEST_PLANT_AFTER_ADMIN
    [ "$read_rc" = 2 ] || fail "read guard accepted planted metadata alongside replacement: $read_out"
    planted_admin="$(git -C "$planted" rev-parse --git-dir)"
    planted_admin="${planted_admin//$'\r'/}"
    planted_entry_slot="${planted_admin##*/}"
    grep -Fxq "worktrees/$planted_replacement_slot" "$MA_READ_GUARD_DIR/state/gitmeta-managed-replaced" ||
      fail "planted replacement case lost the managed replacement proof for $planted_replacement_slot: $read_out"
    grep -Fq "worktrees/$planted_entry_slot" "$MA_READ_GUARD_DIR/state/gitmeta-now" ||
      fail "planted replacement case did not retain the late planted-entry capture: $read_out"
    if grep -Fq "worktrees/$planted_entry_slot" "$MA_READ_GUARD_DIR/state/gitmeta-admin-now"; then
      fail "planted replacement case appeared in the early admin capture: $read_out"
    fi
    ma_read_guard_gitmeta_replacement_only "$MA_READ_GUARD_DIR/state" &&
      fail "planted replacement unexpectedly passed the replacement-only proof"
    git -C "$wt" worktree remove --force "$planted"
    git -C "$wt" worktree remove --force "$planted_new/wt"
    rm -rf "$planted_root" "$planted_new"

    # Isolate the capture race: after the early managed-slot validation,
    # replace that same slot with an unmanaged checkout and leave no other
    # post-capture admin entry to make the final delta hard on its own.
    local takeover_root="$TMP/guard-read-admin-capture-takeover"
    local takeover="$takeover_root/wt"
    local takeover_old="$read_root/oh-my-setting-delegate.takeover-old"
    local takeover_new="$read_root/oh-my-setting-delegate.takeover-new"
    local takeover_old_admin takeover_new_admin takeover_slot takeover_admin
    local takeover_admin_rows="$TMP/guard-read-takeover-admin-rows"
    local takeover_final_rows="$TMP/guard-read-takeover-final-rows"
    make_live_managed_sibling "$wt" "$takeover_old"
    takeover_old_admin="$(git -C "$takeover_old/wt" rev-parse --git-dir)"
    takeover_old_admin="${takeover_old_admin//$'\r'/}"
    case "$takeover_old_admin" in /*) ;; *) takeover_old_admin="$wt/$takeover_old_admin" ;; esac
    sed 's/^pid=.*/pid=999999999/' "$takeover_old/.oh-my-setting-tmp" \
      > "$takeover_old/.oh-my-setting-tmp.dead"
    mv "$takeover_old/.oh-my-setting-tmp.dead" "$takeover_old/.oh-my-setting-tmp"
    ma_read_guard_begin "$read_snapshot/admin-capture-takeover" ||
      fail "admin-capture takeover snapshot failed"
    git -C "$wt" worktree remove --force "$takeover_old/wt"
    rm -rf "$takeover_old"
    make_live_managed_sibling "$wt" "$takeover_new"
    takeover_new_admin="$(git -C "$takeover_new/wt" rev-parse --git-dir)"
    takeover_new_admin="${takeover_new_admin//$'\r'/}"
    case "$takeover_new_admin" in /*) ;; *) takeover_new_admin="$wt/$takeover_new_admin" ;; esac
    [ "$takeover_new_admin" = "$takeover_old_admin" ] ||
      fail "admin-capture fixture did not reuse the managed admin slot"
    takeover_slot="${takeover_new_admin##*/}"
    export MA_READ_GUARD_TEST_REPLACE_AFTER_ADMIN=1
    export MA_READ_GUARD_TEST_MANAGED_WORKTREE="$takeover_new/wt"
    export MA_READ_GUARD_TEST_MANAGED_PARENT="$takeover_new"
    export MA_READ_GUARD_TEST_SLOT_REPLACEMENT="$takeover"
    export MA_READ_GUARD_TEST_REPO="$wt"
    read_rc=0
    read_out="$(ma_read_guard_assert 2>&1)" || read_rc=$?
    unset MA_READ_GUARD_TEST_REPLACE_AFTER_ADMIN
    unset MA_READ_GUARD_TEST_MANAGED_WORKTREE MA_READ_GUARD_TEST_MANAGED_PARENT
    unset MA_READ_GUARD_TEST_SLOT_REPLACEMENT
    [ "$read_rc" = 2 ] ||
      fail "read guard accepted unmanaged content replacing the validated slot after admin capture: $read_out"
    takeover_admin="$(git -C "$takeover" rev-parse --git-dir)"
    takeover_admin="${takeover_admin//$'\r'/}"
    case "$takeover_admin" in /*) ;; *) takeover_admin="$wt/$takeover_admin" ;; esac
    [ "${takeover_admin##*/}" = "$takeover_slot" ] ||
      fail "admin-capture fixture did not replace the validated slot in place"
    grep -Fxq "worktrees/$takeover_slot" "$MA_READ_GUARD_DIR/state/gitmeta-managed-replaced" ||
      fail "admin-capture takeover lost its early validated replacement proof: $read_out"
    grep -E "^worktree-dir worktrees/$takeover_slot$|^worktree worktrees/$takeover_slot/(HEAD|gitdir|commondir) " \
      "$MA_READ_GUARD_DIR/state/gitmeta-admin-now" > "$takeover_admin_rows" ||
      fail "admin-capture takeover lacks early slot lines"
    grep -E "^worktree-dir worktrees/$takeover_slot$|^worktree worktrees/$takeover_slot/(HEAD|gitdir|commondir) " \
      "$MA_READ_GUARD_DIR/state/gitmeta-now" > "$takeover_final_rows" ||
      fail "admin-capture takeover lacks late slot lines"
    if cmp -s "$takeover_admin_rows" "$takeover_final_rows"; then
      fail "admin-capture takeover did not change the validated slot's late content"
    fi
    git -C "$wt" worktree remove --force "$takeover"
    rm -rf "$takeover_root" "$takeover_new"
    unset MA_READ_GUARD_TEST_FORCE_RAW_GITMETA
    unset MA_READ_GUARD_TEST_PLANTED_WORKTREE MA_READ_GUARD_TEST_REPO

    git -C "$wt" worktree remove --force "$read_new/wt"
    rm -rf "$read_new"

    local unmanaged="$TMP/guard-read-unmanaged-replacement/wt"
    local managed_old="$read_root/oh-my-setting-delegate.unmanaged"
    make_live_managed_sibling "$wt" "$managed_old"
    ma_read_guard_begin "$read_snapshot/unmanaged" ||
      fail "unmanaged replacement snapshot failed"
    git -C "$wt" worktree remove --force "$managed_old/wt"
    mkdir -p "${unmanaged%/wt}"
    git -C "$wt" worktree add --quiet --detach "$unmanaged" HEAD
    read_rc=0
    read_out="$(ma_read_guard_assert 2>&1)" || read_rc=$?
    [ "$read_rc" = 2 ] || fail "read guard accepted unmanaged slot replacement: $read_out"
    contains "$read_out" 'gitmeta' || fail "unmanaged slot rejection lost gitmeta: $read_out"
    git -C "$wt" worktree remove --force "$unmanaged"

    local strict_old="$read_root/oh-my-setting-delegate.strict-old"
    local strict_new="$read_root/oh-my-setting-delegate.strict-new"
    make_live_managed_sibling "$wt" "$strict_old"
    sed 's/^pid=.*/pid=999999999/' "$strict_old/.oh-my-setting-tmp" \
      > "$strict_old/.oh-my-setting-tmp.dead"
    mv "$strict_old/.oh-my-setting-tmp.dead" "$strict_old/.oh-my-setting-tmp"
    ma_read_guard_begin "$read_snapshot/strict" || fail "strict replacement snapshot failed"
    git -C "$wt" worktree remove --force "$strict_old/wt"
    rm -rf "$strict_old"
    make_live_managed_sibling "$wt" "$strict_new"
    read_rc=0
    read_out="$(OMS_WORKER_GUARD_STRICT=1 ma_read_guard_assert 2>&1)" || read_rc=$?
    [ "$read_rc" = 2 ] || fail "strict read guard accepted managed slot replacement: $read_out"
    contains "$read_out" 'sibling-cleanup' && contains "$read_out" 'kept-sibling' ||
      fail "strict replacement rejection lost the hard metadata classifications: $read_out"
  ) || fail "read guard managed worktree replacement cases failed"
}

test_shared_memory_context_ranked_recall() {
  local repo="$TMP/memory-recall-ctx"
  local out bad

  make_committed_repo "$repo"
  ( cd "$repo" &&
    bash "$ROOT/scripts/agent-memory.sh" append --agent claude \
      --text "Always run the focused parser test before landing parser changes." >/dev/null &&
    bash "$ROOT/scripts/agent-memory.sh" append --agent claude \
      --text "The deploy pipeline needs the staging flag." >/dev/null )

  # Naming the operation adds a query-ranked recall section to the injected
  # memory context; without a query the recency tails stand alone.
  out="$(cd "$repo" && bash -c '. "$1"; ma_write_shared_memory_context "$2" "refactor the parser module tests"' \
    _ "$ROOT/scripts/lib/agent-memory-common.sh" "$repo")"
  contains "$out" '### relevant recall' ||
    fail "query should add a ranked recall section: $out"
  contains "$out" 'focused parser test' ||
    fail "recall should surface the matching lesson"
  out="$(cd "$repo" && OMS_AGENT_MEMORY_MODE=relevant bash -c '. "$1"; ma_write_shared_memory_context "$2" "parser module tests"' \
    _ "$ROOT/scripts/lib/agent-memory-common.sh" "$repo")"
  contains "$out" 'focused parser test' || fail "relevant mode lost matching evidence"
  contains "$out" '[selection: query relevance' || fail "recall selection reason missing"
  if contains "$out" 'staging flag'; then
    fail "relevant mode included unrelated recent deployment memory"
  fi
  out="$(cd "$repo" && OMS_AGENT_MEMORY_MODE=relevant bash -c '. "$1"; ma_write_shared_memory_context "$2" "zzzxxyy no-match"' \
    _ "$ROOT/scripts/lib/agent-memory-common.sh" "$repo")"
  [ -z "$out" ] || fail "no-match relevant recall should not inject unrelated summaries"
  out="$(cd "$repo" && bash -c '. "$1"; ma_write_shared_memory_context "$2"' \
    _ "$ROOT/scripts/lib/agent-memory-common.sh" "$repo")"
  if contains "$out" 'relevant recall'; then
    fail "no query must mean no recall section"
  fi

  # A note scoped to paths belongs to work on those paths: plain recall still
  # finds it, a target ranks a match first and leaves other scopes out, and
  # neither the compact summary nor injected recall carries it unasked.
  local memory="$ROOT/scripts/agent-memory.sh" lib="$ROOT/scripts/lib/agent-memory-common.sh"
  ( cd "$repo" &&
    bash "$memory" append --paths 'src/parser/**,*.yaml' \
      --text "The parser tokenizer tests need the frozen grammar fixture." >/dev/null &&
    bash "$memory" append --paths 'docs/**' \
      --text "The parser tests guide lives in the handbook chapter." >/dev/null )
  assert_file_contains "$repo/.oms/memory/shared.md" 'paths: src/parser/**,*.yaml'
  if grep -q 'frozen grammar fixture\|handbook chapter' "$repo/.oms/memory/summary.md"; then
    fail "a path-scoped note must stay out of the compact summary"
  fi
  out="$(cd "$repo" && bash "$memory" recall parser tests 2>/dev/null)"
  contains "$out" 'frozen grammar fixture' && contains "$out" 'handbook chapter' ||
    fail "plain recall must still find path-scoped notes: $out"
  out="$(cd "$repo" && bash "$memory" recall --target src/parser/lexer/tokens.py parser tests 2>/dev/null)"
  [ "$(printf '%s\n' "$out" | grep -v '^$' | sed -n 2p)" = "The parser tokenizer tests need the frozen grammar fixture." ] ||
    fail "a note scoped to the target path must rank first: $out"
  contains "$out" 'focused parser test' || fail "an unscoped note must survive a target: $out"
  if contains "$out" 'handbook chapter'; then fail "a note scoped elsewhere must be left out: $out"; fi
  out="$(cd "$repo" && bash "$memory" recall --target ./config.yaml,tools/x.py parser tests 2>/dev/null)"
  contains "$out" 'frozen grammar fixture' || fail "a single-level glob must match a top-level file: $out"
  out="$(cd "$repo" && bash "$memory" recall --target nested/config.yaml parser tests 2>/dev/null)"
  if contains "$out" 'frozen grammar fixture'; then fail "a single * must not cross a directory: $out"; fi
  out="$(cd "$repo" && bash -c '. "$1"; ma_write_shared_memory_context "$2" "parser tests"' _ "$lib" "$repo")"
  if contains "$out" 'frozen grammar fixture' || contains "$out" 'handbook chapter'; then
    fail "injected recall must not carry a path-scoped note when the work's paths are unknown: $out"
  fi
  out="$(cd "$repo" && OMS_MEMORY_TARGET_PATHS=docs/guide.md bash -c \
    '. "$1"; ma_write_shared_memory_context "$2" "parser tests"' _ "$lib" "$repo")"
  contains "$out" 'handbook chapter' || fail "injected recall should carry a note scoped to the named paths: $out"
  if contains "$out" 'frozen grammar fixture'; then fail "injected recall carried another scope: $out"; fi

  # Frozen task paths are scope patterns, not recall's concrete target names.
  # Resolve tracked paths, apply deny rules, and retain declared new files.
  local peer="$ROOT/scripts/lib/peer-common.sh" scope note_id
  mkdir -p "$repo/src/parser/denied" "$repo/docs" "$repo/ignored" "$repo/.github/jobs" "$repo/github/jobs"
  printf 'fixture\n' > "$repo/src/parser/tokens.py"
  printf 'fixture\n' > "$repo/src/parser/denied/omit.py"
  printf 'fixture\n' > "$repo/docs/guide.md"
  printf 'fixture\n' > "$repo/.github/jobs/main.yml"
  printf 'fixture\n' > "$repo/github/jobs/main.yml"
  printf 'ignored/\n' > "$repo/.gitignore"
  printf 'private fixture\n' > "$repo/ignored/checkpoint.bin"
  git -C "$repo" add src docs .gitignore .github github
  git -C "$repo" commit -qm recall-scope-fixture
  "$memory" --repo "$repo" append --paths 'src/parser/denied/**' \
    --text 'Parser tests denied scope lesson.' >/dev/null
  "$memory" --repo "$repo" append --paths 'new/**' \
    --text 'Parser tests new file invariant.' >/dev/null
  "$memory" --repo "$repo" append --paths 'ignored/**' \
    --text 'Parser tests ignored checkpoint lesson.' >/dev/null
  "$memory" --repo "$repo" append --paths '.github/**' \
    --text 'Parser tests hidden workflow invariant.' >/dev/null
  "$memory" --repo "$repo" append --paths 'github/**' \
    --text 'Parser tests visible workflow distraction.' >/dev/null
  for scope in retired redacted; do
    "$memory" --repo "$repo" append --paths 'src/parser/**' \
      --text "Parser tests $scope scope lesson." >/dev/null
    note_id="$("$memory" --repo "$repo" search --json "$scope scope lesson" 2>/dev/null |
      python3 -c 'import json,sys; print(json.load(sys.stdin)["event_id"])')"
    if [ "$scope" = retired ]; then
      "$memory" --repo "$repo" retire --id "$note_id" --reason obsolete >/dev/null
    else
      "$memory" --repo "$repo" redact --id "$note_id" --apply >/dev/null
    fi
  done
  for scope in 'src/parser/' 'src/parser/*.py'; do
    out="$(OMS_MEMORY_TARGET_PATHS=docs/guide.md bash -c \
      '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 "parser tests" "$3" "src/parser/denied/"' \
      _ "$peer" "$repo" "$scope")"
    contains "$out" 'frozen grammar fixture' || fail "task scope lost its matching note: $out"
    contains "$out" 'focused parser test' || fail "task scope lost an unscoped note: $out"
    for bad in 'handbook chapter' 'denied scope lesson' 'retired scope lesson' 'redacted scope lesson'; do
      if contains "$out" "$bad"; then fail "task scope injected ineligible memory: $bad"; fi
    done
  done
  out="$(bash -c '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 "parser tests" "docs/" ""' \
    _ "$peer" "$repo")"
  contains "$out" 'handbook chapter' || fail "changing task paths did not change recall"
  if contains "$out" 'frozen grammar fixture'; then fail "changed task retained its previous scope"; fi
  out="$(bash -c '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 "parser tests" "new/parser.py" ""' \
    _ "$peer" "$repo")"
  contains "$out" 'new file invariant' || fail "a declared new file must supply a recall target"
  out="$(bash -c '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 "parser tests" "ignored/**" ""' \
    _ "$peer" "$repo")"
  if contains "$out" 'ignored checkpoint lesson'; then fail "task recall must not discover ignored files"; fi
  out="$(bash -c '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 "parser tests" ".github/" ""' \
    _ "$peer" "$repo")"
  contains "$out" 'hidden workflow invariant' || fail "dot-directory task scope lost its note"
  if contains "$out" 'visible workflow distraction'; then fail "dot-directory task scope became another directory"; fi
  out="$("$memory" --repo "$repo" recall --target ./.github/jobs/main.yml parser tests 2>/dev/null)"
  contains "$out" 'hidden workflow invariant' || fail "literal ./ removal changed a dot-directory target"
  if contains "$out" 'visible workflow distraction'; then fail "./ normalization stripped a real leading dot"; fi
  out="$(OMS_MEMORY_TARGET_PATHS=docs/guide.md bash -c \
    '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 "parser tests" "" ""' _ "$peer" "$repo")"
  if contains "$out" 'handbook chapter'; then fail "an empty task scope inherited another task target"; fi
  (
    . "$peer"
    MA_KIND=delegate
    export OMS_MEMORY_TARGET_PATHS=docs/guide.md
    ma_write_harness_context "$repo" 1 0 0 'parser tests' 'src/parser/' 'src/parser/denied/' >/dev/null
    [ "$OMS_MEMORY_TARGET_PATHS" = docs/guide.md ] || fail "task targets leaked into the caller environment"
    ma_write_harness_context "$repo" 1 0 0 'parser tests' > "$repo/legacy-recall"
    unset OMS_MEMORY_TARGET_PATHS
    ma_write_harness_context "$repo" 1 0 0 'parser tests' 'docs/' '' >/dev/null
    [ -z "${OMS_MEMORY_TARGET_PATHS+x}" ] || fail "task recall exported a target into later calls"
    ma_write_harness_context "$repo" 1 0 0 'parser tests docs/guide.md' > "$repo/unknown-recall"
  )
  assert_file_contains "$repo/legacy-recall" 'handbook chapter'
  if grep -Fq 'handbook chapter' "$repo/unknown-recall"; then fail "prompt text supplied an undeclared task scope"; fi

  # State/context owners can differ from a source index (including a managed
  # scratch branch). Explicit source binding must win over the registry owner.
  local source_repo="$TMP/memory-recall-source"
  make_committed_repo "$source_repo"
  mkdir -p "$source_repo/remote"
  printf 'fixture\n' > "$source_repo/remote/entry.py"
  git -C "$source_repo" add remote/entry.py
  git -C "$source_repo" commit -qm source-scope
  "$memory" --repo "$repo" append --paths 'remote/**' \
    --text 'Parser tests remote source invariant.' >/dev/null
  out="$(env -u MA_READ_SOURCE_REPO OMS_PANEL_DISPATCH=1 OMS_ROOM_REPO="$repo" REPO="$repo" \
    bash -c '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 "parser tests" "remote/" "" "$3"' \
    _ "$peer" "$repo" "$source_repo")"
  contains "$out" 'remote source invariant' || fail "task targets were resolved against the state repository"
  assert_not_exists "$source_repo/.oms"
  python3 - "$source_repo" <<'PY'
import subprocess, sys
git = ["git", "-C", sys.argv[1]]
blob = subprocess.check_output(git + ["hash-object", "-w", "--stdin"], input=b"fixture\n").decode().strip()
rows = "".join("100644 %s\tbounded/%05d.py\n" % (blob, index) for index in range(10001))
subprocess.run(git + ["update-index", "--index-info"], input=rows.encode(), check=True)
PY
  out="$(env -u MA_READ_SOURCE_REPO OMS_PANEL_DISPATCH=1 OMS_ROOM_REPO="$repo" REPO="$repo" \
    OMS_MEMORY_TARGET_PATHS=docs/guide.md bash -c \
    '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 "parser tests" "remote/" "" "$3"' \
    _ "$peer" "$repo" "$source_repo" 2> "$repo/scope-limit.err")"
  contains "$out" 'focused parser test' || fail "scope enumeration limit lost unscoped recall"
  if contains "$out" 'remote source invariant' || contains "$out" 'handbook chapter'; then
    fail "scope enumeration limit reused partial or inherited targets"
  fi
  assert_file_contains "$repo/scope-limit.err" 'tracked-path limit; scoped recall omitted'

  local timeout_bin="$TMP/memory-target-timeout" timeout_status=0
  mkdir -p "$timeout_bin"
  printf '#!/bin/sh\nexec sleep 30\n' > "$timeout_bin/git"
  chmod +x "$timeout_bin/git"
  out="$(PATH="$timeout_bin:$PATH" bash -c '. "$1"; ma_task_memory_targets "$2" "src/" ""' \
    _ "$peer" "$repo" 2> "$repo/scope-timeout.err")" || timeout_status=$?
  [ "$timeout_status" -ne 0 ] && [ -z "$out" ] || fail "a stalled target lookup must fail without targets"
  assert_file_contains "$repo/scope-timeout.err" 'unavailable; scoped recall omitted'

  python3 -c 'print("scopebudget " * 800)' | "$memory" --repo "$repo" append --paths 'src/parser/**' --stdin >/dev/null
  bash -c '. "$1"; MA_KIND=delegate; ma_write_harness_context "$2" 1 0 0 scopebudget "src/parser/" ""' \
    _ "$peer" "$repo" > "$repo/budget-recall"
  python3 - "$repo/budget-recall" <<'PY' || fail "task recall exceeded the existing memory budget"
import pathlib, sys
text = pathlib.Path(sys.argv[1]).read_text(encoding="utf-8")
recall = text.split("### relevant recall (project)\n", 1)[1].split("\n--- end harness context ---", 1)[0]
assert 3900 <= len(recall.rstrip("\n").encode("utf-8")) <= 4000
PY
  for bad in '/etc/passwd' '../outside/**' 'a b'; do
    if (cd "$repo" && bash "$memory" append --paths "$bad" --text "never recorded" >/dev/null 2>&1); then
      fail "--paths must refuse: $bad"
    fi
  done
  if (cd "$repo" && bash "$memory" search --paths 'src/**' parser >/dev/null 2>&1); then
    fail "--paths applies only to append"
  fi
  ! grep -q 'never recorded' "$repo/.oms/memory/shared.md" || fail "a refused --paths must not append"
  # Explicit project recall also points at session handoff digests whose head
  # matches: a pointer and one line, never the digest body; a sensitive-looking
  # line is withheld; machine header lines do not match; injected recall and
  # global recall carry no pointer, and a removed digest stops matching.
  local handoffs="$repo/.oms/handoffs"
  mkdir -p "$handoffs"
  printf '%s\n' '# Session handoff: claude abc' '' '- captured: 2026-11-09T10:00:00Z' '- agent: claude' \
    '- cwd: /work/zebracrossing' '' '## Last assistant summary' '' 'Wired the quokka loader.' \
    'BODY-ONLY-LINE must never be printed by recall.' '' '## Original request (historical)' '' \
    'Make the quokka loader read the manifest first.' > "$handoffs/claude-abc.md"
  printf '%s\n' '# Session handoff: codex d' '' '- captured: 2026-11-08T10:00:00Z' '- agent: codex' '' \
    '## Original request (historical)' '' "api_k""ey: abcdefgh12345678 quokka thing" > "$handoffs/codex-d.md"
  out="$(cd "$repo" && bash "$memory" recall quokka loader 2>&1)" || fail "a handoff match alone must be a hit: $out"
  contains "$out" 'handoff digest: Make the quokka loader read the manifest first.' &&
    contains "$out" 'open: oms session-handoff show claude-abc.md' ||
    fail "recall should point at the matching handoff digest: $out"
  contains "$out" 'handoff digest: [withheld: sensitive-looking content]' &&
    contains "$out" 'open: oms session-handoff show codex-d.md' ||
    fail "a sensitive-looking handoff line must be withheld with its pointer kept: $out"
  if contains "$out" 'BODY-ONLY-LINE' || contains "$out" 'abcdefgh12345678'; then
    fail "recall must not print a digest body or a withheld line: $out"
  fi
  out="$(cd "$repo" && bash "$memory" recall --json quokka 2>/dev/null)"
  contains "$out" '"event_id": "handoff:claude-abc.md"' && contains "$out" '"kind": "handoff"' ||
    fail "handoff pointers should be typed in recall JSON: $out"
  if (cd "$repo" && bash "$memory" recall zebracrossing >/dev/null 2>&1); then
    fail "a handoff's machine header must not match"
  fi
  out="$(cd "$repo" && bash -c '. "$1"; ma_write_shared_memory_context "$2" "quokka loader"' _ "$lib" "$repo")"
  if contains "$out" 'handoff digest'; then fail "injected recall must not carry handoff pointers: $out"; fi
  rm -f "$handoffs/claude-abc.md" "$handoffs/codex-d.md"
  if (cd "$repo" && bash "$memory" recall quokka >/dev/null 2>&1); then
    fail "a removed handoff digest must stop matching"
  fi

  # A project note leaves its clone three explicit ways: promote copies it to
  # global memory (dry run unless --apply, parent only, once), graduate only
  # prints a diff for a checked-in document, and recall --all-repos reads the
  # registered clones' indexes without writing to them.
  local global="$TMP/memory-recall-global.md" registry="$TMP/memory-recall-registry.txt" note before
  ( cd "$repo" && bash "$memory" append --agent claude \
      --text "Wombat fixtures regenerate with make fixtures, never by hand." >/dev/null )
  note="$(cd "$repo" && bash "$memory" search --json wombat 2>/dev/null |
    python3 -c 'import json,sys; print(json.loads(sys.stdin.readline())["event_id"])')"
  out="$(cd "$repo" && OH_MY_SETTING_GLOBAL_MEMORY="$global" bash "$memory" promote --id "$note" --global 2>&1)" ||
    fail "promote dry run failed: $out"
  contains "$out" 'dry run; nothing changed' || fail "promote must default to a dry run: $out"
  [ ! -e "$global" ] || fail "a promote dry run must not create global memory"
  if (cd "$repo" && OMS_HARNESS_CHILD=1 OH_MY_SETTING_GLOBAL_MEMORY="$global" \
      bash "$memory" promote --id "$note" --global --apply >/dev/null 2>&1); then
    fail "a harness child must not promote to global memory"
  fi
  out="$(cd "$repo" && OH_MY_SETTING_GLOBAL_MEMORY="$global" bash "$memory" promote --id "$note" --global --apply 2>&1)" ||
    fail "promote --apply failed: $out"
  grep -Fq 'Wombat fixtures regenerate with make fixtures' "$global" &&
    grep -Fq "(promoted from project note $note)" "$global" ||
    fail "promote --apply should append the note and its origin ID to global memory"
  if grep -Fq "$repo" "$global" || grep -Fq 'memory-recall-ctx' "$global"; then
    fail "a promoted note must not carry the repository path or name"
  fi
  out="$(cd "$repo" && OH_MY_SETTING_GLOBAL_MEMORY="$global" bash "$memory" promote --id "$note" --global --apply 2>&1)"
  contains "$out" 'already in global memory' || fail "a second promote must be a no-op: $out"
  [ "$(grep -Fc 'Wombat fixtures regenerate' "$global")" = 1 ] || fail "promote appended twice"
  if (cd "$repo" && OH_MY_SETTING_GLOBAL_MEMORY="$global" bash "$memory" promote --id no-such-id --global --apply >/dev/null 2>&1); then
    fail "promote must refuse an unknown ID"
  fi
  printf '# Project\n\n## Decisions\n\n- keep it small\n\n## Notes\n\n- n\n' > "$repo/PROJECT.md"
  before="$(cat "$repo/PROJECT.md")"
  out="$(cd "$repo" && bash "$memory" graduate --id "$note" --to PROJECT.md 2>&1)" || fail "graduate failed: $out"
  contains "$out" '+- Wombat fixtures regenerate with make fixtures, never by hand.' &&
    contains "$out" ' - keep it small' && contains "$out" "retire --id $note --reason graduated" ||
    fail "graduate should print the diff under Decisions and the retire step: $out"
  [ "$(cat "$repo/PROJECT.md")" = "$before" ] || fail "graduate must never write the document"
  if (cd "$repo" && bash "$memory" graduate --id "$note" --to README.md >/dev/null 2>&1); then
    fail "graduate must refuse any other target"
  fi
  printf '%s\n' "$repo" "$TMP/memory-recall-absent" > "$registry"
  ( cd "$repo" && bash "$memory" recall wombat >/dev/null 2>&1 ) || fail "recall should index the wombat note"
  before="$(cd "$repo/.oms/memory" && cksum memory.sqlite3 shared.md)"
  out="$(cd "$TMP" && OMS_TICK_REGISTRY="$registry" bash "$memory" recall --all-repos wombat fixtures 2>&1)" ||
    fail "recall --all-repos should find the note: $out"
  contains "$out" "$note" && contains "$out" 'Wombat fixtures regenerate' &&
    contains "$out" '2 registered repositories (1 without an index)' && contains "$out" 'nothing was written' ||
    fail "recall --all-repos should name the hit, the repositories read and that it wrote nothing: $out"
  [ "$(cd "$repo/.oms/memory" && cksum memory.sqlite3 shared.md)" = "$before" ] ||
    fail "recall --all-repos must not write to a clone's index or log"
  if (cd "$TMP" && OMS_HARNESS_CHILD=1 OMS_TICK_REGISTRY="$registry" bash "$memory" recall --all-repos wombat >/dev/null 2>&1); then
    fail "a harness child must not read other repositories' memory"
  fi
  if (cd "$TMP" && OMS_TICK_REGISTRY="$registry" bash "$memory" recall --all-repos nosuchwordanywhere >/dev/null 2>&1); then
    fail "recall --all-repos without a hit must exit nonzero"
  fi
}

test_memory_recall_tracks_access_for_decay() {
  local repo="$TMP/memory-access-decay"
  local db

  make_committed_repo "$repo"
  ( cd "$repo" &&
    bash "$ROOT/scripts/agent-memory.sh" append --agent claude \
      --text "Parser fixes need the focused test first." >/dev/null &&
    bash "$ROOT/scripts/agent-memory.sh" append --agent claude \
      --text "Deploy needs the staging flag." >/dev/null )
  ( cd "$repo" && bash "$ROOT/scripts/agent-memory.sh" recall \
      --text "parser focused test" --limit 2 >/dev/null )
  db="$(find "$repo/.oms/memory" -name '*.sqlite3' | sed -n '1p')"
  [ -n "$db" ] || fail "memory database missing after recall"
  # Recall is what marks a memory as alive: the returned entry gains an
  # access row, and a second recall increments it. Stats live outside
  # memory_entries so a markdown re-derive cannot erase them.
  python3 - "$db" <<'PY' || fail "first recall should record one access"
import sqlite3, sys
rows = list(sqlite3.connect(sys.argv[1]).execute(
    "select hit_count from memory_access"))
assert rows == [(1,)], rows
PY
  ( cd "$repo" && bash "$ROOT/scripts/agent-memory.sh" recall \
      --text "parser focused test" --limit 2 >/dev/null )
  python3 - "$db" <<'PY' || fail "second recall should increment the hit count"
import sqlite3, sys
rows = list(sqlite3.connect(sys.argv[1]).execute(
    "select hit_count from memory_access"))
assert rows == [(2,)], rows
PY
}

test_shared_memory_writes_are_append_only() {
  local project="$TMP/memory-contract"
  local home_dir="$project/agenthome"
  local memory="$project/.oms/memory/shared.md"
  local before

  make_committed_repo "$project"
  mkdir -p "$home_dir"
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent codex --text "first note" >/dev/null
  before="$(cat "$memory")"

  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent claude --text "second note" >/dev/null
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" pin \
    --agent codex --text "pinned note" >/dev/null
  HOME="$home_dir" "$ROOT/scripts/agent-memory.sh" --repo "$project" compact >/dev/null

  # The guard verifies that existing bytes never change, so the writers have to
  # keep that true: a refactor that starts rewriting the log in place would
  # make every worker look like it forged shared state.
  [ "$(head -c "${#before}" "$memory")" = "$before" ] ||
    fail "appending a note must not rewrite what was already in shared.md"
  grep -Fq 'second note' "$memory" || fail "the new note should still be recorded"
  # summary.md is derived, so regenerating it is not a rewrite of the record.
  [ -f "$project/.oms/memory/summary.md" ] || fail "compact should produce a summary"
}

# smoke-weight: 5
test_worker_guard_keeps_shared_memory_parent_owned() {
  local project="$TMP/guard-memory"
  local result

  make_guard_repo "$project"
  HOME="$project-home" "$ROOT/scripts/agent-memory.sh" --repo "$project" append \
    --agent codex --text "prefer scripts/check.sh before done" >/dev/null

  # Memory is evidence consumed by later agents. A worker reports proposed
  # notes in its artifact; the owner decides what becomes shared state.
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$project" \
    "OMS_STATE_REPO=$project HOME=$project-home $ROOT/scripts/agent-memory.sh --repo $project append --agent codex --text 'worker note' >/dev/null")"
  [ "${result%%	*}" != 0 ] || fail "a worker appending shared memory should fail: $result"
  contains "$result" 'memory/shared.md' ||
    fail "the appended memory log should be named: $result"
  if contains "$result" 'shared-state: failures.jsonl'; then
    fail "parent failure bookkeeping must not be blamed on the memory-mutating worker: $result"
  fi
  if grep -Fq 'worker note' "$project/.oms/memory/shared.md"; then
    fail "the worker memory append should be rolled back"
  fi

  # Editing a note another agent wrote is how a worker would rewrite the record
  # the next session reads as fact.
  local edited="$TMP/guard-memory-edit"
  make_guard_repo "$edited"
  HOME="$edited-home" "$ROOT/scripts/agent-memory.sh" --repo "$edited" append \
    --agent codex --text "prefer scripts/check.sh before done" >/dev/null
  result="$(OMS_WORKER_AUTHORITY_EXCLUSIVE=1 run_guarded_worker "$edited" \
    "sed -i 's/prefer scripts/IGNORE scripts/' $edited/.oms/memory/shared.md")"
  [ "${result%%	*}" != 0 ] || fail "editing an existing memory note should fail the run: $result"
  contains "$result" 'memory/shared.md changed' ||
    fail "the violation should name shared.md and what happened: $result"
  if contains "$result" 'shared-state: failures.jsonl'; then
    fail "parent failure bookkeeping must stay outside the provider-window diff: $result"
  fi
  grep -Fq 'prefer scripts/check.sh' "$edited/.oms/memory/shared.md" ||
    fail "the edited memory note should be restored"
}

test_worker_guard_sees_an_edit_to_an_already_dirty_file() {
  local project="$TMP/guard-dirty"
  local result

  make_guard_repo "$project"
  # The user's own uncommitted work. git status says " M file.txt" before and
  # after a worker rewrites it, so status categories cannot see this at all.
  printf 'base\nEDITED BY USER\n' > "$project/file.txt"

  result="$(OMS_WORKER_GUARD_STRICT=1 run_guarded_worker "$project" \
    "printf 'base\nCLOBBERED BY WORKER\n' > $project/file.txt")"
  [ "${result%%	*}" != 0 ] ||
    fail "clobbering an already-dirty tracked file should fail a strict run: $result"
  contains "$result" 'outside its worktree: tracked' ||
    fail "the tracked surface should catch a content change, not just its status: $result"
}

# smoke-weight: 17
test_thread_appends_are_serialized() {
  local project="$TMP/thread-race"
  local i

  make_committed_repo "$project"
  "$ROOT/scripts/thread.sh" --repo "$project" new --id race >/dev/null

  # A consult panel appends answers concurrently; read-max-then-append without
  # a lock hands two writers the same sequence number.
  i=0
  while [ "$i" -lt 12 ]; do
    "$ROOT/scripts/thread.sh" --repo "$project" --id race append \
      --role note --text "turn $i" >/dev/null 2>&1 &
    i=$((i + 1))
  done
  wait

  python3 - "$project/.oms/threads/race.jsonl" <<'PY' || fail "concurrent appends must keep sequence numbers unique and contiguous"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1]) if line.strip()]
seqs = [r["seq"] for r in rows]
assert len(rows) == 12, len(rows)
assert sorted(seqs) == list(range(1, 13)), seqs
PY
}

test_thread_pointer_does_not_cross_tasks() {
  local project="$TMP/thread-owner"
  local first

  make_committed_repo "$project"
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "first task" >/dev/null )
  first="$("$ROOT/scripts/thread.sh" --repo "$project" new --topic "first" )"
  [ "$("$ROOT/scripts/thread.sh" --repo "$project" current)" = "$first" ] ||
    fail "the thread should be current for the task that opened it"
  # The owner check reads the first task_id, as the writer of CURRENT does.
  python3 - "$project/.oms/task/current.md" <<'PY'
import re, sys
path = sys.argv[1]
text = open(path, encoding="utf-8").read()
open(path, "w", encoding="utf-8").write(re.sub(r"(?m)^(- task_id:.*)$", r"\1\n- task_id: shadow", text, count=1))
PY
  [ "$("$ROOT/scripts/thread.sh" --repo "$project" current)" = "$first" ] ||
    fail "a second task_id line changed whose thread is current"
  # Special files are refused, never read: a FIFO would block every hook.
  if command -v mkfifo >/dev/null 2>&1 && command -v timeout >/dev/null 2>&1; then
    cp "$project/.oms/task/current.md" "$TMP/thread-owner-task.md"
    rm -f "$project/.oms/task/current.md"
    mkfifo "$project/.oms/task/current.md"
    timeout 5 python3 -c 'import sys; sys.path.insert(0, sys.argv[1]); import thread_live; thread_live.current_thread(sys.argv[2])' \
      "$ROOT/scripts/lib" "$project" || fail "a FIFO task file blocked the current-thread check"
    rm -f "$project/.oms/task/current.md"
    cp "$TMP/thread-owner-task.md" "$project/.oms/task/current.md"
    mv "$project/.oms/threads/CURRENT" "$TMP/thread-owner-current"
    mkfifo "$project/.oms/threads/CURRENT"
    if timeout 5 "$ROOT/scripts/thread.sh" --repo "$project" current >/dev/null 2>&1; then
      fail "a FIFO CURRENT counted as a current thread"
    fi
    rm -f "$project/.oms/threads/CURRENT"
    mv "$TMP/thread-owner-current" "$project/.oms/threads/CURRENT"
  fi

  # A different task must not inherit the previous task's conversation.
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" close --reason "moving on" >/dev/null )
  ( cd "$project" && "$ROOT/scripts/agent-task.sh" init --goal "second task" >/dev/null )
  if "$ROOT/scripts/thread.sh" --repo "$project" current >/dev/null 2>&1; then
    fail "a new task must not inherit the previous task's thread"
  fi
}

test_landing_refuses_to_apply_without_a_recorded_intent() {
  local project="$TMP/landing-failclosed"
  local patch="$TMP/landing-failclosed.patch"
  local rc=0
  local out

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  local bin="$TMP/intent-failure-bin"
  mkdir -p "$bin"
  export OMS_FIXTURE_REAL_PYTHON
  OMS_FIXTURE_REAL_PYTHON="$(command -v python3)"
  cat > "$bin/python3" <<'SH_INTENT'
#!/usr/bin/env bash
# Fail before opening the journal, only in the real native intent producer.
[ "${OMS_LD_EVENT:-}" != intent ] || exit 1
exec "$OMS_FIXTURE_REAL_PYTHON" "$@"
SH_INTENT
  chmod +x "$bin/python3"
  out="$(PATH="$bin:$PATH" "$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" --verify true 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "an unrecordable intent must not apply: $out"
  contains "$out" 'refusing to apply' || fail "the refusal should say why: $out"
  [ -z "$(git -C "$project" status --porcelain -- file.txt)" ] || fail "nothing should have been applied"
  python3 - "$ROOT" "$project" "$patch" "$TMP" <<'PY_INTENT' || fail "no-intent publication endpoint failed"
import hashlib, json, os, pathlib, runpy, subprocess, sys
root, repo, source, temporary = map(pathlib.Path, sys.argv[1:])
h = runpy.run_path(str(root / 'scripts/lib/landing-capture.py'))
e = runpy.run_path(str(root / 'scripts/lib/agent-events.py'))
patches = list((repo / '.oms/landing-patches').glob('*.patch'))
assert len(patches) == 1 and patches[0].read_bytes() == source.read_bytes()
rows = h['rows'](str(repo))
assert not any(r.get('event') in ('intent', 'complete', 'abandoned') for r in rows)
item = next(iter(h['reservations'](str(repo)).values()))
cert = h['certificate'](item)
assert cert['terminal']['reason'] == 'publication-without-intent'
assert cert['admission']['exit'] == 0
report = repo / cert['admission']['report']
report_before = report.read_bytes(); index = repo / '.oms/artifacts/index.jsonl'; index_before = index.read_bytes()
# A fresh actual local operation cannot adopt another genuine report, even
# for identical input bytes and the exact same retained private pathname.
reference = root / 'scripts/lib/landing-reference.py'
private = cert['objects']['capture']['path']
other_op = subprocess.check_output([sys.executable, str(reference), 'begin', str(repo), 'patch-admit', private], text=True).strip()
try:
    h['record_admission'](str(repo), private, other_op, str(report), '0')
except ValueError as error:
    assert 'scope' in str(error), error
else:
    raise AssertionError('another actual operation replayed a genuine admission report')
subprocess.run([sys.executable, str(reference), 'finish', str(repo), other_op, 'refuse-no-write'], check=True)
assert report.read_bytes() == report_before and index.read_bytes() == index_before
# Real recovery cannot invent a user task transition or delete this fresh file.
for _ in range(2):
    subprocess.run(['bash', str(root/'scripts/patch-land.sh'), '--repo', str(repo), '--recover'], check=True, stdout=subprocess.DEVNULL)
h['gc'](str(repo), 1, True)
assert patches[0].exists(), 'fresh no-intent publication removed immediately'
if os.name == 'nt':
    assert report.read_bytes() == report_before and index.read_bytes() == index_before
    raise SystemExit(0)  # Native ACL/quarantine deletion is explicitly unsupported.
clock = temporary / 'capture-age-clock'; clock.mkdir()
(clock/'sitecustomize.py').write_text('import time\n_native=time.time\ntime.time=lambda:_native()+172800\n')
env = dict(os.environ, PYTHONPATH=str(clock))
cmd = [sys.executable, str(root/'scripts/lib/landing-capture.py'), 'gc', str(repo), '1', '1']
live = e['create_attempt'](repo, provider='local', tool='capture-observer')
subprocess.run(cmd, env=env, check=True, stdout=subprocess.DEVNULL)
assert patches[0].exists(), 'live observer did not preserve aged publication'
e['append_lifecycle'](repo, e['new_event'](live,0,'attempt.state_changed',from_state=None,to_state='failed',reason_code='fixture-ended'))
pin = repo / '.oms/plan/pin.md'; pin.parent.mkdir(parents=True,exist_ok=True); pin.write_text(str(patches[0]))
subprocess.run(cmd, env=env, check=True, stdout=subprocess.DEVNULL)
assert patches[0].exists(), 'formal pin was mistaken for own admission trace'
pin.unlink()
subprocess.run(cmd, env=env, check=True, stdout=subprocess.DEVNULL)
assert not patches[0].exists() and not pathlib.Path(item['directory']).exists()
assert h['usage'](str(repo)) == (0, 0)
assert report.read_bytes() == report_before and index.read_bytes() == index_before
assert not any(r.get('event') in ('intent', 'complete', 'abandoned') for r in h['rows'](str(repo)))
assert source.read_bytes() and (repo/'file.txt').read_text() == 'base\n'
PY_INTENT
  unset OMS_FIXTURE_REAL_PYTHON

}

test_provider_permissions_grants_only_what_is_missing() {
  local dir="$TMP/provider-perms"
  local settings="$dir/settings.json"
  local bin="$dir/bin"
  local rc=0
  local out

  mkdir -p "$dir" "$bin"
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  chmod +x "$bin/agy"

  out="$(PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" \
    --apply --profile delegate --allow-command uv \
    --worktree-parent /tmp --settings "$settings" 2>&1)" ||
    fail "apply should succeed on a fresh settings file: $out"
  python3 - "$settings" <<'PY' || fail "apply must write exactly the profile's rules"
import json, sys
allow = json.load(open(sys.argv[1]))["permissions"]["allow"]
assert allow == ["read_file(*)", "command(*)",
                 "write_file(/tmp)", "unsandboxed(uv)"], allow
PY

  # Re-running must be a no-op, not a second copy of every rule.
  PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" --check --profile delegate \
    --allow-command uv --worktree-parent /tmp --settings "$settings" >/dev/null ||
    fail "a satisfied config should check clean"

  # A directory grant covers paths under it, so a narrower requirement is met.
  PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" --check --profile delegate \
    --worktree-parent /tmp/nested/deeper --settings "$settings" >/dev/null ||
    fail "write_file(/tmp) should already cover a directory beneath it"

  # An unrelated command is still missing, and the hint must carry the flag
  # that produced the finding.
  out="$(PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" --check --profile delegate \
    --allow-command npm --worktree-parent /tmp --settings "$settings" 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "a missing unsandboxed grant should not check clean: $out"
  contains "$out" '--allow-command npm' ||
    fail "following the hint must grant what was reported: $out"

  # The sandbox boundary is not something to hand over with one flag.
  rc=0
  out="$(PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" --check --profile delegate \
    --allow-command '*' --settings "$settings" 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "a wildcard sandbox escape should be refused: $out"

  # Refuse before creating a worktree, artifact, or running a verifier.
  local project="$dir/repo" mode preflight_rc
  make_committed_repo "$project"
  for mode in normal interactive malformed; do
    mkdir -p "$dir/empty-home"
    if [ "$mode" = malformed ]; then printf '{broken\n' > "$dir/bad.json"; fi
    preflight_rc=0
    if [ "$mode" = interactive ]; then
      PATH="$bin:$PATH" HOME="$dir/empty-home" XDG_CACHE_HOME="$dir/cache" \
        OMS_ANTIGRAVITY_SETTINGS="$dir/bad.json" OMS_DELEGATE_WORKTREE_ROOT="$dir/worktrees" \
        "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to antigravity \
        --prompt test --interactive >"$dir/stdout" 2>"$dir/stderr" || preflight_rc=$?
    else
      PATH="$bin:$PATH" HOME="$dir/empty-home" XDG_CACHE_HOME="$dir/cache" \
        OMS_ANTIGRAVITY_SETTINGS="$dir/bad.json" OMS_DELEGATE_WORKTREE_ROOT="$dir/worktrees" \
        "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to antigravity \
        --prompt test --verify "touch $dir/verified" --repair 2 >"$dir/stdout" 2>"$dir/stderr" || preflight_rc=$?
    fi
    [ "$preflight_rc" = 2 ] || fail "delegate preflight must exit 2 ($mode): $preflight_rc"
    grep -Fq 'oms provider-permissions --apply --profile delegate' "$dir/stderr" ||
      fail "delegate preflight must print its remedy ($mode)"
    [ ! -e "$dir/worktrees" ] && [ ! -e "$dir/verified" ] && [ ! -e "$project/.oms" ] ||
      fail "delegate preflight changed state ($mode)"
  done
  mkdir -p "$dir/empty-home/.local/bin"
  cp "$bin/agy" "$dir/empty-home/.local/bin/agy"
  preflight_rc=0
  PATH="/usr/bin:/bin" HOME="$dir/empty-home" XDG_CACHE_HOME="$dir/cache" \
    OMS_ANTIGRAVITY_SETTINGS="$dir/bad.json" OMS_DELEGATE_WORKTREE_ROOT="$dir/worktrees" \
    "$ROOT/scripts/peer-delegate.sh" --repo "$project" --to antigravity \
    --prompt test --no-verify >"$dir/stdout" 2>"$dir/stderr" || preflight_rc=$?
  [ "$preflight_rc" = 2 ] || fail "preflight missed provider in user-local bin"
  grep -Fq 'oms provider-permissions --apply --profile delegate' "$dir/stderr" ||
    fail "user-local provider refusal did not name its remedy"
  # Exercise the provider-install wrapper without downloading a CLI.
  (
    set --
    . "$ROOT/scripts/install-tools.sh"
    install_antigravity_impl() { return 0; }
    export PATH="$bin:$PATH" OMS_DELEGATE_WORKTREE_ROOT="$dir/worktrees"
    export OMS_ANTIGRAVITY_SETTINGS="$dir/install-settings.json"
    printf '{broken\n' > "$OMS_ANTIGRAVITY_SETTINGS"
    install_antigravity > "$dir/install-out" 2>&1 || exit 1
    grep -Fq 'oms provider-permissions --apply --profile delegate --allow-toolchains' "$dir/install-out" || exit 2
    grep -Fxq '{broken' "$OMS_ANTIGRAVITY_SETTINGS" || exit 3
    printf '%s\n' '{}' > "$OMS_ANTIGRAVITY_SETTINGS"
    OH_MY_SETTING_PEER_PERMISSIONS=0 install_antigravity > "$dir/install-out" 2>&1 || exit 4
    grep -Fxq '{}' "$OMS_ANTIGRAVITY_SETTINGS" || exit 5
    install_antigravity > "$dir/install-out" 2>&1 || exit 6
    "$ROOT/scripts/provider-permissions.sh" --check --profile delegate --allow-toolchains >/dev/null || exit 7
  ) || fail "provider install permission handling failed"

}

test_peer_delegate_uses_managed_private_worktree_root() {
  local project="$TMP/delegate-private-root"
  local home_dir="$TMP/delegate-private-home"
  local cache_dir="$TMP/delegate-private-cache"
  local managed_root="$cache_dir/oh-my-setting/worktrees"
  local out worktree worktree_parent

  make_committed_repo "$project"
  mkdir -p "$home_dir" "$cache_dir"
  out="$(HOME="$home_dir" XDG_CACHE_HOME="$cache_dir" \
    OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --repo "$project" --to codex --prompt 'private root regression' \
      --no-verify --keep-worktree 2>&1)" ||
    fail "delegate dry-run should create an inspectable worktree: $out"
  worktree="$(printf '%s\n' "$out" | sed -n 's/^worktree kept: //p' | tail -n 1)"
  [ -n "$worktree" ] || fail "delegate did not report its kept worktree: $out"
  case "$worktree" in
    "$managed_root"/*/wt-*) ;;
    *) fail "delegate worktree escaped the managed root: $worktree" ;;
  esac
  [ -d "$managed_root" ] && [ ! -L "$managed_root" ] ||
    fail "managed delegate root must be a real directory"
  python3 - "$managed_root" <<'PY' || fail "managed delegate root must be mode 0700"
import os, stat, sys
assert stat.S_IMODE(os.stat(sys.argv[1]).st_mode) == 0o700
PY

  case "$out" in *"commits behind"*) fail "current HEAD must not warn: $out" ;; esac

  worktree_parent="$(dirname "$worktree")"
  git -C "$project" worktree remove --force "$worktree" >/dev/null 2>&1 ||
    fail "could not clean the kept delegate worktree"
  rm -rf "$worktree_parent"

  # A shared checkout two commits behind the known remote default is a strict
  # ancestor: warn on stderr and in the artifact, without moving any ref.
  local base_sha artifact
  base_sha="$(git -C "$project" rev-parse HEAD)"
  printf 'two\n' >> "$project/file.txt"
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' commit -qam two
  printf 'three\n' >> "$project/file.txt"
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' commit -qam three
  git -C "$project" update-ref refs/remotes/origin/main HEAD
  git -C "$project" symbolic-ref refs/remotes/origin/HEAD refs/remotes/origin/main
  git -C "$project" reset -q --hard "$base_sha"
  out="$(HOME="$home_dir" XDG_CACHE_HOME="$cache_dir" \
    OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --repo "$project" --to codex --prompt 'stale base regression' \
      --no-verify 2>&1)" || fail "stale-base dry-run failed: $out"
  case "$out" in *"2 commits behind origin/main (strict ancestor)"*) ;; *) fail "stale base must warn: $out" ;; esac
  artifact="$(printf '%s\n' "$out" | sed -n 's/^dry-run: codex -> //p' | tail -n 1)"
  grep -q '2 commits behind origin/main' "$artifact" || fail "stale-base warning missing from artifact"
  grep '2 commits behind origin/main' "$artifact" | grep "$project" > /dev/null &&
    fail "stale-base artifact line must not embed the repository path"
  [ "$(git -C "$project" rev-parse HEAD)" = "$base_sha" ] || fail "warning must not move HEAD"
  # Without upstream or origin/HEAD, origin/main still names the default.
  git -C "$project" symbolic-ref --delete refs/remotes/origin/HEAD
  out="$(HOME="$home_dir" XDG_CACHE_HOME="$cache_dir" \
    OH_MY_SETTING_DELEGATE_DRY_RUN=1 "$ROOT/scripts/peer-delegate.sh" \
      --repo "$project" --to codex --prompt 'stale base without origin HEAD' \
      --no-verify 2>&1)" || fail "stale-base dry-run without origin/HEAD failed: $out"
  case "$out" in *"2 commits behind origin/main (strict ancestor)"*) ;; *) fail "stale base without origin/HEAD must warn: $out" ;; esac
}

test_provider_permissions_apply_preserves_a_concurrent_settings_edit() {
  local dir="$TMP/provider-perms-apply-cas"
  local settings="$dir/settings.json"
  local managed="$settings.oh-my-setting-permissions.json"
  local bin="$dir/bin"
  local pythonpath="$dir/pythonpath"
  local ready="$dir/backup-copy-ready"
  local continue="$dir/backup-copy-continue"
  local out="$dir/apply.out"
  local pid rc=0 attempts=0

  mkdir -p "$bin" "$pythonpath"
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  chmod +x "$bin/agy"
  cat > "$settings" <<'EOF'
{
  "theme": "user-before",
  "permissions": {
    "allow": ["read_file(*)", "user(existing)"]
  }
}
EOF

  # Pause the standard-library backup copy after apply has read its snapshot.
  # This is process-local dependency injection: production code gets no test
  # hook, while the fixture can deterministically land a concurrent edit in
  # the old read -> write gap.
  cat > "$pythonpath/shutil.py" <<'PY'
import os
import time


def rmtree(path, ignore_errors=False, onerror=None):
    # tempfile only captures this symbol while provider-permissions uses
    # mkstemp; no temporary-directory cleanup runs in this fixture.
    raise AssertionError("unexpected shutil.rmtree call: %s" % path)


def copyfileobj(source, target, length=1024 * 1024):
    ready = os.environ["OMS_TEST_PP_COPY_READY"]
    proceed = os.environ["OMS_TEST_PP_COPY_CONTINUE"]
    with open(ready, "w", encoding="utf-8") as handle:
        handle.write("ready\n")
    deadline = time.time() + 10
    while not os.path.exists(proceed):
        if time.time() >= deadline:
            raise RuntimeError("timed out waiting for concurrent edit")
        time.sleep(0.01)
    while True:
        chunk = source.read(length)
        if not chunk:
            return
        target.write(chunk)
PY

  env PYTHONPATH="$pythonpath" OMS_TEST_PP_COPY_READY="$ready" \
    OMS_TEST_PP_COPY_CONTINUE="$continue" PATH="$bin:$PATH" \
    "$ROOT/scripts/provider-permissions.sh" --apply --profile consult \
    --settings "$settings" >"$out" 2>&1 &
  pid=$!
  while [ ! -e "$ready" ] && kill -0 "$pid" 2>/dev/null; do
    attempts=$((attempts + 1))
    [ "$attempts" -lt 500 ] || break
    sleep 0.01
  done
  if [ ! -e "$ready" ]; then
    : > "$continue"
    wait "$pid" || true
    fail "permission apply did not reach the concurrent-edit boundary: $(cat "$out")"
  fi

  PYTHONPATH='' python3 - "$settings" <<'PY'
import json
import os
import sys
import tempfile

path = sys.argv[1]
with open(path, encoding="utf-8") as handle:
    cfg = json.load(handle)
cfg["theme"] = "user-during-apply"
cfg["permissions"]["allow"].append("user(during-apply)")
fd, temporary = tempfile.mkstemp(prefix=".concurrent-settings.",
                                 dir=os.path.dirname(path))
try:
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        json.dump(cfg, handle, indent=2)
        handle.write("\n")
    os.replace(temporary, path)
finally:
    try:
        os.unlink(temporary)
    except FileNotFoundError:
        pass
PY
  : > "$continue"
  wait "$pid" || rc=$?

  [ "$rc" -ne 0 ] || fail "permission apply overwrote a concurrent settings edit"
  grep -Fq 'settings changed during permission apply' "$out" ||
    fail "concurrent permission refusal was not explained: $(cat "$out")"
  python3 - "$settings" <<'PY' || fail "concurrent permission edit was not preserved"
import json
import sys

cfg = json.load(open(sys.argv[1], encoding="utf-8"))
assert cfg["theme"] == "user-during-apply", cfg
assert cfg["permissions"]["allow"] == [
    "read_file(*)", "user(existing)", "user(during-apply)"
], cfg
PY
  [ ! -e "$managed" ] ||
    fail "failed permission apply claimed ownership it did not grant"
}

test_provider_permissions_tracks_and_revokes_only_managed_rules() {
  local dir="$TMP/provider-perms-managed"
  local settings="$dir/settings.json"
  local managed="$settings.oh-my-setting-permissions.json"
  local bin="$dir/bin"
  local before after out rc=0 victim victim_before

  mkdir -p "$bin"
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  chmod +x "$bin/agy"
  # Interrupt the ownership write and ensure no user rule is claimed.
  mkdir -p "$dir/inject"
  cat > "$dir/inject/sitecustomize.py" <<'PY_INTERRUPT'
import os
original_replace = os.replace
def interrupt(source, target, *args, **kwargs):
    if str(target).endswith('.oh-my-setting-permissions.json'):
        raise OSError('simulated interrupted ownership write')
    return original_replace(source, target, *args, **kwargs)
os.replace = interrupt
PY_INTERRUPT
  printf '%s\n' '{"permissions":{"allow":["read_file(*)"]}}' > "$dir/interrupted.json"
  if PATH="$bin:$PATH" PYTHONPATH="$dir/inject" "$ROOT/scripts/provider-permissions.sh" \
    --apply --profile consult --settings "$dir/interrupted.json" > /dev/null 2>&1; then
    fail "interrupted ownership write should fail"
  fi
  [ ! -e "$dir/interrupted.json.oh-my-setting-permissions.json" ] ||
    fail "interrupted apply recorded rules it did not safely own"
  python3 - "$dir/interrupted.json" <<'PY_INTERRUPT_CHECK' || fail "interrupted apply lost settings"
import json, sys
assert json.load(open(sys.argv[1]))['permissions']['allow'] == ['read_file(*)', 'command(*)']
PY_INTERRUPT_CHECK
  cat > "$settings" <<'EOF'
{
  "theme": "user-before",
  "permissions": {
    "allow": ["read_file(*)", "user(existing)"]
  }
}
EOF

  for help_command in \
      "$ROOT/install.sh --help" \
      "$ROOT/scripts/provider-permissions.sh --help"; do
    out="$(bash -c "$help_command")" || fail "permission help failed: $help_command"
    for rule in 'read_file(*)' 'command(*)'; do
      contains "$out" "$rule" ||
        fail "permission consent omitted $rule: $help_command"
    done
    if contains "$out" 'mcp(*)'; then
      fail "permission consent must not advertise an all-MCP grant: $help_command"
    fi
  done

  PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" \
    --apply --profile consult --settings "$settings" >/dev/null ||
    fail "managed consult permission apply failed"
  python3 - "$settings" "$managed" <<'PY' || fail "permission ownership was recorded incorrectly"
import json, sys
settings, managed = sys.argv[1:]
cfg = json.load(open(settings, encoding="utf-8"))
assert cfg["theme"] == "user-before", cfg
assert cfg["permissions"]["allow"] == [
    "read_file(*)", "user(existing)", "command(*)"
], cfg
state = json.load(open(managed, encoding="utf-8"))
assert state == {"schema": 1, "rules": ["command(*)"]}, state
backup = json.load(open(settings + ".bak", encoding="utf-8"))
assert backup["permissions"]["allow"] == ["read_file(*)", "user(existing)"], backup
PY

  # Changes after installation are user-owned. A duplicate of one managed rule
  # represents a later user grant; removal may consume only the occurrence the
  # sidecar owns, not every equal string in the list.
  python3 - "$settings" <<'PY'
import json, sys
path = sys.argv[1]
cfg = json.load(open(path, encoding="utf-8"))
cfg["theme"] = "user-after"
cfg["permissions"]["allow"].extend(["user(after)", "command(*)"])
with open(path, "w", encoding="utf-8") as handle:
    json.dump(cfg, handle, indent=2)
    handle.write("\n")
PY

  PATH="$bin:$PATH" "$ROOT/scripts/provider-permissions.sh" \
    --apply --profile consult --settings "$settings" >/dev/null ||
    fail "repeated permission apply should be idempotent"
  python3 - "$settings.bak" <<'PY' || fail "repeat apply overwrote the original backup"
import json, sys
cfg = json.load(open(sys.argv[1], encoding="utf-8"))
assert cfg["theme"] == "user-before", cfg
assert "user(after)" not in cfg["permissions"]["allow"], cfg
PY

  # Removal is local JSON surgery and must work even when agy is no longer on
  # PATH. It removes only sidecar-owned occurrences and then deletes the sidecar.
  PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
    --remove --settings "$settings" >/dev/null ||
    fail "managed permission removal failed without agy"
  [ ! -e "$managed" ] || fail "managed permission sidecar survived removal"
  python3 - "$settings" <<'PY' || fail "permission removal overwrote user rules"
import json, sys
cfg = json.load(open(sys.argv[1], encoding="utf-8"))
assert cfg["theme"] == "user-after", cfg
assert cfg["permissions"]["allow"] == [
    "read_file(*)", "user(existing)", "user(after)", "command(*)"
], cfg
PY

  before="$(cksum < "$settings")"
  PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
    --remove --settings "$settings" >/dev/null ||
    fail "repeated permission removal should be idempotent"
  after="$(cksum < "$settings")"
  [ "$before" = "$after" ] || fail "idempotent removal rewrote user settings"

  printf '{not-json\n' > "$managed"
  before="$(cksum < "$settings")"
  rc=0
  out="$(PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
    --remove --settings "$settings" 2>&1)" || rc=$?
  [ "$rc" -ne 0 ] || fail "invalid permission ownership state was ignored"
  after="$(cksum < "$settings")"
  [ "$before" = "$after" ] || fail "failed permission removal mutated settings"
  contains "$out" 'managed permission state' ||
    fail "invalid permission ownership failure was not explained: $out"
  rm -f "$managed"

  # Ownership metadata is privileged input: following a planted sidecar
  # symlink could otherwise turn uninstall into an arbitrary-file rewriter.
  victim="$dir/user-owned.json"
  printf '%s\n' '{"schema":1,"rules":["command(*)"]}' > "$victim"
  if ln -s "$victim" "$managed" 2>/dev/null; then
    before="$(cksum < "$settings")"
    victim_before="$(cksum < "$victim")"
    rc=0
    out="$(PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
      --remove --settings "$settings" 2>&1)" || rc=$?
    [ "$rc" -ne 0 ] || fail "a symbolic-link ownership sidecar was trusted"
    [ "$before" = "$(cksum < "$settings")" ] ||
      fail "symbolic-link ownership failure mutated settings"
    [ "$victim_before" = "$(cksum < "$victim")" ] ||
      fail "symbolic-link ownership failure mutated its target"
    contains "$out" 'symbolic link' ||
      fail "symbolic-link ownership refusal was not explained: $out"
    rm -f "$managed" "$victim"
  fi

  python3 - "$managed" <<'PY'
import json
import sys

with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump({
        "schema": 1,
        "rules": ["command(*)"],
        "removal": {
            "before_sha256": "0" * 64,
            "after_sha256": "1" * 64,
        },
    }, handle)
PY
  before="$(cksum < "$settings")"
  rc=0
  out="$(PATH="/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" \
    --remove --settings "$settings" 2>&1)" || rc=$?
  [ "$rc" -ne 0 ] || fail "a stale permission-removal journal was replayed"
  [ "$before" = "$(cksum < "$settings")" ] ||
    fail "stale permission-removal journal overwrote concurrent user edits"
  [ -f "$managed" ] || fail "failed permission-removal retry lost ownership state"
  contains "$out" 'settings changed' ||
    fail "stale permission-removal journal failure was not explained: $out"
  rm -f "$managed"
}

test_provider_permissions_toolchains_follow_the_machine() {
  local dir="$TMP/provider-perms-toolchains"
  local settings="$dir/settings.json"
  local bin="$dir/bin"
  local out

  # Only tools this machine actually has: an escape granted to something that
  # is not installed buys nothing and outlives the reason it was added.
  mkdir -p "$dir" "$bin"
  printf '#!/bin/sh\nexit 0\n' > "$bin/agy"
  printf '#!/bin/sh\nexit 0\n' > "$bin/npm"
  chmod +x "$bin/agy" "$bin/npm"

  out="$(PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" --print \
    --profile delegate --allow-toolchains --worktree-parent /tmp --settings "$settings" 2>&1)" ||
    fail "print should succeed: $out"
  printf '%s\n' "$out" | grep >/dev/null -Fx 'unsandboxed(npm)' ||
    fail "an installed package manager should be granted: $out"
  if printf '%s\n' "$out" | grep >/dev/null -Fx 'unsandboxed(cargo)'; then
    fail "cargo is not on this PATH and must not be granted: $out"
  fi
  # Tools that write in-tree, contradict the uv policy, or hold root-equivalent
  # access are out of the list regardless of being installed.
  for excluded in pip conda docker make node git; do
    if printf '%s\n' "$out" | grep >/dev/null -Fx "unsandboxed($excluded)"; then
      fail "$excluded must not be granted by --allow-toolchains: $out"
    fi
  done
}

test_provider_permissions_leaves_flag_driven_providers_alone() {
  local dir="$TMP/provider-perms-none"
  local bin="$dir/bin"
  local out

  # No agy on PATH: codex and claude carry authority per invocation, so there
  # is nothing standing to grant and the check must not invent work.
  mkdir -p "$dir" "$bin"
  out="$(PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/provider-permissions.sh" --check 2>&1)" ||
    fail "no antigravity means nothing to do: $out"
  contains "$out" 'not installed' || fail "should say why there is nothing to do: $out"
}

test_worker_guard_spends_its_budget_on_untracked_before_ignored() {
  local project="$TMP/guard-budget-order"
  local snap="$TMP/guard-budget-order-snap"
  local i
  local changed
  local files_line

  make_committed_repo "$project"
  printf 'junk/\n' > "$project/.gitignore"
  git -C "$project" add .gitignore
  git -C "$project" -c user.email=t@t -c user.name=t commit -qm "ignore junk"
  # A real ML repo: an ignored tree with far more files than the budget, and a
  # couple of genuinely new source files whose paths sort after it.
  mkdir -p "$project/junk"
  i=0
  while [ "$i" -lt 30 ]; do
    printf 'x\n' > "$project/junk/blob$i.bin"
    i=$((i + 1))
  done
  printf 'new\n' > "$project/zz_new_source.py"

  rm -rf "$snap"
  ( . "$ROOT/scripts/lib/oms-common.sh"
    OMS_WORKER_GUARD_MAX_FILES=5 oms_worker_surface_snapshot "$project" "$snap" ) ||
    fail "snapshot failed"
  files_line="$(grep '^TRUNCATED' "$snap/files" || true)"
  case "$files_line" in
    *"(ignored)"*) ;;
    *) fail "truncation should land in the ignored class, got: ${files_line:-<none>}" ;;
  esac

  # The point of the ordering: a stray write to an untracked source file is
  # still caught, even though the scan stopped early.
  printf 'new\nWORKER WROTE HERE\n' > "$project/zz_new_source.py"
  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    OMS_WORKER_GUARD_MAX_FILES=5 oms_worker_surface_diff "$project" "$snap" )"
  case "$changed" in
    *files*) ;;
    *) fail "a change to an untracked source file must survive truncation, got: ${changed:-<none>}" ;;
  esac
}

# smoke-weight: 41
test_worker_guard_splits_remote_tracking_and_stash_refs() {
  local project="$TMP/guard-remote-refs"
  local snap="$TMP/guard-remote-refs-snap"
  local changed

  make_committed_repo "$project"

  rm -rf "$snap"
  ( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_snapshot "$project" "$snap" ) ||
    fail "remote-ref snapshot failed"
  git -C "$project" update-ref refs/remotes/origin/main \
    "$(git -C "$project" rev-parse HEAD)"
  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_diff "$project" "$snap" )"
  [ "$changed" = "remote-refs" ] ||
    fail "a remote-tracking ref should change only remote-refs, got: ${changed:-<none>}"

  rm -rf "$snap"
  ( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_snapshot "$project" "$snap" ) ||
    fail "stash snapshot failed"
  git -C "$project" update-ref refs/stash "$(git -C "$project" rev-parse HEAD)"
  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_diff "$project" "$snap" )"
  [ "$changed" = "remote-refs" ] ||
    fail "stash should change only remote-refs, got: ${changed:-<none>}"

  # The Codex app writes turn-diff refs on every turn in the shared repository;
  # a branch merely named codex/ stays on the hard surface.
  rm -rf "$snap"
  ( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_snapshot "$project" "$snap" ) ||
    fail "codex-ref snapshot failed"
  git -C "$project" update-ref refs/codex/turn-diffs/captures/1/base \
    "$(git -C "$project" rev-parse 'HEAD^{tree}')"
  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_diff "$project" "$snap" )"
  [ "$changed" = "remote-refs" ] ||
    fail "a Codex turn-diff ref should change only remote-refs, got: ${changed:-<none>}"
  git -C "$project" update-ref refs/heads/codex/x "$(git -C "$project" rev-parse HEAD)"
  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_diff "$project" "$snap" )"
  [ "$changed" = "refs, remote-refs" ] ||
    fail "a codex/ branch must stay a hard ref change, got: ${changed:-<none>}"

  # Namespace alone is not evidence of foreign ownership; creating an oms/*
  # branch remains hard, as does moving the checked-out branch.
  rm -rf "$snap"
  ( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_snapshot "$project" "$snap" ) ||
    fail "work-branch snapshot failed"
  git -C "$project" update-ref refs/heads/oms/other-main "$(git -C "$project" rev-parse HEAD)"
  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_diff "$project" "$snap" )"
  [ "$changed" = "refs" ] ||
    fail "an unproven oms/ branch write must stay hard, got: ${changed:-<none>}"
  git -C "$project" checkout -q oms/other-main
  rm -rf "$snap"
  ( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_snapshot "$project" "$snap" ) ||
    fail "current-branch snapshot failed"
  git -C "$project" update-ref refs/heads/oms/other-main \
    "$(git -C "$project" commit-tree -p HEAD -m next 'HEAD^{tree}')"
  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    oms_worker_surface_diff "$project" "$snap" )"
  [ "$changed" = "refs" ] ||
    fail "the checked-out oms/ branch must stay a hard ref change, got: ${changed:-<none>}"

  # Panel reads keep state in this repo while executing in another checkout.
  # Both sides tolerate evidence-backed foreign moves, including shared Git
  # metadata, while the source checkout's own surfaces remain protected.
  local read_source="$TMP/guard-read-source"
  local other_main="$TMP/guard-read-other-main"
  make_committed_repo "$read_source"
  git -C "$project" checkout -q main
  git -C "$project" worktree add -q "$other_main" oms/other-main
  (
    . "$ROOT/scripts/lib/peer-common.sh"
    REPO="$project" MA_READ_SOURCE_REPO="$read_source"
    local strict next out rc
    for strict in 0 1; do
      ma_read_guard_begin "$snap/read-$strict" || fail "cross-repo read snapshot failed"
      next="$(git -C "$other_main" commit-tree -p HEAD -m read-move 'HEAD^{tree}')"
      git -C "$other_main" reset -q --hard "$next"
      rc=0
      out="$(OMS_WORKER_GUARD_STRICT="$strict" ma_read_guard_assert 2>&1)" || rc=$?
      if [ "$strict" = 0 ]; then
        [ "$rc" = 0 ] || fail "foreign oms branch move stopped a cross-repo read: $out"
        ! contains "$out" 'read pass observed state repository changes: foreign-ref;' || fail "read foreign-ref should be quiet: $out"
      else
        [ "$rc" = 2 ] || fail "strict read tolerated a foreign ref move: $out"
        contains "$out" 'state repository protected surfaces: refs' || fail "strict read refs not hard: $out"
      fi
    done
    local read_managed_root="$TMP/guard-read-created-root"
    local created_read="$read_managed_root/foreign/wt"
    mkdir -p "${created_read%/wt}"
    OMS_DELEGATE_WORKTREE_ROOT="$read_managed_root"
    for strict in 0 1; do
      ma_read_guard_begin "$snap/read-created-$strict" || fail "read branch-create snapshot failed"
      git -C "$project" worktree add -q --detach "$created_read" HEAD
      git -C "$created_read" checkout -q --no-track -b oms/read-created
      rc=0
      out="$(OMS_WORKER_GUARD_STRICT="$strict" ma_read_guard_assert 2>&1)" || rc=$?
      if [ "$strict" = 0 ]; then
        [ "$rc" = 0 ] || fail "foreign oms branch creation stopped a read: $out"
        ! contains "$out" 'read pass observed state repository changes: foreign-ref;' || fail "read foreign-ref should be quiet: $out"
      else
        [ "$rc" = 2 ] || fail "strict read tolerated foreign oms branch creation: $out"
        contains "$out" 'state repository protected surfaces: refs' || fail "strict read branch-create refs not hard: $out"
      fi
      git -C "$project" worktree remove -f "$created_read"
      git -C "$project" branch -D oms/read-created >/dev/null
    done
    ma_read_guard_begin "$snap/read-unattributed" || fail "read ref attribution snapshot failed"
    next="$(git -C "$other_main" rev-parse HEAD~1)"
    git -C "$project" update-ref refs/heads/oms/other-main "$next"
    rc=0
    out="$(ma_read_guard_assert 2>&1)" || rc=$?
    [ "$rc" = 2 ] || fail "read guard softened a branch write without foreign HEAD evidence: $out"
    contains "$out" 'ref refs/heads/oms/other-main' ||
      fail "a read-guard refs stop should name the changed ref: $out"
    ma_read_guard_begin "$snap/read-source" || fail "read source protection snapshot failed"
    printf 'source mutation\n' >> "$read_source/file.txt"
    rc=0
    out="$(ma_read_guard_assert 2>&1)" || rc=$?
    [ "$rc" = 2 ] || fail "cross-repo read source tracked changes must stay hard: $out"
    contains "$out" 'source repository protected surfaces: tracked' || fail "read source violation was not named: $out"

    # A live managed source must not be mistaken for an exempt sibling.
    local managed_root="$TMP/guard-read-managed"
    local linked_source="$managed_root/oh-my-setting-scratch.source/wt"
    local extra="$TMP/guard-read-extra" action changed
    make_live_managed_sibling "$project" "${linked_source%/wt}"
    git -C "$linked_source" checkout -qb oms/read-source
    # Read by the sourced read-guard helpers.
    # shellcheck disable=SC2034
    OMS_DELEGATE_WORKTREE_ROOT="$managed_root"
    MA_READ_SOURCE_REPO="$linked_source"
    for strict in 0 1; do
      ma_read_guard_begin "$snap/read-linked-$strict" || fail "linked read snapshot failed"
      ma_read_guard_rebaseline_source || fail "linked read rebaseline failed"
      next="$(git -C "$other_main" commit-tree -p HEAD -m linked-read-move 'HEAD^{tree}')"
      git -C "$other_main" reset -q --hard "$next"
      rc=0
      out="$(OMS_WORKER_GUARD_STRICT="$strict" ma_read_guard_assert 2>&1)" || rc=$?
      if [ "$strict" = 0 ]; then
        [ "$rc" = 0 ] || fail "foreign oms move stopped a linked read: $out"
        ! contains "$out" 'read pass observed state repository changes: foreign-ref;' || fail "linked state foreign-ref should be quiet: $out"
        ! contains "$out" 'read pass observed source repository changes: foreign-ref;' || fail "linked source foreign-ref should be quiet: $out"
      else
        [ "$rc" = 2 ] || fail "strict linked read tolerated a foreign ref move: $out"
      fi
    done
    for action in add remove; do
      ma_read_guard_begin "$snap/read-linked-$action" || fail "linked lifecycle snapshot failed"
      if [ "$action" = add ]; then
        git -C "$project" worktree add -q --detach "$extra" HEAD
      else
        git -C "$project" worktree remove "$extra"
      fi
      rc=0
      out="$(ma_read_guard_assert 2>&1)" || rc=$?
      [ "$rc" = 0 ] || fail "foreign worktree $action stopped a linked read: $out"
      contains "$out" 'source repository changes: foreign-worktree' || fail "linked lifecycle warning missing: $out"
    done
    ma_read_guard_begin "$snap/read-linked-own-branch" || fail "own source branch snapshot failed"
    next="$(git -C "$linked_source" commit-tree -p HEAD -m own-source-move 'HEAD^{tree}')"
    git -C "$linked_source" reset -q --hard "$next"
    changed="$(oms_worker_surface_diff "$linked_source" "$MA_READ_GUARD_DIR/source" "" "$linked_source")"
    [ "$changed" = refs ] || fail "source's own branch must remain a hard ref: $changed"
    rc=0
    out="$(ma_read_guard_assert 2>&1)" || rc=$?
    [ "$rc" = 2 ] || fail "linked read tolerated its own source branch move: $out"
    ma_read_guard_begin "$snap/read-linked-own-head" || fail "own source HEAD snapshot failed"
    git -C "$linked_source" checkout -q --detach HEAD
    changed="$(oms_worker_surface_diff "$linked_source" "$MA_READ_GUARD_DIR/source" "" "$linked_source")"
    [ "$changed" = 'refs, gitmeta' ] || fail "live source HEAD identity must remain hard: $changed"
    rc=0
    out="$(ma_read_guard_assert 2>&1)" || rc=$?
    [ "$rc" = 2 ] || fail "linked read tolerated its own source HEAD change: $out"
    contains "$out" 'source repository protected surface: HEAD' ||
      fail "shared source HEAD mutation lost its specific diagnostic: $out"
    ma_read_guard_begin "$snap/read-linked-tracked" || fail "linked source content snapshot failed"
    printf 'linked source mutation\n' >> "$linked_source/file.txt"
    rc=0
    out="$(ma_read_guard_assert 2>&1)" || rc=$?
    [ "$rc" = 2 ] || fail "linked source tracked mutation must stay hard: $out"
    contains "$out" 'source repository protected surfaces: tracked' || fail "linked source content violation was not named: $out"
    ma_read_guard_begin "$snap/read-linked-untracked" || fail "linked source untracked snapshot failed"
    printf 'new linked source file\n' > "$linked_source/read-guard-diagnostic.txt"
    rc=0
    out="$(ma_read_guard_assert 2>&1)" || rc=$?
    [ "$rc" = 2 ] || fail "linked source untracked mutation must stay hard: $out"
    contains "$out" 'source repository protected surfaces: files' || fail "linked source untracked violation was not named: $out"
    contains "$out" 'read-guard-diagnostic.txt' || fail "linked source files diagnostic omitted changed path: $out"
    # Volatile presence families vanish under a read pass without failing it;
    # authority state still fails and the message names the file.
    local vol_case
    MA_READ_SOURCE_REPO="$read_source"
    mkdir -p "$project/.oms/hooks/sessions" "$project/.oms/hooks/panel-activity" "$project/.oms/plan"
    printf '{}\n' > "$project/.oms/hooks/sessions/sess-a.json"
    printf '{}\n' > "$project/.oms/hooks/panel-activity/att_read.json"
    printf '{}\n' > "$project/.oms/plan/tasks.json"
    printf 'row\n' > "$project/.oms/failures.jsonl"
    mkdir -p "$project/.oms/runtime/context" "$project/.oms/tick"
    printf 'row\n' > "$project/.oms/runtime/outcomes.jsonl"
    printf 'row\n' > "$project/.oms/tick/history.jsonl"
    printf '{}\n' > "$project/.oms/runtime/context/pack.json"
    ma_read_guard_begin "$snap/read-volatile-context" || fail "volatile context snapshot failed"
    rm -f "$project/.oms/runtime/context/pack.json"
    rc=0
    out="$(ma_read_guard_assert 2>&1)" || rc=$?
    [ "$rc" = 0 ] || fail "deleted runtime/context cache failed a read pass: $out"
    mkdir -p "$project/.oms/runtime/logs"
    for vol_case in runtime/logs/oms-exec.ab12_x9z runtime/.outcomes.jsonl.q1w2e3r4; do
      printf 'tmp\n' > "$project/.oms/$vol_case"
      ma_read_guard_begin "$snap/read-temp-${vol_case//\//-}" || fail "runtime temp snapshot failed"
      rm -f "$project/.oms/$vol_case"
      printf 'tmp\n' > "$project/.oms/runtime/logs/oms-exec.new0_tmp"
      rc=0
      out="$(ma_read_guard_assert 2>&1)" || rc=$?
      rm -f "$project/.oms/runtime/logs/oms-exec.new0_tmp"
      [ "$rc" = 0 ] || fail "writer temp $vol_case failed a read pass: $out"
    done
    for vol_case in sessions/sess-a.json panel-activity/att_read.json; do
      ma_read_guard_begin "$snap/read-volatile-${vol_case%%/*}" || fail "volatile read snapshot failed"
      rm -f "$project/.oms/hooks/$vol_case"
      rc=0
      out="$(ma_read_guard_assert 2>&1)" || rc=$?
      [ "$rc" = 0 ] || fail "deleted volatile hooks/$vol_case failed a read pass: $out"
    done
    for vol_case in plan/tasks.json failures.jsonl runtime/outcomes.jsonl runtime/outcomes.jsonl.rm tick/history.jsonl; do
      ma_read_guard_begin "$snap/read-authority-${vol_case//\//-}" || fail "authority read snapshot failed"
      case "$vol_case" in
        runtime/outcomes.jsonl.rm) vol_case=runtime/outcomes.jsonl; rm -f "$project/.oms/$vol_case" ;;
        *.jsonl) printf 'x\n' > "$project/.oms/$vol_case" ;;
        *) rm -f "$project/.oms/$vol_case" ;;
      esac
      rc=0
      out="$(ma_read_guard_assert 2>&1)" || rc=$?
      [ "$rc" = 2 ] || fail "read pass tolerated authority change $vol_case: $out"
      contains "$out" 'protected surfaces: shared-state' || fail "authority change was not hard: $out"
      contains "$out" "$vol_case" || fail "read failure did not name $vol_case: $out"
    done
  )
}

# smoke-weight: 7
test_worker_guard_accepts_only_artifact_index_compaction() {
