  changed="$( . "$ROOT/scripts/lib/oms-common.sh"
    OMS_ARTIFACT_INDEX_KEEP=5 oms_worker_surface_diff "$project" "$snap" )"
  [ "$changed" = shared-state ] ||
    fail "rewriting a surviving row must stay a violation, got: ${changed:-<none>}"

