    return (json.dumps(base, sort_keys=True) + "\n").encode()

def resolution(event_id, target):
    return (json.dumps({"schema": 1, "event_id": event_id, "operation_id": "op-" + target,
                        "artifact_id": "art-" + target, "ts": recent_ts,
