  rm -f "$race_ready" "$race_release"
  (
    OMS_SMOKE_RUNNER_ACTIVE=1 \
      OMS_TEST_WG_SNAPSHOT_PAUSE_AFTER=omsstate \
      OMS_TEST_WG_SNAPSHOT_READY="$race_ready" \
      OMS_TEST_WG_SNAPSHOT_RELEASE="$race_release" \
