# smoke-weight: 39
test_delegate_interactive_conversation() {
  local fixture="$TMP/delegate-interactive" case_dir project scenario provider
  mkdir -p "$fixture/bin"
  python3 - "$ROOT/scripts/lib/peer-conversation.py" "$fixture" <<'PY' || fail "conversation protocol rejection table failed"
import json, subprocess, sys
from pathlib import Path

helper, fixture = sys.argv[1:]
controls = [
    '{"prompt":"first","prompt":"second"}\n',
    '{"prompt":"next","unknown":true}\n',
    '{"finish":true,"prompt":"next"}\n',
    json.dumps({"prompt": "x" * 32769}) + "\n",
    '{"prompt":" /model other"}\n',
]
for index, control in enumerate(controls):
    rejected = subprocess.run([sys.executable, helper, "input"], input=control, text=True,
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5)
    assert rejected.returncode == 2 and not rejected.stdout, (index, rejected)

native = Path(fixture) / "native-result.json"
for provider in ("claude", "antigravity"):
    identity = "session_id" if provider == "claude" else "conversation_id"
    valid = ({"type": "result", "subtype": "success", "is_error": False,
              "stop_reason": "end_turn", "result": "Fixture response."}
             if provider == "claude" else {"status": "SUCCESS", "response": "Fixture response."})
    valid[identity] = "fixture-session"
    missing = {key: value for key, value in valid.items() if key != identity}
    denied = dict(valid, permission_denials="invalid") if provider == "claude" else dict(valid, status="DENIED")
    error = dict(valid, is_error=True) if provider == "claude" else dict(valid, error="provider failed")
    cases = [(json.dumps(missing), ""), (json.dumps(valid), "different-session"),
             (json.dumps(denied), ""), (json.dumps(error), ""), ("{malformed", ""),
             (json.dumps(valid) + "\n" + json.dumps(valid), ""),
             (json.dumps(dict(valid, usage="invalid")), ""), ("x" * 1048577, "")]
    prepared = Path(fixture) / provider
    prepared.mkdir()
    for index, (raw, expected) in enumerate(cases):
        native.write_text(raw + "\n", encoding="utf-8")
        rejected = subprocess.run([sys.executable, helper, "prepare", provider, str(native), expected,
                                   "2", str(prepared), str(prepared)],
                                  stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=5)
        assert rejected.returncode == 2 and not rejected.stdout, (provider, index, rejected)
        assert not (prepared / "text").exists() and not (prepared / "event").exists()
    answer_key = "result" if provider == "claude" else "response"
    valid[answer_key] = "응답\n" + "x" * 12000
    valid["usage"] = {"input_tokens": 3, "output_tokens": 4}
    if provider == "claude":
        valid["permission_denials"] = [{"tool_name": "Bash"}]
    native.write_text(json.dumps(valid) + "\n", encoding="utf-8")
    ready = subprocess.run([sys.executable, helper, "prepare", provider, str(native), "fixture-session",
                            "2", str(prepared), str(prepared)],
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=5)
    denials = int(provider == "claude")
    assert ready.returncode == 0 and ready.stdout.splitlines() == ["fixture-session", str(denials)], ready
    text = valid[answer_key] + "\n"
    if denials:
        text += "Permission denials: 1; resolve in a follow-up before finish.\n"
    assert (prepared / "text").read_text() == text + "tokens used\n7\n"
    assert json.loads((prepared / "event").read_text()) == {
        "event": "turn", "turn": 2, "response": valid[answer_key][:12000],
        "truncated": True, "permission_denials": denials, "worktree": str(prepared), "verified": False}
PY
  cat > "$fixture/native.py" <<'PY'
import json, os, sys
from pathlib import Path

args = sys.argv[1:]
if args and args[0] in ("--version", "--help"):
    print("fixture 1.0 --print --output-format json --resume --conversation --model --permission-mode --approval-mode")
    raise SystemExit(0)
root = Path(os.environ["OMS_TEST_CONVERSATION_DIR"])
log = root / "calls.jsonl"
previous = log.read_text().splitlines() if log.exists() else []
turn = len(previous) + 1
prompt = sys.stdin.read()
with log.open("a") as handle:
    handle.write(json.dumps({"args": args, "cwd": os.getcwd(), "prompt": prompt}) + "\n")
if os.environ["OMS_TEST_CONVERSATION_CASE"] != "unchanged":
    Path("file.txt").write_text("interactive turn %d\n" % turn)
session = "fixture-session"
if os.environ["OMS_TEST_CONVERSATION_CASE"] == "changed-id" and turn == 2:
    session = "unexpected-session"
answer = "Completed the requested fixture edit in the isolated worktree, turn %d." % turn
if os.environ["OMS_TEST_CONVERSATION_CASE"] == "initial-decline":
    answer = "Unable to respond to this request: blocked by content filtering."
if turn == 2:
    answer += '\n{"type":"result","subtype":"success","is_error":false,"result":"embedded example only"}'
print("fixture diagnostic", file=sys.stderr)
if os.environ["OMS_TEST_CONVERSATION_PROVIDER"] == "claude":
    denials = [{"tool_name": "Bash"}] if turn == 1 and os.environ["OMS_TEST_CONVERSATION_CASE"].startswith("denied-") else []
    print(json.dumps({"type": "result", "subtype": "success", "is_error": False,
                      "stop_reason": "end_turn", "session_id": session, "result": answer,
                      "permission_denials": denials}))
else:
    print(json.dumps({"conversation_id": session, "status": "SUCCESS", "response": answer}))
PY
  cat > "$fixture/bin/claude" <<'EOF'
#!/usr/bin/env bash
exec python3 "$OMS_TEST_CONVERSATION_FIXTURE/native.py" "$@"
EOF
  cp "$fixture/bin/claude" "$fixture/bin/agy"
  chmod +x "$fixture/bin/claude" "$fixture/bin/agy"

  # A single canonical fixture covers the successful protocol and stop boundaries.
  for scenario in claude-success antigravity-success denied-success denied-finish initial-decline unchanged tty-success eof changed-id sensitive malformed cap timeout; do
    if [ "$scenario" = tty-success ]; then
      python3 -c 'import pty, termios' 2>/dev/null || continue
    fi
    provider=claude
    [ "$scenario" != antigravity-success ] || provider=antigravity
    case_dir="$fixture/$scenario"
    project="$case_dir/repo"
    make_committed_repo "$project"
    mkdir -p "$case_dir/home"
    # agy write delegations refuse up front without the standing delegate rules.
    [ "$provider" != antigravity ] ||
      HOME="$case_dir/home" PATH="$fixture/bin:$PATH" env -u OMS_ANTIGRAVITY_SETTINGS \
        bash "$ROOT/scripts/provider-permissions.sh" --apply --profile delegate >/dev/null ||
      fail "delegate permissions fixture failed"
    HOME="$case_dir/home" PATH="$fixture/bin:$PATH" \
      OMS_TEST_CONVERSATION_FIXTURE="$fixture" \
      OMS_TEST_CONVERSATION_DIR="$case_dir" \
      OMS_TEST_CONVERSATION_CASE="$scenario" \
      OMS_TEST_CONVERSATION_PROVIDER="$provider" OMS_WORKER_GUARD_STRICT=1 \
      python3 - "$ROOT" "$case_dir" "$provider" "$scenario" <<'PY' || fail "interactive conversation case failed: $scenario"
import json, os, queue, subprocess, sys, threading
from pathlib import Path

source, root, provider, scenario = sys.argv[1:]
root = Path(root)
repo = root / "repo"
command = ["bash", str(Path(source) / "scripts/peer-delegate.sh"), "--repo", str(repo),
           "--to", provider, "--interactive", "--model", "fixture-model",
           "--prompt", "Make the initial fixture edit.",
           "--verify", "test \"$(cat file.txt)\" = 'interactive turn 2' && "
                       "printf 'verified\\n' > \"$OMS_TEST_CONVERSATION_DIR/verified\""]
if scenario == "claude-success":
    for incompatible in (["--read-only"], ["--executor", "fixture-executor"],
                         ["--plan-task", "fixture-task"], ["--repair", "1"],
                         ["--apply"], ["--fallback-model", "fixture-fallback"], ["--dry-run"]):
        rejected = subprocess.run(command + incompatible, input="", text=True,
                                  stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=20)
        assert rejected.returncode != 0, incompatible
        assert not (root / "calls.jsonl").exists(), ("provider ran for incompatible mode", incompatible)
if scenario == "cap":
    command += ["--max-turns", "1"]
if scenario == "unchanged":
    # Only orchestrated writes treat an empty patch as a failure (exit 6).
    os.environ.update(OMS_PANEL_DISPATCH="1", OMS_PANEL_ROLE="worker")
if scenario == "timeout":
    command += ["--idle-timeout", "1"]
sample = "sk-" + "a" * 48
events = []
with (root / "stderr").open("w") as errors:
    if scenario == "tty-success":
        import fcntl, pty, termios
        master, slave = pty.openpty()
        process = subprocess.Popen(command, stdin=slave, stdout=subprocess.PIPE,
                                   stderr=errors, text=True, start_new_session=True,
                                   preexec_fn=lambda: fcntl.ioctl(0, termios.TIOCSCTTY, 0))
        os.close(slave)
        process.stdin = os.fdopen(master, "w")
    else:
        process = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                   stderr=errors, text=True)
    pending = queue.Queue()
    def read_events():
        for row in process.stdout:
            pending.put(row)
        pending.put(None)
    reader = threading.Thread(target=read_events, daemon=True)
    reader.start()
    try:
        if scenario == "initial-decline":
            process.stdin.close()
            process.wait(timeout=60)
            reader.join(timeout=5)
            assert process.returncode != 0 and not reader.is_alive()
            rows = list(pending.queue)
            emitted = [json.loads(row) for row in rows if row and row.strip()]
            assert not any(event["event"] in ("turn", "finished") for event in emitted), emitted
            assert len((root / "calls.jsonl").read_text().splitlines()) == 1
            assert not (root / "verified").exists(), "declined dialogue ran verification"
            artifacts = list((repo / ".oms/artifacts/delegate").glob("*.md"))
            assert any("blocked by content filtering" in artifact.read_text() for artifact in artifacts), artifacts
            raise SystemExit(0)
        # Reading the first event before sending input proves actual interactive
        # delivery, and lets us distinguish an idle timeout from startup cost.
        line = pending.get(timeout=60)
        assert line, ("missing initial event", (root / "stderr").read_text())
        events.append(json.loads(line))
        assert events[0]["event"] == "turn" and events[0]["verified"] is False, events
        assert events[0]["permission_denials"] == int(scenario.startswith("denied-")), events
        calls = [json.loads(row) for row in (root / "calls.jsonl").read_text().splitlines()]
        sentinel = root / "verified"
        assert not sentinel.exists(), "verifier ran before finish"
        if scenario == "timeout":
            # Leave stdin open without a message until the bounded reader exits.
            process.wait(timeout=20)
        elif scenario in ("denied-finish", "unchanged"):
            process.stdin.write('{"finish":true}\n')
            process.stdin.flush()
        elif scenario == "eof":
            process.stdin.close()
        else:
            message = {"prompt": "Make the second fixture edit."}
            if scenario == "sensitive":
                message = {"prompt": "Use " + "API_" + "KEY=" + sample}
            control = "{malformed\n" if scenario == "malformed" else json.dumps(message) + "\n"
            process.stdin.write(control)
            process.stdin.flush()
            if scenario.endswith("success"):
                events.append(json.loads(pending.get(timeout=60)))
                assert events[-1]["event"] == "turn", events
                assert not sentinel.exists(), "verifier ran between turns"
                process.stdin.write('{"finish":true}\n')
                process.stdin.flush()
            if scenario != "tty-success":
                process.stdin.close()
        process.wait(timeout=60)
        reader.join(timeout=5)
        assert not reader.is_alive(), "conversation output remained open"
        while not pending.empty():
            row = pending.get_nowait()
            if row is not None and row.strip():
                events.append(json.loads(row))
    finally:
        if process.poll() is None:
            process.kill()
            process.wait()
        reader.join(timeout=5)
        process.stdout.close()
        if not process.stdin.closed:
            process.stdin.close()

calls = [json.loads(row) for row in (root / "calls.jsonl").read_text().splitlines()]
expected_calls = 2 if scenario.endswith("success") or scenario == "changed-id" else 1
assert len(calls) == expected_calls, (scenario, calls)
assert len({row["cwd"] for row in calls}) == 1 and calls[0]["cwd"] != str(repo), calls
assert events[0]["worktree"] == calls[0]["cwd"], events
assert (repo / "file.txt").read_text() == "base\n", "owner worktree was edited"
assert len(list((repo / ".oms/lifecycle/attempts").glob("*/spec.json"))) == 1, "turns created new OMS attempts"
resume = "--resume" if provider == "claude" else "--conversation"
for index, call in enumerate(calls):
    args = call["args"]
    assert args[args.index("--model") + 1] == "fixture-model", args
    assert args[args.index("--output-format") + 1] == "json", args
    if provider == "claude":
        assert "--permission-mode" not in args, "write worker must inherit the operator permission mode"
        assert "--setting-sources" not in args, args
        assert "--settings" not in args, args
        assert "--dangerously-skip-permissions" not in args, args
    else:
        assert "--sandbox" in args and args[args.index("--add-dir") + 1] == call["cwd"], args
    delivered = call["prompt"] if provider == "claude" else args[args.index("--print") + 1]
    assert ("Make the initial fixture edit." if index == 0 else "Make the second fixture edit.") in delivered
    if index == 0:
        assert resume not in args, args
    else:
        assert 'Make the initial fixture edit.' not in delivered, 'resumed turn replayed initial context'
        assert 'Completed the requested fixture edit' not in delivered, 'resumed turn replayed prior answer'
        assert args[args.index(resume) + 1] == "fixture-session", args
        def frozen(row):
            values = row["args"][:]
            for flag in (resume, "--print" if provider != "claude" else "--unused"):
                if flag in values:
                    offset = values.index(flag)
                    del values[offset:offset + 2]
            return values
        assert frozen(calls[0]) == frozen(call), calls
turns = [event for event in events if event["event"] == "turn"]
assert [event["turn"] for event in turns] == list(range(1, len(turns) + 1)), events
assert all(event["verified"] is False and "fixture edit" in event["response"] for event in turns), events
finished = [event for event in events if event["event"] == "finished"]
if scenario.endswith("success"):
    assert process.returncode == 0, (root / "stderr").read_text()
    assert len(turns) == 2 and len(finished) == 1, events
    result = finished[0]
    assert result["verification"] == "passed" and result["applied"] is False, result
    artifact, patch = Path(result["artifact"]), Path(result["patch"])
    assert artifact.is_file() and patch.is_file(), result
    transcript = artifact.read_text()
    assert all(event["response"] in transcript for event in turns), "artifact lost a conversation turn or its embedded JSON example"
    assert "> Make the second fixture edit." in transcript, "artifact omitted the quoted controller follow-up"
    assert "+interactive turn 2" in patch.read_text(), patch.read_text()
    assert sentinel.read_text() == "verified\n", "verifier did not run after finish"
else:
    assert process.returncode != 0 and not finished, (scenario, events, (root / "stderr").read_text())
    assert len(turns) == 1, events
    assert not sentinel.exists(), "failed dialogue ran verification"
    if scenario == "unchanged":
        failed = [event for event in events if event["event"] == "failed"]
        assert process.returncode == 6 and len(failed) == 1, (process.returncode, events)
        assert "verify_exit" in failed[0] and failed[0]["verify_exit"] is None, failed
    assert sample not in (root / "stderr").read_text() and sample not in json.dumps(events)
if scenario == "antigravity-success":
    oversized_brief = root / "oversized-brief.md"
    oversized_brief.write_text("Task\n" + ("x" * 120001) + "\n", encoding="utf-8")
    calls_before = len((root / "calls.jsonl").read_text().splitlines())
    oversized_cmd = ["bash", str(Path(source) / "scripts/peer-delegate.sh"), "--repo", str(repo),
                     "--to", provider, "--interactive", "--model", "fixture-model",
                     "--brief-file", str(oversized_brief), "--verify", "true"]
    rejected = subprocess.run(oversized_cmd, input="", text=True,
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                              timeout=int(os.environ.get("OMS_TEST_CALL_TIMEOUT", "60")))
    assert rejected.returncode != 0, (rejected.returncode, rejected.stdout, rejected.stderr)
    assert len((root / "calls.jsonl").read_text().splitlines()) == calls_before, "oversized interactive prompt must not invoke agy"
    failed_events = [json.loads(row) for row in rejected.stdout.splitlines() if row.strip()]
    assert len(failed_events) == 1 and failed_events[0]["event"] == "failed" and failed_events[0]["worker_exit"] == 2, failed_events
    refusal_text = Path(failed_events[0]["artifact"]).read_text(encoding="utf-8")
    assert "the antigravity transport carries it as one argv element (limit ~128KiB)" in refusal_text, refusal_text
PY
  done
}

# smoke-weight: 21
test_delegate_consults_an_advisor_after_a_repair_also_fails() {
  local project="$TMP/delegate-advise"
  local bin="$project/bin"
  local home_dir="$project/home"
  local out
  local artifact

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  # The worker never succeeds; the advisor is a second provider, which is what
  # the default picker looks for — an opinion from something other than the
  # agent that is already stuck.
  cat > "$bin/codex" <<'EOF'
#!/usr/bin/env bash
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf 'codex 1.0\n'; exit 0 ;; esac
cat > /dev/null
echo "tried and failed"
exit 1
EOF
  cat > "$bin/claude" <<'EOF'
#!/usr/bin/env bash
case "${1:-}" in --version|--help) printf 'claude 1.0\n'; exit 0 ;; esac
cat > /dev/null
echo "VERDICT: stop. The brief names a file that does not exist in this tree."
[ -z "${OMS_TEST_ADVISOR_COUNTER:-}" ] || printf 'called\n' >> "$OMS_TEST_ADVISOR_COUNTER"
EOF
  chmod +x "$bin/codex" "$bin/claude"

  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_ADVISOR_PROVIDER=claude OMS_ADVISE_ON_REPEAT=1 \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt "a task that keeps failing" --model fixture-model --verify false --repair 2 2>&1)" || true

  contains "$out" 'advisor consulted after repeated failure' ||
    fail "a second failing attempt should pull in an outside opinion: $out"
  artifact="$(printf '%s' "$out" | sed -n 's/^artifact: //p' | sed -n '1p')"
  grep -Fq 'Advisor (after repeated failure)' "$artifact" ||
    fail "the advice belongs in the artifact"
  grep -Fq 'The brief names a file that does not exist' "$artifact" ||
    fail "the advisor's actual answer should be recorded"

  # Once per delegation: the point is a different opinion, not a second loop.
  [ "$(grep -c 'Advisor (after repeated failure)' "$artifact")" = 1 ] ||
    fail "the advisor should be consulted once, not every round"
  python3 - "$project/.oms/artifacts/index.jsonl" <<'PY' || fail "advised repair contaminated single-worker replay"
import json, sys
rows = [json.loads(line) for line in open(sys.argv[1])]
assert not any("repair_replay" in row for row in rows if row.get("kind") == "delegate")
PY

  # A repair budget permits the same worker, not a hidden second provider.
  local setting counter="$project/advisor-calls"
  for setting in unset 0 yes; do
    out="$(
      unset OMS_ADVISE_ON_REPEAT
      [ "$setting" = unset ] || export OMS_ADVISE_ON_REPEAT="$setting"
      HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_ADVISOR_PROVIDER=claude \
        OMS_TEST_ADVISOR_COUNTER="$counter" \
        "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
        --prompt "a task that keeps failing" --no-verify --repair 2 2>&1
    )" || true
    [ ! -e "$counter" ] || fail "advisor ran without explicit opt-in ($setting): $out"
    artifact="$(printf '%s' "$out" | sed -n 's/^artifact: //p' | sed -n '1p')"
    [ -f "$artifact" ] && grep -Fq '## Repair 2' "$artifact" ||
      fail "disabling advice must preserve the second worker repair: $out"
  done
}

test_delegate_does_not_consult_an_advisor_on_a_first_failure() {
  local project="$TMP/delegate-advise-first"
  local bin="$project/bin"
  local home_dir="$project/home"
  local out

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  printf '#!/usr/bin/env bash\ncase "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf "codex 1.0\\n"; exit 0 ;; esac\ncat > /dev/null\necho nope\nexit 1\n' > "$bin/codex"
  printf '#!/usr/bin/env bash\ncase "${1:-}" in --version|--help) printf "claude 1.0\\n"; exit 0 ;; esac\ncat > /dev/null\necho advice\n' > "$bin/claude"
  chmod +x "$bin/codex" "$bin/claude"

  # One repair is the ordinary path: a worker that stumbles once and is told so
  # usually recovers, and an advisor call there would be a tax on every run.
  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_ADVISOR_PROVIDER=claude OMS_ADVISE_ON_REPEAT=1 \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt "fails once" --no-verify --repair 1 2>&1)" || true
  if contains "$out" 'advisor consulted'; then
    fail "a single repair round should not pay for an advisor: $out"
  fi
}

test_harness_child_cannot_start_recursive_peer_work() {
  local project="$TMP/child-peer-authority"
  local bin="$project/bin"
  local home_dir="$project/home"
  local counter="$project/provider-calls"
  local router_counter="$project/router-provider-calls"
  local router_output="$project/router-child.out"
  local verify_sentinel="$project/reviewer-verify-ran"
  local verdicts="$project/verdicts"
  local output rc label

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir" "$verdicts"
  for provider in codex claude agy; do
    cat > "$bin/$provider" <<'EOF'
#!/usr/bin/env bash
printf 'called\n' >> "$OMS_TEST_PEER_COUNTER"
cat >/dev/null || true
printf 'A complete fixture answer that should never be reached by a harness child.\n'
EOF
    chmod +x "$bin/$provider"
  done

  assert_child_peer_refused() {
    label="$1"
    shift
    output="$project/$label.out"
    rc=0
    OMS_HARNESS_CHILD=1 OMS_TEST_PEER_COUNTER="$counter" \
      HOME="$home_dir" PATH="$bin:/usr/bin:/bin" "$@" \
      >"$output" 2>&1 || rc=$?
    [ "$rc" = 2 ] ||
      fail "harness child peer start $label returned $rc: $(cat "$output")"
    grep -Fq 'a harness child cannot start peer calls or delegation' "$output" ||
      fail "harness child peer refusal $label was not actionable: $(cat "$output")"
  }

  assert_child_peer_refused agent-call "$ROOT/scripts/agent-call.sh" \
    --to codex --repo "$project" --prompt child
  assert_child_peer_refused peer-ask "$ROOT/scripts/peer-ask.sh" \
    --repo "$project" --providers codex --prompt child --dry-run
  assert_child_peer_refused peer-review "$ROOT/scripts/peer-review.sh" \
    --repo "$project" --providers codex --prompt child --no-diff --gate \
    --verify 'touch reviewer-verify-ran'
  assert_child_peer_refused peer-delegate env OMS_DELEGATE_MAX_DEPTH=999 \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt child --no-verify --apply --dry-run
  assert_child_peer_refused consult "$ROOT/scripts/consult.sh" \
    --to codex --repo "$project" --prompt child --dry-run
  assert_child_peer_refused advise "$ROOT/scripts/advise.sh" \
    --to codex --repo "$project" --prompt child --no-failures \
    --no-strategy --dry-run

  # The public guards prevent ordinary callers reaching the common router.
  # Exercise that defense directly so a future front door cannot bypass it.
  rc=0
  (
    # shellcheck source=scripts/lib/peer-common.sh
    . "$ROOT/scripts/lib/peer-common.sh"
    ma_run_routed_provider_inner() {
      printf 'called\n' >> "$router_counter"
    }
    ma_resolve_seat_recovery() { return 0; }
    OMS_HARNESS_CHILD=1 ma_run_routed_provider codex read /dev/null \
      "$project/router-artifact" "$project" router-test "" router-test
  ) >"$router_output" 2>&1 || rc=$?
  [ "$rc" = 2 ] ||
    fail "common provider router let a harness child through: $(cat "$router_output")"
  [ ! -e "$router_counter" ] ||
    fail "common provider router dispatched a child-marked call"

  (
    # shellcheck source=scripts/lib/peer-common.sh
    . "$ROOT/scripts/lib/peer-common.sh"
    ma_run_routed_provider_inner() {
      printf 'called\n' >> "$router_counter"
    }
    ma_resolve_seat_recovery() { return 0; }
    ma_run_routed_provider codex read /dev/null "$project/router-artifact" \
      "$project" router-test "" router-test
  ) >/dev/null 2>&1 || fail "an unmarked owner could not use the common provider router"
  [ -s "$router_counter" ] ||
    fail "the common provider router regression never reached its provider stub"

  [ ! -e "$counter" ] || fail "a refused child peer start reached a provider"
  [ ! -e "$verify_sentinel" ] ||
    fail "a refused child peer-review executed its verifier"
  [ ! -e "$project/.oms" ] ||
    fail "a refused child peer start wrote project authority state"

  # Verdict extraction is observation, not a new peer call.
  printf '# codex review\n\n## Output\n\nGATE: pass\n\n## Exit\n\n0\n' \
    > "$verdicts/codex-child-20260611T000000Z-1.md"
  OMS_HARNESS_CHILD=1 "$ROOT/scripts/peer-review.sh" verdicts "$verdicts" \
    >/dev/null || fail "a harness child should be able to inspect review verdicts"
  OMS_HARNESS_CHILD=1 "$ROOT/scripts/agent-call.sh" --help >/dev/null ||
    fail "peer help should remain available to a harness child"
}

test_delegate_refuses_to_nest_beyond_the_depth_cap() {
  local project="$TMP/delegate-depth"
  local bin="$project/bin"
  local home_dir="$project/home"
  local rc=0
  local out

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  printf '#!/usr/bin/env bash\ncat > /dev/null\necho worked\n' > "$bin/codex"
  chmod +x "$bin/codex"

  # Nesting multiplies: a worker that delegates can spawn workers that delegate.
  # The project rules already said a worker does not do this; nothing enforced
  # it, and a worker that tried simply succeeded.
  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_HARNESS_DELEGATE_DEPTH=1 \
    "$ROOT/scripts/peer-delegate.sh" --to codex --repo "$project" \
    --prompt "spawn from inside a worker" --no-verify 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "a worker must not spawn its own worker: $out"
  contains "$out" 'does not spawn its own workers' ||
    fail "the refusal should say what to do instead: $out"
  contains "$out" 'let the parent fan out' ||
    fail "the refusal should return recursive work to the parent: $out"

  # A two-stage job can raise the cap on purpose, in one place.
  rc=0
  HOME="$home_dir" PATH="$bin:/usr/bin:/bin" OMS_HARNESS_DELEGATE_DEPTH=1 \
    OMS_DELEGATE_MAX_DEPTH=2 "$ROOT/scripts/peer-delegate.sh" --to codex \
    --repo "$project" --prompt "explicitly nested" --no-verify --allow-no-change >/dev/null 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "an explicitly raised cap should allow one more level"

  # And the top level is unaffected.
  rc=0
  HOME="$home_dir" PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --prompt "top level" --no-verify --allow-no-change >/dev/null 2>&1 || rc=$?
  [ "$rc" = 0 ] || fail "an ordinary delegation must still run"
}

test_delegate_reports_a_worker_that_could_not_act() {
  local project="$TMP/delegate-blocked"
  local bin="$project/bin"
  local home_dir="$project/home"
  local rc=0
  local out

  make_committed_repo "$project"
  mkdir -p "$bin" "$home_dir"
  # A CLI that exits 0 having printed only its reason for doing nothing. The
  # empty patch that follows is indistinguishable from honest work on an
  # already-correct tree, which is how a permission problem reads as success.
  cat > "$bin/codex" <<'EOF'
#!/usr/bin/env bash
cat > /dev/null
echo 'jetski: no output produced — a tool required the "unsandboxed" permission that headless mode cannot prompt for, so it was auto-denied.'
exit 0
EOF
  chmod +x "$bin/codex"

  out="$(HOME="$home_dir" PATH="$bin:/usr/bin:/bin" "$ROOT/scripts/peer-delegate.sh" \
    --to codex --repo "$project" --prompt "add a thing" \
    --verify 'echo unnecessary-verifier-ran' --repair 2 2>&1)" || rc=$?

  # The script keeps its one failure code; the distinct 126 rides on the worker
  # status, where a caller reading the run can tell "could not act" from "acted
  # and failed".
  [ "$rc" != 0 ] || fail "a blocked worker must not report success: $out"
  contains "$out" 'could not run' ||
    fail "the operator needs to be told the worker never acted: $out"
  contains "$out" 'exit 126' ||
    fail "a blocked worker should be distinguishable from a failed one: $out"
  # No rewording of the brief grants a permission, so repair must not burn calls.
  if contains "$out" 'repair 1'; then
    fail "a blocked worker is not repairable: $out"
  fi
  if grep -R -Fxq unnecessary-verifier-ran "$project/.oms/artifacts/delegate"; then
    fail "blocked provider must not trigger project verification"
  fi
}

# smoke-weight: 5
test_landing_refuses_while_another_landing_holds_the_repo() {
  local project="$TMP/landing-serialized"
  local patch="$TMP/landing-serialized.patch"
  local holder_pid
  local waited=0
  local rc=0
  local recovery_rc=0
  local out
  local recovery_out
  local failure=""

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  mkdir -p "$project/.oms"
  printf '*\n' > "$project/.oms/.gitignore"

  # Stand in for a landing already in flight. Two landers can both see a clean
  # tree and both pass admission against the same base, so the second must be
  # turned away rather than applying into the first one's half-landed tree.
  (
    . "$ROOT/scripts/lib/file-lock.sh"
    oms_hold_file_lock "$project/.oms/landings.jsonl" 7 || exit 1
    : > "$project/held"
    while [ -f "$project/held" ]; do sleep 1; done
    # A real holder releases on exit the way patch-land does; only an flock fd
    # is dropped for free by the kernel.
    oms_release_held_file_lock
  ) &
  holder_pid=$!
  while [ ! -f "$project/held" ]; do
    waited=$((waited + 1))
    [ "$waited" -lt 50 ] || fail "the stand-in landing never took the lock"
    sleep 1
  done

  out="$("$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" 2>&1)" || rc=$?
  recovery_out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)" || recovery_rc=$?
  rm -f "$project/held"
  wait "$holder_pid" 2>/dev/null || true

  [ "$rc" = 75 ] || failure="landing exit=$rc (expected 75): $out"
  contains "$out" 'another landing or recovery is in progress' ||
    failure="${failure:+$failure; }landing refusal did not name the reason: $out"
  [ "$recovery_rc" = 75 ] ||
    failure="${failure:+$failure; }recovery exit=$recovery_rc (expected 75): $recovery_out"
  contains "$recovery_out" 'another landing or recovery is in progress' ||
    failure="${failure:+$failure; }recovery refusal did not name the reason: $recovery_out"
  [ -z "$failure" ] || fail "$failure"
  [ -z "$(git -C "$project" status --porcelain -- file.txt)" ] ||
    fail "the refused landing must not have applied anything"

  # The lock is not sticky: once the holder is gone the same landing proceeds.
  rc=0
  out="$("$ROOT/scripts/patch-land.sh" --patch "$patch" --repo "$project" 2>&1)" || rc=$?
  [ "$rc" = 0 ] || fail "landing should succeed once the lock is free: $out"
}

test_landing_recovery_refuses_a_changed_patch() {
  local project="$TMP/landing-patchbound"
  local patch="$project/change.patch"
  local rc=0
  local out

  make_committed_repo "$project"
  printf 'base\nadded\n' > "$project/file.txt"
  ( cd "$project" && git diff > "$patch" && git checkout -q -- file.txt )
  mkdir -p "$project/.oms"
  printf '*\n' > "$project/.oms/.gitignore"
  # The intent names a patch whose content no longer matches: recovery cannot
  # tell whether THIS patch landed, and guessing writes a false record.
  printf '{"schema":1,"ts":"2026-07-27T00:00:00Z","landing_id":"l1","event":"intent","patch":"%s","patch_sha":"deadbeef","task":"","lease":""}\n' \
    "$patch" > "$project/.oms/landings.jsonl"

  out="$("$ROOT/scripts/patch-land.sh" --repo "$project" --recover 2>&1)" || rc=$?
  [ "$rc" != 0 ] || fail "a changed patch should make recovery exit nonzero: $out"
  contains "$out" 'recover this one by hand' ||
    fail "recovery should hand it to a human: $out"
  # Neither outcome may be recorded: the transaction stays outstanding.
  if grep -Eq '"event": ?"(complete|abandoned)"' "$project/.oms/landings.jsonl"; then
    fail "recovery must not guess an outcome for a changed patch"
  fi
}

test_provider_contract_check_passes_without_providers() {
  local home="$TMP/pc-home"
  local out

  mkdir -p "$home"
  # A machine with no provider CLIs and no registrations is healthy: loader
  # parity and fail-open still verify, MCP checks become notes.
  out="$(HOME="$home" CODEX_HOME="$home/.codex" PATH="/usr/bin:/bin" \
    bash "$ROOT/scripts/doctor.sh" --contract 2>&1)" ||
    fail "provider-contract should pass with no providers: $out"
  printf '%s\n' "$out" | grep >/dev/null 'ok: loader parity (general)' ||
    fail "general loader parity not verified: $out"
  printf '%s\n' "$out" | grep >/dev/null 'ok: loader parity (ml)' ||
    fail "ml loader parity (GEMINI adoption + style retire) not verified: $out"
  printf '%s\n' "$out" | grep >/dev/null 'ok: fail-open' ||
    fail "fail-open hook contract not verified: $out"
  printf '%s\n' "$out" | grep >/dev/null 'note: mcp (claude): CLI not installed' ||
    fail "missing CLI must be a note, not a failure: $out"
  printf '%s\n' "$out" | grep >/dev/null 'provider-contract: ok' ||
    fail "missing ok summary: $out"
}

test_provider_contract_flags_mcp_drift() {
  local home="$TMP/pc-drift-home"
  local bin="$TMP/pc-drift-bin"
  local srv1="$TMP/pc-drift-srv1"
  local srv2="$TMP/pc-drift-srv2"
  local out rc

  mkdir -p "$home" "$home/.codex" "$bin" "$srv1" "$srv2"
  printf '#!/bin/sh\nexit 0\n' > "$bin/claude"
  chmod +x "$bin/claude"
  : > "$srv1/oms-mcp-server.py"
  : > "$srv2/oms-mcp-server.py"
  cat > "$home/.claude.json" <<EOF
{"mcpServers":{"oh-my-setting":{"type":"stdio","command":"python3","args":["$srv1/oms-mcp-server.py"]}}}
EOF
  cat > "$home/.codex/config.toml" <<EOF
[mcp_servers.oh-my-setting]
command = "python3"
args = ["$srv2/oms-mcp-server.py"]
EOF

  # Two providers reading two different servers is the drift this gate exists
  # to catch, even when each registration is individually valid.
  rc=0
  out="$(HOME="$home" CODEX_HOME="$home/.codex" PATH="$bin:/usr/bin:/bin" \
    bash "$ROOT/scripts/doctor.sh" --contract 2>&1)" || rc=$?
  [ "$rc" = 1 ] || fail "drifted registrations should exit 1 (rc=$rc): $out"
  printf '%s\n' "$out" | grep >/dev/null 'fail: mcp parity' ||
    fail "parity drift not reported: $out"

  cat > "$home/.codex/config.toml" <<EOF
[mcp_servers.oh-my-setting]
command = "python3"
args = ["$srv1/oms-mcp-server.py"]
EOF
  out="$(HOME="$home" CODEX_HOME="$home/.codex" PATH="$bin:/usr/bin:/bin" \
    bash "$ROOT/scripts/doctor.sh" --contract 2>&1)" ||
    fail "aligned registrations should pass: $out"
  printf '%s\n' "$out" | grep >/dev/null 'ok: mcp parity' ||
    fail "parity ok line missing: $out"
}

test_state_verify_clean_and_unadopted() {
  local plain="$TMP/sv-plain"
  local project="$TMP/sv-clean"
  local out

  mkdir -p "$plain"
  out="$("$ROOT/scripts/state-verify.sh" --repo "$plain" 2>&1)" ||
    fail "an unadopted directory must verify clean: $out"
