    # Replay observed Git replies to exercise timeout edges without real waits.
    repo = spaced
    timeout_fields = list(valid_fields)
    timeout_fields[1] = str(remote_spaced)
    for index in (5, 9, 10):
        timeout_fields[index] = pushed
    timeout_wire = "\nOMS_TARGET_V1\n" + "\0".join(timeout_fields) + "\0"
    for action, default_budget in (("status", 120), ("sync", 1800)):
        for selected in (None, 10, 7200):
            expected_budget = default_budget if selected is None else selected
            def budget_transport(command, **kwargs):
                assert kwargs["timeout"] == expected_budget, (command, kwargs["timeout"], expected_budget)
                if command[0] == str(stub):
                    assert command[-1] == str(expected_budget), command
                    return subprocess.CompletedProcess(command, 0, timeout_wire, "")
                return recorded_local[tuple(command)]
            arguments = ["target", action, "sample"]
            if action == "sync":
                arguments.extend(("--sha", pushed))
            if selected is not None:
                arguments.extend(("--timeout", str(selected)))
            with patch.object(targets, "_run", side_effect=budget_transport):
                assert call(*arguments)["ok"]
        for invalid in ("", "0", "9", "7201", "-1", "1.5", "malformed"):
            with patch.object(targets, "_run", side_effect=AssertionError("invalid timeout launched process")):
                call("target", action, "sample", "--timeout=" + invalid, rc=2)
        assert "read-only" in call("target", action, "sample", "--timeout", "7200", child=True, rc=2)
    for invalid in (False, "10", 10.5):
        try:
            targets.inspect_target(repo, "sample", timeout_seconds=invalid)
        except targets.CoreError as error:
            assert "timeout" in str(error)
        else:
            raise AssertionError(invalid)
    repo = original_repo
    def timed_out(command, **kwargs):
        if command[0] == str(stub):
            assert kwargs["timeout"] == 120 and kwargs["input"] == targets._REMOTE_SCRIPT
            assert kwargs["start_new_session"] is True
            raise subprocess.TimeoutExpired("ssh", 120)
        return actual_run(command, **kwargs)
    with patch.object(targets, "_run", side_effect=timed_out):
        row = call("target", "status", "sample", rc=3)
        assert row["reason"] == "timeout" and row["state_unknown"] is True, row
    with patch.dict(os.environ, {"OMS_SSH_BIN": str(repo.parent / "missing-ssh")}):
        assert call("target", "status", "sample", rc=3)["reason"] == "no-network"
    with patch.dict(os.environ, {"OMS_TEST_REMOTE_HOME": ""}):
        assert call("target", "status", "sample", rc=3)["reason"] == "not-git"
    non_git = repo.parent / "not-git"
    non_git.mkdir()
    repo = non_git
    call("target", "add", "sample", "--ssh-alias", "sample-host")
    git(non_git, "init", "-q")
    git(non_git, "remote", "add", "origin", origin)
    git(non_git, "fetch", "origin")
    git(non_git, "checkout", "-qb", "main", "origin/main")
    (remote_home / non_git.name).mkdir()
    assert call("target", "status", "sample", rc=3)["reason"] == "not-git"
    assert call("target", "sync", "sample", rc=3)["reason"] == "not-git"
    assert not list((remote_home / non_git.name).iterdir())
    repo = original_repo
    bare256 = repo.parent / "origin256.git"
    git(repo, "init", "--bare", "--object-format=sha256", str(bare256))
    repo = repo.parent / "project256"
    repo.mkdir()
    git(repo, "init", "--object-format=sha256")
    git(repo, "symbolic-ref", "HEAD", "refs/heads/main")
    commit256 = commit("sha256 first")
    assert len(commit256) == 64
    origin256 = "https://sha256.example.test/team/project.git"
    git(repo, "remote", "add", "origin", origin256)
    call("target", "add", "sample", "--ssh-alias", "sample-host")
    with patch.dict(os.environ, {"GIT_CONFIG_COUNT": "1", "GIT_CONFIG_KEY_0": "url." + bare256.as_uri() + ".insteadOf",
                                 "GIT_CONFIG_VALUE_0": origin256}):
        git(repo, "push", "origin", "main")
        row = call("target", "sync", "sample", "--sha", commit256)
        assert row["after_sha"] == commit256 and row["before_sha"] is None, row
        assert call("target", "status", "sample")["head"] == commit256
        next256 = commit("sha256 advance")
        git(repo, "push", "origin", "main")
        row = call("target", "sync", "sample", "--sha", next256)
        assert row["before_sha"] == commit256 and row["after_sha"] == next256, row
    repo = original_repo
assert registry.read_bytes() == saved

output = repo.parent / "targets-capsule.json"
capsule.export(repo, output)
portable = output.read_text(encoding="utf-8")
assert all(value not in portable for value in ("targets.json", "ssh_alias", "sample-host", expected_dir, str(remote_home)))
assert capsule.verify(output)["valid"] is True
assert capsule.import_capsule(repo, output)["authority_transfer"] is False
assert registry.read_bytes() == saved
assert call("target", "remove", "sample")["targets"] == {}
assert call("target", "list", child=True) == {"schema": 1, "targets": {}}
assert "unknown remote target" in call("target", "remove", "sample", rc=2)
PY
}

test_portable_capsule_import_surfaces_advisory_continuity() {
  local project="$TMP/portable-capsule-continuity"
  local capsule_file="$TMP/portable-capsule.json"
  local before_nonportable after_nonportable state_json state_text inbox_json
  local resume_out latest_id

  make_committed_repo "$project"
  before_nonportable="$(python3 - "$project" <<'PY'
import hashlib, json, pathlib, sys
root = pathlib.Path(sys.argv[1]) / ".oms"
rows = {}
if root.exists():
    for path in sorted(root.rglob("*")):
        relative = path.relative_to(root)
        if relative.parts and relative.parts[0] == "portable":
            continue
        if path.is_symlink():
            rows[str(relative)] = "link:" + str(path.readlink())
        elif path.is_file():
            rows[str(relative)] = hashlib.sha256(path.read_bytes()).hexdigest()
print(json.dumps(rows, sort_keys=True))
PY
)"

  "$ROOT/scripts/runtime.sh" --repo "$project" capsule export \
    --output "$capsule_file" >/dev/null
  "$ROOT/scripts/runtime.sh" --repo "$project" capsule import \
    "$capsule_file" >/dev/null

  after_nonportable="$(python3 - "$project" <<'PY'
import hashlib, json, pathlib, sys
root = pathlib.Path(sys.argv[1]) / ".oms"
rows = {}
if root.exists():
    for path in sorted(root.rglob("*")):
        relative = path.relative_to(root)
        if relative.parts and relative.parts[0] == "portable":
            continue
        if path.is_symlink():
            rows[str(relative)] = "link:" + str(path.readlink())
        elif path.is_file():
            rows[str(relative)] = hashlib.sha256(path.read_bytes()).hexdigest()
print(json.dumps(rows, sort_keys=True))
PY
)"
  [ "$before_nonportable" = "$after_nonportable" ] ||
    fail "capsule import changed canonical task/plan/evidence/authority state"

  state_json="$("$ROOT/scripts/state.sh" --repo "$project" --json)"
  printf '%s' "$state_json" | python3 -c '
import json, re, sys
row = json.load(sys.stdin)["runtime"]["continuity"]["latest_import"]
assert row["present"] is True, row
assert row["advisory"] is True and row["authority_transfer"] is False, row
assert re.fullmatch(r"capsule-[0-9a-f]{32}", row["capsule_id"]), row
assert row["status"] == "current", row
assert row["head_matches"] is True and row["state_digest_matches"] is True, row
' || fail "state did not surface current advisory capsule continuity: $state_json"

  inbox_json="$("$ROOT/scripts/inbox.sh" --repo "$project" --json)"
  printf '%s' "$inbox_json" | python3 -c '
import json, sys
items = json.load(sys.stdin)["items"]
row = next(item for item in items if item["code"] == "portable-capsule-review")
assert row["priority"] == "P3" and "current" in row["summary"], row
' || fail "inbox did not surface imported capsule review: $inbox_json"

  resume_out="$(printf '{"session_id":"me","cwd":"%s"}' "$project" |
    "$ROOT/scripts/resume-hook.sh")" ||
    fail "resume hook rejected imported capsule"
  printf '%s\n' "$resume_out" | grep >/dev/null -F 'portable capsule' ||
    fail "resume hook did not surface imported capsule: $resume_out"
  printf '%s\n' "$resume_out" | grep >/dev/null -F 'current; advisory only' ||
    fail "resume hook hid capsule status or authority boundary: $resume_out"

  printf 'changed\n' >> "$project/file.txt"
  git -C "$project" add file.txt
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' \
    commit -m drift >/dev/null
  state_json="$("$ROOT/scripts/state.sh" --repo "$project" --json)"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)["runtime"]["continuity"]["latest_import"]
assert row["status"] == "head-diverged", row
assert row["head_matches"] is False, row
' || fail "state did not mark imported continuity stale after HEAD drift: $state_json"

  latest_id="$(tr -d '\r\n' < "$project/.oms/portable/imports/LATEST")"
  printf '{broken\n' > "$project/.oms/portable/imports/$latest_id.json"
  state_json="$("$ROOT/scripts/state.sh" --repo "$project" --json)"
  printf '%s' "$state_json" | python3 -c '
import json, sys
runtime = json.load(sys.stdin)["runtime"]
row = runtime["continuity"]["latest_import"]
assert runtime["healthy"] is True, runtime
assert row["status"] == "invalid" and row["capsule_id"] == "'"$latest_id"'", row
' || fail "invalid advisory capsule disabled canonical runtime: $state_json"
  state_text="$("$ROOT/scripts/state.sh" --repo "$project")"
  printf '%s\n' "$state_text" | grep >/dev/null -F \
    "imported capsule: $latest_id status=invalid" ||
    fail "state rendered invalid capsule incorrectly: $state_text"
  printf 'not-a-capsule\n' > "$project/.oms/portable/imports/LATEST"
  state_text="$("$ROOT/scripts/state.sh" --repo "$project")"
  printf '%s\n' "$state_text" | grep >/dev/null -F \
    'imported capsule: unknown status=invalid' ||
    fail "state rendered a null capsule id instead of unknown: $state_text"
  resume_out="$(printf '{"session_id":"me","cwd":"%s"}' "$project" |
    "$ROOT/scripts/resume-hook.sh")"
  printf '%s\n' "$resume_out" | grep >/dev/null -F \
    'portable capsule unknown (invalid; advisory only' ||
    fail "resume rendered a null capsule id instead of unknown: $resume_out"
}

test_goal_drive_problem_campaign() {
  local project="$TMP/problem-campaign"
  local stub="$TMP/campaign-stub"
  make_committed_repo "$project"
  mkdir -p "$stub/bin" "$stub/home"
  printf '#!/usr/bin/env bash\nSTUB_DIR=%q\n' "$stub" > "$stub/bin/codex"
  cat >> "$stub/bin/codex" <<'STUB'
case "${1:-}:${2:-}" in --version:|--help:|exec:--help) printf 'codex 1.0\n'; exit 0 ;; esac
prompt="$(cat)"
printf 'call\n' >> "$STUB_DIR/calls"
case "$prompt" in
  *"# Wave digest"*)
    printf '%s' "$prompt" | python3 -c 'import json,re,sys,pathlib; p=sys.stdin.read(); c=re.search(r"cand_[0-9a-f]+",p).group(); d=re.search(r"receipt=([0-9a-f]{64})",p).group(1); f=pathlib.Path(sys.argv[1])/"mode"; mode=f.read_text() if f.exists() else ""; good={"text":"useful note","candidates":[c],"receipts":[d]}; bad=[{"text":"bad id","candidates":["unknown"],"receipts":[d]},{"text":"bad receipt","candidates":[c],"receipts":["0"*64]}]; body= ("["*2000+"0"+"]"*2000) if mode=="deep" else json.dumps(([dict(good,text=chr(0xd83d)),good] if mode=="surrogate" else [good]*6000 if mode=="many" else [good]+bad)); print("```json\n"+body+"\n```")' "$STUB_DIR" ;;
  *MARK_BROKEN*) echo "route broke"; exit 42 ;;
  *MARK_PASS*) printf 'try this\n```patch\n'; cat "$STUB_DIR/pass.patch"; printf '```\n' ;;
  *MARK_TAMPER*) printf '```patch\n'; cat "$STUB_DIR/tamper.patch"; printf '```\n' ;;
  *MARK_WRONG*) printf '```patch\n'; cat "$STUB_DIR/wrong.patch"; printf '```\n' ;;
  *) echo "no idea" ;;
esac
STUB
  chmod +x "$stub/bin/codex"
  python3 -B - "$ROOT" "$project" "$stub" <<'PY'
import copy, hashlib, importlib.util, json, pathlib, subprocess, sys, concurrent.futures
root, repo, stub = map(pathlib.Path, sys.argv[1:])
import os
problem = repo / 'problem.txt'
problem.write_text('problem\n')
digest = hashlib.sha256(problem.read_bytes()).hexdigest()
base = subprocess.check_output(['git', '-C', str(repo), 'rev-parse', 'HEAD'], text=True).strip()
m = {'problem': {'file':'problem.txt','sha256':digest}, 'base':base,
     'verify': {'command':'true','timeout_s':1,'inputs':[]},
     'candidate_formats':['patch'],
     'groups':[{'id':'a','formulation':'approach','k':1,'routes':[{'provider':'codex','model':'example'}]}],
     'budget':{'max_concurrent':2,'total_calls':2,'deadline_s':60,'max_waves':1,'stall_waves':1,
               'verifier':{'concurrency':1,'timeout_s':1,'max_artifact_bytes':1}}}
path = repo / 'campaign.json'
env = {k: v for k, v in os.environ.items() if k not in ('OMS_HARNESS_CHILD', 'OMS_HARNESS_DELEGATE_DEPTH')}
env.update(PATH=str(stub/'bin')+':/usr/bin:/bin', HOME=str(stub/'home'), NVM_DIR=str(stub/'home/.nvm'), OMS_DELEGATE_WORKTREE_ROOT=str(stub/'managed'))
def run(manifest, *args):
    path.write_text(json.dumps(manifest))
    return subprocess.run(['bash',str(root/'scripts/goal-drive.sh'),'--repo',str(repo),'--campaign',str(path),*args],capture_output=True,text=True,env=env)
def attempt(target, *args):
    try: return target.reserve(*args)['id']
    except module.BudgetRefused as refusal: return refusal.reason
r = run(m, '--dry-run'); assert r.returncode == 0, r.stderr
out = json.loads(r.stdout); assert out['campaign_id'] and out['totals']['planned_seat_calls'] == 1
assert out['groups'][0]['routes'][0]['cap_source'] == 'global'
for route in (None, {}, {'provider':'codex', 'model':''}, {'provider':'unknown', 'model':'x'},
              {'provider':'cursor', 'model':'x', 'effort':'high'}, {'provider':'codex', 'model':'provider-default'}):
    bad=copy.deepcopy(m); bad['consolidator']=route
    assert run(bad,'--dry-run').returncode == 2, route
valid=copy.deepcopy(m); valid['consolidator']={'provider':'codex', 'model':'x'}
assert run(valid,'--dry-run').returncode == 0
path.write_text(json.dumps(m))
assert not (repo/'.oms').exists()
sub = repo/'nested'; sub.mkdir()
subrun = subprocess.run(['bash',str(root/'scripts/goal-drive.sh'),'--campaign',str(path),'--dry-run'],cwd=sub,capture_output=True,text=True)
assert subrun.returncode == 0, subrun.stderr
assert json.loads(subrun.stdout)['campaign_id'] == out['campaign_id']
assert out['totals']['remaining_headroom'] == 0
small=copy.deepcopy(m); small['budget']['total_calls']=1
small_out=json.loads(run(small,'--dry-run').stdout)
assert small_out['totals']['planned_seat_calls'] == 0 and small_out['totals']['remaining_headroom'] == 0
small['budget']['max_waves']=2
assert 'total_calls must cover one consolidator per wave' in run(small,'--dry-run').stderr
path.write_text(json.dumps(m))
bad = copy.deepcopy(m); bad['extra'] = 1
assert run(bad,'--dry-run').stderr == 'error: unknown key in manifest: extra\n'
bad = copy.deepcopy(m); bad['problem']['sha256'] = '0'*64
assert run(bad,'--dry-run').stderr == 'error: problem digest mismatch\n'
bad = copy.deepcopy(m); bad['base'] = '0'*40
assert run(bad,'--dry-run').stderr == 'error: base must equal HEAD\n'
assert 'unknown' in run(m,'--dry-run','--max-parallel-tasks','1').stderr
for option, value in [('--contract-id','x'),('--commit-task','x'),('--auto-repair',None),('--retry-known',None),('--expected-ref','x'),('--to','codex'),('--max-cycles','1'),('--run-id','x'),('--model','x'),('--fallback-model','x'),('--reasoning-effort','low'),('--provider-timeout','1s'),('--allow-verifier-change',None),('--allow-floor-change','x'),('--commit-message','x'),('--help',None)]:
    args = [option] + ([value] if value else [])
    assert ('--campaign cannot be combined with ' + option) in run(m,'--dry-run',*args).stderr
for key, low, high in [('max_concurrent',1,16),('total_calls',1,200),('deadline_s',60,86400),('max_waves',1,20),('stall_waves',1,1)]:
    for value in (0, high+1, 'bad'):
        bad=copy.deepcopy(m); bad['budget'][key]=value
        assert run(bad,'--dry-run').returncode == 2, (key,value)
    bad=copy.deepcopy(m); bad['budget'][key]=high
    if key == 'max_waves': bad['budget']['total_calls']=high
    assert run(bad,'--dry-run').returncode == 0, key
for key, low, high in [('concurrency',1,4),('timeout_s',1,3600),('max_artifact_bytes',1,1073741824)]:
    for value in (0, high+1, 'bad'):
        bad=copy.deepcopy(m); bad['budget']['verifier'][key]=value
        assert run(bad,'--dry-run').returncode == 2, (key,value)
    bad=copy.deepcopy(m); bad['budget']['verifier'][key]=high
    assert run(bad,'--dry-run').returncode == 0, key
for key in ('groups','candidate_formats'):
    bad=copy.deepcopy(m); bad[key]=[]
    assert run(bad,'--dry-run').returncode == 2, key
for value in (0, 9, 'bad'):
    bad=copy.deepcopy(m); bad['groups'][0]['k']=value
    assert run(bad,'--dry-run').returncode == 2
bad=copy.deepcopy(m); bad['groups'][0]['k']=8
assert run(bad,'--dry-run').returncode == 0
for field, high in [('calls',200),('concurrency',16)]:
    for value in (0, high+1, 'bad'):
        bad=copy.deepcopy(m); bad['budget']['per_provider']={'codex':{'calls':1,'concurrency':1}}
        bad['budget']['per_provider']['codex'][field]=value
        assert run(bad,'--dry-run').returncode == 2
    bad=copy.deepcopy(m); bad['budget']['per_provider']={'codex':{'calls':1,'concurrency':1}}
    bad['budget']['per_provider']['codex'][field]=high
    assert run(bad,'--dry-run').returncode == 0
bad=copy.deepcopy(m); bad['verify']['inputs']=[{'path':'problem.txt','sha256':'0'*64}]
assert 'verify input digest mismatch' in run(bad,'--dry-run').stderr
bad=copy.deepcopy(m); bad['groups'][0]['routes']=[]
assert run(bad,'--dry-run').returncode == 2
bad=copy.deepcopy(m); bad['groups'][0]['routes'][0]['unexpected']=True
assert 'unknown key' in run(bad,'--dry-run').stderr
bad=copy.deepcopy(m); bad['budget']['per_provider']={'codex':{'calls':1,'concurrency':1}}
assert json.loads(run(bad,'--dry-run').stdout)['groups'][0]['routes'][0]['cap_source'] == 'provider'
dirty = subprocess.check_output(['git','-C',str(repo),'ls-files'],text=True).splitlines()[0]
tracked=repo/dirty
original=tracked.read_bytes(); tracked.write_bytes(original+b'changed')
assert 'campaign requires a clean tracked tree' in run(m).stderr
assert run(m,'--dry-run').returncode == 0
tracked.write_bytes(original)
tracked.write_bytes(original+b'staged')
subprocess.run(['git','-C',str(repo),'add','--',dirty],check=True)
assert 'campaign requires a clean tracked tree' in run(m).stderr
subprocess.run(['git','-C',str(repo),'reset','--',dirty],check=True,stdout=subprocess.DEVNULL)
tracked.write_bytes(original)
path.write_text(json.dumps(m))
r=subprocess.run(['bash',str(root/'scripts/goal-drive.sh'),'--repo',str(sub),'--campaign',str(path)],capture_output=True,text=True,env=env)
assert r.returncode == 3 and 'stopped (max_waves)' in r.stdout, (r.stdout, r.stderr)
assert not (sub/'.oms').exists()
r=run(m); assert r.returncode == 3 and 'stopped (max_waves)' in r.stdout, r.stdout
state=repo/'.oms/plan/campaigns'/out['campaign_id']
spec=importlib.util.spec_from_file_location('problem_campaign', root/'scripts/lib/problem_campaign.py')
module=importlib.util.module_from_spec(spec); spec.loader.exec_module(module)
ledger=module.Ledger(state)
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
    ids=list(pool.map(lambda _: attempt(ledger,'codex','seat'), range(4)))
assert sum(x.startswith('res_') for x in ids) == 1, ids
assert ledger.spent()['total_calls'] == 2
try:
    module.Ledger(state, dict(m['budget'], total_calls=200))
    raise AssertionError('caller budget accepted')
except TypeError:
    pass
assert module.Ledger(state).remaining()['total_calls'] == 0
ledger.budget['total_calls'] = 200
assert attempt(ledger,'codex','seat') == 'total_calls exhausted'
original_name=module.os.name
original_safe=module._durable.safe_regular
try:
    module.os.name='nt'
    module._durable.safe_regular=lambda _: False
    try:
        with module.locked(state): pass
        raise AssertionError('invalid lock accepted')
    except ValueError:
        pass
finally:
    module.os.name=original_name
    module._durable.safe_regular=original_safe
old_names=module.provider_names
module.provider_names=lambda: set()
assert module.Ledger(state).spent()['total_calls'] == 2
module.initialize(repo,m)
module.provider_names=old_names
manifest_file=state/'manifest.json'
original_manifest=manifest_file.read_bytes()
manifest_file.write_text(json.dumps(dict(m, budget=dict(m['budget'], total_calls=200))))
try:
    ledger.reserve('codex','seat')
    raise AssertionError('existing ledger ignored changed manifest')
except ValueError:
    pass
try:
    module.Ledger(state)
    raise AssertionError('tampered manifest accepted')
except ValueError:
    pass
manifest_file.write_bytes(original_manifest)
try:
    module.durable_call(module._durable.read_no_follow, str(state), str(state/'missing'), label='missing')
    raise AssertionError('durable error accepted')
except ValueError:
    pass
r=run(m); assert r.returncode == 3
rows=[json.loads(line) for line in (state/'events.jsonl').read_text().splitlines()]
assert rows[-1]['type'] == 'campaign_resumed' and ledger.remaining()['total_calls'] == 0
assert attempt(ledger,'codex','seat') == 'total_calls exhausted'
reservation = next(x for x in ids if x.startswith('res_'))
assert ledger.settle(reservation, 'done') is True
assert ledger.settle(reservation, 'done') is False
assert attempt(ledger,'codex','seat') == 'total_calls exhausted'
other=copy.deepcopy(m)
other['budget'].update(total_calls=4, max_concurrent=2, per_provider={'codex':{'calls':2,'concurrency':1}})
other['groups'][0]['routes'].append({'provider':'claude','model':'example'})
module.initialize(repo,other)
other_id=module.validate(repo,other)[0]['campaign_id']
limited=module.Ledger(repo/'.oms/plan/campaigns'/other_id)
a=limited.reserve('codex','seat')['id']
assert attempt(limited,'codex','seat') == 'provider concurrency exhausted'
assert limited.settle(a,'ok')
b=limited.reserve('codex','seat')['id']
assert attempt(limited,'codex','seat') == 'provider calls exhausted'
for bad_args in (('unknown','seat'),('codex','wrong')):
    try:
        limited.reserve(*bad_args)
        raise AssertionError('invalid reservation accepted')
    except module.BudgetRefused:
        raise AssertionError('invalid request is not a budget refusal')
    except ValueError:
        pass
v=limited.reserve('claude','verifier')['id']
assert attempt(limited,'claude','verifier') == 'max_concurrent exhausted'
assert limited.settle(b,'ok')
assert attempt(limited,'claude','verifier') == 'verifier concurrency exhausted'
problem.write_text('changed')
assert 'problem digest mismatch' in run(m).stderr
PY
  python3 -B - "$ROOT" "$TMP" <<'PY'
import importlib.util, json, pathlib, sys
from unittest import mock
root, tmp = map(pathlib.Path, sys.argv[1:])
spec = importlib.util.spec_from_file_location('campaign_lock_probe', root/'scripts/lib/problem_campaign.py')
mod = importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
directory = tmp/'campaign-lock-probe'; directory.mkdir()
manifest = {'budget': {}, 'groups': [{'routes': [{'provider': 'codex'}]}]}
raw = json.dumps(manifest, sort_keys=True, separators=(',', ':')).encode()
import hashlib
directory = directory/hashlib.sha256(raw).hexdigest()[:16]; directory.mkdir()
(directory/'manifest.json').write_bytes(raw)
start = {'type': 'campaign_started', 'budget': {}}
invalid = {'type': 'reservation', 'id': 'res_' + 'a'*32, 'provider': [], 'kind': 'seat'}
(directory/'events.jsonl').write_text('\n'.join(map(json.dumps, (start, invalid)))+'\n')
try:
    mod.Ledger(directory).spent()
    raise AssertionError('malformed event accepted')
except ValueError:
    pass
import os
if os.name == 'nt':
    sys.exit(0)
import fcntl
real_flock = fcntl.flock
def replace_lock(fd, action):
    if action == fcntl.LOCK_EX:
        os.unlink(directory/'events.lock')
        (directory/'events.lock').touch()
    return real_flock(fd, action)
with mock.patch.object(fcntl, 'flock', replace_lock):
    try:
        with mod.locked(directory):
            raise AssertionError('replaced lock accepted')
    except ValueError:
        pass
def replace_directory(fd, action):
    if action == fcntl.LOCK_EX:
        directory.rename(directory.with_name('moved'))
        directory.mkdir()
        (directory/'events.lock').touch()
    return real_flock(fd, action)
with mock.patch.object(fcntl, 'flock', replace_directory):
    try:
        with mod.locked(directory):
            raise AssertionError('replaced directory accepted')
    except ValueError:
        pass
PY
  local waves="$TMP/campaign-waves"
  make_committed_repo "$waves"
  python3 -B - "$ROOT" "$waves" "$stub" <<'PY'
import copy, hashlib, json, os, pathlib, subprocess, sys
root, repo, stub = map(pathlib.Path, sys.argv[1:])
def git(*a, cwd=repo): return subprocess.check_output(['git', '-C', str(cwd), *a], text=True).strip()
(repo/'problem.txt').write_text('make target.txt say fixed\n')
(repo/'target.txt').write_text('broken\n')
(repo/'check.sh').write_text('grep -qx fixed target.txt\n')
git('add', '.')
git('-c', 'user.email=t@example.com', '-c', 'user.name=T', 'commit', '-qm', 'campaign files')
def sha(name): return hashlib.sha256((repo/name).read_bytes()).hexdigest()
def diff(name, old, new): return 'diff --git a/%s b/%s\n--- a/%s\n+++ b/%s\n@@ -1 +1 @@\n-%s\n+%s\n' % (name, name, name, name, old, new)
(stub/'pass.patch').write_text(diff('target.txt', 'broken', 'fixed'))
(stub/'wrong.patch').write_text(diff('target.txt', 'broken', 'other'))
(stub/'tamper.patch').write_text(diff('check.sh', 'grep -qx fixed target.txt', 'true'))
env = {k: v for k, v in os.environ.items() if k not in ('OMS_HARNESS_CHILD', 'OMS_HARNESS_DELEGATE_DEPTH')}
env.update(PATH=str(stub/'bin')+':/usr/bin:/bin', HOME=str(stub/'home'), NVM_DIR=str(stub/'home/.nvm'), OMS_DELEGATE_WORKTREE_ROOT=str(stub/'managed'))
def manifest(groups, **budget):
    b = {'max_concurrent': 2, 'total_calls': 8, 'deadline_s': 600, 'max_waves': 2, 'stall_waves': 2,
         'verifier': {'concurrency': 2, 'timeout_s': 60, 'max_artifact_bytes': 4096}}
    b.update(budget)
    return {'problem': {'file': 'problem.txt', 'sha256': sha('problem.txt')}, 'base': git('rev-parse', 'HEAD'),
            'verify': {'command': 'bash check.sh', 'timeout_s': 60, 'inputs': [{'path': 'check.sh', 'sha256': sha('check.sh')}]},
            'candidate_formats': ['patch'], 'groups': groups, 'budget': b}
def group(gid, marker, model, k=1): return {'id': gid, 'formulation': marker, 'k': k, 'routes': [{'provider': 'codex', 'model': model}]}
def go(m, extra_env=None, where=repo, *args):
    file = where/'wave-campaign.json'
    file.write_text(json.dumps(m))
    e = dict(env, **(extra_env or {}))
    return subprocess.run(['bash', str(root/'scripts/goal-drive.sh'), '--repo', str(where), '--campaign', str(file), *args], capture_output=True, text=True, env=e)
def rows(m, where=repo):
    cid = hashlib.sha256(json.dumps(m, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()).hexdigest()[:16]
    return [json.loads(l) for l in (where/'.oms/plan/campaigns'/cid/'events.jsonl').read_text().splitlines()]
def calls(): return len((stub/'calls').read_text().split()) if (stub/'calls').exists() else 0
def kinds(r): return [x['type'] for x in r]

# A live ledger is readable without taking its events lock and without writes.
import importlib.util
spec = importlib.util.spec_from_file_location('pc_status', root/'scripts/lib/problem_campaign.py')
pc_status = importlib.util.module_from_spec(spec); spec.loader.exec_module(pc_status)
live = manifest([group('a', 'MARK_WRONG', 'live')])
directory, _ = pc_status.initialize(repo, live, repo)
before_events = (directory/'events.jsonl').read_bytes()
with pc_status.locked(directory):
    r = go(live, {'OMS_HARNESS_CHILD': '1'}, repo, '--status')
assert r.returncode == 0 and 'running' in r.stdout and 'last_event=campaign_started' in r.stdout, (r.stdout, r.stderr)
assert (directory/'events.jsonl').read_bytes() == before_events

# Two groups: one route fails (seat_failed, skipped), the other solves. Exit 0, winner recorded.
solve = manifest([group('a', 'MARK_BROKEN', 'm1'), group('b', 'MARK_PASS', 'm2')])
before = calls()
r = go(solve); assert r.returncode == 0, (r.stdout, r.stderr)
ev = rows(solve)
failed = [x for x in ev if x['type'] == 'seat_failed']
assert len(failed) == 1 and failed[0]['group'] == 'a' and 'ts' in failed[0], failed
verdict = [x for x in ev if x['type'] == 'candidate_verdict']
assert [x['verdict'] for x in verdict] == ['pass'], verdict
done = [x for x in ev if x['type'] == 'campaign_solved']
assert len(done) == 1 and done[0]['candidate'] == verdict[0]['id'] and len(done[0]['sha256']) == 64, done
assert 'solved' in r.stdout and done[0]['candidate'] in r.stdout, r.stdout
assert 'final_receipt' in done[0] and 'oms patch-admit --repo' in r.stdout, (done, r.stdout)
assert go(solve, {'OMS_HARNESS_CHILD': '1'}, repo, '--status').returncode == 0
assert ev[0]['type'] == 'campaign_started' and 'started_at' in ev[0]
assert 'scratch' not in git('worktree', 'list') and len(git('worktree', 'list').splitlines()) == 1
spent = calls(); assert spent - before == 2, (before, spent)
# Resume of a solved campaign re-prints the winner and spends nothing.
r = go(solve); assert r.returncode == 0 and done[0]['candidate'] in r.stdout, r.stdout
assert calls() == spent and kinds(rows(solve)).count('reservation') == 2

# Status must not start a campaign or require parent authority.
missing = manifest([group('a', 'MARK_WRONG', 'missing')])
r = go(missing, {'OMS_HARNESS_CHILD': '1'}, repo, '--status')
assert r.returncode == 2 and 'unknown argument' not in r.stderr, r.stderr
assert go(solve, None, repo, '--status', '--dry-run').returncode == 2
cid = hashlib.sha256(json.dumps(solve, sort_keys=True, separators=(',', ':')).encode()).hexdigest()[:16]
handoff = json.loads((repo/'.oms/plan/campaigns'/cid/'handoff.json').read_text())
assert handoff['sha256'] == done[0]['sha256'] and handoff['final_receipt']['verdict'] == 'pass'
assert handoff['command'] in r.stdout or handoff['command'] in go(solve, None, repo, '--status').stdout

# Malformed and oversized consolidations are counted and the next wave runs.
for mode, accepted, rejected in [('surrogate', 1, 1), ('deep', 0, 1), ('many', 32, 5968)]:
    (stub/'mode').write_text(mode)
    m = manifest([group('a', 'MARK_WRONG', mode)], max_waves=2, stall_waves=2)
    m['consolidator'] = {'provider': 'codex', 'model': 'm2'}
    r = go(m); assert r.returncode == 3, (mode, r.stdout, r.stderr)
    ev = rows(m)
    records = [x for x in ev if x['type'] == 'consolidation_recorded']
    assert len(records) == 1 and len(records[0]['claims']) == accepted and records[0]['rejected_count'] == rejected, records
    assert sum(x['type'] == 'wave_completed' for x in ev) == 2
(stub/'mode').unlink()

# Cite only receipts present in the ledger and feed accepted notes into wave two.
cons = manifest([group('a', 'MARK_WRONG', 'm1')], max_waves=2, stall_waves=2)
cons['consolidator'] = {'provider': 'codex', 'model': 'm2'}
r = go(cons); assert r.returncode == 3, (r.stdout, r.stderr)
ev = rows(cons)
assert sum(x.get('kind') == 'consolidator' for x in ev if x['type'] == 'reservation') == 1
records = [x for x in ev if x['type'] == 'consolidation_recorded']
assert len(records) == 1 and records[0]['rejected_count'] == 2 and len(records[0]['claims']) == 1, records
cid = hashlib.sha256(json.dumps(cons, sort_keys=True, separators=(',', ':')).encode()).hexdigest()[:16]
prompt = (repo/'.oms/artifacts/campaigns'/cid/'seats/w2-a-0/prompt.md').read_text()
assert 'Unverified notes' in prompt and 'useful note' in prompt and 'bad id' not in prompt
assert 'Earlier candidates of this approach (verdicts only)' not in prompt
assert not any(x.get('kind') == 'consolidator' for x in rows(solve) if x['type'] == 'reservation')

# No call is useful at a stall or when the seat allowance is already exhausted.
for stop_budget, reason in [({'stall_waves': 1}, 'stall'), ({'total_calls': 3}, 'budget')]:
    stopped = manifest([group('a', 'MARK_WRONG', reason)], max_waves=2, **stop_budget)
    stopped['consolidator'] = {'provider': 'codex', 'model': 'm2'}
    r = go(stopped); assert r.returncode == 3, (r.stdout, r.stderr)
    ev = rows(stopped)
    assert not any(x.get('kind') == 'consolidator' for x in ev if x['type'] == 'reservation'), ev
    assert ev[-1]['reason'] == reason, ev[-1]

last = manifest([group('a', 'MARK_WRONG', 'last')], max_waves=1, stall_waves=1)
last['consolidator'] = {'provider': 'codex', 'model': 'm2'}
assert go(last).returncode == 3
assert not any(x.get('kind') == 'consolidator' for x in rows(last) if x['type'] == 'reservation')
limited = manifest([group('a', 'MARK_WRONG', 'limited')], max_waves=2, stall_waves=2,
                   per_provider={'codex': {'calls': 1, 'concurrency': 1}})
limited['consolidator'] = {'provider': 'codex', 'model': 'm2'}
assert go(limited).returncode == 3
assert not any(x.get('kind') == 'consolidator' for x in rows(limited) if x['type'] == 'reservation')

# A deadline crossed by the wave cannot trigger another provider call.
from unittest import mock
deadline = manifest([group('a', 'MARK_WRONG', 'deadline')])
deadline['consolidator'] = {'provider': 'codex', 'model': 'm2'}
deadline_dir, _ = pc_status.initialize(repo, deadline, repo)
with mock.patch.object(pc_status.Controller, 'wave', return_value=None), \
     mock.patch.object(pc_status.Controller, 'remaining', side_effect=[1, 0]):
    assert pc_status.run_campaign(repo, repo, deadline_dir, deadline, pc_status.time.time()) == 3
ev = pc_status.Ledger(deadline_dir).events()
assert ev[-1]['reason'] == 'deadline' and not any(x['type'] == 'reservation' for x in ev)

# A failed consolidator is recorded and does not stop the next wave.
failed_cons = manifest([group('a', 'MARK_WRONG', 'm1')], max_waves=2, stall_waves=2)
failed_cons['consolidator'] = {'provider': 'claude', 'model': 'm2'}
r = go(failed_cons); assert r.returncode == 3, (r.stdout, r.stderr)
ev = rows(failed_cons)
assert sum(x['type'] == 'wave_completed' for x in ev) == 2
assert any(x['type'] == 'seat_failed' and x['group'] == 'consolidator' for x in ev)

# Validate empty, malformed and boundary-size claims using ledger-bound receipts.
claim_manifest = manifest([group('a', 'MARK_WRONG', 'claims')], total_calls=20)
claim_manifest['consolidator'] = {'provider': 'codex', 'model': 'claims'}
claim_dir, _ = pc_status.initialize(repo, claim_manifest, repo)
ctl = pc_status.Controller(repo, repo, claim_dir, claim_manifest)
ctl.ledger.emit('candidate_recorded', id='cand_test')
ctl.ledger.emit('candidate_verdict', id='cand_test', receipt_sha256='a'*64)
for index, (body, accepted, rejected) in enumerate([
        ('[]', 0, 0), ('not json', 0, 1),
        (json.dumps([{'text':'x'*4096,'candidates':['cand_test'],'receipts':['a'*64]}]), 1, 0),
        (json.dumps([{'text':'x'*4097,'candidates':['cand_test'],'receipts':['a'*64]}]), 0, 1)]):
    ctl.call = lambda *args, body=body: ('ok', '```json\n'+body+'\n```\n')
    ctl.consolidate(index+1, pc_status.time.time())
    row = [x for x in ctl.ledger.events() if x['type'] == 'consolidation_recorded'][-1]
    assert len(row['claims']) == accepted and row['rejected_count'] == rejected, row

good = {'text':'x', 'candidates':['cand_test'], 'receipts':['a'*64]}
for count in (0, 32, 33):
    body = json.dumps([good]*count)
    ctl.call = lambda *args, body=body: ('ok', '```json\n'+body+'\n```\n')
    ctl.consolidate(10+count, pc_status.time.time())
    row = [x for x in ctl.ledger.events() if x['type'] == 'consolidation_recorded'][-1]
    assert len(row['claims']) == min(count, 32) and row['rejected_count'] == max(0, count-32), row
# The serialized note budget includes citation bytes and JSON framing.
base_claims = [dict(good, text='') for _ in range(4)]
room = pc_status.DIGEST_CAP - len(json.dumps(base_claims, ensure_ascii=False).encode())
for item in base_claims:
    amount = min(4096, room)
    item['text'] = 'x'*amount
    room -= amount
assert room == 0
for extra, accepted, rejected in [(0, 4, 0), (1, 3, 1)]:
    sample = copy.deepcopy(base_claims)
    sample[-1]['text'] += 'x'*extra
    ctl.call = lambda *args, sample=sample: ('ok', '```json\n'+json.dumps(sample)+'\n```\n')
    ctl.consolidate(40+extra, pc_status.time.time())
    row = [x for x in ctl.ledger.events() if x['type'] == 'consolidation_recorded'][-1]
    assert len(row['claims']) == accepted and row['rejected_count'] == rejected, row

large = dict(good, candidates=['cand_test']*300, receipts=['a'*64]*300)
ctl.call = lambda *args: ('ok', '```json\n'+json.dumps([large])+'\n```\n')
ctl.consolidate(44, pc_status.time.time())
row = [x for x in ctl.ledger.events() if x['type'] == 'consolidation_recorded'][-1]
assert row['claims'] == [] and row['rejected_count'] == 1

def broken_call(*args):
    raise ValueError('failure')
ctl.call = broken_call
ctl.consolidate(45, pc_status.time.time())
assert any(x['type'] == 'seat_failed' and x.get('wave') == 45 for x in ctl.ledger.events())
legacy = {'type':'consolidation_recorded', 'claims':[dict(good, text='x'*4096)]*10}
prompt, _ = ctl.prompt(claim_manifest['groups'][0], [legacy])
notes = prompt.split('# Unverified notes with citations\n', 1)[1].strip()
assert len(notes.encode()) <= pc_status.DIGEST_CAP and len(json.loads(notes)) == 3

# The second verification consumes an external fixture already removed by the first.
marker = stub/'one-pass'; marker.touch()
retry = manifest([group('a', 'MARK_PASS', 'm1')], max_waves=1, stall_waves=1)
retry['verify']['command'] = 'test -f %s && rm %s && bash check.sh' % (marker, marker)
r = go(retry); assert r.returncode == 3, (r.stdout, r.stderr)
ev = rows(retry)
assert 'final_verify_failed' in kinds(ev) and 'campaign_solved' not in kinds(ev), ev

# A patch that edits a pinned verifier input is refused; stall_waves ends it.
tamper = manifest([group('a', 'MARK_TAMPER', 'm1')], max_waves=3, stall_waves=2)
r = go(tamper); assert r.returncode == 3 and 'stopped (stall)' in r.stdout, (r.stdout, r.stderr)
ev = rows(tamper)
assert [(x['verdict'], x['reason']) for x in ev if x['type'] == 'candidate_verdict'] == [('error', 'verifier-tamper')] * 2
assert kinds(ev).count('wave_completed') == 2 and ev[-1]['type'] == 'campaign_stopped' and ev[-1]['reason'] == 'stall'
spent = calls()
r = go(tamper); assert r.returncode == 3 and calls() == spent and kinds(rows(tamper)).count('reservation') == 2

# Seat budget (total_calls minus one reserved consolidator per wave) ends the campaign with exit 3.
cap = manifest([group('a', 'MARK_WRONG', 'm1', k=3)], total_calls=3, max_waves=1, stall_waves=1, max_concurrent=3)
r = go(cap); assert r.returncode == 3 and 'stopped (budget)' in r.stdout, (r.stdout, r.stderr)
ev = rows(cap)
assert kinds(ev).count('reservation') == 2 and 'budget_exhausted' in kinds(ev) and ev[-1]['reason'] == 'budget'
assert [x['verdict'] for x in ev if x['type'] == 'candidate_verdict'] == ['fail', 'fail']

# A verify command that outlives its timeout (with a grandchild) is killed and recorded.
slow = manifest([group('a', 'MARK_WRONG', 'm3')], max_waves=1, stall_waves=1)
slow['verify'].update(command='sleep 30 & sleep 30', timeout_s=1)
r = go(slow); assert r.returncode == 3, (r.stdout, r.stderr)
assert [x['verdict'] for x in rows(slow) if x['type'] == 'candidate_verdict'] == ['timeout']

# A model name agent-call would reject is refused at validation; an unrunnable route fails its seat once.
bad = manifest([group('a', 'MARK_WRONG', 'provider-default')])
assert 'provider-default' in go(bad, None, repo, '--dry-run').stderr
bad['groups'][0]['routes'][0]['model'] = 'x' * 161
assert go(bad, None, repo, '--dry-run').returncode == 2
bad['groups'][0]['routes'][0]['model'] = 'x' * 160
assert go(bad, None, repo, '--dry-run').returncode == 0
lost = manifest([group('a', 'MARK_WRONG', 'm1')], max_waves=2, stall_waves=2)
lost['groups'][0]['routes'] = [{'provider': 'claude', 'model': 'm1'}]
before = calls()
r = go(lost); assert r.returncode == 3 and 'routes_exhausted' in r.stdout, (r.stdout, r.stderr)
ev = rows(lost); assert kinds(ev).count('seat_failed') == 1 and kinds(ev).count('reservation') == 1, kinds(ev)
r = go(lost); assert r.returncode == 3 and kinds(rows(lost)).count('reservation') == 1 and calls() == before

# A core-era ledger (no started_at, resume rows without ts) resumes and runs.
import importlib.util
spec = importlib.util.spec_from_file_location('pc', root/'scripts/lib/problem_campaign.py')
pc = importlib.util.module_from_spec(spec); spec.loader.exec_module(pc)
old = manifest([group('a', 'MARK_PASS', 'm5')])
directory, _ = pc.initialize(repo, old, repo)
lines = [json.loads(l) for l in (directory/'events.jsonl').read_text().splitlines()]
lines[0].pop('started_at'); lines[0].pop('ts'); lines.append({'type': 'campaign_resumed'})
(directory/'events.jsonl').write_text(''.join(json.dumps(x, sort_keys=True, separators=(',', ':'))+'\n' for x in lines))
r = go(old); assert r.returncode == 0 and 'solved' in r.stdout, (r.stdout, r.stderr)

# A harness child is refused before any ledger row exists.
child = manifest([group('a', 'MARK_WRONG', 'm9')])
r = go(child, {'OMS_HARNESS_CHILD': '1'}); assert r.returncode == 2 and 'harness child' in r.stderr, r.stderr
assert not (repo/'.oms/plan/campaigns').joinpath(hashlib.sha256(json.dumps(child, sort_keys=True, separators=(',', ':')).encode()).hexdigest()[:16]).exists()
r = go(child, {'OMS_HARNESS_DELEGATE_DEPTH': '1'}); assert r.returncode == 2 and 'harness child' in r.stderr
r = subprocess.run([sys.executable, '-B', str(root/'scripts/lib/problem_campaign.py'), '--repo', str(repo), '--campaign', str(repo/'wave-campaign.json')], capture_output=True, text=True, env=env)
assert r.returncode == 2 and '--state-repo is required' in r.stderr, r.stderr

# Route validation: pi needs public_data, cursor has no effort, effort must be a known value.
bad = copy.deepcopy(child); bad['groups'][0]['routes'] = [{'provider': 'pi', 'model': 'x'}]
assert 'public_data' in go(bad, None, repo, '--dry-run').stderr
bad['public_data'] = True; assert go(bad, None, repo, '--dry-run').returncode == 0
bad['groups'][0]['routes'] = [{'provider': 'cursor', 'model': 'x', 'effort': 'high'}]
assert 'no effort control' in go(bad, None, repo, '--dry-run').stderr
bad['groups'][0]['routes'] = [{'provider': 'codex', 'model': 'x', 'effort': 'turbo'}]
assert 'route effort' in go(bad, None, repo, '--dry-run').stderr
bad['groups'][0]['routes'] = [{'provider': 'codex', 'model': 'x', 'effort': 'high'}]
assert go(bad, None, repo, '--dry-run').returncode == 0

# A scratch checkout shares the owner checkout's ledger.
scratch = pathlib.Path(subprocess.check_output(['bash', str(root/'scripts/scratch-worktree.sh'), 'add', '--repo', str(repo), '--owner-pid', str(os.getpid())], text=True, env=env).strip())
try:
    r = go(solve, {'OMS_HARNESS_CHILD': '1'}, scratch, '--status')
    assert r.returncode == 0 and done[0]['candidate'] in r.stdout, (r.stdout, r.stderr)
    linked = manifest([group('a', 'MARK_NONE', 'm1')], max_waves=1, stall_waves=1)
    r = go(linked, None, scratch); assert r.returncode == 3, (r.stdout, r.stderr)
    assert 'candidate_rejected' in kinds(rows(linked)) and not (scratch/'.oms/plan/campaigns').exists()
finally:
    subprocess.run(['bash', str(root/'scripts/scratch-worktree.sh'), 'remove', '--repo', str(repo), '--force', str(scratch)], env=env, capture_output=True)
PY
}

test_goal_drive_silences_foreign_closed_intents() {
  local project="$TMP/gd-foreign-intents" out rc=0
  make_committed_repo "$project"
  "$ROOT/scripts/agent-plan.sh" --repo "$project" init --goal silence --accept true >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" add --id t1 --title silence >/dev/null
  "$ROOT/scripts/agent-plan.sh" --repo "$project" block --id t1 --reason fixture >/dev/null
  python3 - "$project" <<'PY'
import json, pathlib, subprocess, sys
repo = pathlib.Path(sys.argv[1])
base = subprocess.check_output(["git", "-C", str(repo), "rev-parse", "HEAD"], text=True).strip()
row = {"schema": 1, "kind": "commit-intent", "ts": "2026-09-04T00:00:00Z", "cycle": 1,
       "task_id": "t1", "base_sha": base, "head_ref": "refs/heads/main", "reason": "fixture"}
rows = [dict(row, run_id="gd-foreign", intent_id="foreign-landed", phase="prepared"),
        dict(row, run_id="gd-foreign", intent_id="foreign-landed", phase="landed"),
        dict(row, intent_id="legacy-bad", phase="prepared")]
with open(repo / ".oms/plan/progress.jsonl", "w", encoding="utf-8") as fh:
    for r in rows:
        fh.write(json.dumps(r) + "\n")
PY
  out="$("$ROOT/scripts/goal-drive.sh" --repo "$project" --max-cycles 1 2>&1)" || rc=$?
  contains "$out" 'ignored invalid commit intent legacy-bad' ||
    fail "a current-run (legacy) invalid intent must still warn (rc=$rc): $out"
  if contains "$out" 'foreign-landed'; then
    fail "a closed foreign-run chain must stay silent: $out"
  fi
}

test_plan_snapshot_is_nonvacuous_across_state_runtime_and_goal_drive() {
  local project="$TMP/nonvacuous-plan"
  local plan="$ROOT/scripts/agent-plan.sh"
  local snapshot state_json runtime_json out rc

  make_committed_repo "$project"
  "$plan" --repo "$project" init --goal "empty cannot be done" --accept true >/dev/null

  snapshot="$("$plan" --repo "$project" status --json)" ||
    fail "empty plan status JSON failed"
  printf '%s' "$snapshot" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["present"] is True, row
assert row["task_count"] == 0 and row["nonempty"] is False, row
assert row["all_done"] is False, row
' || fail "canonical plan snapshot treated zero tasks as done: $snapshot"

  state_json="$("$ROOT/scripts/state.sh" --repo "$project" --json)"
  runtime_json="$("$ROOT/scripts/runtime.sh" --repo "$project" envelope show)"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)["plan"]
assert row["present"] is True, row
assert row["task_count"] == 0 and row["nonempty"] is False, row
assert row["all_done"] is False, row
' || fail "repo state disagreed on empty plan semantics: $state_json"
  printf '%s' "$runtime_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)["plan"]
assert row["present"] is True, row
assert row["task_count"] == 0 and row["nonempty"] is False, row
assert row["all_done"] is False, row
' || fail "runtime disagreed on empty plan semantics: $runtime_json"

  rc=0
  out="$("$ROOT/scripts/goal-drive.sh" --repo "$project" --max-cycles 1 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "goal-drive accepted a zero-task plan (rc=$rc): $out"
  contains "$out" 'no tasks' ||
    fail "zero-task refusal did not explain the missing work contract: $out"
  if [ -f "$project/.oms/plan/progress.jsonl" ] &&
    grep -Eq '"status"[[:space:]]*:[[:space:]]*"(pass|done)"' \
      "$project/.oms/plan/progress.jsonl"; then
    fail "zero-task plan wrote successful acceptance/completion evidence"
  fi
  runtime_json="$("$ROOT/scripts/runtime.sh" --repo "$project" envelope show)"
  printf '%s' "$runtime_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
actions = [item["id"] for item in row["next_actions"]]
assert row["evidence"]["complete"] is False, row["evidence"]
assert "record_verified_completion" not in actions, actions
assert "repair_empty_plan" in actions, actions
' || fail "runtime allowed an empty plan to become verified completion: $runtime_json"
}

test_project_state_parser_is_shared_and_rejects_typos() {
  local project="$TMP/project-state-parser"
  local out rc

  make_committed_repo "$project"
  "$ROOT/scripts/apply-project-template.sh" general "$project" >/dev/null
  sed -i 's/^- State: draft/- State: confirmd/; s/^- Test:$/- Test: true/; s/^- Success criteria:$/- Success criteria: checks pass/' \
    "$project/PROJECT.md"

  rc=0
  out="$("$ROOT/scripts/project-doctor.sh" --strict "$project" 2>&1)" || rc=$?
  [ "$rc" = 1 ] || fail "strict project-doctor accepted an invalid State (rc=$rc): $out"
  contains "$out" 'invalid' ||
    fail "project-doctor did not name the invalid State: $out"

  out="$("$ROOT/scripts/init.sh" --repo "$project" --no-private)" ||
    fail "init should diagnose an invalid State without crashing"
  contains "$out" 'requires confirmation' ||
    fail "init presented an invalid State as an in-place contract: $out"

  rc=0
  out="$("$ROOT/scripts/plan-from-spec.sh" --repo "$project" 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "plan-from-spec accepted an invalid State (rc=$rc): $out"
  contains "$out" 'invalid' ||
    fail "plan-from-spec did not name the invalid State: $out"

  rc=0
  out="$("$ROOT/scripts/autopilot.sh" --repo "$project" --base main propose 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "autopilot accepted an invalid State (rc=$rc): $out"
  contains "$out" 'invalid' ||
    fail "autopilot did not name the invalid State: $out"

  sed -i 's/^- State: confirmd/- State: active/' "$project/PROJECT.md"
  out="$("$ROOT/scripts/init.sh" --repo "$project" --no-private)" ||
    fail "init rejected legacy active State"
  contains "$out" 'spec=active' ||
    fail "init changed the public legacy active spelling: $out"
  if contains "$out" 'legacy-active'; then
    fail "init leaked the internal typed legacy-active verdict: $out"
  fi
  out="$("$ROOT/scripts/project-doctor.sh" "$project")" ||
    fail "project-doctor rejected legacy active State"
  contains "$out" 'PROJECT.md state: active' ||
    fail "project-doctor changed the public legacy active spelling: $out"

  sed -i 's/^- Scope:$/- Scope: src\/, tests\//' "$project/PROJECT.md"
  scope="$("$ROOT/scripts/plan-from-spec.sh" --repo "$project" --scope-only 2>&1)" ||
    fail "the planner's Scope parser was not exposed to autopilot: $scope"
  contains "$scope" 'src/' || fail "Scope parser lost the declared paths: $scope"

  sed -i 's@^- Scope:.*@- Scope: ../escape@' "$project/PROJECT.md"
  git -C "$project" add -f PROJECT.md && git -C "$project" commit -qm 'test: invalid scope fixture' ||
    fail "could not prepare a clean autopilot scope fixture"
  rc=0
  out="$("$ROOT/scripts/autopilot.sh" --repo "$project" propose 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "autopilot accepted an unsafe default Scope (rc=$rc): $out"
  contains "$out" 'PROJECT.md Scope is not a safe --allowed path list; pass --allowed explicitly' ||
    fail "unsafe default Scope used the wrong refusal: $out"
  # A glob Scope could grant the whole repository; the derived default accepts plain paths only.
  sed -i 's@^- Scope:.*@- Scope: src/, *@' "$project/PROJECT.md"
  git -C "$project" commit -qam 'test: glob scope fixture' || fail "could not prepare a glob scope fixture"
  rc=0
  out="$("$ROOT/scripts/autopilot.sh" --repo "$project" propose 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "autopilot accepted a glob default Scope (rc=$rc): $out"
  contains "$out" 'PROJECT.md Scope is not a safe --allowed path list; pass --allowed explicitly' ||
    fail "glob default Scope used the wrong refusal: $out"

  git -C "$project" checkout -q --detach HEAD || fail "could not detach the fixture"
  rc=0
  out="$("$ROOT/scripts/autopilot.sh" --repo "$project" --allowed src propose 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "autopilot accepted a detached default base (rc=$rc): $out"
  contains "$out" 'propose requires --base so its continuation is executable' ||
    fail "detached HEAD used the wrong base refusal: $out"

  rc=0
  out="$("$ROOT/scripts/autopilot.sh" --repo "$project" --base 'invalid branch' \
    --allowed src propose 2>&1)" || rc=$?
  [ "$rc" = 2 ] || fail "autopilot accepted an invalid explicit base (rc=$rc): $out"
  contains "$out" 'base: invalid branch (explicit)' ||
    fail "explicit base was not reported as authoritative: $out"
  contains "$out" '--base is not a valid branch name' ||
    fail "explicit base was not validated: $out"
}

test_autopilot_bound_plan_uses_reviewed_envelope_without_scope_default() {
  local mode project planner out rc

  for mode in accepted remainder; do
    project="$TMP/autopilot-bound-envelope-$mode"
    make_committed_repo "$project"
    printf '/.oms/\n' > "$project/.gitignore"
    cat > "$project/PROJECT.md" <<'EOF'
# PROJECT.md

## Status

- State: confirmed

## Project

- Goal: finish the bounded feature
- Scope: src/, tests/
- Non-goals: release

## Commands

- Test: true

## Verification

- Required checks: true
- Required check files: PROJECT.md
EOF
    git -C "$project" add .gitignore PROJECT.md
    git -C "$project" -c user.email=test@example.com -c user.name='Test User' \
      commit -qm 'test: bound autopilot fixture'
    mkdir -p "$project/.oms/plan"
    OMS_T_ACCEPT="$([ "$mode" = accepted ] && echo true || echo false)" \
      python3 - "$project" <<'PY'
import hashlib, json, os, pathlib, sys
repo = pathlib.Path(sys.argv[1])
spec = (repo / "PROJECT.md").read_bytes()
digest = hashlib.sha256(spec).hexdigest()
now = "2026-10-21T00:00:00Z"
task = {
    "id": "t1", "title": "feat: initial", "state": "done",
    "depends": [], "allowed_paths": ["src/"], "forbidden_paths": [],
    "verify": "true", "role": "", "provider": "codex", "ttl": "",
    "artifact": "artifact", "patch": "patch", "reason": "",
    "executor_id": "", "executor_soul_sha256": "", "lease_epoch": 1,
    "lease_id": "lease", "review_lease_id": "lease", "repair_count": 0,
    "repair_artifact": "", "created": now, "updated": now,
}
plan = {
    "schema": 3, "goal": "finish the bounded feature",
    "accept": os.environ["OMS_T_ACCEPT"],
    "project_contract": {
        "schema": 1, "spec_sha256": digest,
        "allowed_envelope": ["src"],
        "acceptance_files": ["PROJECT.md"],
        "acceptance_manifest": [{"path": "PROJECT.md", "sha256": digest}],
    },
    "tasks": {"t1": task},
}
with (repo / ".oms/plan/tasks.json").open("w", encoding="utf-8") as handle:
    json.dump(plan, handle)
    handle.write("\n")
PY

    if [ "$mode" = accepted ]; then
      rc=0
      out="$("$ROOT/scripts/autopilot.sh" --repo "$project" propose 2>&1)" || rc=$?
      [ "$rc" = 0 ] || fail "bound accepted plan failed without --allowed ($rc): $out"
      contains "$out" 'acceptance already passes; no remainder proposal is needed' ||
        fail "bound accepted plan did not exit on passing acceptance: $out"
    else
      planner="$TMP/autopilot-fake-plan-from-spec"
      cat > "$planner" <<'EOF'
#!/usr/bin/env bash
set -eu
repo=""
while [ "$#" -gt 0 ]; do
  case "$1" in
    --repo) repo="$2"; shift 2 ;;
    *) shift ;;
  esac
done
proposal="$repo/.oms/plan/proposal-r1.json"
printf '{}\n' > "$proposal"
digest="$(python3 -c 'import hashlib,sys; print(hashlib.sha256(open(sys.argv[1], "rb").read()).hexdigest())' "$proposal")"
printf 'plan-from-spec: proposed 1 task(s) -> %s\n' "$proposal"
printf 'plan-from-spec: proposal sha256: %s\n' "$digest"
EOF
      chmod +x "$planner"
      rc=0
      out="$(OMS_AUTOPILOT_PLAN_FROM_SPEC="$planner" \
        "$ROOT/scripts/autopilot.sh" --repo "$project" propose 2>&1)" || rc=$?
      [ "$rc" = 4 ] || fail "bound remainder proposal failed without --allowed ($rc): $out"
      contains "$out" 'proposal awaits parent-agent review' ||
        fail "bound unfinished acceptance did not reach the remainder proposal: $out"
    fi
    contains "$out" 'allowed: src (reviewed plan envelope)' ||
      fail "bound plan did not report its reviewed envelope: $out"
    if contains "$out" '--allowed cannot widen or replace the reviewed plan envelope'; then
      fail "Scope default was treated as a replacement for the bound envelope: $out"
    fi
  done
}

test_autopilot_scope_default_requires_an_explicit_safe_envelope() {
  local project planner marker kind scope expected out rc
  project="$TMP/autopilot-invalid-scope"
  planner="$TMP/autopilot-scope-planner"
  marker="$TMP/autopilot-scope-planner-called"
  make_committed_repo "$project"
  printf '/.oms/\n' > "$project/.gitignore"
  cat > "$project/PROJECT.md" <<'EOF'
# PROJECT.md

## Status

- State: confirmed

## Project

- Goal: finish the bounded feature
- Scope: src/, tests/
- Non-goals: release

## Commands

- Test: true

## Verification

- Required checks: true
- Required check files: PROJECT.md
EOF
  git -C "$project" add .gitignore PROJECT.md
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' \
    commit -qm 'test: invalid autopilot scope fixture'
  cat > "$planner" <<'EOF'
#!/usr/bin/env bash
for arg in "$@"; do
  if [ "$arg" = --scope-only ]; then
    exec "$OMS_TEST_REAL_PLAN_FROM_SPEC" "$@"
  fi
done
: > "$OMS_TEST_SCOPE_CALLED"
exit 0
EOF
  chmod +x "$planner"

  sed 's@- Scope: src/, tests/@- Scope: `src/`, `tests/`@' "$project/PROJECT.md" > "$project/scope-ticks"
  mv "$project/scope-ticks" "$project/PROJECT.md"
  git -C "$project" add PROJECT.md
  git -C "$project" -c user.email=test@example.com -c user.name='Test User' commit -qm 'test: backtick Scope'
  rc=0
  out="$(OMS_AUTOPILOT_PLAN_FROM_SPEC="$planner" OMS_TEST_SCOPE_CALLED="$marker" \
    OMS_TEST_REAL_PLAN_FROM_SPEC="$ROOT/scripts/plan-from-spec.sh" \
    "$ROOT/scripts/autopilot.sh" --repo "$project" propose 2>&1)" || rc=$?
  contains "$out" 'autopilot: allowed: src,tests (from PROJECT.md Scope)' ||
    fail "backtick Scope was not normalized: $out"
  [ -e "$marker" ] || fail "backtick Scope did not reach planner: $out"

  for kind in empty prose parentheses root; do
    case "$kind" in
      empty) scope="   "; expected='PROJECT.md Scope is empty; pass --allowed explicitly' ;;
      prose) scope='src and tests'; expected='PROJECT.md Scope is not a safe --allowed path list; pass --allowed explicitly' ;;
      parentheses) scope='src/ (tests/)'; expected='PROJECT.md Scope is not a safe --allowed path list; pass --allowed explicitly' ;;
      root) scope='.'; expected='PROJECT.md Scope cannot grant the whole repository; pass --allowed explicitly' ;;
    esac
    SCOPE_VALUE="$scope" python3 - "$project/PROJECT.md" <<'PY'
import os, pathlib, sys
path = pathlib.Path(sys.argv[1])
lines = path.read_text(encoding="utf-8").splitlines()
for index, line in enumerate(lines):
    if line.startswith("- Scope:"):
        lines[index] = "- Scope: " + os.environ["SCOPE_VALUE"]
        break
else:
    raise SystemExit("PROJECT.md fixture lost its Scope field")
path.write_text("\n".join(lines) + "\n", encoding="utf-8")
PY
    git -C "$project" add PROJECT.md
    git -C "$project" -c user.email=test@example.com -c user.name='Test User' \
      commit -qm "test: $kind autopilot Scope"
    rm -f "$marker"
    rc=0
    out="$(OMS_AUTOPILOT_PLAN_FROM_SPEC="$planner" OMS_TEST_SCOPE_CALLED="$marker" \
      OMS_TEST_REAL_PLAN_FROM_SPEC="$ROOT/scripts/plan-from-spec.sh" \
      "$ROOT/scripts/autopilot.sh" --repo "$project" propose 2>&1)" || rc=$?
    [ "$rc" = 2 ] || fail "$kind Scope should refuse before planner call ($rc): $out"
    contains "$out" "$expected" || fail "$kind Scope refusal did not explain --allowed: $out"
    [ ! -e "$marker" ] || fail "$kind Scope reached the planner before refusal"
  done
}

# smoke-weight: 5
test_state_read_is_nonmutating_and_projection_failures_stay_visible() {
  local project="$TMP/state-read-health"
  local before after state_json inbox_json

  state_inventory() {  # REPO
    python3 - "$1" <<'PY'
import hashlib, os, pathlib, sys

root = pathlib.Path(sys.argv[1])
for path in sorted(root.rglob("*")):
    rel = path.relative_to(root)
    if rel.parts and rel.parts[0] == ".git":
        continue
    if path.is_symlink():
        print("L", rel.as_posix(), os.readlink(path))
    elif path.is_dir():
        print("D", rel.as_posix())
    elif path.is_file():
        print("F", rel.as_posix(), hashlib.sha256(path.read_bytes()).hexdigest())
PY
  }

  make_committed_repo "$project"
  before="$(state_inventory "$project")"
  state_json="$("$ROOT/scripts/state.sh" --repo "$project" --json)" ||
    fail "state failed on a clean repo with no plan"
  after="$(state_inventory "$project")"
  [ "$after" = "$before" ] ||
    fail "read-only state changed clean-repo paths or bytes: before=[$before] after=[$after]"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["plan"]["present"] is False and row["plan"]["healthy"] is True, row["plan"]
assert row["task"]["present"] is False and row["task"]["healthy"] is True, row["task"]
' || fail "clean-repo projection health is wrong: $state_json"

  mkdir -p "$project/.oms/task/current.md"
  state_json="$("$ROOT/scripts/state.sh" --repo "$project" --json)" ||
    fail "state should return an explicit unhealthy task projection"
  printf '%s' "$state_json" | python3 -c '
import json, sys
task = json.load(sys.stdin)["task"]
assert task["present"] is True, task
assert task["healthy"] is False, task
assert task["error"] == "status-unavailable", task
' || fail "physical task status failure was disguised as normal absence: $state_json"
  rmdir "$project/.oms/task/current.md" "$project/.oms/task"

  mkdir -p "$project/.oms/plan"
  printf '{malformed plan\n' > "$project/.oms/plan/tasks.json"
  state_json="$(PYTHONOPTIMIZE=1 "$ROOT/scripts/state.sh" --repo "$project" --json)" ||
    fail "state should return an explicit unhealthy plan projection"
  printf '%s' "$state_json" | python3 -c '
import json, sys
plan = json.load(sys.stdin)["plan"]
assert plan["present"] is True, plan
assert plan["healthy"] is False, plan
assert plan["error"] == "status-unavailable", plan
' || fail "malformed physical plan was disguised as normal absence: $state_json"

  printf 'not-json evidence\n' > "$project/.oms/failures.jsonl"
  state_json="$(PYTHONOPTIMIZE=1 "$ROOT/scripts/state.sh" --repo "$project" --json)" ||
    fail "state should return explicit unhealthy failure-ledger health"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
failures = row["failures"]
assert failures["present"] is True, failures
assert failures["healthy"] is False, failures
# Quarantine refined the tag: the projection stays available, the corrupt
# row is counted, and health goes false — still never disguised as empty.
assert failures["error"] == "invalid-rows", failures
assert failures["invalid_rows"] == 1, failures
assert row["plan"]["present"] is True and row["plan"]["healthy"] is False, row["plan"]
' || fail "multiple malformed physical projections were disguised as healthy: $state_json"

  # A failed validator process must invalidate every family, including a
  # healthy projection, rather than accepting a partial verdict.
  local python_fail_bin real_python
  real_python="$(command -v python3)"
  python_fail_bin="$TMP/state-python-fail"
  mkdir -p "$python_fail_bin"
  cat > "$python_fail_bin/python3" <<'PYTHON'
#!/usr/bin/env bash
set -u
script=""
for arg in "$@"; do
  if [ "$arg" = - ]; then
    script="$(cat)"
    case "$script" in
      *failure_path,\ failure_base,*)
        case "${OMS_TEST_VALIDATOR_MODE:-fail}" in
          fail) exit 91 ;;
          short) printf '1\n'; exit 0 ;;
          shape) printf '{"schema":99,"failures":[],"invalid_rows":0}\n' > "$2" ;;
        esac
        ;;
    esac
    printf '%s' "$script" | "$OMS_TEST_REAL_PYTHON" "$@"
    exit $?
  fi
done
exec "$OMS_TEST_REAL_PYTHON" "$@"
PYTHON
  chmod +x "$python_fail_bin/python3"
  state_json="$(PATH="$python_fail_bin:$PATH" OMS_TEST_REAL_PYTHON="$real_python" \
    "$ROOT/scripts/state.sh" --repo "$project" --json)" ||
    fail "state should survive a projection validator process failure"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
for name in ("failures", "task", "plan"):
    assert row[name]["healthy"] is False, row[name]
' || fail "validator process failure did not default every projection unhealthy: $state_json"

  state_json="$(PATH="$python_fail_bin:$PATH" OMS_TEST_REAL_PYTHON="$real_python" \
    OMS_TEST_VALIDATOR_MODE=short "$ROOT/scripts/state.sh" --repo "$project" --json)" ||
    fail "state should survive a partial projection verdict"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert all(row[name]["healthy"] is False for name in ("failures", "task", "plan")), row
' || fail "a partial validator verdict reopened authority: $state_json"
  local validator_repo="$TMP/state-validator-control"
  make_committed_repo "$validator_repo"
  state_json="$(PATH="$python_fail_bin:$PATH" OMS_TEST_REAL_PYTHON="$real_python" \
    OMS_TEST_VALIDATOR_MODE=shape PYTHONOPTIMIZE=1 \
    "$ROOT/scripts/state.sh" --repo "$validator_repo" --json)" ||
    fail "state should reject a wrong-shaped JSON projection in optimized Python"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["failures"]["healthy"] is False, row["failures"]
assert row["task"]["healthy"] is True and row["plan"]["healthy"] is True, row
' || fail "optimized Python skipped projection validation: $state_json"

  inbox_json="$("$ROOT/scripts/inbox.sh" --repo "$project" --json)"
  printf '%s' "$inbox_json" | python3 -c '
import json, sys
items = json.load(sys.stdin)["items"]
assert any(item["code"] == "failure-ledger-corrupt" for item in items), items
' || fail "inbox hid malformed canonical failure state: $inbox_json"
}

test_agent_plan_apply_rejects_noncanonical_project_state() {
  local kind project spec_sha proposal proposal_sha base rc out

  for kind in duplicate typo; do
    project="$TMP/apply-project-state-$kind"
    make_committed_repo "$project"
    if [ "$kind" = duplicate ]; then
      printf '%s\n' '# PROJECT.md' '- State: confirmed' '- State: draft' > "$project/PROJECT.md"
    else
      printf '%s\n' '# PROJECT.md' '- State: confirmd' > "$project/PROJECT.md"
    fi
    spec_sha="$(python3 -c 'import hashlib,sys; print(hashlib.sha256(open(sys.argv[1], "rb").read()).hexdigest())' "$project/PROJECT.md")"
    base="$(git -C "$project" rev-parse HEAD)"
    proposal="$project/proposal.json"
    printf '{"schema":1,"kind":"agent-plan-proposal","spec_sha256":"%s","plan_sha256":"absent","base_sha":"%s","id_prefix":"","allowed_envelope":["."],"acceptance_files":[],"tasks":[{"id":"t1","title":"test state gate","allowed":["."],"verify":"true","depends":[]}]}' \
      "$spec_sha" "$base" > "$proposal"
    proposal_sha="$(python3 -c 'import hashlib,sys; print(hashlib.sha256(open(sys.argv[1], "rb").read()).hexdigest())' "$proposal")"
    rc=0
    out="$("$ROOT/scripts/agent-plan.sh" --repo "$project" apply-proposal \
      --proposal "$proposal" --expected-proposal-sha256 "$proposal_sha" \
      --expected-plan-sha256 absent --goal gate --accept true \
      --allowed-envelope . 2>&1)" || rc=$?
    [ "$rc" = 2 ] || fail "apply-proposal accepted $kind PROJECT State (rc=$rc): $out"
    contains "$out" 'PROJECT.md State' ||
      fail "apply-proposal $kind refusal did not name PROJECT.md State: $out"
    [ ! -e "$project/.oms/plan/tasks.json" ] ||
      fail "apply-proposal mutated topology for $kind PROJECT State"
  done
}

