            "lease_epoch": 0, "lease_id": "", "autopilot_owner_id": "",
            "review_lease_id": "", "repair_count": 0,
            "repair_artifact": "", "created": "2026-08-29T00:00:01Z",
            "updated": "2026-08-29T00:00:01Z",
        },
    },
}
with open(plan, "w", encoding="utf-8") as handle:
    json.dump(row, handle, sort_keys=True)
    handle.write("\n")
PY

  status="$("$plan" --repo "$project" status --json)" ||
    fail "contract-bound plan status failed"
  printf '%s' "$status" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["contract"]["bound"] is True, row
assert row["contract"]["satisfied"] is True, row
assert row["contract"]["blocker"] == "", row
assert row["actionable"] == ["t1", "t2"], row
' || fail "fresh PROJECT contract did not authorize ready work: $status"

  "$plan" --repo "$project" claim --id t1 --provider codex --ttl 60 >/dev/null ||
    fail "could not claim the first task before drift"
  lease="$("$plan" --repo "$project" show --id t1 | python3 -c \
    'import json,sys; print(json.load(sys.stdin).get("lease_id", ""))' | tr -d '\r')"
  [ -n "$lease" ] || fail "could not claim the first task before drift"
  printf '\n## Changed\ncontract drift\n' >> "$project_file"
  before="$(python3 -c 'import hashlib,sys; print(hashlib.sha256(open(sys.argv[1], "rb").read()).hexdigest())' "$plan_file")"

  status="$("$plan" --repo "$project" status --json)" ||
    fail "drifted contract status should remain readable"
  printf '%s' "$status" | python3 -c '
import json, re, sys
row = json.load(sys.stdin)
contract = row["contract"]
assert contract["bound"] is True and contract["satisfied"] is False, row
assert contract["project_state"] == "confirmed", contract
assert contract["blocker"] == "project-drift", contract
assert re.fullmatch(r"[0-9a-f]{64}", contract["expected_spec_sha256"]), contract
assert re.fullmatch(r"[0-9a-f]{64}", contract["current_spec_sha256"]), contract
assert row["actionable"] == [], row
' || fail "PROJECT drift did not remove canonical actionability: $status"
  [ -z "$("$plan" --repo "$project" ready)" ] ||
    fail "ready exposed a task after PROJECT contract drift"
  rc=0
  out="$("$plan" --repo "$project" next 2>&1)" || rc=$?
  [ "$rc" = 3 ] && contains "$out" 'PROJECT.md contract' ||
    fail "next did not report the contract blocker (rc=$rc): $out"
  rc=0
  out="$("$plan" --repo "$project" claim --id t2 --provider codex 2>&1)" || rc=$?
  [ "$rc" = 2 ] && contains "$out" 'PROJECT.md contract' ||
    fail "direct claim bypassed PROJECT drift (rc=$rc): $out"
  [ "$(python3 -c 'import hashlib,sys; print(hashlib.sha256(open(sys.argv[1], "rb").read()).hexdigest())' "$plan_file")" = "$before" ] ||
    fail "a refused drifted claim changed the plan"

  # Drift cannot strand authority that already exists. The exact lease may
  # advance and release, but it cannot create a sibling lease while drifted.
  "$plan" --repo "$project" start --id t1 --lease-id "$lease" >/dev/null ||
    fail "PROJECT drift blocked an already-claimed start transition"
  "$plan" --repo "$project" release --id t1 --lease-id "$lease" >/dev/null ||
    fail "PROJECT drift blocked exact lease cleanup"

  runtime_file="$project/runtime.json"
  state_file="$project/state.json"
  inbox_file="$project/inbox.json"
  "$ROOT/scripts/runtime.sh" --repo "$project" envelope show > "$runtime_file" ||
    fail "runtime could not project a drifted contract"
  "$ROOT/scripts/state.sh" --repo "$project" --json > "$state_file" ||
    fail "state could not project a drifted contract"
  "$ROOT/scripts/inbox.sh" --repo "$project" --json > "$inbox_file" ||
    fail "inbox could not project a drifted contract"
  python3 - "$runtime_file" "$state_file" "$inbox_file" <<'PY' ||
    fail "runtime/state/inbox disagreed on PROJECT drift"
import json, sys
runtime, state, inbox = [json.load(open(path, encoding="utf-8")) for path in sys.argv[1:]]
runtime_actions = [item["id"] for item in runtime["next_actions"]]
inbox_actions = [item["id"] for item in inbox["recommended_actions"]]
assert runtime["plan"]["contract"]["blocker"] == "project-drift", runtime["plan"]
assert state["plan"]["contract"]["blocker"] == "project-drift", state["plan"]
assert state["plan"]["actionable"] == [], state["plan"]
assert "execute_ready_task" not in runtime_actions, runtime_actions
assert "inspect_plan_contract" in runtime_actions, runtime_actions
assert "execute_ready_task" not in inbox_actions, inbox_actions
assert "inspect_plan_contract" in inbox_actions, inbox_actions
PY
  out="$("$ROOT/scripts/state.sh" --repo "$project")" ||
    fail "state text could not project a drifted contract"
  contains "$out" 'PROJECT contract: BLOCKED (project-drift' ||
    fail "state text hid the PROJECT contract blocker: $out"

  rm -f "$project_file"
  ln -s "$(basename "$original")" "$project_file"
  status="$("$plan" --repo "$project" status --json)" ||
    fail "status should project an unsafe PROJECT leaf without following it"
  printf '%s' "$status" | python3 -c '
import json, sys
row = json.load(sys.stdin)
contract = row["contract"]
assert contract["satisfied"] is False, contract
assert contract["project_healthy"] is False, contract
assert contract["blocker"] == "project-unreadable", contract
assert contract["current_spec_sha256"] == "", contract
assert row["actionable"] == [], row
' || fail "PROJECT symlink was followed as plan authority: $status"
  "$ROOT/scripts/runtime.sh" --repo "$project" envelope show > "$runtime_file" ||
    fail "runtime collapsed when PROJECT.md was an unsafe leaf"
  python3 - "$runtime_file" <<'PY' ||
    fail "runtime did not preserve the typed unsafe-PROJECT blocker"
import json, sys
row = json.load(open(sys.argv[1], encoding="utf-8"))
assert row["plan"]["contract"]["blocker"] == "project-unreadable", row["plan"]
assert "inspect_plan_contract" in [item["id"] for item in row["next_actions"]], row["next_actions"]
PY
  rm -f "$project_file"
  cp "$original" "$project_file"
  status="$("$plan" --repo "$project" status --json)"
  printf '%s' "$status" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["contract"]["satisfied"] is True, row
assert row["actionable"] == ["t1", "t2"], row
' || fail "restoring exact PROJECT bytes did not reactivate the plan: $status"

  # Manual legacy plans remain usable because they carry no reviewed digest.
  python3 - "$plan_file" <<'PY'
import json, sys
path = sys.argv[1]
row = json.load(open(path, encoding="utf-8"))
row.pop("project_contract", None)
with open(path, "w", encoding="utf-8") as handle:
    json.dump(row, handle, sort_keys=True)
    handle.write("\n")
PY
  printf '\nlegacy drift\n' >> "$project_file"
  status="$("$plan" --repo "$project" status --json)"
  printf '%s' "$status" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["contract"]["bound"] is False, row
assert row["contract"]["satisfied"] is True, row
assert row["actionable"] == ["t1", "t2"], row
' || fail "legacy unbound plan lost compatibility: $status"
}

test_state_unhealthy_projections_never_reopen_authority() {
  local project="$TMP/state-unhealthy-authority"
  local external_task="$TMP/external-task-authority.md"
  local external_plan="$TMP/external-plan-authority.json"
  local state_json state_text

  make_committed_repo "$project"
  mkdir -p "$project/.oms/task" "$project/.oms/plan"
  printf '%s\n' '## Goal' 'EXTERNAL_TASK_AUTHORITY_MARKER' '' \
    '## Next Step' 'EXTERNAL_TASK_NEXT_MARKER' > "$external_task"
  printf '%s\n' \
    '{"schema":3,"goal":"EXTERNAL_PLAN_AUTHORITY_MARKER","tasks":{}}' \
    > "$external_plan"
  ln -s "$external_task" "$project/.oms/task/current.md"
  ln -s "$external_plan" "$project/.oms/plan/tasks.json"

  state_json="$("$ROOT/scripts/state.sh" --repo "$project" --json)" ||
    fail "state should report unhealthy symlink projections"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["task"]["present"] is True and row["task"]["healthy"] is False, row["task"]
assert row["plan"]["present"] is True and row["plan"]["healthy"] is False, row["plan"]
assert "goal" not in row["task"] and "next" not in row["task"], row["task"]
assert "goal" not in row["plan"], row["plan"]
assert "EXTERNAL_" not in json.dumps(row), row
' || fail "unhealthy state reopened external symlink authority: $state_json"

  state_text="$("$ROOT/scripts/state.sh" --repo "$project")" ||
    fail "state text should report unhealthy symlink projections"
  if contains "$state_text" 'EXTERNAL_'; then
    fail "state text exposed external symlink authority: $state_text"
  fi
}

test_failure_ledger_structured_junk_quarantines_visibly() {
  local project="$TMP/failure-ledger-structured-junk"
  local bad out state_json inbox_json rc=0

  make_committed_repo "$project"
  mkdir -p "$project/.oms"
  for bad in \
    '{}' \
    '{"schema":"2","event":"fail","fingerprint":"fp"}' \
    '{"schema":2,"event":"other","fingerprint":"fp"}' \
    '{"schema":2,"event":"fail","fingerprint":"fp"}' \
    '{"schema":2,"event":"fail","fingerprint":"fp","ts":"2026-08-01T00:00:00Z","agent":"test","kind":"cmd","cmd":"false","exit":"1"}' \
    '{"schema":1,"event":"resolved","fingerprint":7}'; do
    printf '%s\n' "$bad" > "$project/.oms/failures.jsonl"
    rc=0
    out="$("$ROOT/scripts/fail-ledger.sh" --repo "$project" list --unresolved --json 2>&1)" || rc=$?
    # Quarantine, not brick: the read stays alive, the row is counted as
    # invalid in the payload, and the warning names it. Exit 2 here used to
    # kill the whole runtime envelope while the inbox's remediation was this
    # very command.
    [ "$rc" = 0 ] || fail "quarantining ledger list returned $rc for $bad: $out"
    contains "$out" 'invalid row' ||
      fail "structured junk was not identified as an invalid row for $bad: $out"
    printf '%s' "$out" | grep >/dev/null '"invalid_rows": *1' ||
      fail "structured junk was not counted in the payload for $bad: $out"
  done

  # A torn tail plus a real append: the guard opens a fresh line so the new
  # record survives on its own, and only the torn fragment is quarantined.
  printf '{"schema":2,"event":"fail","fingerprint":"torn","ts":"2026-08-0' \
    > "$project/.oms/failures.jsonl"
  (cd "$project" && "$ROOT/scripts/fail-ledger.sh" record --cmd "torn-tail-probe" --exit 1 \
    >/dev/null 2>&1) || fail "record after a torn tail failed"
  out="$("$ROOT/scripts/fail-ledger.sh" --repo "$project" list --unresolved --json 2>&1)" ||
    fail "list after a torn tail should stay alive: $out"
  printf '%s' "$out" | python3 -c '
import json, sys
raw = sys.stdin.read()
doc = json.loads(raw[raw.index("{"):])
assert doc["invalid_rows"] == 1, doc
assert len(doc["failures"]) == 1, doc
' || fail "the record appended after a torn tail was lost: $out"

  printf '{}\n' > "$project/.oms/failures.jsonl"

  state_json="$("$ROOT/scripts/state.sh" --repo "$project" --json)" ||
    fail "state should carry an unhealthy failure projection"
  printf '%s' "$state_json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["failures"]["present"] is True, row["failures"]
assert row["failures"]["healthy"] is False, row["failures"]
assert row["failures"]["invalid_rows"] == 1, row["failures"]
# The runtime envelope survives quarantined ledger junk; the corruption is
# surfaced through the failures projection and the inbox item instead.
assert row["runtime"]["healthy"] is True, row["runtime"]
' || fail "state did not quarantine structured junk visibly: $state_json"
  inbox_json="$("$ROOT/scripts/inbox.sh" --repo "$project" --json)"
  printf '%s' "$inbox_json" | python3 -c '
import json, sys
items = json.load(sys.stdin)["items"]
assert any(item["code"] == "failure-ledger-corrupt" for item in items), items
' || fail "inbox hid structured failure-ledger junk: $inbox_json"

  rc=0
  out="$("$ROOT/scripts/runtime.sh" --repo "$project" envelope show 2>&1)" ||
    fail "the runtime envelope must survive quarantined ledger junk (rc=$?): $out"
}

# smoke-weight: 45
test_doctor_repo_json_and_remediation_plan_are_structured() {
  local project="$TMP/doctor-structured-project"
  local other="$TMP/doctor-structured-other"
  local home_dir="$TMP/doctor-structured-home"
  local runtime="$home_dir/runtime"
  local json plan rc=0

  setup_doctor_home "$home_dir"
  make_committed_repo "$project"
  mkdir -p "$other" "$project/.oms/artifacts/call"
  printf 'orphan\n' > "$project/.oms/artifacts/call/orphan.md"
  touch -t 202601010000 "$project/.oms/artifacts/call/orphan.md"

  json="$(cd "$other" && HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" \
    XDG_RUNTIME_DIR="$runtime" OH_MY_SETTING_REQUIRE_TOOLS=0 \
    "$ROOT/scripts/doctor.sh" --repo "$project" --json --no-model-doctor)" || rc=$?
  [ "$rc" = 0 ] || fail "structured doctor failed: $json"
  printf '%s' "$json" | python3 -c '
import json, os, sys
row = json.load(sys.stdin)
assert row["schema"] == 1, row
assert row["repo"] == os.path.realpath(sys.argv[1]), row
assert row["status"] == "ok" and row["exit"] == 0, row
assert isinstance(row["findings"], list) and row["findings"], row
assert any(item["level"] == "warn" and "unindexed artifact" in item["message"] for item in row["findings"]), row
assert any(item["authority"] == "local_mutation" and "artifact-index.sh prune --files" in item["command"] for item in row["remediations"]), row
assert "raw_output" not in row, row
' "$project" || fail "doctor JSON contract is wrong: $json"

  plan="$(cd "$other" && HOME="$home_dir" XDG_CACHE_HOME="$home_dir/.cache" \
    XDG_RUNTIME_DIR="$runtime" OH_MY_SETTING_REQUIRE_TOOLS=0 \
    "$ROOT/scripts/doctor.sh" --repo "$project" --remediation-plan \
      --no-model-doctor)" || fail "doctor remediation plan failed"
  contains "$plan" 'local_mutation' ||
    fail "doctor plan omitted authority: $plan"
  contains "$plan" 'artifact-index.sh prune --files' ||
    fail "doctor plan omitted the exact remedy: $plan"

  if "$ROOT/scripts/doctor.sh" --repo "$project" --json --repair \
      >/dev/null 2>&1; then
    fail "structured doctor accepted a mutating repair"
  fi

  # From a checkout that is not the receipt owner the structured report must
  # judge the owner's tree, as plain doctor.sh does.
  local owner="$TMP/doctor-structured-owner"
  local owner_home="$TMP/doctor-structured-owner-home"
  local receipt="$owner_home/receipt.json"
  setup_doctor_home "$owner_home"
  mkdir -p "$owner/scripts"
  printf '#!/usr/bin/env bash\necho "ok: owner-marker"\nexit 0\n' > "$owner/scripts/doctor.sh"
  chmod +x "$owner/scripts/doctor.sh"
  python3 - "$receipt" "$owner" <<'PY'
import json, os, sys
json.dump({"schema": 1, "source_root": os.path.realpath(sys.argv[2]), "commit": "a" * 40,
           "channel": "main", "version": "0.0.0", "installed_at": "2026-01-01T00:00:00Z",
           "plugin": {"name": "oh-my-setting", "version": "0.0.0", "sha256": "b" * 64}},
          open(sys.argv[1], "w", encoding="utf-8"))
PY
  rc=0
  json="$(cd "$other" && HOME="$owner_home" XDG_CACHE_HOME="$owner_home/.cache" \
    XDG_RUNTIME_DIR="$owner_home/runtime" OH_MY_SETTING_REQUIRE_TOOLS=0 \
    OMS_INSTALL_RECEIPT="$receipt" \
    "$ROOT/scripts/doctor.sh" --repo "$project" --json --no-model-doctor)" || rc=$?
  [ "$rc" = 0 ] || fail "structured doctor did not delegate to the receipt owner: $json"
  printf '%s' "$json" | python3 -c '
import json, sys
row = json.load(sys.stdin)
assert row["status"] == "ok" and row["exit"] == 0, row
assert any("owner-marker" in item["message"] for item in row["findings"]), row
' || fail "structured doctor omitted the owner verdict: $json"
  plan="$(cd "$other" && HOME="$owner_home" XDG_CACHE_HOME="$owner_home/.cache" \
    XDG_RUNTIME_DIR="$owner_home/runtime" OH_MY_SETTING_REQUIRE_TOOLS=0 \
    OMS_INSTALL_RECEIPT="$receipt" \
    "$ROOT/scripts/doctor.sh" --repo "$project" --remediation-plan --no-model-doctor)" ||
    fail "owner-delegated remediation plan failed: $plan"
  contains "$plan" 'owner-marker' && fail "owner plan listed an ok finding: $plan"
  return 0
}

# Every hook the Codex plugin registers must reach a script the dispatcher
# admits: a hooks.json row naming a tool outside harness-hook.sh's allowlist
# fails silently at dispatch time, which is how a hook can ship registered
# and never run. The syntax guard must reach its script.
test_codex_plugin_hooks_dispatch_only_allowlisted_scripts() {
  local hooks="$ROOT/plugins/oh-my-setting/hooks.json"
  local manifest="$ROOT/plugins/oh-my-setting/.codex-plugin/plugin.json"
  local dispatcher="$ROOT/plugins/oh-my-setting/scripts/harness-hook.sh"
  local allow tool

  python3 - "$manifest" <<'PY' || fail "the Codex plugin manifest contract failed"
import json, sys
doc = json.load(open(sys.argv[1], encoding="utf-8"))
assert "defaultPrompt" not in doc.get("interface", {}), doc.get("interface", {})
assert doc.get("hooks") == "./hooks.json", doc.get("hooks")
PY
  allow="$(sed -n 's/^case "\$tool" in \(.*\)) ;; \*) exit 0 ;; esac$/\1/p' "$dispatcher")"
  [ -n "$allow" ] || fail "could not read the dispatcher allowlist from $dispatcher"
  for tool in $(python3 - "$hooks" <<'PY'
import json, re, sys
doc = json.load(open(sys.argv[1], encoding="utf-8"))
tools = set()
for entries in doc["hooks"].values():
    for entry in entries:
        for hook in entry.get("hooks", []):
            match = re.search(r'harness-hook\.sh" (\S+)', hook.get("command", ""))
            if match:
                tools.add(match.group(1))
print(" ".join(sorted(tools)))
PY
  ); do
    case "|$allow|" in *"|$tool|"*) ;; *) fail "hooks.json dispatches $tool but the dispatcher does not admit it" ;; esac
    [ -f "$ROOT/scripts/$tool.sh" ] || fail "hooks.json dispatches $tool but scripts/$tool.sh does not exist"
  done
  python3 - "$hooks" <<'PY' || fail "the Codex plugin must run the syntax guard after apply_patch"
import json, sys
doc = json.load(open(sys.argv[1], encoding="utf-8"))
rows = [entry for entry in doc["hooks"].get("PostToolUse", [])
        if any("syntax-guard-hook" in hook.get("command", "") for hook in entry.get("hooks", []))]
assert len(rows) == 1, rows
assert "apply_patch" in rows[0].get("matcher", ""), rows[0]
PY
  python3 - "$hooks" "$dispatcher" "$ROOT" <<'PY' || fail "the Codex dispatcher contract failed"
import json, os, runpy, subprocess, sys
from pathlib import Path
doc = json.load(open(sys.argv[1], encoding="utf-8"))
bridge = runpy.run_path(str(Path(sys.argv[3]) / "scripts/lib/codex-hook-bridge.py"))
registered = bridge["expected_hook_keys"](Path(sys.argv[1]).parent, "fixture")
assert registered["fixture:hooks.json:post_tool_use:0:0"] == "syntax-guard-hook", registered
assert "fixture:hooks.json:post_tool_use:1:0" not in registered, registered
env = dict(os.environ)
for name in ("OMS_PANEL_MAIN_ATTEMPT", "OMS_PANEL_SESSION", "OMS_HARNESS_CHILD"):
    env.pop(name, None)
timeout = float(os.environ.get("OMS_TEST_CALL_TIMEOUT", "30"))
probes = (
    ('''cat() { printf partial; printf 'fixture read failure\\n' >&2; return 73; }
export -f cat
exec bash "$1" "$2"
''', 73),
    ('''cd() { printf 'fixture setup failure\\n' >&2; return 74; }
export -f cd
exec bash "$1" "$2"
''', 74),
    ('''unset HOME
exec bash "$1" "$2"
''', 1),
)
for probe, status in probes:
    result = subprocess.run(["bash", "-c", probe, "dispatcher-probe", sys.argv[2], "turn-guard"],
                            input="{}", capture_output=True, text=True, env=env, timeout=timeout)
    assert not result.stdout and result.returncode == status and result.stderr, result
PY
}

