          "nonce": "d" * 64,
          "task_id": task, "bundle_sha256": bundle_sha, "room_id": "room", "participant": "main",
          "lease_id": "lease", "state": "review", "plan_sha256": "b" * 64,
          "task_sha256": "c" * 64, "snapshot_sha256": "e" * 64,
